_PREMIUM_EMOJI_PATTERN = re.compile(
    "|".join(re.escape(_e) for _e in sorted(PREMIUM_EMOJI_IDS, key=len, reverse=True))
) if PREMIUM_EMOJI_IDS else None

# Spans that must never be touched by the injector: already-wrapped
# <tg-emoji> tags, and the literal contents of <pre>/<code> blocks.
_PREMIUM_EMOJI_PROTECTED_RE = re.compile(
    r"(<tg-emoji[^>]*>.*?</tg-emoji>|<pre>.*?</pre>|<code>.*?</code>|<tg-button[^>]*>.*?</tg-button>|<tg-button-row[^>]*>.*?</tg-button-row>)",
    re.DOTALL
)


def inject_premium_emojis(text):
    """Wrap configured plain emoji characters in <tg-emoji emoji-id=...> tags
    so they render as Telegram Premium (animated) emoji for every user —
    Premium or not. No-op on falsy input, on text with no configured emoji,
    or on the protected <tg-emoji>/<pre>/<code> spans described above."""
    if not text or not _PREMIUM_EMOJI_PATTERN:
        return text

    def _wrap(m):
        e = m.group(0)
        return f'<tg-emoji emoji-id="{PREMIUM_EMOJI_IDS[e]}">{e}</tg-emoji>'

    parts = _PREMIUM_EMOJI_PROTECTED_RE.split(text)
    for i, part in enumerate(parts):
        # Odd indices from re.split() with a capturing group are the
        # protected spans themselves — leave them exactly as-is.
        if i % 2 == 1:
            continue
        parts[i] = _PREMIUM_EMOJI_PATTERN.sub(_wrap, part)
    return "".join(parts)


def _premium_emojify_kwarg(kwargs, args, pos_index, key):
    """Apply inject_premium_emojis() to kwargs[key] (preferred) or the
    positional slot at pos_index, but ONLY when this call is using
    parse_mode=ParseMode.HTML — never touches plain-text sends."""
    if kwargs.get("parse_mode") != ParseMode.HTML:
        return args, kwargs
    if key in kwargs and kwargs[key]:
        kwargs[key] = inject_premium_emojis(kwargs[key])
    elif pos_index is not None and len(args) > pos_index and args[pos_index]:
        args = list(args)
        args[pos_index] = inject_premium_emojis(args[pos_index])
        args = tuple(args)
    return args, kwargs


_orig_send_message = _telegram_module.Bot.send_message
_orig_edit_message_text = _telegram_module.Bot.edit_message_text
_orig_edit_message_caption = _telegram_module.Bot.edit_message_caption
_orig_send_document = _telegram_module.Bot.send_document
_orig_send_video = _telegram_module.Bot.send_video
# Chain on top of the already-patched (file_id-caching) send_photo/send_animation
_orig_send_photo_chain = _telegram_module.Bot.send_photo
_orig_send_animation_chain = _telegram_module.Bot.send_animation


async def _premium_send_message(self, *args, **kwargs):
    args, kwargs = _premium_emojify_kwarg(kwargs, args, 1, "text")
    return await _orig_send_message(self, *args, **kwargs)


async def _premium_edit_message_text(self, *args, **kwargs):
    args, kwargs = _premium_emojify_kwarg(kwargs, args, 0, "text")
    try:
        return await _orig_edit_message_text(self, *args, **kwargs)
    except _telegram_module.error.BadRequest as e:
        # 🩹 GLOBAL FIX: "Message is not modified" isn't a real failure — it just
        # means the new text+markup are byte-identical to what's already shown
        # (e.g. re-tapping a pagination/filter button that lands on the same
        # page). Every callback used to need its own try/except for this; a
        # handful had it, most didn't, so it kept surfacing as an unhandled
        # exception. Swallowing it once here covers every call site.
        if "message is not modified" in str(e).lower():
            return None
        raise


async def _premium_edit_message_caption(self, *args, **kwargs):
    args, kwargs = _premium_emojify_kwarg(kwargs, args, None, "caption")
    try:
        return await _orig_edit_message_caption(self, *args, **kwargs)
    except _telegram_module.error.BadRequest as e:
        if "message is not modified" in str(e).lower():
            return None
        raise


