class _TourSharedDict(dict):
    """A dict where every read/write for a group_id transparently redirects
    to that group's tournament "home" id (via TOUR_GROUP_ALIAS) if it's
    linked to another group's tournament — otherwise behaves like a normal
    defaultdict. This makes EVERY existing `tournament_teams[group_id]`,
    `.get(group_id, ...)`, `.setdefault(...)`, `.pop(...)` call site across
    the whole file automatically multi-group-aware with zero changes there:
    once two groups are linked, they simply end up reading/writing the same
    underlying entry."""
    def __init__(self, default_factory):
        super().__init__()
        self.default_factory = default_factory

    @staticmethod
    def _resolve(key):
        return TOUR_GROUP_ALIAS.get(key, key)

    def __getitem__(self, key):
        rkey = self._resolve(key)
        if not super().__contains__(rkey):
            super().__setitem__(rkey, self.default_factory())
        return super().__getitem__(rkey)

    def __setitem__(self, key, value):
        super().__setitem__(self._resolve(key), value)

    def __contains__(self, key):
        return super().__contains__(self._resolve(key))

    def get(self, key, default=None):
        return super().get(self._resolve(key), default)

    def setdefault(self, key, default=None):
        return super().setdefault(self._resolve(key), default)

    def pop(self, key, *args):
        return super().pop(self._resolve(key), *args)

    def __delitem__(self, key):
        super().__delitem__(self._resolve(key))


def is_tour_organiser(user_id: int, group_id: int) -> bool:
    """🏏 Owner / SECOND_APPROVER / anyone with the 'groups' power / anyone granted tour-organiser for this group."""
    if user_id == OWNER_ID or user_id == SECOND_APPROVER_ID:
        return True
    if has_power(user_id, "groups"):
        return True
    return (user_id, group_id) in TOURNAMENT_ORGANISERS

