# ═══════════════════════════════════════════════════════════════
# 🎨 CUSTOM EMOJI + BUTTON COLORS  (Bot API 9.4, Feb 2026)
# ═══════════════════════════════════════════════════════════════
# Telegram now lets bots:
#   1. Use real custom (Premium) emoji INSIDE message text via the
#      HTML tag  fallback
#   2. Give InlineKeyboardButton / KeyboardButton a `style` of
#      "primary" (blue) / "success" (green) / "danger" (red), and an
#      `icon_custom_emoji_id` to show a custom emoji on the button.
#
# IMPORTANT: both (1) and the icon on (2) only render if the Telegram
# account behind THIS BOT'S TOKEN has an active Telegram Premium
# subscription. Without Premium, Telegram just ignores them and shows
# the plain fallback emoji/text — nothing breaks either way. `style`
# (the button color) works for every bot, Premium or not.
#
# HOW TO GET A REAL CUSTOM EMOJI ID (one-time setup):
#   1. In any chat, find/send the Premium emoji you want to use.
#   2. Forward that single message to @userinfobot (or @RawDataBot).
#   3. It'll dump the message's raw JSON — look for an entity of type
#      "custom_emoji" and copy its "custom_emoji_id" value.
#   4. Paste it into CUSTOM_EMOJI_IDS below.
# Leave a key's value empty/missing and ce()/styled_button() simply
# fall back to the plain emoji — totally safe to ship as-is.
CUSTOM_EMOJI_IDS: Dict[str, str] = {
    # "wicket":   "5XXXXXXXXXXXXXXXXXXX",
    # "duck":     "5XXXXXXXXXXXXXXXXXXX",
    # "four":     "5XXXXXXXXXXXXXXXXXXX",
    # "six":      "5XXXXXXXXXXXXXXXXXXX",
    # "fifty":    "5XXXXXXXXXXXXXXXXXXX",
    # "hundred":  "5XXXXXXXXXXXXXXXXXXX",
    # "trophy":   "5XXXXXXXXXXXXXXXXXXX",
    # "fire":     "5XXXXXXXXXXXXXXXXXXX",
    # "captain":  "5XXXXXXXXXXXXXXXXXXX",
}

def ce(key: str, fallback: str) -> str:
    """Wrap `fallback` emoji in a <tg-emoji> tag if a real custom emoji ID
    is configured for `key`; otherwise just return `fallback` unchanged.
    Only has visible effect inside text sent with parse_mode=ParseMode.HTML."""
    eid = CUSTOM_EMOJI_IDS.get(key)
    if eid:
        return f'<tg-emoji emoji-id="{eid}">{fallback}</tg-emoji>'
    return fallback


_SMALL_CAPS_MAP = {
    'a': 'ᴀ', 'b': 'ʙ', 'c': 'ᴄ', 'd': 'ᴅ', 'e': 'ᴇ', 'f': 'ꜰ', 'g': 'ɢ',
    'h': 'ʜ', 'i': 'ɪ', 'j': 'ᴊ', 'k': 'ᴋ', 'l': 'ʟ', 'm': 'ᴍ', 'n': 'ɴ',
    'o': 'ᴏ', 'p': 'ᴘ', 'q': 'ǫ', 'r': 'ʀ', 's': 'ꜱ', 't': 'ᴛ', 'u': 'ᴜ',
    'v': 'ᴠ', 'w': 'ᴡ', 'x': 'x', 'y': 'ʏ', 'z': 'ᴢ',
}

def to_small_caps(text: str) -> str:
    """Convert a normal string to ᴛɪɴʏ ᴄᴀᴘꜱ unicode. Digits, emojis, symbols
    stay unchanged (no mapping = passthrough)."""
    if not text:
        return text
    return "".join(_SMALL_CAPS_MAP.get(ch.lower(), ch) for ch in text)


# ───────────────────
# 🩹 BUGFIX: raw "❌" showing up as
# literal text instead of an emoji.
#
# Cause: Telegram's answerCallbackQuery API (used by query.answer(text,
# show_alert=True) — the little popup that appears when you tap an inline
# button) has NO parse_mode support at all. Every query.answer() text is
# always sent as plain text, entities included. So any <tg-emoji> tag
# placed inside a query.answer() call can never render as an emoji — it
# always shows up as the raw tag. This is different from normal chat
# messages (reply_text/send_message with parse_mode=ParseMode.HTML), where
# tg-emoji tags render fine.
#
# Fix: strip the <tg-emoji ...> wrapper down to just its fallback emoji
# character (the text between the tags) before it ever reaches
# query.answer(). Safe to call on any string — plain text passes through
# unchanged.
# ───────────────────
_TG_EMOJI_TAG_RE = re.compile(r"<tg-emoji[^>]*>(.*?)</tg-emoji>")


def plain_alert(text: str) -> str:
    """Strip tg-emoji (and any other HTML) tags for use in query.answer()
    popups, which can't render formatting — leaves the fallback emoji char."""
    if not text:
        return text
    return _TG_EMOJI_TAG_RE.sub(r"\1", text)


# ───────────────────
# 🎨 Auto unicode-emoji for inline buttons.
#
# Every inline button in the bot is built through styled_button()/btn(), so
# adding the lookup here (instead of touching ~460 call sites individually)
# covers the whole bot in one place. If the button's label already starts
# with an emoji (many call sites already pass one manually), we leave it
# alone — this only fills in the ones that don't have one, picking the
# emoji from the most specific keyword match against the label text or
# callback_data.
# ───────────────────
_BUTTON_LEADING_EMOJI_RE = re.compile(
    "^[\U0001F1E6-\U0001FAFF\u2190-\u21FF\u2300-\u27BF\u2B00-\u2BFF\uFE0F]"
)

_BUTTON_EMOJI_RULES: list = [
    # (keywords, emoji) — checked in order, first match wins, most specific first
    (["close"], "✖️"),
    (["cancel"], "🚫"),
    (["leave"], "🚪"),
    (["delete", "rmjersey", "remove"], "🗑️"),
    (["stop"], "🛑"),
    (["exit"], "🚪"),
    (["reject", "decline", "unsold"], "❌"),
    (["back to menu", "back"], "⬅️"),
    (["prev"], "◀️"),
    (["next"], "▶️"),
    (["refresh"], "🔄"),
    (["ban"], "🔨"),
    (["unban", "forgive"], "✅"),
    (["approve", "confirm", "done", "accept", "yes", "sold"], "✅"),
    (["heads", "tails", "toss"], "🪙"),
    (["bat"], "🏏"),
    (["bowl"], "🎯"),
    (["start", "join"], "🚀"),
    (["buy", "base_", "auction"], "💰"),
    (["win", "ready"], "🏆"),
    (["swap"], "🔀"),
    (["take", "keep"], "🤝"),
    (["team"], "👥"),
    (["solo"], "🧍"),
    (["tour"], "🏆"),
    (["fantasy"], "🌟"),
    (["stats", "mystats", "leaderboard", "soloendlb"], "📊"),
    (["admin"], "🛠️"),
    (["help"], "📚"),
    (["support"], "🆘"),
    (["settings", "set_"], "⚙️"),
    (["overs"], "⏱️"),
    (["registration", "closereg"], "📝"),
    (["captain"], "🧢"),
    (["edit"], "✏️"),
    (["view"], "👁️"),
    (["donate", "add to group"], "➕"),
]


def _auto_button_emoji(text: str, callback_data: Optional[str], url: Optional[str]) -> str:
    """Prepend an appropriate unicode emoji to a button label if it doesn't
    already start with one."""
    if not text or _BUTTON_LEADING_EMOJI_RE.match(text.strip()):
        return text
    haystack = f"{text} {callback_data or ''} {url or ''}".lower()
    for keywords, emoji in _BUTTON_EMOJI_RULES:
        if any(k in haystack for k in keywords):
            return f"{emoji} {text}"
    return f"🔘 {text}"


def styled_button(text: str, callback_data: Optional[str] = None, url: Optional[str] = None,
                   style: Optional[str] = None, emoji_key: Optional[str] = None,
                   small_caps: bool = False) -> "InlineKeyboardButton":
    """Build an InlineKeyboardButton with Telegram Premium colors ('primary'/'success'/'danger')
    and custom emoji icons across all bot features (Toss, Batting, Bowling, Stats, etc.).
    Button label is auto-converted to small-caps unicode by default; pass
    small_caps=False to keep text as-is."""
    text = _auto_button_emoji(text, callback_data, url)
    if small_caps and text:
        text = to_small_caps(text)
    if not style:
        t_low = (text or "").lower()
        cb_low = (callback_data or "").lower()
        if any(w in t_low or w in cb_low for w in ["close", "cancel", "leave", "back", "delete", "stop", "exit", "reject", "no", "remove", "rmjersey"]):
            style = "danger"
        elif any(w in t_low or w in cb_low for w in ["bat", "bowl", "heads", "tails", "start", "done", "join", "confirm", "yes", "accept", "buy", "win", "ready", "swap", "take", "keep"]):
            style = "success"
        else:
            style = "primary"

    kwargs = {}
    if callback_data is not None:
        kwargs["callback_data"] = callback_data
    if url is not None:
        kwargs["url"] = url
    if style:
        kwargs["style"] = style
    # 🔧 Premium custom emoji icons removed from buttons per user request —
    # buttons now render with plain style only, no icon_custom_emoji_id.
    try:
        return InlineKeyboardButton(text, **kwargs)
    except TypeError:
        kwargs.pop("style", None)
        kwargs.pop("icon_custom_emoji_id", None)
        return InlineKeyboardButton(text, **kwargs)

def btn(text: str, callback_data: Optional[str] = None, url: Optional[str] = None,
        style: Optional[str] = None, emoji_key: Optional[str] = None,
        small_caps: bool = False) -> "InlineKeyboardButton":
    return styled_button(text, callback_data=callback_data, url=url, style=style,
                          emoji_key=emoji_key, small_caps=small_caps)


# 🛝 "Playground" redirect button — shown under the full scorecard, under the
# Player of the Match card, and under the mini scorecard.
VERSE_ZONE_URL = "https://t.me/verse_zone"


def verse_zone_markup() -> "InlineKeyboardMarkup":
    return InlineKeyboardMarkup([[styled_button("🛝 Playground", url=VERSE_ZONE_URL, small_caps=False)]])



