# ═══════════════════════════════════════════════════════════════
# 🎨 THEMED MESSAGE FORMATTER (╭━━┃╰ style)
# ═══════════════════════════════════════════════════════════════
_TAG_RE = re.compile(r"<[^>]+>")


def _visible_len(text: str) -> int:
    """Approximate on-screen length of a string, ignoring HTML tags
    (tg-emoji/b/i/code/etc.) so box-width math isn't thrown off by markup."""
    return len(_TAG_RE.sub("", text or ""))


STANDARD_BAR_LEN = 20  # standard separator width used by themed messages


def _dynamic_bar(*pieces, min_len: int = 12, max_len: int = 40) -> str:
    """STANDARD box border: always the same fixed length, regardless of how
    short or long the content is (previously scaled with content length)."""
    return "┈" * STANDARD_BAR_LEN


def themed(title: str, lines: list, emoji: str = "🏏", divider: bool = True) -> str:
    """
    Build a themed bordered message wrapped in a native Telegram quote box
    (<blockquote>), used for turn notifications (batting/bowling), run-scored
    updates, and similar alerts — in both GC and DM, solo and team mode.
    title  – header text shown above the box
    lines  – list of strings; each becomes a ├ line inside the box
    emoji  – decorative emoji appended to the header
    Returns a fully-formatted HTML-safe string.

    Border is a STANDARD fixed length (STANDARD_BAR_LEN) for every box,
    no matter whether the content is short or long.
    """
    # If the title already starts with its own emoji/symbol, don't prefix a second one.
    if title and ord(title.strip()[0]) > 0x2000:
        header = f"<b>{title.strip()}</b>"
    elif title:
        header = f"{emoji} <b>{title}</b>" if emoji else f"<b>{title}</b>"
    else:
        header = ""
    _bar = _RC_DIV
    _lines = list(lines)
    _plain_title = re.sub(r"<[^>]+>", "", title or "").upper()
    if (len(_lines) > 1 and re.match(r"^📊 (<b>)?Scores?\b", str(_lines[-1]))
            and not any(k in _plain_title for k in ("BATTING", "BOWLING"))):
        body = "\n".join(_lines[:-1]) + "\n" + _bar + "\n" + str(_lines[-1])
    else:
        body = "\n".join(f"{l}" for l in _lines)
    if header and body:
        sep = ("\n" + _RC_DIV + "\n") if divider else "\n"
        return header + sep + body
    return header or body


# ── 📊 RICH TABLE HELPER (Telegram Bot API 10.1+ sendRichMessage) ───────────────────
# Real tables via Bot API's new Rich Messages system, instead of monospace
# <pre> hacks. If the call fails for any reason (older client, transient
# error, etc.) we transparently fall back to a normal HTML message so the
# bot never breaks.
def _rt_text(val) -> dict:
    """Wrap a plain string as a RichText 'plain' node."""
    return {"type": "plain", "text": "" if val is None else str(val)}


def _rt_cell(val, header: bool = False) -> dict:
    cell = {"text": [_rt_text(val)]}
    if header:
        cell["is_header"] = True
    return cell


async def send_rich_table_message(
    chat_id: int,
    headers: list,
    rows: list,
    title: Optional[str] = None,
    intro_lines: Optional[list] = None,
    footer: Optional[str] = None,
    reply_to_message_id: Optional[int] = None,
    fallback_html: Optional[str] = None,
    expandable: bool = False,
) -> Optional[int]:
    """Send a real Telegram table via sendRichMessage (Bot API 10.1+).

    headers      – list[str] column headers
    rows         – list[list[str]] row values (plain text, no HTML needed)
    title        – optional heading shown above the table
    intro_lines  – optional list of paragraph lines shown above the table
    footer       – optional footer line shown below the table
    fallback_html– if given, used to send a normal HTML message when the
                   rich message call fails (e.g. library/server too old)
    expandable   – if True, wraps the <pre> table in a collapsible
                   <blockquote expandable> so long lists start collapsed.
    Returns the sent message_id, or None if it fell back / failed.
    """
    # 🔧 GLITCH FIX: `sendRichMessage` is NOT a real Telegram Bot API method —
    # every call here always failed (404 from Telegram), and the fallback
    # below used to reference `application.bot`, a variable that only exists
    # locally inside main() → NameError → swallowed by except → the command
    # silently sent NOTHING to the owner. Fixed by (1) building a clean HTML
    # table directly instead of a fake API call, and (2) using the module-
    # level `_global_bot` handle so the send can never NameError.
    bot = _global_bot
    if bot is None:
        logger.error("send_rich_table_message: _global_bot not set yet — bot not fully started.")
        return None

    def _esc(v) -> str:
        return html.escape(str(v))

    lines = []
    if title:
        lines.append(f"<b>{_esc(title)}</b>")
        lines.append("┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈")
    if intro_lines:
        for line in intro_lines:
            lines.append(_esc(line))
        lines.append("")

    if headers and rows:
        # Column widths based on header + all row values (monospace table via <pre>/<code>)
        col_widths = [len(str(h)) for h in headers]
        str_rows = [[str(v) for v in row] for row in rows]
        for row in str_rows:
            for i, v in enumerate(row):
                if i < len(col_widths):
                    col_widths[i] = max(col_widths[i], len(v))

        def _fmt_row(vals):
            return "  ".join(str(v).ljust(col_widths[i]) if i < len(col_widths) - 1 else str(v)
                              for i, v in enumerate(vals))

        table_lines = [_fmt_row(headers)]
        table_lines.append("  ".join("─" * w for w in col_widths))
        for row in str_rows:
            table_lines.append(_fmt_row(row))
        table_html = f"<pre>{_esc(chr(10).join(table_lines))}</pre>"
        if expandable:
            table_html = f"<blockquote expandable>{table_html}</blockquote>"
        lines.append(table_html)

    if footer:
        lines.append("┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈")
        lines.append(_esc(footer))

    text = fallback_html if fallback_html else "\n".join(lines)
    if not fallback_html:
        text = "\n".join(lines)

    try:
        sent = await bot.send_message(
            chat_id, text, parse_mode=ParseMode.HTML,
            reply_to_message_id=reply_to_message_id,
            disable_web_page_preview=True
        )
        return sent.message_id
    except Exception as e:
        logger.error(f"send_rich_table_message: HTML send failed ({chat_id}): {e}")
        # Last-resort plain-text retry (strip HTML tags) so the command never sends nothing
        try:
            plain_text = re.sub(r"<[^>]+>", "", text)
            sent = await bot.send_message(chat_id, plain_text, reply_to_message_id=reply_to_message_id)
            return sent.message_id
        except Exception as e2:
            logger.error(f"send_rich_table_message: plain-text retry also failed ({chat_id}): {e2}")
        return None


# --- GLOBAL HELPER FUNCTION (FIXED) ---
def get_user_tag(user):
    """Returns a clickable HTML link for the user"""
    if not user:
        return "Unknown"
    
    # ✅ FIX: Handle both User objects AND Player objects
    try:
        # Case 1: Telegram User object (has .id)
        if hasattr(user, 'id'):
            user_id = user.id
            first_name = user.first_name
        # Case 2: Player object (has .user_id)
        elif hasattr(user, 'user_id'):
            user_id = user.user_id
            first_name = user.first_name
        else:
            return "Unknown"
        
        # Clean the name to prevent HTML errors
        clean_name = html.escape(first_name)
        tag = f'<a href="tg://user?id={user_id}">{clean_name}</a>' + _title_suffix(user_id)
        return tag
    except Exception as e:
        logger.error(f"Error creating user tag: {e}")
        return "Unknown"

