def fmt_coins(amount) -> str:
    """Format a coin amount for display, e.g. 1234 -> '1,234 ✧'."""
    try:
        amount = int(amount)
    except Exception:
        amount = 0
    return f"{amount:,} {CRICOIN_SYMBOL}"

