WIN_TAX_PCT = 18      # /bet winning payout tax (charged at settlement)
TRANSFER_TAX_PCT = 6.5  # /transfer tax

def _title_emoji_tag(key: str) -> str:
    """Return the <tg-emoji> tag for a title key, or '' if unknown.
    Each tier gets the fallback emoji shown in the shop for that tier —
    wrapped in the tier's own real Telegram Premium emoji_id, so the
    Premium emoji actually renders (previously this always returned a
    single hardcoded 🏅 with no emoji-id wrapper at all)."""
    t = get_fantasy_title_info(key)
    if not t:
        return ""
    eid = t.get("emoji_id")
    fallback = FANTASY_TITLE_FALLBACK_EMOJI.get(key, "🏅")
    if eid:
        return f'<tg-emoji emoji-id="{eid}">{fallback}</tg-emoji>'
    return fallback

def _equipped_title_emoji(user_id: int) -> str:
    """Return the equipped fantasy title's premium emoji tag for a user_id, or '' if none equipped."""
    try:
        equipped_key = fantasy_data.get(user_id, {}).get("title")
        if equipped_key:
            return _title_emoji_tag(equipped_key)
    except Exception:
        pass
    return ""


def _title_suffix(user_id) -> str:
    """" + emoji" ready to tack onto the end of any name-mention string —
    used everywhere a player's name is displayed (scorecards, /players,
    lineups, auctions, transfers, match winners, etc.) so their equipped
    Fantasy Shop title emoji shows up next to their name across the whole
    bot, not just in a couple of spots. Returns '' if the user has no
    title equipped or if user_id isn't a valid int (defensive — some call
    sites pass values from dicts that could theoretically be malformed)."""
    try:
        uid = int(user_id)
    except (TypeError, ValueError):
        return ""
    e = _equipped_title_emoji(uid)
    return f" {e}" if e else ""

# 🏷️ Limited-time Fantasy Shop discount (owner-controlled via /fantasydiscount)
FANTASY_DISCOUNT = {"percent": 0, "expires_at": 0}


def get_active_discount_percent() -> int:
    """Returns the currently active discount % (0 if none/expired)."""
    if FANTASY_DISCOUNT["percent"] > 0 and time.time() < FANTASY_DISCOUNT["expires_at"]:
        return FANTASY_DISCOUNT["percent"]
    return 0


def get_discounted_price(base_price: int) -> int:
    pct = get_active_discount_percent()
    if pct <= 0:
        return base_price
    return max(1, int(round(base_price * (100 - pct) / 100)))

# --- DUAL STORAGE MANAGER (SQL + JSON) ---
# ═══════════════════════════════════════════════════════════════
# 🔧 FIX: centralized, self-healing DB connection helper.
# Every sqlite3.connect(DB_PATH/DB_FILE/TOURNAMENT_DB_PATH) call now
# goes through here. This guarantees the schema exists (fixes
# "no such table: user_stats" caused by any code path that opens a
# connection before init_db()/init_tournament_db() has run, e.g.
# after /restore with a partial DB, or on a fresh/wiped disk) without
# re-running the full CREATE/ALTER TABLE sequence on every call
# (only runs once per process, then is a cheap flag check).
# ═══════════════════════════════════════════════════════════════
_db_ready = False
_tournament_db_ready = False

def db_connect(path):
    """Drop-in replacement for sqlite3.connect(path) that guarantees
    the relevant schema has been created first."""
    global _db_ready, _tournament_db_ready
    try:
        if path in (DB_PATH, DB_FILE) and not _db_ready:
            init_db()
            _db_ready = True
        elif path == TOURNAMENT_DB_PATH and not _tournament_db_ready:
            init_tournament_db()
            _tournament_db_ready = True
    except Exception:
        logger.exception(f"db_connect: schema init check failed for {path}")
    # check_same_thread=False: db_connect() is routinely invoked via
    # `await asyncio.to_thread(db_connect, ...)`, which creates the
    # connection on a threadpool worker thread while the caller then
    # runs c.execute()/commit() back on the main event-loop thread (or
    # a different worker thread on a later to_thread call). SQLite's
    # default check_same_thread=True raises "SQLite objects created in
    # a thread can only be used in that same thread" in exactly that
    # situation. We only ever touch a given connection sequentially
    # (never concurrently from two threads at once), so disabling the
    # same-thread check is safe here.
    return sqlite3.connect(path, check_same_thread=False)


def init_db():
    """Initialize SQL Tables with SQLite WAL mode for high concurrency & speed."""
    conn = sqlite3.connect(DB_FILE)  # raw connect on purpose: db_connect() calls init_db(), so using db_connect() here would recurse infinitely
    c = conn.cursor()
    c.execute("PRAGMA journal_mode=WAL;")
    c.execute("PRAGMA synchronous=NORMAL;")
    # ⚡ Performance tuning: bigger page cache, in-memory temp tables, memory
    # mapped I/O and a busy timeout so concurrent writers wait instead of
    # raising "database is locked" under group-match load.
    for _pragma in (
        "PRAGMA cache_size=-64000;",      # ~64 MB page cache
        "PRAGMA temp_store=MEMORY;",
        "PRAGMA mmap_size=268435456;",    # 256 MB mmap
        "PRAGMA busy_timeout=8000;",
        "PRAGMA foreign_keys=ON;",
    ):
        try:
            c.execute(_pragma)
        except Exception:
            logger.warning(f"init_db: pragma failed {_pragma}")
    
    print("Creating tables...")
    
    # Original tables
    c.execute('''CREATE TABLE IF NOT EXISTS users (user_id INTEGER PRIMARY KEY, data TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS player_stats (user_id INTEGER PRIMARY KEY, data TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS matches (match_id TEXT PRIMARY KEY, data TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS groups (group_id INTEGER PRIMARY KEY, data TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS achievements (user_id INTEGER PRIMARY KEY, data TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS fantasy_stats (user_id INTEGER PRIMARY KEY, data TEXT)''')

    # 👑 Powered users (broadcast/groupapprove access) — persisted so the owner
    # doesn't have to re-grant power to the same trusted people after every
    # bot restart. Loaded into the in-memory POWERED_USERS set at startup.
    c.execute('''CREATE TABLE IF NOT EXISTS powered_users (
        user_id INTEGER PRIMARY KEY,
        permissions TEXT DEFAULT '',
        granted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    # Migration: add permissions column if table already existed without it
    try:
        c.execute("ALTER TABLE powered_users ADD COLUMN permissions TEXT DEFAULT ''")
    except Exception:
        pass

    # 🔧 LIGHTWEIGHT OVER-CHECKPOINT: tiny per-match snapshot written after
    # every completed over (NOT a full stats commit). If the server crashes
    # mid-match, the match can recover from the last checkpointed over
    # instead of losing the whole game. Cleared once the match ends normally
    # and a full stats commit (save_data()) has happened.
    c.execute('''CREATE TABLE IF NOT EXISTS match_checkpoints (
        group_id INTEGER PRIMARY KEY,
        over_number INTEGER,
        data TEXT,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')

    # Create user_stats table for detailed statistics
    c.execute('''CREATE TABLE IF NOT EXISTS user_stats (
        user_id INTEGER PRIMARY KEY,
        username TEXT,
        first_name TEXT,
        total_runs INTEGER DEFAULT 0,
        total_balls_faced INTEGER DEFAULT 0,
        total_wickets INTEGER DEFAULT 0,
        total_balls_bowled INTEGER DEFAULT 0,
        total_runs_conceded INTEGER DEFAULT 0,
        matches_played INTEGER DEFAULT 0,
        matches_won INTEGER DEFAULT 0,
        highest_score INTEGER DEFAULT 0,
        total_hundreds INTEGER DEFAULT 0,
        total_fifties INTEGER DEFAULT 0,
        total_sixes INTEGER DEFAULT 0,
        total_fours INTEGER DEFAULT 0,
        total_dots INTEGER DEFAULT 0,
        best_bowling TEXT DEFAULT '0/0',
        best_bowling_wickets INTEGER DEFAULT 0,
        best_bowling_runs INTEGER DEFAULT 0,
        total_ducks INTEGER DEFAULT 0,
        five_wicket_hauls INTEGER DEFAULT 0,
        player_of_match_count INTEGER DEFAULT 0,
        last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    
    # Migration: add missing columns to existing DB
    for col_name, col_def in [
        ("best_bowling_wickets", "INTEGER DEFAULT 0"),
        ("best_bowling_runs", "INTEGER DEFAULT 0"),
        ("five_wicket_hauls", "INTEGER DEFAULT 0"),
        ("player_of_match_count", "INTEGER DEFAULT 0"),
        ("last_updated", "TIMESTAMP DEFAULT CURRENT_TIMESTAMP"),
        ("total_boundaries", "INTEGER DEFAULT 0"),
        ("win_streak", "INTEGER DEFAULT 0"),
        ("hat_tricks", "INTEGER DEFAULT 0"),
        ("times_not_out", "INTEGER DEFAULT 0"),
        ("team_matches_played", "INTEGER DEFAULT 0"),
        ("team_matches_won", "INTEGER DEFAULT 0"),
        ("team_total_runs", "INTEGER DEFAULT 0"),
        ("team_total_wickets", "INTEGER DEFAULT 0"),
        ("team_total_runs_conceded", "INTEGER DEFAULT 0"),
        ("team_highest_score", "INTEGER DEFAULT 0"),
        ("team_total_sixes", "INTEGER DEFAULT 0"),
        ("team_total_fours", "INTEGER DEFAULT 0"),
        ("team_best_bowling_wickets", "INTEGER DEFAULT 0"),
        ("team_best_bowling_runs", "INTEGER DEFAULT 0"),
        ("team_total_hundreds", "INTEGER DEFAULT 0"),
        ("team_total_fifties", "INTEGER DEFAULT 0"),
        ("team_total_ducks", "INTEGER DEFAULT 0"),
        ("team_total_dots", "INTEGER DEFAULT 0"),
        ("total_dots", "INTEGER DEFAULT 0"),
        ("team_total_balls_faced", "INTEGER DEFAULT 0"),
        ("team_total_balls_bowled", "INTEGER DEFAULT 0"),
        ("team_total_catches", "INTEGER DEFAULT 0"),
        ("team_total_stumpings", "INTEGER DEFAULT 0"),
        ("dismissals_bowled", "INTEGER DEFAULT 0"),
        ("dismissals_lbw", "INTEGER DEFAULT 0"),
        ("dismissals_caught", "INTEGER DEFAULT 0"),
        ("catches_taken", "INTEGER DEFAULT 0"),
        ("solo_matches_played", "INTEGER DEFAULT 0"),
        ("solo_matches_won", "INTEGER DEFAULT 0"),
        ("solo_total_runs", "INTEGER DEFAULT 0"),
        ("solo_total_balls_faced", "INTEGER DEFAULT 0"),
        ("solo_highest_score", "INTEGER DEFAULT 0"),
        ("solo_total_sixes", "INTEGER DEFAULT 0"),
        ("solo_total_fours", "INTEGER DEFAULT 0"),
        ("solo_total_hundreds", "INTEGER DEFAULT 0"),
        ("solo_total_fifties", "INTEGER DEFAULT 0"),
        ("solo_total_ducks", "INTEGER DEFAULT 0"),
        ("solo_top3_finishes", "INTEGER DEFAULT 0"),
        ("solo_total_wickets", "INTEGER DEFAULT 0"),
        ("solo_total_balls_bowled", "INTEGER DEFAULT 0"),
        ("solo_total_runs_conceded", "INTEGER DEFAULT 0"),
        ("solo_best_bowling_wickets", "INTEGER DEFAULT 0"),
        ("solo_best_bowling_runs", "INTEGER DEFAULT 0"),
        ("solo_matches_bowled", "INTEGER DEFAULT 0"),
        ("bowling_strike_count", "INTEGER DEFAULT 0"),
        ("bowling_ban_until", "TEXT DEFAULT ''"),
        ("bowling_ban_total_count", "INTEGER DEFAULT 0"),
        ("endmatch_strike_count", "INTEGER DEFAULT 0"),
        ("endmatch_ban_until", "TEXT DEFAULT ''"),
        ("endmatch_ban_total_count", "INTEGER DEFAULT 0"),
        ("total_reactions_received", "INTEGER DEFAULT 0"),
    ]:
        try:
            c.execute(f"ALTER TABLE user_stats ADD COLUMN {col_name} {col_def}")
        except Exception:
            pass

    c.execute('''CREATE TABLE IF NOT EXISTS ai_stats (
        user_id INTEGER PRIMARY KEY,
        total_matches INTEGER DEFAULT 0,
        wins INTEGER DEFAULT 0,
        losses INTEGER DEFAULT 0,
        easy_matches INTEGER DEFAULT 0,
        medium_matches INTEGER DEFAULT 0,
        hard_matches INTEGER DEFAULT 0,
        easy_wins INTEGER DEFAULT 0,
        medium_wins INTEGER DEFAULT 0,
        hard_wins INTEGER DEFAULT 0,
        highest_score INTEGER DEFAULT 0,
        total_runs INTEGER DEFAULT 0,
        total_sixes INTEGER DEFAULT 0,
        total_fours INTEGER DEFAULT 0,
        last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    
    # Create gc_settings table for per-group admin settings
    c.execute('''CREATE TABLE IF NOT EXISTS gc_settings (
        group_id INTEGER PRIMARY KEY,
        drs_enabled INTEGER DEFAULT 0,
        commentary_style TEXT DEFAULT 'english',
        wide_enabled INTEGER DEFAULT 1,
        lobby_time INTEGER DEFAULT 120,
        solo_wide_enabled INTEGER DEFAULT 1,
        lobby_timer_enabled INTEGER DEFAULT 0,
        adminlock_enabled INTEGER DEFAULT 0
    )''')
    # Migration: add gc_settings table if missing
    try:
        c.execute("SELECT group_id FROM gc_settings LIMIT 1")
    except Exception:
        c.execute('''CREATE TABLE IF NOT EXISTS gc_settings (
            group_id INTEGER PRIMARY KEY,
            drs_enabled INTEGER DEFAULT 0,
            commentary_style TEXT DEFAULT 'english',
            wide_enabled INTEGER DEFAULT 1,
            lobby_time INTEGER DEFAULT 120,
            solo_wide_enabled INTEGER DEFAULT 1,
            lobby_timer_enabled INTEGER DEFAULT 0,
            adminlock_enabled INTEGER DEFAULT 0
        )''')
    # Migration: add solo_wide_enabled column to existing gc_settings tables
    try:
        c.execute("ALTER TABLE gc_settings ADD COLUMN solo_wide_enabled INTEGER DEFAULT 1")
        conn.commit()
    except Exception:
        pass  # column already exists
    # Migration: add lobby_timer_enabled column to existing gc_settings tables.
    # Defaults to 0 (OFF) — lobby timer is now opt-in per group, adjustable
    # from /gcsettings.
    try:
        c.execute("ALTER TABLE gc_settings ADD COLUMN lobby_timer_enabled INTEGER DEFAULT 0")
        conn.commit()
    except Exception:
        pass  # column already exists
    # Migration: add adminlock_enabled column — when ON, only group admins
    # can host a /game (start/host a match) in that group. Off by default.
    try:
        c.execute("ALTER TABLE gc_settings ADD COLUMN adminlock_enabled INTEGER DEFAULT 0")
        conn.commit()
    except Exception:
        pass  # column already exists

    # Create match_history table
    c.execute('''CREATE TABLE IF NOT EXISTS match_history (
        match_id INTEGER PRIMARY KEY AUTOINCREMENT,
        group_id INTEGER,
        match_type TEXT,
        winner_team TEXT,
        runner_up_team TEXT,
        total_overs INTEGER,
        team_x_score TEXT,
        team_y_score TEXT,
        player_of_match INTEGER,
        match_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    
    conn.commit()
    
    # Verify tables were created
    c.execute("SELECT name FROM sqlite_master WHERE type='table'")
    tables = c.fetchall()
    
    print("\n✅ Database created successfully!")
    print(f"\nTables created: {len(tables)}")
    for table in tables:
        print(f"  - {table[0]}")

    # ⚡ Indexes for the hot read paths (leaderboards, history lookups,
    # checkpoint recovery). Each is created only when the target table AND
    # column actually exist, so schema drift can never break startup.
    _existing = {t[0] for t in tables}

    def _cols(table):
        try:
            return {r[1] for r in c.execute(f'PRAGMA table_info("{table}")')}
        except Exception:
            return set()

    _wanted = [
        ("match_history", ("user_id",)),
        ("match_history", ("group_id",)),
        ("match_history", ("match_id",)),
        ("match_checkpoints", ("group_id",)),
        ("user_stats", ("user_id",)),
        ("ai_stats", ("user_id",)),
        ("powered_users", ("user_id",)),
    ]
    _made = 0
    for _table, _idx_cols in _wanted:
        if _table not in _existing:
            continue
        _available = _cols(_table)
        if not all(col in _available for col in _idx_cols):
            continue
        _name = "idx_{}_{}".format(_table, "_".join(_idx_cols))
        _cols_sql = ", ".join(f'"{col}"' for col in _idx_cols)
        try:
            c.execute(f'CREATE INDEX IF NOT EXISTS "{_name}" ON "{_table}" ({_cols_sql})')
            _made += 1
        except Exception:
            logger.warning(f"init_db: could not create index {_name}")
    try:
        c.execute("ANALYZE;")
    except Exception:
        pass
    conn.commit()
    print(f"Indexes ensured: {_made}")

    conn.close()


# ══════════════════════════════════════════════════════════════════════
# 🚫 BOWLING-TIMEOUT BAN SYSTEM
# ------------------------------------------------------------------------
# CONTINUOUS strike counter: increments every time a player gets disqualified
# for a bowling timeout in a match (2 timeouts within one over/spell = 1
# "strike"). The counter RESETS to 0 the moment that same player completes
# a match having bowled WITHOUT being disqualified (see
# reset_bowling_strike_on_clean_match()). Escalation only fires on the
# CURRENT continuous streak, not lifetime total.
#
# Escalation table (continuous strikes -> ban duration):
#   currently flat 30 minutes at every escalation trigger point (2/3/5/7)
# A ban only BLOCKS starting/joining NEW matches (and being /add-ed by
# someone else). It never touches a match the player is already inside.
# ══════════════════════════════════════════════════════════════════════

BOWLING_BAN_ESCALATION = {
    2: timedelta(minutes=30),
    3: timedelta(minutes=30),
    5: timedelta(minutes=30),
    7: timedelta(minutes=30),
}

def _bowling_ban_duration_for_strike(strike_count: int) -> Optional[timedelta]:
    """Returns the ban duration to apply for this exact strike count, or None if this
    strike count isn't an escalation trigger point."""
    return BOWLING_BAN_ESCALATION.get(strike_count)

def record_bowling_timeout_strike(user_id: int) -> Optional[dict]:
    """
    Call this exactly when a player is disqualified for a bowling timeout
    (2 timeouts in one spell) in a live match. Increments their CONTINUOUS
    strike counter and applies a ban if this strike count is an escalation
    trigger. Returns a dict {strike_count, ban_until, ban_label} if a NEW
    ban was just applied, else None.
    """
    try:
        conn = db_connect(DB_PATH)
        c = conn.cursor()
        c.execute("SELECT bowling_strike_count, bowling_ban_total_count FROM user_stats WHERE user_id=?", (user_id,))
        row = c.fetchone()
        current_strikes = (row[0] or 0) if row else 0
        total_bans = (row[1] or 0) if row else 0
        new_strikes = current_strikes + 1

        duration = _bowling_ban_duration_for_strike(new_strikes)
        result = None
        if duration:
            ban_until = datetime.now() + duration
            total_bans += 1
            c.execute(
                "UPDATE user_stats SET bowling_strike_count=?, bowling_ban_until=?, bowling_ban_total_count=? WHERE user_id=?",
                (new_strikes, ban_until.isoformat(), total_bans, user_id)
            )
            if c.rowcount == 0:
                c.execute(
                    "INSERT INTO user_stats (user_id, bowling_strike_count, bowling_ban_until, bowling_ban_total_count) VALUES (?, ?, ?, ?)",
                    (user_id, new_strikes, ban_until.isoformat(), total_bans)
                )
            result = {"strike_count": new_strikes, "ban_until": ban_until, "duration": duration}
        else:
            c.execute("UPDATE user_stats SET bowling_strike_count=? WHERE user_id=?", (new_strikes, user_id))
            if c.rowcount == 0:
                c.execute("INSERT INTO user_stats (user_id, bowling_strike_count) VALUES (?, ?)", (user_id, new_strikes))
        conn.commit()
        conn.close()
        return result
    except Exception as e:
        logger.error(f"record_bowling_timeout_strike failed for {user_id}: {e}")
        return None

def reset_bowling_strike_on_clean_match(user_id: int):
    """Call when a player finishes a match having bowled at least one legal ball
    WITHOUT being disqualified for a bowling timeout — breaks the continuous streak."""
    try:
        conn = db_connect(DB_PATH)
        c = conn.cursor()
        c.execute("UPDATE user_stats SET bowling_strike_count=0 WHERE user_id=?", (user_id,))
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"reset_bowling_strike_on_clean_match failed for {user_id}: {e}")

def get_bowling_ban_remaining(user_id: int) -> Optional[timedelta]:
    """Returns remaining ban duration if the player is currently banned from
    starting/joining new matches, else None. Auto-clears an expired ban."""
    try:
        conn = db_connect(DB_PATH)
        c = conn.cursor()
        c.execute("SELECT bowling_ban_until FROM user_stats WHERE user_id=?", (user_id,))
        row = c.fetchone()
        if not row or not row[0]:
            conn.close()
            return None
        ban_until = datetime.fromisoformat(row[0])
        now = datetime.now()
        if ban_until <= now:
            c.execute("UPDATE user_stats SET bowling_ban_until='' WHERE user_id=?", (user_id,))
            conn.commit()
            conn.close()
            return None
        conn.close()
        return ban_until - now
    except Exception as e:
        logger.error(f"get_bowling_ban_remaining failed for {user_id}: {e}")
        return None


# ───────────────────
# 🆕 "Start the main bot first" gate
#
# A player is considered "known to Cricoverse" once they exist in
# user_data (this now happens on /start in the DM). Since main bot + all
# clones share one database, a player only ever needs to do this ONCE —
# after that they're recognized everywhere (main community or any clone).
#
# Any join flow (team join, solo join, mid-game /join) should call
# player_is_known()/require_started_main_bot() BEFORE silently registering
# someone, so brand-new players are pointed at @cricoverse_bot with an
# inline button instead of being auto-created with no DM link to the bot
# (which used to break DMs like the "bowl" prompt for that player).
# ───────────────────
MAIN_BOT_USERNAME = "cricoverse_bot"


def player_is_known(user_id: int) -> bool:
    """True if this user already exists in the shared user_data store —
    i.e. they've started the bot (main or any clone, since it's one DB)."""
    return user_id in user_data


def _start_main_bot_markup() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[
        styled_button("Start Cricoverse Bot", url=f"https://t.me/{MAIN_BOT_USERNAME}?start=start")
    ]])


async def require_started_main_bot(update: Update, user, use_callback: bool = False) -> bool:
    """Gate for join flows. If the player hasn't started @cricoverse_bot yet,
    tells them to do so (with an inline button) and returns False so the
    caller can stop the join. Returns True if the player is already known."""
    if player_is_known(user.id):
        return True

    text = (
        "🚀 <b>One quick step first!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"👋 Looks like you're new to <b>Cricoverse</b>!\n"
        f"Please start the main bot @{MAIN_BOT_USERNAME} first, then come back and join.\n"
        f"<i>You only need to do this once — it works everywhere, main bot or any clone!</i>"
    )
    markup = _start_main_bot_markup()

    try:
        if use_callback and update.callback_query:
            await update.callback_query.answer(
                plain_alert(f"👋 Please start @{MAIN_BOT_USERNAME} first, then join!"), show_alert=True
            )
            try:
                await update.callback_query.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
            except Exception:
                pass
        else:
            await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception as e:
        logger.error(f"require_started_main_bot prompt failed: {e}")

    return False

def _format_ban_remaining(delta: timedelta) -> str:
    total_secs = int(delta.total_seconds())
    days, rem = divmod(total_secs, 86400)
    hours, rem = divmod(rem, 3600)
    minutes = rem // 60
    parts = []
    if days: parts.append(f"{days}d")
    if hours: parts.append(f"{hours}h")
    if minutes and not days: parts.append(f"{minutes}m")
    return " ".join(parts) if parts else "a few minutes"

async def _dm_owner_ban_applied(context: ContextTypes.DEFAULT_TYPE, ban_type: str, user_id: int,
                                 strike_count: int, ban_until: datetime, duration: timedelta):
    """DM the bot owner whenever ANY penalty ban (bowling-timeout or endmatch) is
    applied to a player, with an inline button to instantly forgive/unban them."""
    try:
        try:
            member = await context.bot.get_chat(user_id)
            name = html.escape(member.first_name or str(user_id))
        except Exception:
            name = str(user_id)

        label = "Bowling Timeout" if ban_type == "bowl" else "Endmatch (Early End)"
        text = (
            "🚫 <b>Player Banned (Penalty)</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"👤 Player: <a href=\"tg://user?id={user_id}\">{name}</a> (<code>{user_id}</code>)\n"
            f"📌 Reason: {label} strike #{strike_count}\n"
            f"⏳ Duration: {_format_ban_remaining(duration)}\n"
            f"🔓 Lifts at: {ban_until.strftime('%d %b %Y, %I:%M %p')}"
        )
        markup = InlineKeyboardMarkup([[
            InlineKeyboardButton("✅ Unban (Forgive)", callback_data=f"ownerunban_{ban_type}_{user_id}")
        ]])
        await context.bot.send_message(
            chat_id=OWNER_ID,
            text=text,
            parse_mode=ParseMode.HTML,
            reply_markup=markup
        )
    except Exception as e:
        logger.error(f"_dm_owner_ban_applied failed: {e}")


async def _dm_bowling_ban_notice(context: ContextTypes.DEFAULT_TYPE, user_id: int, strike_count: int, ban_until: datetime, duration: timedelta):
    """DM the player when a new bowling-timeout ban is applied."""
    try:
        await context.bot.send_message(
            chat_id=user_id,
            text=(
                "🚫 <b>Match Ban Applied</b>\n\n"
                f"You've been disqualified for a bowling timeout <b>{strike_count} times in a row</b> "
                "(not bowling / going offline during your over).\n\n"
                f"⏳ <b>Ban duration:</b> {_format_ban_remaining(duration)}\n"
                f"🔓 <b>Lifts at:</b> {ban_until.strftime('%d %b %Y, %I:%M %p')}\n\n"
                "During this ban you can't join or start a new match, and no one can add you to one. "
                "Any match you're already in is unaffected.\n\n"
                "ℹ️ Play a full match bowling your overs to reset your strike streak."
            ),
            parse_mode=ParseMode.HTML
        )
    except Exception:
        pass  # user may have blocked the bot / not started a DM

    await _dm_owner_ban_applied(context, "bowl", user_id, strike_count, ban_until, duration)


# ══════════════════════════════════════════════════════════════════════
# 🚫 ENDMATCH (INCOMPLETE GAME) STRIKE SYSTEM
# ------------------------------------------------------------------------
# CONTINUOUS strike counter: increments every time a match HOST force-ends
# a match with /endmatch (or /endsolo) BEFORE it completes naturally (i.e.
# stats are NOT saved). The counter RESETS to 0 the moment that same host
# completes a match naturally (stats saved — see reset point in
# update_player_stats_after_match / save_solo_match_stats). Escalation only
# fires on the CURRENT continuous streak, not lifetime total.
#
# Escalation table (continuous strikes -> ban duration):
#   3 -> 12 hours   5 -> 1 day   7 -> 3 days   10 -> 7 days   15 -> 15 days
# A ban only BLOCKS starting/joining NEW matches. It never touches a match
# the player is already inside.
# ══════════════════════════════════════════════════════════════════════

ENDMATCH_BAN_ESCALATION = {
    3: timedelta(hours=2),
    5: timedelta(hours=2),
    7: timedelta(hours=2),
    10: timedelta(hours=2),
    15: timedelta(hours=2),
}

def _endmatch_ban_duration_for_strike(strike_count: int) -> Optional[timedelta]:
    """Returns the ban duration for this exact strike count, or None if this
    strike count isn't an escalation trigger point."""
    return ENDMATCH_BAN_ESCALATION.get(strike_count)

def record_endmatch_strike(user_id: int) -> Optional[dict]:
    """
    Call this exactly when a match HOST force-ends a match via /endmatch or
    /endsolo BEFORE it completes (no stats saved). Increments their
    CONTINUOUS strike counter and applies/escalates a ban if this strike
    count is an escalation trigger. Returns a dict {strike_count, ban_until,
    duration} if a NEW ban was just applied, else None.
    """
    try:
        conn = db_connect(DB_PATH)
        c = conn.cursor()
        c.execute("SELECT endmatch_strike_count, endmatch_ban_total_count FROM user_stats WHERE user_id=?", (user_id,))
        row = c.fetchone()
        current_strikes = (row[0] or 0) if row else 0
        total_bans = (row[1] or 0) if row else 0
        new_strikes = current_strikes + 1

        duration = _endmatch_ban_duration_for_strike(new_strikes)
        result = None
        if duration:
            ban_until = datetime.now() + duration
            total_bans += 1
            c.execute(
                "UPDATE user_stats SET endmatch_strike_count=?, endmatch_ban_until=?, endmatch_ban_total_count=? WHERE user_id=?",
                (new_strikes, ban_until.isoformat(), total_bans, user_id)
            )
            if c.rowcount == 0:
                c.execute(
                    "INSERT INTO user_stats (user_id, endmatch_strike_count, endmatch_ban_until, endmatch_ban_total_count) VALUES (?, ?, ?, ?)",
                    (user_id, new_strikes, ban_until.isoformat(), total_bans)
                )
            result = {"strike_count": new_strikes, "ban_until": ban_until, "duration": duration}
        else:
            c.execute("UPDATE user_stats SET endmatch_strike_count=? WHERE user_id=?", (new_strikes, user_id))
            if c.rowcount == 0:
                c.execute("INSERT INTO user_stats (user_id, endmatch_strike_count) VALUES (?, ?)", (user_id, new_strikes))
        conn.commit()
        conn.close()
        return result
    except Exception as e:
        logger.error(f"record_endmatch_strike failed for {user_id}: {e}")
        return None

def reset_endmatch_strike_on_clean_match(user_id: int):
    """Call when a match HOSTED by this user completes naturally (stats saved)
    — breaks the continuous incomplete-game streak."""
    try:
        conn = db_connect(DB_PATH)
        c = conn.cursor()
        c.execute("UPDATE user_stats SET endmatch_strike_count=0 WHERE user_id=?", (user_id,))
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"reset_endmatch_strike_on_clean_match failed for {user_id}: {e}")

def get_endmatch_strike_count(user_id: int) -> int:
    """Current continuous incomplete-game strike count for this user."""
    try:
        conn = db_connect(DB_PATH)
        c = conn.cursor()
        c.execute("SELECT endmatch_strike_count FROM user_stats WHERE user_id=?", (user_id,))
        row = c.fetchone()
        conn.close()
        return (row[0] or 0) if row else 0
    except Exception as e:
        logger.error(f"get_endmatch_strike_count failed for {user_id}: {e}")
        return 0

def get_endmatch_ban_remaining(user_id: int) -> Optional[timedelta]:
    """Returns remaining ban duration if this user is currently banned from
    starting/joining new matches due to endmatch strikes, else None.
    Auto-clears an expired ban."""
    try:
        conn = db_connect(DB_PATH)
        c = conn.cursor()
        c.execute("SELECT endmatch_ban_until FROM user_stats WHERE user_id=?", (user_id,))
        row = c.fetchone()
        if not row or not row[0]:
            conn.close()
            return None
        ban_until = datetime.fromisoformat(row[0])
        now = datetime.now()
        if ban_until <= now:
            c.execute("UPDATE user_stats SET endmatch_ban_until='' WHERE user_id=?", (user_id,))
            conn.commit()
            conn.close()
            return None
        conn.close()
        return ban_until - now
    except Exception as e:
        logger.error(f"get_endmatch_ban_remaining failed for {user_id}: {e}")
        return None

async def _dm_endmatch_strike_notice(context: ContextTypes.DEFAULT_TYPE, user_id: int, strike_count: int,
                                      ban_until: Optional[datetime] = None, duration: Optional[timedelta] = None):
    """DM the host every time an endmatch strike is recorded. If a ban was just
    applied (strike_count hit an escalation point), includes the ban details."""
    try:
        lines = [
            "⚠️ <b>Match Ended Early — Strike Recorded</b>",
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            f"You force-ended a match with <code>/endmatch</code> before it finished "
            f"(stats not saved). This is strike <b>#{strike_count}</b> in a row.",
        ]
        if duration and ban_until:
            lines += [
                "",
                "🚫 <b>Ban Applied</b>",
                f"⏳ Duration: {_format_ban_remaining(duration)}",
                f"🔓 Lifts at: {ban_until.strftime('%d %b %Y, %I:%M %p')}",
                "",
                "During this ban you can't start or join a new match, and no one can add you to one. "
                "Any match you're already in is unaffected.",
            ]
        lines += [
            "",
            "ℹ️ Play a match to full completion (without /endmatch) to reset your strike streak.",
        ]
        await context.bot.send_message(
            chat_id=user_id,
            text="<blockquote>" + "\n".join(lines) + "</blockquote>",
            parse_mode=ParseMode.HTML
        )
    except Exception:
        pass  # user may have blocked the bot / not started a DM

    if duration and ban_until:
        await _dm_owner_ban_applied(context, "endmatch", user_id, strike_count, ban_until, duration)


def init_tournament_db():
    """Initialize tournament registration database"""
    conn = sqlite3.connect(TOURNAMENT_DB_PATH)  # raw connect on purpose: db_connect() calls init_tournament_db(), so using db_connect() here would recurse infinitely
    c = conn.cursor()
    
    c.execute("""
        CREATE TABLE IF NOT EXISTS tournament_groups (
            group_id INTEGER PRIMARY KEY,
            group_name TEXT,
            approved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            expires_at TIMESTAMP,
            reminder_sent INTEGER DEFAULT 0
        )
    """)
    # Add expires_at and reminder_sent columns if they don't exist (for existing DBs)
    try:
        c.execute("ALTER TABLE tournament_groups ADD COLUMN expires_at TIMESTAMP")
    except: pass
    try:
        c.execute("ALTER TABLE tournament_groups ADD COLUMN reminder_sent INTEGER DEFAULT 0")
    except: pass
    
    c.execute("""
        CREATE TABLE IF NOT EXISTS registration_periods (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            group_id INTEGER,
            tournament_name TEXT,
            start_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            end_date TIMESTAMP,
            days INTEGER,
            is_active INTEGER DEFAULT 1,
            FOREIGN KEY (group_id) REFERENCES tournament_groups(group_id)
        )
    """)
    
    c.execute("""
        CREATE TABLE IF NOT EXISTS registered_players (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            group_id INTEGER,
            user_id INTEGER,
            username TEXT,
            full_name TEXT,
            base_price INTEGER,
            registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(group_id, user_id),
            FOREIGN KEY (group_id) REFERENCES tournament_groups(group_id)
        )
    """)
    # 🏏 Approval workflow: new self-registrations sit as 'pending' until a tour
    # organiser approves/rejects them. Existing rows (added before this column
    # existed) default to 'approved' so nothing already registered breaks.
    try:
        c.execute("ALTER TABLE registered_players ADD COLUMN status TEXT DEFAULT 'approved'")
    except Exception:
        pass

    c.execute("""
        CREATE TABLE IF NOT EXISTS tournament_organisers (
            user_id INTEGER,
            group_id INTEGER,
            added_by INTEGER,
            added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(user_id, group_id)
        )
    """)

    c.execute("""
        CREATE TABLE IF NOT EXISTS auction_results (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            group_id INTEGER,
            player_user_id INTEGER,
            player_name TEXT,
            team_name TEXT,
            final_price INTEGER,
            auction_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (group_id) REFERENCES tournament_groups(group_id)
        )
    """)
    
    c.execute("""
        CREATE TABLE IF NOT EXISTS tournament_power_users (
            user_id INTEGER,
            group_id INTEGER,
            granted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (user_id, group_id)
        )
    """)

    # ✅ Temporary tour-state storage (teams, fixtures, points, match stats).
    # Cleared automatically when a tour is ended via /tourend or the "End Tour" button.
    c.execute("""
        CREATE TABLE IF NOT EXISTS tour_state (
            group_id INTEGER PRIMARY KEY,
            teams TEXT,
            fixtures TEXT,
            points TEXT,
            match_stats TEXT,
            fixture_counter INTEGER DEFAULT 0,
            groups TEXT,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)
    # 🆕 GROUP SYSTEM (Group A / Group B): older DBs won't have the "groups"
    # column yet — add it if missing so existing installs don't crash.
    try:
        c.execute("ALTER TABLE tour_state ADD COLUMN groups TEXT")
    except Exception:
        pass  # column already exists

    # 🆕 MULTI-GROUP TOURNAMENTS: a secondary group can be "linked" to a
    # primary group's tournament (via /tourcode + /linktour) so matches
    # played in EITHER group share the same teams/fixtures/points/stats —
    # multiple matches of the SAME tournament can run at the same time in
    # different groups, all feeding one shared points table.
    c.execute("""
        CREATE TABLE IF NOT EXISTS tour_group_links (
            secondary_group_id INTEGER PRIMARY KEY,
            primary_group_id INTEGER,
            linked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)

    conn.commit()
    conn.close()
    logger.info("✅ Tournament database initialized")


def _save_tour_state_sync(group_id: int):
    """Actual blocking DB write — always run this inside a background thread,
    never directly on the event loop (see save_tour_state below)."""
    try:
        # 🩹 FIX: a secondary group linked via /linktour reads/writes the SAME
        # in-memory tour data as its primary group (via _TourSharedDict's
        # alias resolution), but this write used to save under the RAW
        # group_id it was called with — so a match finishing in the
        # secondary group wrote a SEPARATE, duplicate row for that
        # secondary group_id in tour_state. On the next restart,
        # load_tour_state() loads every row in the table (including that
        # stale duplicate) and the LAST one read wins — so whichever row
        # happened to be older could silently overwrite the other group's
        # freshly-updated points/fixtures/stats, making matches/results
        # appear to randomly vanish after a restart. Resolving to the
        # primary group_id before writing means only ONE row is ever kept
        # per tournament, no matter which linked group the save came from.
        group_id = TOUR_GROUP_ALIAS.get(group_id, group_id)
        conn= db_connect(TOURNAMENT_DB_PATH)
        c = conn.cursor()
        c.execute("""
            INSERT INTO tour_state (group_id, teams, fixtures, points, match_stats, fixture_counter, groups, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
            ON CONFLICT(group_id) DO UPDATE SET
                teams=excluded.teams, fixtures=excluded.fixtures, points=excluded.points,
                match_stats=excluded.match_stats, fixture_counter=excluded.fixture_counter,
                groups=excluded.groups,
                updated_at=CURRENT_TIMESTAMP
        """, (
            group_id,
            json.dumps(tournament_teams.get(group_id, {})),
            json.dumps(tournament_fixtures.get(group_id, [])),
            json.dumps(tournament_points.get(group_id, {})),
            json.dumps(tour_match_stats.get(group_id, {})),
            tour_fixture_counter.get(group_id, 0),
            json.dumps(tournament_groups.get(group_id, {})),
        ))
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Error saving tour state for {group_id}: {e}")


def save_tour_state(group_id: int):
    """Persist the in-progress tour state for one group so it survives restarts.
    Called after every tour mutation (team edits, fixtures generated, result recorded).

    🔧 SCALE FIX: this used to open a sqlite connection and write to disk
    directly on the event loop. With many groups/tournaments running at
    once, every single result/edit would freeze ball-detection and result
    messages for EVERY other group for as long as the write took. Now the
    actual DB write runs in a background thread, so the event loop is
    never blocked."""
    try:
        asyncio.create_task(asyncio.to_thread(_save_tour_state_sync, group_id))
    except RuntimeError:
        # No running event loop (e.g. startup/shutdown code) — write inline.
        _save_tour_state_sync(group_id)


def load_tour_state():
    """Restore any in-progress tours on startup so nothing is lost on a bot restart."""
    try:
        conn= db_connect(TOURNAMENT_DB_PATH)
        c = conn.cursor()
        c.execute("SELECT group_id, teams, fixtures, points, match_stats, fixture_counter, groups FROM tour_state")
        rows = c.fetchall()
        conn.close()
        # 🩹 FIX: older DBs (saved before _save_tour_state_sync started
        # resolving group-links to the primary group_id) may still contain a
        # stale duplicate row under a SECONDARY (linked) group_id. Loading
        # that row after the primary's row would silently overwrite the
        # primary's fresh, merged data with a stale snapshot — exactly the
        # "match data disappearing after restart" symptom. TOUR_GROUP_ALIAS
        # is already restored before this runs, so skip any row whose
        # group_id is a known secondary alias — only the primary's row (or a
        # standalone, unlinked group's row) is ever loaded.
        for group_id, teams, fixtures, points, match_stats, fixture_counter, groups in rows:
            if group_id in TOUR_GROUP_ALIAS:
                logger.info(f"⏭️ Skipping stale linked-group tour_state row for {group_id} (aliased to {TOUR_GROUP_ALIAS[group_id]})")
                continue
            tournament_teams[group_id] = json.loads(teams) if teams else {}
            tournament_fixtures[group_id] = json.loads(fixtures) if fixtures else []
            tournament_points[group_id] = json.loads(points) if points else {}
            tour_match_stats[group_id] = json.loads(match_stats) if match_stats else {}
            tour_fixture_counter[group_id] = fixture_counter or 0
            tournament_groups[group_id] = json.loads(groups) if groups else {}
        if rows:
            logger.info(f"✅ Restored in-progress tour state for {len(rows)} group(s)")
    except Exception as e:
        logger.error(f"❌ Error loading tour state: {e}")


def clear_tour_state(group_id: int):
    """Wipe all temporary tour data for a group once the tour has ended."""
    try:
        conn= db_connect(TOURNAMENT_DB_PATH)
        c = conn.cursor()
        c.execute("DELETE FROM tour_state WHERE group_id = ?", (group_id,))
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Error clearing tour state for {group_id}: {e}")

    tournament_teams.pop(group_id, None)
    tournament_fixtures.pop(group_id, None)
    tournament_points.pop(group_id, None)
    tour_match_stats.pop(group_id, None)
    tour_fixture_counter.pop(group_id, None)
    tournament_groups.pop(group_id, None)
    pending_tour_match.pop(group_id, None)

    # 🆕 Unlink every group that was sharing this tournament (it's gone now)
    linked = [sec for sec, prim in TOUR_GROUP_ALIAS.items() if prim == group_id]
    for sec in linked:
        unlink_tour_group(sec)


# ═══════════════════════════════════════════════════════════════
# 🆕 MULTI-GROUP TOURNAMENT LINKING
# Lets a tournament span several Telegram groups: matches started in ANY
# linked group all read/write the SAME teams/fixtures/points/player-stats
# (via TOUR_GROUP_ALIAS + _TourSharedDict above), so two matches of the
# same tournament can genuinely run at the same time in two different
# groups without their results/stats getting siloed apart.
# ═══════════════════════════════════════════════════════════════

def generate_tour_link_code(primary_group_id: int) -> str:
    """Organiser runs /tourcode in the PRIMARY (main) tournament group to get
    a short code other admins can use with /linktour <code> in their own
    group."""
    code = ''.join(random.choices('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', k=6))
    TOUR_LINK_CODES[code] = primary_group_id
    return code


def link_tour_group(secondary_group_id: int, primary_group_id: int):
    """Link secondary_group_id's tournament data to primary_group_id's."""
    TOUR_GROUP_ALIAS[secondary_group_id] = primary_group_id
    try:
        conn = db_connect(TOURNAMENT_DB_PATH)
        c = conn.cursor()
        c.execute("""
            INSERT INTO tour_group_links (secondary_group_id, primary_group_id, linked_at)
            VALUES (?, ?, CURRENT_TIMESTAMP)
            ON CONFLICT(secondary_group_id) DO UPDATE SET
                primary_group_id=excluded.primary_group_id, linked_at=CURRENT_TIMESTAMP
        """, (secondary_group_id, primary_group_id))
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Error saving tour group link {secondary_group_id}->{primary_group_id}: {e}")
    # Drop any of the secondary group's own (now-shadowed) tour data on disk
    try:
        conn = db_connect(TOURNAMENT_DB_PATH)
        c = conn.cursor()
        c.execute("DELETE FROM tour_state WHERE group_id = ?", (secondary_group_id,))
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Error clearing pre-link tour state for {secondary_group_id}: {e}")


def unlink_tour_group(secondary_group_id: int):
    TOUR_GROUP_ALIAS.pop(secondary_group_id, None)
    try:
        conn = db_connect(TOURNAMENT_DB_PATH)
        c = conn.cursor()
        c.execute("DELETE FROM tour_group_links WHERE secondary_group_id = ?", (secondary_group_id,))
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Error removing tour group link for {secondary_group_id}: {e}")


def load_tour_group_links():
    """Restore TOUR_GROUP_ALIAS on startup — MUST run before load_tour_state()
    so rows from every linked group land on the correct shared entry."""
    try:
        conn = db_connect(TOURNAMENT_DB_PATH)
        c = conn.cursor()
        c.execute("SELECT secondary_group_id, primary_group_id FROM tour_group_links")
        for sec, prim in c.fetchall():
            TOUR_GROUP_ALIAS[sec] = prim
        conn.close()
        logger.info(f"✅ Loaded {len(TOUR_GROUP_ALIAS)} tournament group links")
    except Exception as e:
        logger.error(f"Error loading tour group links: {e}")

def load_tournament_data():
    """Load tournament data on startup"""
    try:
        conn= db_connect(TOURNAMENT_DB_PATH)
        c = conn.cursor()
        
        c.execute('SELECT group_id FROM tournament_groups')
        for (group_id,) in c.fetchall():
            TOURNAMENT_APPROVED_GROUPS.add(group_id)
        
        c.execute("""
            SELECT group_id, end_date, days, tournament_name FROM registration_periods
            WHERE is_active = 1 AND end_date > ?
        """, (datetime.now().isoformat(),))
        for group_id, end_date, days, tournament_name in c.fetchall():
            REGISTRATION_ACTIVE[group_id] = {
                'end_date': datetime.fromisoformat(end_date),
                'days': days,
                'tournament_name': tournament_name or 'Tournament'
            }
        
        c.execute('SELECT user_id, group_id FROM tournament_power_users')
        for user_id, group_id in c.fetchall():
            TOURNAMENT_POWER_USERS.add((user_id, group_id))

        c.execute('SELECT user_id, group_id FROM tournament_organisers')
        for user_id, group_id in c.fetchall():
            TOURNAMENT_ORGANISERS.add((user_id, group_id))
        
        conn.close()
        logger.info(f"✅ Loaded {len(TOURNAMENT_APPROVED_GROUPS)} tournament groups")
    except Exception as e:
        logger.error(f"Error loading tournament data: {e}")

    # ✅ Restore any in-progress tour (teams/fixtures/points/match stats)
    load_tour_group_links()  # 🆕 must load BEFORE load_tour_state so aliasing is active
    load_tour_state()


_save_data_dirty = False
_save_data_task = None

def _save_data_sync():
    """The actual blocking I/O — only ever run inside a background thread now."""
    try:
        # 1. SQL Save (Primary & Fast)
        conn= db_connect(DB_FILE)
        c = conn.cursor()
        c.execute("BEGIN TRANSACTION")
        
        for uid, data in user_data.items():
            c.execute("INSERT OR REPLACE INTO users (user_id, data) VALUES (?, ?)", (uid, json.dumps(data)))
        for uid, data in player_stats.items():
            c.execute("INSERT OR REPLACE INTO player_stats (user_id, data) VALUES (?, ?)", (uid, json.dumps(data)))
        for match in match_history:
            mid = match.get("match_id", str(time.time()))
            c.execute("INSERT OR REPLACE INTO matches (match_id, data) VALUES (?, ?)", (mid, json.dumps(match)))
        for gid, data in registered_groups.items():
            c.execute("INSERT OR REPLACE INTO groups (group_id, data) VALUES (?, ?)", (gid, json.dumps(data)))
        for uid, data in achievements.items():
            c.execute("INSERT OR REPLACE INTO achievements (user_id, data) VALUES (?, ?)", (uid, json.dumps(data)))
        for uid, data in fantasy_data.items():
            c.execute("INSERT OR REPLACE INTO fantasy_stats (user_id, data) VALUES (?, ?)", (uid, json.dumps(data)))

        conn.commit()
        conn.close()
        # 🔧 JSON backup removed — SQLite (DB_FILE) is now the single source of
        # truth. Writing 6 JSON files on every save doubled disk I/O for no
        # benefit once SQLite is reliable, so it's gone. If you ever need a
        # human-readable export, use /dbexport or a one-off script instead.

    except Exception as e:
        logger.error(f"Error saving data: {e}")


async def _save_data_debounced():
    """
    🔧 SCALE FIX: save_data() debounces disk writes (wait 10s) and runs in background thread.
    """
    global _save_data_dirty, _save_data_task
    await asyncio.sleep(10)
    _save_data_dirty = False
    await asyncio.to_thread(_save_data_sync)
    _save_data_task = None


def save_data():
    """Non-blocking: schedules a debounced background save instead of writing inline."""
    global _save_data_dirty, _save_data_task
    _save_data_dirty = True
    if _save_data_task is None or _save_data_task.done():
        try:
            _save_data_task = asyncio.create_task(_save_data_debounced())
        except RuntimeError:
            # No running event loop (e.g. called from sync startup code) — save immediately, inline.
            _save_data_sync()

def _checkpoint_match_sync(group_id: int, over_number: int, snapshot: dict):
    """
    ⚡ LIGHTWEIGHT PER-OVER CHECKPOINT (runs in a background thread).
    Writes ONE small row for this match — not a full stats DB commit.
    This is what keeps a crash from losing the whole match: worst case you
    lose the current, still-in-progress over, not the whole game.
    """
    try:
        conn = db_connect(DB_FILE)
        c = conn.cursor()
        c.execute(
            "INSERT OR REPLACE INTO match_checkpoints (group_id, over_number, data, updated_at) VALUES (?, ?, ?, CURRENT_TIMESTAMP)",
            (group_id, over_number, json.dumps(snapshot)),
        )
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"Checkpoint save failed for group {group_id}: {e}")


def checkpoint_match(group_id: int, match) -> None:
    """
    Call this once per completed over. Fire-and-forget — never blocks the
    ball flow. This intentionally does NOT touch user_data / player_stats /
    achievements etc; that full commit only happens at match end via
    save_data() (or the debounced background save it schedules).
    """
    try:
        bat_team = match.current_batting_team
        snapshot = {
            "innings": match.innings,
            "batting_team": bat_team.name,
            "score": bat_team.score,
            "wickets": bat_team.wickets,
            "balls": bat_team.balls,
            "target": getattr(match, "target", None),
            "total_overs": match.total_overs,
        }
        over_number = bat_team.balls // 6
        asyncio.create_task(asyncio.to_thread(_checkpoint_match_sync, group_id, over_number, snapshot))
    except RuntimeError:
        # No running event loop — safe to skip, this is a best-effort backup only.
        pass
    except Exception as e:
        logger.error(f"checkpoint_match failed for group {group_id}: {e}")


def clear_match_checkpoint(group_id: int) -> None:
    """Drop the checkpoint row once the match ends and a full save_data() commit has run."""
    def _clear():
        try:
            conn = db_connect(DB_FILE)
            c = conn.cursor()
            c.execute("DELETE FROM match_checkpoints WHERE group_id = ?", (group_id,))
            conn.commit()
            conn.close()
        except Exception as e:
            logger.error(f"Checkpoint clear failed for group {group_id}: {e}")
    try:
        asyncio.create_task(asyncio.to_thread(_clear))
    except RuntimeError:
        _clear()


def load_data():
    """Load all data (Try SQL first, Fallback to JSON)"""
    global user_data, match_history, player_stats, achievements, registered_groups, banned_groups, fantasy_data
    
    # Initialize DB (also runs column migrations on existing DBs — safe to call every time)
    init_db()

    # 👑 Load persisted powered users so the owner doesn't have to re-grant
    # power after every restart.
    try:
        _conn = db_connect(DB_FILE)
        _c = _conn.cursor()
        _c.execute("SELECT user_id, permissions FROM powered_users")
        for (uid, perms_str) in _c.fetchall():
            perm_set = set(p for p in (perms_str or "").split(",") if p)
            if not perm_set:
                # Legacy rows with no permissions saved — grant everything so
                # nobody silently loses access after this upgrade.
                perm_set = {key for key, _ in POWER_PERMISSIONS}
            POWERED_USERS[uid] = perm_set
        _conn.close()
        logger.info(f"✅ Loaded {len(POWERED_USERS)} powered users")
    except Exception as e:
        logger.error(f"Error loading powered users: {e}")

    data_loaded_from_sql = False
    
    # --- TRY LOADING FROM SQL ---
    try:
        conn= db_connect(DB_FILE)
        c = conn.cursor()
        
        # Check if tables exist, if not create them
        c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='player_stats'")
        if not c.fetchone():
            logger.warning("⚠️ player_stats table missing, creating tables...")
            c.execute('''CREATE TABLE IF NOT EXISTS users (user_id INTEGER PRIMARY KEY, data TEXT)''')
            c.execute('''CREATE TABLE IF NOT EXISTS player_stats (user_id INTEGER PRIMARY KEY, data TEXT)''')
            c.execute('''CREATE TABLE IF NOT EXISTS matches (match_id TEXT PRIMARY KEY, data TEXT)''')
            c.execute('''CREATE TABLE IF NOT EXISTS groups (group_id INTEGER PRIMARY KEY, data TEXT)''')
            c.execute('''CREATE TABLE IF NOT EXISTS achievements (user_id INTEGER PRIMARY KEY, data TEXT)''')
            conn.commit()
            logger.info("✅ Tables created successfully")

        # ✅ MIGRATION: fantasy_stats table was added later — make sure it exists
        # on databases created before this feature existed (independent check so
        # it self-heals even if the block above never ran).
        try:
            c.execute("SELECT user_id FROM fantasy_stats LIMIT 1")
        except Exception:
            c.execute('''CREATE TABLE IF NOT EXISTS fantasy_stats (user_id INTEGER PRIMARY KEY, data TEXT)''')
            conn.commit()
            logger.info("✅ fantasy_stats table created (migration)")
        
        c.execute("SELECT count(*) FROM users")
        if c.fetchone()[0] > 0:
            c.execute("SELECT user_id, data FROM users")
            user_data = {row[0]: json.loads(row[1]) for row in c.fetchall()}

            c.execute("SELECT user_id, data FROM player_stats")
            player_stats = {row[0]: json.loads(row[1]) for row in c.fetchall()}

            c.execute("SELECT data FROM matches")
            match_history = [json.loads(row[0]) for row in c.fetchall()]

            c.execute("SELECT group_id, data FROM groups")
            registered_groups = {row[0]: json.loads(row[1]) for row in c.fetchall()}

            c.execute("SELECT user_id, data FROM achievements")
            achievements = {row[0]: json.loads(row[1]) for row in c.fetchall()}

            c.execute("SELECT user_id, data FROM fantasy_stats")
            fantasy_data = {row[0]: json.loads(row[1]) for row in c.fetchall()}
            
            data_loaded_from_sql = True
            logger.info("✅ Data loaded from SQL Database.")
            
        conn.close()
    except Exception as e:
        logger.error(f"SQL Load Error (Falling back to JSON): {e}")

    # --- FALLBACK TO JSON ---
    if not data_loaded_from_sql:
        logger.info("⚠️ Loading from JSON files...")
        try:
            if os.path.exists(USERS_FILE):
                with open(USERS_FILE, 'r') as f: 
                    user_data = {int(k): v for k, v in json.load(f).items()}
            if os.path.exists(STATS_FILE):
                with open(STATS_FILE, 'r') as f: 
                    player_stats = {int(k): v for k, v in json.load(f).items()}
            if os.path.exists(MATCHES_FILE):
                with open(MATCHES_FILE, 'r') as f: 
                    match_history = json.load(f)
            if os.path.exists(GROUPS_FILE):
                with open(GROUPS_FILE, 'r') as f: 
                    registered_groups = {int(k): v for k, v in json.load(f).items()}
            if os.path.exists(ACHIEVEMENTS_FILE):
                with open(ACHIEVEMENTS_FILE, 'r') as f: 
                    achievements = {int(k): v for k, v in json.load(f).items()}
            if os.path.exists(FANTASY_FILE):
                with open(FANTASY_FILE, 'r') as f: 
                    fantasy_data = {int(k): v for k, v in json.load(f).items()}
            
            # JSON se load hone ke baad turant SQL me sync kar do
            save_data()
        except Exception: 
            pass
    
    # ✅ LOAD BANNED GROUPS
    if os.path.exists(BANNED_GROUPS_FILE):
        try:
            with open(BANNED_GROUPS_FILE, 'r') as f:
                banned_groups = set(json.load(f))
            logger.info(f"🚫 Loaded {len(banned_groups)} banned groups")
        except Exception as e:
            logger.error(f"Error loading banned groups: {e}")
            banned_groups = set()

    # ✅ LOAD BANNED USERS
    global banned_users
    if os.path.exists(BANNED_USERS_FILE):
        try:
            with open(BANNED_USERS_FILE, 'r') as f:
                banned_users = {int(k): v for k, v in json.load(f).items()}
            logger.info(f"🚫 Loaded {len(banned_users)} banned users")
        except Exception as e:
            logger.error(f"Error loading banned users: {e}")
            banned_users = {}

    # Load per-group settings
    load_gc_settings()

    # ✧ CRICOINS one-time migration: divide every existing balance by 100.
    # Guarded by a sentinel file so this only ever runs once per bot install.
    try:
        migration_flag = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".cricoins_migrated")
        if not os.path.exists(migration_flag):
            for _uid, _prof in fantasy_data.items():
                if isinstance(_prof, dict) and "points" in _prof:
                    _prof["points"] = max(0, int(_prof["points"]) // 100)
            with open(migration_flag, 'w') as _f:
                _f.write(str(time.time()))
            save_data()
            logger.info("✧ Cricoins migration complete: all balances divided by 100.")
    except Exception:
        logger.exception("Cricoins migration failed")

_BANNED_FILE_MTIME = None


def _banned_file_mtime():
    try:
        return os.stat(BANNED_USERS_FILE).st_mtime
    except Exception:
        return None


def save_banned_users():
    """Persist the banned_users dict to disk (atomic write)."""
    global _BANNED_FILE_MTIME
    try:
        os.makedirs(os.path.dirname(BANNED_USERS_FILE) or ".", exist_ok=True)
        tmp_path = BANNED_USERS_FILE + ".tmp"
        with open(tmp_path, 'w') as f:
            json.dump({str(k): v for k, v in banned_users.items()}, f, indent=2)
        os.replace(tmp_path, BANNED_USERS_FILE)
        _BANNED_FILE_MTIME = _banned_file_mtime()
    except Exception as e:
        logger.error(f"Error saving banned users: {e}")


def reload_banned_users_if_changed():
    """🔄 Main bot and every clone bot share ONE banned_users.json. Each process
    keeps its own in-memory copy, so a ban/unban done in one bot would never reach
    the others until restart. This re-reads the file whenever its mtime changes
    (one cheap os.stat per update), keeping all bots in sync instantly."""
    global _BANNED_FILE_MTIME
    try:
        mt = _banned_file_mtime()
        if mt == _BANNED_FILE_MTIME:
            return
        _BANNED_FILE_MTIME = mt
        if mt is None:
            banned_users.clear()
            return
        with open(BANNED_USERS_FILE, 'r') as f:
            fresh = {int(k): v for k, v in json.load(f).items()}
        banned_users.clear()
        banned_users.update(fresh)
    except Exception as e:
        logger.error(f"reload_banned_users_if_changed failed: {e}")


def is_user_banned(user_id) -> bool:
    """True if this user is fully banned from the bot (owner is never banned)."""
    try:
        if user_id == OWNER_ID:
            return False
        reload_banned_users_if_changed()
        return int(user_id) in banned_users
    except Exception:
        return False

# Initialize player stats for a user
def load_gc_settings():
    """Load all gc_settings from DB into memory"""
    global gc_settings
    try:
        conn= db_connect(DB_PATH)
        c = conn.cursor()
        c.execute("SELECT group_id, drs_enabled, commentary_style, wide_enabled, lobby_time, solo_wide_enabled, lobby_timer_enabled, adminlock_enabled FROM gc_settings")
        rows = c.fetchall()
        conn.close()
        gc_settings = {}
        for row in rows:
            gc_settings[row[0]] = {
                "drs_enabled": bool(row[1]),
                "commentary_style": row[2],
                "wide_enabled": bool(row[3]),
                "lobby_time": row[4],
                "solo_wide_enabled": bool(row[5]) if row[5] is not None else True,
                # 🔧 Lobby timer is OFF by default — groups opt in via /gcsettings.
                "lobby_timer_enabled": bool(row[6]) if row[6] is not None else False,
                # 🔒 Adminlock is OFF by default — only owner/powered users can enable it.
                "adminlock_enabled": bool(row[7]) if len(row) > 7 and row[7] is not None else False
            }
    except Exception as e:
        logger.warning(f"gc_settings load error: {e}")
        gc_settings = {}

def save_gc_setting(group_id: int):
    """Save one group's settings to DB"""
    s = gc_settings.get(group_id, {})
    try:
        conn= db_connect(DB_PATH)
        c = conn.cursor()
        c.execute("""INSERT OR REPLACE INTO gc_settings 
            (group_id, drs_enabled, commentary_style, wide_enabled, lobby_time, solo_wide_enabled, lobby_timer_enabled, adminlock_enabled)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
            (group_id,
             int(s.get("drs_enabled", False)),
             s.get("commentary_style", "english"),
             int(s.get("wide_enabled", True)),
             s.get("lobby_time", 120),
             int(s.get("solo_wide_enabled", True)),
             int(s.get("lobby_timer_enabled", False)),
             int(s.get("adminlock_enabled", False))))
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"gc_settings save error: {e}")

def get_gc_setting(group_id: int, key: str, default=None):
    """Get a specific setting for a group"""
    if group_id not in gc_settings:
        gc_settings[group_id] = {
            "drs_enabled": False,
            "commentary_style": "english",
            "wide_enabled": True,
            "lobby_time": 120,
            "solo_wide_enabled": True,
            "lobby_timer_enabled": False,
            "adminlock_enabled": False
        }
    return gc_settings[group_id].get(key, default if default is not None else {
        "drs_enabled": False, "commentary_style": "english",
        "wide_enabled": True, "lobby_time": 120, "solo_wide_enabled": True,
        "lobby_timer_enabled": False, "adminlock_enabled": False
    }.get(key))


