def _pick_static_commentary(event_type: str, style: str) -> str:
    """Shared lookup: pick a random commentary line for the given resolved style."""
    comments = COMMENTARY_BY_STYLE.get(style, COMMENTARY).get(event_type, [])

    if comments:
        return random.choice(comments)

    fallback = {
        "dot": "Dot ball.",
        "single": "Single taken.",
        "double": "Two runs.",
        "triple": "Three runs.",
        "boundary": "Four runs!",
        "five": "Five runs!",
        "six": "Six runs!",
        "wicket": "OUT!",
        "noball": "No ball!",
        "wide": "Wide ball!",
        "freehit": "Free hit!",
        "hitwicket": "Hit wicket!",
        "wide": "Wide ball!"
    }
    return fallback.get(event_type, "Interesting delivery!")


