def _solo_pad(s, w):
    s = html.escape(str(s))
    return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))


def _solo_rpad(s, w):
    s = str(s)
    return (s[: max(w - 1, 1)] + "…") if len(s) > w else (" " * (w - len(s))) + s


def _build_solo_scorecard_html(match) -> str:
    """Real <table> version of the solo scorecard for sendRichMessage
    (Bot API 10.1+) — same pattern as build_new_scorecard_html."""
    players = match.solo_players

    bat_rows = ""
    sno = 0
    for i, p in enumerate(players):
        if p.balls_faced <= 0 and not p.is_out and i != match.current_solo_bat_idx:
            continue
        sno += 1
        status = "*" if p.is_out else (" (batting)" if i == match.current_solo_bat_idx else "")
        name = html.escape(f"{p.first_name}{status}")
        bat_rows += (
            f"<tr><td align='center'>{sno}</td><td>{name}</td><td align='right'>{p.runs}</td>"
            f"<td align='right'>{p.balls_faced}</td><td align='right'>{p.get_strike_rate()}</td>"
            f"<td align='right'>{p.sixes}</td><td align='right'>{p.boundaries}</td></tr>"
        )
    if not bat_rows:
        bat_rows = "<tr><td colspan='7' align='center'>No batters yet</td></tr>"
    bat_table = (
        "<table bordered striped>"
        "<tr><th>#️⃣</th><th>🧢Name</th><th>🏏R</th><th>⚪B</th><th>⚡S.R</th><th>🚀6s</th><th>🔥4s</th></tr>"
        f"{bat_rows}</table>"
    )

    bowl_rows = ""
    sno = 0
    for i, p in enumerate(players):
        is_current_bowler = (i == getattr(match, "current_solo_bowl_idx", -1))
        if p.balls_bowled <= 0 and not is_current_bowler:
            continue
        sno += 1
        name = html.escape(p.first_name)
        if p.balls_bowled <= 0 and is_current_bowler:
            bowl_rows += (
                f"<tr><td align='center'>{sno}</td><td>{name}</td>"
                f"<td colspan='5' align='center'><i>Not yet bowling</i></td></tr>"
            )
            continue
        extras = getattr(p, "wides", 0) + getattr(p, "no_balls", 0)
        bowl_rows += (
            f"<tr><td align='center'>{sno}</td><td>{name}</td><td align='right'>{format_overs(p.balls_bowled)}</td>"
            f"<td align='right'>{p.runs_conceded}</td><td align='right'>{p.wickets}</td>"
            f"<td align='right'>{p.get_economy()}</td><td align='right'>{extras}</td></tr>"
        )
    if not bowl_rows:
        bowl_rows = "<tr><td colspan='7' align='center'>No bowling yet</td></tr>"
    bowl_table = (
        "<table bordered striped>"
        "<tr><th>#️⃣</th><th>🎯Name</th><th>⏱️Ovr</th><th>🏏Runs</th><th>🎳Wkt</th><th>💰Eco</th><th>➕Extra</th></tr>"
        f"{bowl_rows}</table>"
    )

    return (
        f"<h3>🏏 SOLO SCORECARD</h3>"
        f"<details><summary>🏏 Batting</summary>{bat_table}</details>"
        f"<details><summary>🎯 Bowling</summary>{bowl_table}</details>"
        f"<footer>📟 SOLO SCORECARD 🎮</footer>"
    )


def _build_solo_scorecard(match):
    """Build the standalone Solo Scorecard message: Batting table + Bowling
    table, with Refresh/Back buttons. Returns (text, InlineKeyboardMarkup)."""
    players = match.solo_players

    bat_header = f"{_solo_pad('#️⃣', 4)}{_solo_pad('🧢Name', 14)}{_solo_rpad('🏏R', 5)}{_solo_rpad('⚪B', 4)}{_solo_rpad('🔥4s', 5)}{_solo_rpad('🚀6s', 5)}{_solo_rpad('⚡S.R', 7)}\n"
    bat_table = bat_header + ("—" * 44) + "\n"
    sno = 0
    for i, p in enumerate(players):
        if p.balls_faced <= 0 and not p.is_out and i != match.current_solo_bat_idx:
            continue
        sno += 1
        status = ""
        if p.is_out:
            status = "*"
        elif i == match.current_solo_bat_idx:
            status = " (batting)"
        name = f"{p.first_name}{status}"
        bat_table += f"{_solo_pad(sno, 4)}{_solo_pad(name, 14)}{_solo_rpad(p.runs, 5)}{_solo_rpad(p.balls_faced, 4)}{_solo_rpad(p.boundaries, 5)}{_solo_rpad(p.sixes, 5)}{_solo_rpad(p.get_strike_rate(), 7)}\n"
    if sno == 0:
        bat_table += "  No batters yet\n"

    bowl_header = f"{_solo_pad('#️⃣', 4)}{_solo_pad('🎯Name', 14)}{_solo_rpad('⏱️Ovr', 6)}{_solo_rpad('🏏R', 5)}{_solo_rpad('🎳Wkt', 5)}{_solo_rpad('💰Eco', 6)}{_solo_rpad('➕Ext', 5)}\n"
    bowl_table = bowl_header + ("—" * 45) + "\n"
    any_bowled = False
    sno = 0
    for i, p in enumerate(players):
        is_current_bowler = (i == getattr(match, "current_solo_bowl_idx", -1))
        if p.balls_bowled <= 0 and not is_current_bowler:
            continue
        sno += 1
        any_bowled = True
        if p.balls_bowled <= 0 and is_current_bowler:
            bowl_table += f"{_solo_pad(sno, 4)}{_solo_pad(p.first_name, 14)}Not yet bowling\n"
            continue
        extras = getattr(p, "wides", 0) + getattr(p, "no_balls", 0)
        bowl_table += f"{_solo_pad(sno, 4)}{_solo_pad(p.first_name, 14)}{_solo_rpad(format_overs(p.balls_bowled), 6)}{_solo_rpad(p.runs_conceded, 5)}{_solo_rpad(p.wickets, 5)}{_solo_rpad(p.get_economy(), 6)}{_solo_rpad(extras, 5)}\n"
    if not any_bowled:
        bowl_table += "  No bowling yet\n"

    text = "🏏 <b>SOLO SCORECARD</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    text += "Batting\n"
    text += f"<blockquote expandable><pre>{bat_table}</pre></blockquote>"
    text += "Bowling\n"
    text += f"<blockquote expandable><pre>{bowl_table}</pre></blockquote>"
    text += "\n📟 SOLO SCORECARD 🎮"

    group_id = getattr(match, "group_id", None) or getattr(match, "chat_id", None)
    kb = InlineKeyboardMarkup([[
        styled_button("Refresh", callback_data=f"soloscore_refresh_{group_id}"),
        styled_button("◀ Back", callback_data=f"soloscore_back_{group_id}"),
    ]])
    return text, kb


async def soloscore_refresh_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Refresh button on the standalone Solo Scorecard message."""
    query = update.callback_query
    await query.answer()
    try:
        group_id = int(query.data[len("soloscore_refresh_"):])
    except ValueError:
        return
    match = active_matches.get(group_id)
    if not match:
        await query.answer("Match ended!", show_alert=True)
        return
    text, kb = _build_solo_scorecard(match)
    try:
        await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as e:
        # The message being refreshed may be a native rich card (sendRichMessage),
        # which can't be edited through the normal editMessageText call — send an
        # updated rich card instead so Refresh still works from that message.
        logger.info(f"soloscore_refresh_callback plain edit failed ({e}), sending fresh rich card")
        try:
            html_solo = _build_solo_scorecard_html(match)
            ok = await _tg_send_rich_message(group_id, html_solo, reply_markup=kb)
            if not ok:
                await context.bot.send_message(group_id, text, parse_mode=ParseMode.HTML, reply_markup=kb)
        except Exception as e2:
            logger.error(f"soloscore_refresh_callback fallback send error: {e2}")


async def soloscore_back_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Back button on the standalone Solo Scorecard message — show the solo leaderboard."""
    query = update.callback_query
    await query.answer()
    try:
        group_id = int(query.data[len("soloscore_back_"):])
    except ValueError:
        return
    match = active_matches.get(group_id)
    if not match:
        await query.answer("Match ended!", show_alert=True)
        return

    sorted_players = sorted(match.solo_players, key=lambda x: x.runs, reverse=True)
    msg = "🏆 <b>SOLO BATTLE LEADERBOARD</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
    for i, p in enumerate(sorted_players, 1):
        rank = f"<b>{i}.</b>"
        # 🩹 BUGFIX: same rank-vs-original-index mixup as soloscore_command —
        # compare by player identity, not by position in the runs-sorted list.
        status = ""
        if p.is_out: status = " (out)"
        elif p is (match.solo_players[match.current_solo_bat_idx] if match.current_solo_bat_idx < len(match.solo_players) else None): status = " (batting)"
        elif p is (match.solo_players[match.current_solo_bowl_idx] if match.current_solo_bowl_idx < len(match.solo_players) else None): status = " (bowling)"
        sr = round((p.runs / max(p.balls_faced, 1)) * 100, 1)
        msg += f"{rank} <b>{html.escape(p.first_name)}</b>{status}\n"
        msg += f"   {p.runs} runs ({p.balls_faced} balls)  SR: {sr}\n\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"

    kb = InlineKeyboardMarkup([[styled_button("Table", callback_data=f"soloscore_refresh_{group_id}")]])
    try:
        await query.edit_message_text(msg, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as e:
        # Original message may be a native rich card that can't be edited via
        # editMessageText — send the leaderboard as a fresh message instead.
        logger.info(f"soloscore_back_callback plain edit failed ({e}), sending fresh message")
        try:
            await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML, reply_markup=kb)
        except Exception as e2:
            logger.error(f"soloscore_back_callback fallback send error: {e2}")


async def scorecard_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏏 Enhanced scorecard — auto-detects Team/Solo mode"""
    group_id = update.effective_chat.id
    match = active_matches.get(group_id)

    if not match:
        await update.message.reply_text("🏏 No active match! Use /game to begin")
        return

    # ── SOLO MODE: standalone Batting/Bowling table scorecard ──
    if getattr(match, 'game_mode', None) in ["SOLO", "MAGICBALL"] or match.phase in [GamePhase.SOLO_JOINING, GamePhase.SOLO_MATCH]:
        text, kb = _build_solo_scorecard(match)
        try:
            html_solo = _build_solo_scorecard_html(match)
            # Attach Refresh/Back buttons directly to the rich card itself,
            # so they sit right below the scorecard instead of arriving as a
            # separate message.
            ok = await _tg_send_rich_message(group_id, html_solo, reply_markup=kb)
        except Exception as solo_rt_e:
            logger.warning(f"Solo scorecard rich table error: {solo_rt_e}")
            ok = False
        if not ok:
            # Fallback: plain-text scorecard (already has expandable batting/
            # bowling blockquotes) with the same Refresh/Back buttons attached.
            await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
        return

    # ── Image cooldown check ──
    if update.effective_chat.type != "private":
        remaining = check_image_cooldown(group_id)
        if remaining is not None:
            await send_cooldown_warning(update, remaining)
            return
        # ── Full scorecard 2-minute cooldown ──
        sc_remaining = check_scorecard_cooldown(group_id)
        if sc_remaining is not None:
            secs = math.ceil(sc_remaining)
            mins = secs // 60
            sec_part = secs % 60
            warn_msg = await update.message.reply_text(
                f"⏳ <b>Scorecard Cooldown</b>\n"
                f"Wait <b>{mins}m {sec_part}s</b> before using /scorecard again.\n"
                f"<i>Cooldown prevents spam (2 min per group).</i>",
                parse_mode=ParseMode.HTML
            )
            asyncio.get_event_loop().call_later(
                sc_remaining + 1,
                lambda: asyncio.ensure_future(warn_msg.delete())
            )
            return
        set_scorecard_cooldown(group_id)

    # ── New-style (TEAM-X/TEAM-Y, per-player drop-down) scorecard — capped
    # at MAX_NEW_SCORECARD_USES manual uses per match ──
    used = NEW_SCORECARD_USE_COUNT.get(group_id, 0)
    if used >= MAX_NEW_SCORECARD_USES:
        await update.message.reply_text(
            f"⚠️ Scorecard limit reached — used {used}/{MAX_NEW_SCORECARD_USES} times this match."
        )
    else:
        NEW_SCORECARD_USE_COUNT[group_id] = used + 1
        try:
            await send_new_scorecard(update.message, group_id, match)
        except Exception as nsc_e:
            logger.error(f"New-style scorecard error: {nsc_e}")

    # NOTE: /scorecard now sends exactly ONE message — the new-style table
    # scorecard above. It used to also auto-send a worm-graph photo here,
    # which is why the card visually appeared "twice". The worm graph is
    # still available on demand via its own refresh/worm button
    # (scorecard_worm_callback) instead of being force-sent every time.

# 🆕 UNIVERSAL 10-min inactivity auto-end (per user's request): every phase
# is now covered, not just ball-by-ball play. Lobby/setup phases (host
# selection, over selection, toss, fantasy pick, captain selection, team
# edit, team joining) still have their OWN dedicated quick timers — those
# keep working exactly as before. This universal watchdog is an ADDITIONAL
# safety net so a match can never get stuck in ANY phase for 10+ min with
# zero player activity (button taps, joins, ball input, /add etc.) — a
# global "touch" handler (see touch_activity_on_any_update, registered in
# handler group -1) refreshes match.last_activity on every incoming update
# for a chat that has an active match, in EVERY phase, so this check is
# now safe to apply blanket-wide.
_BALL_PHASES_FOR_TIMEOUT = {p for p in GamePhase if p != GamePhase.MATCH_ENDED}


def _touch_match_activity(match) -> None:
    """Refresh a match's last-activity timestamp AND clear any inactivity
    warning flags, so a fresh burst of activity after a reminder resets the
    whole timeout cycle instead of instantly re-firing."""
    match.last_activity = time.time()
    for _flag in ("_inactivity_warn2_sent", "_inactivity_warn4_sent", "_inactivity_warn6_sent",
                  "_inactivity_warn8_sent", "_inactivity_warn9h_sent"):
        setattr(match, _flag, False)


async def touch_activity_on_any_update(update: "Update", context: ContextTypes.DEFAULT_TYPE) -> None:
    """🆕 Global activity pulse (per user's request: auto-end after 10 min
    idle no matter which phase the match is in, mid-game join included).

    Registered in handler group -1 (runs FIRST, alongside every other
    handler — it never blocks/consumes the update) for both messages and
    callback queries. Any incoming update in a chat that currently has an
    active match — a button tap, a join, a ball number, an /add, literally
    anything — refreshes that match's last_activity and clears the
    reminder flags, so cleanup_inactive_matches' universal 10-min watchdog
    only fires when a match has TRULY had zero player action for 10 min,
    regardless of phase."""
    try:
        chat = update.effective_chat
        if not chat:
            return
        match = active_matches.get(chat.id)
        if match is None or getattr(match, "phase", None) == GamePhase.MATCH_ENDED:
            return
        _touch_match_activity(match)
    except Exception as e:
        logger.error(f"touch_activity_on_any_update error: {e}")


def _host_tag_for_match(match) -> str:
    """Best-effort clickable tag for the match host, for inactivity nudges."""
    host_id = getattr(match, "host_id", None)
    host_name = getattr(match, "host_name", None) or "Host"
    if not host_id:
        return html.escape(host_name)
    return f'<a href="tg://user?id={host_id}">{html.escape(host_name)}</a>' + _title_suffix(host_id)
async def cleanup_inactive_matches(context: ContextTypes.DEFAULT_TYPE):
    """
    UNIVERSAL inactivity watchdog — now covers EVERY match phase (lobby/
    setup phases still have their own faster dedicated timers running in
    parallel; this is the guaranteed outer safety net). Runs every 60s and,
    per match:
      • at 2/4/6/8 min idle    — reminder ping (progress so far)
      • at 9 min 30s idle      — final warning, ~30s left
      • at 10 min idle         — auto-end the match, save a 12h /regame snapshot,
                                 and announce the auto-end
    "Idle" means zero activity of ANY kind in that chat for a match still in
    progress — any button tap, join, ball input, or command touches
    match.last_activity (see touch_activity_on_any_update), regardless of
    which phase the match is currently in.
    """
    current_time = time.time()
    end_threshold = 10 * 60
    warn_thresholds = [
        (5 * 60, "_inactivity_warn2_sent", "5 minutes"),
        (8 * 60, "_inactivity_warn4_sent", "8 minutes"),
        (9 * 60, "_inactivity_warn6_sent", "9 minutes"),
        (9 * 60 + 30, "_inactivity_warn9h_sent", "9 minutes 30 seconds"),
    ]
    chats_to_remove = []

    for chat_id, match in active_matches.items():
        # Skip only fully-ended matches — every other phase is now covered
        # by this universal watchdog (see _BALL_PHASES_FOR_TIMEOUT above).
        if match.phase not in _BALL_PHASES_FOR_TIMEOUT:
            continue
        if not hasattr(match, "last_activity"):
            match.last_activity = time.time()
            continue

        idle_for = current_time - match.last_activity
        host_tag = _host_tag_for_match(match)

        if idle_for >= end_threshold:
            chats_to_remove.append(chat_id)
            try:
                # 💾 Save a resumable snapshot (same 12h /regame system as a
                # manual /endmatch) before we tear the match down, since this
                # is a mid-game force-stop with no result declared.
                resume_code = save_match_for_resume(match, chat_id, match.group_name, match.host_id)
                extra = f"\n🔑 Resume within 12h: <code>/regame {resume_code}</code>" if resume_code else ""
                await context.bot.send_message(
                    chat_id=chat_id,
                    text=(
                        f"⏰ <b>AUTO END DUE TO INACTIVITY!</b>\n"
                        f"{host_tag}, the match was ended after 10 minutes with no response.{extra}"
                    ),
                    parse_mode=ParseMode.HTML
                )
                if match.main_message_id:
                    await context.bot.unpin_chat_message(chat_id=chat_id, message_id=match.main_message_id)
            except Exception as e:
                logger.error(f"Error ending inactive match {chat_id}: {e}")
            continue

        # 🔔 Fire whichever reminder threshold we've newly crossed, highest first
        for threshold, flag_name, label in reversed(warn_thresholds):
            if idle_for >= threshold and not getattr(match, flag_name, False):
                setattr(match, flag_name, True)
                remaining = end_threshold - threshold
                remaining_label = "30 seconds" if remaining <= 30 else f"~{remaining // 60} min"
                try:
                    await context.bot.send_message(
                        chat_id=chat_id,
                        text=(
                            f"⏳ {host_tag}, inactivity detected! No one has played for {label} — "
                            f"play a ball soon or the match will auto-end in {remaining_label}."
                        ),
                        parse_mode=ParseMode.HTML
                    )
                except Exception as e:
                    logger.error(f"Error sending {label} inactivity warning for {chat_id}: {e}")
                break

    # 🔧 GLITCH FIX: do a FULL cleanup (cancel lingering tasks + clear
    # per-group locks) instead of a blunt dict delete — otherwise stale
    # tasks/locks from the killed match could linger and make the very
    # next /game behave as if an old match were still around.
    for chat_id in chats_to_remove:
        match = active_matches.get(chat_id)
        if match is None:
            continue
        for task_attr in (
            'ball_timeout_task', 'batsman_selection_task', 'bowler_selection_task',
            'join_phase_task', 'solo_timer_task', 'pause_task', 'active_ball_task',
        ):
            task = getattr(match, task_attr, None)
            if task:
                try:
                    task.cancel()
                except Exception:
                    pass
        active_matches.pop(chat_id, None)
        processing_commands.pop(chat_id, None)

def bump_ball_seq(match) -> int:
    """Same anti-duplicate-timer protection as bump_solo_ball_seq, but for
    TEAM mode's game_timer. Without this, a cancelled-and-recreated
    ball_timeout_task can still race and fire its own "HURRY UP!" warning
    into an already-resolved ball, producing the duplicate warning bug."""
    match.ball_seq = getattr(match, 'ball_seq', 0) + 1
    return match.ball_seq


async def game_timer(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, player_type: str, player_name: str, seq: int = None):
    """Handles 40s timer with Penalties & Disqualification"""
    if seq is None:
        seq = getattr(match, 'ball_seq', 0)
    try:
        # Wait 25 seconds
        await asyncio.sleep(25)

        # 🔧 GLITCH FIX: if the ball already moved on (new timer started,
        # player answered, over/innings changed) while we were sleeping,
        # this timer is stale — abort instead of sending a duplicate
        # "HURRY UP!" warning into an already-resolved ball.
        if getattr(match, 'ball_seq', None) != seq or is_match_stale(group_id, match):
            logger.info("⛔ game_timer aborted (25s mark) — stale timer, ball already resolved.")
            return

        # Warning
        await context.bot.send_message(group_id, f"<b>⏳ HURRY UP!</b> {html.escape(player_name)}, only 15s left!", parse_mode=ParseMode.HTML)
        
        # Wait remaining 15 seconds
        await asyncio.sleep(15)

        # 🔧 GLITCH FIX: same stale check right before acting on timeout.
        if getattr(match, 'ball_seq', None) != seq or is_match_stale(group_id, match):
            logger.info("⛔ game_timer aborted (timeout mark) — stale timer, ball already resolved.")
            return
        
        # --- TIMEOUT HAPPENED ---
        await handle_timeout_penalties(context, group_id, match, player_type)
            
    except asyncio.CancelledError:
        pass # Timer stopped safely because player played

async def handle_timeout_penalties(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, player_type: str):
    """Process Penalties for Timeouts"""
    bat_team = match.current_batting_team
    bowl_team = match.current_bowling_team
    
    # --- BOWLER TIMEOUT ---
    if player_type == "bowler":
        bowler = bowl_team.players[bowl_team.current_bowler_idx]
        bowler.bowling_timeouts += 1
        
        # Case A: Disqualification (2 Timeouts) — the over is NOT restarted.
        # Whatever balls were already bowled in this over stay bowled; the
        # captain appoints a new bowler who bowls only the remaining balls
        # of this same over.
        if bowler.bowling_timeouts >= 2:
            current_over_balls = bat_team.get_current_over_balls()
            remaining_balls = 6 - current_over_balls
            msg = f"🚫 <b>DISQUALIFIED!</b> {bowler.first_name} timed out 2 times!\n"
            msg += (
                f"⛔ <b>Banned from bowling for the rest of this match.</b>\n"
                f"⚠️ <b>Over continues — {remaining_balls} ball(s) left this over.</b> "
                f"Captain, appoint a new bowler for the rest of the over."
            )
            await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)

            # 🚫 Bowling-timeout ban tracking: mark this player as having failed to
            # bowl in this match (continuous streak), and apply/escalate a ban if due.
            try:
                match._bowling_timeout_offenders = getattr(match, '_bowling_timeout_offenders', set())
                match._bowling_timeout_offenders.add(bowler.user_id)
                ban_result = record_bowling_timeout_strike(bowler.user_id)
                if ban_result:
                    await _dm_bowling_ban_notice(
                        context, bowler.user_id,
                        ban_result["strike_count"], ban_result["ban_until"], ban_result["duration"]
                    )
            except Exception as e:
                logger.error(f"bowling-timeout strike tracking failed: {e}")

            # ✅ FIX: do NOT reset bat_team.balls / overs — the over's ball
            # progress (however many legal balls were already bowled) is kept
            # exactly as-is. The next bowler simply continues from here and
            # will only face the remaining balls of this over.

            # Remove bowler from attack
            bowl_team.current_bowler_idx = None

            # 🩹 FIX: this used to reset is_bowling_banned back to False right
            # after disqualifying the bowler, which silently undid the ban —
            # the player would be offered again as an "available" bowler in a
            # later over (get_available_bowlers only checks is_bowling_banned).
            # 2 bowler-timeouts now bans them from bowling for the REST of
            # this match, same rule as solo mode.
            match.current_ball_data = {} # Clear ball data
            bowler.is_bowling_banned = True  # ✅ Banned for the rest of THIS match
            await request_bowler_selection(context, group_id, match)
            return

        # Case B: No Ball (Standard Timeout)
        else:
            bat_team.score += 1 # Penalty Run
            bat_team.extras += 1
            match.is_free_hit = True # Activate Free Hit
            
            msg = themed(
                "BOWLER TIMEOUT",
                [
                    f"⏱ Count: <b>{bowler.bowling_timeouts}/2</b>",
                    "🚫 Result: No Ball · +1 run.",
                    "⚡ Next ball is a Free Hit.",
                ],
                "⏰"
            )

            await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
            
            # Reset inputs to allow re-bowl (No ball doesn't count legal ball)
            match.current_ball_data = {}

            # Re-send the bowling prompt to group (Bug 2 fix: always show bowling message after every delivery)
            # and retry DM to bowler; timer is restarted inside execute_ball (Bug 3 fix: timer keeps running)
            await execute_ball(context, group_id, match)

    # --- BATSMAN TIMEOUT ---
    elif player_type == "batsman":
        striker = bat_team.players[bat_team.current_batsman_idx]
        striker.batting_timeouts += 1
        
        # Case A: Hit Wicket (3 Timeouts)
        if striker.batting_timeouts >= 2:
            msg = f"🚫 <b>DISMISSED!</b> {striker.first_name} timed out 2 times.\n"
            msg += "❌ <b>Result:</b> HIT WICKET (OUT)!"
            await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
            
            # Trigger Wicket Logic Manually
            match.current_ball_data["batsman_number"] = match.current_ball_data["bowler_number"] # Force match numbers to trigger out
            await process_ball_result(context, group_id, match)
            
        # Case B: Penalty Runs (-6 Runs)
        else:
            bat_team.score -= 6
            bat_team.score = max(0, bat_team.score) # Score negative nahi jayega
            # Update current_over_runs for graph accuracy
            match.current_over_runs = max(0, getattr(match, 'current_over_runs', 0) - 6)
            
            msg = "⏰ <b>BATSMAN TIMEOUT!</b>\n"
            msg += "<blockquote>"
            msg += f"⏱ Count: {striker.batting_timeouts}/2\n"
            msg += "📉 Penalty: -6 Runs!\n"
            msg += f"📊 Score: {bat_team.score}/{bat_team.wickets}"
            msg += "</blockquote>"

            await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
            
            # Count ball but no runs (Treat as Dot Ball)
            bat_team.balls += 1
            bat_team.update_overs()
            match.current_ball_data = {} # Reset
            
            if bat_team.get_current_over_balls() == 0:
                await check_over_complete(context, group_id, match)
            else:
                await execute_ball(context, group_id, match)

