def bump_solo_ball_seq(match) -> int:
    """
    🔧 GLITCH FIX: advance solo-ball sequence counter, return new value.
    Root cause of the "2 games running, one accepts no numbers" bug: the
    45s timeout timer and a real user's number-submission can both fire for
    the SAME ball in a tiny race window. When that happens, two parallel
    "send your number" flows get created against the same match — one is a
    ghost. Every time a ball's waiting-period starts OR is resolved by real
    input, we bump this counter and stamp the timer task with it; if the
    timer wakes up later and the counter has moved on, it knows a newer ball
    already started and it aborts instead of firing a duplicate flow.
    """
    match.solo_ball_seq = getattr(match, 'solo_ball_seq', 0) + 1
    return match.solo_ball_seq


def is_match_stale(chat_id, match) -> bool:
    """
    🔧 GLITCH FIX: True if this `match` object is no longer the live match for
    chat_id — either it already ended, or a newer match has replaced it in
    active_matches. Old code only checked `chat_id not in active_matches`,
    which is true-negative when a NEW match has taken over the same chat_id,
    letting a dead match's leftover timers/tasks keep sending messages
    ("phantom second game" bug).
    """
    return match.phase == GamePhase.MATCH_ENDED or active_matches.get(chat_id) is not match


async def solo_game_timer(context, chat_id, match, player_type, player_name, seq=None):
    """Timer specifically for Solo Mode (40s)"""
    if seq is None:
        seq = getattr(match, 'solo_ball_seq', 0)
    try:
        # Wait 25 seconds
        await asyncio.sleep(25)

        # 🔧 GLITCH FIX: if the real player already answered (or the ball
        # moved on some other way) while we were sleeping, our seq is stale
        # — abort instead of sending a duplicate "hurry up" into a resolved ball.
        if getattr(match, 'solo_ball_seq', None) != seq:
            logger.info("⛔ solo_game_timer aborted (25s mark) — stale timer, ball already resolved.")
            return
        try:
            await context.bot.send_message(
                chat_id, 
                f"⏳ <b>Hurry Up {player_name}!</b>\n<blockquote>⚠️ Only 15 seconds left → play your ball!</blockquote>", 
                parse_mode=ParseMode.HTML
            )
        except: pass
        
        # Remaining 15 Seconds
        await asyncio.sleep(15)
        
        # 🔧 GLITCH FIX: same stale check right before acting on timeout —
        # this is the exact race window users hit (number submitted at ~44-45s).
        if getattr(match, 'solo_ball_seq', None) != seq:
            logger.info("⛔ solo_game_timer aborted (timeout mark) — stale timer, ball already resolved.")
            return

        # Timeout Trigger
        await handle_solo_timeout(context, chat_id, match, player_type)
            
    except asyncio.CancelledError:
        pass

async def handle_solo_timeout(context, chat_id, match, player_type):
    """Handle Penalties for Solo Mode Timeouts"""
    # 🔧 GLITCH FIX: match may have been ended via /endmatch during the 45s wait.
    if is_match_stale(chat_id, match):
        logger.info("⛔ handle_solo_timeout aborted — match already ended.")
        return
    
    # --- BATSMAN TIMEOUT ---
    if player_type == "batsman":
        batter = match.solo_players[match.current_solo_bat_idx]
        batter.batting_timeouts += 1
        
        # 3 Timeouts = AUTO OUT
        if batter.batting_timeouts >= 2:
            msg = f"🚫 <b>AUTO-OUT!</b> {batter.first_name} timed out 3 times.\n❌ <b>Result:</b> Wicket!"
            await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
            
            # Simulate Wicket Logic
            match.current_ball_data["batsman_number"] = match.current_ball_data["bowler_number"]
            await process_solo_turn_result(context, chat_id, match)
            return

        # < 3 Timeouts = warning only — no run penalty
        # 🩹 CHANGE (per request): batsman's runs are never deducted anymore
        # in solo mode. Timeout still counts towards the auto-out at 2/2,
        # it just no longer costs runs along the way.
        else:
            msg = "⏰ <b>TIMEOUT WARNING!</b>\n"
            msg += "<blockquote>"
            msg += f"⏱ Count: {batter.batting_timeouts}/2\n"
            msg += f"📊 Current Score: {batter.runs}"
            msg += "</blockquote>"
            await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
            
            batter.balls_faced += 1
            await rotate_solo_bowler(context, chat_id, match)

    # --- BOWLER TIMEOUT ---
    elif player_type == "bowler":
        bowler = match.solo_players[match.current_solo_bowl_idx]
        batter = match.solo_players[match.current_solo_bat_idx]
        bowler.bowling_timeouts += 1
        
        # 2 Timeouts = BANNED from bowling for the REST of this solo game
        if bowler.bowling_timeouts >= 2:
            msg = "🚫 <b>BOWLER BANNED</b>\n"
            msg += f"{html.escape(bowler.first_name)}: 2 bowling timeouts reached.\n"
            msg += "Banned from bowling for the rest of this match."
            await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)

            bowler.is_bowling_banned = True  # ✅ Banned for THIS solo game only

            # 🚫 Also record a strike/penalty against the player (same system
            # used for team/real-cricket bowling-timeout offenders).
            try:
                ban_result = record_bowling_timeout_strike(bowler.user_id)
                if ban_result:
                    await _dm_bowling_ban_notice(
                        context, bowler.user_id,
                        ban_result["strike_count"], ban_result["ban_until"], ban_result["duration"]
                    )
            except Exception as e:
                logger.error(f"solo bowling-timeout strike tracking failed: {e}")

            await rotate_solo_bowler(context, chat_id, match, force_new_bowler=True)
            return
            
        # < 3 Timeouts = NO BALL + FREE HIT
        else:
            batter.runs += 1
            match.is_free_hit = True
            
            msg = "⏰ <b>BOWLER TIMEOUT!</b>\n"
            msg += "<blockquote>"
            msg += f"⏱ Count: {bowler.bowling_timeouts}/2\n"
            msg += "🚫 Result: DEAD BALL! (+1 Run)\n"
            msg += "⚡ Next ball is a NORMAL BALL!\n"
            msg += "🔄 Bowler must bowl again!"
            msg += "</blockquote>"
            await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
            
            match.ball_timeout_task = asyncio.create_task(
                solo_game_timer(context, chat_id, match, "bowler", bowler.first_name, seq=bump_solo_ball_seq(match))
            )

# Helper to Rotate Bowler in Solo (Handles the Skip Logic)
async def rotate_solo_bowler(context, chat_id, match, force_new_bowler=False):
    """Rotates bowler, skipping banned players"""
    # 🔧 GLITCH FIX: if /endmatch or /endall already ended this match, stop here.
    if is_match_stale(chat_id, match):
        logger.info("⛔ rotate_solo_bowler aborted — match already ended.")
        return
    
    if not force_new_bowler:
        match.solo_balls_this_spell += 1

    if match.solo_balls_this_spell >= 3 or force_new_bowler:
        match.solo_balls_this_spell = 0
        
        original_idx = match.current_solo_bowl_idx
        attempts = 0
        total_players = len(match.solo_players)
        
        while True:
            match.current_solo_bowl_idx = (match.current_solo_bowl_idx + 1) % total_players
            
            if match.current_solo_bowl_idx == match.current_solo_bat_idx:
                match.current_solo_bowl_idx = (match.current_solo_bowl_idx + 1) % total_players
                
            next_bowler = match.solo_players[match.current_solo_bowl_idx]
            
            if not next_bowler.is_bowling_banned:
                break
            
            attempts += 1
            if attempts > total_players:
                await context.bot.send_message(
                    chat_id,
                    "🚫 <b>NO ELIGIBLE BOWLER LEFT!</b>\n"
                    "⏰ Match auto-ended — the remaining player(s) are banned from bowling "
                    "(2 timeouts) and no one else is available to bowl.",
                    parse_mode=ParseMode.HTML
                )
                await end_solo_game_logic(context, chat_id, match)
                return

        new_bowler = match.solo_players[match.current_solo_bowl_idx]
        await context.bot.send_message(chat_id, f"🔄 <b>New Bowler!</b>\n<blockquote>⚾ {new_bowler.first_name} comes into the attack.</blockquote>", parse_mode=ParseMode.HTML)

    await trigger_solo_ball(context, chat_id, match)

async def check_user_started_bot(bot, user_id: int) -> bool:
    """
    Check if a user has started the bot by attempting to send them a
    chat action. Returns True if reachable, False if Forbidden (bot not started).
    """
    try:
        await bot.send_chat_action(user_id, "typing")
        return True
    except Forbidden:
        return False
    except Exception:
        # Other errors (network, etc.) — assume reachable to avoid false negatives
        return True


# Start command handler
async def start_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Welcome message with Add to Group button"""

    # ── Handle "Deliver Bowl" deep link: ?start=bowl_{group_id} ──
    if context.args and context.args[0].startswith('bowl_'):
        try:
            group_id = int(context.args[0].split('_')[1])
            user = update.effective_user

            match = active_matches.get(group_id)
            # Support both TEAM (MATCH_IN_PROGRESS) and SOLO (SOLO_MATCH) phases
            if not match or match.phase not in (GamePhase.MATCH_IN_PROGRESS, GamePhase.SOLO_MATCH):
                await update.message.reply_text(
                    "⚠️ <b>No active match found!</b>\n"
                    "<i>The match may have ended or not started yet.</i>",
                    parse_mode=ParseMode.HTML
                )
                return

            # ── Build group redirect button ──
            try:
                _cid_str = str(abs(group_id))
                _tme_gid = _cid_str[3:] if _cid_str.startswith("100") else _cid_str
                _game_url = f"https://t.me/c/{_tme_gid}/{match.main_message_id or 1}"
                _go_group_markup = InlineKeyboardMarkup([[
                    styled_button("Go to Game", url=_game_url)
                ]])
            except Exception:
                _go_group_markup = None

            # ── SOLO MODE ──
            if match.phase == GamePhase.SOLO_MATCH:
                if match.current_solo_bowl_idx < len(match.solo_players):
                    bowler = match.solo_players[match.current_solo_bowl_idx]
                    if bowler.user_id == user.id:
                        if match.current_ball_data.get("bowler_number") is not None:
                            await update.message.reply_text(
                                "✅ <b>You've already bowled this ball!</b>\n"
                                "<i>Wait for the batsman to play their shot.</i>",
                                parse_mode=ParseMode.HTML,
                                reply_markup=_go_group_markup
                            )
                            return
                        batter = match.solo_players[match.current_solo_bat_idx] if match.current_solo_bat_idx < len(match.solo_players) else None
                        if batter:
                            sr = round((batter.runs / max(batter.balls_faced, 1)) * 100, 1)
                            dm_text = themed(
                                "YOUR TURN TO BOWL",
                                [
                                    f"🏏 Batsman: <b>{html.escape(batter.first_name)}</b> — {batter.runs}({batter.balls_faced}) • SR {sr}",
                                    "📩 Send a number (0–6) to bowl.",
                                    "⏱ Your timer is running.",
                                ],
                                "⚔️",
                            )
                        else:
                            dm_text = themed(
                                "YOUR TURN TO BOWL",
                                ["📩 Send a number (0–6) to bowl.", "⏱ Your timer is running."],
                                "⚔️",
                            )
                        await update.message.reply_text(dm_text, parse_mode=ParseMode.HTML, reply_markup=_go_group_markup)
                        return
                    else:
                        await update.message.reply_text(
                            "⚠️ <b>You are not the current bowler!</b>",
                            parse_mode=ParseMode.HTML,
                            reply_markup=_go_group_markup
                        )
                        return
                return

            # ── TEAM MODE ──
            bowl_team = match.current_bowling_team
            if bowl_team and bowl_team.current_bowler_idx is not None:
                bowler = bowl_team.players[bowl_team.current_bowler_idx]
                if bowler.user_id == user.id:
                    # Player is the current bowler → send them the bowl prompt
                    if match.current_ball_data.get("bowler_number") is not None:
                        await update.message.reply_text(
                            "✅ <b>You've already bowled this ball!</b>\n"
                            "<i>Wait for the batsman to play their shot.</i>",
                            parse_mode=ParseMode.HTML,
                            reply_markup=_go_group_markup
                        )
                        return

                    bat_team = match.current_batting_team
                    striker = bat_team.players[bat_team.current_batsman_idx] if bat_team.current_batsman_idx is not None else None

                    bowl_lines = []
                    if striker:
                        bowl_lines.append(f"🏏 Batsman: <b>{html.escape(striker.first_name)}</b> — {striker.runs}/{striker.balls_faced}")
                    bowl_lines.append(f"📊 Score: <b>{bat_team.score}/{bat_team.wickets}</b> • {format_overs(bat_team.balls)} ov")
                    if match.innings == 2:
                        runs_needed = match.target - bat_team.score
                        balls_left = (match.total_overs * 6) - bat_team.balls
                        bowl_lines.append(f"🎯 Defend: <b>{runs_needed} runs</b> in <b>{balls_left} balls</b>")
                    if match.is_free_hit:
                        bowl_lines.append("⚡ Free hit — the batsman cannot be dismissed.")
                    bowl_lines.extend(["📩 Send a number (0–6) to bowl.", "⏱ Your timer is running."])
                    dm_text = themed("YOUR TURN TO BOWL", bowl_lines, "⚾")

                    await update.message.reply_text(dm_text, parse_mode=ParseMode.HTML, reply_markup=_go_group_markup)
                    return
                else:
                    await update.message.reply_text(
                        "⚠️ <b>You are not the current bowler!</b>",
                        parse_mode=ParseMode.HTML,
                        reply_markup=_go_group_markup
                    )
                    return
            else:
                await update.message.reply_text(
                    "⚠️ <b>No bowler is set right now.</b>\n<i>Please wait for the over to start.</i>",
                    parse_mode=ParseMode.HTML,
                    reply_markup=_go_group_markup
                )
                return
        except Exception as e:
            logger.error(f"bowl deep link error: {e}")
            # Fall through to normal start

    # Check for registration deep link
    if context.args and context.args[0].startswith('reg_'):
        try:
            parts = context.args[0].split('_')
            group_id = int(parts[1])
            base_price = int(parts[2])
            
            user_id = update.effective_user.id
            username = update.effective_user.username or 'NoUsername'
            full_name = update.effective_user.full_name
            
            # ✅ FIX 6: Check if registration is still active (link expiry)
            is_active = False
            if group_id in REGISTRATION_ACTIVE:
                end_dt = REGISTRATION_ACTIVE[group_id].get('end_date')
                if end_dt and end_dt > datetime.now():
                    is_active = True
            
            if not is_active:
                # Check DB — must be is_active=1 AND end_date in future
                conn_check= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
                c_check = conn_check.cursor()
                c_check.execute(
                    "SELECT is_active, end_date FROM registration_periods WHERE group_id = ? AND is_active = 1",
                    (group_id,)
                )
                row = c_check.fetchone()
                conn_check.close()
                if row:
                    try:
                        end_dt_db = datetime.fromisoformat(row[1])
                        if end_dt_db > datetime.now():
                            is_active = True
                    except Exception:
                        pass
            
            if not is_active:
                await update.message.reply_text(
                    themed(
                        "REGISTRATION CLOSED",
                        ["This registration link has expired.", "<i>Contact your group admin for more info.</i>"],
                        "⏰",
                    ),
                    parse_mode=ParseMode.HTML
                )
                return
            
            # Check if already registered
            conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
            c = conn.cursor()
            c.execute('SELECT user_id FROM registered_players WHERE user_id = ? AND group_id = ?', (user_id, group_id))
            if c.fetchone():
                conn.close()
                await update.message.reply_text(
                    themed(
                        "ALREADY REGISTERED",
                        ["You are already registered for this tournament.", "<i>Good luck, champion! 🏏</i>"],
                        "✅",
                    ),
                    parse_mode=ParseMode.HTML
                )
                return
            
            # Register the player — pending until a tour organiser approves it
            c.execute(
                'INSERT INTO registered_players (group_id, user_id, username, full_name, base_price, registered_at, status) VALUES (?, ?, ?, ?, ?, ?, ?)',
                (group_id, user_id, username, full_name, base_price, datetime.now(), 'pending')
            )
            conn.commit()
            conn.close()
            
            # Get tournament name
            tour_name = REGISTRATION_ACTIVE.get(group_id, {}).get('tournament_name', 'Tournament')
            
            # Send confirmation to user
            await update.message.reply_photo(
                photo=REGISTRATION_OPEN_PHOTO,
                caption=(
                    f"⏳ <b>REGISTRATION SUBMITTED!</b>\n"
                    f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                    f"🏆 <b>Tournament:</b> {tour_name}\n"
                    f"👤 <b>Name:</b> {full_name}\n"
                    f"🔖 <b>Username:</b> @{username}\n"
                    f"💰 <b>Base Price:</b> {base_price} 🔷\n"
                    f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                    f"🕒 <i>Waiting for the tour organiser to confirm your request.</i>"
                ),
                parse_mode=ParseMode.HTML
            )
            
            # Notify in group with Approve/Reject buttons for tour organisers
            approval_kb = InlineKeyboardMarkup([
                [
                    styled_button("✅ Approve", callback_data=f"regapp_{group_id}_{user_id}"),
                    styled_button("❌ Reject", callback_data=f"regrej_{group_id}_{user_id}")
                ]
            ])
            try:
                await context.bot.send_photo(
                    chat_id=group_id,
                    photo=PLAYER_REGISTERED_PHOTO,
                    caption=(
                        f"🆕 <b>REGISTRATION REQUEST</b>\n"
                        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                        f"👤 <b>{full_name}</b>\n"
                        f"🔖 @{username}\n"
                        f"💰 <b>Base Price:</b> {base_price} 🔷\n"
                        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                        f"🕒 Awaiting tour organiser approval — <b>{tour_name}</b>"
                    ),
                    parse_mode=ParseMode.HTML,
                    reply_markup=approval_kb
                )
            except Exception:
                pass
            
            return
        except Exception as e:
            logger.error(f"Registration link error: {e}")
            await update.message.reply_text(
                "❌ <b>Registration Failed!</b>\n"
                "Invalid link or an error occurred. Please try again or contact your group admin.",
                parse_mode=ParseMode.HTML
            )
            return

    user = update.effective_user
    chat = update.effective_chat
    
    is_new_user = False
    
    if user.id not in user_data:
        user_data[user.id] = {
            "user_id": user.id,
            "username": user.username or "",
            "first_name": user.first_name,
            "started_at": datetime.now().isoformat(),
            "total_matches": 0
        }
        init_player_stats(user.id)
        save_data()
        is_new_user = True

    # Notify support group any time someone starts the bot in DM (new or returning)
    if chat.type == "private":
        try:
            status_label = "🆕 New User Started Bot" if is_new_user else "🔁 User Started Bot Again"
            await context.bot.send_message(
                chat_id=SUPPORT_GROUP_ID,
                text=(
                    f'{status_label}\n'
                    f'👤 {html.escape(user.first_name)} (<a href="tg://user?id={user.id}">{user.id}</a>)\n'
                    f'🎈 @{user.username if user.username else "no_username"}'
                ),
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.error(f"Failed to notify support group about /start: {e}")

    welcome_text = (
        "<b>🏏 CRICOVERSE</b>  <i>— The Ultimate Hand Cricket Bot</i>\n"
        "<blockquote>"
        "🎮 <b>Game Modes</b>\n"
        "⚡ Team Match — 2-team battles\n"
        "⚔️ Solo Battle — free-for-all\n"
        "🤖 AI Mode — play vs the bot\n"
        "🔮 Magic Ball — wild card mode"
        "</blockquote>"
        "<blockquote>"
        "🏆 <b>Features</b>\n"
        "📺 DRS Reviews · 🎙️ Commentary\n"
        "📊 Career Stats · 🏅 Tournaments\n"
        "🔥 Leaderboards · 🧢 Captaincy\n"
        "🎉 Live Reactions · 💰 Fantasy XI"
        "</blockquote>"
        "👇 <b>Add me to your group</b> and use /game to begin!\n"
        "❓ Tap <b>Help</b> below for the full command guide."
    )

    
    if chat.type == "private":
        # Add to Group + Help + Support Group buttons
        bot_username = (await context.bot.get_me()).username
        keyboard = [
            [styled_button("➕ Add to Group", url=f"https://t.me/{bot_username}?startgroup=true", style="primary")],
            [styled_button("📚 Help", callback_data="help_main", style="success"),
             styled_button("🏆 Leaderboard", callback_data="help_stats", style="success")],
            [styled_button("🆘 Support Group", url="https://t.me/cricoverse", style="danger")]
        ]
        
        _welcome_mid = None
        try:
            _welcome_mid = await send_welcome_rich(
                chat.id, user.first_name, bot_username,
                reply_to=update.message.message_id if update.message else None)
        except Exception:
            logger.exception("rich welcome failed — using classic welcome")
        if _welcome_mid:
            return
        await update.message.reply_photo(
            photo=MEDIA_ASSETS["welcome"],
            caption=welcome_text,
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode=ParseMode.HTML
        )
    else:
        await update.message.reply_text("Bot is ready! Use /game to start.\n Please give me the command to Schedule your match")

