    """Handle Help Menu Navigation"""
    query = update.callback_query
    await query.answer()
    
    data = query.data
    
    if data == "help_close":
        await query.message.delete()
        return

    # Determine Text based on selection
    if data == "help_main":
        text = get_help_main_text()
        keyboard = [
            [styled_button("Team Mode", callback_data="help_team"),
             styled_button("Solo Mode", callback_data="help_solo")],
            [styled_button("Tournament", callback_data="help_tournament"),
             styled_button("Fantasy", callback_data="help_fantasy")],
            [styled_button("Stats", callback_data="help_stats"),
             styled_button("🎉 Reactions", callback_data="help_reactions")],
            [styled_button("Admin", callback_data="help_admin"),
             styled_button("How to Play", callback_data="help_tutorial")],
            [styled_button("Contact Us", callback_data="help_contact")],
            [styled_button("🆘 Support Group", url="https://t.me/cricoverse")],
            [styled_button("Close", callback_data="help_close")]
        ]
    
    elif data == "help_team":
        text = get_help_team_text()
        keyboard = [[styled_button("⬅️ Back to Menu", callback_data="help_main")]]
        
    elif data == "help_solo":
        text = get_help_solo_text()
        keyboard = [[styled_button("⬅️ Back to Menu", callback_data="help_main")]]
    
    elif data == "help_tournament":
        text = get_help_tournament_text()
        keyboard = [[styled_button("⬅️ Back to Menu", callback_data="help_main")]]

    elif data == "help_fantasy":
        text = get_help_fantasy_text()
        keyboard = [[styled_button("⬅️ Back to Menu", callback_data="help_main")]]

    elif data == "help_stats":
        text = get_help_stats_text()
        keyboard = [[styled_button("⬅️ Back to Menu", callback_data="help_main")]]

    elif data == "help_reactions":
        text = get_help_reactions_text()
        keyboard = [[styled_button("⬅️ Back to Menu", callback_data="help_main")]]

    elif data == "help_admin":
        text = get_help_admin_text()
        keyboard = [[styled_button("⬅️ Back to Menu", callback_data="help_main")]]
        
    elif data == "help_tutorial":
        text = get_help_tutorial_text()
        keyboard = [[styled_button("⬅️ Back to Menu", callback_data="help_main")]]

