async def teamcreate_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Create a tournament team: /teamcreate [team name]"""
    chat = update.effective_chat
    user = update.effective_user

    if chat.type == "private":
        await update.message.reply_text("Use this command in a group!")
        return

    group_id = chat.id

    # Check approval → silently ignore unapproved groups
    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return

    # Admin check
    member = await context.bot.get_chat_member(group_id, user.id)
    if member.status not in ["administrator", "creator"]:
        await update.message.reply_text("🚫 Only group admins can create teams!")
        return
    
    if not context.args:
        await update.message.reply_text(
            "📋 Usage: <code>/teamcreate [team name]</code>\nExample: <code>/teamcreate Team Alpha</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    team_name = " ".join(context.args).strip()
    
    if team_name in tournament_teams[group_id]:
        await update.message.reply_text(f"⚠️ Team '<b>{team_name}</b>' already exists!", parse_mode=ParseMode.HTML)
        return
    
    tournament_teams[group_id][team_name] = {"players": [], "captain": None}
    await asyncio.to_thread(_save_tour_state_sync, group_id)  # ✅ persist immediately so a restart doesn't lose the team
    
    await update.message.reply_text(
        f"✅ <b>Team Created!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🏏 <b>Team:</b> {team_name}\n\n"
        f"Now add players:\n"
        f"<code>/teamadd {team_name} @username @username2...</code>",
        parse_mode=ParseMode.HTML
    )


async def setgroup_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🆕 Manually assign a tournament team to Group A or Group B:
    /setgroup [team name] [A|B] — admin only. Optional; if never used,
    fixture generation auto-splits teams evenly when there are 4+ teams."""
    chat = update.effective_chat
    user = update.effective_user

    if chat.type == "private":
        await update.message.reply_text("Use this command in a group!")
        return

    group_id = chat.id

    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return

    member = await context.bot.get_chat_member(group_id, user.id)
    if member.status not in ["administrator", "creator"]:
        await update.message.reply_text("🚫 Only group admins can set groups!")
        return

    if not context.args or len(context.args) < 2:
        await update.message.reply_text(
            "📋 Usage: <code>/setgroup [team name] [A/B]</code>\n"
            "Example: <code>/setgroup Team Alpha A</code>",
            parse_mode=ParseMode.HTML
        )
        return

    letter = context.args[-1].strip().upper()
    if letter not in ("A", "B"):
        await update.message.reply_text("⚠️ Group must be <b>A</b> or <b>B</b>.", parse_mode=ParseMode.HTML)
        return

    team_name = " ".join(context.args[:-1]).strip()
    teams = tournament_teams.get(group_id, {})
    if team_name not in teams:
        await update.message.reply_text(f"⚠️ Team '<b>{team_name}</b>' not found!", parse_mode=ParseMode.HTML)
        return

    if tournament_fixtures.get(group_id):
        await update.message.reply_text(
            "⚠️ Fixtures are already generated for this tournament — group changes "
            "won't affect them. Use <code>/tourend</code> and start fresh if you need to re-group.",
            parse_mode=ParseMode.HTML
        )
        return

    tournament_groups.setdefault(group_id, {})[team_name] = letter
    await asyncio.to_thread(_save_tour_state_sync, group_id)

    await update.message.reply_text(
        f"✅ <b>{html.escape(team_name)}</b> assigned to <b>Group {letter}</b>.",
        parse_mode=ParseMode.HTML
    )


async def teamadd_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Add players to tournament team: /teamadd [team] @user @user2...
    Also supports reply to add single user, or user IDs."""
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.type == "private":
        await update.message.reply_text("Use this command in a group!")
        return
    
    group_id = chat.id
    
    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return
    
    member = await context.bot.get_chat_member(group_id, user.id)
    if member.status not in ["administrator", "creator"]:
        await update.message.reply_text("🚫 Only admins can add players!")
        return
    
    if not context.args:
        await update.message.reply_text(
            "📋 Usage: <code>/teamadd [team name] @user @user2...</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Parse: first arg(s) might be multi-word team name, then @mentions
    args = context.args
    teams = tournament_teams.get(group_id, {})
    
    # Find team name (try progressively longer phrases)
    team_name = None
    player_args_start = 0
    for i in range(len(args), 0, -1):
        potential = " ".join(args[:i])
        if potential in teams:
            team_name = potential
            player_args_start = i
            break
    
    if not team_name:
        team_list = ", ".join(teams.keys()) if teams else "None"
        await update.message.reply_text(
            f"⚠️ Team not found!\nAvailable teams: {team_list}",
            parse_mode=ParseMode.HTML
        )
        return
    
    player_args = args[player_args_start:]
    added = []
    failed = []
    
    # Parse mentions and user IDs
    entities = update.message.entities or []
    mentioned_users = []
    for entity in entities:
        if entity.type == "mention":
            username = update.message.text[entity.offset+1:entity.offset+entity.length]
            try:
                chat_member = await context.bot.get_chat_member(group_id, f"@{username}")
                mentioned_users.append({
                    "user_id": chat_member.user.id,
                    "username": chat_member.user.username or "",
                    "first_name": chat_member.user.first_name
                })
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 5650)")
                failed.append(f"@{username}")
        elif entity.type == "text_mention" and entity.user:
            mentioned_users.append({
                "user_id": entity.user.id,
                "username": entity.user.username or "",
                "first_name": entity.user.first_name
            })
    
    # Also check numeric user IDs in args
    for arg in player_args:
        if arg.isdigit():
            try:
                cm = await context.bot.get_chat_member(group_id, int(arg))
                mentioned_users.append({
                    "user_id": cm.user.id,
                    "username": cm.user.username or "",
                    "first_name": cm.user.first_name
                })
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 5669)")
                failed.append(arg)
    
    team_data = tournament_teams[group_id][team_name]
    existing_ids = {p["user_id"] for p in team_data["players"]}
    
    not_started = []  # Users who haven't started the bot
    for p in mentioned_users:
        if p["user_id"] not in existing_ids:
            # ✅ Check if player has started the bot before adding
            started = await check_user_started_bot(context.bot, p["user_id"])
            if not started:
                not_started.append(p["first_name"])
                # Still add them — but warn the admin
            team_data["players"].append(p)
            existing_ids.add(p["user_id"])
            added.append(p["first_name"])
    
    bot_username = context.bot.username
    if added:
        await asyncio.to_thread(_save_tour_state_sync, group_id)  # ✅ persist immediately so a restart doesn't lose the roster
    msg = f"✅ <b>Players Added to {team_name}</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    if added:
        msg += f"✅ Added: {', '.join(added)}\n"
    if failed:
        msg += f"⚠️ Not found in group: {', '.join(failed)}\n"
    if not_started:
        msg += (
            f"\n⚠️ <b>Hasn't started bot:</b> {', '.join(not_started)}\n"
            f"👉 Ask them to start: <a href='https://t.me/{bot_username}'>@{bot_username}</a>\n"
            f"<i>They won't receive bowl/bat DMs until they do!</i>\n"
        )
    msg += f"\n📊 <b>Team size:</b> {len(team_data['players'])} players"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML, disable_web_page_preview=True)


async def teamremove_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Remove player(s) from tournament team: /teamremove [team] @user @user2..."""
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.type == "private":
        return
    
    group_id = chat.id
    
    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return
    
    member = await context.bot.get_chat_member(group_id, user.id)
    if member.status not in ["administrator", "creator"]:
        await update.message.reply_text("🚫 Only admins can remove players!")
        return
    
    if not context.args:
        await update.message.reply_text(
            "📋 Usage: <code>/teamremove [team name] @user @user2...</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    args = context.args
    teams = tournament_teams.get(group_id, {})
    
    team_name = None
    player_args_start = 0
    for i in range(len(args), 0, -1):
        potential = " ".join(args[:i])
        if potential in teams:
            team_name = potential
            player_args_start = i
            break
    
    if not team_name:
        await update.message.reply_text("⚠️ Team not found!")
        return
    
    # Collect IDs to remove
    ids_to_remove = set()
    entities = update.message.entities or []
    for entity in entities:
        if entity.type == "mention":
            username = update.message.text[entity.offset+1:entity.offset+entity.length]
            try:
                cm = await context.bot.get_chat_member(group_id, f"@{username}")
                ids_to_remove.add(cm.user.id)
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 5756)")
                pass
        elif entity.type == "text_mention" and entity.user:
            ids_to_remove.add(entity.user.id)
    
    for arg in context.args[player_args_start:]:
        if arg.isdigit():
            ids_to_remove.add(int(arg))
    
    team_data = tournament_teams[group_id][team_name]
    before = len(team_data["players"])
    team_data["players"] = [p for p in team_data["players"] if p["user_id"] not in ids_to_remove]
    after = len(team_data["players"])
    removed = before - after

    if removed:
        await asyncio.to_thread(_save_tour_state_sync, group_id)  # ✅ persist immediately so a restart doesn't lose the change

    await update.message.reply_text(
        f"✅ <b>Removed {removed} player(s) from {team_name}</b>\n"
        f"📊 <b>Team size:</b> {after} players",
        parse_mode=ParseMode.HTML
    )


async def teamdelete_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Dissolve a tournament team/franchise: /teamdelete [team name]"""
    chat = update.effective_chat
    user = update.effective_user

    if chat.type == "private":
        await update.message.reply_text("Use this command in a group!")
        return

    group_id = chat.id

    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return

    member = await context.bot.get_chat_member(group_id, user.id)
    if member.status not in ["administrator", "creator"]:
        await update.message.reply_text("🚫 Only group admins can delete teams!")
        return

    if not context.args:
        await update.message.reply_text(
            "📋 Usage: <code>/teamdelete [team name]</code>\nExample: <code>/teamdelete Team Alpha</code>",
            parse_mode=ParseMode.HTML
        )
        return

    args = context.args
    teams = tournament_teams.get(group_id, {})

    # Find team name (progressively longer phrases, same logic as /teamadd)
    team_name = None
    for i in range(len(args), 0, -1):
        potential = " ".join(args[:i])
        if potential in teams:
            team_name = potential
            break

    if not team_name:
        team_list = ", ".join(teams.keys()) if teams else "None"
        await update.message.reply_text(
            f"⚠️ Team not found!\nAvailable teams: {team_list}",
            parse_mode=ParseMode.HTML
        )
        return

    # Confirm if this team has already played matches (points table entry exists)
    pts_row = tournament_points.get(group_id, {}).get(team_name)
    has_history = bool(pts_row and pts_row.get("played", 0) > 0)

    del tournament_teams[group_id][team_name]

    # Remove any *unplayed* fixtures involving this team (played ones are left as history)
    fixtures = tournament_fixtures.get(group_id, [])
    tournament_fixtures[group_id] = [
        f for f in fixtures
        if f.get("result") is not None or (f.get("team1") != team_name and f.get("team2") != team_name)
    ]

    await asyncio.to_thread(_save_tour_state_sync, group_id)  # ✅ persist immediately

    warn = ""
    if has_history:
        warn = (
            f"\n\n⚠️ <b>Note:</b> This team already had match results recorded "
            f"(P{pts_row['played']} W{pts_row['won']} L{pts_row['lost']}, NRR {pts_row.get('nrr', 0):+.2f}).\n"
            f"That record is kept in the points table. If you create a <b>new</b> team with the "
            f"<u>exact same name</u> later, it will inherit this old record — use a different name "
            f"if you want a clean slate."
        )

    await update.message.reply_text(
        f"🗑️ <b>Team Dissolved!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🏏 <b>Team:</b> {team_name}\n"
        f"Removed from tournament + any unplayed fixtures cleared."
        f"{warn}",
        parse_mode=ParseMode.HTML
    )


def _default_team_stats():
    """Default points-table row for a team, including NRR tracking fields."""
    return {
        "played": 0, "won": 0, "lost": 0, "tied": 0, "pts": 0, "nrr": 0.0,
        "runs_for": 0.0, "overs_for": 0.0, "runs_against": 0.0, "overs_against": 0.0,
    }


def _effective_overs(team, allotted_overs: float) -> float:
    """Standard NRR rule: if a team is bowled all out before using its full quota of
    overs, the FULL allotted overs are used for run-rate purposes. Otherwise the
    actual overs faced/bowled are used."""
    actual_overs = (team.balls or 0) / 6.0
    if getattr(team, "all_out", False):
        return float(allotted_overs)
    return actual_overs


# ═══════════════════════════════════════════════════════════════
# 🆕 TOURNAMENT MATCH SCHEDULING (per user's request)
# A group admin sets a match's time in 24h format (IST assumed, "today" if
# the time hasn't passed yet, otherwise "tomorrow"). 1 hour before that time,
# both teams' players get tagged with a reminder. Time can be changed or the
# match postponed at any point simply by setting a new time — the old
# reminder job is cancelled and a fresh one armed.
# ═══════════════════════════════════════════════════════════════

def _ist_now() -> datetime:
    return datetime.utcnow() + timedelta(hours=5, minutes=30)


def _fx_countdown_str(scheduled_dt_ist: datetime, now_ist: datetime) -> str:
    """'2d 8h 17m' / '8h 17m' / '17m' style countdown to a scheduled time.
    Returns 'Starting now' once the time has passed."""
    delta = scheduled_dt_ist - now_ist
    total_minutes = int(delta.total_seconds() // 60)
    if total_minutes <= 0:
        return "Starting now"
    days, rem = divmod(total_minutes, 1440)
    hours, minutes = divmod(rem, 60)
    parts = []
    if days:
        parts.append(f"{days}d")
    if hours or days:
        parts.append(f"{hours}h")
    parts.append(f"{minutes}m")
    return " ".join(parts)


def _tour_reminder_job_name(group_id: int, match_id: int) -> str:
    return f"tourrem_{group_id}_{match_id}"


def _tour_kickoff_job_name(group_id: int, match_id: int) -> str:
    return f"tourkickoff_{group_id}_{match_id}"


def _cancel_tour_reminder_job(job_queue, group_id: int, match_id: int):
    if not job_queue:
        return
    for job in job_queue.get_jobs_by_name(_tour_reminder_job_name(group_id, match_id)):
        job.schedule_removal()
    for job in job_queue.get_jobs_by_name(_tour_kickoff_job_name(group_id, match_id)):
        job.schedule_removal()


_VENUE_LINK_CACHE: Dict[int, str] = {}


async def _get_venue_display(context: ContextTypes.DEFAULT_TYPE, group_id: int) -> str:
    """HTML-ready 'venue' label for a fixture's assigned group — a clickable
    link to that group when possible, otherwise just its bold title.
    Cached per group_id so a fixtures page with many matches in the same
    group doesn't hit the Bot API once per row."""
    if group_id in _VENUE_LINK_CACHE:
        return _VENUE_LINK_CACHE[group_id]

    label = "This Group"
    try:
        chat = await context.bot.get_chat(group_id)
        title = html.escape(chat.title or "Group")
        if getattr(chat, "username", None):
            label = f'<a href="https://t.me/{chat.username}">{title}</a>'
        elif getattr(chat, "invite_link", None):
            label = f'<a href="{chat.invite_link}">{title}</a>'
        else:
            try:
                link = await context.bot.export_chat_invite_link(group_id)
                label = f'<a href="{link}">{title}</a>'
            except Exception:
                label = f"<b>{title}</b>"
    except Exception:
        pass

    _VENUE_LINK_CACHE[group_id] = label
    return label


def _find_tour_fixture(group_id: int, match_id: int) -> Optional[dict]:
    for fix in tournament_fixtures.get(group_id, []):
        if fix.get("match_id") == match_id:
            return fix
    return None


def _arm_tour_reminder_job(job_queue, group_id: int, match_id: int, scheduled_dt_ist: datetime,
                            arm_reminder: bool = True, arm_kickoff: bool = True):
    """(Re)schedule the 1-hour-before reminder AND/OR the at-kickoff-time
    admin ping for this fixture. Cancels any existing jobs for the same
    match first, so re-scheduling/postponing just works by calling this
    again with a new time.

    🩹 BUGFIX: arm_reminder/arm_kickoff let a caller (re)arm just ONE of the
    two jobs. This matters on bot restart: the startup re-arm loop used to
    gate BOTH jobs behind a single "reminder_sent" flag, so if the process
    restarted between the reminder firing and kickoff time, the kickoff
    ping never got rescheduled and silently never fired. Now each job is
    armed independently based on its own "*_sent" flag."""
    if not job_queue:
        return
    _cancel_tour_reminder_job(job_queue, group_id, match_id)

    if arm_reminder:
        fire_at_ist = scheduled_dt_ist - timedelta(hours=1)
        delay = (fire_at_ist - _ist_now()).total_seconds()
        if delay < 0:
            # Less than 1h away (or already past) — fire almost immediately so
            # the reminder still goes out instead of silently never firing.
            delay = 2
        job_queue.run_once(
            tour_match_reminder_job,
            when=delay,
            data={"group_id": group_id, "match_id": match_id, "scheduled_iso": scheduled_dt_ist.isoformat()},
            name=_tour_reminder_job_name(group_id, match_id),
        )

    if arm_kickoff:
        # 🆕 Kickoff-time ping — fires right at the scheduled match time and
        # tags all group admins about the match starting.
        kickoff_delay = (scheduled_dt_ist - _ist_now()).total_seconds()
        if kickoff_delay < 0:
            kickoff_delay = 3
        job_queue.run_once(
            tour_match_kickoff_job,
            when=kickoff_delay,
            data={"group_id": group_id, "match_id": match_id, "scheduled_iso": scheduled_dt_ist.isoformat()},
            name=_tour_kickoff_job_name(group_id, match_id),
        )


def _tag_team_players(group_id: int, team_name: str) -> str:
    """Clickable tags for every player in a tournament team's roster."""
    team_data = tournament_teams.get(group_id, {}).get(team_name, {})
    tags = []
    for p in team_data.get("players", []):
        uid = p.get("user_id")
        name = p.get("first_name") or p.get("username") or str(uid)
        if uid:
            tags.append(f'<a href="tg://user?id={uid}">{html.escape(str(name))}</a>')
    return ", ".join(tags) if tags else "—"


def _team_player_ids(group_id: int, team_name: str) -> List[int]:
    """Raw list of user_ids for every player in a tournament team's roster."""
    team_data = tournament_teams.get(group_id, {}).get(team_name, {})
    ids = []
    for p in team_data.get("players", []):
        uid = p.get("user_id")
        if uid:
            ids.append(uid)
    return ids


async def tour_match_reminder_job(context: ContextTypes.DEFAULT_TYPE):
    """Fires ~1 hour before a scheduled tournament match — tags both teams'
    players in the group AND DMs each player individually."""
    data = context.job.data or {}
    group_id = data.get("group_id")
    match_id = data.get("match_id")
    fix = _find_tour_fixture(group_id, match_id)
    if not fix or fix.get("result") is not None:
        return  # match already played / fixture gone — nothing to remind about
    # Safety: if the schedule was changed since this job was armed, the old
    # job would've been cancelled already, but double-check just in case.
    if fix.get("scheduled_time_ist") != data.get("scheduled_iso"):
        return
    if fix.get("reminder_sent"):
        return
    fix["reminder_sent"] = True
    await asyncio.to_thread(_save_tour_state_sync, group_id)

    t1, t2 = fix["team1"], fix["team2"]
    try:
        sched_dt = datetime.fromisoformat(fix["scheduled_time_ist"])
        time_label = sched_dt.strftime("%H:%M")
    except Exception:
        time_label = "soon"

    text = themed("MATCH REMINDER", [
        f"🆚 <b>{html.escape(t1)}</b> vs <b>{html.escape(t2)}</b>",
        f"🕐 Starts at <b>{time_label} IST</b> — in about 1 hour.",
        f"🏏 {html.escape(t1)}: {_tag_team_players(group_id, t1)}",
        f"🏏 {html.escape(t2)}: {_tag_team_players(group_id, t2)}",
        "🔥 Be ready for the match.",
    ], "⏰")
    try:
        await context.bot.send_message(chat_id=group_id, text=text, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.error(f"tour_match_reminder_job send failed for group {group_id}: {e}")

    # 🆕 DM every player of both teams individually, 1 hour before kickoff.
    dm_text = themed("MATCH REMINDER", [
        f"🆚 <b>{html.escape(t1)}</b> vs <b>{html.escape(t2)}</b>",
        f"🕐 Starts at <b>{time_label} IST</b> — in about 1 hour.",
        "🔥 Be ready for the match.",
    ], "⏰")
    player_ids = set(_team_player_ids(group_id, t1)) | set(_team_player_ids(group_id, t2))
    for uid in player_ids:
        try:
            await context.bot.send_message(chat_id=uid, text=dm_text, parse_mode=ParseMode.HTML)
        except Exception as e:
            # Player may have blocked the bot / never started a DM with it — skip silently.
            logger.info(f"tour_match_reminder_job: DM failed for {uid}: {e}")


async def tour_match_kickoff_job(context: ContextTypes.DEFAULT_TYPE):
    """Fires exactly at the scheduled match time — tags all group admins
    about the match starting."""
    data = context.job.data or {}
    group_id = data.get("group_id")
    match_id = data.get("match_id")
    fix = _find_tour_fixture(group_id, match_id)
    if not fix or fix.get("result") is not None:
        return  # match already played / fixture gone
    if fix.get("scheduled_time_ist") != data.get("scheduled_iso"):
        return  # schedule changed since this job was armed
    if fix.get("kickoff_ping_sent"):
        return
    fix["kickoff_ping_sent"] = True
    await asyncio.to_thread(_save_tour_state_sync, group_id)

    t1, t2 = fix["team1"], fix["team2"]

    admin_tags = []
    try:
        admins = await context.bot.get_chat_administrators(group_id)
        for a in admins:
            if a.user.is_bot:
                continue
            admin_tags.append(f'<a href="tg://user?id={a.user.id}">{html.escape(a.user.first_name)}</a>')
    except Exception as e:
        logger.info(f"tour_match_kickoff_job: could not fetch admins for {group_id}: {e}")

    admins_line = ", ".join(admin_tags) if admin_tags else "—"

    text = (
        "🚨 <b>MATCH TIME!</b>\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🆚 <b>{html.escape(t1)}</b> vs <b>{html.escape(t2)}</b>\n"
        "🕐 Kickoff is right now!\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"👮 {admins_line}\n"
        "Please start the match! 🏏"
    )
    try:
        await context.bot.send_message(chat_id=group_id, text=text, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.error(f"tour_match_kickoff_job send failed for group {group_id}: {e}")


def _update_team_nrr(pts_row: dict, runs_for: float, overs_for: float, runs_against: float, overs_against: float):
    """Add this match's runs/overs into a team's running NRR totals and recompute NRR."""
    pts_row["runs_for"] = pts_row.get("runs_for", 0.0) + runs_for
    pts_row["overs_for"] = pts_row.get("overs_for", 0.0) + overs_for
    pts_row["runs_against"] = pts_row.get("runs_against", 0.0) + runs_against
    pts_row["overs_against"] = pts_row.get("overs_against", 0.0) + overs_against
    rr_for = pts_row["runs_for"] / pts_row["overs_for"] if pts_row["overs_for"] > 0 else 0.0
    rr_against = pts_row["runs_against"] / pts_row["overs_against"] if pts_row["overs_against"] > 0 else 0.0
    pts_row["nrr"] = round(rr_for - rr_against, 3)


def _tour_parse_mid(token: str):
    """Fixture ids are ints for league matches and strings like "po_sf1" for
    playoffs. 🩹 The tour_host_/tour_overs_/tour_teamx_/tour_teamy_ handlers
    all did int(callback.split("_")[2]) — for "po_sf1" that is int("po") —
    ValueError, so playoff fixtures could be generated but never started."""
    return int(token) if str(token).isdigit() else str(token)


def _tour_maybe_create_playoff_final(group_id: int) -> Optional[Tuple[str, str]]:
    """After both semi-finals have a decisive result, add the Final fixture
    (winner SF1 vs winner SF2). Playoffs used to stop at the semis, so a
    tournament could never actually finish. Returns (t1, t2) if created."""
    fixtures = tournament_fixtures.get(group_id, [])
    if any(f.get("match_id") == "po_final" for f in fixtures):
        return None
    sfs = [f for f in fixtures if f.get("match_id") in ("po_sf1", "po_sf2")]
    if len(sfs) != 2:
        return None
    winners = []
    for f in sorted(sfs, key=lambda x: x["match_id"]):
        res = f.get("result") or ""
        w = next((t for t in (f["team1"], f["team2"]) if res.startswith(f"{t} won")), None)
        if not w:
            return None  # not played yet, or a tie — admin decides
        winners.append(w)
    fixtures.append({"team1": winners[0], "team2": winners[1], "result": None, "match_id": "po_final"})
    return winners[0], winners[1]


def _tour_skip_league_points(group_id: int, mid) -> bool:
    """🩹 True when a result must NOT touch the league points table:
    (a) playoff fixtures (match_id "po_*") — they used to add played/won/pts/NRR
        to the league standings, distorting the very table playoffs were
        seeded from; (b) a fixture that already has a result — replaying or
        manually re-entering it used to count the same match twice."""
    if isinstance(mid, str) and mid.startswith("po_"):
        return True
    for fix in tournament_fixtures.get(group_id, []):
        if fix.get("match_id") == mid and fix.get("result") is not None:
            return True
    return False


async def record_tour_match_result(context, group_id: int, match, winner, loser):
    """Auto-capture player stats + result for a TOURNAMENT-mode match the moment it ends.
    This runs automatically when any tournament match finishes, so /tourresult becomes
    optional — points table, fixtures, NRR, and top-scorer stats (runs/wickets/sixes/fours/MVP)
    are saved right away instead of depending on an admin typing the result manually."""
    try:
        mid = getattr(match, "tournament_match_id", None)
        if mid is None or group_id not in pending_tour_match:
            return  # Not a tournament match, nothing to do

        t1 = match.team_x.name
        t2 = match.team_y.name

        player_runs, player_wkts, player_sixes, player_fours = {}, {}, {}, {}
        player_names = {}
        best_player, best_score = None, -1
        # 🩹 BUGFIX: these were previously keyed by p.first_name (a plain
        # string), but _build_tourlb_page (used by /tourlb) reads this dict
        # as {user_id: total} and calls tg://user?id=<key> to build profile
        # links, plus user_data.get(<key>) for username/jersey lookups.
        # Keying by name meant every /tourlb profile link was a broken
        # tg://user?id=<Name> URL, username/jersey always showed as
        # "—"/"Unranked", and two players sharing a first name would have
        # their stats silently merged into one row. Key by user_id instead.
        for p in match.team_x.players + match.team_y.players:
            if p.runs:
                player_runs[p.user_id] = player_runs.get(p.user_id, 0) + p.runs
            if p.wickets:
                player_wkts[p.user_id] = player_wkts.get(p.user_id, 0) + p.wickets
            if p.sixes:
                player_sixes[p.user_id] = player_sixes.get(p.user_id, 0) + p.sixes
            if p.boundaries:
                player_fours[p.user_id] = player_fours.get(p.user_id, 0) + p.boundaries
            # 🩹 BUGFIX: /tourlb showed raw numeric user_ids instead of names
            # for players whose user_data entry never got a "first_name"
            # (e.g. they never DM'd the bot). Save the name we already have
            # on the match's Player object right here, so the leaderboard
            # never has to depend on user_data being populated.
            if p.first_name:
                player_names[p.user_id] = p.first_name
            impact = p.runs + (p.wickets * 20)
            if impact > best_score:
                best_score, best_player = impact, p.first_name

        tour_match_stats[group_id][mid] = {
            "team1": t1, "team2": t2,
            "player_runs": player_runs,
            "player_wickets": player_wkts,
            "player_sixes": player_sixes,
            "player_fours": player_fours,
            "player_names": player_names,
            "mvp": best_player,
        }

        # Auto-update points table
        pts = tournament_points[group_id]
        _skip_pts = _tour_skip_league_points(group_id, mid)
        for tn in [t1, t2]:
            if tn not in pts:
                pts[tn] = _default_team_stats()

        if winner is None:
            if not _skip_pts:
                pts[t1]["played"] += 1; pts[t2]["played"] += 1
                pts[t1]["tied"] += 1; pts[t2]["tied"] += 1
                pts[t1]["pts"] += 1; pts[t2]["pts"] += 1
            result_str = "Tie"
        else:
            winner_name, loser_name = winner.name, loser.name
            pts.setdefault(winner_name, _default_team_stats())
            pts.setdefault(loser_name, _default_team_stats())
            if not _skip_pts:
                pts[winner_name]["played"] += 1; pts[loser_name]["played"] += 1
                pts[winner_name]["won"] += 1; pts[loser_name]["lost"] += 1
                pts[winner_name]["pts"] += 2
            result_str = f"{winner_name} won"

        # ✅ Update Net Run Rate for both teams (standard "all-out = full overs" rule)
        if not _skip_pts:
            allotted = float(getattr(match, "total_overs", 0) or 0)
            x_overs = _effective_overs(match.team_x, allotted)
            y_overs = _effective_overs(match.team_y, allotted)
            _update_team_nrr(pts[t1], match.team_x.score, x_overs, match.team_y.score, y_overs)
            _update_team_nrr(pts[t2], match.team_y.score, y_overs, match.team_x.score, x_overs)

        # Update the matching fixture + clear the pending-match session
        for fix in tournament_fixtures.get(group_id, []):
            if fix.get("match_id") == mid:
                fix["result"] = result_str
                break
        _final_pair = _tour_maybe_create_playoff_final(group_id)

        pending_tour_match.pop(group_id, None)
        # 🩹 BUGFIX: this used to call save_tour_state() (fire-and-forget —
        # asyncio.create_task without awaiting it). If the bot restarted
        # even a second or two after a match finished, that background
        # write could still be in-flight and would never complete, so the
        # DB kept the PREVIOUS snapshot. On next startup load_tour_state()
        # restored that stale, older points table — silently rolling back
        # "played"/"pts" for whichever matches finished right before the
        # restart (exactly the "matches count going down" glitch).
        # Awaiting the write here guarantees this match's result is safely
        # on disk before we move on, so a restart can never lose it.
        await asyncio.to_thread(_save_tour_state_sync, group_id)

        try:
            await context.bot.send_message(
                group_id,
                f"🏆 <b>Tournament stats saved!</b>\n{result_str} • Points table, NRR & top-scorer stats updated automatically."
                + (f"\n\n🏆 <b>FINAL SET:</b> {html.escape(_final_pair[0])} vs {html.escape(_final_pair[1])} — run it from Start Match!" if _final_pair else ""),
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass
    except Exception as e:
        logger.error(f"❌ Error auto-recording tour match result: {e}")


# ═══════════════════════════════════════════════════════════════
# MANUAL RESULT ENTRY — /addresult
# Owner + Powered users only. Flow:
# Team X → Team Y → Overs → Winner → Margin (runs text / wickets buttons)
# → per-player stats (runs/wkts/4s/6s, Skip = didn't play).
# ═══════════════════════════════════════════════════════════════

def _is_result_admin(user_id: int) -> bool:
    """Only the bot owner or 'powered' users may use /addresult.
    A user whose ONLY grant is the 'clone' permission is not a result admin —
    otherwise giving someone clone access would also (silently) hand them
    manual result entry."""
    if user_id == OWNER_ID:
        return True
    perms = POWERED_USERS.get(user_id)
    return perms is not None and perms != {"clone"}


def _mres_squad(group_id: int, team1: str, team2: str) -> List[Tuple[int, str, str]]:
    """Combined (user_id, first_name, team_name) list for both teams, pulled
    from tournament_teams — this is what lets the bot know the full playing
    pool. Whoever gets ⏭ Skipped in the stats loop is treated as 'didn't
    play' (no stats added for them at all)."""
    squad = []
    teams = tournament_teams.get(group_id, {})
    for tn in (team1, team2):
        for pd in teams.get(tn, {}).get("players", []):
            squad.append((pd["user_id"], pd.get("first_name", "Player"), tn))
    return squad


def _parse_cricket_overs(text: str) -> float:
    """Parse cricket-notation overs like '8.4' (8 overs, 4 balls) into the
    actual decimal overs (8 + 4/6 = 8.667) used for run-rate math. Raises
    ValueError on anything invalid (non-numeric, or ball part > 5)."""
    text = text.strip()
    if "." in text:
        whole_s, ball_s = text.split(".", 1)
        whole = int(whole_s) if whole_s else 0
        balls = int(ball_s)
    else:
        whole = int(text)
        balls = 0
    if balls > 5 or balls < 0 or whole < 0:
        raise ValueError("invalid overs")
    return whole + balls / 6.0


def _mres_overs_keyboard(mid) -> InlineKeyboardMarkup:
    rows = []
    for start in range(1, 21, 5):
        rows.append([styled_button(str(o), callback_data=f"mres_overs_{o}") for o in range(start, min(start + 5, 21))])
    return InlineKeyboardMarkup(rows)


def _mres_wkts_keyboard() -> InlineKeyboardMarkup:
    rows = []
    for start in range(0, 20, 5):
        rows.append([styled_button(str(w), callback_data=f"mres_wktmargin_{w}") for w in range(start, min(start + 5, 20))])
    return InlineKeyboardMarkup(rows)


def _mres_stats_prompt_text(session: Dict) -> str:
    idx = session["idx"]
    squad = session["squad"]
    uid, name, team = squad[idx]
    return (
        f"🧮 <b>Player stats</b> ({idx + 1}/{len(squad)})\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"👤 <b>{html.escape(name)}</b> ({html.escape(team)})\n\n"
        f"Reply with: <code>runs wickets sixes fours</code>\n"
        f"e.g. <code>41 0 2 3</code> for 41 runs, 0 wkts, 2 sixes, 3 fours.\n\n"
        f"Didn't play this match? Tap ⏭ Skip — no stats will be added for them."
    )


def _mres_stats_keyboard() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [styled_button("⏭ Skip (didn't play)", callback_data="mres_playerskip")],
        [styled_button("Finish & Save now", callback_data="mres_playerdone")],
        [styled_button("Cancel", callback_data="mres_cancel")],
    ])


async def _mres_advance_to_stats(query_or_msg, context, group_id: int, edit: bool):
    session = manual_result_sessions[group_id]
    if session["idx"] >= len(session["squad"]):
        await _mres_finalize(query_or_msg, context, group_id)
        return
    text = _mres_stats_prompt_text(session)
    kb = _mres_stats_keyboard()
    try:
        if edit:
            await query_or_msg.edit_message_text(text, reply_markup=kb, parse_mode=ParseMode.HTML)
        else:
            await query_or_msg.reply_text(text, reply_markup=kb, parse_mode=ParseMode.HTML)
    except Exception:
        await context.bot.send_message(group_id, text, reply_markup=kb, parse_mode=ParseMode.HTML)


async def _mres_finalize(query_or_msg, context, group_id: int):
    session = manual_result_sessions.pop(group_id, None)
    if not session:
        return

    t1, t2 = session["team1"], session["team2"]
    winner = session["winner"]
    margin_text = session.get("margin_text", "")
    mid = session["mid"]

    pts = tournament_points[group_id]
    for tn in (t1, t2):
        pts.setdefault(tn, _default_team_stats())
    _skip_pts = _tour_skip_league_points(group_id, mid)

    if winner is None:
        if not _skip_pts:
            pts[t1]["played"] += 1; pts[t2]["played"] += 1
            pts[t1]["tied"] += 1; pts[t2]["tied"] += 1
            pts[t1]["pts"] += 1; pts[t2]["pts"] += 1
        result_str = "Tie"
    else:
        loser = t2 if winner == t1 else t1
        if not _skip_pts:
            pts[winner]["played"] += 1; pts[loser]["played"] += 1
            pts[winner]["won"] += 1; pts[loser]["lost"] += 1
            pts[winner]["pts"] += 2
        result_str = f"{winner} won" + (f" {margin_text}" if margin_text else "")

    # ✅ NRR — use the per-team score & actual overs played that were
    # collected during the flow (not the shared match-format overs), so a
    # team bowled out early (or a shortened innings) reflects correctly.
    score1 = session.get("score1")
    overs1 = session.get("overs1")
    score2 = session.get("score2")
    overs2 = session.get("overs2")
    if not _skip_pts and score1 is not None and score2 is not None and overs1 and overs2:
        _update_team_nrr(pts[t1], score1, overs1, score2, overs2)
        _update_team_nrr(pts[t2], score2, overs2, score1, overs1)

    for fix in tournament_fixtures.get(group_id, []):
        if fix.get("match_id") == mid:
            fix["result"] = result_str
            break
    _final_pair = _tour_maybe_create_playoff_final(group_id)

    player_runs, player_wkts, player_sixes, player_fours = {}, {}, {}, {}
    best_player, best_score = None, -1
    # 🩹 BUGFIX: same issue as record_tour_match_result — keyed by name
    # instead of user_id, breaking /tourlb profile links, username and
    # jersey lookups. Key by uid; keep displaying the typed-in name for MVP.
    for uid, name, team in session["squad"]:
        s = session["stats"].get(uid)
        if not s:
            continue  # skipped → did not play, no stats at all
        if s["runs"]:
            player_runs[uid] = player_runs.get(uid, 0) + s["runs"]
        if s["wkts"]:
            player_wkts[uid] = player_wkts.get(uid, 0) + s["wkts"]
        if s["sixes"]:
            player_sixes[uid] = player_sixes.get(uid, 0) + s["sixes"]
        if s["fours"]:
            player_fours[uid] = player_fours.get(uid, 0) + s["fours"]
        impact = s["runs"] + (s["wkts"] * 20)
        if impact > best_score:
            best_score, best_player = impact, name

    tour_match_stats[group_id][mid] = {
        "team1": t1, "team2": t2,
        "player_runs": player_runs,
        "player_wickets": player_wkts,
        "player_sixes": player_sixes,
        "player_fours": player_fours,
        "mvp": best_player,
        "manual_entry": True,
    }

    pending_tour_match.pop(group_id, None)
    # 🩹 BUGFIX: same restart-data-loss issue as record_tour_match_result —
    # await the write instead of firing-and-forgetting it, so a manually
    # entered result can never be silently rolled back by a restart.
    await asyncio.to_thread(_save_tour_state_sync, group_id)

    def _fmt_overs(o):
        if not o:
            return "—"
        whole = int(o)
        balls = round((o - whole) * 6)
        return f"{whole}.{balls}"

    score_line = ""
    if score1 is not None and score2 is not None:
        score_line = (
            f"🏏 <b>{html.escape(t1)}:</b> {score1} ({_fmt_overs(overs1)} ov)\n"
            f"🏏 <b>{html.escape(t2)}:</b> {score2} ({_fmt_overs(overs2)} ov)\n"
        )

    text = (
        f"✅ <b>MANUAL RESULT SAVED!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"⚔️ <b>{t1}</b> vs <b>{t2}</b>\n"
        f"🎯 <b>Match format:</b> {session.get('overs')} overs\n"
        f"{score_line}"
        f"🏆 <b>Result:</b> {result_str}\n"
        f"👑 <b>MVP:</b> {html.escape(best_player) if best_player else '—'}\n\n"
        f"Points table, NRR, fixture result & player stats have been updated."
        + (f"\n\n🏆 <b>FINAL SET:</b> {html.escape(_final_pair[0])} vs {html.escape(_final_pair[1])}" if _final_pair else "")
    )
    try:
        await query_or_msg.edit_message_text(text, parse_mode=ParseMode.HTML)
    except Exception:
        try:
            await query_or_msg.reply_text(text, parse_mode=ParseMode.HTML)
        except Exception:
            await context.bot.send_message(group_id, text, parse_mode=ParseMode.HTML)


async def addresult_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/addresult — owner/powered-only manual result + player-stats entry.
    Flow: Team X -> Team Y -> Overs -> Winner -> Margin -> player stats."""
    chat = update.effective_chat
    user = update.effective_user
    if chat.type == "private":
        await update.message.reply_text("Use this inside the tournament group.")
        return

    group_id = chat.id
    if not _is_result_admin(user.id):
        await update.message.reply_text("🚫 Only the bot owner or powered users can use this.")
        return

    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        await update.message.reply_text("⚠️ This group isn't tournament-approved.")
        return

    all_teams = list(tournament_teams.get(group_id, {}).keys())
    if len(all_teams) < 2:
        await update.message.reply_text("⚠️ Need at least 2 registered tournament teams first.")
        return

    mid = f"manual_{int(time.time())}"
    manual_result_sessions[group_id] = {
        "user_id": user.id, "mid": mid, "team1": None, "team2": None,
        "overs": None, "winner": None, "margin_text": "",
        "score1": None, "overs1": None, "score2": None, "overs2": None,
        "squad": [], "idx": 0, "stats": {}, "stage": "team_x",
    }

    kb = [[styled_button(tn, callback_data=f"mres_tx_{tn}")] for tn in all_teams]
    kb.append([styled_button("Cancel", callback_data="mres_cancel")])
    await update.message.reply_text(
        "🏆 <b>Manual Result Entry</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n🔵 Select <b>Team X</b>:",
        reply_markup=InlineKeyboardMarkup(kb), parse_mode=ParseMode.HTML,
    )


async def mres_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    user = query.from_user
    group_id = query.message.chat.id
    data = query.data

    if not _is_result_admin(user.id):
        await query.answer(plain_alert("🚫 Not authorized."), show_alert=True)
        return

    session = manual_result_sessions.get(group_id)
    if not session or session["user_id"] != user.id:
        if data != "mres_cancel":
            await query.answer("No active session for you here. Run /addresult again.", show_alert=True)
            return

    if data == "mres_cancel":
        manual_result_sessions.pop(group_id, None)
        await query.edit_message_text("❌ Manual result entry cancelled.")
        await query.answer()
        return

    # ── Team X ──
    if data.startswith("mres_tx_"):
        tx = data[len("mres_tx_"):]
        session["team1"] = tx
        all_teams = [t for t in tournament_teams.get(group_id, {}).keys() if t != tx]
        kb = [[styled_button(tn, callback_data=f"mres_ty_{tn}")] for tn in all_teams]
        kb.append([styled_button("Cancel", callback_data="mres_cancel")])
        await query.edit_message_text(
            f"✅ Team X = <b>{html.escape(tx)}</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n🔴 Select <b>Team Y</b>:",
            reply_markup=InlineKeyboardMarkup(kb), parse_mode=ParseMode.HTML,
        )
        await query.answer()
        return

    # ── Team Y ──
    if data.startswith("mres_ty_"):
        ty = data[len("mres_ty_"):]
        session["team2"] = ty
        session["squad"] = _mres_squad(group_id, session["team1"], session["team2"])
        session["stage"] = "overs"
        await query.edit_message_text(
            f"✅ <b>{html.escape(session['team1'])}</b> vs <b>{html.escape(ty)}</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n🔢 Select number of overs:",
            reply_markup=_mres_overs_keyboard(session["mid"]), parse_mode=ParseMode.HTML,
        )
        await query.answer()
        return

    # ── Overs (match format, e.g. "10 over game") ──
    if data.startswith("mres_overs_"):
        overs = int(data.split("_")[2])
        session["overs"] = overs
        session["stage"] = "score1_text"
        t1 = session["team1"]
        await query.edit_message_text(
            f"✅ <b>{overs}-over match</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"✏️ Reply with <b>{html.escape(t1)}</b>'s score and overs actually played "
            f"(format: <code>runs overs.balls</code>)\n\n"
            f"e.g. <code>145 {overs}.0</code> if they batted the full quota, "
            f"or <code>90 7.4</code> if all out in 7 overs 4 balls.",
            parse_mode=ParseMode.HTML,
        )
        await query.answer()
        return

    # ── Winner ──
    if data.startswith("mres_win_"):
        choice = data.split("_")[2]
        session["winner"] = {"t1": session["team1"], "t2": session["team2"], "tie": None}[choice]
        session["stage"] = "margin_type"
        if session["winner"] is None:
            session["margin_text"] = ""
            session["stage"] = "player_stats"
            await query.answer()
            await _mres_advance_to_stats(query, context, group_id, edit=True)
            return
        kb = [
            [styled_button("By Runs", callback_data="mres_margintype_runs")],
            [styled_button("By Wickets", callback_data="mres_margintype_wkts")],
            [styled_button("⏭ Skip margin", callback_data="mres_margintype_skip")],
        ]
        await query.edit_message_text(
            f"✅ Result: <b>{session['winner']} won</b>\n\n📏 Winning margin?",
            reply_markup=InlineKeyboardMarkup(kb), parse_mode=ParseMode.HTML,
        )
        await query.answer()
        return

    # ── Margin type ──
    if data.startswith("mres_margintype_"):
        kind = data.split("_")[2]
        if kind == "skip":
            session["margin_text"] = ""
            session["stage"] = "player_stats"
            await query.answer()
            await _mres_advance_to_stats(query, context, group_id, edit=True)
        elif kind == "wkts":
            session["stage"] = "margin_wkts"
            await query.edit_message_text(
                "🎯 Select wicket margin:", reply_markup=_mres_wkts_keyboard()
            )
            await query.answer()
        else:  # runs — bigger range, ask as text
            session["stage"] = "margin_runs_text"
            await query.edit_message_text("✏️ Reply with the winning run margin, e.g. 20")
            await query.answer()
        return

    # ── Wicket margin button (0-19) ──
    if data.startswith("mres_wktmargin_"):
        w = int(data.split("_")[2])
        session["margin_text"] = f"by {w} wicket{'s' if w != 1 else ''}"
        session["stage"] = "player_stats"
        await query.answer()
        await _mres_advance_to_stats(query, context, group_id, edit=True)
        return

    if data == "mres_playerskip":
        session["idx"] += 1
        await query.answer()
        await _mres_advance_to_stats(query, context, group_id, edit=True)
        return

    if data == "mres_playerdone":
        await query.answer()
        await _mres_finalize(query, context, group_id)
        return


async def handle_tour_schedule_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """Call this FIRST inside handle_group_input (alongside the result-entry
    hijack). Returns True if the message was consumed as the date/time reply
    for an in-progress /addvc-style 'Schedule a Match' flow."""
    if update.effective_chat.type == "private" or not update.message or not update.message.text:
        return False
    group_id = update.effective_chat.id
    user = update.effective_user
    pending = TOUR_SCHEDULE_PENDING.get(user.id)
    if not pending or pending.get("group_id") != group_id or pending.get("step") != "awaiting_datetime":
        return False

    text = update.message.text.strip()
    team1, team2 = pending["team1"], pending["team2"]
    now_ist = _ist_now()
    scheduled_dt = None

    # Try "DD-MM-YYYY HH:MM" first, then fall back to "HH:MM" only (today,
    # or tomorrow if that time has already passed today).
    for fmt in ("%d-%m-%Y %H:%M", "%d/%m/%Y %H:%M"):
        try:
            scheduled_dt = datetime.strptime(text, fmt)
            break
        except ValueError:
            continue
    if scheduled_dt is None:
        m = re.match(r"^([01]?\d|2[0-3]):([0-5]\d)$", text)
        if m:
            hh, mm = int(m.group(1)), int(m.group(2))
            candidate = now_ist.replace(hour=hh, minute=mm, second=0, microsecond=0)
            if candidate <= now_ist:
                candidate += timedelta(days=1)
            scheduled_dt = candidate

    if scheduled_dt is None:
        await update.message.reply_text(
            "⚠️ Couldn't understand that. Send either:\n"
            "<code>DD-MM-YYYY HH:MM</code>  e.g. <code>25-09-2026 18:30</code>\n"
            "or just <code>HH:MM</code>  e.g. <code>18:30</code>",
            parse_mode=ParseMode.HTML
        )
        return True

    # Find an existing unplayed fixture for this pair (either order); update
    # it (= reschedule/postpone). Otherwise create a brand-new fixture.
    # 🆕 Matched case/whitespace-insensitively so a stray space or casing
    # difference never causes a false "not found" → duplicate fixture.
    def _norm(s):
        return (s or "").strip().casefold()

    fixtures = tournament_fixtures[group_id]
    wanted = {_norm(team1), _norm(team2)}
    matches = [
        f for f in fixtures if f.get("result") is None and
        {_norm(f.get("team1")), _norm(f.get("team2"))} == wanted
    ]
    fix = matches[0] if matches else None
    # If duplicates already exist from before this fix, fold the extras away
    # instead of leaving dangling near-identical unplayed fixtures.
    for extra in matches[1:]:
        fixtures.remove(extra)
    is_new = fix is None
    if fix is None:
        tour_fixture_counter[group_id] += 1
        fix = {"team1": team1, "team2": team2, "result": None, "match_id": tour_fixture_counter[group_id]}
        fixtures.append(fix)
        for tname in (team1, team2):
            tournament_points[group_id].setdefault(tname, _default_team_stats())

    fix["scheduled_time_ist"] = scheduled_dt.isoformat()
    fix["reminder_sent"] = False
    fix["assigned_group"] = group_id  # 🆕 this match will start here, even in a multi-group linked tournament
    _arm_tour_reminder_job(context.job_queue, group_id, fix["match_id"], scheduled_dt)
    await asyncio.to_thread(_save_tour_state_sync, group_id)
    TOUR_SCHEDULE_PENDING.pop(user.id, None)

    verb = "SCHEDULED" if is_new else "RESCHEDULED"
    await update.message.reply_text(
        f"✅ <b>MATCH {verb}!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🆚 <b>{html.escape(team1)}</b> vs <b>{html.escape(team2)}</b>\n"
        f"🕐 <b>{scheduled_dt.strftime('%d %b %Y, %H:%M')} IST</b>\n"
        f"⏰ Both teams get pinged 1 hour before kickoff — in the group and by DM.\n"
        f"👮 All group admins get tagged the moment kickoff time arrives.\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"This now shows up in Fixtures and the /tourinfo dashboard.",
        parse_mode=ParseMode.HTML
    )
    return True


async def handle_tour_manage_team_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """Call this inside handle_group_input. Returns True if the message was
    consumed as a reply for the button-driven Manage Teams flow (create team
    name, or add-player @mention/reply/id)."""
    if update.effective_chat.type == "private" or not update.message or not update.message.text:
        return False
    group_id = update.effective_chat.id
    user = update.effective_user
    pending = TOUR_TEAM_TEXT_PENDING.get(user.id)
    if not pending or pending.get("group_id") != group_id:
        return False

    action = pending.get("action")
    text = update.message.text.strip()

    if action == "create":
        team_name = text
        if not team_name:
            return True
        teams = tournament_teams.setdefault(group_id, {})
        if team_name in teams:
            await update.message.reply_text(f"⚠️ Team '<b>{html.escape(team_name)}</b>' already exists!", parse_mode=ParseMode.HTML)
            TOUR_TEAM_TEXT_PENDING.pop(user.id, None)
            return True
        teams[team_name] = {"players": [], "captain": None}
        await asyncio.to_thread(_save_tour_state_sync, group_id)
        TOUR_TEAM_TEXT_PENDING.pop(user.id, None)
        names = sorted(teams.keys())
        idx = names.index(team_name)
        kb = InlineKeyboardMarkup([[styled_button("➕ Add Players Now", callback_data=f"tour_mteam_{idx}_add"),
                                     styled_button("Back to Teams", callback_data="tour_mteams_0")]])
        await update.message.reply_text(
            f"✅ <b>Team Created!</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n🏏 {html.escape(team_name)}",
            reply_markup=kb, parse_mode=ParseMode.HTML
        )
        return True

    if action == "rename":
        old_name = pending.get("team_name")
        new_name = text
        teams = tournament_teams.get(group_id, {})
        if old_name not in teams:
            TOUR_TEAM_TEXT_PENDING.pop(user.id, None)
            await update.message.reply_text("⚠️ That team no longer exists.")
            return True
        if not new_name or new_name == old_name:
            TOUR_TEAM_TEXT_PENDING.pop(user.id, None)
            return True
        if new_name in teams:
            await update.message.reply_text(f"⚠️ A team named '<b>{html.escape(new_name)}</b>' already exists!", parse_mode=ParseMode.HTML)
            TOUR_TEAM_TEXT_PENDING.pop(user.id, None)
            return True
        if tournament_fixtures.get(group_id):
            await update.message.reply_text(
                "⚠️ Fixtures are already generated for this tournament — renaming now would break "
                "existing match references. Use <code>/tourend</code> and start fresh if you need to rename.",
                parse_mode=ParseMode.HTML
            )
            TOUR_TEAM_TEXT_PENDING.pop(user.id, None)
            return True

        teams[new_name] = teams.pop(old_name)
        grp_map = tournament_groups.get(group_id, {})
        if old_name in grp_map:
            grp_map[new_name] = grp_map.pop(old_name)
        pts_map = tournament_points.get(group_id, {})
        if old_name in pts_map:
            pts_map[new_name] = pts_map.pop(old_name)
        await asyncio.to_thread(_save_tour_state_sync, group_id)
        TOUR_TEAM_TEXT_PENDING.pop(user.id, None)
        kb = InlineKeyboardMarkup([[styled_button("Back to Teams", callback_data="tour_mteams_0")]])
        await update.message.reply_text(
            f"✅ Renamed <b>{html.escape(old_name)}</b> → <b>{html.escape(new_name)}</b>",
            reply_markup=kb, parse_mode=ParseMode.HTML
        )
        return True

    if action == "addplayer":
        team_name = pending.get("team_name")
        teams = tournament_teams.get(group_id, {})
        if team_name not in teams:
            TOUR_TEAM_TEXT_PENDING.pop(user.id, None)
            await update.message.reply_text("⚠️ That team no longer exists.")
            return True

        mentioned_users = []
        if update.message.reply_to_message and update.message.reply_to_message.from_user:
            ru = update.message.reply_to_message.from_user
            mentioned_users.append({"user_id": ru.id, "username": ru.username or "", "first_name": ru.first_name})

        entities = update.message.entities or []
        for entity in entities:
            if entity.type == "mention":
                username = update.message.text[entity.offset + 1:entity.offset + entity.length]
                try:
                    cm = await context.bot.get_chat_member(group_id, f"@{username}")
                    mentioned_users.append({"user_id": cm.user.id, "username": cm.user.username or "", "first_name": cm.user.first_name})
                except Exception:
                    pass
            elif entity.type == "text_mention" and entity.user:
                mentioned_users.append({"user_id": entity.user.id, "username": entity.user.username or "", "first_name": entity.user.first_name})

        for arg in text.split():
            if arg.isdigit():
                try:
                    cm = await context.bot.get_chat_member(group_id, int(arg))
                    mentioned_users.append({"user_id": cm.user.id, "username": cm.user.username or "", "first_name": cm.user.first_name})
                except Exception:
                    pass

        if not mentioned_users:
            await update.message.reply_text(
                "⚠️ Couldn't find a player there. Reply to their message, or send @username / user_id.",
                parse_mode=ParseMode.HTML
            )
            return True

        team_data = teams[team_name]
        existing_ids = {p["user_id"] for p in team_data["players"]}
        added, not_started = [], []
        for p in mentioned_users:
            if p["user_id"] in existing_ids:
                continue
            started = await check_user_started_bot(context.bot, p["user_id"])
            if not started:
                not_started.append(p["first_name"])
            team_data["players"].append(p)
            existing_ids.add(p["user_id"])
            added.append(p["first_name"])

        if added:
            await asyncio.to_thread(_save_tour_state_sync, group_id)
        TOUR_TEAM_TEXT_PENDING.pop(user.id, None)

        msg = f"✅ <b>Players Added — {html.escape(team_name)}</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        msg += f"✅ Added: {', '.join(added)}\n" if added else "⚠️ No new players added (already in team?)\n"
        if not_started:
            bot_username = context.bot.username
            msg += (f"\n⚠️ <b>Hasn't started bot:</b> {', '.join(not_started)}\n"
                    f"👉 <a href='https://t.me/{bot_username}'>@{bot_username}</a>")
        kb = InlineKeyboardMarkup([[styled_button("➕ Add More", callback_data=f"tour_mteams_0"),
                                     styled_button("Done", callback_data="tour_mteams_0")]])
        await update.message.reply_text(msg, reply_markup=kb, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
        return True

    if action == "linkcode":
        TOUR_TEAM_TEXT_PENDING.pop(user.id, None)
        code = text.strip().upper()
        primary_group_id = TOUR_LINK_CODES.get(code)
        kb = InlineKeyboardMarkup([[styled_button("🔙 Back", callback_data="tour_linkmenu")]])
        if not primary_group_id:
            await update.message.reply_text("❌ <b>Invalid or expired code!</b>", reply_markup=kb, parse_mode=ParseMode.HTML)
            return True
        if primary_group_id == group_id:
            await update.message.reply_text("❌ Can't link a group to itself!", reply_markup=kb, parse_mode=ParseMode.HTML)
            return True
        if tournament_teams.get(group_id) and group_id not in TOUR_GROUP_ALIAS:
            await update.message.reply_text(
                "⚠️ <b>THIS GROUP ALREADY HAS ITS OWN TOURNAMENT DATA!</b>\n\n"
                "Linking would hide it behind the other tournament's data. End this group's "
                "tournament first (End Tour), then link.",
                reply_markup=kb, parse_mode=ParseMode.HTML
            )
            return True
        link_tour_group(group_id, primary_group_id)
        await update.message.reply_text(
            "✅ <b>LINKED!</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\nThis group now shares its tournament "
            "(teams, fixtures, points table, player stats) with the linked group.",
            reply_markup=kb, parse_mode=ParseMode.HTML
        )
        return True

    TOUR_TEAM_TEXT_PENDING.pop(user.id, None)
    return False


async def handle_manual_result_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """Call this FIRST inside handle_group_input. Returns True if the message
    was consumed as part of an /addresult session (runs margin or player stats)."""
    if update.effective_chat.type == "private" or not update.message or not update.message.text:
        return False

    group_id = update.effective_chat.id
    user = update.effective_user
    session = manual_result_sessions.get(group_id)
    if not session or session["user_id"] != user.id:
        return False

    text = update.message.text.strip()

    if session["stage"] in ("score1_text", "score2_text"):
        parts = text.split()
        if len(parts) != 2:
            await update.message.reply_text(
                "⚠️ Format: <code>runs overs.balls</code> — e.g. <code>145 9.4</code>",
                parse_mode=ParseMode.HTML,
            )
            return True
        runs_s, overs_s = parts
        try:
            runs = int(runs_s)
            actual_overs = _parse_cricket_overs(overs_s)
        except ValueError:
            await update.message.reply_text(
                "⚠️ Couldn't read that. Format: <code>runs overs.balls</code> — "
                "e.g. <code>145 9.4</code> (balls part must be 0-5).",
                parse_mode=ParseMode.HTML,
            )
            return True
        # 🩹 BUGFIX: negative runs (e.g. a stray "-" typo) used to be accepted
        # as-is, silently corrupting the score used for NRR and the fixture
        # result — with no warning until the points table looked wrong.
        if runs < 0:
            await update.message.reply_text("⚠️ Runs can't be negative — please re-enter.")
            return True

        if session["stage"] == "score1_text":
            session["score1"] = runs
            session["overs1"] = actual_overs
            session["stage"] = "score2_text"
            t2 = session["team2"]
            allotted = session.get("overs")
            await update.message.reply_text(
                f"✅ <b>{html.escape(session['team1'])}</b>: {runs}/? in {overs_s} overs\n"
                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                f"✏️ Now reply with <b>{html.escape(t2)}</b>'s score and overs actually played "
                f"(format: <code>runs overs.balls</code>)\n\n"
                f"e.g. <code>150 {allotted}.0</code> if they batted the full quota, "
                f"or <code>90 7.4</code> if all out in 7 overs 4 balls.",
                parse_mode=ParseMode.HTML,
            )
            return True
        else:
            session["score2"] = runs
            session["overs2"] = actual_overs
            session["stage"] = "winner"
            t1, t2 = session["team1"], session["team2"]
            kb = [
                [styled_button(t1, callback_data="mres_win_t1")],
                [styled_button(t2, callback_data="mres_win_t2")],
                [styled_button("Tie", callback_data="mres_win_tie")],
                [styled_button("Cancel", callback_data="mres_cancel")],
            ]
            await update.message.reply_text(
                f"⚔️ <b>{html.escape(t1)} {session['score1']}</b> vs <b>{html.escape(t2)} {runs}</b>\n\n"
                f"🏆 Who won?",
                reply_markup=InlineKeyboardMarkup(kb), parse_mode=ParseMode.HTML,
            )
            return True

    if session["stage"] == "margin_runs_text":
        try:
            n = int(text)
        except ValueError:
            await update.message.reply_text("⚠️ Send a number, e.g. 20")
            return True
        session["margin_text"] = f"by {n} run{'s' if n != 1 else ''}"
        session["stage"] = "player_stats"
        await _mres_advance_to_stats(update.message, context, group_id, edit=False)
        return True

    if session["stage"] == "player_stats":
        parts = text.split()
        # 🩹 BUGFIX: no length/sign validation here before — a typo like an
        # extra number ("41 0 2 3 5") got silently truncated to the first 4
        # values with no warning, and negative numbers were accepted as-is,
        # both quietly corrupting a player's saved match stats with no way
        # for the admin to notice until much later on the leaderboard.
        if not (1 <= len(parts) <= 4):
            await update.message.reply_text(
                "⚠️ Format: <code>runs wickets sixes fours</code> (1-4 numbers) — e.g. <code>41 0 2 3</code>",
                parse_mode=ParseMode.HTML,
            )
            return True
        try:
            vals = [int(p) for p in parts]
        except ValueError:
            await update.message.reply_text("⚠️ Format: runs wickets sixes fours — e.g. 41 0 2 3")
            return True
        if any(v < 0 for v in vals):
            await update.message.reply_text("⚠️ Stats can't be negative — please re-enter.")
            return True
        vals += [0] * (4 - len(vals))
        runs, wkts, sixes, fours = vals[:4]
        uid = session["squad"][session["idx"]][0]
        session["stats"][uid] = {"runs": runs, "wkts": wkts, "sixes": sixes, "fours": fours}
        session["idx"] += 1
        await _mres_advance_to_stats(update.message, context, group_id, edit=False)
        return True

    return False


async def tourresult_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Record tournament match result: /tourresult [winning_team]"""
    chat = update.effective_chat
    user = update.effective_user
    group_id = chat.id
    
    if chat.type == "private":
        return
    
    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return
    
    member = await context.bot.get_chat_member(group_id, user.id)
    if member.status not in ["administrator", "creator"]:
        await update.message.reply_text("🚫 Only admins can record results!")
        return
    
    if group_id not in pending_tour_match:
        await update.message.reply_text("⚠️ No active tournament match found!")
        return
    
    if not context.args:
        await update.message.reply_text(
            "📋 Usage: <code>/tourresult [winning team name]</code>\nOr <code>/tourresult tie</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    tm = pending_tour_match[group_id]
    t1 = tm["team1"]
    t2 = tm["team2"]
    match_id = tm["match_id"]
    winner_arg = " ".join(context.args).strip().lower()

    # 🩹 BUGFIX: matches already auto-record their result the moment they
    # finish (record_tour_match_result), which also clears
    # pending_tour_match[group_id] — so by the time an admin could type
    # /tourresult for an already-finished match, this guard normally
    # wouldn't even be reached. But nothing stopped an admin from running
    # /tourresult twice in a row (or after a manual /addresult) for the
    # SAME still-pending fixture, which added a second set of
    # played/won/lost/pts to both teams every time — silently corrupting
    # the points table. Block re-recording a fixture that already has a
    # result.
    for _fix in tournament_fixtures.get(group_id, []):
        if _fix.get("match_id") == match_id and _fix.get("result"):
            await update.message.reply_text(
                f"⚠️ This match was already recorded as: <b>{_fix['result']}</b>\n"
                f"Use /tourfixtures to check, or contact the bot owner if this needs correcting.",
                parse_mode=ParseMode.HTML
            )
            del pending_tour_match[group_id]
            return

    pts = tournament_points[group_id]
    for tn in [t1, t2]:
        if tn not in pts:
            pts[tn] = _default_team_stats()
    
    # 🩹 playoff fixtures must not touch the league table (see
    # _tour_skip_league_points)
    _skip_pts = _tour_skip_league_points(group_id, match_id)

    if winner_arg == "tie":
        if not _skip_pts:
            pts[t1]["played"] += 1
            pts[t2]["played"] += 1
            pts[t1]["tied"] += 1
            pts[t2]["tied"] += 1
            pts[t1]["pts"] += 1
            pts[t2]["pts"] += 1
        result_str = "Tie"
    else:
        # Match team name — 🩹 exact match first; substring-only matching
        # picked the wrong team for short/overlapping names (e.g. "CSK" vs
        # "CSK Kings"), and the points went to the loser.
        winner = None
        for tn in [t1, t2]:
            if tn.lower() == winner_arg:
                winner = tn
                break
        if winner is None:
            _cands = [tn for tn in (t1, t2) if winner_arg in tn.lower()]
            if len(_cands) == 1:
                winner = _cands[0]
            elif len(_cands) > 1:
                await update.message.reply_text(
                    f"⚠️ '{html.escape(winner_arg)}' matches both teams — type the full team name: {html.escape(t1)} / {html.escape(t2)}",
                    parse_mode=ParseMode.HTML
                )
                return
        
        if not winner:
            await update.message.reply_text(f"⚠️ Team not found! Valid teams: {t1}, {t2}")
            return
        
        loser = t2 if winner == t1 else t1
        if not _skip_pts:
            pts[winner]["played"] += 1
            pts[loser]["played"] += 1
            pts[winner]["won"] += 1
            pts[loser]["lost"] += 1
            pts[winner]["pts"] += 2
        result_str = f"{winner} won"
    
    # Update fixture
    for fix in tournament_fixtures[group_id]:
        if fix["match_id"] == match_id:
            fix["result"] = result_str
            break
    _final_pair = _tour_maybe_create_playoff_final(group_id)
    
    del pending_tour_match[group_id]

    # 🩹 BUGFIX: same restart-data-loss issue as record_tour_match_result —
    # await the write instead of firing-and-forgetting it, so this /tourresult
    # entry can never be silently rolled back by a restart.
    await asyncio.to_thread(_save_tour_state_sync, group_id)

    await update.message.reply_text(
        f"✅ <b>RESULT RECORDED!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"⚔️ <b>{t1}</b> vs <b>{t2}</b>\n"
        f"🏆 <b>Result:</b> {result_str}\n\n"
        f"Points table has been updated!"
        + (f"\n\n🏆 <b>FINAL SET:</b> {html.escape(_final_pair[0])} vs {html.escape(_final_pair[1])}" if _final_pair else ""),
        parse_mode=ParseMode.HTML
    )


async def tourlb_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Tournament leaderboard: /tourlb — attractive paginated image version"""
    chat = update.effective_chat
    user = update.effective_user
    group_id = chat.id

    if chat.type == "private":
        await update.message.reply_text("Use in a group!")
        return

    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return

    # 🎨 Rich-UI first (table + tabs); legacy photo card below is the fallback
    try:
        _rb, _rr = await asyncio.to_thread(_build_tourlb_page, group_id, "runs", 0, True)
        if await rc_send(group_id, _rb, _rr, reply_to=update.message.message_id if update.message else None):
            return
    except Exception:
        logger.exception("rich tourlb failed — using legacy view")

    # Build category text
    def _pname(pid):
        """🔧 FIX: leaderboard used to show raw numeric user_ids as the name
        (setdefault froze name=str(pid) forever). Resolve the real first_name
        from user_data instead, falling back to the id only if truly unknown."""
        return user_data.get(pid, {}).get("first_name") or str(pid)

    def _pad(s, w):
        s = str(s)
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))

    def _rpad(s, w):
        s = str(s)
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else (" " * (w - len(s))) + s

    metric = "runs"
    text, kb = _build_tourlb_page(group_id, metric, 0)

    # Try generate image
    try:
        img_bio = await asyncio.to_thread(generate_tour_leaderboard_image, group_id)
    except Exception:
        img_bio = None

    try:
        if img_bio:
            await update.message.reply_photo(photo=img_bio, caption=text, parse_mode=ParseMode.HTML, reply_markup=kb)
        else:
            photo = MEDIA_ASSETS.get("tournament_mode")
            await update.message.reply_photo(photo=photo, caption=text, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 6530)")
        await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)


# 📄 PAGE_SIZE for the /tourlb caption — shows ALL players, paginated instead of a hard top-10 cutoff
_TOURLB_PAGE_SIZE = 10


def _tour_resolve_name(pid, group_id, match_id=None):
    """Best-effort real name lookup for a tournament player, in order:
    1. Name captured at match-record time (works for matches played after
       this fix shipped).
    2. user_data (populated once the player DMs the bot at least once).
    3. The user_stats SQL table — this gets a real first_name written to it
       during solo/team matches even for players who never DM'd the bot, so
       it recovers names for OLDER tournament matches recorded before this
       fix, without needing any manual backfill.
    4. Falls back to the raw numeric id (only if truly nothing is known)."""
    if match_id is not None:
        nm = tour_match_stats.get(group_id, {}).get(match_id, {}).get("player_names", {}).get(pid)
        if nm:
            return nm
    nm = user_data.get(pid, {}).get("first_name") or user_data.get(str(pid), {}).get("first_name")
    if nm:
        return nm
    try:
        conn = db_connect(DB_PATH)
        c = conn.cursor()
        c.execute("SELECT first_name FROM user_stats WHERE user_id = ?", (pid,))
        row = c.fetchone()
        conn.close()
        if row and row[0] and row[0].strip() and row[0].strip().lower() != "player":
            return row[0].strip()
    except Exception:
        pass
    return str(pid)


def _build_tourlb_page(group_id: int, metric: str, page: int, rich: bool = False):
    """Builds the (caption_text, InlineKeyboardMarkup) pair for one page of the
    tournament leaderboard caption. Shows the FULL list of players for the chosen
    metric (not capped at top 10), paginated with Next/Previous, category tabs,
    and a Back button. Uses the same blockquote card style as /leaderboard."""

    # 🩹 BUGFIX: previously only checked user_data (needs the player to have
    # DM'd the bot at least once), so any tournament player who never messaged
    # the bot directly showed up as a raw numeric ID instead of their name.
    # Now falls back to the name captured at match-record time, and then to
    # the user_stats SQL table (recovers names for older matches too).
    def _pname(pid, match_id=None):
        return _tour_resolve_name(pid, group_id, match_id)

    def _name_link(uid, name):
        return f'<a href="tg://user?id={uid}">{html.escape(name)}</a>' + _title_suffix(uid)

    def _uname_disp(uid):
        u = user_data.get(uid, {}).get("username")
        return f"@{u}" if u else "—"

    def _jersey_tag(uid):
        number = user_data.get(uid, {}).get("jersey_number")
        return f"🎽#{number}" if number is not None else "🎽 Unranked"

    # 🩹 BUGFIX: after a bot restart, tour_match_stats is reloaded from the DB
    # via json.loads(), which turns all dict keys (including player_runs/
    # wickets/sixes/fours keys, originally int user_ids) into STRINGS — JSON
    # object keys are always strings. Any match recorded before a restart
    # therefore has string pids ("12345"), while any match recorded after
    # (fresh in-memory, never round-tripped through JSON) has int pids
    # (12345). setdefault(pid, ...) below then created TWO separate rows for
    # the same player instead of merging their totals — e.g. Shubh showing
    # up as both 53 runs and 10 runs instead of 63. Normalize every pid to
    # int right here so both forms collapse into the same leaderboard row.
    def _norm_pid(pid):
        try:
            return int(pid)
        except (TypeError, ValueError):
            return pid

    all_runs, all_wickets, all_sixes, all_fours = {}, {}, {}, {}
    for match_id, stats in tour_match_stats.get(group_id, {}).items():
        for raw_pid, val in stats.get("player_runs", {}).items():
            pid = _norm_pid(raw_pid)
            row = all_runs.setdefault(pid, {"pid": pid, "name": _pname(pid, match_id), "total": 0})
            row["total"] += val
        for raw_pid, val in stats.get("player_wickets", {}).items():
            pid = _norm_pid(raw_pid)
            row = all_wickets.setdefault(pid, {"pid": pid, "name": _pname(pid, match_id), "total": 0})
            row["total"] += val
        for raw_pid, val in stats.get("player_sixes", {}).items():
            pid = _norm_pid(raw_pid)
            row = all_sixes.setdefault(pid, {"pid": pid, "name": _pname(pid, match_id), "total": 0})
            row["total"] += val
        for raw_pid, val in stats.get("player_fours", {}).items():
            pid = _norm_pid(raw_pid)
            row = all_fours.setdefault(pid, {"pid": pid, "name": _pname(pid, match_id), "total": 0})
            row["total"] += val

    if metric == "wickets":
        title, unit, stat_emoji, cat_emoji = "TOP WICKET TAKERS", "Wickets", "⚾", "⚾"
        data = sorted(all_wickets.values(), key=lambda x: -x["total"])
    elif metric == "sixes":
        title, unit, stat_emoji, cat_emoji = "MOST SIXES", "Sixes", "🚀", "🚀"
        data = sorted(all_sixes.values(), key=lambda x: -x["total"])
    elif metric == "fours":
        title, unit, stat_emoji, cat_emoji = "MOST FOURS", "Fours", "💥", "4️⃣"
        data = sorted(all_fours.values(), key=lambda x: -x["total"])
    else:
        metric = "runs"
        title, unit, stat_emoji, cat_emoji = "TOP RUN SCORERS", "Runs", "🏏", "🏃"
        data = sorted(all_runs.values(), key=lambda x: -x["total"])

    total_players = len(data)
    total_pages = max(1, math.ceil(total_players / _TOURLB_PAGE_SIZE))
    page = max(0, min(page, total_pages - 1))
    start = page * _TOURLB_PAGE_SIZE
    page_rows = data[start:start + _TOURLB_PAGE_SIZE]

    total_matches = len(tour_match_stats.get(group_id, {}))

    if rich:
        return _tourlb_rich_view(group_id, metric, title, unit, page, total_pages, start,
                                 page_rows, total_matches, total_players)

    _RANK_MEDALS = {1: "🥇", 2: "🥈", 3: "🥉"}
    lines = [f"🏟️ Matches played: <b>{total_matches}</b>", f"👥 Players ranked: <b>{total_players}</b>", f"{stat_emoji} <b>{title}</b>"]
    if page_rows:
        for i, d in enumerate(page_rows):
            rank = start + i + 1
            pid = d["pid"]
            medal = _RANK_MEDALS.get(rank, f"#{rank}")
            lines.append(f"{medal} <b>#{rank}</b> {_name_link(pid, d['name'])} · {stat_emoji} <b>{d['total']}</b> {unit}")
        lines.append(f"📄 Page <b>{page + 1}/{total_pages}</b>")
    else:
        lines.append("📭 No data yet. Complete some matches first.")
    text = themed("TOURNAMENT LEADERBOARD", lines, "🏃‍♀️")

    rows = [
        [styled_button("Runs",    callback_data=f"tourlb_{group_id}_runs_0"),
         styled_button("Wickets", callback_data=f"tourlb_{group_id}_wickets_0")],
        [styled_button("Sixes",   callback_data=f"tourlb_{group_id}_sixes_0"),
         styled_button("4⃣ Fours",   callback_data=f"tourlb_{group_id}_fours_0")],
    ]

    nav_row = []
    if page > 0:
        nav_row.append(styled_button("Previous", callback_data=f"tourlb_{group_id}_{metric}_{page - 1}"))
    if page < total_pages - 1:
        nav_row.append(styled_button("Next", callback_data=f"tourlb_{group_id}_{metric}_{page + 1}"))
    if nav_row:
        rows.append(nav_row)

    rows.append([styled_button("Back", callback_data="mode_tournament")])

    return text, InlineKeyboardMarkup(rows)


def _solo_board_render(match):
    """Build the compact Solo Battle lobby card."""
    count = len(match.solo_players)
    remaining = max(0, int(match.solo_join_end_time - time.time()))
    mins, secs = divmod(remaining, 60)

    if match.host_id and match.host_name:
        host_tag = f'<a href="tg://user?id={match.host_id}">{html.escape(match.host_name)}</a>' + _title_suffix(match.host_id)
    else:
        host_tag = "Unknown"

    SOLO_LINEUP_SIZE = 11
    number_emojis = ["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟"]

    msg = "🏏 <b>SOLO BATTLE</b>\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += f"Host: {host_tag}\n"
    msg += f"Time left: <b>{mins:02d}:{secs:02d}</b>\n"
    msg += f"Players: <b>{count}/{SOLO_LINEUP_SIZE}</b>\n\n"
    msg += "<b>Playing XI</b>\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"

    if match.solo_players:
        for i, player in enumerate(match.solo_players, 1):
            jnum = jersey_number_prefix(player.user_id)
            ptag = f'<a href="tg://user?id={player.user_id}">{jnum}{html.escape(player.first_name)}</a>' + _title_suffix(player.user_id)
            crown = " 👑" if match.host_id and player.user_id == match.host_id else ""
            emoji = number_emojis[i - 1] if i <= len(number_emojis) else f"{i}."
            msg += f"{emoji} {ptag}{crown}\n"
    else:
        msg += "<i>Waiting for players...</i>\n"

    msg = msg.rstrip("\n")
    keyboard = [
        [styled_button("Join Battle", callback_data="solo_join"),
         styled_button("Leave", callback_data="solo_leave")]
    ]
    if count >= 2:
        keyboard.append([styled_button("START MATCH", callback_data="solo_start_game")])

    return msg, keyboard


async def bump_solo_board(context, chat_id, match):
    """Deletes and resends the solo joining board so it resurfaces at the
    bottom of the chat instead of staying buried above newer messages."""
    msg, keyboard = _solo_board_render(match)
    await refresh_game_message(context, chat_id, match, msg, InlineKeyboardMarkup(keyboard), media_key="joining")


async def update_solo_board(context, chat_id, match, _force=False):
    """
    Updates the Solo Joining List in place, IMMEDIATELY (no throttle) so
    joins/leaves show up in the group the moment someone taps a button.
    Bumping the message back to the bottom of the chat is handled
    separately (see bump_solo_board / solo_join_countdown), every 30s.
    """
    if not match.main_message_id:
        # No message yet — send the first one.
        msg, keyboard = _solo_board_render(match)
        await refresh_game_message(context, chat_id, match, msg, InlineKeyboardMarkup(keyboard), media_key="joining")
        return

    msg, keyboard = _solo_board_render(match)
    reply_markup = InlineKeyboardMarkup(keyboard)

    try:
        await context.bot.edit_message_caption(
            chat_id=chat_id,
            message_id=match.main_message_id,
            caption=msg,
            reply_markup=reply_markup,
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        error_str = str(e).lower()
        if "message is not modified" in error_str:
            return
        try:
            await context.bot.edit_message_text(
                chat_id=chat_id,
                message_id=match.main_message_id,
                text=msg,
                reply_markup=reply_markup,
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass

async def start_team_mode(query, context: ContextTypes.DEFAULT_TYPE, chat, user):
    """Initialize team mode — Host Selection happens FIRST (first tap wins), THEN joining opens."""
    # Create new match (host not decided yet)
    match = Match(chat.id, chat.title)
    active_matches[chat.id] = match
    try:
        await notify_group_game_started(context, chat.id, chat.title)
    except Exception:
        pass

    match.phase = GamePhase.HOST_SELECTION
    match.host_id = None
    match.host_name = None

    keyboard = [[styled_button("‍ I Want to be Host", callback_data="team_pick_host")]]
    reply_markup = InlineKeyboardMarkup(keyboard)

    host_text = themed(
        "HOST SELECTION",
        [
            "<i>The Host controls match settings, overs and team edits.</i>",
            "⚡ First tap becomes the Host.",
            "👇 <i>Tap below to claim the Host seat.</i>",
        ],
        "🎙️",
    )

    await refresh_game_message(context, chat.id, match, host_text, reply_markup, media_key="host")


async def team_pick_host_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """First tap on 'I Want to be Host' claims the host seat, then opens the joining board."""
    query = update.callback_query
    chat = query.message.chat
    user = query.from_user

    match = active_matches.get(chat.id)
    if not match or match.phase != GamePhase.HOST_SELECTION:
        await query.answer(plain_alert("⚠️ Host selection isn't active anymore."), show_alert=True)
        return

    if match.host_id is not None:
        await query.answer("Host already claimed!", show_alert=True)
        return

    match.host_id = user.id
    match.host_name = user.first_name
    _touch_match_activity(match)
    await query.answer(plain_alert(f"🎙️ You're the Host now!"))

    match.phase = GamePhase.TEAM_JOINING
    await _open_team_join_board(context, chat.id, match)


async def _open_team_join_board(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Open the Join Team X/Y board — called once the host is locked in."""
    # Set time (2 minutes)
    match.team_join_end_time = time.time() + get_gc_setting(match.group_id, "lobby_time", 120)

    # Buttons
    keyboard = [
        [styled_button("Join Team X", callback_data="join_team_x"),
         styled_button("Join Team Y", callback_data="join_team_y")],
        [styled_button("Leave Team", callback_data="leave_team")],
        [styled_button("Start Now (Host)", callback_data="team_start_now")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    # Fancy Text
    text = get_team_join_message(match)

    # Send using Master Function (With Image)
    await refresh_game_message(context, group_id, match, text, reply_markup, media_key="joining")

    # Start Timer
    match.join_phase_task = asyncio.create_task(
        team_join_countdown(context, group_id, match)
    )

def get_team_join_message(match: Match) -> str:
    """Build the Team Arena joining card in the compact lobby style."""
    remaining = max(0, int(match.team_join_end_time - time.time()))
    minutes, seconds = divmod(remaining, 60)
    total_p = len(match.team_x.players) + len(match.team_y.players)
    bar = "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"

    msg = (
        "🏟️ <b>TEAM ARENA</b>\n"
        f"{bar}\n"
        f"⏳ Time left: <code>{minutes:02d}:{seconds:02d}</code>\n"
        f"👥 Players joined: <b>{total_p}</b>\n"
    )

    for team, icon in ((match.team_x, "❄️"), (match.team_y, "🔥")):
        overs = format_overs(getattr(team, "balls", 0))
        msg += (
            f"\n{icon} <b>TEAM {html.escape(team.name)} ➔ "
            f"{team.score}/{team.wickets} ({overs} ov)</b>\n{bar}\n"
        )
        if team.players:
            for i, player in enumerate(team.players, 1):
                captain = " 👑" if player.user_id == team.captain_id else ""
                jnum = jersey_number_prefix(player.user_id)
                ptag = f'<a href="tg://user?id={player.user_id}">{jnum}{html.escape(player.first_name)}</a>' + _title_suffix(player.user_id)
                msg += f"• {i}. {ptag}{captain}\n"
        else:
            msg += "<i>Waiting for players...</i>\n"

    msg += "\n📢 Tap below to join your team.\n"
    msg += "🛠️ Host controls: <code>/add</code> · <code>/remove</code> · <code>/shift</code>."
    if getattr(match, "magic_ball_mode", False) or getattr(match, "game_mode", "") == "MAGICBALL":
        msg += "\n🔮 <i>Magic Ball Mode is active.</i>"
    return msg


async def _build_not_approved_notice(context: ContextTypes.DEFAULT_TYPE, chat_id: int):
    """Owner + group-admins tagged notice for premium-only features (Registration/Auction/Tournament).
    Returns (text, reply_markup) — reply_markup has a direct 'Contact Owner' button."""
    owner_tag = f'<a href=\"tg://user?id={OWNER_ID}\">Owner</a>'
    admin_tags = []
    try:
        admins = await context.bot.get_chat_administrators(chat_id)
        for a in admins:
            if a.user.is_bot or a.user.id == OWNER_ID:
                continue
            admin_tags.append(f'<a href=\"tg://user?id={a.user.id}\">{html.escape(a.user.first_name)}</a>')
    except Exception:
        pass

    who = owner_tag
    if admin_tags:
        who += " or " + ", ".join(admin_tags)

    text = (
        f"👋 <b>Hey there!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        f"This group doesn't have premium authorization yet.\n\n"
        f"Please ask {who} to give me the authorization to use this feature.\n\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
    )
    keyboard = InlineKeyboardMarkup([[styled_button("Contact Owner", url=f"tg://user?id={OWNER_ID}")]])
    return text, keyboard


async def _is_host_or_admin(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match, user_id: int) -> bool:
    """True if the user is the lobby host OR a group admin/creator."""
    if match.host_id and user_id == match.host_id:
        return True
    try:
        member = await context.bot.get_chat_member(chat_id, user_id)
        return member.status in ("administrator", "creator")
    except Exception as e:
        logger.error(f"Admin check failed: {e}")
        return False


async def team_start_now_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🚀 Host or a group admin force-starts the team lobby early (with confirmation)."""
    query = update.callback_query
    chat_id = query.message.chat.id
    match = active_matches.get(chat_id)

    if not match or match.phase != GamePhase.TEAM_JOINING:
        await query.answer(plain_alert("⚠️ No active joining lobby!"), show_alert=True)
        return

    # 🔒 HOST-ONLY: force-start restricted to the match host (no group-admin bypass)
    if query.from_user.id != match.host_id:
        await query.answer(plain_alert("🚫 Only the host can force-start!"), show_alert=True)
        return

    total_players = len(match.team_x.players) + len(match.team_y.players)
    if total_players < 4:
        await query.answer(plain_alert("⚠️ Need at least 4 players (2 per team) to start!"), show_alert=True)
        return

    await query.answer()

    # Ask for explicit Yes/No confirmation before force-starting
    confirm_keyboard = InlineKeyboardMarkup([
        [styled_button("Yes, Force Start", callback_data="team_start_confirm_yes"),
         styled_button("No, Cancel", callback_data="team_start_confirm_no")]
    ])
    try:
        await context.bot.send_message(
            chat_id=chat_id,
            text=(f"⚠️ <b>{html.escape(query.from_user.first_name)}</b> wants to force-start the match now, "
                  f"skipping the rest of the join timer.\n\n"
                  f"👥 <b>Players:</b> <code>{total_players}</code>\n\n"
                  f"❓ Force start now?"),
            parse_mode=ParseMode.HTML,
            reply_markup=confirm_keyboard
        )
    except Exception as e:
        logger.error(f"Failed to send force-start confirmation: {e}")


async def team_start_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles Yes/No confirmation for force-starting the team lobby."""
    query = update.callback_query
    chat_id = query.message.chat.id
    match = active_matches.get(chat_id)
    choice = query.data  # "team_start_confirm_yes" or "team_start_confirm_no"

    if not match or match.phase != GamePhase.TEAM_JOINING:
        await query.answer(plain_alert("⚠️ This lobby is no longer active!"), show_alert=True)
        try:
            await query.edit_message_text(
                themed("Confirmation Expired", ["The lobby is no longer active."],
                       emoji="⚠️"),
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass
        return

    # 🔒 HOST-ONLY: no group-admin bypass
    if query.from_user.id != match.host_id:
        await query.answer(plain_alert("🚫 Only the host can confirm this!"), show_alert=True)
        return

    if choice == "team_start_confirm_no":
        await query.answer(plain_alert("❌ Force-start cancelled."))
        try:
            await query.edit_message_text("❌ <b>FORCE START CANCELLED</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\nThe lobby will continue normally.",
                                           parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return

    total_players = len(match.team_x.players) + len(match.team_y.players)
    if total_players < 4:
        await query.answer(plain_alert("⚠️ Need at least 4 players (2 per team) to start!"), show_alert=True)
        return

    await query.answer(plain_alert("🚀 Starting now!"))
    try:
        await query.edit_message_text("🚀 <b>FORCE START CONFIRMED</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\nClosing registration now...",
                                       parse_mode=ParseMode.HTML)
    except Exception:
        pass

    if match.join_phase_task:
        match.join_phase_task.cancel()
    await end_team_join_phase(context, chat_id, match)


async def team_join_countdown(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Countdown timer that updates the board and auto-ends the lobby when time is up."""
    try:
        warning_sent = False
        last_bump = time.time()
        while True:
            # Stop the timer if we've left the joining phase (e.g. force-started)
            if match.phase != GamePhase.TEAM_JOINING:
                break

            # 🔧 Lobby timer is OFF by default per group (admins opt in via
            # /gcsettings). When it's off, just keep the board fresh and
            # never auto-end the lobby — host force-starts manually.
            if not get_gc_setting(group_id, "lobby_timer_enabled", False):
                await asyncio.sleep(10)
                if match.phase == GamePhase.TEAM_JOINING and time.time() - last_bump >= 30:
                    await bump_team_board(context, group_id, match)
                    last_bump = time.time()
                continue

            remaining = match.team_join_end_time - time.time()

            # 30 Seconds Warning
            if remaining <= 30 and remaining > 20 and not warning_sent:
                await context.bot.send_message(
                    group_id,
                    "⏳ Only <b>30 seconds</b> remain to join the match.",
                    parse_mode=ParseMode.HTML
                )
                warning_sent = True

            if remaining <= 0:
                await end_team_join_phase(context, group_id, match)
                break

            # Wait up to 10 seconds, but don't overshoot the deadline
            await asyncio.sleep(min(10, max(1, remaining)))

            # Re-check phase before touching the board
            if match.phase == GamePhase.TEAM_JOINING:
                # Every 30s: delete + resend so the board resurfaces at the
                # bottom of the chat (won't get buried under new messages).
                if time.time() - last_bump >= 30:
                    await bump_team_board(context, group_id, match)
                    last_bump = time.time()
                else:
                    await update_joining_board(context, group_id, match)

    except asyncio.CancelledError:
        pass
    except Exception as e:
        logger.error(f"Timer error: {e}")

async def end_team_join_phase(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """End joining phase and move straight to Over Selection.
    (Host was already locked in at /game — Team Mode / Real Cricket time — the
    lobby creator is the host from the start, so there's no separate
    "Become Host" step anymore: host phase -> joining -> over selection.)"""
    total_players = len(match.team_x.players) + len(match.team_y.players)
    
    # Min 4 Players Check
    if total_players < 4:
        await context.bot.send_message(
            chat_id=group_id,
            text="❌ <b>MATCH CANCELLED</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\nAt least 4 players are required (2 per team).",
            parse_mode=ParseMode.HTML
        )
        try: await context.bot.unpin_chat_message(group_id, match.main_message_id)
        except: pass
        del active_matches[group_id]
        return

    match.phase = GamePhase.OVER_SELECTION
    _touch_match_activity(match)
    await _send_over_selection_ui(context, group_id, match)


async def _send_over_selection_ui(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Shared over-selection UI (1-20 buttons + /over [1-50] hint), shown once the host is locked in."""
    keyboard = []
    row = []
    for i in range(1, 21):
        row.append(styled_button(f"{i}", callback_data=f"overs_{i}"))
        if len(row) == 5:
            keyboard.append(row)
            row = []
    if row:
        keyboard.append(row)
    reply_markup = InlineKeyboardMarkup(keyboard)

    host_tag = f'<a href="tg://user?id={match.host_id}">{html.escape(match.host_name or "Host")}</a>' + _title_suffix(match.host_id)
    msg = (
        f"🎙 <b>HOST: {host_tag}</b>\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        "🎯 Select the number of overs for this match.\n"
        "Buttons: <b>1 to 20 overs</b>.\n"
        "✏️ Need more? Use <code>/over [number]</code> up to 50."
    )

    await refresh_game_message(context, group_id, match, msg, reply_markup, media_key="over_selection")



# Team join/leave callback handlers
async def team_join_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle team join/leave with tagging alerts & Auto-Update"""
    query = update.callback_query

    chat = query.message.chat
    user = query.from_user

    if chat.id not in active_matches:
        await query.answer()
        return

    match = active_matches[chat.id]

    if match.phase != GamePhase.TEAM_JOINING:
        await query.answer(plain_alert("⚠️ Joining phase has ended!"), show_alert=True)
        return

    # 🚫 Bowling-timeout ban check (repeated bowling timeouts) — only blocks
    # NEW joins, never affects a match the player is already inside.
    if query.data in ("join_team_x", "join_team_y"):
        ban_left = get_bowling_ban_remaining(user.id)
        if ban_left:
            await query.answer(
                plain_alert(f"🚫 Banned from joining matches for repeated bowling timeouts. Time left: {_format_ban_remaining(ban_left)}"),
                show_alert=True
            )
            return

    # 🆕 New players must start @cricoverse_bot first (shared DB across main + clones)
    if query.data in ("join_team_x", "join_team_y") and not player_is_known(user.id):
        await require_started_main_bot(update, user, use_callback=True)
        return

    # Initialize User Data
    if user.id not in user_data:
        user_data[user.id] = {
            "user_id": user.id,
            "username": user.username or "",
            "first_name": user.first_name,
            "started_at": datetime.now().isoformat(),
            "total_matches": 0
        }
        init_player_stats(user.id)
        save_data()

    user_tag = f'<a href=\"tg://user?id={user.id}\">{html.escape(user.first_name)}</a>' + _title_suffix(user.id)
    alert_msg = ""
    popup_msg = ""
    updated = False

    # JOIN LOGIC
    if query.data == "join_team_x":
        if not match.team_x.get_player(user.id):
            if match.team_y.get_player(user.id):
                match.team_y.remove_player(user.id)

            player = Player(user.id, user.username or "", user.first_name)
            match.team_x.add_player(player)
            alert_msg = f"✅ <b>PLAYER JOINED</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n{user_tag} joined <b>Team X</b>.\nPlayers can still join until the lobby closes."
            popup_msg = "✅ You joined Team X!"
            updated = True
        else:
            popup_msg = "⚠️ You're already in Team X!"

    elif query.data == "join_team_y":
        if not match.team_y.get_player(user.id):
            if match.team_x.get_player(user.id):
                match.team_x.remove_player(user.id)

            player = Player(user.id, user.username or "", user.first_name)
            match.team_y.add_player(player)
            alert_msg = f"✅ <b>PLAYER JOINED</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n{user_tag} joined <b>Team Y</b>.\nPlayers can still join until the lobby closes."
            popup_msg = "✅ You joined Team Y!"
            updated = True
        else:
            popup_msg = "⚠️ You're already in Team Y!"

    elif query.data == "leave_team":
        if match.team_x.remove_player(user.id) or match.team_y.remove_player(user.id):
            alert_msg = f"👋 {user_tag} left the team."
            popup_msg = "👋 You left the team."
            updated = True
        else:
            popup_msg = "⚠️ You're not in any team!"

    # Popup alert to the player who tapped the button (no group spam)
    await query.answer(popup_msg, show_alert=True)

    # Update the Board (Agar change hua hai)
    if updated:
        await update_joining_board(context, chat.id, match)

