# Host selection callback
async def host_selection_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Host Selection safely with 4-20 Overs"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches:
        return
        
    match = active_matches[chat.id]
    
    # Check if someone is already host
    if match.host_id is not None:
        await query.answer("Host already selected!", show_alert=True)
        return

    # Set Host
    match.host_id = user.id
    match.host_name = user.first_name
    _touch_match_activity(match)  # Reset timer
    
    match.phase = GamePhase.OVER_SELECTION
    
    # --- LOGIC FOR 1 TO 20 OVERS ---
    keyboard = []
    row = []
    # Loop from 1 to 20 (inclusive)
    for i in range(1, 21):
        # Add button to current row
        row.append(styled_button(f"{i}", callback_data=f"overs_{i}"))
        
        # If row has 5 buttons, add it to keyboard and start new row
        if len(row) == 5:
            keyboard.append(row)
            row = []
            
    # Add any remaining buttons
    if row:
        keyboard.append(row)
    
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    # --- FIX: Generate User Tag ---
    user_tag = get_user_tag(user)
    
    msg = "🎙️ <b>HOST SELECTED</b>\n\n"
    msg += "┈" * 19 + "\n"
    msg += f"{user_tag} is now the match host.\n"
    msg += "Select the match length using the buttons below.\n"
    msg += "Use <code>/over [number]</code> for up to 50 overs."
    
    # Use Safe Refresh Function
    await refresh_game_message(context, chat.id, match, msg, reply_markup, media_key="host")

async def bet_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """💰 /bet [points] — bet fantasy points on a team to win. 1st innings only, one bet per player per match."""
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_matches:
        await update.message.reply_text("🚫 No active match found.")
        return

    match = active_matches[chat.id]

    if match.game_mode not in ("TEAM", "TOURNAMENT"):
        await update.message.reply_text("⚠️ Betting is only available in Team Mode matches.")
        return

    # 🎲 Betting window opens right after the toss (once TOSS phase is done)
    # and stays open through the 1st innings until the striker/bowler are set.
    if match.phase == GamePhase.TOSS:
        pass  # toss just completed — betting window is now open
    elif match.phase != GamePhase.MATCH_IN_PROGRESS or match.innings != 1:
        await update.message.reply_text("⏳ Bets can only be placed after the toss, during the <b>1st innings</b>.", parse_mode=ParseMode.HTML)
        return
    else:
        # ⏱️ Betting window closes the moment the striker/bowler for this
        # innings have been assigned — bets are only allowed before play starts.
        bat_team = match.current_batting_team
        bowl_team = match.current_bowling_team
        if (bat_team and bat_team.current_batsman_idx is not None) or \
           (bowl_team and bowl_team.current_bowler_idx is not None):
            await update.message.reply_text("⏳ Betting is closed — the batsman/bowler for this innings are already set.")
            return

    if user.id in match.bets:
        await update.message.reply_text("⚠️ You've already placed a bet on this match.")
        return

    if not context.args or not context.args[0].isdigit():
        await update.message.reply_text(f"ℹ️ Usage: <code>/bet [amount]</code> ({CRICOIN_SYMBOL} cricoins)", parse_mode=ParseMode.HTML)
        return

    amount = int(context.args[0])
    if amount <= 0:
        await update.message.reply_text("⚠️ Bet amount must be positive.")
        return

    init_fantasy_data(user.id, user.first_name, user.username or "")
    balance = fantasy_data[user.id]["points"]
    if amount > balance:
        await update.message.reply_text(
            f"⚠️ Insufficient cricoins! Your balance: <b>{fmt_coins(balance)}</b>", parse_mode=ParseMode.HTML
        )
        return

    # 🚫 Max 50% of current balance in a single bet.
    max_allowed = balance // 2
    if amount > max_allowed:
        await update.message.reply_text(
            f"⚠️ You can bet at most 50% of your balance — max <b>{fmt_coins(max_allowed)}</b> right now.",
            parse_mode=ParseMode.HTML
        )
        return

    entry_tax = int(round(amount * ENTRY_TAX_PCT / 100))
    stake = amount - entry_tax

    text = themed(
        "PLACE YOUR BET",
        [
            f"🎯 Amount: <b>{fmt_coins(amount)}</b>",
            f"🧾 Entry tax ({ENTRY_TAX_PCT}%): -{fmt_coins(entry_tax)}",
            f"📥 Staked: <b>{fmt_coins(stake)}</b>",
            "⚖️ Choose the team you are backing to win.",
        ],
        "💰"
    )
    keyboard = [
        [styled_button(f"{match.team_x.name}", callback_data=f"bet_X_{amount}"),
         styled_button(f"{match.team_y.name}", callback_data=f"bet_Y_{amount}")]
    ]
    await update.message.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)


async def bet_team_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle team selection for /bet [points]."""
    query = update.callback_query
    user = query.from_user
    chat = query.message.chat

    if chat.id not in active_matches:
        await query.answer("No active match found.", show_alert=True)
        return
    match = active_matches[chat.id]

    try:
        _, team_letter, amount_str = query.data.split("_")
        amount = int(amount_str)
    except Exception:
        await query.answer("Invalid bet data.", show_alert=True)
        return

    if match.phase == GamePhase.TOSS:
        pass  # toss just completed — betting window is now open
    elif match.phase != GamePhase.MATCH_IN_PROGRESS or match.innings != 1:
        await query.answer("Betting window has closed (after toss, 1st innings only).", show_alert=True)
        return
    else:
        bat_team = match.current_batting_team
        bowl_team = match.current_bowling_team
        if (bat_team and bat_team.current_batsman_idx is not None) or \
           (bowl_team and bowl_team.current_bowler_idx is not None):
            await query.answer("Betting is closed — batsman/bowler already set.", show_alert=True)
            return

    if user.id in match.bets:
        await query.answer("You've already placed a bet on this match.", show_alert=True)
        return

    init_fantasy_data(user.id, user.first_name, user.username or "")
    balance = fantasy_data[user.id]["points"]
    if amount > balance:
        await query.answer("Insufficient cricoins anymore!", show_alert=True)
        return
    if amount > balance // 2:
        await query.answer("That's more than 50% of your balance — bet rejected.", show_alert=True)
        return

    entry_tax = int(round(amount * ENTRY_TAX_PCT / 100))
    stake = amount - entry_tax

    team = match.team_x if team_letter == "X" else match.team_y
    fantasy_data[user.id]["points"] -= amount
    match.bets[user.id] = {"team": team_letter, "amount": amount, "stake": stake, "name": user.first_name}

    await query.answer(plain_alert(f"✅ Bet placed: {fmt_coins(stake)} (after tax) on {team.name}!"), show_alert=True)
    try:
        await query.edit_message_text(
            themed("BET PLACED!", [
                f"👤 {html.escape(user.first_name)}",
                f"🎯 {fmt_coins(stake)} staked on <b>{html.escape(team.name)}</b> (entry tax: {fmt_coins(entry_tax)})",
            ], emoji="💰"),
            parse_mode=ParseMode.HTML
        )
    except Exception:
        pass


async def transfer_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/transfer [amount] — send cricoins to the replied-to user, or
    /transfer @username [amount] — send to any username. 6.5% tax applies."""
    sender = update.effective_user
    args = context.args or []

    target_id = None
    target_name = None
    amount = None

    replied = update.message.reply_to_message
    if replied and replied.from_user:
        if not args or not args[0].replace('.', '', 1).isdigit():
            await update.message.reply_text(f"ℹ️ Usage: <code>/transfer [amount]</code> (as a reply) ({CRICOIN_SYMBOL} cricoins)", parse_mode=ParseMode.HTML)
            return
        target_id = replied.from_user.id
        target_name = replied.from_user.first_name
        amount = int(float(args[0]))
    else:
        if len(args) < 2 or not args[0].startswith("@") or not args[1].replace('.', '', 1).isdigit():
            await update.message.reply_text(
                f"ℹ️ Usage: <code>/transfer @username [amount]</code> or reply to someone with <code>/transfer [amount]</code>",
                parse_mode=ParseMode.HTML
            )
            return
        uname = args[0].lstrip("@").lower()
        amount = int(float(args[1]))
        # Look up a known user by username from stored fantasy profiles
        for uid, prof in fantasy_data.items():
            if (prof.get("username") or "").lower() == uname:
                target_id = uid
                target_name = prof.get("first_name", "Player")
                break
        if target_id is None:
            await update.message.reply_text(f"🚫 Couldn't find @{uname} — they need to have used the bot before.")
            return

    if amount is None or amount <= 0:
        await update.message.reply_text("⚠️ Transfer amount must be positive.")
        return

    if target_id == sender.id:
        await update.message.reply_text("⚠️ You can't transfer cricoins to yourself.")
        return

    init_fantasy_data(sender.id, sender.first_name, sender.username or "")
    init_fantasy_data(target_id, target_name or "Player")

    balance = fantasy_data[sender.id]["points"]
    if amount > balance:
        await update.message.reply_text(
            f"⚠️ Insufficient cricoins! Your balance: <b>{fmt_coins(balance)}</b>", parse_mode=ParseMode.HTML
        )
        return

    tax = int(round(amount * TRANSFER_TAX_PCT / 100))
    received = amount - tax

    fantasy_data[sender.id]["points"] -= amount
    fantasy_data[target_id]["points"] += received
    save_data()

    await update.message.reply_text(
        themed("TRANSFER COMPLETE", [
            f"👤 From: {html.escape(sender.first_name)}",
            f"👤 To: {html.escape(target_name or 'Player')}",
            f"📤 Sent: <b>{fmt_coins(amount)}</b>",
            f"🧾 Transfer tax ({TRANSFER_TAX_PCT}%): -{fmt_coins(tax)}",
            f"📥 Received: <b>{fmt_coins(received)}</b>",
        ], emoji=f"💰"),
        parse_mode=ParseMode.HTML
    )


async def give_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/give [userid] [amount]  OR reply to a user with /give [amount]
    — OWNER-ONLY. Mints cricoins directly into someone's balance (no tax,
    no deduction from anyone — unlike /transfer). Any non-owner using this
    command is silently ignored: no reply, no error, nothing — so it
    doesn't even reveal that an owner-only command exists."""
    user = update.effective_user
    if user.id != OWNER_ID:
        return  # silent ignore for everyone except the bot owner

    args = context.args or []
    target_id = None
    target_name = None
    amount = None

    replied = update.message.reply_to_message
    if replied and replied.from_user:
        if not args or not args[0].replace('.', '', 1).isdigit():
            await update.message.reply_text(
                f"ℹ️ Usage: <code>/give [amount]</code> (as a reply) or <code>/give [user_id] [amount]</code>",
                parse_mode=ParseMode.HTML
            )
            return
        target_id = replied.from_user.id
        target_name = replied.from_user.first_name
        amount = int(float(args[0]))
    else:
        if len(args) < 2 or not args[0].isdigit() or not args[1].replace('.', '', 1).isdigit():
            await update.message.reply_text(
                f"ℹ️ Usage: <code>/give [user_id] [amount]</code> or reply to someone with <code>/give [amount]</code>",
                parse_mode=ParseMode.HTML
            )
            return
        target_id = int(args[0])
        amount = int(float(args[1]))
        # Pull a display name from any known profile; fall back to the id itself
        target_name = fantasy_data.get(target_id, {}).get("first_name") or user_data.get(target_id, {}).get("first_name") or str(target_id)

    if amount is None or amount <= 0:
        await update.message.reply_text("⚠️ Amount must be positive.")
        return

    init_fantasy_data(target_id, target_name or "Player")
    fantasy_data[target_id]["points"] += amount
    save_data()

    new_balance = fantasy_data[target_id]["points"]
    await update.message.reply_text(
        themed("CRICOINS GIVEN", [
            f"👤 To: {html.escape(str(target_name or 'Player'))} (<code>{target_id}</code>)",
            f"📥 Given: <b>{fmt_coins(amount)}</b>",
            f"💰 New Balance: <b>{fmt_coins(new_balance)}</b>",
        ], emoji="🎁"),
        parse_mode=ParseMode.HTML
    )


async def resolve_match_bets(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, winner: 'Team'):
    """Pay out fantasy-point bets once the match winner is known. Winners get 2x their bet back (net profit = bet)."""
    if not match.bets:
        return
    winner_letter = "X" if winner is match.team_x else "Y"
    lines = []
    for uid, bet in match.bets.items():
        init_fantasy_data(uid, bet.get("name", "Player"))
        if bet["team"] == winner_letter:
            stake = bet.get("stake", bet["amount"])
            gross_payout = stake * 2
            win_tax = int(round(gross_payout * WIN_TAX_PCT / 100))
            net_payout = gross_payout - win_tax
            fantasy_data[uid]["points"] += net_payout
            lines.append(f"✅ {html.escape(bet.get('name','Player'))}: +{fmt_coins(net_payout)} (won, {WIN_TAX_PCT}% tax: -{fmt_coins(win_tax)})")
        else:
            lines.append(f"❌ {html.escape(bet.get('name','Player'))}: -{fmt_coins(bet['amount'])} (lost)")
    if lines:
        try:
            await context.bot.send_message(
                group_id,
                themed("BET RESULTS", lines, emoji="💰"),
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass


# ============================================================
# ⚔️ /CHALLENGE — 1v1 DUEL MODE
# Lightweight, self-contained (does not touch the Match/Team classes).
# State lives in active_challenges[group_id] as a plain dict:
# {
#   "challenger_id","challenger_name","opponent_id","opponent_name",
#   "phase": "pending" | "overs" | "toss" | "choice" | "innings1" | "innings2" | "done",
#   "message_id", "overs": int,
#   "toss_winner_id", "bat_id", "bowl_id",
#   "innings": 1|2,
#   "score": {1: int, 2: int}, "balls": {1: int, 2: int},
#   "target": int|None,
#   "pending_bowl_num": int|None,
# }
# ============================================================

def _chal_player_tag(user_id: int, name: str) -> str:
    return f'<a href="tg://user?id={user_id}">{html.escape(name)}</a>' + _title_suffix(user_id)


# ── 🔢 Unique challenge IDs (so a group can run several /challenge duels at
# once, capped at MAX_CHALLENGES_PER_GROUP). Each entry keeps its own
# "group_id" for cap-counting and for message edits — the dict key itself
# is just an incrementing int, no longer the group's chat_id. ──
_chal_id_counter = 0

def _new_chal_id() -> int:
    global _chal_id_counter
    _chal_id_counter += 1
    return _chal_id_counter

MAX_CHALLENGES_PER_GROUP = 5

def _group_challenge_count(group_id: int) -> int:
    return sum(
        1 for ch in active_challenges.values()
        if isinstance(ch, dict) and ch.get("group_id") == group_id
    )


# 🖼️ Static image used for every /challenge message (caption + buttons get edited turn by turn)
CHALLENGE_IMAGE_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "challenge.jpg")

async def _chal_send_initial(context: ContextTypes.DEFAULT_TYPE, chat_id: int, text: str, reply_markup=None):
    """Send the FIRST challenge message. Uses the static challenge.jpg as a photo (caption edited
    turn-by-turn from here on) if the file exists next to cric.py, else falls back to plain text."""
    if os.path.isfile(CHALLENGE_IMAGE_PATH):
        try:
            with open(CHALLENGE_IMAGE_PATH, "rb") as img:
                sent = await context.bot.send_photo(
                    chat_id, photo=img, caption=text, reply_markup=reply_markup, parse_mode=ParseMode.HTML
                )
            return sent.message_id, True
        except Exception as e:
            logger.error(f"Challenge image send failed, falling back to text: {e}")
    sent = await context.bot.send_message(chat_id, text, reply_markup=reply_markup, parse_mode=ParseMode.HTML)
    return sent.message_id, False


async def _chal_edit(context: ContextTypes.DEFAULT_TYPE, gid, text: str, reply_markup=None):
    """Edit the ongoing challenge message — caption if it's a photo message, text otherwise.
    Buttons and caption/text both get refreshed on every call so the single message stays live.
    `gid` is either an int group chat_id (normal /challenge, message sent by the bot into a
    chat it's in) OR a string "inl:<inline_message_id>" (challenge started via inline mode —
    Telegram sent the message on the bot's behalf into a chat the bot has no access to, so
    edits must target inline_message_id instead of chat_id+message_id)."""
    ch = active_challenges.get(gid)
    if not ch:
        return
    inline_mid = ch.get("inline_message_id")
    if not inline_mid and not ch.get("message_id"):
        return
    ch["last_activity"] = datetime.now().isoformat()  # ⏱️ any state transition counts as activity
    # 🩹 gid is now a unique per-challenge id, not necessarily the group's
    # chat_id (a group can have several challenges running at once) — the
    # real chat_id for a normal group challenge lives in ch["group_id"].
    real_chat_id = ch.get("group_id", gid)
    try:
        if inline_mid:
            if ch.get("is_photo"):
                await context.bot.edit_message_caption(
                    inline_message_id=inline_mid, caption=text,
                    reply_markup=reply_markup, parse_mode=ParseMode.HTML
                )
            else:
                await context.bot.edit_message_text(
                    inline_message_id=inline_mid, text=text,
                    reply_markup=reply_markup, parse_mode=ParseMode.HTML
                )
        elif ch.get("is_photo"):
            await context.bot.edit_message_caption(
                chat_id=real_chat_id, message_id=ch["message_id"], caption=text,
                reply_markup=reply_markup, parse_mode=ParseMode.HTML
            )
        else:
            await context.bot.edit_message_text(
                chat_id=real_chat_id, message_id=ch["message_id"], text=text,
                reply_markup=reply_markup, parse_mode=ParseMode.HTML
            )
    except Exception as e:
        logger.error(f"Challenge message edit error: {e}")


def _chal_resolve_gid(query, data: str, pos: int):
    """Resolve the active_challenges key from a chal*-prefixed callback.
    If this callback fired on a message Telegram sent via an inline result, the
    CallbackQuery carries inline_message_id directly (regardless of what's baked
    into callback_data) — use that. Otherwise fall back to the normal group_id
    embedded in callback_data at `pos` (unchanged behaviour for /challenge in groups)."""
    if getattr(query, "inline_message_id", None):
        return f"inl:{query.inline_message_id}"
    return int(data.split("_")[pos])


CHALLENGE_INACTIVITY_TIMEOUT = timedelta(minutes=5)

async def challenge_inactivity_job(context: ContextTypes.DEFAULT_TYPE):
    """⏱️ Runs every minute. Auto-ends any /challenge that's had no activity
    (no button tap / state change) for 5+ minutes — edits the message to show
    it timed out and clears the active_challenges slot so /challenge can be
    used again in that group."""
    now = datetime.now()
    for gid in list(active_challenges.keys()):
        ch = active_challenges.get(gid)
        if not ch:
            continue
        last_raw = ch.get("last_activity")
        try:
            last_activity = datetime.fromisoformat(last_raw) if last_raw else now
        except Exception:
            last_activity = now
        if now - last_activity < CHALLENGE_INACTIVITY_TIMEOUT:
            continue

        # 🏷️ Tag both players in the timeout message, per user's request —
        # not just a generic "no activity" line.
        challenger_tag = _chal_player_tag(ch.get("challenger_id"), ch.get("challenger_name") or "Player 1") if ch.get("challenger_id") else None
        opponent_tag = _chal_player_tag(ch.get("opponent_id"), ch.get("opponent_name") or "Player 2") if ch.get("opponent_id") else None
        tag_line = " & ".join(t for t in (challenger_tag, opponent_tag) if t) or "Players"
        timeout_text = themed(
            "CHALLENGE TIMED OUT",
            [
                tag_line,
                "⚠️ No activity for 5 minutes.",
                "❌ This challenge has been cancelled.",
                "Use <code>/challenge</code> to start a new one.",
            ],
            "⏱️"
        )
        real_chat_id = ch.get("group_id", gid)
        try:
            inline_mid = ch.get("inline_message_id")
            if inline_mid:
                if ch.get("is_photo"):
                    await context.bot.edit_message_caption(
                        inline_message_id=inline_mid, caption=timeout_text,
                        reply_markup=None, parse_mode=ParseMode.HTML
                    )
                else:
                    await context.bot.edit_message_text(
                        inline_message_id=inline_mid, text=timeout_text,
                        reply_markup=None, parse_mode=ParseMode.HTML
                    )
            elif ch.get("message_id"):
                if ch.get("is_photo"):
                    await context.bot.edit_message_caption(
                        chat_id=real_chat_id, message_id=ch["message_id"], caption=timeout_text,
                        reply_markup=None, parse_mode=ParseMode.HTML
                    )
                else:
                    await context.bot.edit_message_text(
                        chat_id=real_chat_id, message_id=ch["message_id"], text=timeout_text,
                        reply_markup=None, parse_mode=ParseMode.HTML
                    )
        except Exception as e:
            logger.debug(f"Challenge timeout edit failed (gid={gid}): {e}")
        finally:
            active_challenges.pop(gid, None)


async def challenge_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """⚔️ /challenge — start a 1v1 duel. Reply/@username/user_id to target someone, or no args for an open challenge."""
    chat = update.effective_chat
    user = update.effective_user

    if _group_challenge_count(chat.id) >= MAX_CHALLENGES_PER_GROUP:
        await update.message.reply_text(
            f"⚠️ Max {MAX_CHALLENGES_PER_GROUP} challenges already running in this group at once. "
            f"Wait for one to finish before starting another."
        )
        return

    target_id = None
    target_name = None

    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        ru = update.message.reply_to_message.from_user
        if not ru.is_bot and ru.id != user.id:
            target_id, target_name = ru.id, ru.first_name
    elif context.args:
        arg = context.args[0]
        if arg.startswith("@"):
            uname = arg[1:].lower()
            for uid, data in user_data.items():
                if data.get("username", "").lower() == uname:
                    target_id, target_name = uid, data.get("first_name", uname)
                    break
            # 🩹 BUGFIX: if the @username lookup failed (not found in
            # user_data — e.g. they've never messaged the bot), target_id
            # stayed None and execution silently fell through to the
            # "OPEN CHALLENGE — anyone can join" branch below. Someone
            # typing /challenge @specific_person would unknowingly end up
            # challenging the whole group instead, with zero indication
            # their target wasn't found. Tell them and stop instead.
            if target_id is None:
                await update.message.reply_text(
                    f"⚠️ Couldn't find @{arg[1:]} — they may not have started the bot yet. "
                    f"Try replying to their message instead.",
                    parse_mode=ParseMode.HTML
                )
                return
        elif arg.isdigit():
            uid_int = int(arg)
            if uid_int != user.id:
                target_id = uid_int
                target_name = user_data.get(uid_int, {}).get("first_name", str(uid_int))

    chal_id = _new_chal_id()
    active_challenges[chal_id] = {
        "group_id": chat.id,  # 🩹 real chat_id for edits — the dict key is now a unique chal_id, not chat.id
        "challenger_id": user.id, "challenger_name": user.first_name,
        "opponent_id": target_id, "opponent_name": target_name,
        "phase": "pending", "message_id": None, "is_photo": False,
        "overs": 0, "toss_winner_id": None, "bat_id": None, "bowl_id": None,
        "innings": 1, "score": {1: 0, 2: 0}, "balls": {1: 0, 2: 0},
        "target": None, "pending_bowl_num": None,
        "prev_bat_num": None, "prev_bowl_num": None,
        "last_activity": datetime.now().isoformat(),  # ⏱️ used by challenge_inactivity_job (5 min auto-timeout)
    }

    challenger_tag = _chal_player_tag(user.id, user.first_name)

    if target_id:
        text = themed(
            "CHALLENGE",
            [f"{challenger_tag} is challenging {_chal_player_tag(target_id, target_name)}!"],
            "⚔️"
        )
        keyboard = [[
            styled_button("Accept", callback_data=f"chal_accept_{chal_id}"),
            styled_button("Reject", callback_data=f"chal_reject_{chal_id}")
        ]]
    else:
        text = themed(
            "OPEN CHALLENGE",
            [
                f"{challenger_tag} is challenging anyone.",
                "Tap below to accept.",
            ],
            "⚔️"
        )
        keyboard = [[styled_button("Join Challenge", callback_data=f"chal_join_{chal_id}")]]

    mid, is_photo = await _chal_send_initial(context, chat.id, text, InlineKeyboardMarkup(keyboard))
    active_challenges[chal_id]["message_id"] = mid
    active_challenges[chal_id]["is_photo"] = is_photo


async def challenge_response_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Accept/Reject/Join taps on a /challenge."""
    query = update.callback_query
    user = query.from_user
    # query.message is None for a message Telegram sent via an inline query result
    # (the bot was never actually given that message/chat) — chat is unused below
    # anyway, this was just carried over from the group-only version.
    chat = query.message.chat if query.message else None

    data = query.data  # chal_accept_<gid> | chal_reject_<gid> | chal_join_<gid> | chal_join_inl
    parts = data.split("_")
    action = parts[1]
    gid = _chal_resolve_gid(query, data, 2)

    if gid not in active_challenges or active_challenges[gid]["phase"] != "pending":
        await query.answer("This challenge is no longer active.", show_alert=True)
        return
    ch = active_challenges[gid]

    if action == "reject":
        if user.id != ch["opponent_id"]:
            await query.answer("Only the challenged player can reject.", show_alert=True)
            return
        await query.answer("Challenge declined.")
        del active_challenges[gid]
        await _chal_edit(context, gid, f"❌ Challenge declined by {_chal_player_tag(user.id, user.first_name)}.")
        return

    if action == "accept":
        if user.id != ch["opponent_id"]:
            await query.answer("Only the challenged player can accept.", show_alert=True)
            return
        await query.answer("Challenge accepted!")

    elif action == "join":
        if ch["opponent_id"] is not None:
            await query.answer("Someone already joined!", show_alert=True)
            return
        if user.id == ch["challenger_id"]:
            await query.answer("You can't join your own challenge!", show_alert=True)
            return
        ch["opponent_id"] = user.id
        ch["opponent_name"] = user.first_name
        await query.answer("Joined!")

    # Move to overs-selection phase — the CHALLENGER picks overs (1-4)
    ch["phase"] = "overs"
    text = (
        f"🎯 <b>{_chal_player_tag(ch['challenger_id'], ch['challenger_name'])}</b> vs "
        f"<b>{_chal_player_tag(ch['opponent_id'], ch['opponent_name'])}</b>\n"
        f"{html.escape(ch['challenger_name'])}, select the number of overs."
    )
    keyboard = [[styled_button(f"{n}", callback_data=f"chalovers_{gid}_{n}") for n in range(1, 5)]]
    await _chal_edit(context, gid, text, InlineKeyboardMarkup(keyboard))


async def challenge_overs_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    user = query.from_user
    data = query.data
    gid = _chal_resolve_gid(query, data, 1)
    overs = int(data.rsplit("_", 1)[-1])

    if gid not in active_challenges or active_challenges[gid]["phase"] != "overs":
        await query.answer("Session expired.", show_alert=True)
        return
    ch = active_challenges[gid]

    if user.id != ch["challenger_id"]:
        await query.answer("Only the challenger selects the overs.", show_alert=True)
        return

    ch["overs"] = overs
    ch["phase"] = "toss"
    await query.answer(f"{overs} overs set!")

    # Toss: the CHALLENGED player calls heads/tails
    text = (
        f"🪙 <b>TOSS TIME</b>\n\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"Format: <b>{overs} over{'s' if overs != 1 else ''}</b>\n"
        f"{_chal_player_tag(ch['opponent_id'], ch['opponent_name'])}, make your call."
    )
    keyboard = [[
        styled_button("Heads", callback_data=f"chaltoss_{gid}_heads"),
        styled_button("Tails", callback_data=f"chaltoss_{gid}_tails")
    ]]
    await _chal_edit(context, gid, text, InlineKeyboardMarkup(keyboard))


async def challenge_toss_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    user = query.from_user
    data = query.data
    gid = _chal_resolve_gid(query, data, 1)
    call = data.rsplit("_", 1)[-1]

    if gid not in active_challenges or active_challenges[gid]["phase"] != "toss":
        await query.answer("Session expired.", show_alert=True)
        return
    ch = active_challenges[gid]

    if user.id != ch["opponent_id"]:
        await query.answer("Only the challenged player calls the toss.", show_alert=True)
        return

    result = random.choice(["heads", "tails"])
    winner_id = ch["opponent_id"] if call == result else ch["challenger_id"]
    winner_name = ch["opponent_name"] if call == result else ch["challenger_name"]
    ch["toss_winner_id"] = winner_id
    ch["phase"] = "choice"
    await query.answer(f"It's {result}!")

    text = themed(
        f"TOSS: {result.upper()}!",
        [
            f"🏆 {_chal_player_tag(winner_id, winner_name)} won the toss.",
            "🎯 Choose to bat or bowl.",
        ],
        "🪙"
    )
    keyboard = [[
        styled_button("Bat", callback_data=f"chalchoice_{gid}_bat"),
        styled_button("Bowl", callback_data=f"chalchoice_{gid}_bowl")
    ]]
    await _chal_edit(context, gid, text, InlineKeyboardMarkup(keyboard))


async def challenge_choice_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    user = query.from_user
    data = query.data
    gid = _chal_resolve_gid(query, data, 1)
    choice = data.rsplit("_", 1)[-1]

    if gid not in active_challenges or active_challenges[gid]["phase"] != "choice":
        await query.answer("Session expired.", show_alert=True)
        return
    ch = active_challenges[gid]

    if user.id != ch["toss_winner_id"]:
        await query.answer("Only the toss winner chooses.", show_alert=True)
        return

    other_id = ch["opponent_id"] if user.id == ch["challenger_id"] else ch["challenger_id"]
    other_name = ch["opponent_name"] if user.id == ch["challenger_id"] else ch["challenger_name"]

    if choice == "bat":
        ch["bat_id"], ch["bowl_id"] = user.id, other_id
    else:
        ch["bowl_id"], ch["bat_id"] = user.id, other_id

    await query.answer(f"Chose to {choice}!")
    ch["phase"] = "innings1"
    ch["innings"] = 1
    ch["pending_bowl_num"] = None
    await _ask_challenge_bowler(context, gid)


async def _bat_bowl_names(gid: int):
    ch = active_challenges[gid]
    bat_name = ch["challenger_name"] if ch["bat_id"] == ch["challenger_id"] else ch["opponent_name"]
    bowl_name = ch["challenger_name"] if ch["bowl_id"] == ch["challenger_id"] else ch["opponent_name"]
    return bat_name, bowl_name


def _challenge_overs_str(gid: int) -> str:
    ch = active_challenges[gid]
    inn = ch["innings"]
    balls = ch["balls"][inn]
    return f"{balls // 6}.{balls % 6}"


def _challenge_turn_text(gid: int, turn_role: str) -> str:
    """Build the compact themed turn prompt for a challenge innings."""
    ch = active_challenges[gid]
    inn = ch["innings"]
    bat_name = ch["challenger_name"] if ch["bat_id"] == ch["challenger_id"] else ch["opponent_name"]
    bowl_name = ch["challenger_name"] if ch["bowl_id"] == ch["challenger_id"] else ch["opponent_name"]
    bat_tag = _chal_player_tag(ch["bat_id"], bat_name)
    bowl_tag = _chal_player_tag(ch["bowl_id"], bowl_name)
    score = ch["score"][inn]
    overs_str = _challenge_overs_str(gid)

    prompt = [f"Score: <b>{score}</b>", f"Over: <b>{overs_str}</b>"]
    if inn == 2 and ch["target"] is not None:
        prompt.append(f"Target: <b>{ch['target']}</b>")

    prev_bat = ch.get("prev_bat_num")
    prev_bowl = ch.get("prev_bowl_num")
    if prev_bat is not None or prev_bowl is not None:
        prompt.append(f"Last ball: {html.escape(bat_name)} {prev_bat if prev_bat is not None else '-'} | {html.escape(bowl_name)} {prev_bowl if prev_bowl is not None else '-'}")

    if turn_role == "bowl":
        prompt.append(f"🎯 {bowl_tag}, your turn to bowl.")
    else:
        prompt.append(f"🏏 {bat_tag}, pick your number.")
    return "\n".join(prompt)


def _chal_surrender_row(gid) -> list:
    """🏳️ Surrender button row — only for normal group challenges (inline
    challenges have no group chat to post the confirmation into)."""
    if isinstance(gid, int):
        return [[styled_button("🏳️ Surrender", callback_data=f"chalsurr_{gid}")]]
    return []


async def _ask_challenge_bowler(context: ContextTypes.DEFAULT_TYPE, gid: int):
    ch = active_challenges[gid]
    text = _challenge_turn_text(gid, "bowl")
    keyboard = [[styled_button(f"{n}", callback_data=f"chalbowl_{gid}_{n}") for n in range(1, 4)],
                [styled_button(f"{n}", callback_data=f"chalbowl_{gid}_{n}") for n in range(4, 7)]]
    keyboard += _chal_surrender_row(gid)
    await _chal_edit(context, gid, text, InlineKeyboardMarkup(keyboard))


async def challenge_bowl_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    user = query.from_user
    data = query.data
    gid = _chal_resolve_gid(query, data, 1)
    num = int(data.rsplit("_", 1)[-1])

    if gid not in active_challenges or active_challenges[gid]["phase"] not in ("innings1", "innings2"):
        await query.answer("Session expired.", show_alert=True)
        return
    ch = active_challenges[gid]

    if user.id != ch["bowl_id"]:
        await query.answer("Only the bowler picks this number.", show_alert=True)
        return

    ch["pending_bowl_num"] = num
    await query.answer(f"🎯 Bowled: {num}")

    text = _challenge_turn_text(gid, "bat")
    keyboard = [[styled_button(f"{n}", callback_data=f"chalbat_{gid}_{n}") for n in range(1, 4)],
                [styled_button(f"{n}", callback_data=f"chalbat_{gid}_{n}") for n in range(4, 7)]]
    keyboard += _chal_surrender_row(gid)
    await _chal_edit(context, gid, text, InlineKeyboardMarkup(keyboard))


async def challenge_bat_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    user = query.from_user
    data = query.data
    gid = _chal_resolve_gid(query, data, 1)
    bat_num = int(data.rsplit("_", 1)[-1])

    if gid not in active_challenges or active_challenges[gid]["phase"] not in ("innings1", "innings2"):
        await query.answer("Session expired.", show_alert=True)
        return
    ch = active_challenges[gid]

    if user.id != ch["bat_id"]:
        await query.answer("Only the batter picks this number.", show_alert=True)
        return
    if ch["pending_bowl_num"] is None:
        await query.answer("Wait for the bowler!", show_alert=True)
        return

    bowl_num = ch["pending_bowl_num"]
    ch["pending_bowl_num"] = None
    inn = ch["innings"]
    ch["balls"][inn] += 1
    is_out = (bat_num == bowl_num)

    if not is_out:
        ch["score"][inn] += bat_num
        await query.answer(plain_alert(f"🏃 {bat_num} run{'s' if bat_num != 1 else ''}!"))
    else:
        await query.answer("🎯 OUT!")

    # Remember this ball as "last turn" for the next prompt
    ch["prev_bat_num"] = bat_num
    ch["prev_bowl_num"] = bowl_num

    bat_name, bowl_name = await _bat_bowl_names(gid)
    overs_str = _challenge_overs_str(gid)
    result_emoji = "🎯 <b>OUT!</b>" if is_out else f"🏃 <b>{bat_num} Run{'s' if bat_num != 1 else ''}!</b>"
    ball_result_text = (
        f"{result_emoji}\n"
        f"🏏 <b>Over : {overs_str}</b>\n\n"
        f"  🏏 Batter : {html.escape(bat_name)}\n"
        f"  🎯 Bowler : {html.escape(bowl_name)}\n\n"
        f" {html.escape(bat_name)}  Bat {bat_num}\n"
        f"{html.escape(bowl_name)} Bowl {bowl_num}"
    )
    await _chal_edit(context, gid, ball_result_text, None)

    balls_done = ch["balls"][inn]
    overs_done = balls_done >= ch["overs"] * 6
    target_chased = inn == 2 and ch["target"] is not None and ch["score"][inn] >= ch["target"]

    if is_out or overs_done or target_chased:
        await asyncio.sleep(2)
        await _end_challenge_innings(context, gid)
    else:
        await asyncio.sleep(1.5)
        await _ask_challenge_bowler(context, gid)


async def _end_challenge_innings(context: ContextTypes.DEFAULT_TYPE, gid: int):
    ch = active_challenges[gid]
    inn = ch["innings"]

    if inn == 1:
        ch["target"] = ch["score"][1] + 1
        ch["innings"] = 2
        ch["bat_id"], ch["bowl_id"] = ch["bowl_id"], ch["bat_id"]
        ch["phase"] = "innings2"
        ch["pending_bowl_num"] = None
        ch["prev_bat_num"] = None
        ch["prev_bowl_num"] = None
        bat_name, bowl_name = await _bat_bowl_names(gid)
        text = themed(
            "INNINGS BREAK",
            [
                f"🏏 Innings 1: <b>{ch['score'][1]}</b> run{'s' if ch['score'][1] != 1 else ''}.",
                f"🎯 Target for {html.escape(bat_name)}: <b>{ch['target']}</b>",
            ],
            "🔄"
        )
        await _chal_edit(context, gid, text, None)
        await asyncio.sleep(2)
        await _ask_challenge_bowler(context, gid)
        return

    # Innings 2 finished → determine winner
    score1, score2 = ch["score"][1], ch["score"][2]

    # Whoever batted in innings 1 is now bowling in innings 2; recover names directly:
    # ch["bowl_id"] currently is the innings-1 batter (roles were swapped at innings break)
    inn1_batter_id = ch["bowl_id"]
    inn1_batter_name = ch["challenger_name"] if inn1_batter_id == ch["challenger_id"] else ch["opponent_name"]
    inn2_batter_id = ch["bat_id"]
    inn2_batter_name = ch["challenger_name"] if inn2_batter_id == ch["challenger_id"] else ch["opponent_name"]
    inn1_tag = _chal_player_tag(inn1_batter_id, inn1_batter_name)
    inn2_tag = _chal_player_tag(inn2_batter_id, inn2_batter_name)

    if score2 >= ch["target"]:
        winner_id, winner_name, winner_tag = inn2_batter_id, inn2_batter_name, inn2_tag
        remaining_balls = ch['overs'] * 6 - ch['balls'][2]
        margin = f"won by {remaining_balls} ball{'s' if remaining_balls != 1 else ''} remaining"
    elif score2 < score1:
        winner_id, winner_name, winner_tag = inn1_batter_id, inn1_batter_name, inn1_tag
        run_diff = score1 - score2
        margin = f"won by {run_diff} Run{'s' if run_diff != 1 else ''}"
    else:
        winner_id, winner_name, winner_tag = None, None, None
        margin = "Match tied!"

    result_text = themed(
        "MATCH OVER",
        [
            f"🏏 {inn2_tag}: <b>{score2}</b> run{'s' if score2 != 1 else ''}.",
            f"🏏 {inn1_tag}: <b>{score1}</b> run{'s' if score1 != 1 else ''}.",
            (f"🤝 <b>{margin}</b>" if not winner_id else f"🏆 Winner: {winner_tag} — <b>{margin}</b>"),
        ],
        "🏆"
    )
    await _chal_edit(context, gid, result_text, None)

    del active_challenges[gid]


async def challenge_surrender_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏳️ Player taps Surrender mid-match — bot posts a fresh confirmation
    message tagging THAT player with Yes/No buttons (doesn't touch the live
    turn message, so match state is untouched if they cancel)."""
    query = update.callback_query
    user = query.from_user
    data = query.data  # chalsurr_<gid>
    gid = _chal_resolve_gid(query, data, 1)

    if gid not in active_challenges or active_challenges[gid]["phase"] not in ("innings1", "innings2"):
        await query.answer("This challenge isn't in a state that can be surrendered.", show_alert=True)
        return
    ch = active_challenges[gid]

    if user.id not in (ch["challenger_id"], ch["opponent_id"]):
        await query.answer("Only the two players in this challenge can surrender.", show_alert=True)
        return

    await query.answer()
    tag = _chal_player_tag(user.id, user.first_name)
    confirm_text = themed(
        "SURRENDER CHALLENGE",
        [
            f"{tag}, are you sure you want to surrender?",
            "⚠️ This ends the match immediately.",
            "🏆 Your opponent will be declared the winner.",
        ],
        "🏳️"
    )
    keyboard = [[
        styled_button("✅ Yes, surrender", callback_data=f"chalsurrconfirm_{gid}_{user.id}"),
        styled_button("❌ No, continue", callback_data=f"chalsurrcancel_{gid}_{user.id}")
    ]]
    real_chat_id = ch.get("group_id")
    if real_chat_id:
        await context.bot.send_message(
            real_chat_id, confirm_text, parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup(keyboard)
        )


async def challenge_surrender_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Yes on the surrender confirmation — end the match, opponent wins."""
    query = update.callback_query
    user = query.from_user
    data = query.data  # chalsurrconfirm_<gid>_<presser_id>
    parts = data.split("_")
    gid = int(parts[1])
    presser_id = int(parts[2])

    if user.id != presser_id:
        await query.answer("This confirmation isn't for you.", show_alert=True)
        return

    if gid not in active_challenges:
        await query.answer("This challenge already ended.", show_alert=True)
        try:
            await query.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass
        return

    ch = active_challenges[gid]
    await query.answer("Surrendered.")

    opp_id = ch["opponent_id"] if presser_id == ch["challenger_id"] else ch["challenger_id"]
    opp_name = ch["opponent_name"] if presser_id == ch["challenger_id"] else ch["challenger_name"]
    surr_name = ch["challenger_name"] if presser_id == ch["challenger_id"] else ch["opponent_name"]
    surr_tag = _chal_player_tag(presser_id, surr_name)
    opp_tag = _chal_player_tag(opp_id, opp_name)

    result_text = themed(
        "SURRENDER",
        [
            f"{surr_tag} surrendered the challenge.",
            f"🏆 Winner: {opp_tag}",
        ],
        "🏳️"
    )
    await _chal_edit(context, gid, result_text, None)
    del active_challenges[gid]

    try:
        await query.edit_message_text(
            f"✅ You surrendered — {opp_tag} wins the challenge!", parse_mode=ParseMode.HTML
        )
    except Exception:
        try:
            await query.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass


async def challenge_surrender_cancel_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """No on the surrender confirmation — match continues untouched."""
    query = update.callback_query
    user = query.from_user
    data = query.data  # chalsurrcancel_<gid>_<presser_id>
    parts = data.split("_")
    presser_id = int(parts[2])

    if user.id != presser_id:
        await query.answer("This confirmation isn't for you.", show_alert=True)
        return

    await query.answer("Cancelled.")
    try:
        await query.edit_message_text("❌ Surrender cancelled — match continues.", parse_mode=ParseMode.HTML)
    except Exception:
        try:
            await query.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass


async def over_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """✍️ /over [number] — manually pick overs (1-50) during the over-selection phase.
    Same effect as tapping an overs_N button, but lets the host go beyond the 20 shown on buttons."""
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_matches:
        await update.message.reply_text("🚫 No active match found.")
        return

    match = active_matches[chat.id]

    if match.phase != GamePhase.OVER_SELECTION:
        await update.message.reply_text("⚠️ Overs can only be set during the over-selection phase.")
        return

    if user.id != match.host_id:
        await update.message.reply_text("🚧 <b>HOST ONLY!</b> Only the host can select overs.", parse_mode=ParseMode.HTML)
        return

    if not context.args or not context.args[0].isdigit():
        await update.message.reply_text("ℹ️ Usage: <code>/over [number]</code> — between 1 and 50.", parse_mode=ParseMode.HTML)
        return

    overs = int(context.args[0])
    if not (1 <= overs <= 50):
        await update.message.reply_text("⚠️ Overs must be between 1 and 50.")
        return

    match.total_overs = overs

    # ✅ Overs picked -> dedicated Team Edit phase (Edit Team X / Edit Team Y)
    match.phase = GamePhase.TEAM_EDIT
    match.editing_team = None
    await update_team_edit_message(context, chat.id, match)

async def changeover_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """✍️ /changeover [number] — host can extend/reduce the match's total overs mid-game.
    Overs already bowled stay bowled; only the remaining-overs count is recalculated,
    since balls_remaining = (total_overs*6) - balls_bowled_so_far is derived live."""
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_matches:
        await update.message.reply_text("🚫 No active match found.")
        return

    match = active_matches[chat.id]

    if user.id != match.host_id:
        await update.message.reply_text("🚧 <b>HOST ONLY!</b> Only the host can change overs.", parse_mode=ParseMode.HTML)
        return

    if match.phase != GamePhase.MATCH_IN_PROGRESS:
        await update.message.reply_text("⏳ <b>MATCH NOT IN PROGRESS!</b> Can only change overs during an active match.", parse_mode=ParseMode.HTML)
        return

    if not context.args or not context.args[0].isdigit():
        await update.message.reply_text("ℹ️ Usage: <code>/changeover [number]</code> — between 1 and 50.", parse_mode=ParseMode.HTML)
        return

    new_overs = int(context.args[0])
    if not (1 <= new_overs <= 50):
        await update.message.reply_text("⚠️ Overs must be between 1 and 50.")
        return

    balls_bowled_now = match.current_batting_team.balls if match.current_batting_team else 0
    overs_already_bowled = balls_bowled_now // 6
    balls_into_current_over = balls_bowled_now % 6

    if new_overs * 6 < balls_bowled_now:
        await update.message.reply_text(
            f"⚠️ Can't set overs below what's already been bowled "
            f"({overs_already_bowled}.{balls_into_current_over} overs done).",
            parse_mode=ParseMode.HTML
        )
        return

    old_overs = match.total_overs
    match.total_overs = new_overs
    balls_left = (new_overs * 6) - balls_bowled_now
    overs_left = balls_left // 6
    balls_left_rem = balls_left % 6

    await update.message.reply_text(
        themed(
            "OVERS CHANGED",
            [
                f"📏 {old_overs} → <b>{new_overs}</b> overs",
                f"✅ Already bowled: {overs_already_bowled}.{balls_into_current_over} overs (unaffected)",
                f"⏳ Remaining: {overs_left}.{balls_left_rem} overs",
            ],
            "🔄",
        ),
        parse_mode=ParseMode.HTML
    )

# Captain selection callback
async def open_fantasy_squad_window(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    🏆 Announce + open the Pre-Match Fantasy Dream III picking window.
    Anyone in the group can tap player buttons below to build a fantasy
    squad (max 3 players) during the 30-second window right after captain
    selection — the toss starts automatically once the window closes.
    """
    if match.game_mode not in ("TEAM", "TOURNAMENT"):
        return

    pool = match.team_x.players + match.team_y.players
    if len(pool) < 4:
        return  # Not enough players for a meaningful fantasy contest

    match.fantasy_squads = {}
    match.fantasy_window_open = True
    match.phase = GamePhase.FANTASY_PICK

    cap = get_fantasy_squad_cap(match)

    msg = themed(
        "DREAM III",
        [
            "Build your fantasy squad before the match begins.",
            f"Pick up to <b>{cap}</b> players and earn points from their performance.",
            f"Points: +1 per run · +{FANTASY_PTS_PER_SIX_BONUS} per six · +{FANTASY_PTS_PER_WICKET} per wicket.",
            "Tap <b>My Squad</b> to review your picks.",
            f"⏳ <i>Selection closes in {FANTASY_PICK_WINDOW_SECONDS} seconds.</i>",
        ],
        "🏆"
    )

    keyboard = []
    row = []
    for p in pool:
        team_emoji = "🧊" if p in match.team_x.players else "🔥"
        btn_style = "primary" if p in match.team_x.players else "danger"
        row.append(styled_button(f"{team_emoji} {p.first_name}", callback_data=f"fpick_{group_id}_{p.user_id}", style=btn_style))
        if len(row) == 2:
            keyboard.append(row)
            row = []
    if row:
        keyboard.append(row)
    keyboard.append([styled_button("My Squad", callback_data=f"fmysquad_{group_id}", emoji_key="trophy")])

    try:
        fantasy_photo = MEDIA_ASSETS.get("fantasy") or MEDIA_ASSETS.get("squads")
        if fantasy_photo:
            sent = await context.bot.send_photo(
                chat_id=group_id,
                photo=fantasy_photo,
                caption=msg,
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup(keyboard)
            )
        else:
            sent = await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(keyboard))
        match.fantasy_announce_message_id = sent.message_id
    except Exception as e:
        logger.error(f"Error sending fantasy squad window: {e}")

    # ⏰ Auto-close the Dream III window after the pick window and move to toss
    asyncio.create_task(fantasy_window_timeout(context, group_id, match))


async def _start_captain_selection(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Show the Captain Selection board. Runs AFTER the Dream III fantasy window closes."""
    match.phase = GamePhase.CAPTAIN_SELECTION

    captain_x = match.team_x.get_player(match.team_x.captain_id)
    captain_y = match.team_y.get_player(match.team_y.captain_id)

    cap_x_name = captain_x.first_name if captain_x else "Not Selected"
    cap_y_name = captain_y.first_name if captain_y else "Not Selected"

    keyboard = [
        [styled_button("Become Captain - Team X", callback_data="captain_team_x")],
        [styled_button("Become Captain - Team Y", callback_data="captain_team_y")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    msg = "🧢 <b>CAPTAIN SELECTION</b>\n\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += f"<b>Team X:</b> {cap_x_name}\n"
    msg += f"<b>Team Y:</b> {cap_y_name}\n\n"
    msg += "<i>Tap below to lead your team.</i>"

    await refresh_game_message(context, group_id, match, msg, reply_markup, media_key="captain_selection")


async def fantasy_window_timeout(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """After the Dream III pick window expires, lock picks and move to Captain Selection."""
    await asyncio.sleep(FANTASY_PICK_WINDOW_SECONDS)

    if match.phase != GamePhase.FANTASY_PICK:
        return  # Match moved on (cancelled / ended) before the timer fired

    match.fantasy_window_open = False

    try:
        squad_count = len([s for s in match.fantasy_squads.values() if s.get("players")])
        await context.bot.send_message(
            group_id,
            f"🔒 <b>DREAM III LOCKED</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\nFantasy squads are now locked.\nSquads submitted: <b>{squad_count}</b>",
            parse_mode=ParseMode.HTML,
        )
    except Exception as e:
        logger.error(f"Error sending fantasy lock message: {e}")

    await _start_captain_selection(context, group_id, match)


async def captain_selection_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Captain Selection and move to Toss safely"""
    query = update.callback_query
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches:
        await query.answer("No active match.", show_alert=True)
        return
    
    match = active_matches[chat.id]
    
    # Check Phase
    if match.phase != GamePhase.CAPTAIN_SELECTION:
        await query.answer("Captain selection phase has ended.", show_alert=True)
        return
    
    # Logic for Team X
    if query.data == "captain_team_x":
        if not match.team_x.get_player(user.id):
            await query.answer("You must be in Team X!", show_alert=True)
            return
        if match.team_x.captain_id:
            await query.answer("Team X already has a captain.", show_alert=True)
            return
        match.team_x.captain_id = user.id
        await query.answer("You are Captain of Team X!")
    
    # Logic for Team Y
    elif query.data == "captain_team_y":
        if not match.team_y.get_player(user.id):
            await query.answer("You must be in Team Y!", show_alert=True)
            return
        if match.team_y.captain_id:
            await query.answer("Team Y already has a captain.", show_alert=True)
            return
        match.team_y.captain_id = user.id
        await query.answer("You are Captain of Team Y!")
    
    # Check if BOTH are selected
    if match.team_x.captain_id and match.team_y.captain_id:
        # ✅ FLOW: Dream III already happened before Captain Selection — go straight to Toss
        match.phase = GamePhase.TOSS
        await start_toss(query, context, match)

    else:
        # Update Message (Show who is selected)
        captain_x = match.team_x.get_player(match.team_x.captain_id)
        captain_y = match.team_y.get_player(match.team_y.captain_id)
        
        cap_x_name = captain_x.first_name if captain_x else "Not Selected"
        cap_y_name = captain_y.first_name if captain_y else "Not Selected"
        
        keyboard = [
            [styled_button("Become Captain - Team X", callback_data="captain_team_x", emoji_key="captain")],
            [styled_button("Become Captain - Team Y", callback_data="captain_team_y", emoji_key="captain")]
        ]
        reply_markup = InlineKeyboardMarkup(keyboard)
        
        msg = "🧢 <b>CAPTAIN SELECTION</b>\n\n"
        msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        msg += f"<b>Team X:</b> {cap_x_name}\n"
        msg += f"<b>Team Y:</b> {cap_y_name}\n\n"
        msg += "<i>Waiting for both captains...</i>"
        
        # ✅ FIX: Use refresh_game_message instead of risky edits
        await refresh_game_message(context, chat.id, match, msg, reply_markup, media_key="squads")

async def _finish_joining_and_proceed(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match):
    """
    ✅ Team/Real-Cricket mode: the standalone Team Edit Phase has been removed.
    Squad editing (/add, /remove, /shift) now happens ONLY during the
    TEAM_JOINING window itself. Once overs are picked, we go straight from
    joining into the Fantasy squad window (or Captain Selection if fantasy
    isn't applicable) — no separate edit step / timer in between.
    """
    if len(match.team_x.players) == 0 or len(match.team_y.players) == 0:
        try:
            await context.bot.send_message(
                chat_id,
                "⚠️ Both teams need at least one player before the match can start. "
                "Host, use <code>/add</code> to add more players.",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass
        return

    try:
        await open_fantasy_squad_window(context, chat_id, match)
    except Exception as e:
        logger.error(f"Error opening fantasy squad window: {e}")

    if match.phase != GamePhase.FANTASY_PICK:
        # Not enough players for fantasy (e.g. <4) — go straight to captain selection
        await _start_captain_selection(context, chat_id, match)


async def start_team_edit_phase(query, context: ContextTypes.DEFAULT_TYPE, match: Match):
    """Enter the dedicated Team Edit phase: Edit Team X / Edit Team Y sub-modes,
    then Done - Proceed once both squads are ready."""
    match.phase = GamePhase.TEAM_EDIT
    match.editing_team = None  # start on the main panel (neither team selected yet)

    chat_id = query.message.chat.id
    await update_team_edit_message(context, chat_id, match)


# ═══════════════════════════════════════════════════════════════
# 🆕 MID-GAME /join — request to join a match that's already running
# ═══════════════════════════════════════════════════════════════
async def join_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    🙋 Mid-game join request.
    Works while a TEAM or SOLO match is already in progress. Sends a request
    to the host, tagging them, with buttons to accept into Team X / Team Y
    (or just Accept for solo) or Reject. Spam-proofed: a user can only send
    one pending /join request per match — repeats are silently ignored.
    """
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_matches:
        await update.message.reply_text("⚠️ No active match here to join.")
        return

    match = active_matches[chat.id]

    if match.phase not in (GamePhase.MATCH_IN_PROGRESS, GamePhase.SOLO_MATCH, GamePhase.SUPER_OVER):
        await update.message.reply_text("⚠️ No match is currently in progress to join.")
        return

    # 🆕 New players must start @cricoverse_bot first (shared DB across main + clones)
    if not await require_started_main_bot(update, user, use_callback=False):
        return

    ban_left = get_bowling_ban_remaining(user.id)
    if ban_left:
        await update.message.reply_text(
            f"🚫 You're banned from joining matches for repeated bowling timeouts.\n"
            f"⏳ Time left: <b>{_format_ban_remaining(ban_left)}</b>",
            parse_mode=ParseMode.HTML
        )
        return

    # Already playing?
    if match.game_mode == "TEAM":
        if match.team_x.get_player(user.id) or match.team_y.get_player(user.id):
            await update.message.reply_text("🏏 You're already in this match!")
            return
    else:
        if any(p.user_id == user.id for p in match.solo_players):
            await update.message.reply_text("🏏 You're already in this match!")
            return

    # 🔁 One request per user per match — ignore repeat /join spam
    if user.id in match.mid_game_join_requests:
        return

    match.mid_game_join_requests.add(user.id)

    if not match.host_id:
        await update.message.reply_text("⚠️ This match has no host to approve join requests.")
        return

    host_tag = get_user_tag_by_id(match.host_id) if "get_user_tag_by_id" in globals() else f'<a href="tg://user?id={match.host_id}">Host</a>'
    requester_tag = get_user_tag(user)

    if match.game_mode == "TEAM":
        keyboard = [
            [
                styled_button("Team X", callback_data=f"midjoin_x_{user.id}"),
                styled_button("Team Y", callback_data=f"midjoin_y_{user.id}")
            ],
            [styled_button("Reject", callback_data=f"midjoin_reject_{user.id}")]
        ]
    else:
        keyboard = [
            [styled_button("Accept", callback_data=f"midjoin_solo_{user.id}")],
            [styled_button("Reject", callback_data=f"midjoin_reject_{user.id}")]
        ]

    msg = (
        f"🙋 <b>Join Request</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"👤 {requester_tag} wants to join the match!\n\n"
        f"🧢 {host_tag}, please respond:"
    )

    await update.message.reply_text(msg, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(keyboard))


async def mid_game_join_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles Team X / Team Y / Solo Accept / Reject buttons on a mid-game join request."""
    query = update.callback_query
    data = query.data  # midjoin_x_<uid> | midjoin_y_<uid> | midjoin_solo_<uid> | midjoin_reject_<uid>
    chat = query.message.chat

    if chat.id not in active_matches:
        await query.answer(plain_alert("⚠️ Match no longer active."), show_alert=True)
        return

    match = active_matches[chat.id]

    # Only the host can decide
    if query.from_user.id != match.host_id:
        await query.answer(plain_alert("🚫 Only the host can respond to this!"), show_alert=True)
        return

    parts = data.split("_")
    action = parts[1]  # x / y / solo / reject
    target_id = int(parts[2])

    await query.answer()

    # 🩹 BUGFIX: mid_game_join_requests was only ever added to, never
    # removed — so a rejected player (or even an accepted one, defensively)
    # could never send /join again for the rest of the match. join_command's
    # "one pending request" guard just silently no-ops on repeat attempts
    # with zero feedback, so a rejected player had no way to ever try again,
    # and no indication why. Clear it once the host has actually decided.
    match.mid_game_join_requests.discard(target_id)

    try:
        target_chat = await context.bot.get_chat(target_id)
        target_name = target_chat.first_name
        target_username = target_chat.username or ""
    except Exception:
        target_name = user_data.get(target_id, {}).get("first_name", "Player")
        target_username = user_data.get(target_id, {}).get("username", "")

    if action == "reject":
        await query.edit_message_text(
            f"❌ <b>{target_name}</b>'s join request was rejected by the host.",
            parse_mode=ParseMode.HTML
        )
        return

    # Double-check they haven't already joined by some other route
    already_in = False
    if match.game_mode == "TEAM":
        already_in = bool(match.team_x.get_player(target_id) or match.team_y.get_player(target_id))
    else:
        already_in = any(p.user_id == target_id for p in match.solo_players)

    if already_in:
        await query.edit_message_text(f"ℹ️ <b>{target_name}</b> is already in the match.", parse_mode=ParseMode.HTML)
        return

    new_player = Player(target_id, target_username, target_name)

    if action == "x":
        match.team_x.add_player(new_player)
        team_label = "🧊 Team X"
        joined_team = match.team_x
    elif action == "y":
        match.team_y.add_player(new_player)
        team_label = "🔥 Team Y"
        joined_team = match.team_y
    elif action == "solo":
        match.solo_players.append(new_player)
        team_label = "the match"
        joined_team = None
    else:
        return

    # 🕐 Tell them exactly when they'll actually get to play, instead of a vague
    # "welcome" — this was ambiguous before (mid-innings vs next innings).
    timing_note = ""
    if joined_team is not None:
        if joined_team is match.current_batting_team:
            timing_note = (
                "\n🏏 You've been added to the <b>end of the batting order</b> — "
                "you'll come in once the players ahead of you are out, still <b>this innings</b>."
            )
        elif joined_team is match.current_bowling_team:
            timing_note = (
                "\n⚾ You've joined the <b>bowling squad</b> — you'll be eligible to bowl "
                "from the <b>next over</b> onward."
            )
        else:
            timing_note = "\n📋 You've been added to the squad and will play from the <b>next innings</b>."

    await query.edit_message_text(
        f"✅ <b>{target_name}</b> has joined {team_label}! Welcome aboard 🏏{timing_note}",
        parse_mode=ParseMode.HTML
    )



# Add/Remove player commands (Host only)
async def add_player_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ✅ BULK ADD: Add multiple players at once
    Usage:
    - Reply: /add
    - Multiple: /add @user1 @user2 @user3
    """
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_matches:
        return
    
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.TEAM_EDIT:
        await update.message.reply_text("⚠️ Team editing inactive.")
        return
    
    # Check if Host
    if user.id != match.host_id:
        await update.message.reply_text("⚠️ Only Host can add.")
        return
    
    # Check if mode is set
    if not match.editing_team:
        await update.message.reply_text("⚠️ Please click 'Edit Team X' or 'Edit Team Y' button first!")
        return
    
    target_users = []  # List of user objects to add
    
    # Method 1: Reply to message
    if update.message.reply_to_message:
        target_users.append(update.message.reply_to_message.from_user)
    
    # Method 2: Parse mentions and IDs from command
    if update.message.entities or context.args:
        # Extract all mentions
        if update.message.entities:
            for entity in update.message.entities:
                if entity.type == "mention":
                    username = update.message.text[entity.offset:entity.offset + entity.length].replace("@", "")
                    # Find in user_data
                    for uid, data in user_data.items():
                        if data.get("username", "").lower() == username.lower():
                            try:
                                target_user = await context.bot.get_chat(uid)
                                target_users.append(target_user)
                            except Exception as e:
                                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 7564)")
                                pass
                            break
                elif entity.type == "text_mention":
                    target_users.append(entity.user)
        
        # Extract all User IDs from arguments
        if context.args:
            for arg in context.args:
                if arg.isdigit():
                    try:
                        user_id = int(arg)
                        target_user = await context.bot.get_chat(user_id)
                        target_users.append(target_user)
                    except Exception as e:
                        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 7578)")
                        pass
    
    if not target_users:
        await update.message.reply_text(
            "⚠️ <b>Usage:</b>\n"
            "Reply: <code>/add</code>\n"
            "Single: <code>/add @username</code>\n"
            "Multiple: <code>/add @user1 @user2 @user3</code>\n"
            "ID: <code>/add 123456789</code>\n"
            "Mixed: <code>/add @user1 123456 @user2</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Determine which team to add to
    if match.editing_team == "X":
        team = match.team_x
        t_name = "Team X"
    else:
        team = match.team_y
        t_name = "Team Y"
    
    # Process each user
    added_users = []
    skipped_users = []
    failed_users = []
    not_started_users = []
    penalty_banned_users = []
    
    for target_user in target_users:
        try:
            # Check duplicate
            if match.team_x.get_player(target_user.id) or match.team_y.get_player(target_user.id):
                skipped_users.append(target_user.first_name)
                continue

            # 🚫 Fully banned from the bot — can never be added
            if is_user_banned(target_user.id):
                penalty_banned_users.append(f"{target_user.first_name} (banned from the bot)")
                continue

            # 🚫 Bowling-timeout ban check — banned players can't be added by anyone
            ban_left = get_bowling_ban_remaining(target_user.id)
            if ban_left:
                penalty_banned_users.append(f"{target_user.first_name} ({_format_ban_remaining(ban_left)} left)")
                continue
            
            # ✅ Check if player has started the bot
            started = await check_user_started_bot(context.bot, target_user.id)
            if not started:
                not_started_users.append(target_user.first_name)
                # Still add but flag below

            # 🔒 Privacy: only persist a permanent profile/stats row for players
            # who have actually started the bot themselves. Others still play
            # the match normally (in-memory Player object below) but leave no
            # DB record behind.
            if started and target_user.id not in user_data:
                user_data[target_user.id] = {
                    "user_id": target_user.id,
                    "username": target_user.username or "",
                    "first_name": target_user.first_name,
                    "started_at": datetime.now().isoformat(),
                    "total_matches": 0
                }
                init_player_stats(target_user.id)
                save_data()
            
            # Add Player
            p = Player(target_user.id, target_user.username or "", target_user.first_name)
            team.add_player(p)
            added_users.append(get_user_tag(target_user))
            
        except Exception as e:
            logger.error(f"Failed to add {target_user.id}: {e}")
            failed_users.append(target_user.first_name if hasattr(target_user, 'first_name') else str(target_user.id))
    
    # Build response message
    bot_username = context.bot.username
    msg = f"📊 <b>ADD RESULT - {t_name}</b>\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    
    if added_users:
        msg += f"✅ <b>Added ({len(added_users)}):</b>\n"
        for user_tag in added_users:
            msg += f"  • {user_tag}\n"
        msg += "\n"
    
    if skipped_users:
        msg += f"⚠️ <b>Skipped ({len(skipped_users)}):</b>\n"
        for name in skipped_users:
            msg += f"  • {name} (Already in a team)\n"
        msg += "\n"
    
    if failed_users:
        msg += f"❌ <b>Failed ({len(failed_users)}):</b>\n"
        for name in failed_users:
            msg += f"  • {name} (Error fetching user)\n"
        msg += "\n"

    if penalty_banned_users:
        msg += f"🚫 <b>Banned, can't add ({len(penalty_banned_users)}):</b>\n"
        for name in penalty_banned_users:
            msg += f"  • {name} — repeated bowling timeouts\n"
        msg += "\n"
    
    if not_started_users:
        msg += (
            f"⚠️ <b>Bot not started ({len(not_started_users)}):</b>\n"
        )
        for name in not_started_users:
            msg += f"  • {name}\n"
        msg += (
            f"👉 Ask them to start: <a href='https://t.me/{bot_username}'>@{bot_username}</a>\n"
            f"<i>They can't receive bowl/bat DMs until they do!</i>\n\n"
        )
    
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += f"📈 <b>Total {t_name} Players:</b> {len(team.players)}"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
    
    # Update team edit board
    await update_team_edit_message(context, chat.id, match)

async def remove_player_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ✅ BULK REMOVE: Remove multiple players at once
    Usage:
    - Reply: /remove
    - Username: /remove @username
    - Multiple: /remove @user1 @user2 @user3
    - ID: /remove 123456789
    - Serial: /remove 1 2 3 4
    - Mixed: /remove @user1 2 @user2 123456
    """
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_matches:
        return
    
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.TEAM_EDIT:
        return
    
    if user.id != match.host_id:
        await update.message.reply_text("⚠️ Only Host can remove players.")
        return
    
    if not match.editing_team:
        await update.message.reply_text("⚠️ First Click on 'Edit Team X' or 'Edit Team Y' button")
        return
    
    target_user_ids = []  # List of user IDs to remove
    
    # Get current team
    if match.editing_team == "X":
        team = match.team_x
        team_name = "Team X"
    else:
        team = match.team_y
        team_name = "Team Y"
    
    # Method 1: Reply to message
    if update.message.reply_to_message:
        target_user_ids.append(update.message.reply_to_message.from_user.id)
    
    # Method 2: Parse mentions, IDs, and serials from command
    if update.message.entities or context.args:
        # Extract all mentions
        if update.message.entities:
            for entity in update.message.entities:
                if entity.type == "mention":
                    username = update.message.text[entity.offset:entity.offset + entity.length].replace("@", "")
                    # Find in user_data
                    for uid, data in user_data.items():
                        if data.get("username", "").lower() == username.lower():
                            target_user_ids.append(uid)
                            break
                elif entity.type == "text_mention":
                    target_user_ids.append(entity.user.id)
        
        # Extract all IDs and Serials from arguments
        if context.args:
            for arg in context.args:
                if arg.isdigit():
                    num = int(arg)
                    
                    # Check if it's a serial number (1-20 range typically)
                    if 1 <= num <= len(team.players):
                        target_player = team.get_player_by_serial(num)
                        if target_player:
                            target_user_ids.append(target_player.user_id)
                    else:
                        # Treat as User ID
                        target_user_ids.append(num)
    
    if not target_user_ids:
        await update.message.reply_text(
            "⚠️ <b>Usage:</b>\n"
            "Reply: <code>/remove</code>\n"
            "Single: <code>/remove @username</code>\n"
            "Multiple: <code>/remove @user1 @user2 @user3</code>\n"
            "ID: <code>/remove 123456789</code>\n"
            "Serial: <code>/remove 1 2 3</code>\n"
            "Mixed: <code>/remove @user1 2 123456</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Remove duplicates from target list
    target_user_ids = list(set(target_user_ids))
    
    # Process each user
    removed_users = []
    not_found_users = []
    
    for target_id in target_user_ids:
        # Get player name before removing
        player = team.get_player(target_id)
        if player:
            player_name = player.first_name
        else:
            # Try to get name from user_data
            player_name = user_data.get(target_id, {}).get("first_name", f"User {target_id}")
        
        # Try to remove
        if team.remove_player(target_id):
            removed_users.append(player_name)
        else:
            not_found_users.append(player_name)
    
    # Build response message
    msg = f"📊 <b>REMOVE RESULT - {team_name}</b>\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    if removed_users:
        msg += f"✅ <b>Removed ({len(removed_users)}):</b>\n"
        for name in removed_users:
            msg += f"  • {name}\n"
        msg += "\n"
    
    if not_found_users:
        msg += f"⚠️ <b>Not Found ({len(not_found_users)}):</b>\n"
        for name in not_found_users:
            msg += f"  • {name} (Not in {team_name})\n"
        msg += "\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += f"📈 <b>Remaining {team_name} Players:</b> {len(team.players)}"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)
    
    # Update team edit board
    await update_team_edit_message(context, chat.id, match)



# Team edit done callback
async def team_edit_done_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Finish Team Edit and start Captain Selection"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches: return
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.TEAM_EDIT:
        await query.answer("Team edit phase has ended.", show_alert=True)
        return
    
    if user.id != match.host_id:
        await query.answer("Only the Host can proceed.", show_alert=True)
        return
    
    # Validate teams
    if len(match.team_x.players) == 0 or len(match.team_y.players) == 0:
        await query.answer("Both teams need at least one player.", show_alert=True)
        return
    
    # ✅ FLOW: Team Edit ke baad ab Dream III (Fantasy) window aayega, uske baad Captain Selection
    try:
        await open_fantasy_squad_window(context, chat.id, match)
    except Exception as e:
        logger.error(f"Error opening fantasy squad window: {e}")

    if match.phase != GamePhase.FANTASY_PICK:
        # Not enough players for fantasy (e.g. <4) — go straight to captain selection
        await _start_captain_selection(context, chat.id, match)
    return

# Over selection callback
async def over_selection_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle over selection and move to Team Edit"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches:
        await query.answer("No active match found.", show_alert=True)
        return
    
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.OVER_SELECTION:
        await query.answer("Over selection phase has ended.", show_alert=True)
        return
    
    if user.id != match.host_id:
        await query.answer("Only the Host can select overs.", show_alert=True)
        return
    
    # --- LOGIC ---
    try:
        data_parts = query.data.split("_")
        if len(data_parts) != 2: return
        overs_selected = int(data_parts[1])
        
        if 1 <= overs_selected <= 20:
            match.total_overs = overs_selected

            # ✅ Overs picked -> dedicated Team Edit phase (Edit Team X / Edit Team Y)
            await start_team_edit_phase(query, context, match)

        else:
            await query.answer("Overs must be between 1 and 20.", show_alert=True)
    except ValueError:
        await query.answer("Invalid format.", show_alert=True)

async def start_toss(query, context: ContextTypes.DEFAULT_TYPE, match: Match):
    """Start the toss phase safely"""
    # Try to fetch Team X Captain safely
    captain_x = match.team_x.get_player(match.team_x.captain_id)
    cap_x_name = captain_x.first_name if captain_x else "Team X Captain"
    
    keyboard = [
        [styled_button("Heads", callback_data="toss_heads")],
        [styled_button("Tails", callback_data="toss_tails")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    toss_text = "🪙 <b>TOSS TIME</b>\n\n"
    toss_text += "┈" * 19 + "\n"
    toss_text += f"Format: <b>{match.total_overs} overs</b>\n"
    toss_text += f"{cap_x_name}, make your call.\n"
    toss_text += "Choose Heads or Tails below. (30 seconds)"
    
    # ✅ FIX: Always use refresh_game_message to switch images safely
    chat_id = match.group_id
    await refresh_game_message(context, chat_id, match, toss_text, reply_markup, media_key="toss")

# Toss callback
async def toss_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle toss selection safely"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches:
        await query.answer("No active match found.", show_alert=True)
        return
    
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.TOSS:
        await query.answer("Toss phase has ended.", show_alert=True)
        return
    
    # Only Team X captain can call toss
    if user.id != match.team_x.captain_id:
        await query.answer("Only Team X Captain can call the toss.", show_alert=True)
        return
    
    # Determine toss result
    toss_result = random.choice(["heads", "tails"])
    captain_call = "heads" if query.data == "toss_heads" else "tails"
    
    if toss_result == captain_call:
        match.toss_winner = match.team_x
        winner_captain = match.team_x.get_player(match.team_x.captain_id)
    else:
        match.toss_winner = match.team_y
        winner_captain = match.team_y.get_player(match.team_y.captain_id)
    
    # Ask winner to choose bat or bowl
    keyboard = [
        [styled_button("Bat First", callback_data="toss_decision_bat")],
        [styled_button("Bowl First", callback_data="toss_decision_bowl")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    decision_text = "🪙 <b>TOSS RESULT</b>\n\n"
    decision_text += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    decision_text += f"{match.toss_winner.name} won the toss.\n"
    decision_text += f"Coin landed on: <b>{toss_result.upper()}</b>\n"
    decision_text += f"Captain {winner_captain.first_name}, choose to bat or bowl.\n"
    decision_text += "You have 30 seconds to decide."

    
    # ✅ FIX: Use refresh_game_message instead of edit_message_text
    await refresh_game_message(context, chat.id, match, decision_text, reply_markup, media_key="bat_or_ball")
    
    # Set timeout for decision
    asyncio.create_task(toss_decision_timeout(context, chat.id, match))

async def toss_decision_timeout(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Handle toss decision timeout"""
    await asyncio.sleep(30)
    
    if match.phase != GamePhase.TOSS:
        return
    
    # Auto select bat if no decision made
    match.batting_first = match.toss_winner
    match.bowling_first = match.get_other_team(match.toss_winner)
    
    await start_match(context, group_id, match, auto_decision=True)

# Toss decision callback
async def toss_decision_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle bat/bowl decision"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches:
        await query.answer("No active match found.", show_alert=True)
        return
    
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.TOSS:
        await query.answer("Toss phase has ended.", show_alert=True)
        return
    
    # Only toss winner captain can decide
    winner_captain = match.get_captain(match.toss_winner)
    if user.id != winner_captain.user_id:
        await query.answer("Only the toss winner captain can decide.", show_alert=True)
        return
    
    if query.data == "toss_decision_bat":
        match.batting_first = match.toss_winner
        match.bowling_first = match.get_other_team(match.toss_winner)
    else:
        match.bowling_first = match.toss_winner
        match.batting_first = match.get_other_team(match.toss_winner)
    
    await start_match(context, chat.id, match, auto_decision=False)

async def start_match(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, auto_decision: bool):
    """Start the actual match with prediction poll - FIXED WORKFLOW"""
    match.phase = GamePhase.MATCH_IN_PROGRESS
    match.current_batting_team = match.batting_first
    match.current_bowling_team = match.bowling_first
    match.innings = 1
    match.current_batting_team.innings_start_squad_size = len(match.current_batting_team.players)
    match.fantasy_window_open = False
    
    # ✅ CRITICAL: Reset Batsmen & Bowler indices to None (Fresh Start)
    match.current_batting_team.current_batsman_idx = None
    match.current_batting_team.current_non_striker_idx = None
    match.current_bowling_team.current_bowler_idx = None
    
    # ✅ Enable Waiting Flags
    match.waiting_for_batsman = True
    match.waiting_for_bowler = False 

    # Cleanup the Toss Board
    if match.main_message_id:
        try:
            await context.bot.unpin_chat_message(chat_id=group_id, message_id=match.main_message_id)
        except: pass

    # 🔕 "MATCH HAS BEGUN" text message removed per request — go straight to the prediction poll.
    # ✅ CREATE PREDICTION POLL
    await create_prediction_poll(context, group_id, match)

    # 🏏 REAL CRICKET: Powerplay 1 GIF + 5s pause before the first ball
    if match.is_real_cricket:
        await real_cricket_maybe_powerplay_transition(context, group_id, match, 1)
    
    # Wait 3 seconds for effect
    await asyncio.sleep(1.5)
    
    # ✅ REQUEST STRIKER ONLY (Step 1)
    captain = match.get_captain(match.current_batting_team)
    if not captain:
        await context.bot.send_message(group_id, "⚠️ No captain found!", parse_mode=ParseMode.HTML)
        return
    
    captain_tag = get_user_tag(captain)
    
    msg = (
        f"🏏 {captain_tag}\n"
        "Select your batsman.\n"
        "Use <code>/batting [number]</code>."
    )

    
    await _send_selection_prompt(context, group_id, msg, BATTING_SELECT_GIF)
    
    # Start selection timer
    match.batsman_selection_time = time.time()
    match.batsman_selection_task = asyncio.create_task(
        batsman_selection_timeout(context, group_id, match)
    )

# 🎬 Batting/Bowling selection GIFs — shown whenever the captain is prompted
# to pick their batsman/bowler. Drop your video into the same "gifs" folder
# used above (GIFS_DIR). Any of these filenames/extensions works — first one
# found on disk wins (so batting.mp4 / bowling.mp4 / bowler.mp4 all work,
# no renaming needed).
def _first_existing_g(*names: str) -> Path:
    for name in names:
        p = _g(name)
        if p.is_file():
            return p
    return _g(names[0])  # fall back to the first candidate (used for the "missing" warning)

BATTING_SELECT_GIF = _first_existing_g("batting.gif", "batting.mp4", "batsman.mp4", "batsman.gif")
BOWLING_SELECT_GIF = _first_existing_g("bowling.gif", "bowling.mp4", "bowler.mp4", "bowler.gif")

# 🎬 Same two local files, reused for the per-ball "BATTING TIME" / "BOWLING TIME"
# live messages that used to be hardcoded to a random external t.me post link
# (which could vanish/break any time). Falls back to that old link only if
# the local file genuinely isn't on disk yet.
# 🔁 SWAPPED on purpose: BOWLING_SELECT_GIF's file visually reads as the
# "batting time" clip and vice versa, so the labels below are intentionally
# crossed to match what's actually in each file.
BALL_TIME_BATTING_GIF = BOWLING_SELECT_GIF if BOWLING_SELECT_GIF.is_file() else "https://t.me/kyanaamrkhe/7"
BALL_TIME_BOWLING_GIF = BATTING_SELECT_GIF if BATTING_SELECT_GIF.is_file() else "https://t.me/kyanaamrkhe/6"

# ═══════════════════════════════════════════════════════════════════════════
# 📏 SAME-SIZE BALL-EVENT VIDEOS
# Run / dot / wicket clips (five1.mp4, six2.mp4 …) used to come out BIGGER than
# the batting / bowling clips in the rich card because every file has its own
# native resolution and the card renders the video at that size. Fix: every
# local clip in GIFS is re-encoded ONCE (background thread, ffmpeg) to the exact
# width x height of the batting/bowling clip, and get_random_gif() hands out
# that normalized copy. Until a copy is ready the original is used, so nothing
# ever blocks or breaks. Originals are never touched.
# ═══════════════════════════════════════════════════════════════════════════
import subprocess as _sp_norm
import threading as _th_norm

_NORM_DIR = Path(GIFS_DIR) / "_norm"
_norm_ready: Dict[str, Path] = {}     # str(original path) -> normalized path (encoded on disk)
_norm_warm: Dict[str, Path] = {}      # subset of _norm_ready whose Telegram file_id is ALREADY cached
_norm_done = _th_norm.Event()
_norm_lock = _th_norm.Lock()


def _norm_target_size():
    """(width, height) of the batting/bowling clip — everything else is matched to it."""
    for p in (BATTING_SELECT_GIF, BOWLING_SELECT_GIF):
        if isinstance(p, Path) and p.is_file():
            _d, w, h = get_video_meta(p)
            if w and h:
                return (w // 2) * 2, (h // 2) * 2
    return None


def _norm_one(src_path: Path, w: int, h: int) -> Optional[Path]:
    try:
        _NORM_DIR.mkdir(parents=True, exist_ok=True)
        out = _NORM_DIR / f"{src_path.stem}_{src_path.suffix.lstrip('.').lower()}_{w}x{h}.mp4"
        if out.is_file() and out.stat().st_mtime >= src_path.stat().st_mtime and out.stat().st_size > 0:
            return out
        tmp = out.with_suffix(".tmp.mp4")
        vf = (f"scale={w}:{h}:force_original_aspect_ratio=increase,"
              f"crop={w}:{h},setsar=1,format=yuv420p")
        r = _sp_norm.run(
            ["ffmpeg", "-y", "-v", "error", "-i", str(src_path), "-an", "-vf", vf,
             "-threads", "1", "-c:v", "libx264", "-preset", "veryfast", "-crf", "23",
             "-movflags", "+faststart", str(tmp)],
            capture_output=True, text=True, timeout=300,
            preexec_fn=(lambda: os.nice(19)) if hasattr(os, "nice") else None,   # never starve the bot
        )
        if r.returncode != 0 or not tmp.is_file() or tmp.stat().st_size == 0:
            logger.warning(f"⚠️ normalize failed for {src_path.name}: {r.stderr[-200:]}")
            return None
        os.replace(tmp, out)
        return out
    except Exception as e:
        logger.warning(f"⚠️ normalize error for {src_path}: {e}")
        return None


def _norm_worker():
    size = _norm_target_size()
    if not size:
        logger.warning("📏 gif normalize skipped — batting/bowling clip not found/probe failed")
        return
    w, h = size
    logger.info(f"📏 normalizing ball-event clips to {w}x{h}")
    seen = set()
    for _ev, items in list(GIFS.items()):
        if isinstance(_ev, str) or not isinstance(items, list):
            continue   # str keys = auction gifs → keep original size, no re-encode
        for g in items:
            if isinstance(g, Path) and g.is_file() and str(g) not in seen:
                seen.add(str(g))
                out = _norm_one(g, w, h)
                if out:
                    with _norm_lock:
                        _norm_ready[str(g)] = out
    logger.info(f"📏 normalized {len(_norm_ready)} clip(s) to {w}x{h}")


def _norm_worker_wrapper():
    try:
        _norm_worker()
    finally:
        _norm_done.set()


_th_norm.Thread(target=_norm_worker_wrapper, daemon=True, name="gif-normalize").start()

_get_random_gif_unnormalized = get_random_gif


def get_random_gif(event: MatchEvent):  # noqa: F811 — intentional wrapper
    g = _get_random_gif_unnormalized(event)
    if isinstance(g, Path):
        with _norm_lock:
            w = _norm_warm.get(str(g))
        if w is not None and str(w) in _animation_file_id_cache:
            return w          # normalized AND already uploaded once → instant, same as before
    return g                  # not ready/warm yet → original (already cached) — never slower


async def warm_normalized_gifs(bot):
    """Upload each normalized clip ONCE (to the owner's DM, silently, then delete it) so its
    Telegram file_id is cached BEFORE any match uses it. Only then does get_random_gif switch
    to it — so the first run/wicket message of a match is never delayed by an upload."""
    try:
        for _ in range(900):                               # wait up to ~15 min for ffmpeg
            if _norm_done.is_set():
                break
            await asyncio.sleep(1)
        with _norm_lock:
            items = list(_norm_ready.items())
        for orig, norm in items:
            try:
                if str(norm) not in _animation_file_id_cache:
                    await asyncio.to_thread(get_video_meta, norm)      # ffprobe off the event loop
                    m = await bot.send_animation(OWNER_ID, norm, disable_notification=True)
                    try:
                        await bot.delete_message(OWNER_ID, m.message_id)
                    except Exception:
                        pass
                if str(norm) in _animation_file_id_cache:
                    with _norm_lock:
                        _norm_warm[orig] = norm
            except Exception as e:
                logger.warning(f"⚠️ warm-up failed for {norm.name} (keeping original): {e}")
            await asyncio.sleep(0.5)
        logger.info(f"🔥 {len(_norm_warm)}/{len(items)} normalized clip(s) warmed & active")
    except asyncio.CancelledError:
        pass
    except Exception as e:
        logger.error(f"warm_normalized_gifs error: {e}")


async def _send_selection_prompt(context: ContextTypes.DEFAULT_TYPE, chat_id: int, msg: str,
                                  gif_path: Path, reply_markup=None):
    """Text-only selection prompt (SELECT BOWLER / SELECT OPENING BATSMAN / etc).
    gif_path is accepted for backward compatibility but intentionally unused —
    these lobby prompts no longer attach a video."""
    return await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML, reply_markup=reply_markup)


async def request_batsman_selection(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match):
    """Prompt captain for new batsman after wicket"""
    # 🔧 GLITCH FIX: if /endmatch or /endall already ended this match, stop here.
    if is_match_stale(chat_id, match):
        logger.info("⛔ request_batsman_selection aborted — match already ended.")
        return

    # ── Check batting queue first ──
    bat_team = match.current_batting_team
    queued_idx = _pop_next_batsman(chat_id, bat_team)
    if queued_idx is not None:
        bat_team.current_batsman_idx = queued_idx
        match.waiting_for_batsman = False
        queued_player = bat_team.players[queued_idx]
        player_tag = get_user_tag(queued_player)
        await _send_selection_prompt(
            context, chat_id,
            f"🏏 <b>NEXT BATSMAN (from queue):</b> {player_tag} walks in!",
            BATTING_SELECT_GIF
        )
        logger.info(f"✅ Auto-selected queued batsman: {queued_player.first_name}")
        await asyncio.sleep(0.5)
        if match.current_bowling_team.current_bowler_idx is not None:
            await execute_ball(context, chat_id, match)
        return

    captain = match.get_captain(bat_team)
    if not captain:
        no_cap_msg = (
            "⚠️ <b>NO BATTING CAPTAIN</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            "Select your batsman.\n"
            f"Host (<code>{match.host_id}</code>) can pick.\n"
            "Use <code>/batting [number]</code>."
        )
        await context.bot.send_message(
            chat_id,
            no_cap_msg,
            parse_mode=ParseMode.HTML
        )
        return

    captain_tag = get_user_tag(captain)
    
    # Count available batsmen for display
    available_batsmen_count = len([
        p for i, p in enumerate(bat_team.players)
        if i not in bat_team.out_players_indices
        and i != bat_team.current_non_striker_idx
        and i != bat_team.current_batsman_idx
    ])
    
    msg = (
        f"🏏 {captain_tag}\n"
        "Select your batsman.\n"
        "Use <code>/batting [number]</code>."
    )
    
    await _send_selection_prompt(context, chat_id, msg, BATTING_SELECT_GIF)
    
    # Start 30s timer for selection
    match.batsman_selection_time = time.time() + 30
    match.batsman_selection_task = asyncio.create_task(
        selection_timer(context, chat_id, match, "batsman", captain.first_name)
    )

async def selection_timer(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match, selection_type: str, name: str):
    """Timeout for batsman/bowler selection (30s)"""
    await asyncio.sleep(30)
    if (selection_type == "batsman" and match.waiting_for_batsman and 
        time.time() >= match.batsman_selection_time) or \
       (selection_type == "bowler" and match.waiting_for_bowler and 
        time.time() >= match.bowler_selection_time):
        msg = f"⏰ <b>{name}</b> timed out on {selection_type} selection! Random selected."
        await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
        await auto_select_player(context, chat_id, match, selection_type)

async def auto_select_player(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match, selection_type: str):
    """Randomly select player on timeout"""
    if selection_type == "batsman":
        team = match.current_batting_team
        available = [p for idx, p in enumerate(team.players) if idx not in team.out_players_indices and 
                     idx != team.current_batsman_idx and idx != team.current_non_striker_idx]
        if available:
            random_idx = random.choice([i for i in range(len(team.players)) if i not in team.out_players_indices and 
                                        i != team.current_batsman_idx and i != team.current_non_striker_idx])
            team.current_batsman_idx = random_idx  # New striker
            match.waiting_for_batsman = False
            await resume_after_selection(context, chat_id, match)
    elif selection_type == "bowler":
        team = match.current_bowling_team
        available = team.get_available_bowlers()
        if available:
            new_bowler = random.choice(available)
            team.current_bowler_idx = team.players.index(new_bowler)
            team.bowler_history.append(team.current_bowler_idx)
            match.waiting_for_bowler = False
            await execute_ball(context, chat_id, match)  # Resume next ball

async def resume_after_selection(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match):
    """Resume game after batsman selection (e.g., next ball)"""
    # Cancel timer
    if match.batsman_selection_task:
        match.batsman_selection_task.cancel()
    match.waiting_for_batsman = False
    
    # If mid-over, bowler already set — just resume the next ball
    if match.current_bowling_team.current_bowler_idx is not None:
        await execute_ball(context, chat_id, match)
    else:
        # Edge: Start over or something→log
        logger.warning("Resume called without bowler")

_LINEUP_NUM_EMOJI = ["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟",
                     "1️⃣1️⃣","1️⃣2️⃣","1️⃣3️⃣","1️⃣4️⃣","1️⃣5️⃣"]


def _build_lineup_list_rich_html(team: "Team", mode: str) -> str:
    """CCC/fantasylb-style native <table> dropdown for the bare /batting or
    /bowling (no serial) player list — same collapsible pattern as
    _build_fantasylb_rich_html, instead of a plain <pre> text grid."""
    cmd = "/batting [serial_number]" if mode == "batting" else "/bowling [serial_number]"
    title = "🏏 SELECT YOUR BATSMAN" if mode == "batting" else "🎯 SELECT YOUR BOWLER"

    trs = ""
    for i, player in enumerate(team.players, 1):
        name = html.escape((player.first_name or "Player")[:16])

        if mode == "batting":
            if player.is_out:
                status = "❌ Out"
            elif (i - 1) == team.current_batsman_idx or (i - 1) == team.current_non_striker_idx:
                status = "🏏 Batting"
            else:
                status = "✅ Not Out"
        else:
            if getattr(player, "is_bowling_banned", False):
                status = "🚫 Banned"
            elif (i - 1) == team.current_bowler_idx:
                status = "🎯 Bowling"
            else:
                status = "✅ Available"

        # 📊 Extra stat column: runs scored (batting) / overs bowled (bowling)
        if mode == "batting":
            stat_val = str(getattr(player, "runs", 0) or 0)
        else:
            stat_val = format_overs(getattr(player, "balls_bowled", 0) or 0)

        trs += (
            f"<tr><td align='center'>{i}</td>"
            f"<td>{name}</td>"
            f"<td>{status}</td>"
            f"<td align='center'>{stat_val}</td></tr>"
        )

    stat_th = "🏏 Runs" if mode == "batting" else "⏱️ Overs"
    table = (
        "<table bordered striped>"
        f"<tr><th>#️⃣</th><th>🧢 Player</th><th>📋 Status</th><th>{stat_th}</th></tr>"
        f"{trs}</table>"
    )
    return (
        f"<h3>{title}</h3>"
        "<details open><summary>👥 Available Players</summary>"
        f"{table}</details>"
        f"<footer>👉 <code>{cmd}</code></footer>"
    )


def _build_lineup_list_text(team: "Team", mode: str) -> str:
    """Bare /batting or /bowling (no serial) — show the team's players as a
    simple table: S.No | Player | Status. Only this team's own players are
    shown (batting team for /batting, bowling team for /bowling).
    Plain-text fallback used only if the rich native table can't be sent."""
    cmd = "/batting [serial_number]" if mode == "batting" else "/bowling [serial_number]"

    stat_label = "Runs" if mode == "batting" else "Overs"
    table_header = f"{_nsc_pad('S.No', 6)}{_nsc_pad('Player', 16)}{_nsc_pad('Status', 10)}{_nsc_pad(stat_label, 6)}\n"
    rows = ""
    for i, player in enumerate(team.players, 1):
        name = player.first_name

        if mode == "batting":
            if player.is_out:
                status = "Out"
            elif (i - 1) == team.current_batsman_idx or (i - 1) == team.current_non_striker_idx:
                status = "Batting"
            else:
                status = "Not Out"
        else:
            if getattr(player, "is_bowling_banned", False):
                status = "Banned"
            elif (i - 1) == team.current_bowler_idx:
                status = "Bowling"
            else:
                status = "Available"

        if mode == "batting":
            stat_val = str(getattr(player, "runs", 0) or 0)
        else:
            stat_val = format_overs(getattr(player, "balls_bowled", 0) or 0)

        rows += f"{_nsc_pad(i, 6)}{_nsc_pad(name, 16)}{_nsc_pad(status, 10)}{_nsc_pad(stat_val, 6)}\n"

    table = f"<pre>{table_header}{('—' * 38)}\n{rows}</pre>"
    return f"{table}\n👉 <b>Command:</b> <code>{cmd}</code>"


async def _send_lineup_list(context: ContextTypes.DEFAULT_TYPE, chat_id: int, team: "Team", mode: str):
    """Send the available-players list as a CCC/fantasylb-style native table,
    falling back to the plain <pre> text table if Rich Messages aren't
    supported in this chat."""
    html_content = _build_lineup_list_rich_html(team, mode)
    ok = await _tg_send_rich_message(chat_id, html_content)
    if not ok:
        await context.bot.send_message(chat_id, _build_lineup_list_text(team, mode), parse_mode=ParseMode.HTML)


async def batting_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ✅ COMPLETE BATTING COMMAND - FIXED: Proper flow after selection
    """
    chat = update.effective_chat
    user = update.effective_user
    
    logger.info(f"🏏 /batting command from {user.first_name} (ID: {user.id})")
    
    if chat.id not in active_matches:
        logger.warning(f"⚠️ No active match in chat {chat.id}")
        return
    
    match = active_matches[chat.id]

    # 🏏 Super Over uses its own batting lineup selection too, so allow that phase here —
    # previously only MATCH_IN_PROGRESS was accepted, which made /batting wrongly say
    # "Match is not in progress" during a Super Over.
    if match.phase not in (GamePhase.MATCH_IN_PROGRESS, GamePhase.SUPER_OVER):
        logger.warning(f"⚠️ Match not in progress, phase={match.phase}")
        await update.message.reply_text("⚠️ Match is not in progress!")
        return

    bat_team = match.current_batting_team
    
    # Captain OR host can select → silently reject & delete everyone else's messages
    is_captain = bool(bat_team.captain_id and user.id == bat_team.captain_id)
    is_host = (user.id == match.host_id)
    if not is_captain and not is_host:
        logger.warning(f"👮‍♂️ User {user.first_name} is not captain or host")
        try:
            await update.message.delete()
        except Exception:
            pass
        return

    if not context.args:
        await _send_lineup_list(context, chat.id, bat_team, "batting")
        return
    
    try:
        serial = int(context.args[0])
        logger.info(f"🔢 Serial number: {serial}")
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 8240)")
        await update.message.reply_text("❌ Invalid number.")
        return

    player = bat_team.get_player_by_serial(serial)
    if not player:
        logger.warning(f"🚫 Player #{serial} not found")
        await update.message.reply_text(f"🚫 Player #{serial} not found.")
        return
    
    logger.info(f"👤 Player selected: {player.first_name} (ID: {player.user_id})")
    
    if player.is_out:
        logger.warning(f"💀 Player {player.first_name} is already OUT")
        await update.message.reply_text(
            themed("Already Out", [f"{html.escape(player.first_name)} is already OUT!"],
                   emoji="💀"),
            parse_mode=ParseMode.HTML
        )
        return
    
    player_idx = serial - 1
    
    # Check duplicates
    if player_idx == bat_team.current_batsman_idx or player_idx == bat_team.current_non_striker_idx:
        logger.warning(f"🛑 Player {player.first_name} already on crease")
        await update.message.reply_text(f"🛑 {player.first_name} is already on the crease!")
        return

    # 👍 Confirm the selection went through with a reaction on the captain's command
    await react_thumbs_up(context, chat.id, update.message.message_id)

    # ========================================
    # 🎯 CASE 1: SELECTING STRIKER (Opening)
    # ========================================
    if bat_team.current_batsman_idx is None and bat_team.current_non_striker_idx is None:
        logger.info("🎯 CASE 1: Selecting STRIKER (Opening)")
        bat_team.current_batsman_idx = player_idx
        
        await update.message.reply_text(
            f"✅ <b>Hey here is our Striker:</b> {player.first_name}", 
            parse_mode=ParseMode.HTML
        )
        logger.info(f"✅ Here is our Striker set: {player.first_name} (Index: {player_idx})")
        await asyncio.sleep(0.5)

        # Request Non-Striker
        captain_tag = get_user_tag(match.get_captain(bat_team))
        msg = f"🏏 {captain_tag}\n"
        msg += "Select your non-striker.\n"
        msg += "Use <code>/batting [number]</code>."
        
        await context.bot.send_message(chat.id, msg, parse_mode=ParseMode.HTML)
        logger.info("✅ Here our Non-striker request sent")
        return

    # ========================================
    # 🎯 CASE 2: SELECTING NON-STRIKER (Opening)
    # ========================================
    elif bat_team.current_non_striker_idx is None:
        logger.info("🎯 CASE 2: Selecting NON-STRIKER (Opening)")
        bat_team.current_non_striker_idx = player_idx
        
        await update.message.reply_text(f"🃏 <b>Non-Striker Selected:</b> {player.first_name}", parse_mode=ParseMode.HTML)
        logger.info(f"✅ Non-striker set: {player.first_name} (Index: {player_idx})")
        await asyncio.sleep(0.5)
        
        # ✅ Opening Pair Complete
        match.waiting_for_batsman = False
        if match.batsman_selection_task:
            match.batsman_selection_task.cancel()
            logger.info("✅ Batsman selection timer cancelled")
        
        striker = bat_team.players[bat_team.current_batsman_idx]
        non_striker = bat_team.players[bat_team.current_non_striker_idx]
        
        confirm_msg = themed(
            "🏏 TODAY'S MATCH OPENER",
            [
                f"⚡ 𝗦𝘁𝗿𝗶𝗸𝗲𝗿: {html.escape(striker.first_name)}",
                f"🛡️ 𝗡𝗼𝗻-𝗦𝘁𝗿𝗶𝗸𝗲𝗿: {html.escape(non_striker.first_name)}",
            ],
            "🏏"
        )
        
        # Send with photo
        try:
            await context.bot.send_photo(
                chat.id,
                photo=OPENING_PAIR_PHOTO,
                caption=confirm_msg,
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.error(f"Error sending opening pair photo: {e}")
            # Fallback to text
            await context.bot.send_message(chat.id, confirm_msg, parse_mode=ParseMode.HTML)
        
        logger.info("✅ Opening pair confirmed")
        await asyncio.sleep(1)
        
        # ✅ Request Bowler (Step 3) - THIS IS THE CRITICAL FIX
        match.waiting_for_bowler = True
        match.waiting_for_batsman = False  # Ensure this is false
        logger.info("📣 Calling request_bowler_selection...")
        await request_bowler_selection(context, chat.id, match)
        logger.info("✅ Bowler selection initiated")
        return

    # ========================================
    # 🎯 CASE 3: NEW BATSMAN (After Wicket)
    # ========================================
    else:
        logger.info("🎯 CASE 3: Selecting NEW BATSMAN after wicket")
        
        if not match.waiting_for_batsman:
            logger.warning("⚠️ Not waiting for batsman")
            await update.message.reply_text("⚠️ Batsmen are already set. Use /impact for substitution.")
            return

        # ✅ SET NEW STRIKER (NON-STRIKER STAYS SAME)
        bat_team.current_batsman_idx = player_idx
        match.waiting_for_batsman = False
        
        if match.batsman_selection_task:
            match.batsman_selection_task.cancel()
            logger.info("✅ Batsman selection timer cancelled")
    
        player_tag = get_user_tag(player)
        logger.info(f"✅ New batsman set: {player.first_name} (Index: {player_idx})")
    
        await asyncio.sleep(1)
        
        # ✅ CRITICAL: Check pending over complete status FIRST
        if hasattr(match, 'pending_over_complete') and match.pending_over_complete:
            logger.info("🏁 Pending over complete detected, calling check_over_complete")
            match.pending_over_complete = False  # Reset flag
            await check_over_complete(context, chat.id, match)
            return
        
        # ✅ If no pending over complete, resume normal play
        bowl_team = match.current_bowling_team
        
        # ✅ If bowler exists, resume
        if bowl_team.current_bowler_idx is not None:
            logger.info("▶️ Bowler exists, resuming ball execution")
            await execute_ball(context, chat.id, match)
            
        # ✅ Edge case: No bowler (shouldn't happen in normal flow)
        else:
            logger.warning("⚠️ No bowler found, requesting bowler selection")
            match.waiting_for_bowler = True
            await request_bowler_selection(context, chat.id, match)        
        return

async def _build_players_text(match: Match) -> str:
    """Rebuild the /players text (used by both the command and the Refresh button)."""
    toss_winner_team = getattr(match, 'toss_winner', None)

    NUM_EMOJI = ["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟",
                 "1️⃣1️⃣","1️⃣2️⃣","1️⃣3️⃣","1️⃣4️⃣","1️⃣5️⃣"]

    def _get_player_status_icons(player, team):
        if player.is_out:
            return "❌"
        icons = []
        if player.user_id == team.captain_id:
            icons.append("👑")
        if match.current_batting_team == team:
            bat_idx = team.current_batsman_idx
            ns_idx = team.current_non_striker_idx
            if bat_idx is not None and bat_idx < len(team.players) and team.players[bat_idx].user_id == player.user_id:
                icons.append("🏏")
            elif ns_idx is not None and ns_idx < len(team.players) and team.players[ns_idx].user_id == player.user_id:
                icons.append("🏃‍♂️")
        if match.current_bowling_team == team:
            bowl_idx = team.current_bowler_idx
            if bowl_idx is not None and bowl_idx < len(team.players) and team.players[bowl_idx].user_id == player.user_id:
                icons.append("‼️")
        return " ".join(icons) if icons else ""

    def _build_player_row(player, team, num):
        tag = f'<a href="tg://user?id={player.user_id}">{html.escape(player.first_name)}</a>' + _title_suffix(player.user_id)
        status = _get_player_status_icons(player, team)
        num_icon = NUM_EMOJI[num-1] if num <= len(NUM_EMOJI) else f"{num}."
        row = f"{num_icon} {tag}"
        if status:
            row += f" {status}"
        row += "\n"
        return row

    def _build_team_block(team, color, num_players):
        toss_icon = " 🪙" if toss_winner_team == team else ""
        score_str = ""
        if match.phase == GamePhase.MATCH_IN_PROGRESS or match.innings >= 1:
            score_str = f" ➔ {team.score}/{team.wickets} ({format_overs(team.balls)} ov)"
        color_icon = "🧊" if team == match.team_x else "🔥"
        block = f"{color_icon} <b>𝗧𝗘𝗔𝗠 {html.escape(team.name)}</b>{toss_icon}{score_str}\n"
        block += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        for i, player in enumerate(team.players, 1):
            block += _build_player_row(player, team, i)
        block += "\n"
        return block

    host_tag = f'<a href="tg://user?id={match.host_id}">{html.escape(match.host_name or "Host")}</a>' + _title_suffix(match.host_id)
    overs_info = getattr(match, 'total_overs', 0)
    resume_code_top = getattr(match, 'resume_code', None)
    text = f"👑 <b>𝗛𝗼𝘀𝘁:</b> {host_tag}\n"
    text += f"⏱️ <b>𝗢𝘃𝗲𝗿𝘀:</b> {overs_info}\n"
    if resume_code_top:
        text += f"🔄 <b>𝗥𝗲𝘀𝘂𝗺𝗲:</b> /regame {resume_code_top}\n"
    text += "\n"
    text += _build_team_block(match.team_x, "❄️", len(match.team_x.players))
    text += _build_team_block(match.team_y, "🔥", len(match.team_y.players))
    ist_now = datetime.utcnow() + timedelta(hours=5, minutes=30)
    text += f"\n⏱️ 𝗟𝗮𝘀𝘁 𝘂𝗽𝗱𝗮𝘁𝗲𝗱: {ist_now.strftime('%H:%M:%S')} IST"
    return text


PLAYERS_CMD_MAX_USES = 6  # /players can only be run this many times per match (Refresh button doesn't count)


async def players_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏏 Show playing squads with player tags and live real-time status"""
    group_id = update.effective_chat.id
    match = active_matches.get(group_id)
    
    if not match:
        await update.message.reply_text("🏏 No active match! Start with /game")
        return

    if getattr(match, 'game_mode', None) in ["SOLO", "MAGICBALL"] or match.phase in [GamePhase.SOLO_JOINING, GamePhase.SOLO_MATCH]:
        # Solo mode → show player roster
        msg = "📜 𝗦𝗢𝗟𝗢 𝗕𝗔𝗧𝗧𝗟𝗘 𝗥𝗢𝗦𝗧𝗘𝗥\n"
        msg += "<blockquote>"
        lines = []
        for i, p in enumerate(match.solo_players, 1):
            status = "⏳ <i>Waiting</i>"
            if p.is_out: status = "❌ <b>OUT</b>"
            elif match.phase == GamePhase.SOLO_MATCH:
                if i-1 == match.current_solo_bat_idx: status = "🏏 <b>BATTING</b>"
                elif i-1 == match.current_solo_bowl_idx: status = "⚾ <b>BOWLING</b>"
                elif p.is_bowling_banned: status = "🚫 <b>BANNED (Bowl)</b>"
            lines.append(f"├ <b>{i}. {p.first_name}</b> ➜ {status} • {p.runs} Runs")
        msg += "\n".join(lines)
        msg += "</blockquote>"
        await update.message.reply_text(msg, parse_mode=ParseMode.HTML)
        return

    # ── Usage limit: /players can only be used 6 times per match ──
    uses = getattr(match, 'players_cmd_uses', 0)
    if uses >= PLAYERS_CMD_MAX_USES:
        await update.message.reply_text(
            f"⚠️ <b>/players limit reached</b> ({PLAYERS_CMD_MAX_USES}/match). "
            f"Use the 🔄 Refresh button on the last card instead.",
            parse_mode=ParseMode.HTML
        )
        return

    # ── 2-minute cooldown for players command during active match ──
    if match.phase == GamePhase.MATCH_IN_PROGRESS:
        remaining = check_players_cooldown(group_id)
        if remaining is not None:
            secs = math.ceil(remaining)
            mins = secs // 60
            sec_part = secs % 60
            cool_msg = await update.message.reply_text(
                f"⏳ <b>Players command cooldown:</b> Wait <b>{mins}m {sec_part}s</b> more!",
                parse_mode=ParseMode.HTML
            )
            asyncio.get_event_loop().call_later(
                remaining + 1,
                lambda: asyncio.ensure_future(cool_msg.delete())
            )
            return
        set_players_cooldown(group_id)

    match.players_cmd_uses = uses + 1
    text = await _build_players_text(match)
    refresh_kb = InlineKeyboardMarkup([[
        styled_button("Refresh", callback_data=f"players_refresh_{group_id}")
    ]])

    try:
        players_img = await generate_players_squad_image(match, context)
        if players_img:
            sent = await update.message.reply_photo(
                photo=players_img, caption=text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb
            )
        else:
            sent = await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb)
    except Exception:
        try:
            sent = await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb)
        except Exception:
            await update.message.reply_text("🏏 Players list unavailable right now.")
            return
    # Pin the players message
    try:
        await context.bot.pin_chat_message(
            chat_id=group_id,
            message_id=sent.message_id,
            disable_notification=True
        )
    except Exception:
        pass


async def players_refresh_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔄 Refresh button on /players — updates the text in place, doesn't count against the 6-use limit."""
    query = update.callback_query
    try:
        group_id = int(query.data.split("_")[-1])
    except Exception:
        await query.answer("Invalid request", show_alert=True)
        return

    match = active_matches.get(group_id)
    if not match:
        await query.answer(plain_alert("⚠️ No active match anymore!"), show_alert=True)
        return

    text = await _build_players_text(match)
    refresh_kb = InlineKeyboardMarkup([[
        styled_button("Refresh", callback_data=f"players_refresh_{group_id}")
    ]])
    try:
        if query.message.photo:
            await query.edit_message_caption(caption=text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb)
        else:
            await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb)
        await query.answer(plain_alert("✅ Refreshed!"))
    except Exception:
        await query.answer("Already up to date!")



async def batsman_selection_timeout(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Handle batsman selection timeout"""
    try:
        await asyncio.sleep(120)  # 2 minutes - send reminder

        # 🔧 GLITCH FIX: match may have ended (or been replaced by a new one
        # in the same chat) while we were asleep — stop dead instead of
        # sending a phantom "pick your next batter" reminder forever.
        if is_match_stale(group_id, match) or not match.waiting_for_batsman:
            return
        
        # 2-minute reminder
        reminder_msg = (
            "⏳ <b>BATSMAN REMINDER</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"{match.current_batting_team.name} must pick the next batsman.\n"
            "Use <code>/batting [number]</code>.\n"
            "Only <b>2 minutes</b> remain."
        )
        await context.bot.send_message(
            chat_id=group_id,
            text=reminder_msg,
            parse_mode=ParseMode.HTML
        )
        
        await asyncio.sleep(120)  # Another 2 minutes (total 4 min)
        
        if is_match_stale(group_id, match) or not match.waiting_for_batsman or getattr(match, 'is_paused', False):
            return
        
        # Timeout occurred - penalty
        penalty = 6
        match.current_batting_team.score -= penalty
        match.current_batting_team.score = max(0, match.current_batting_team.score)
        match.current_batting_team.penalty_runs += penalty
        
        penalty_msg = (
            "⚠️ <b>BATSMAN TIMEOUT</b>\n"
            f"<b>-{penalty} runs</b> applied for the delay.\n"
            f"Score: <b>{match.current_batting_team.score}/{match.current_batting_team.wickets}</b>\n"
            "Use <code>/batting [number]</code> now."
        )
        
        await context.bot.send_message(
            chat_id=group_id,
            text=penalty_msg,
            parse_mode=ParseMode.HTML
        )
        
        # Re-check once more right before rescheduling — a race between the
        # penalty message above and the match ending shouldn't spawn a new
        # infinite-timer task on a dead match.
        if is_match_stale(group_id, match) or not match.waiting_for_batsman:
            return

        # Reset timer
        match.batsman_selection_time = time.time()
        match.batsman_selection_task = asyncio.create_task(
            batsman_selection_timeout(context, group_id, match)
        )
    
    except asyncio.CancelledError:
        pass

async def request_bowler_selection(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match):
    """Prompt captain for bowler - GUARANTEED DELIVERY WITH FULL LOGGING"""

    # 🔧 GLITCH FIX: if /endmatch or /endall already ended this match, stop here.
    if is_match_stale(chat_id, match):
        logger.info("⛔ request_bowler_selection aborted — match already ended.")
        return

    logger.info(f"🎬 === BOWLER SELECTION START === Chat: {chat_id}")
    
    # Validate bowling team exists
    if not match.current_bowling_team:
        logger.error("❌ CRITICAL: No bowling team set!")
        await context.bot.send_message(chat_id, "⚠️ Error: No bowling team found!", parse_mode=ParseMode.HTML)
        return
    
    logger.info(f"✅ Bowling team: {match.current_bowling_team.name}")

    # ── Check bowling queue first ──
    bowl_team = match.current_bowling_team
    queued_idx = _pop_next_bowler(chat_id, bowl_team)
    if queued_idx is not None:
        bowl_team.current_bowler_idx = queued_idx
        match.waiting_for_bowler = False
        match.current_ball_data = {}
        queued_bowler = bowl_team.players[queued_idx]
        bowler_tag = get_user_tag(queued_bowler)
        await _send_selection_prompt(
            context, chat_id,
            f"⚾ <b>NEXT BOWLER (from queue):</b> {bowler_tag} takes the ball!",
            BOWLING_SELECT_GIF
        )
        logger.info(f"✅ Auto-selected queued bowler: {queued_bowler.first_name}")
        await asyncio.sleep(0.5)
        await execute_ball(context, chat_id, match)
        return
    
    # Get captain
    captain = match.get_captain(match.current_bowling_team)
    if not captain:
        logger.error("❌ CRITICAL: No bowling captain found!")
        await context.bot.send_message(
            chat_id, 
            f"⚠️ <b>NO BOWLING CAPTAIN</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\nHost (<code>{match.host_id}</code>) can choose the bowler.\nUse <code>/bowling [number]</code> or /changecap.", 
            parse_mode=ParseMode.HTML
        )
        return

    captain_tag = get_user_tag(captain)
    logger.info(f"👑 Captain: {captain.first_name} (ID: {captain.user_id})")
    
    # Get available bowlers
    available = match.current_bowling_team.get_available_bowlers()
    logger.info(f"📊 Available bowlers: {len(available)}")
    
    if len(available) == 0:
        logger.error("❌ CRITICAL: No available bowlers!")
        await context.bot.send_message(
            chat_id,
            "⚠️ <b>Error:</b> No bowlers available! All players may be banned from bowling.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Log available bowlers
    for i, p in enumerate(available):
        logger.info(f"  Bowler #{i+1}: {p.first_name} (ID: {p.user_id})")
    
    # Build message → properly initialized
    over_num = len(match.team_x_over_runs if match.current_batting_team == match.team_x else match.team_y_over_runs) + 1
    msg = (
        f"⚾ {captain_tag}\n"
        "Choose the next bowler.\n"
        "Use <code>/bowling [number]</code>."
    )
    
    # Group URL for "Go to Group" button
    try:
        _cid_str = str(abs(chat_id))
        _tme_gid = _cid_str[3:] if _cid_str.startswith("100") else _cid_str
        _group_url = f"https://t.me/c/{_tme_gid}/1"
    except Exception:
        _group_url = f"https://t.me/{context.bot.username}"
    
    bowler_select_markup = InlineKeyboardMarkup([[
        styled_button("Go to Group", url=_group_url)
    ]])
    
    # Send message to group
    try:
        sent_msg = await _send_selection_prompt(context, chat_id, msg, BOWLING_SELECT_GIF, reply_markup=bowler_select_markup)
        logger.info(f"✅ Group message sent successfully (msg_id: {sent_msg.message_id})")
    except Exception as e:
        logger.error(f"❌ Failed to send group message: {e}")
        return
    
    # SET WAITING STATE BEFORE ANYTHING ELSE
    match.waiting_for_bowler = True
    match.waiting_for_batsman = False
    match.current_ball_data = {}
    logger.info(f"✅ State set: waiting_for_bowler=True, waiting_for_batsman=False")
    
    # Start timeout timer
    match.bowler_selection_time = time.time()
    match.bowler_selection_task = asyncio.create_task(
        bowler_selection_timeout(context, chat_id, match)
    )
    logger.info(f"✅ Timeout timer started (120 seconds)")
    
    logger.info(f"🎬 === BOWLER SELECTION END ===")

async def bowler_selection_timeout(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Handle bowler selection timeout"""
    try:
        await asyncio.sleep(120)  # 2 minutes - send reminder

        # 🔧 GLITCH FIX: same fix as batsman_selection_timeout — match may
        # have ended (or been replaced by a new one in the same chat) while
        # we were asleep. Without this check this task keeps rescheduling
        # itself and firing "delayed bowler selection" penalties forever,
        # mid-game AND after the match has already ended.
        if is_match_stale(group_id, match) or not match.waiting_for_bowler:
            return
        
        # 2-minute reminder
        captain = match.get_captain(match.current_bowling_team)
        captain_tag = get_user_tag(captain) if captain else match.current_bowling_team.name
        reminder_msg = (
            f"⚾ <b>Bowler Selection!</b>\n"
            f"<blockquote>{captain_tag} → pick your bowler now!\n"
            f"⌨️ <code>/bowling [number]</code>  ·  ⏳ 2 min left!</blockquote>"
        )
        await context.bot.send_message(
            chat_id=group_id,
            text=reminder_msg,
            parse_mode=ParseMode.HTML
        )
        
        await asyncio.sleep(120)  # Another 2 minutes (total 4 min)
        
        if is_match_stale(group_id, match) or not match.waiting_for_bowler or getattr(match, 'is_paused', False):
            return
        
        # Get current bowler if any
        if match.current_bowling_team.current_bowler_idx is not None:
            bowler = match.current_bowling_team.players[match.current_bowling_team.current_bowler_idx]
            bowler.bowling_timeouts += 1
            
            timeout_count = bowler.bowling_timeouts
            
            if timeout_count >= 3:
                # Ban from bowling
                bowler.is_bowling_banned = True
                
                penalty_msg = (
                    "🚫 <b>BOWLER BANNED</b>\n"
                    f"{html.escape(bowler.first_name)}: 3 bowling timeouts reached.\n"
                    "No Ball + Free Hit applied.\n"
                    "Choose another bowler: <code>/bowling [number]</code>."
                )
                
                # Add no ball
                match.current_batting_team.score += 1
                match.current_batting_team.extras += 1
                match.is_free_hit = True
                
                await context.bot.send_message(
                    chat_id=group_id,
                    text=penalty_msg,
                    parse_mode=ParseMode.HTML
                )
            else:
                penalty_msg = (
                    f"⏱️ <b>BOWLER TIMEOUT!</b>  <code>{timeout_count}/3</code>\n"
                    f"<blockquote>⚠️ {bowler.first_name} didn't bowl in time!\n"
                    f"📌 NO BALL  ·  ➕ +1 Run  ·  ⚡ FREE HIT!\n"
                    f"⌨️ <code>/bowling [number]</code> → select bowler!</blockquote>"
                )
                
                # Add no ball
                match.current_batting_team.score += 1
                match.current_batting_team.extras += 1
                match.is_free_hit = True
                
                await context.bot.send_message(
                    chat_id=group_id,
                    text=penalty_msg,
                    parse_mode=ParseMode.HTML
                )
        else:
            # First ball, no specific bowler to penalize
            # 🔧 BUGFIX: message claimed "-6 Run Penalty applied" but no runs
            # were ever actually added to the batting team's score. Now applied.
            PENALTY = 6
            match.current_batting_team.score += PENALTY
            match.current_batting_team.extras += PENALTY
            penalty_msg = (
                f"⚠️ <b>{match.current_bowling_team.name}</b> delayed bowler selection!\n"
                f"<blockquote>💸 -{PENALTY} Run Penalty applied.\n"
                f"⌨️ <code>/bowling [number]</code> → select NOW!</blockquote>"
            )
            
            await context.bot.send_message(
                chat_id=group_id,
                text=penalty_msg,
                parse_mode=ParseMode.HTML
            )

        # 🔧 GLITCH FIX: re-check once more right before rescheduling — a
        # race between the penalty message above and the match ending
        # shouldn't spawn a new infinite-timer task on a dead match.
        if is_match_stale(group_id, match) or not match.waiting_for_bowler:
            return

        # Reset timer
        match.bowler_selection_time = time.time()
        match.bowler_selection_task = asyncio.create_task(
            bowler_selection_timeout(context, group_id, match)
        )
    
    except asyncio.CancelledError:
        pass

async def bowling_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Bowling Selection - FIXED VERSION"""
    chat = update.effective_chat
    user = update.effective_user
    
    logger.info(f"⚾ === BOWLING COMMAND START === From: {user.first_name} (ID: {user.id})")
    
    if chat.id not in active_matches: 
        logger.warning(f"❌ No active match in chat {chat.id}")
        await update.message.reply_text("❌ No active match")
        return
    
    match = active_matches[chat.id]
    logger.info(f"✅ Match found - Phase: {match.phase}")
    
    # Check if we are waiting for bowler
    if not match.waiting_for_bowler:
        logger.warning(f"⚠️ Not waiting for bowler (waiting_for_bowler=False)")
        await update.message.reply_text("⚠️ Not waiting for bowler selection right now.")
        return
    
    logger.info(f"✅ Waiting for bowler confirmed")
    
    bowling_captain = match.get_captain(match.current_bowling_team)
    is_host = (user.id == match.host_id)

    if not bowling_captain and not is_host:
        logger.error(f"❌ No bowling captain found!")
        await update.message.reply_text("⚠️ No bowling captain found!")
        return

    if bowling_captain:
        logger.info(f"👑 Bowling captain: {bowling_captain.first_name} (ID: {bowling_captain.user_id})")

    is_captain = bool(bowling_captain and user.id == bowling_captain.user_id)
    if not is_captain and not is_host:
        logger.warning(f"🚫 User {user.first_name} is not the bowling captain or host")
        try:
            await update.message.delete()
        except Exception:
            pass
        return
    
    logger.info(f"✅ Captain/host verification passed")
    
    if not context.args:
        logger.warning(f"⚠️ No serial number provided")
        await _send_lineup_list(context, chat.id, match.current_bowling_team, "bowling")
        return
    
    try:
        serial = int(context.args[0])
        logger.info(f"🔢 Serial number: {serial}")
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 8878)")
        logger.error(f"❌ Invalid serial number: {context.args[0]}")
        await update.message.reply_text("❌ Invalid number.")
        return
    
    bowler = match.current_bowling_team.get_player_by_serial(serial)
    if not bowler:
        logger.error(f"❌ Player #{serial} not found in bowling team")
        await update.message.reply_text(f"❌ Player #{serial} not found.")
        return
    
    logger.info(f"👤 Bowler selected: {bowler.first_name} (ID: {bowler.user_id})")
        
    if bowler.is_bowling_banned:
        logger.warning(f"🚫 {bowler.first_name} is banned from bowling")
        await update.message.reply_text("🚫 Player is BANNED from bowling.")
        return
    
    logger.info(f"✅ Bowler validation passed")
    
    # ✅ NO CONSECUTIVE OVERS CHECK
    bowler_idx = serial - 1
    if match.current_bowling_team.bowler_history:
        if bowler_idx == match.current_bowling_team.bowler_history[-1]:
            logger.warning(f"🚫 Consecutive over attempt by {bowler.first_name}")
            await update.message.reply_text("🚫 <b>Rule:</b> Bowler cannot bowl 2 consecutive overs!", parse_mode=ParseMode.HTML)
            return
    
    logger.info(f"✅ Consecutive over check passed")

    # 🏏 REAL CRICKET: max-overs-per-bowler cap (consecutive-over rule above
    # already covers the no-back-to-back requirement for this mode too)
    if match.is_real_cricket:
        _rc_reason = real_cricket_bowler_eligible(match, bowler.user_id)
        if _rc_reason:
            await update.message.reply_text(_rc_reason, parse_mode=ParseMode.HTML)
            return

    # ✅ SET BOWLER
    match.current_bowling_team.current_bowler_idx = bowler_idx
    match.waiting_for_bowler = False
    match.waiting_for_batsman = False 
    
    logger.info(f"✅ Bowler set: Index={bowler_idx}, waiting_for_bowler=False")
    
    if match.bowler_selection_task: 
        match.bowler_selection_task.cancel()
        logger.info(f"✅ Bowler selection timer cancelled")
    
    # 👍 Confirm the selection went through with a reaction on the captain's command
    # (BOWLER LOCKED confirmation message removed per request)
    await react_thumbs_up(context, chat.id, update.message.message_id)
    logger.info(f"✅ Bowler locked in, confirmed via thumbs-up reaction")
    
    await asyncio.sleep(1)
    
    # ✅ RESUME GAME (Trigger first ball of over) - THIS IS THE CRITICAL FIX
    logger.info(f"🎮 Calling execute_ball to start bowling...")
    await execute_ball(context, chat.id, match)
    logger.info(f"⚾ === BOWLING COMMAND END ===")


