# 🎯 REAL CRICKET FIELD COMMAND
# ----------------------------------------------------------------
# /field is intentionally available only in Real Cricket Mode.
# Every innings starts with 3 field-change points.
# Each successful change costs exactly 1 point.
# Permission: current bowling captain OR Host emergency fallback.
# ═══════════════════════════════════════════════════════════════
def _real_field_keyboard(group_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [
            styled_button("On Boundary", callback_data=f"field_boundary_{group_id}", style="primary"),
            styled_button("Inside Circle", callback_data=f"field_circle_{group_id}", style="primary"),
        ],
        [
            styled_button("Balanced", callback_data=f"field_balanced_{group_id}", style="primary"),
        ],
    ])


def _real_field_status(match: Match) -> tuple:
    innings = match.innings
    remaining = match.real_field_points.get(innings, 3)
    used = 3 - remaining
    position = match.real_field_position.get(innings, "Balanced")
    return used, remaining, position


async def field_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Change the bowling-side field setting in Real Cricket Mode."""
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_matches:
        return

    match = active_matches[chat.id]

    if not getattr(match, "is_real_cricket", False):
        await update.message.reply_text(
            "⚠️ <b>/field</b> is available only in Real Cricket Mode.",
            parse_mode=ParseMode.HTML,
        )
        return

    if match.phase != GamePhase.MATCH_IN_PROGRESS:
        await update.message.reply_text(
            "⚠️ Field changes are available only while the match is in progress.",
            parse_mode=ParseMode.HTML,
        )
        return

    bowling_captain = match.get_captain(match.current_bowling_team)
    is_captain = bool(bowling_captain and user.id == bowling_captain.user_id)
    is_host = bool(match.host_id and user.id == match.host_id)

    # Normal control belongs to the current bowling captain.
    # Host is retained as an emergency fallback, matching the existing
    # captain/host permission pattern used by bowling selection.
    if not is_captain and not is_host:
        try:
            await update.message.delete()
        except Exception:
            pass
        return

    remaining = match.real_field_points.get(match.innings, 3)
    if remaining <= 0:
        await update.message.reply_text(
            themed(
                "🔐 FIELD LOCKED",
                [
                    "No field changes remain for this innings.",
                    "🎯 <b>Points: 0/3</b>",
                    "The bowling captain has used all 3 field changes.",
                ],
                "🔐",
            ),
            parse_mode=ParseMode.HTML,
        )
        return

    used, remaining, position = _real_field_status(match)
    captain_name = bowling_captain.first_name if bowling_captain else "Bowling Captain"
    actor_note = "Host emergency control" if is_host and not is_captain else "Bowling Captain"

    text = themed(
        "🎯 FIELD CONTROL",
        [
            f"🥎 <b>Bowling Captain:</b> {html.escape(captain_name)}",
            f"📍 <b>Current Field:</b> {html.escape(position)}",
            f"🎯 <b>Points:</b> {used}/3",
            f"🔋 <b>Changes Remaining:</b> {remaining}",
            f"👤 <b>Control:</b> {actor_note}",
            "",
            "Choose the new field placement below.",
            "Each successful change costs <b>1 point</b>.",
        ],
        "🎯",
    )

    await update.message.reply_text(
        text,
        parse_mode=ParseMode.HTML,
        reply_markup=_real_field_keyboard(chat.id),
    )


async def field_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Apply a selected Real Cricket field placement and consume one point."""
    query = update.callback_query
    await query.answer()

    data = query.data or ""
    parts = data.split("_")
    if len(parts) != 3:
        return

    action = parts[1]
    try:
        group_id = int(parts[2])
    except (ValueError, TypeError):
        await query.answer(plain_alert("❌ Invalid field control."), show_alert=True)
        return

    if group_id not in active_matches:
        await query.answer(plain_alert("⚠️ No active match!"), show_alert=True)
        return

    match = active_matches[group_id]

    if not getattr(match, "is_real_cricket", False):
        await query.answer(plain_alert("⚠️ Real Cricket Mode only."), show_alert=True)
        return

    if match.phase != GamePhase.MATCH_IN_PROGRESS:
        await query.answer(plain_alert("⚠️ Match is not in progress."), show_alert=True)
        return

    bowling_captain = match.get_captain(match.current_bowling_team)
    is_captain = bool(bowling_captain and query.from_user.id == bowling_captain.user_id)
    is_host = bool(match.host_id and query.from_user.id == match.host_id)

    if not is_captain and not is_host:
        await query.answer(plain_alert("🚫 Only the current bowling captain or Host can change the field."), show_alert=True)
        return

    remaining = match.real_field_points.get(match.innings, 3)
    if remaining <= 0:
        await query.answer("🔐 No field changes remain in this innings.", show_alert=True)
        return

    positions = {
        "boundary": "On Boundary",
        "circle": "Inside Circle",
        "balanced": "Balanced",
    }
    position = positions.get(action)
    if not position:
        await query.answer(plain_alert("❌ Invalid field option."), show_alert=True)
        return

    # A click on the already-active field does not waste a point.
    current = match.real_field_position.get(match.innings, "Balanced")
    if current == position:
        await query.answer(f"ℹ️ Field is already set to {position}.", show_alert=True)
        return

    # Consume exactly one point only after all validation passes.
    match.real_field_points[match.innings] = remaining - 1
    match.real_field_change_count[match.innings] = (
        match.real_field_change_count.get(match.innings, 0) + 1
    )
    match.real_field_position[match.innings] = position

    used = 3 - match.real_field_points[match.innings]
    left = match.real_field_points[match.innings]

    try:
        await query.edit_message_text(
            themed(
                "✅ FIELD CHANGED",
                [
                    f"📍 <b>New Field:</b> {html.escape(position)}",
                    f"🎯 <b>Points:</b> {used}/3",
                    f"🔋 <b>Changes Remaining:</b> {left}",
                    f"🥎 <b>Bowling Team:</b> {html.escape(match.current_bowling_team.name)}",
                    "",
                    (
                        "🔐 <b>No field change remains for this innings.</b>"
                        if left == 0
                        else "Captain can use <code>/field</code> again when another change is needed."
                    ),
                ],
                "🎯",
            ),
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        pass


