async def bannedgroups_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Show list of all banned groups (Owner Only)
    """
    user = update.effective_user
    
    if not has_power(user.id, "ban"):
        return
    
    if not banned_groups:
        await update.message.reply_text(
            "✅ <b>NO BANNED GROUPS</b>\n\n"
            "Currently, no groups are banned from using the bot.",
            parse_mode=ParseMode.HTML
        )
        return
    
    msg = f"🚫 <b>BANNED GROUPS LIST</b>\n"
    msg += f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += f"📊 <b>Total:</b> {len(banned_groups)} groups\n\n"
    
    for i, chat_id in enumerate(banned_groups, 1):
        # Try to get group name
        try:
            chat_info = await context.bot.get_chat(chat_id)
            group_name = chat_info.title
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 9601)")
            group_name = "Unknown/Left Group"
        
        msg += f"{i}. <b>{group_name}</b>\n"
        msg += f"   🆔 <code>{chat_id}</code>\n\n"
        
        # Telegram message limit protection
        if len(msg) > 3500:
            await update.message.reply_text(msg, parse_mode=ParseMode.HTML)
            msg = "<b>...continued</b>\n\n"
    
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += "<i>Use /unbangroup [id] to unban</i>"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

async def unbangroup_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Unban a group (Owner Only)
    Usage: 
      - In group: /unbangroup
      - Via DM: /unbangroup -1001234567890
    """
    user = update.effective_user
    
    # Owner check
    if not has_power(user.id, "ban"):
        return
    
    chat = update.effective_chat
    
    # Method 1: Command used in the group itself
    if chat.type in ["group", "supergroup"]:
        target_chat_id = chat.id
        target_chat_name = chat.title
    
    # Method 2: Command used in DM with group ID
    elif context.args:
        try:
            target_chat_id = int(context.args[0])
            
            # Try to get group info
            try:
                chat_info = await context.bot.get_chat(target_chat_id)
                target_chat_name = chat_info.title
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 9646)")
                target_chat_name = "Unknown Group"
        except ValueError:
            await update.message.reply_text(
                "⚠️ <b>Invalid Group ID</b>\n\n"
                "<b>Usage:</b>\n"
                "In Group: <code>/unbangroup</code>\n"
                "In DM: <code>/unbangroup -1001234567890</code>",
                parse_mode=ParseMode.HTML
            )
            return
    else:
        await update.message.reply_text(
            "⚠️ <b>Usage:</b>\n"
            "In Group: <code>/unbangroup</code>\n"
            "In DM: <code>/unbangroup [group_id]</code>\n\n"
            "<b>Example:</b> <code>/unbangroup -1001234567890</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if actually banned
    if target_chat_id not in banned_groups:
        await update.message.reply_text(
            f"⚠️ <b>{target_chat_name}</b> (<code>{target_chat_id}</code>) is not banned!",
            parse_mode=ParseMode.HTML
        )
        return
    
    # ✅ UNBAN THE GROUP
    banned_groups.discard(target_chat_id)
    save_data()
    
    # Notify the group
    await notify_ban_status(context, target_chat_id, is_ban=False)
    
    # Confirm to owner
    await update.message.reply_text(
        f"✅ <b>GROUP UNBANNED</b>\n\n"
        f"📛 <b>Name:</b> {target_chat_name}\n"
        f"🆔 <b>ID:</b> <code>{target_chat_id}</code>\n\n"
        f"✅ This group can now use the bot again.",
        parse_mode=ParseMode.HTML
    )
    
    # Log to support group
    try:
        await context.bot.send_message(
            chat_id=SUPPORT_GROUP_ID,
            text=(
                f"✅ <b>GROUP UNBANNED</b>\n"
                f"📛 {target_chat_name}\n"
                f"🆔 <code>{target_chat_id}</code>\n"
                f"👤 By: {user.first_name}"
            ),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 9703)")
        pass

# ==================== ACHIEVEMENTS ADMIN COMMANDS ====================

def _resolve_achievement_target(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Resolve (target_id, target_name, achievement_text) for /addach and /removeach.
    Supports: reply, @username, or numeric user ID. Returns (None, None, error_text) on failure.
    """
    args = list(context.args) if context.args else []

    if update.message.reply_to_message:
        target_user = update.message.reply_to_message.from_user
        target_id = target_user.id
        target_name = target_user.first_name
        text = " ".join(args).strip()
        if not text:
            return None, None, None
        return target_id, target_name, text

    if not args:
        return None, None, None

    first = args[0]
    if first.startswith("@"):
        uname = first[1:].lower()
        found = None
        target_name = None
        for uid, data in user_data.items():
            if (data.get("username") or "").lower() == uname:
                found = uid
                target_name = data.get("first_name", uname)
                break
        if not found:
            return None, None, "not_found"
        text = " ".join(args[1:]).strip()
        if not text:
            return None, None, None
        return found, target_name, text
    elif first.isdigit():
        target_id = int(first)
        target_name = user_data.get(target_id, {}).get("first_name", str(target_id))
        text = " ".join(args[1:]).strip()
        if not text:
            return None, None, None
        return target_id, target_name, text
    else:
        return None, None, None


async def addach_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    🏆 Add an achievement to a player's /mystats card (Owner / Approved Members only).
    Usage:
      /addach (reply to user) Achievement Text
      /addach @username Achievement Text
      /addach 123456789 Achievement Text
    """
    user = update.effective_user

    if not has_power(user.id, "achievements"):
        await update.message.reply_text(
            "❌ <b>Permission Denied</b>\nOnly the Bot Owner or Approved Members can use this command.",
            parse_mode=ParseMode.HTML
        )
        return

    target_id, target_name, ach_text = _resolve_achievement_target(update, context)

    if target_id is None:
        if ach_text == "not_found":
            await update.message.reply_text(
                "❌ <b>Not Found</b>\nCouldn't resolve that username. Try replying to their message, or use their numeric user ID instead.",
                parse_mode=ParseMode.HTML
            )
        else:
            await update.message.reply_text(
                "⚙️ <b>Usage</b>\n"
                "• <code>/addach</code> (reply to user) Achievement Text\n"
                "• <code>/addach @username</code> Achievement Text\n"
                "• <code>/addach 123456789</code> Achievement Text",
                parse_mode=ParseMode.HTML
            )
        return

    user_achievements = achievements.setdefault(target_id, [])

    # Duplicate protection (case-insensitive match)
    if any(existing.lower() == ach_text.lower() for existing in user_achievements):
        await update.message.reply_text(
            "❌ Player already has this achievement.",
            parse_mode=ParseMode.HTML
        )
        return

    user_achievements.append(ach_text)
    save_data()

    await update.message.reply_text(
        f"🏆 <b>Achievement Added!</b>\n"
        f"👤 Player: {html.escape(target_name or str(target_id))}\n"
        f"🎖️ Achievement: {html.escape(ach_text)}",
        parse_mode=ParseMode.HTML
    )


async def removeach_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    🗑️ Remove an achievement from a player's /mystats card (Owner / Approved Members only).
    Usage:
      /removeach (reply to user) Achievement Text
      /removeach @username Achievement Text
      /removeach 123456789 Achievement Text
    """
    user = update.effective_user

    if not has_power(user.id, "achievements"):
        await update.message.reply_text(
            "❌ <b>Permission Denied</b>\nOnly the Bot Owner or Approved Members can use this command.",
            parse_mode=ParseMode.HTML
        )
        return

    target_id, target_name, ach_text = _resolve_achievement_target(update, context)

    if target_id is None:
        if ach_text == "not_found":
            await update.message.reply_text(
                "❌ <b>Not Found</b>\nCouldn't resolve that username. Try replying to their message, or use their numeric user ID instead.",
                parse_mode=ParseMode.HTML
            )
        else:
            await update.message.reply_text(
                "⚙️ <b>Usage</b>\n"
                "• <code>/removeach</code> (reply to user) Achievement Text\n"
                "• <code>/removeach @username</code> Achievement Text\n"
                "• <code>/removeach 123456789</code> Achievement Text",
                parse_mode=ParseMode.HTML
            )
        return

    user_achievements = achievements.get(target_id, [])
    match = next((a for a in user_achievements if a.lower() == ach_text.lower()), None)

    if not match:
        await update.message.reply_text(
            "❌ Player doesn't have this achievement.",
            parse_mode=ParseMode.HTML
        )
        return

    user_achievements.remove(match)
    save_data()

    await update.message.reply_text(
        f"🗑️ <b>Achievement Removed</b>\n"
        f"👤 Player: {html.escape(target_name or str(target_id))}\n"
        f"🎖️ Achievement: {html.escape(match)}",
        parse_mode=ParseMode.HTML
    )


# ==================== GROUP BAN MIDDLEWARE ====================

def clear_penalty_bans(user_id: int):
    """Wipes any active bowling-timeout / endmatch penalty ban (and their
    continuous strike streaks) for this user. Used by /ignore and by the
    owner's 'Unban (Forgive)' button."""
    try:
        conn = db_connect(DB_PATH)
        c = conn.cursor()
        c.execute(
            "UPDATE user_stats SET bowling_ban_until='', bowling_strike_count=0, "
            "endmatch_ban_until='', endmatch_strike_count=0 WHERE user_id=?",
            (user_id,)
        )
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"clear_penalty_bans failed for {user_id}: {e}")


async def ignore_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /ignore — Owner / Powered Users only. Instantly clears a player's active
    penalty ban (bowling-timeout or endmatch), so they can join/start matches again.
    Usage:
      /ignore (reply to user)
      /ignore @username
      /ignore 123456789
    """
    user = update.effective_user
    if not user:
        return

    if not has_power(user.id, "ignore"):
        await update.message.reply_text(
            "❌ <b>Permission Denied</b>\nOnly the Bot Owner or Approved Members can use this command.",
            parse_mode=ParseMode.HTML
        )
        return

    target_id = None
    target_name = None
    args = list(context.args) if context.args else []

    if update.message.reply_to_message:
        target_user = update.message.reply_to_message.from_user
        target_id = target_user.id
        target_name = target_user.first_name
    elif args:
        first = args[0]
        if first.startswith("@"):
            uname = first[1:].lower()
            for uid, data in user_data.items():
                if (data.get("username") or "").lower() == uname:
                    target_id = uid
                    target_name = data.get("first_name", uname)
                    break
            if target_id is None:
                await update.message.reply_text(
                    "❌ <b>Not Found</b>\nCouldn't resolve that username. Try replying to their message, or use their numeric user ID instead.",
                    parse_mode=ParseMode.HTML
                )
                return
        elif first.isdigit():
            target_id = int(first)
            target_name = user_data.get(target_id, {}).get("first_name", str(target_id))
        else:
            await update.message.reply_text(
                "❌ <b>Invalid</b>\nProvide a valid <code>@username</code>, numeric user ID, or reply to the user's message.",
                parse_mode=ParseMode.HTML
            )
            return
    else:
        await update.message.reply_text(
            "⚙️ <b>Usage</b>\n"
            "• <code>/ignore</code> (reply to user)\n"
            "• <code>/ignore @username</code>\n"
            "• <code>/ignore 123456789</code>",
            parse_mode=ParseMode.HTML
        )
        return

    had_bowl_ban = get_bowling_ban_remaining(target_id) is not None
    had_endmatch_ban = get_endmatch_ban_remaining(target_id) is not None

    if not had_bowl_ban and not had_endmatch_ban:
        await update.message.reply_text(
            f"ℹ️ <b>{target_name or target_id}</b> doesn't have any active penalty ban to ignore.",
            parse_mode=ParseMode.HTML
        )
        return

    clear_penalty_bans(target_id)
    await update.message.reply_text(
        f"✅ <b>Penalty cleared for {target_name or target_id}!</b> They can join or start a match again.",
        parse_mode=ParseMode.HTML
    )

    try:
        await context.bot.send_message(
            chat_id=target_id,
            text="🎉 <b>Good news!</b> Your penalty ban has been lifted by the bot admin — you can join or start matches again.",
            parse_mode=ParseMode.HTML
        )
    except Exception:
        pass


async def ownerunban_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles the owner's 'Unban (Forgive)' button on the ban-notification DM."""
    query = update.callback_query
    user = update.effective_user

    if not user or not has_power(user.id, "ban"):
        await query.answer(plain_alert("⛔ Only the bot owner can use this."), show_alert=True)
        return

    try:
        _, ban_type, target_id_str = query.data.split("_", 2)
        target_id = int(target_id_str)
    except Exception:
        await query.answer(plain_alert("⚠️ Invalid button data."), show_alert=True)
        return

    clear_penalty_bans(target_id)
    await query.answer(plain_alert("✅ Player forgiven — ban lifted!"), show_alert=True)

    try:
        await query.edit_message_reply_markup(reply_markup=None)
        forgiven_line = "✅ <b>Forgiven by owner — ban lifted.</b>"
        new_text = (query.message.text_html or query.message.text or rc_stored_plain(query.message.chat_id, query.message.message_id) or "") + "\n\n" + forgiven_line
        await query.edit_message_text(new_text, parse_mode=ParseMode.HTML)
    except Exception:
        pass

    try:
        await context.bot.send_message(
            chat_id=target_id,
            text="🎉 <b>Good news!</b> The bot owner has forgiven your penalty ban — you can join or start matches again.",
            parse_mode=ParseMode.HTML
        )
    except Exception:
        pass


async def ban_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    🚫 Ban a player from using the bot (OWNER ONLY).
    Usage:
      /cban (reply to user)      [reason]
      /cban @username            [reason]
      /cban 123456789            [reason]
    Any non-owner attempting this command is silently ignored.
    """
    user = update.effective_user

    # Owner-only — everyone else is ignored silently, no reply at all.
    if not has_power(user.id, "ban"):
        return
    reload_banned_users_if_changed()

    target_id = None
    target_name = None
    reason_args = list(context.args) if context.args else []

    if update.message.reply_to_message:
        target_user = update.message.reply_to_message.from_user
        target_id = target_user.id
        target_name = target_user.first_name
        reason = " ".join(reason_args) if reason_args else "No reason provided"
    else:
        if not reason_args:
            await update.message.reply_text(
                themed("⚙️ USAGE", [
                    "<code>/cban</code> (reply to user) [reason]",
                    "<code>/cban @username</code> [reason]",
                    "<code>/cban 123456789</code> [reason]",
                ], "⚙️"),
                parse_mode=ParseMode.HTML
            )
            return

        first = reason_args[0]
        if first.startswith("@"):
            uname = first[1:].lower()
            found = None
            for uid, data in user_data.items():
                if (data.get("username") or "").lower() == uname:
                    found = uid
                    target_name = data.get("first_name", uname)
                    break
            if not found:
                await update.message.reply_text(
                    themed("❌ NOT FOUND", [
                        "Couldn't resolve that username.",
                        "Try replying to their message, or use their numeric user ID instead."
                    ], "❌"),
                    parse_mode=ParseMode.HTML
                )
                return
            target_id = found
            reason_args = reason_args[1:]
        elif first.isdigit():
            target_id = int(first)
            target_name = user_data.get(target_id, {}).get("first_name", str(target_id))
            reason_args = reason_args[1:]
        else:
            await update.message.reply_text(
                themed("❌ INVALID", [
                    "Provide a valid <code>@username</code>, numeric user ID, or reply to the user's message."
                ], "❌"),
                parse_mode=ParseMode.HTML
            )
            return

        reason = " ".join(reason_args) if reason_args else "No reason provided"

    if target_id == OWNER_ID:
        await update.message.reply_text(
            themed("❌ NOPE", ["You can't ban yourself, boss 😅"], "❌"),
            parse_mode=ParseMode.HTML
        )
        return

    banned_users[target_id] = {
        "reason": reason,
        "banned_by": user.id,
        "banned_at": datetime.now().isoformat(),
        "name": target_name or str(target_id),
    }
    save_banned_users()

    # 📩 Tell the player in DM that they got banned (silently skipped if they
    # never started the bot / blocked it — Telegram won't allow that DM).
    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=themed("🚫 YOU GOT BANNED", [
                "You have been <b>banned</b> from this bot.",
                f"📝 Reason: <b>{html.escape(str(reason))}</b>",
                "",
                "You can no longer use any command or play any match.",
                "Contact the bot owner if you think this is a mistake.",
            ], "🚫"),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.info(f"Ban DM to {target_id} failed (probably never started bot): {e}")

    try:
        await update.message.reply_text(
            themed("🚫 USER BANNED", [
                f"👤 <b>{html.escape(str(target_name or target_id))}</b> (<code>{target_id}</code>)",
                f"📝 Reason: <b>{html.escape(str(reason))}</b>",
                "",
                "This user can no longer use any bot command.",
            ], "🚫"),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.error(f"ban_command reply failed: {e}")
        try:
            await update.message.reply_text(f"🚫 Banned {target_id}.")
        except Exception:
            pass


async def unban_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ✅ Unban a previously banned player (OWNER ONLY).
    Usage:
      /unban (reply to user)
      /unban @username
      /unban 123456789
    Any non-owner attempting this command is silently ignored.
    """
    user = update.effective_user

    if not has_power(user.id, "ban"):
        return
    reload_banned_users_if_changed()

    target_id = None

    if update.message.reply_to_message:
        target_id = update.message.reply_to_message.from_user.id
    elif context.args:
        first = context.args[0]
        if first.startswith("@"):
            uname = first[1:].lower()
            for uid, data in user_data.items():
                if (data.get("username") or "").lower() == uname:
                    target_id = uid
                    break
        elif first.isdigit():
            target_id = int(first)

    if target_id is None:
        await update.message.reply_text(
            themed("⚙️ USAGE", [
                "<code>/cunban</code> (reply to user)",
                "<code>/cunban @username</code>",
                "<code>/cunban 123456789</code>",
            ], "⚙️"),
            parse_mode=ParseMode.HTML
        )
        return

    if target_id not in banned_users:
        await update.message.reply_text(
            themed("ℹ️ NOT BANNED", ["This user isn't banned."], "ℹ️"),
            parse_mode=ParseMode.HTML
        )
        return

    info = banned_users.pop(target_id)
    save_banned_users()

    try:
        await update.message.reply_text(
            themed("✅ USER UNBANNED", [
                f"👤 <b>{html.escape(str(info.get('name', target_id)))}</b> (<code>{target_id}</code>)",
                "Can use the bot again.",
            ], "✅"),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.error(f"unban_command reply failed: {e}")
        try:
            await update.message.reply_text(f"✅ Unbanned {target_id}.")
        except Exception:
            pass


_OWN_COMMAND_NAMES_CACHE = None


def _get_own_command_names(application) -> set:
    """Collects every command name this bot itself registered (from all
    CommandHandler instances), cached after first call."""
    global _OWN_COMMAND_NAMES_CACHE
    if _OWN_COMMAND_NAMES_CACHE is None:
        names = set()
        try:
            for handlers in application.handlers.values():
                for h in handlers:
                    if isinstance(h, CommandHandler):
                        names |= set(h.commands)
        except Exception:
            pass
        _OWN_COMMAND_NAMES_CACHE = names
    return _OWN_COMMAND_NAMES_CACHE


def _update_touches_this_bot(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """True only for a genuine interaction with THIS bot — a button press on
    our own message, a reply to our own message, an explicit @our_bot
    mention, or a slash command that matches one of our own registered
    commands. False for someone just sitting/typing in a group the bot
    happens to also be in — e.g. a command meant for a totally different
    bot — since that person has no real association with this bot."""
    if update.callback_query:
        return True
    msg = update.message
    if not msg:
        return False
    reply = msg.reply_to_message
    if reply and reply.from_user and context.bot and reply.from_user.id == context.bot.id:
        return True
    text = msg.text or msg.caption or ""
    bot_username = (context.bot.username or "").lower() if context.bot else ""
    if bot_username and f"@{bot_username}" in text.lower():
        return True
    if text.startswith("/"):
        cmd = text[1:].split()[0].split("@")[0].lower()
        return cmd in _get_own_command_names(context.application)
    return False


async def global_username_cache_updater(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    🗂️ ROSE/GROUPHELP-STYLE GLOBAL USERNAME CACHE
    Runs on EVERY update (any group), registered in group=-1 so it fires
    before anything else — BUT only actually caches/creates a user when the
    update is a genuine interaction with THIS bot (see
    _update_touches_this_bot). Someone typing a command meant for a
    different bot in the same group, or any message that never touches us
    at all, is skipped entirely — they have zero association with this bot
    and shouldn't get a stored profile.

    For users who DO interact with us, we save their id/username/first_name
    into user_data right here, same as Rose/GroupHelp build up their giant
    username—id lookup tables just by watching traffic addressed to them.

    Effect: once a user has sent so much as one command/button-press aimed
    at THIS bot in ANY group, /aucplayer, /addauctionplayer, /impact etc.
    can resolve their @username or numeric ID from then on — even in a
    totally different group, even if they never DMed the bot.
    """
    user = update.effective_user
    if not user or user.is_bot:
        return

    if not _update_touches_this_bot(update, context):
        return  # no real association with this bot — don't store anything

    existing = user_data.get(user.id)
    new_username = user.username or ""
    new_first_name = user.first_name or "Player"

    if existing is None:
        user_data[user.id] = {
            "user_id": user.id,
            "username": new_username,
            "first_name": new_first_name,
            "started_at": datetime.now().isoformat(),
            "total_matches": 0,
        }
        init_player_stats(user.id)
        save_data()
    else:
        # Keep the cached username/name fresh (people change these) without
        # touching stats fields. Only write (and mark dirty) if something
        # actually changed, so this stays a no-op on the common case of
        # rapid repeat messages from the same active players.
        if existing.get("username", "") != new_username or existing.get("first_name", "") != new_first_name:
            existing["username"] = new_username
            existing["first_name"] = new_first_name
            save_data()


async def global_group_registerer(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    🏘️ GLOBAL GROUP AUTO-REGISTER
    Runs on EVERY update (any message/button-press — not just bot commands),
    registered in group=-2 so it fires before anything else, same pattern as
    global_username_cache_updater above.

    Previously a group only entered `registered_groups` when an admin
    explicitly changed the commentary style (see the two `if group_id not in
    registered_groups:` blocks elsewhere in the file). That meant a group
    that used the bot for months but never touched that one setting never
    showed up as "registered" — undercounting Groups/Active Groups on
    /botstats and skipping it for group-wide features that key off
    registered_groups (e.g. broadcast-to-groups, banned-groups checks).

    Now: the moment ANYONE interacts with the bot in a group (any message or
    callback the bot receives), that group is registered immediately.
    """
    chat = update.effective_chat
    if not chat or chat.type not in ("group", "supergroup"):
        return

    group_id = chat.id
    if group_id in banned_groups:
        return

    if group_id not in registered_groups:
        registered_groups[group_id] = {
            "group_id": group_id,
            "group_name": chat.title or "Group",
            "total_matches": 0,
            "commentary_style": "english",
        }
        save_data()
    else:
        # Keep the cached group name fresh (groups get renamed) without
        # touching other settings. Only write when it actually changed.
        current_name = chat.title or "Group"
        if registered_groups[group_id].get("group_name") != current_name:
            registered_groups[group_id]["group_name"] = current_name
            save_data()


GLOBAL_CMD_SPAM_WINDOW_SECONDS = 5         # how far back we look for spam
GLOBAL_CMD_SPAM_THRESHOLD = 10              # commands within the window that count as spam
GLOBAL_CMD_SPAM_IGNORE_SECONDS = 15 * 60   # how long we then ignore them (15 min)
_cmd_spam_history: Dict[int, List[float]] = {}
_cmd_spam_ignored_until: Dict[int, float] = {}


async def global_command_spam_guard(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    🚫 Runs before every other handler (registered in group=-1).
    If a user fires commands too fast (more than GLOBAL_CMD_SPAM_THRESHOLD
    within GLOBAL_CMD_SPAM_WINDOW_SECONDS), every command from them is
    silently ignored for the next 15 minutes.
    """
    user = update.effective_user
    if not user or user.id == OWNER_ID:
        return

    msg = update.effective_message
    if not (msg and msg.text and msg.text.startswith("/")):
        return  # only rate-limit actual commands, not plain text/buttons

    now = time.time()
    uid = user.id

    ignored_until = _cmd_spam_ignored_until.get(uid)
    if ignored_until:
        if now < ignored_until:
            raise ApplicationHandlerStop  # fully silent — command just does nothing
        _cmd_spam_ignored_until.pop(uid, None)
        _cmd_spam_history.pop(uid, None)

    history = _cmd_spam_history.setdefault(uid, [])
    history.append(now)
    cutoff = now - GLOBAL_CMD_SPAM_WINDOW_SECONDS
    while history and history[0] < cutoff:
        history.pop(0)

    if len(history) >= GLOBAL_CMD_SPAM_THRESHOLD:
        _cmd_spam_ignored_until[uid] = now + GLOBAL_CMD_SPAM_IGNORE_SECONDS
        _cmd_spam_history.pop(uid, None)
        try:
            await msg.reply_text(
                "🚫 <b>Slow down!</b> You're sending commands too fast — "
                "your commands will be <b>ignored for the next 15 minutes</b>.",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass
        raise ApplicationHandlerStop


async def global_user_ban_enforcer(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    🛡️ Runs before every other handler (registered in group=-1).
    Blocks any command or button-press from a banned user.

    Behaviour:
      - /game and /mystats  -> reply showing the ban reason.
      - Every other command -> silently ignored (no reply at all).
      - Join buttons (join_team_x / join_team_y / solo_join*) -> silently
        ignored so the banned user is never added to the match.
      - Every other button press -> silently ignored too.
    """
    user = update.effective_user
    if not user or user.id == OWNER_ID:
        return

    reload_banned_users_if_changed()  # 🔄 pick up bans made from main bot / other clones

    # 🚫 ENDMATCH-STRIKE BAN: only blocks STARTING/JOINING new matches
    # (/game command and join_team_x / join_team_y / solo_join buttons).
    # Does not touch matches the player is already inside, and doesn't
    # silence any other command the way a full ban does.
    em_ban_left = get_endmatch_ban_remaining(user.id)
    if em_ban_left:
        if update.callback_query and update.callback_query.data in ("join_team_x", "join_team_y", "solo_join"):
            try:
                await update.callback_query.answer(
                    plain_alert(f"🚫 Banned from starting/joining matches for repeated early /endmatch use. Time left: {_format_ban_remaining(em_ban_left)}"),
                    show_alert=True
                )
            except Exception:
                pass
            raise ApplicationHandlerStop
        msg_em = update.effective_message
        if msg_em and msg_em.text and msg_em.text.startswith("/"):
            cmd_em = msg_em.text[1:].split()[0].split("@")[0].lower() if len(msg_em.text) > 1 else ""
            if cmd_em == "game":
                try:
                    await msg_em.reply_text(
                        "<blockquote>🚫 <b>Match-Start Banned</b>\n"
                        f"You can't start or join a new match for another <b>{_format_ban_remaining(em_ban_left)}</b> "
                        "(repeated early /endmatch use).</blockquote>",
                        parse_mode=ParseMode.HTML
                    )
                except Exception:
                    pass
                raise ApplicationHandlerStop

    ban_info = banned_users.get(user.id)
    if not ban_info:
        return

    reason = ban_info.get("reason", "No reason provided")

    # ── Button presses: always silent, never let them take effect ──
    if update.callback_query:
        try:
            await update.callback_query.answer()  # clears the loading spinner, no alert text
        except Exception:
            pass
        raise ApplicationHandlerStop

    # ── Any message from a banned user, command or plain text ──
    # 🩹 FIX: this used to only stop messages that started with "/", so a
    # banned player could still fully play the game — bowling/batting
    # numbers are typed as plain text (e.g. in DM), not sent as commands or
    # buttons, so those messages fell straight through this check and were
    # processed normally. A banned user must be blocked from EVERY message,
    # not just slash-commands, or the ban does nothing during actual gameplay.
    # A fully banned user is IGNORED completely: no reply, no alert, nothing —
    # not even /game or /mystats. Commands, typed numbers, buttons (including
    # every join button) are all swallowed here before any handler sees them.
    raise ApplicationHandlerStop


async def check_group_ban(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """
    Check if group is banned. Returns True if allowed, False if banned.
    Call this at the start of every group command.
    """
    chat = update.effective_chat
    
    # Allow private chats and owner commands
    if chat.type == "private":
        return True
    
    if chat.id in banned_groups:
        # Silently ignore (bot won't respond in banned groups)
        logger.info(f"Blocked command in banned group: {chat.id}")
        return False
    
    return True

async def notify_ban_status(context: ContextTypes.DEFAULT_TYPE, chat_id: int, is_ban: bool):
    """Send notification to group about ban/unban"""
    if is_ban:
        msg = (
            "🚫 <b>GROUP BANNED</b> 🚫\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            "This group has been <b>banned</b> from using this bot.\n\n"
            "🔒 All commands are now disabled.\n"
            "📧 Contact bot owner for more information."
        )
    else:
        msg = (
            "✅ <b>GROUP UNBANNED</b> ✅\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            "This group can now use the bot again!\n\n"
            "🎮 Use /game to start playing."
        )
    
    try:
        await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.error(f"Failed to notify group {chat_id}: {e}")

async def save_solo_match_stats(match):
    """Save solo match stats to database"""
    conn= await asyncio.to_thread(db_connect, DB_PATH)
    c = conn.cursor()
    
    # Get top 3 players
    sorted_players = sorted(
        match.solo_players.items(),
        key=lambda x: x[1]['runs'],
        reverse=True
    )[:3]
    
    for user_id, stats in match.solo_players.items():
        username = stats.get('username', 'Unknown')
        first_name = stats.get('first_name', 'Player')
        
        # Update user stats
        c.execute("SELECT user_id FROM user_stats WHERE user_id = ?", (user_id,))
        exists = c.fetchone()
        
        if not exists:
            c.execute("""
                INSERT INTO user_stats (user_id, username, first_name, total_runs, 
                                       total_balls_faced, matches_played)
                VALUES (?, ?, ?, ?, ?, 1)
            """, (user_id, username, first_name, stats['runs'], stats['balls']))
        else:
            c.execute("""
                UPDATE user_stats 
                SET total_runs = total_runs + ?,
                    total_balls_faced = total_balls_faced + ?,
                    matches_played = matches_played + 1,
                    highest_score = MAX(highest_score, ?),
                    username = ?,
                    first_name = ?
                WHERE user_id = ?
            """, (stats['runs'], stats['balls'], stats['runs'], 
                  username, first_name, user_id))
        
        # Check for fifties/hundreds
        if stats['runs'] >= 100:
            c.execute("UPDATE user_stats SET total_hundreds = total_hundreds + 1 WHERE user_id = ?", (user_id,))
        elif stats['runs'] >= 50:
            c.execute("UPDATE user_stats SET total_fifties = total_fifties + 1 WHERE user_id = ?", (user_id,))
    
    # Save match history
    winner_id = sorted_players[0][0] if sorted_players else None
    c.execute("""
        INSERT INTO match_history 
        (group_id, match_type, player_of_match, match_date)
        VALUES (?, 'SOLO', ?, CURRENT_TIMESTAMP)
    """, (match.group_id, winner_id))
    
    conn.commit()
    conn.close()

    # 🎽 Mark all participants as active today so their jersey numbers stay safe
    try:
        touch_jersey_activity(list(match.solo_players.keys()))
    except Exception as jersey_err:
        logger.error(f"Jersey activity touch error: {jersey_err}")

    # 🚫 Endmatch strike reset: this solo match completed naturally (stats
    # saved), so break the host's continuous "incomplete game" strike streak.
    try:
        if getattr(match, 'host_id', None):
            reset_endmatch_strike_on_clean_match(match.host_id)
    except Exception as e:
        logger.error(f"endmatch-strike reset (solo) failed: {e}")

    # 🏅 Tier/Achievements check — solo mode.
    try:
        sync_legacy_player_stats_to_ccc()
        for user_id in match.solo_players.keys():
            newly = await asyncio.to_thread(check_and_award_achievements, user_id)
            if newly:
                asyncio.create_task(notify_new_achievements_via_bot(user_id, newly))
    except Exception as e:
        logger.error(f"solo-mode achievement check failed: {e}")

async def bangroup_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Ban a group from using the bot (Owner Only)
    Usage: 
      - In group: /bangroup
      - Via DM: /bangroup -1001234567890
    """
    user = update.effective_user
    
    # Owner check
    if not has_power(user.id, "ban"):
        return
    
    chat = update.effective_chat
    
    # Method 1: Command used in the group itself
    if chat.type in ["group", "supergroup"]:
        target_chat_id = chat.id
        target_chat_name = chat.title
    
    # Method 2: Command used in DM with group ID as argument
    elif context.args:
        try:
            target_chat_id = int(context.args[0])
            
            # Try to get group info
            try:
                chat_info = await context.bot.get_chat(target_chat_id)
                target_chat_name = chat_info.title
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 10206)")
                target_chat_name = "Unknown Group"
        except ValueError:
            await update.message.reply_text(
                "⚠️ <b>Invalid Group ID</b>\n\n"
                "<b>Usage:</b>\n"
                "In Group: <code>/bangroup</code>\n"
                "In DM: <code>/bangroup -1001234567890</code>",
                parse_mode=ParseMode.HTML
            )
            return
    else:
        await update.message.reply_text(
            "⚠️ <b>Usage:</b>\n"
            "In Group: <code>/bangroup</code>\n"
            "In DM: <code>/bangroup [group_id]</code>\n\n"
            "<b>Example:</b> <code>/bangroup -1001234567890</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if already banned
    if target_chat_id in banned_groups:
        await update.message.reply_text(
            f"⚠️ <b>{target_chat_name}</b> (<code>{target_chat_id}</code>) is already banned!",
            parse_mode=ParseMode.HTML
        )
        return
    
    # ✅ BAN THE GROUP
    banned_groups.add(target_chat_id)
    save_data()
    
    # End any active match in that group
    if target_chat_id in active_matches:
        match = active_matches[target_chat_id]
        match.phase = GamePhase.MATCH_ENDED
        
        # Cancel all tasks
        if match.ball_timeout_task: match.ball_timeout_task.cancel()
        if match.batsman_selection_task: match.batsman_selection_task.cancel()
        if match.bowler_selection_task: match.bowler_selection_task.cancel()
        if hasattr(match, 'join_phase_task') and match.join_phase_task: 
            match.join_phase_task.cancel()
        
        del active_matches[target_chat_id]
    
    # Notify the group
    await notify_ban_status(context, target_chat_id, is_ban=True)
    
    # Confirm to owner
    await update.message.reply_text(
        f"✅ <b>GROUP BANNED</b>\n\n"
        f"📛 <b>Name:</b> {target_chat_name}\n"
        f"🆔 <b>ID:</b> <code>{target_chat_id}</code>\n\n"
        f"🚫 This group can no longer use the bot.For unban contact @ASTRO_SHUBH",
        parse_mode=ParseMode.HTML
    )
    
    # Log to support group
    try:
        await context.bot.send_message(
            chat_id=SUPPORT_GROUP_ID,
            text=(
                f"🚫 <b>GROUP BANNED</b>\n"
                f"📛 {target_chat_name}\n"
                f"🆔 <code>{target_chat_id}</code>\n"
                f"👤 By: {user.first_name}"
            ),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 10277)")
        pass

async def process_player_number(update: Update, context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, number: int):
    """Process number sent by player"""
    user = update.effective_user
    
    batsman = match.current_batting_team.players[match.current_batting_team.current_batsman_idx]
    bowler = match.current_bowling_team.players[match.current_bowling_team.current_bowler_idx]
    
    # Check if bowler sent number
    if user.id == bowler.user_id and match.current_ball_data.get("bowler_number") is None:
        match.current_ball_data["bowler_number"] = number
        # ⚡ SPEED FIX: don't await this DM confirmation before the GC prompt —
        # awaiting it here was a blocking network round-trip that delayed the
        # "batting kro" group message by 2-3s on every ball. Fire it in the
        # background instead so it can't hold up request_batsman_number().
        asyncio.create_task(update.message.reply_text(f"Your number: {number}\nWaiting for batsman..."))
        
        # Cancel bowler timeout task
        if match.ball_timeout_task:
            match.ball_timeout_task.cancel()
        
        # Now request batsman number
        await request_batsman_number(context, group_id, match)
        return
    
    # Check if batsman sent number
    if user.id == batsman.user_id and match.current_ball_data.get("batsman_number") is None:
        if match.current_ball_data.get("bowler_number") is None:
            await update.message.reply_text("Please wait for bowler to send their number first.")
            return
        
        match.current_ball_data["batsman_number"] = number
        # ⚡ SPEED FIX: same fix as above — fire-and-forget so it doesn't
        # delay the "bowling kro" GC message / next bowler DM.
        asyncio.create_task(update.message.reply_text(f"Your number: {number}\nProcessing ball..."))
        
        # Cancel batsman timeout task
        if match.ball_timeout_task:
            match.ball_timeout_task.cancel()
        
        # Process ball result
        await process_ball_result(context, group_id, match)
        return

async def request_batsman_number(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Request batsman number with GIF - FIXED"""
    batsman = match.current_batting_team.players[match.current_batting_team.current_batsman_idx]
    
    batsman_tag = f'<a href=\"tg://user?id={batsman.user_id}\">{html.escape(batsman.first_name)}</a>' + _title_suffix(batsman.user_id)
    
    sr_live = round((batsman.runs / batsman.balls_faced) * 100, 1) if batsman.balls_faced > 0 else 0.0
    text = themed(
        "BATTING",
        [
            f"{batsman_tag} — {batsman.runs}({batsman.balls_faced}) • SR: {sr_live}",
            f"📊 Score: <b>{match.current_batting_team.score}</b>",
        ],
        "🔴",
    )
    
    # ✅ FIX: Add GIF
    batting_gif = BALL_TIME_BATTING_GIF  # Cricket batting GIF
    
    _t0 = time.monotonic()
    _cache_state = "URL(no-cache)" if not isinstance(batting_gif, Path) else (
        "HIT" if _animation_file_id_cache.get(str(batting_gif)) else "MISS(disk-upload)"
    )
    try:
        await context.bot.send_animation(
            group_id,
            animation=batting_gif,
            caption=text,
            parse_mode=ParseMode.HTML
        )
        logger.info(f"✅ [BATTING GIF] sent | cache={_cache_state} | took={time.monotonic()-_t0:.2f}s")
    except Exception as e:
        logger.error(f"❌ [BATTING GIF] failed: {e} | cache={_cache_state} | took={time.monotonic()-_t0:.2f}s")
        await context.bot.send_message(group_id, text, parse_mode=ParseMode.HTML)
    
    if match.ball_timeout_task:
        match.ball_timeout_task.cancel()
    match.ball_timeout_task = asyncio.create_task(
        game_timer(context, group_id, match, "batsman", batsman.first_name, seq=bump_ball_seq(match))
    )

async def wait_for_batsman_number(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """⚡ SPEED FIX: wait for batsman to send number — total window now under 5s (was 60s)."""
    batsman = match.current_batting_team.players[match.current_batting_team.current_batsman_idx]
    
    try:
        # Wait 2 seconds
        await asyncio.sleep(2)
        
        if match.current_ball_data.get("batsman_number") is None:
            # Send reminder at 2s
            try:
                await context.bot.send_message(
                    chat_id=batsman.user_id,
                    text="<blockquote>— 🚨 2s LEFT! \n🏏 Bat NOW or -6 run penalty!\n</blockquote>",
                    parse_mode=ParseMode.HTML
                )
            except Exception as e:
                logger.error(f"Error sending reminder to batsman: {e}")
        
        # Wait final 2 seconds
        await asyncio.sleep(2)
        
        if match.current_ball_data.get("batsman_number") is None:
            # Timeout - handle penalty
            await handle_batsman_timeout(context, group_id, match)
    
    except asyncio.CancelledError:
        pass

async def handle_batsman_timeout(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Handle batsman timeout penalty"""
    batsman = match.current_batting_team.players[match.current_batting_team.current_batsman_idx]
    batsman.batting_timeouts += 1
    
    timeout_count = batsman.batting_timeouts
    
    # Penalty: -6 runs
    match.current_batting_team.score -= 6
    match.current_batting_team.score = max(0, match.current_batting_team.score)
    match.current_batting_team.penalty_runs += 6
    # Update current_over_runs to reflect penalty (so worm/bar chart shows correct values)
    match.current_over_runs = max(0, getattr(match, 'current_over_runs', 0) - 6)
    
    if timeout_count >= 3:
        # Auto out - Hit Wicket
        batsman.is_out = True
        batsman.dismissal_type = "Hit Wicket (Timeout)"
        match.current_batting_team.wickets += 1
        
        # ✅ FIX: Update player_stats dismissal field
        if batsman.user_id in match.current_batting_team.player_stats:
            match.current_batting_team.player_stats[batsman.user_id]["dismissal"] = batsman.dismissal_type
        
        gif_url = get_random_gif(MatchEvent.WICKET)
        
        penalty_text = themed(
            "BATSMAN TIMEOUT",
            [
                "🚨 Penalty: -6 runs — OUT!",
                f"🏏 Updated Score: <b>{match.current_batting_team.score}/{match.current_batting_team.wickets}</b>",
                f"⚠️ {html.escape(batsman.first_name)} timed out 3× — wicket.",
            ],
            "⏰",
        )
        
        try:
            if gif_url:
                await context.bot.send_animation(
                    chat_id=group_id,
                    animation=gif_url,
                    caption=penalty_text,
                    parse_mode=ParseMode.HTML
                )
            else:
                await context.bot.send_message(
                    chat_id=group_id,
                    text=penalty_text,
                    parse_mode=ParseMode.HTML
                )
        except Exception as e:
            logger.error(f"Error sending timeout wicket message: {e}")
            await context.bot.send_message(
                chat_id=group_id,
                text=penalty_text,
                parse_mode=ParseMode.HTML
            )
        
        # Log ball
        match.ball_by_ball_log.append({
            "over": format_overs(match.current_batting_team.balls),
            "batsman": batsman.first_name,
            "bowler": match.current_bowling_team.players[match.current_bowling_team.current_bowler_idx].first_name,
            "result": "Wicket (Timeout)",
            "runs": -6,
            "is_wicket": True
        })
        
        await asyncio.sleep(0.3)  # ⚡ SPEED FIX: was 1.5s
        
        # Check if innings over
        if match.is_innings_complete():
            await end_innings(context, group_id, match)
        else:
            # Request new batsman
            match.waiting_for_batsman = True
            await request_batsman_selection(context, group_id, match)
    else:
        penalty_text = themed(
            "BATSMAN TIMEOUT",
            [
                "🚨 Penalty: -6 runs.",
                f"🏏 Updated Score: <b>{match.current_batting_team.score}/{match.current_batting_team.wickets}</b>",
                "⚠️ Avoid delays to prevent further penalties.",
            ],
            "⏰",
        )
        
        await context.bot.send_message(
            chat_id=group_id,
            text=penalty_text,
            parse_mode=ParseMode.HTML
        )
        
        # Reset and wait again
        match.current_ball_data["batsman_number"] = None
        match.current_ball_data["batsman_start_time"] = time.time()
        match.ball_timeout_task = asyncio.create_task(
            wait_for_batsman_number(context, group_id, match)
        )


def _bowl_number_keyboard(gid: int) -> List[List]:
    """🆕 FEATURE: inline 0–6 number pad sent to the bowler in DM, as an
    alternative to typing the number. callback_data carries the group_id so
    the callback handler can find the match without any extra lookup.
    Returns raw button ROWS (not a wrapped InlineKeyboardMarkup).
    Layout (per request): [0][1] / [2][3][4] / [5][6]."""
    def _b(n):
        return styled_button(str(n), callback_data=f"bowldm_{gid}_{n}")
    return [
        [_b(0), _b(1)],
        [_b(2), _b(3), _b(4)],
        [_b(5), _b(6)],
    ]


_BOWL_GROUP_LINK_CACHE: Dict[int, str] = {}
_INVITE_PERM_WARNED: Set[int] = set()


async def _get_bowl_group_redirect_url(context: ContextTypes.DEFAULT_TYPE, group_id: int) -> str:
    """Resolve (and cache) the best URL for the 'Watch in Group' button that
    appears once a delivery locks in. Prefers a real public/invite link over
    the bare t.me/c/<id> deep-link, which only opens for people already in
    the group and isn't always handled consistently across clients.

    🆕 FEATURE: if the bot doesn't have permission to create an invite link
    (not an admin, or missing the 'Invite Users via Link' right), tag the
    group's admins ONCE asking them to grant it, so future buttons work
    properly — instead of silently and repeatedly falling back forever."""
    if group_id in _BOWL_GROUP_LINK_CACHE:
        return _BOWL_GROUP_LINK_CACHE[group_id]

    url = None
    try:
        chat = await context.bot.get_chat(group_id)
        if getattr(chat, "username", None):
            url = f"https://t.me/{chat.username}"
        elif getattr(chat, "invite_link", None):
            url = chat.invite_link
        else:
            try:
                url = await context.bot.export_chat_invite_link(group_id)
            except Exception:
                if group_id not in _INVITE_PERM_WARNED:
                    _INVITE_PERM_WARNED.add(group_id)
                    try:
                        admins = await context.bot.get_chat_administrators(group_id)
                        tags = [
                            f'<a href="tg://user?id={a.user.id}">{html.escape(a.user.first_name)}</a>'
                            for a in admins if not a.user.is_bot
                        ]
                        await context.bot.send_message(
                            group_id,
                            "⚠️ <b>Permission needed for a better experience!</b>\n"
                            f"{', '.join(tags) if tags else 'Admins'} — please grant me the "
                            "<b>Invite Users via Link</b> permission.\n"
                            "This makes the \"Watch in Group\" button in bowler DMs work properly.",
                            parse_mode=ParseMode.HTML
                        )
                    except Exception as e:
                        logger.info(f"could not send invite-link permission notice for {group_id}: {e}")
    except Exception as e:
        logger.info(f"_get_bowl_group_redirect_url: get_chat failed for {group_id}: {e}")

    if not url:
        _cid_str = str(abs(group_id))
        _tme_gid = _cid_str[3:] if _cid_str.startswith("100") else _cid_str
        url = f"https://t.me/c/{_tme_gid}"

    _BOWL_GROUP_LINK_CACHE[group_id] = url
    return url


async def bowl_number_dm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🆕 FEATURE: handles the 0–6 inline number buttons sent to the bowler's
    DM, for every mode (TEAM, TOURNAMENT, SOLO, MAGICBALL).

    Shares the exact same match.current_ball_data lock fields
    ("_bowler_lock" / "bowler_number") that the text-based number entry
    already uses, so whichever arrives first — a typed number or a button
    tap — wins, and the other path's guard rejects the late one.

    Handles a flaky connection cleanly: if the bowler's tap doesn't register
    (bad net) and they mash the same button 15 times, only the FIRST tap
    that actually reaches the bot is accepted. Every repeat after that is
    silently ignored — just an empty callback-answer to clear Telegram's
    loading spinner, no error, no wide-ball penalty. A repeat tap of the
    SAME button is not spam like the text-entry wide-ball check guards
    against (bowling the same number 3 times on purpose); it's the same
    single delivery arriving late or more than once, so the wide/spam logic
    is intentionally skipped for this path entirely.

    On the accepted tap, the DM is edited in place to a locked confirmation
    with a plain "Watch in Group" redirect button (see
    _get_bowl_group_redirect_url), and the batsman is notified + timer
    started, mirroring what the text-entry path does."""
    query = update.callback_query
    data = query.data or ""
    try:
        _, gid_str, num_str = data.split("_", 2)
        gid = int(gid_str)
        num = int(num_str)
    except Exception:
        await query.answer()
        return

    match = active_matches.get(gid)
    if not match:
        await query.answer("⚠️ This match has already ended.", show_alert=True)
        return

    user = query.from_user
    mode = getattr(match, "game_mode", "TEAM")

    bowler = None
    is_solo = mode in ("SOLO", "MAGICBALL") and match.phase == GamePhase.SOLO_MATCH
    if is_solo:
        if match.current_solo_bowl_idx < len(match.solo_players):
            bowler = match.solo_players[match.current_solo_bowl_idx]
    elif mode in ("TEAM", "TOURNAMENT") and match.phase in (GamePhase.MATCH_IN_PROGRESS, GamePhase.SUPER_OVER):
        if match.current_bowling_team and match.current_bowling_team.current_bowler_idx is not None:
            bowler = match.current_bowling_team.players[match.current_bowling_team.current_bowler_idx]

    if not bowler or user.id != bowler.user_id:
        await query.answer("🚫 Not your ball to bowl!", show_alert=True)
        return

    # 🔒 Idempotent lock — first tap (or typed number) in wins. Every
    # subsequent tap, however many, is silently ignored from here on.
    if match.current_ball_data.get("bowler_number") is not None or match.current_ball_data.get("_bowler_lock"):
        await query.answer()
        return
    match.current_ball_data["_bowler_lock"] = True
    match.current_ball_data["bowler_number"] = num
    match.current_ball_data["bowler_id"] = user.id
    bowler.wide_banned_number = None  # a button pick never counts as a wide

    await query.answer(f"🎯 Locked: {num}")

    if match.ball_timeout_task:
        match.ball_timeout_task.cancel()

    locked_lines = [
        f"🎯 Your number: <b>{num}</b>",
        "⏳ <i>Waiting for batsman to play...</i>",
        "🏟️ <i>Watch the result live in the group!</i>",
    ]
    locked_msg = themed("🔒 DELIVERY LOCKED", locked_lines, "🥎")
    try:
        await query.edit_message_text(locked_msg, parse_mode=ParseMode.HTML,
                                       reply_markup=InlineKeyboardMarkup([[
                                           styled_button("Watch in Group", url=await _get_bowl_group_redirect_url(context, gid))
                                       ]]))
    except Exception as e:
        logger.info(f"bowl_number_dm_callback: could not edit DM to locked state: {e}")

    if is_solo:
        bump_solo_ball_seq(match)
        if match.current_solo_bat_idx < len(match.solo_players):
            batter = match.solo_players[match.current_solo_bat_idx]
            sr = round((batter.runs / max(batter.balls_faced, 1)) * 100, 1)
            batter_tag = f'<a href="tg://user?id={batter.user_id}">{html.escape(batter.first_name)}</a>' + _title_suffix(batter.user_id)
            notification_msg = themed(
                "BATTING",
                [
                    f"{batter_tag} ➜ {batter.runs}({batter.balls_faced}) | SR: {sr}",
                    f"📊 Score : {sum(p.runs for p in match.solo_players)}",
                ],
                "🔴",
            )
            try:
                await context.bot.send_animation(gid, BALL_TIME_BATTING_GIF, caption=notification_msg, parse_mode=ParseMode.HTML)
            except Exception:
                await context.bot.send_message(gid, notification_msg, parse_mode=ParseMode.HTML)
            match.ball_timeout_task = asyncio.create_task(
                solo_game_timer(context, gid, match, "batsman", batter.first_name)
            )
    else:
        bat_team = match.current_batting_team
        if bat_team and bat_team.current_batsman_idx is not None:
            striker = bat_team.players[bat_team.current_batsman_idx]
            sr = round((striker.runs / max(striker.balls_faced, 1)) * 100, 1)
            striker_tag = f'<a href="tg://user?id={striker.user_id}">{html.escape(striker.first_name)}</a>' + _title_suffix(striker.user_id)
            notification_msg = (
                "🔴 <b>BATTING</b>\n"
                "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                f"{striker_tag} ➜ {striker.runs}({striker.balls_faced}) | SR: {sr}\n"
                f"📊 Score : {bat_team.score}/{bat_team.wickets}"
            )
            try:
                await context.bot.send_animation(gid, BALL_TIME_BATTING_GIF, caption=notification_msg, parse_mode=ParseMode.HTML)
            except Exception:
                await context.bot.send_message(gid, notification_msg, parse_mode=ParseMode.HTML)
            match.ball_timeout_task = asyncio.create_task(
                game_timer(context, gid, match, "batsman", striker.first_name, seq=bump_ball_seq(match))
            )


async def process_ball_result(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    ✅ COMPLETE FIX: Proper ball counting with OVERS LIMIT CHECK
    """
    # 🔧 GLITCH FIX: if /endmatch or /endall already ended this match, stop here.
    if match.phase == GamePhase.MATCH_ENDED or group_id not in active_matches:
        logger.info("⛔ process_ball_result aborted — match already ended.")
        return

    bat_team = match.current_batting_team
    bowl_team = match.current_bowling_team
    
    if bat_team.current_batsman_idx is None or bowl_team.current_bowler_idx is None:
        logger.error("❌ No batsman or bowler index!")
        return

    bowler_num = match.current_ball_data.get("bowler_number")
    batsman_num = match.current_ball_data.get("batsman_number")
    
    if bowler_num is None or batsman_num is None:
        logger.error("❌ Missing bowler or batsman number!")
        return
    
    striker = bat_team.players[bat_team.current_batsman_idx]
    bowler = bowl_team.players[bowl_team.current_bowler_idx]
    
    # ============================================
    # 🎯 WICKET LOGIC
    # ============================================
    if bowler_num == batsman_num:
        logger.info("❌ Numbers matched - WICKET!")
        
        if match.is_free_hit:
            # Free hit save logic
            half_runs = batsman_num // 2
            bat_team.score += half_runs
            striker.runs += half_runs
            striker.balls_faced += 1
            bowler.balls_bowled += 1
            bowler.runs_conceded += half_runs
            bat_team.balls += 1  # ✅ Sync batting team ball count
            bat_team.update_overs()
            
            commentary = await get_ai_commentary_async("freehit", gc_settings.get(group_id, {}).get("commentary_style", registered_groups.get(group_id, {}).get("commentary_style", "english")))
            
            gif_url = get_random_gif(MatchEvent.FREE_HIT)
            msg = themed("⚡ FREE HIT — SAFE!", [
                f"🛡️ Numbers matched ({batsman_num}) but <b>FREE HIT</b> saves it!",
                f"🏃 <b>+{half_runs} runs</b> awarded",
                f"💬 <i>{commentary}</i>",
                f"📊 Score: <b>{bat_team.score}/{bat_team.wickets}</b>  ✅ <b>NOT OUT</b>",
            ], "⚡", divider=False)
            
            try:
                await context.bot.send_animation(group_id, animation=gif_url, caption=msg, parse_mode=ParseMode.HTML)
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 10556)")
                await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
            
            match.is_free_hit = False
            
            # ✅ CHECK TARGET AFTER FREE HIT
            if match.innings == 2 and bat_team.score >= match.target:
                logger.info("🏆 TARGET CHASED ON FREE HIT!")
                await end_innings(context, group_id, match)
                return
            
            # ✅ CHECK IF OVERS COMPLETE
            if bat_team.balls >= match.total_overs * 6:
                logger.info("⏱ OVERS COMPLETE!")
                await end_innings(context, group_id, match)
                return
            
            if bat_team.get_current_over_balls() == 0:
                await check_over_complete(context, group_id, match)
            else:
                await execute_ball(context, group_id, match)
            return
        else:
            # 🎯 REGULAR WICKET (Single commentary line with player names)
            striker_tag = get_user_tag(striker)
            _wkt_style = gc_settings.get(group_id, {}).get("commentary_style", registered_groups.get(group_id, {}).get("commentary_style", "english"))

            # 🧤 Decide HOW they got out (Bowled/Caught/LBW only) & credit catch if Caught
            dismissal_type, fielder = decide_dismissal_and_fielder(striker, bowler, bowl_team)
            dismissal_line = build_dismissal_line(dismissal_type, bowler.first_name, striker.dismissal_fielder_name, _wkt_style, striker.first_name)

            wkt_lines = [
                f"🏏 <b>{html.escape(striker.first_name)}</b> is out.",
                f"Final score: <b>{striker.runs} ({striker.balls_faced + 1})</b>",
                f"💬 <i>{dismissal_line}</i>",
            ]
            wicket_msg = (
                "❌ <b>WICKET!</b>\n"
                "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                + "\n".join(wkt_lines) + "\n"
                "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                f"📊 Score: <b>{bat_team.score}/{bat_team.wickets + 1}</b>"
            )
            
            gif_url = get_random_gif(MatchEvent.WICKET_CAUGHT if dismissal_type == "Caught" else MatchEvent.WICKET)
            _wkt_react_markup = _build_event_reaction_markup("wicket", bowler.user_id, group_id)
            try:
                await context.bot.send_animation(group_id, animation=gif_url, caption=wicket_msg, parse_mode=ParseMode.HTML, reply_markup=_wkt_react_markup)
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 10599)")
                await context.bot.send_message(group_id, wicket_msg, parse_mode=ParseMode.HTML, reply_markup=_wkt_react_markup)
            
            await asyncio.sleep(0.2)  # ⚡ SPEED FIX: was 1s
            
            # ✅ INCREMENT BALLS FOR WICKET BALL
            striker.balls_faced += 1
            bowler.balls_bowled += 1
            bat_team.balls += 1  # ✅ Sync batting team ball count
            bat_team.update_overs()
            
            # ✅ OFFER DRS
            match.last_wicket_ball = {
                "batsman": striker,
                "bowler": bowler,
                "bowler_number": bowler_num,
                "batsman_number": batsman_num
            }
            
            if bat_team.drs_remaining > 0 and (getattr(match, "is_real_cricket", False) or get_gc_setting(group_id, "drs_enabled", False)):
                await offer_drs_to_captain(context, group_id, match)
            else:
                calculate_momentum_change(match, 0, True, False)
                await confirm_wicket_and_continue(context, group_id, match)
            return
    
    # ============================================
    # 🏃 RUNS SCORED
    # ============================================
    else:
        runs = batsman_num

        # 🏏 REAL CRICKET: powerplay boundary cap → convert to No Ball
        if match.is_real_cricket and real_cricket_register_boundary(match, runs):
            extra = 1
            bat_team.score += extra
            bowler.runs_conceded += extra
            match.current_over_runs = getattr(match, 'current_over_runs', 0) + extra
            match.is_free_hit = True  # No Ball => next legal delivery is a free hit
            msg = themed("🚧 NO BALL — POWERPLAY CAP!", [
                f"⚠️ Boundary limit for Powerplay {match.real_pp_current[match.innings]} already reached.",
                f"🏃 <b>+{extra} run</b> (No Ball) — next ball is a <b>Free Hit</b>!",
                f"📊 Score: <b>{bat_team.score}/{bat_team.wickets}</b>",
            ], "🚧")
            try:
                await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
            except Exception:
                logger.exception("real cricket no-ball message failed")
            match.current_ball_data = {}
            await execute_ball(context, group_id, match)  # replay the ball, over/ball-count unchanged
            return

        bat_team.score += runs
        striker.runs += runs
        striker.balls_faced += 1
        bowler.balls_bowled += 1
        bowler.runs_conceded += runs
        bowler.consecutive_wickets = 0  # 🔄 Reset consecutive wickets when runs scored
        match.current_over_runs = getattr(match, 'current_over_runs', 0) + runs  # 📊 Track in-progress over runs
        
        # ✅ CRITICAL: INCREMENT BALLS HERE (BEFORE OVERS UPDATE)
        bat_team.balls += 1  # ✅ Sync batting team ball count
        bat_team.update_overs()
        
        # 🔮 MAGIC BALL MODE → Check for power-up ball
        magic_ball_result = None
        if getattr(match, "magic_ball_mode", False):
            match_context = {
                "match": match,
                "bat_team": bat_team,
                "bowl_team": bowl_team,
                "striker": striker,
                "bowler": bowler,
                "batsman_num": batsman_num,
                "bowler_num": bowler_num
            }
            magic_ball_result = await process_magic_ball(batsman_num, bowler_num, match_context)
            if magic_ball_result and magic_ball_result.get("magic_type"):
                # Apply magic ball effect
                delta = magic_ball_result["runs"] - runs
                if delta != 0:
                    bat_team.score += delta
                    striker.runs += delta
                    bowler.runs_conceded += delta
                # Update player_stats for magic ball tracking
                init_player_stats(striker.user_id)
                if striker.user_id in player_stats:
                    mb = player_stats[striker.user_id].setdefault("magicball", {})
                    mb["magic_balls_triggered"] = mb.get("magic_balls_triggered", 0) + 1
                    mt = magic_ball_result["magic_type"]
                    from collections import Counter
                    mb_counts = mb.get("_mb_counts", {})
                    mb_counts[mt] = mb_counts.get(mt, 0) + 1
                    mb["_mb_counts"] = mb_counts
                    # Set best (most frequent) magic ball
                    best = max(mb_counts, key=mb_counts.get)
                    mb["best_magic_ball"] = MAGIC_BALL_NAMES.get(best, best)
                runs = magic_ball_result["runs"]
        
        # Check milestones
        await check_and_celebrate_milestones(context, group_id, match, striker, 'batting')
        
        # Update boundaries
        if runs == 4:
            striker.boundaries += 1
        elif runs == 6:
            striker.sixes += 1
        
        # 🏆 FANTASY: credit run + six-bonus points to any squad owner who picked this batsman
        award_fantasy_runs(match, striker, runs)
        
        # 🎯 TRACK STRIKE ZONE (NEW)
        zone = determine_strike_zone(runs)
        team_key = 'team_x' if match.current_batting_team == match.team_x else 'team_y'
        match.strike_zones[team_key][zone] += runs
        
        # Update partnership
        match.current_partnership_runs += runs
        match.current_partnership_balls += 1
        if match.current_partnership_runs > match.longest_partnership_this_match:
            match.longest_partnership_this_match = match.current_partnership_runs

        # 🤝 Check 50/100 partnership milestone — sends the DP banner and
        # pauses the game 5s afterward, same as half-century/century/hatrick.
        if await check_and_celebrate_partnership(context, group_id, match):
            await asyncio.sleep(5)

        # ⚡ UPDATE MOMENTUM (NEW)
        is_boundary = runs in [4, 6]
        calculate_momentum_change(match, runs, False, is_boundary)

        # ✅ Get commentary based on GROUP setting (AI-powered)
        events = {
            0: "dot", 
            1: "single", 
            2: "double", 
            3: "triple", 
            4: "boundary", 
            5: "five", 
            6: "six"
        }
        comm_key = events.get(runs, "dot")
        commentary = get_commentary(comm_key, group_id=group_id, striker=striker.first_name, bowler=bowler.first_name)
        
        # Get GIF
        event_type = getattr(MatchEvent, f"RUNS_{runs}") if runs > 0 else MatchEvent.DOT_BALL
        gif_url = get_random_gif(event_type)
        
        # Build the compact live-ball card.
        run_label = {
            0: "🏏 0 RUNS",
            1: "🏏 1 RUN",
            2: "🏏 2 RUNS",
            3: "🏏 3 RUNS",
            4: "🏏 4 RUNS!",
            5: "🏏 5 RUNS!",
            6: "🏏 6 RUNS!",
        }.get(runs, f"🏏 {runs} RUNS")

        if match.is_free_hit:
            match.is_free_hit = False

        result_lines = [f"💬 <i>{commentary}</i>"]
        if magic_ball_result and magic_ball_result.get("magic_type"):
            magic_msg = _themed_magic_message(magic_ball_result.get("message", ""))
            if magic_msg:
                result_lines.append(html.escape(re.sub(r"<[^>]+>", "", magic_msg)))

        msg = (
            f"<b>{run_label}</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            + "\n".join(result_lines) + "\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"📊 Score: <b>{bat_team.score}/{bat_team.wickets}</b>"
        )

        # 🎉 Reaction buttons on 4s/6s
        _bnd_react = None
        if runs == 4:
            _bnd_react = _build_event_reaction_markup("four", striker.user_id, group_id)
        elif runs == 6:
            _bnd_react = _build_event_reaction_markup("six", striker.user_id, group_id)

        # 🔁 ORDER FIX: runs-scored GIF must finish sending BEFORE the next
        # ball's "bowling" GIF goes out — strict sequence (runs GIF → then
        # bowling GIF), not both firing in parallel. Awaited directly
        # instead of being fired as a background task.
        async def _send_runs_gif():
            try:
                if gif_url:
                    await context.bot.send_animation(group_id, animation=gif_url, caption=msg, parse_mode=ParseMode.HTML, reply_markup=_bnd_react)
                else:
                    await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML, reply_markup=_bnd_react)
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 10778)")
                try:
                    await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
                except Exception:
                    pass
        await _send_runs_gif()
        
        # ✅ LOG BALL - runs scored
        match.ball_by_ball_log.append({
            "over": format_overs(bat_team.balls),  # ✅ FIX: bat_team overs
            "batsman": striker.first_name,
            "bowler": bowler.first_name,
            "batting_team": bat_team.name,
            "runs": runs,
            "wicket": False,
            "is_wicket": False,
            "wide": False,
            "noball": False,
        })

        # Swap batsmen on odd runs
        if runs % 2 == 1:
            bat_team.swap_batsmen()
    
    # ============================================
    # ✅ CRITICAL: CHECK IF TARGET CHASED
    # ============================================
    if match.innings == 2 and bat_team.score >= match.target:
        logger.info("🏆🎉 TARGET CHASED! MATCH WON!")
        await asyncio.sleep(0.3)  # ⚡ SPEED FIX: was 1.5s
        await end_innings(context, group_id, match)
        return
    
    # ============================================
    # ✅ CRITICAL: CHECK IF OVERS COMPLETE (FIRST PRIORITY)
    # ============================================
    if bat_team.balls >= match.total_overs * 6:
        logger.info("⏱ OVERS COMPLETE! INNINGS ENDING!")
        await asyncio.sleep(0.2)  # ⚡ SPEED FIX: was 1s
        await end_innings(context, group_id, match)
        return
    
    # ============================================
    # 🔄 RESET & CONTINUE
    # ============================================
    match.current_ball_data = {}
    
    # Check if over completed
    current_over_balls = bat_team.get_current_over_balls()
    
    if current_over_balls == 0 and bat_team.balls > 0:
        await check_over_complete(context, group_id, match)
        return
    
    # Continue with next ball
    await execute_ball(context, group_id, match)

async def commentary_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Handle commentary style button clicks (Admin Only)
    Callback data format: gcommentary_style_groupid
    """
    query = update.callback_query
    await query.answer()
    
    user = query.from_user
    data = query.data
    
    # Parse data: gcommentary_style_groupid
    if not data.startswith("gcommentary_"):
        return
    
    parts = data.split("_")
    if len(parts) < 3:
        await query.answer(plain_alert("❌ Invalid callback data!"), show_alert=True)
        return
    
    style = parts[1]
    try:
        group_id = int(parts[2])
    except (ValueError, IndexError):
        group_id = query.message.chat.id
    
    valid_styles = ["english", "hinglish", "tamil", "bengali"]
    if style not in valid_styles:
        await query.answer(plain_alert("❌ Invalid style!"), show_alert=True)
        return
    
    # Check if user is admin in this group
    try:
        member = await context.bot.get_chat_member(group_id, user.id)
        if member.status not in ["creator", "administrator"]:
            await query.answer(plain_alert("⚠️ Only admins can change commentary!"), show_alert=True)
            return
    except Exception as e:
        logger.error(f"Admin check failed: {e}")
        await query.answer("Error verifying admin status", show_alert=True)
        return
    
    # Save to group settings
    if group_id not in registered_groups:
        registered_groups[group_id] = {
            "group_id": group_id,
            "group_name": query.message.chat.title if hasattr(query.message.chat, 'title') else "Group",
            "total_matches": 0,
            "commentary_style": style
        }
    else:
        registered_groups[group_id]["commentary_style"] = style
    
    # Also update active match if one exists
    if group_id in active_matches:
        active_matches[group_id].commentary_style = style
    
    save_data()
    
    style_names = {
        "english": "English",
        "hinglish": "Hinglish",
        "tamil": "Tamil",
        "bengali": "Bengali"
    }
    style_display = style_names.get(style, style)
    
    try:
        await query.edit_message_caption(
            caption=f"✅ <b>Commentary Updated!</b>\n\n"
                    f"🎙️ <b>New Style:</b> {style_display}\n"
                    f"👥 <b>Group:</b> All matches\n"
                    f"👮 <b>Changed by:</b> {html.escape(user.first_name)} (Admin)\n\n"
                    f"<i>All future matches will use this style.</i>",
            parse_mode=ParseMode.HTML
        )
    except Exception:
        try:
            await query.edit_message_text(
                text=f"✅ <b>Commentary Updated!</b>\n\n"
                     f"🎙️ <b>New Style:</b> {style_display}\n"
                     f"👮 <b>Changed by:</b> {html.escape(user.first_name)} (Admin)",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass


async def offer_drs_to_captain(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    ✅ DRS with INLINE BUTTONS - 10 second auto-reject
    """
    match.drs_in_progress = True
    batsman = match.last_wicket_ball["batsman"]
    bat_captain = match.get_captain(match.current_batting_team)
    
    if not bat_captain:
        logger.error("🚫 No batting captain found!")
        calculate_momentum_change(match, 0, True, False)
        await confirm_wicket_and_continue(context, group_id, match)
        return
    
    captain_tag = get_user_tag(bat_captain)
    batsman_tag = get_user_tag(batsman)
    
    # ⌨️ INLINE KEYBOARD (Updated Emojis + Bot API 9.4 colors)
    keyboard = [
        [styled_button("DRS Review", callback_data="drs_take")],
        [styled_button("Don't Want", callback_data="drs_reject")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    # ✨ Decorative Message
    drs_lines = [
        f"Captain {captain_tag}, do you want to challenge this dismissal?",
        "You have <b>10 seconds</b> to decide.",
    ]
    msg = themed("DRS REVIEW", drs_lines, "📺")
    
    await context.bot.send_message(group_id, msg, reply_markup=reply_markup, parse_mode=ParseMode.HTML)
    
    match.drs_in_progress = True
    match.drs_offer_time = time.time()
    
    # ⏱️ 10 Second Timer
    asyncio.create_task(drs_timeout_handler(context, group_id, match))

async def offer_drs(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Offer DRS to batting captain after wicket"""
    batsman = match.last_wicket_ball["batsman"]
    bowler = match.last_wicket_ball["bowler"]
    
    # Check if DRS available
    if match.current_batting_team.drs_remaining <= 0:
        # No DRS available, wicket confirmed
        await confirm_wicket(context, group_id, match, drs_used=False, drs_successful=False)
        return
    
    batting_captain = match.get_captain(match.current_batting_team)
    
    gif_url = get_random_gif(MatchEvent.WICKET)
    commentary = get_random_commentary("wicket", group_id=group_id)
    
    wicket_text = themed("WICKET!", [
        f"Over: <b>{format_overs(match.current_bowling_team.balls)}</b>",
        f"Bowler: <b>{match.last_wicket_ball['bowler_number']}</b> | Batsman: <b>{match.last_wicket_ball['batsman_number']}</b>",
        f"{html.escape(batsman.first_name)} ➜ {batsman.runs}({batsman.balls_faced})",
        f"🧢 Captain <b>{html.escape(batting_captain.first_name)}</b>: <b>{match.current_batting_team.drs_remaining} DRS</b> review available.",
        "📹 Challenge the decision? Use /drs",
        "⏳ <i>30 seconds to decide...</i>",
    ], emoji="🔴")
    
    try:
        if gif_url:
            await context.bot.send_animation(
                chat_id=group_id,
                animation=gif_url,
                caption=wicket_text
            )
        else:
            await context.bot.send_message(
                chat_id=group_id,
                text=wicket_text
            )
    except Exception as e:
        logger.error(f"Error sending wicket message: {e}")
        await context.bot.send_message(
            chat_id=group_id,
            text=wicket_text
        )
    
    match.drs_in_progress = True
    
    # Set timeout for DRS decision
    asyncio.create_task(drs_decision_timeout(context, group_id, match))

async def drs_timeout_handler(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """⏳ Auto-reject DRS after 10 seconds"""
    try:
        await asyncio.sleep(10)
        
        if not match.drs_in_progress:
            return
        
        match.drs_in_progress = False
        
        await context.bot.send_message(
            group_id,
            "⌛ <b>DRS TIMEOUT</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            "No review was taken.\n"
            "Umpire's decision stands.\n"
            "Wicket confirmed.",
            parse_mode=ParseMode.HTML
        )
        
        await asyncio.sleep(1)
        
        # ✅ CRITICAL FIX: Confirm wicket properly
        calculate_momentum_change(match, 0, True, False)
        await confirm_wicket_and_continue(context, group_id, match)
        
    except asyncio.CancelledError:
        pass

# ✅ DRS Callback Handler
async def drs_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🖱️ Handle DRS button clicks"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches:
        return
    
    match = active_matches[chat.id]
    
    if not match.drs_in_progress:
        await query.answer("⌛ DRS window closed!", show_alert=True)
        return
    
    # Check if captain
    batting_captain = match.get_captain(match.current_batting_team)
    if user.id != batting_captain.user_id:
        await query.answer(plain_alert("🧢 Only Captain can decide DRS!"), show_alert=True)
        return
    
    match.drs_in_progress = False
    
    if query.data == "drs_take":
        # 📺 Use DRS
        match.current_batting_team.drs_remaining -= 1
        await query.message.edit_text(
            "📺 <b>DRS REVIEW CALLED</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            "Sending to the Third Umpire...\n\n"
            "⏳ <i>Awaiting ball-tracking data...</i>",
            parse_mode=ParseMode.HTML
        )
        await process_drs_review(context, chat.id, match)
        
    elif query.data == "drs_reject":
        # ❌ Don't use DRS
        await query.message.edit_text(
            "✋ <b>DRS DECLINED</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"{html.escape(batting_captain.first_name)} accepts the umpire's call.\n"
            "Decision stands.",
            parse_mode=ParseMode.HTML
        )
        await asyncio.sleep(1)
        
        # ✅ CRITICAL FIX: Continue game after rejection
        calculate_momentum_change(match, 0, True, False)
        await confirm_wicket_and_continue(context, chat.id, match)

async def drs_decision_timeout(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Handle DRS decision timeout"""
    await asyncio.sleep(30)
    
    if not match.drs_in_progress:
        return
    
    # No DRS taken, confirm wicket
    match.drs_in_progress = False
    await confirm_wicket(context, group_id, match, drs_used=False, drs_successful=False)

# DRS command
async def drs_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ✅ UPDATED: DRS command with 10 second check
    """
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.type == "private":
        await update.message.reply_text("This command only works in groups.")
        return
    
    if chat.id not in active_matches:
        await update.message.reply_text("No active match found.")
        return
    
    match = active_matches[chat.id]
    
    if not match.drs_in_progress:
        await update.message.reply_text("No DRS review available at this moment.")
        return
    
    # Check if 10 seconds have passed
    current_time = time.time()
    if current_time - match.drs_offer_time > 10:
        await update.message.reply_text("⚠️ DRS time expired! 10 seconds over.")
        match.drs_in_progress = False
        calculate_momentum_change(match, 0, True, False)
        await confirm_wicket_and_continue(context, chat.id, match)
        return
    
    # Check if user is batting captain
    batting_captain = match.get_captain(match.current_batting_team)
    if not batting_captain:
        await update.message.reply_text("⚠️ No batting captain found!")
        return
    
    if user.id != batting_captain.user_id:
        await update.message.reply_text(
            f"⚠️ Only {match.current_batting_team.name} Captain can request DRS."
        )
        return
    
    # Process DRS
    match.drs_in_progress = False
    match.current_batting_team.drs_remaining -= 1
    
    await process_drs_review(context, chat.id, match)


async def process_drs_review(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    ✅ FIXED: DRS successful doesn't reduce wickets below original count
    """
    batsman = match.last_wicket_ball["batsman"]
    
    drs_text = "📺 <b>DRS IN REVIEW</b>\n\n"
    drs_text += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    drs_text += "Ball-tracking analysis underway.\n"
    drs_text += "Consulting the Third Umpire.\n\n"
    drs_text += "⏳ <i>Please hold...</i>"
    
    gif_url = get_random_gif(MatchEvent.DRS_REVIEW)
    
    try:
        if gif_url:
            msg = await context.bot.send_animation(group_id, animation=gif_url, caption=drs_text, parse_mode=ParseMode.HTML)
        else:
            msg = await context.bot.send_message(group_id, drs_text, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 11166)")
        msg = await context.bot.send_message(group_id, drs_text, parse_mode=ParseMode.HTML)
    
    await asyncio.sleep(1.5)
    
    is_overturned = random.random() < 0.40
    
    if is_overturned:
        # ✅ NOT OUT - Don't touch wickets (they were never incremented)
        batsman.is_out = False
        match.current_batting_team.out_players_indices.discard(match.current_batting_team.current_batsman_idx)
        
        gif = get_random_gif(MatchEvent.DRS_NOT_OUT)
        
        result_text = "✅ <b>DRS RESULT: NOT OUT</b>\n\n"
        result_text += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        result_text += f"{html.escape(batsman.first_name)} survives. Decision overturned!\n"
        result_text += f"DRS left: {match.current_batting_team.drs_remaining}"
        
        try:
            if gif:
                await context.bot.send_animation(group_id, animation=gif, caption=result_text, parse_mode=ParseMode.HTML)
            else:
                await context.bot.send_message(group_id, result_text, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 11190)")
            await context.bot.send_message(group_id, result_text, parse_mode=ParseMode.HTML)
        
        await asyncio.sleep(1)
        
        if match.current_bowling_team.get_current_over_balls() == 0:
            await check_over_complete(context, group_id, match)
        else:
            await execute_ball(context, group_id, match)
    else:
        # OUT confirmed
        out_gif_url = get_random_gif(MatchEvent.DRS_OUT)
        result_text = "🔴 <b>DRS RESULT: OUT</b>\n\n"
        result_text += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        result_text += f"{html.escape(batsman.first_name)} is out. Decision upheld.\n"
        result_text += f"Score: {batsman.runs} ({batsman.balls_faced})\n"
        result_text += f"DRS left: {match.current_batting_team.drs_remaining}"
        
        try:
            if out_gif_url:
                await context.bot.send_animation(group_id, animation=out_gif_url, caption=result_text, parse_mode=ParseMode.HTML)
            else:
                await context.bot.send_message(group_id, result_text, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 11212)")
            await context.bot.send_message(group_id, result_text, parse_mode=ParseMode.HTML)
        
        await asyncio.sleep(1)
        calculate_momentum_change(match, 0, True, False)
        await confirm_wicket_and_continue(context, group_id, match)

async def confirm_wicket_and_continue(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    ✅ FIXED: Wicket handler WITH proper wicket increment
    """
    
    logger.info(f"🔴🏏 === WICKET HANDLER START === Group: {group_id}")
    
    if match.phase == GamePhase.MATCH_ENDED:
        logger.warning("🛑 Match already ended, aborting wicket handling")
        return

    bat_team = match.current_batting_team
    bowl_team = match.current_bowling_team
    
    # Get the OUT player
    if bat_team.current_batsman_idx is None:
        logger.error("🚫👤 CRITICAL: No batsman index set!")
        await context.bot.send_message(group_id, "⚠️ Error: No batsman found!", parse_mode=ParseMode.HTML)
        return
    
    out_player = bat_team.players[bat_team.current_batsman_idx]
    bowler = bowl_team.players[bowl_team.current_bowler_idx]
    
    logger.info(f"☠️ OUT Player: {out_player.first_name} (Index: {bat_team.current_batsman_idx})")
    
    await asyncio.sleep(0.5)
    
    # ✅ CRITICAL FIX: INCREMENT WICKETS HERE
    out_player.is_out = True
    bat_team.wickets += 1  # ✅ INCREMENT TEAM WICKET COUNT
    bowler.wickets += 1    # ✅ INCREMENT BOWLER WICKET COUNT
    # 🏆 FANTASY: credit +30 to any squad owner who picked this bowler
    award_fantasy_wicket(match, bowler)
    # Save & reset partnership on wicket
    if match.current_partnership_runs > 0:
        _batsman_name = match.current_batting_team.players[match.current_batting_team.current_batsman_idx].first_name if match.current_batting_team.current_batsman_idx is not None else '?'
        _ns_name = match.current_batting_team.players[match.current_batting_team.current_non_striker_idx].first_name if match.current_batting_team.current_non_striker_idx is not None else '?'
        match.partnership_history.append({'p1': _batsman_name, 'p2': _ns_name, 'runs': match.current_partnership_runs, 'balls': match.current_partnership_balls})
    match.current_partnership_runs = 0
    match.current_partnership_balls = 0
    match.partnership_milestones_celebrated = set()  # 🤝 fresh partnership, fresh milestones
    # Increment over wickets counter
    match.current_over_wickets += 1
    bowler.consecutive_wickets += 1  # 🎯 Increment consecutive wickets for hat-trick
    
    # ✅ LOG WICKET BALL
    match.ball_by_ball_log.append({
        "over": format_overs(bat_team.balls),
        "batsman": out_player.first_name,
        "bowler": bowler.first_name,
        "batting_team": bat_team.name,
        "runs": 0,
        "wicket": True,
        "is_wicket": True,
        "wide": False,
        "noball": False,
    })

    logger.info(f"✅ Wickets updated: Team={bat_team.wickets}, Bowler={bowler.wickets}, Consecutive={bowler.consecutive_wickets}")

    # 🦆 ZERO/DUCK CHECK — fires whenever the batsman departs on 0
    if out_player.runs == 0:
        out_player.ducks += 1
        is_golden = out_player.balls_faced <= 1  # out on the very first ball faced
        duck_gif = get_random_gif(MatchEvent.DUCK)
        duck_label = f"🟡 {ce('duck', '🦆')} GOLDEN DUCK!" if is_golden else f"🦆 {ce('duck', '🦆')} DUCK!"
        duck_msg = (
            f"{duck_label}\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"😬 <b>{out_player.first_name}</b> departs without scoring!\n"
            f"🎯 Ducks this match: <b>{out_player.ducks}</b>"
        )
        try:
            if duck_gif:
                await context.bot.send_animation(group_id, animation=duck_gif, caption=duck_msg, parse_mode=ParseMode.HTML)
            else:
                await context.bot.send_message(group_id, duck_msg, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.error(f"Error sending duck gif: {e}")
            await context.bot.send_message(group_id, duck_msg, parse_mode=ParseMode.HTML)
        await asyncio.sleep(0.5)

    # 🎉 CHECK BOWLING MILESTONE
    await check_and_celebrate_milestones(context, group_id, match, bowler, 'bowling')
    
    # 🔕 MATCH CENTRE mini scorecard after a wicket removed per request.

    await asyncio.sleep(0.5)
    
    # ⚰️ Mark player as OUT
    bat_team.out_players_indices.add(bat_team.current_batsman_idx)
    logger.info(f"✅ Marked {out_player.first_name} as OUT (Total Out: {len(bat_team.out_players_indices)})")
    
    # 🧹 Clear striker position
    bat_team.current_batsman_idx = None
    logger.info("🧹 Striker position cleared, non-striker remains same")
    
    # 🧮 Check innings end conditions
    remaining_players = len(bat_team.players) - len(bat_team.out_players_indices)
    logger.info(f"👥 Remaining Players: {remaining_players}")
    
    # ✅ CRITICAL: Check if this wicket fell on the LAST ball of the over
    current_over_balls_after_wicket = bat_team.get_current_over_balls()
    is_last_ball_of_over = (current_over_balls_after_wicket == 0 and bat_team.balls > 0)
    
    if bat_team.is_all_out():
        logger.info("❌🛑 ALL OUT - Ending Innings")
        await asyncio.sleep(1)
        await end_innings(context, group_id, match)
        return
    
    if bat_team.balls >= match.total_overs * 6:
        logger.info("⏱ Overs complete - Ending Innings")
        await end_innings(context, group_id, match)
        return
    
    if match.innings == 2 and bat_team.score >= match.target:
        logger.info("🎉🏆 Target chased - Match Won")
        await end_innings(context, group_id, match)
        return
    
    # 🔄 PRIORITY #1: Request new batsman FIRST (ALWAYS)
    match.waiting_for_batsman = True
    match.waiting_for_bowler = False
    match.current_ball_data = {}
    logger.info("⏸️✋ Game PAUSED - waiting_for_batsman=True")
    
    # 📌 STORE OVER STATUS - Will be checked AFTER batsman is selected
    match.pending_over_complete = is_last_ball_of_over
    logger.info(f"📊 Over status stored: pending_over_complete={match.pending_over_complete}")
    
    batting_captain = match.get_captain(bat_team)
    if not batting_captain:
        logger.error("🚫👮 CRITICAL: No batting captain found!")
        await context.bot.send_message(group_id, "⚠️ Error: No captain found!", parse_mode=ParseMode.HTML)
        return
    
    captain_tag = get_user_tag(batting_captain)
    available_batsmen = [
        p for i, p in enumerate(bat_team.players) 
        if i not in bat_team.out_players_indices 
        and i != bat_team.current_non_striker_idx
    ]
    available_count = len(available_batsmen)
    
    if available_count == 0:
        logger.error("🔭 No available batsmen!")
        await end_innings(context, group_id, match)
        return
    
    msg = (
        f"🏏 {captain_tag}  Send in your batter!\n"
        f"⚙️ 𝗨𝘀𝗲: <code>/batting [number]</code>\n"
        f"ℹ️ 𝗡𝗼𝘁𝗲: Host can also send this if the captain's away."
    )
    
    await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
    logger.info("📨 New batsman request sent to group")
    
    # ⏱️ Start selection timer
    match.batsman_selection_time = time.time()
    match.batsman_selection_task = asyncio.create_task(
        batsman_selection_timeout(context, group_id, match)
    )
    logger.info("⏱️🚀 Batsman selection timer started")
    logger.info(f"🔴🏏 === WICKET HANDLER END ===\n")

async def handle_noball_and_continue(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    ✅ FIX 7: After No Ball — send bowling message again so bowler re-bowls
    """
    bat_team = match.current_batting_team
    bowl_team = match.current_bowling_team
    
    match.is_free_hit = True
    bat_team.score += 1
    bat_team.extras += 1
    
    bowler = bowl_team.players[bowl_team.current_bowler_idx] if bowl_team.current_bowler_idx is not None else None
    bowler_tag = get_user_tag(bowler) if bowler else "Bowler"
    
    nb_gif = get_random_gif(MatchEvent.NO_BALL)
    nb_msg = themed(
        "NO BALL",
        [
            f"⚾ {bowler_tag} oversteps.",
            "➕ +1 extra · ⚡ Free Hit next ball.",
            f"📊 Score: <b>{bat_team.score}/{bat_team.wickets}</b>",
            "🔁 Ball does not count. Bowl again.",
        ],
        "🚫"
    )
    
    try:
        if nb_gif:
            await context.bot.send_animation(group_id, animation=nb_gif, caption=nb_msg, parse_mode=ParseMode.HTML)
        else:
            await context.bot.send_message(group_id, nb_msg, parse_mode=ParseMode.HTML)
    except Exception:
        await context.bot.send_message(group_id, nb_msg, parse_mode=ParseMode.HTML)
    
    # Log no ball (does NOT count as legal delivery)
    striker = bat_team.players[bat_team.current_batsman_idx] if bat_team.current_batsman_idx is not None else None
    match.ball_by_ball_log.append({
        "over": format_overs(bat_team.balls),
        "batsman": striker.first_name if striker else "?",
        "bowler": bowler.first_name if bowler else "?",
        "batting_team": bat_team.name,
        "runs": 1,
        "wicket": False,
        "is_wicket": False,
        "wide": False,
        "noball": True,
    })
    
    # Reset ball data and re-send bowling prompt (ball NOT counted)
    match.current_ball_data = {}
    await execute_ball(context, group_id, match)


async def check_drinks_break(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    🥤 DRINKS BREAK - Triggers at the 10th over (60 balls).
    🔧 BUG FIX: this function was being called (see check_over_complete) but was never
    actually defined — it existed only as dead, unreachable code accidentally left
    inside the no-ball handler above, so every match that reached over 10 crashed
    with a NameError right here. Restored as a real function below.

    Also pause-aware like /timeout: sets match.is_paused for the break's duration and
    cancels the live selection/ball timers so they can't fire underneath the break,
    then restores them exactly as /timeout does.
    """
    bat_team = match.current_batting_team

    # Don't double-pause on top of an active /timeout
    if getattr(match, 'is_paused', False):
        return

    match.is_paused = True
    match.pause_until = time.time() + 30

    # Cancel active timers so they don't expire during the break
    if match.ball_timeout_task:
        match.ball_timeout_task.cancel()
        match.ball_timeout_task = None
    if match.bowler_selection_task:
        match.bowler_selection_task.cancel()
        match.bowler_selection_task = None
    if match.batsman_selection_task:
        match.batsman_selection_task.cancel()
        match.batsman_selection_task = None

    drinks_gif = "https://media.giphy.com/media/l0HlBO7eyXzSZkJri/giphy.gif"

    overs_played = max(bat_team.balls / 6, 0.1)
    crr = round(bat_team.score / overs_played, 2)

    msg = "🥤 <b>DRINKS BREAK</b>\n\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += f"Score: <b>{bat_team.score}/{bat_team.wickets}</b> ({format_overs(bat_team.balls)})\n"
    msg += f"Current Run Rate: <b>{crr}</b>\n"

    if match.innings == 2:
        runs_needed = match.target - bat_team.score
        balls_left = (match.total_overs * 6) - bat_team.balls
        rrr = round((runs_needed / balls_left) * 6, 2) if balls_left > 0 else 0
        msg += f"Required Run Rate: <b>{rrr}</b>\n"
        msg += f"Need <b>{runs_needed}</b> runs in <b>{balls_left}</b> balls\n"

    msg += "\n⏳ <i>Resuming in 30 seconds...</i>"

    try:
        await context.bot.send_animation(group_id, animation=drinks_gif, caption=msg, parse_mode=ParseMode.HTML)
    except Exception:
        await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)

    await asyncio.sleep(30)

    match.is_paused = False
    match.pause_until = 0.0

    await context.bot.send_message(
        group_id,
        text="▶️ <b>BREAK OVER</b>\nPlay resumes now. 🏏",
        parse_mode=ParseMode.HTML
    )
    await asyncio.sleep(1)

    # Re-request whatever was pending before the break, exactly like /timeout does
    if match.waiting_for_bowler:
        await request_bowler_selection(context, group_id, match)
    elif match.waiting_for_batsman:
        captain = match.get_captain(match.current_batting_team)
        cap_tag = get_user_tag(captain) if captain else match.current_batting_team.name
        await context.bot.send_message(
            group_id,
            f"🏏 {cap_tag}\nSelect your batsman.\nUse <code>/batting [number]</code>.",
            parse_mode=ParseMode.HTML
        )
        match.batsman_selection_time = time.time()
        match.batsman_selection_task = asyncio.create_task(
            batsman_selection_timeout(context, group_id, match)
        )


def real_cricket_powerplay_for_over(match: Match, over_num_1indexed: int) -> int:
    """Returns which powerplay (1/2/3) the given (1-indexed) over falls in,
    for the match's total_overs format. Only meaningful when
    match.is_real_cricket is True. Works for ANY overs count (1-20), not
    just the 10/20-over presets — those two keep their exact stated splits,
    everything else is scaled proportionally to the same ratios."""
    overs = getattr(match, "total_overs", 0)
    if overs <= 0:
        return 0
    if overs == 10:
        if over_num_1indexed <= 3:
            return 1
        elif over_num_1indexed <= 6:
            return 2
        else:
            return 3
    elif overs == 20:
        if over_num_1indexed <= 4:
            return 1
        elif over_num_1indexed <= 15:
            return 2
        else:
            return 3
    else:
        # 🔧 General formula for any other overs count (e.g. 5, 6, 8, 15...):
        # PP1 = first ~30% of overs, PP2 = up to ~75%, PP3 = remainder.
        pp1_end = max(1, round(overs * 0.3))
        pp2_end = max(pp1_end + 1, round(overs * 0.75))
        pp2_end = min(pp2_end, overs - 1) if overs > 1 else pp2_end
        if over_num_1indexed <= pp1_end:
            return 1
        elif over_num_1indexed <= pp2_end:
            return 2
        else:
            return 3


def real_cricket_boundary_cap(pp_number: int) -> int:
    """Max boundary (4/6) balls allowed within a powerplay."""
    return {1: 3, 2: 4, 3: 5}.get(pp_number, 999)


def real_cricket_max_overs_per_bowler(match: Match) -> int:
    """Max overs a single bowler can bowl — standard 'max 20% of the
    innings' cricket rule, so it scales for ANY overs count, not just
    10/20 (10—2, 20—4, 5—1, 8—2, 15—3, etc)."""
    overs = getattr(match, "total_overs", 0) or 1
    return max(1, math.ceil(overs / 5))


def real_cricket_drinks_break_overs(match: Match) -> List[int]:
    """Over numbers (completed-overs count) after which a drinks break
    fires. 10/20-over presets keep their exact stated overs; anything
    else scales proportionally (~35% for a single break under 14 overs,
    ~35%/~80% two breaks for longer matches)."""
    overs = getattr(match, "total_overs", 0)
    if overs == 10:
        return [7]
    elif overs == 20:
        return [7, 16]
    elif overs < 6:
        return []  # too short for a drinks break
    elif overs < 14:
        return [max(1, round(overs * 0.7))]
    else:
        return [max(1, round(overs * 0.35)), max(2, round(overs * 0.8))]


async def _real_cricket_send_gif(context: ContextTypes.DEFAULT_TYPE, group_id: int, filename: str, caption: str):
    """Sends a LOCAL gif file that lives in the same folder as this script
    (e.g. powerplay.gif, drinks_break.gif — just drop the renamed file next
    to cric.py). Falls back to text-only if the file isn't found so the
    bot never crashes because a gif is missing."""
    gif_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), filename)
    try:
        if os.path.isfile(gif_path):
            with open(gif_path, "rb") as f:
                await context.bot.send_animation(chat_id=group_id, animation=f, caption=caption, parse_mode=ParseMode.HTML)
        else:
            logger.warning(f"Real Cricket gif not found at {gif_path}, sending text only")
            await context.bot.send_message(chat_id=group_id, text=caption, parse_mode=ParseMode.HTML)
    except Exception:
        logger.exception(f"_real_cricket_send_gif failed for {filename}")
        try:
            await context.bot.send_message(chat_id=group_id, text=caption, parse_mode=ParseMode.HTML)
        except Exception:
            pass


async def real_cricket_maybe_send_powerplay_gif(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, pp_number: int):
    """Sends the powerplay-start banner image + rules reminder, pauses 5s, then
    lets play resume. Call this the moment a new powerplay begins."""
    cap = real_cricket_boundary_cap(pp_number)
    match.real_break_in_progress = True
    caption = themed(
        f"POWERPLAY {pp_number} ACTIVE",
        [
            f"🎯 Maximum <b>{cap}</b> boundary balls allowed in this powerplay.",
            "🚫 Cross the cap and the delivery becomes a No Ball.",
        ],
        "⚡"
    )
    pp_key = f"powerplay{pp_number}"
    try:
        pp_photo = MEDIA_ASSETS.get(pp_key)
        if pp_photo and os.path.isfile(pp_photo):
            await context.bot.send_photo(chat_id=group_id, photo=pp_photo, caption=caption, parse_mode=ParseMode.HTML)
        else:
            await _real_cricket_send_gif(context, group_id, "powerplay.gif", caption)
    except Exception:
        logger.exception(f"Failed to send powerplay banner for pp{pp_number}, falling back to gif/text")
        await _real_cricket_send_gif(context, group_id, "powerplay.gif", caption)
    await asyncio.sleep(5)
    match.real_break_in_progress = False


async def real_cricket_maybe_drinks_break(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, completed_over: int):
    """Call right after an over finishes. Fires a 30s auto drinks break
    if completed_over matches this format's break point(s)."""
    if not match.is_real_cricket:
        return
    if completed_over not in real_cricket_drinks_break_overs(match):
        return
    if completed_over in match.real_drinks_done[match.innings]:
        return
    match.real_drinks_done[match.innings].add(completed_over)

    match.real_break_in_progress = True
    await _real_cricket_send_gif(context, group_id, "drinks_break.gif", "🥤 <b>DRINKS BREAK!</b>\nResuming in 30 seconds...")

    await asyncio.sleep(30)

    await _real_cricket_send_gif(context, group_id, "drinks_break.gif", "▶️ <b>Match resumed!</b>")

    match.real_break_in_progress = False


async def real_cricket_maybe_powerplay_transition(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, next_over_1indexed: int):
    """Call right before the NEXT over starts (i.e. after over-complete
    housekeeping). Detects a powerplay boundary and fires the GIF+5s pause
    if this over begins a new powerplay."""
    if not match.is_real_cricket:
        return
    new_pp = real_cricket_powerplay_for_over(match, next_over_1indexed)
    if new_pp == 0:
        return
    if match.real_pp_current[match.innings] != new_pp:
        match.real_pp_current[match.innings] = new_pp
        match.real_pp_boundary_count[match.innings] = 0  # reset cap counter for the new powerplay
        await real_cricket_maybe_send_powerplay_gif(context, group_id, match, new_pp)


def real_cricket_register_boundary(match: Match, runs: int) -> bool:
    """Call when a legal delivery scores runs, BEFORE committing them to the
    scorecard. Returns True if this ball should be converted to a No Ball
    (i.e. the powerplay's boundary cap was already reached), else False.
    If it returns False and runs was a 4/6, the boundary count is incremented."""
    if not match.is_real_cricket:
        return False
    pp = match.real_pp_current.get(match.innings, 0)
    if pp == 0 or runs not in (4, 6):
        return False
    cap = real_cricket_boundary_cap(pp)
    current = match.real_pp_boundary_count.get(match.innings, 0)
    if current >= cap:
        return True  # cap breached -> caller should treat this ball as a no-ball instead
    match.real_pp_boundary_count[match.innings] = current + 1
    return False


def real_cricket_bowler_eligible(match: Match, bowler_id: int) -> Optional[str]:
    """Returns None if the bowler CAN bowl the next over, or a short reason
    string if they can't (max-overs reached / consecutive-over rule)."""
    if not match.is_real_cricket:
        return None
    overs_bowled = match.real_bowler_overs[match.innings].get(bowler_id, 0)
    if overs_bowled >= real_cricket_max_overs_per_bowler(match):
        return f"⚠️ Max {real_cricket_max_overs_per_bowler(match)} overs/bowler reached in Real Cricket Mode."
    if match.real_last_over_bowler.get(match.innings) == bowler_id:
        return "⚠️ Same bowler can't bowl consecutive overs in Real Cricket Mode."
    return None


def real_cricket_record_over_bowled(match: Match, bowler_id: int):
    """Call once per completed over, from check_over_complete, to update
    per-bowler over counts and the last-bowler tracker."""
    if not match.is_real_cricket:
        return
    d = match.real_bowler_overs[match.innings]
    d[bowler_id] = d.get(bowler_id, 0) + 1
    match.real_last_over_bowler[match.innings] = bowler_id


async def check_over_complete(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    🏁 End of Over: Show Mini Scorecard, Swap Batsmen, Request New Bowler
    """
    
    logger.info(f"🟢 check_over_complete called for group {group_id}")
    
    if match.phase == GamePhase.MATCH_ENDED:
        logger.warning("🛑 Match already ended, skipping over complete")
        return

    bat_team = match.current_batting_team
    bowl_team = match.current_bowling_team
    
    # Get current bowler info BEFORE clearing
    if bowl_team.current_bowler_idx is not None:
        bowler = bowl_team.players[bowl_team.current_bowler_idx]
        bowl_team.bowler_history.append(bowl_team.current_bowler_idx)
        logger.info(f"✅ Bowler {bowler.first_name} added to history")
        real_cricket_record_over_bowled(match, bowler.user_id)
    else:
        bowler = type("obj", (object,), {"first_name": "Unknown", "wickets": 0, "runs_conceded": 0})
        logger.error("🚫 No bowler found at over complete!")
    
    # Save over wickets
    if bat_team == match.team_x:
        match.team_x_over_wickets.append(match.current_over_wickets)
    else:
        match.team_y_over_wickets.append(match.current_over_wickets)
    match.current_over_wickets = 0

    # ✅ Save over runs for this completed over
    if bat_team == match.team_x:
        already_accounted = sum(match.team_x_over_runs)
        runs_in_this_over = bat_team.score - already_accounted
        match.team_x_over_runs.append(max(0, runs_in_this_over))
    else:
        already_accounted = sum(match.team_y_over_runs)
        runs_in_this_over = bat_team.score - already_accounted
        match.team_y_over_runs.append(max(0, runs_in_this_over))
    match.current_over_runs = 0  # Reset for the next over

    # ⚡ Lightweight checkpoint — one small row per over, NOT a full stats
    # commit. Full stats only get committed at match end (see end_innings /
    # match completion, where save_data() + clear_match_checkpoint() run).
    checkpoint_match(group_id, match)

    # ── Compute best ball of the over from ball_by_ball_log ──
    over_num_done = bat_team.balls // 6
    over_balls_log = [
        b for b in match.ball_by_ball_log
        if b.get("batting_team") == bat_team.name
    ]
    this_over_balls = over_balls_log[-(over_num_done * 6 - (over_num_done - 1) * 6):]  # last 6 legal
    # Simpler: just last min(6, len) entries for this batting team
    this_over_balls = [
        b for b in match.ball_by_ball_log
        if b.get("batting_team") == bat_team.name
    ][-6:]
    best_ball_runs = max((b.get("runs", 0) for b in this_over_balls), default=0)
    wicket_in_over = any(b.get("is_wicket") or b.get("wicket") for b in this_over_balls)
    dot_balls_over = sum(1 for b in this_over_balls if b.get("runs", 0) == 0 and not (b.get("is_wicket") or b.get("wicket")))

    # ✅ STEP 1: SWAP BATSMEN (Strike Rotation) — do BEFORE building summary
    logger.info(f"🔄 Swapping batsmen - Before: Striker={bat_team.current_batsman_idx}, Non-Striker={bat_team.current_non_striker_idx}")
    bat_team.swap_batsmen()
    logger.info(f"🔄 After swap: Striker={bat_team.current_batsman_idx}, Non-Striker={bat_team.current_non_striker_idx}")
    
    # Re-fetch players after swap
    new_striker = bat_team.players[bat_team.current_batsman_idx] if bat_team.current_batsman_idx is not None else None
    new_non_striker = bat_team.players[bat_team.current_non_striker_idx] if bat_team.current_non_striker_idx is not None else None

    # ── Build END OF OVER summary ──
    _over_runs_list = match.team_x_over_runs if bat_team == match.team_x else match.team_y_over_runs
    _over_wkts_list = match.team_x_over_wickets if bat_team == match.team_x else match.team_y_over_wickets
    _last_runs = _over_runs_list[-1] if _over_runs_list else 0
    _last_wkts = _over_wkts_list[-1] if _over_wkts_list else 0
    # Run history bar (last 5 overs)
    _hist = ""
    for _r in (_over_runs_list[-5:] if _over_runs_list else []):
        if _r >= 12: _hist += "🟣"
        elif _r >= 9: _hist += "🔴"
        elif _r >= 6: _hist += "🟠"
        elif _r >= 3: _hist += "🟡"
        else: _hist += "⚫"
    _rr = round(bat_team.score / (bat_team.balls / 6), 2) if bat_team.balls > 0 else 0.0
    _part_txt = f"  ┊  🤝 Partnership: {match.current_partnership_runs}({match.current_partnership_balls})" if match.current_partnership_runs > 0 else ""

    # Bowler economy this over
    _over_econ = round(_last_runs / 1, 2)  # runs per over (this was 1 over)
    # Best ball label
    if best_ball_runs == 6:
        _best_ball_txt = "🚀 Best ball: SIX!"
    elif best_ball_runs == 4:
        _best_ball_txt = "🔥 Best ball: FOUR!"
    elif wicket_in_over:
        _best_ball_txt = "💀 Wicket taken this over!"
    elif dot_balls_over >= 3:
        _best_ball_txt = f"🔒 {dot_balls_over} dot balls → tight bowling!"
    else:
        _best_ball_txt = f"📊 {dot_balls_over} dot ball{'s' if dot_balls_over != 1 else ''}"

    # ── Build END OF OVER summary using new styled format ──
    mini_card = generate_mini_scorecard(match)
    combined_caption = mini_card
    mini_card_markup = verse_zone_markup()

    # ✅ Send combined over-summary + mini scorecard with chart
    chart_sent2 = False
    try:
        chart_bio2 = await asyncio.to_thread(generate_over_bar_chart, match)
        if chart_bio2:
            await context.bot.send_photo(
                group_id,
                photo=chart_bio2,
                caption=combined_caption,
                parse_mode=ParseMode.HTML,
                reply_markup=mini_card_markup
            )
            chart_sent2 = True
    except Exception as chart_err2:
        logger.warning(f"Bar chart (over complete) failed: {chart_err2}")
    if not chart_sent2:
        try:
            await context.bot.send_photo(
                group_id,
                photo=MINI_SCORECARD_PHOTO,
                caption=combined_caption,
                parse_mode=ParseMode.HTML,
                reply_markup=mini_card_markup
            )
        except Exception as photo_error:
            logger.error(f"Error sending mini scorecard photo: {photo_error}")
            await context.bot.send_message(group_id, combined_caption, parse_mode=ParseMode.HTML, reply_markup=mini_card_markup)
    logger.info("📨 Combined over-summary + mini scorecard sent")

    # (Mid-match "LIVE MATCH CENTER" image removed per request — no longer sent)
    
    # ✅ DRINKS BREAK CHECK (10th over = 60 balls) — classic mid-innings break,
    # meant for the 20-over format where over 10 is genuinely the halfway point.
    # 🩹 BUGFIX: this fired unconditionally at ball 60 with no format check —
    # for any match with total_overs <= 10 (a 10-over match especially, a
    # valid/common preset), ball 60 IS the innings' last ball, so this
    # popped up a "🥤 DRINKS BREAK! Resuming in 30 seconds..." message and
    # blocked play for 30s right as the innings had already finished, with
    # end_innings() firing immediately after the break ended. It also fired
    # in Real Cricket Mode on top of that mode's own properly-scaled
    # drinks-break logic below (real_cricket_maybe_drinks_break), which
    # already covers Real Cricket matches of every format correctly.
    if bat_team.balls == 60 and not match.is_real_cricket and match.total_overs > 10:
        await check_drinks_break(context, group_id, match)
    
    # ✅ STEP 3: CHECK INNINGS/MATCH END
    if bat_team.balls >= match.total_overs * 6:
        logger.info("⌛ Innings complete - Overs finished")
        await end_innings(context, group_id, match)
        return
    
    if match.innings == 2 and bat_team.score >= match.target:
        logger.info("🏆 Match won - Target chased")
        await end_innings(context, group_id, match)
        return
    
    # ✅ STEP 4: CLEAR OLD BOWLER & PAUSE GAME
    logger.info(f"🛑 Clearing bowler - Old index: {bowl_team.current_bowler_idx}")
    bowl_team.current_bowler_idx = None  
    match.waiting_for_bowler = True
    match.waiting_for_batsman = False
    match.current_ball_data = {}
    logger.info("⏸️ Match state set to waiting_for_bowler=True")
    
    await asyncio.sleep(1)

    # 🏏 REAL CRICKET: drinks break (if this over triggers one), then
    # powerplay transition GIF+pause for the over about to start.
    if match.is_real_cricket:
        completed_over_num = bat_team.balls // 6
        await real_cricket_maybe_drinks_break(context, group_id, match, completed_over_num)
        await real_cricket_maybe_powerplay_transition(context, group_id, match, completed_over_num + 1)

    # ✅ STEP 5: REQUEST NEW BOWLER (CRITICAL)
    logger.info("📢 Calling request_bowler_selection...")
    await request_bowler_selection(context, group_id, match)
    logger.info("✅ request_bowler_selection completed")


