async def confirm_wicket(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, drs_used: bool, drs_successful: bool):
    """Confirm wicket and update match state"""
    batsman = match.last_wicket_ball["batsman"]
    bowler = match.last_wicket_ball["bowler"]
    
    # Mark batsman as out
    batsman.is_out = True
    batsman.dismissal_type = "Bowled"
    match.current_batting_team.wickets += 1
    bowler.wickets += 1
    # 🏆 FANTASY: credit +30 to any squad owner who picked this bowler
    award_fantasy_wicket(match, bowler)
    
    # ✅ FIX: Update player_stats dismissal field
    if batsman.user_id in match.current_batting_team.player_stats:
        match.current_batting_team.player_stats[batsman.user_id]["dismissal"] = batsman.dismissal_type
    
    # ✅ CHECK BOWLING MILESTONE
    # 🩹 BUGFIX: this call was duplicated back-to-back (copy-paste), so any
    # wicket that goes through confirm_wicket() — reachable when the
    # batting team has no DRS reviews left, or when a DRS decision times
    # out — fired the bowler's milestone celebration (e.g. a 3-wicket-haul
    # announcement) TWICE for the same wicket.
    await check_and_celebrate_milestones(context, group_id, match, bowler, 'bowling')
    
    if drs_used and not drs_successful:
        gif_url = get_random_gif(MatchEvent.DRS_OUT)
        
        result_text = "📺〔 <b>DRS RESULT</b> 〕📺\n\n"
        result_text += "⚖️ <b>Decision:</b> OUT — Stands!\n\n"
        result_text += "Third umpire upholds the original call.\n\n"
        result_text += f"📊 <b>{batsman.first_name}:</b> {batsman.runs} ({batsman.balls_faced})\n\n"
        result_text += f"📡 DRS Remaining: {match.current_batting_team.drs_remaining}\n\n"
        result_text += f"📊 <b>Score:</b> {match.current_batting_team.score}/{match.current_batting_team.wickets}"
        
        try:
            if gif_url:
                await context.bot.send_animation(
                    chat_id=group_id,
                    animation=gif_url,
                    caption=result_text
                )
            else:
                await context.bot.send_message(
                    chat_id=group_id,
                    text=result_text
                )
        except Exception as e:
            logger.error(f"Error sending DRS out message: {e}")
            await context.bot.send_message(
                chat_id=group_id,
                text=result_text
            )
    else:
        wicket_confirm_text = f"Wicket Confirmed\n\n"
        wicket_confirm_text += f"{batsman.first_name}: {batsman.runs} ({batsman.balls_faced})\n"
        wicket_confirm_text += f"Bowler: {bowler.first_name}\n\n"
        wicket_confirm_text += f"Score: {match.current_batting_team.score}/{match.current_batting_team.wickets}"
        
        await context.bot.send_message(
            chat_id=group_id,
            text=wicket_confirm_text
        )
    
    # Update stats
    batsman.balls_faced += 1
    bowler.balls_bowled += 1
    match.current_batting_team.update_overs()
    
    # Check for duck
    if batsman.runs == 0:
        batsman.ducks += 1
        is_golden = batsman.balls_faced <= 1  # 🩹 BUGFIX: was `<= 0`, but balls_faced was
        # already incremented by 1 a few lines above — so this could never be true, and
        # "GOLDEN DUCK" (out first ball, no runs) never showed, only the regular "DUCK"
        # label, even on a genuine golden duck. confirm_wicket_and_continue's equivalent
        # check (`<= 1`, after its own increment) has the correct threshold — match it.
        duck_gif = get_random_gif(MatchEvent.DUCK)
        duck_label = f"🟡 {ce('duck', '🦆')} GOLDEN DUCK!" if is_golden else f"🦆 {ce('duck', '🦆')} DUCK!"
        duck_msg = (
            f"{duck_label}\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"😬 <b>{batsman.first_name}</b> departs without scoring!\n"
            f"🎯 Ducks this match: <b>{batsman.ducks}</b>"
        )
        try:
            if duck_gif:
                await context.bot.send_animation(group_id, animation=duck_gif, caption=duck_msg, parse_mode=ParseMode.HTML)
            else:
                await context.bot.send_message(group_id, duck_msg, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.error(f"Error sending duck gif: {e}")
            await context.bot.send_message(group_id, duck_msg, parse_mode=ParseMode.HTML)
    
    # Log ball
    match.ball_by_ball_log.append({
        "over": format_overs(match.current_batting_team.balls - 1),
        "batsman": batsman.first_name,
        "bowler": bowler.first_name,
        "result": "Wicket",
        "runs": 0,
        "is_wicket": True
    })
    
    await asyncio.sleep(1)
    
    # Check if innings over
    if match.is_innings_complete():
        await end_innings(context, group_id, match)
    else:
        # Request new batsman
        match.waiting_for_batsman = True
        await request_batsman_selection(context, group_id, match)

