async def addauctionplayer_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ➕ Bulk add player(s) to auction pool (Mid-Auction) — same bulk flow as /aucplayer
    Usage: Reply to user with /addauctionplayer
    or /addauctionplayer @username
    or /addauctionplayer @u1 @u2 @u3  (bulk)
    or /addauctionplayer rohit virat kohli  (Ideal players)
    """
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\nStart an auction first with /auction",
            parse_mode=ParseMode.HTML
        )
        return

    auction = active_auctions[chat.id]

    # Only host/auctioneer can add
    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🚫 <b>AUCTIONEER ONLY!</b>\n\nOnly the auctioneer can add players!",
            parse_mode=ParseMode.HTML
        )
        return

    if not context.args and not update.message.reply_to_message:
        await update.message.reply_text(
            "📌 <b>BULK ADD PLAYER USAGE</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            "<b>Reply Method:</b>\n"
            "<code>/addauctionplayer</code>\n\n"
            "<b>Single Player:</b>\n"
            "<code>/addauctionplayer @username</code>\n\n"
            "<b>Multiple Players:</b>\n"
            "<code>/addauctionplayer @u1 @u2 @u3</code>\n\n"
            "<b>Using ID:</b>\n"
            "<code>/addauctionplayer 123456789</code>\n\n"
            "<b>Mixed Method:</b>\n"
            "<code>/addauctionplayer @u1 123456 @u2</code>\n\n"
            "<b>Ideal (imaginary) Players:</b>\n"
            "<code>/addauctionplayer rohit virat kohli</code>\n"
            "(choose 🧑 Ideal Player when asked — no user ID/username needed)\n\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
        return

    # Reuse the exact same pending/mode-select flow as /aucplayer (keyed by
    # chat.id, so aucplayer_mode_callback / process_ideal_aucplayer /
    # process_real_aucplayer / bulk_base_price_callback all just work as-is)
    aucplayer_pending[chat.id] = {
        "args": list(context.args) if context.args else [],
        "message": update.message,
        "auctioneer_id": user.id,
    }

    keyboard = [
        [
            styled_button("Ideal Player", callback_data="aucmode_ideal"),
            styled_button("Real Player", callback_data="aucmode_real"),
        ]
    ]
    await update.message.reply_text(
        "🏏 <b>WHAT KIND OF PLAYER(S)?</b>\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        "🧑 <b>Ideal Player</b> — made-up/imaginary players, just names, no Telegram user needed.\n"
        "👤 <b>Real Player</b> — actual Telegram users, needs userid/username/@mention/reply.\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        reply_markup=InlineKeyboardMarkup(keyboard),
        parse_mode=ParseMode.HTML
    )


async def midauc_base_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle mid-auction player base price"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    
    if chat.id not in active_auctions:
        return
    
    auction = active_auctions[chat.id]
    
    # Parse callback data
    try:
        parts = query.data.split("_")
        price = int(parts[2])
        player_id = int(parts[3])
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 11909)")
        return
    
    # Get player info
    player_info = user_data.get(player_id)
    if not player_info:
        await query.message.edit_text("❌ Player not found!")
        return

    # 🩹 BUGFIX: this quick-add path had NO duplicate check at all — not
    # even against the pool, let alone sold/unsold. Same root issue as the
    # bulk /addauctionplayer paths: could silently put an already-sold
    # player back up for bidding, letting them be bought a second time.
    if auction.player_already_in_auction(player_id):
        await query.message.edit_text(
            f"⚠️ <b>ALREADY IN THIS AUCTION!</b>\n\n"
            f"👤 {html.escape(player_info['first_name'])} is already in the pool, sold, or unsold list — not added again."
        )
        return

    # Add to pool
    auction.player_pool.append({
        "player_id": player_id,
        "player_name": player_info["first_name"],
        "base_price": price
    })
    
    player_tag = f'<a href=\"tg://user?id={player_id}\">{player_info['first_name']}</a>' + _title_suffix(player_id)
    
    await query.message.edit_text(
        f"✅ <b>Player Added to Pool!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        f"👤 {player_tag}\n"
        f"💰 Base Price: {price}\n\n"
        f"📊 Total in Pool: {len(auction.player_pool)}",
        parse_mode=ParseMode.HTML
    )


# 2️⃣ REMOVE PLAYER FROM AUCTION
async def removeauctionplayer_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ➖ Remove player from auction pool
    Usage: Reply to user with /removeauctionplayer
    """
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_auctions:
        await update.message.reply_text("❌ No active auction!")
        return
    
    auction = active_auctions[chat.id]
    
    # Only host/auctioneer
    if user.id != auction.auctioneer_id:
        await update.message.reply_text("🚫 Only Host/Auctioneer can remove players!")
        return
    
    # Cannot remove during live bidding
    if auction.phase == AuctionPhase.AUCTION_LIVE and auction.current_player_id:
        await update.message.reply_text("⚠️ Cannot remove player during active bidding!")
        return
    
    # Get target
    target_id = None
    
    if update.message.reply_to_message:
        target_id = update.message.reply_to_message.from_user.id
    elif context.args:
        arg = context.args[0]
        if arg.startswith("@"):
            username = arg[1:].lower()
            for uid, data in user_data.items():
                if data.get("username", "").lower() == username:
                    target_id = uid
                    break
        elif arg.isdigit():
            target_id = int(arg)
    
    if not target_id:
        await update.message.reply_text(
            "ℹ️ <b>Usage:</b>\n"
            "Reply: <code>/removeauctionplayer</code>\n"
            "Username: <code>/removeauctionplayer @username</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Find and remove
    found = False
    for i, p in enumerate(auction.player_pool):
        if p["player_id"] == target_id:
            removed = auction.player_pool.pop(i)
            found = True
            
            await update.message.reply_text(
                f"➖ <b>Player Removed!</b>\n"
                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
                f"👤 {removed['player_name']}\n"
                f"💰 Base: {removed['base_price']}\n\n"
                f"📊 Remaining in Pool: {len(auction.player_pool)}",
                parse_mode=ParseMode.HTML
            )
            break
    
    if not found:
        await update.message.reply_text("⚠️ Player not found in auction pool!")


# 3️⃣ ADD/REMOVE PURSE
async def addpurse_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    💰 Add money to team purse
    Usage: /addpurse [team_name] [amount]
    """
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_auctions:
        await update.message.reply_text("❌ No active auction!")
        return
    
    auction = active_auctions[chat.id]
    
    # Only auctioneer
    if user.id != auction.auctioneer_id:
        await update.message.reply_text("🚫 Only the Auctioneer can modify purse!")
        return
    
    if len(context.args) < 2:
        await update.message.reply_text(
            "ℹ️ <b>Usage:</b>\n"
            "<code>/addpurse [TeamName] [Amount]</code>\n\n"
            "<b>Example:</b>\n"
            "<code>/addpurse Mumbai Indians 100</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    try:
        amount = int(context.args[-1])
        team_name = " ".join(context.args[:-1])
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12041)")
        await update.message.reply_text("❌ Invalid amount!")
        return
    
    if team_name not in auction.teams:
        await update.message.reply_text(f"❌ Team '{team_name}' not found!")
        return
    
    team = auction.teams[team_name]
    team.purse_remaining += amount
    
    await update.message.reply_text(
        f"💰 <b>Purse Updated!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        f"🏏 <b>Team:</b> {team_name}\n"
        f"➕ <b>Added:</b> {amount}\n"
        f"💵 <b>New Balance:</b> {team.purse_remaining}",
        parse_mode=ParseMode.HTML
    )


