# 4️⃣ PLAYER STATS IN AUCTION
async def generate_player_bid_card(context: ContextTypes.DEFAULT_TYPE, player_id: int, fallback_name: str) -> Optional[str]:
    """🖼️ Light-theme 16:8 'Player up for bid' card — DP + Username + Name.
    Returns a local PNG file path, or None if generation fails (caller falls
    back to the existing GIF/photo/text chain in that case)."""
    try:
        W, H = 1600, 800  # 16:8 aspect ratio

        display_name = fallback_name or "Unknown"
        username = None
        try:
            chat = await context.bot.get_chat(player_id)
            display_name = chat.full_name or display_name
            username = chat.username
        except Exception:
            pass

        avatar_bytes = await fetch_user_avatar_bytes(context, player_id)

        # ── Light theme canvas ──
        img = Image.new("RGB", (W, H), (247, 249, 252))
        draw = ImageDraw.Draw(img, "RGBA")
        draw.rectangle([0, 0, 20, H], fill=(37, 99, 235, 255))  # accent bar

        # ── DP (circular) ──
        dp_size = 620
        dp_x, dp_y = 100, (H - dp_size) // 2
        if avatar_bytes:
            avatar = _circle_avatar(avatar_bytes, dp_size, initials=(display_name or "CV")[:2])
            img.paste(avatar, (dp_x, dp_y), avatar)
        else:
            placeholder = Image.new("RGBA", (dp_size, dp_size), (0, 0, 0, 0))
            pdraw = ImageDraw.Draw(placeholder)
            pdraw.ellipse((0, 0, dp_size - 1, dp_size - 1), fill=(230, 234, 241, 255),
                          outline=(203, 210, 223, 255), width=6)
            f_nodp = _get_font(True, 46)
            text = "No DP"
            bbox = pdraw.textbbox((0, 0), text, font=f_nodp)
            tw, th = bbox[2] - bbox[0], bbox[3] - bbox[1]
            pdraw.text(((dp_size - tw) / 2, (dp_size - th) / 2 - th * 0.2), text,
                       font=f_nodp, fill=(130, 139, 158, 255))
            img.paste(placeholder, (dp_x, dp_y), placeholder)

        ring = Image.new("RGBA", (dp_size + 20, dp_size + 20), (0, 0, 0, 0))
        rdraw = ImageDraw.Draw(ring)
        rdraw.ellipse((3, 3, dp_size + 16, dp_size + 16), outline=(37, 99, 235, 255), width=8)
        img.paste(ring, (dp_x - 10, dp_y - 10), ring)

        # ── Text: Name + Username (vertically centered in the right half) ──
        text_x = dp_x + dp_size + 90
        f_label = _get_font(True, 30)
        f_name = _get_font(True, 96)
        f_user = _get_font(False, 44)

        label_text = "PLAYER UP FOR BID"
        name_bbox = draw.textbbox((0, 0), display_name, font=f_name)
        name_h = name_bbox[3] - name_bbox[1]
        user_text = f"@{username}" if username else "No Username"

        block_h = 40 + name_h + 45 + 50  # label + gap + name + gap + username
        block_top = (H - block_h) / 2

        draw.text((text_x, block_top), label_text, font=f_label, fill=(37, 99, 235, 255))
        draw.text((text_x, block_top + 40), display_name, font=f_name, fill=(20, 24, 33, 255))
        draw.text((text_x, block_top + 40 + name_h + 45), user_text, font=f_user, fill=(100, 109, 128, 255))

        out_path = f"/tmp/player_bid_card_{player_id}_{int(time.time())}.png"
        img.save(out_path, "PNG")
        return out_path
    except Exception:
        logger.exception("generate_player_bid_card: failed to build card")
        return None


async def bring_next_player(context: ContextTypes.DEFAULT_TYPE, chat_id: int, auction: Auction):
    """🎯 Bring next player with PREMIUM UI"""

    # ⏸ Safety net: never bring a new player into the ring while the
    # auctioneer has the auction paused — whatever was in progress just
    # stays exactly as it is until /resumeauction is used. This backstops
    # every caller of bring_next_player() in one place, regardless of how
    # they got here (bid_timer flow, sold/reject confirmation, etc).
    if getattr(auction, 'is_paused', False):
        return

    # Check if auction complete
    if len(auction.player_pool) == 0:
        # Ask auctioneer/host for confirmation before officially ending
        sold_count = len(auction.sold_players)
        unsold_count = len(auction.unsold_players)
        confirm_kb = InlineKeyboardMarkup([[
            styled_button("Yes, Conclude Auction", callback_data=f"confirm_endauction_{chat_id}"),
            styled_button("Keep Going", callback_data="cancel_endauction")
        ]])
        try:
            await context.bot.send_message(
                chat_id,
                f"🏁 <b>AUCTION COMPLETE!</b>\n"
                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                f"All players have been auctioned!\n"
                f"📊 <b>Final Status</b>\n"
                f"🔨 Sold: <b>{sold_count}</b>\n"
                f"❌ Unsold: <b>{unsold_count}</b>\n"
                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                f"<b>Preparing Final Scorecard...</b>\n"
                f"Please confirm to officially conclude the auction?",
                parse_mode=ParseMode.HTML,
                reply_markup=confirm_kb
            )
        except Exception as e:
            logger.error(f"bring_next_player end confirm error: {e}")
            await end_auction(context, chat_id, auction)
        return
    
    # Get player
    player = auction.player_pool.pop(0)
    auction.current_player_id = player["player_id"]
    auction.current_player_name = player["player_name"]
    auction.current_base_price = player["base_price"]
    auction.current_highest_bid = player["base_price"]
    auction.current_highest_bidder = None
    auction.last_bid_teams = []  # Reset bid history for new player
    auction.last_bidder_tag = None
    auction.last_team_name = None
    auction.live_bid_log = []
    auction.bids_frozen = False
    auction.pending_sold_confirmation = False
    
    # ✅ FIX: Set phase to AUCTION_LIVE
    auction.phase = AuctionPhase.AUCTION_LIVE

    base = player["base_price"]
    player_tag = f"<a href=\"tg://user?id={player['player_id']}\">{html.escape(str(player['player_name']))}</a>" + _title_suffix(player['player_id'])

    # 🩹 BUGFIX (root cause of "ERROR BRINGING NEXT PLAYER!"): everything
    # below this point used to run unguarded — a bad player_stats entry,
    # a locked/corrupt sqlite file, or any other one-off exception while
    # building the fancy stats card would raise, escape bring_next_player
    # entirely, and permanently stall the auction (no timer ever got
    # started, and — until now — /nextplayer didn't even exist to recover
    # it manually). We now build the rich message in its own try/except:
    # if ANY of it fails, we fall back to a minimal-but-correct player
    # card instead of raising, so a player (and a working bid timer) is
    # GUARANTEED to go out every single time this function is called.
    quick_kb = InlineKeyboardMarkup([
        [
            styled_button(f"+3 ({base+3})", callback_data=f"quickbid_{chat_id}_{base+3}"),
            styled_button(f"+5 ({base+5})", callback_data=f"quickbid_{chat_id}_{base+5}"),
        ],
        [
            styled_button(f"+10 ({base+10})", callback_data=f"quickbid_{chat_id}_{base+10}"),
        ]
    ])

    try:
        # 🎬 PLAYER INTRODUCTION
        # 🩹 BUGFIX: "auction_live" was never actually a key in GIFS (only
        # auction_start/auction_sold/auction_unsold/auction_countdown exist),
        # so this always returned None. Falling back to a real existing GIF
        # key fixes the common case.
        player_gif = GIFS.get("auction_live") or GIFS.get("auction_start")

        # Fetch player stats - try DB first, fallback to in-memory
        p_id = player['player_id']
        init_player_stats(p_id)
        s = player_stats.get(p_id, {}).get('team', {})

        # Also try to read from DB for accurate team stats
        try:
            _auc_conn = await asyncio.to_thread(db_connect, DB_PATH)
            _auc_c = _auc_conn.cursor()
            _auc_c.execute("""SELECT 
                team_matches_played, team_matches_won,
                team_total_runs, team_total_balls_faced, team_total_wickets,
                team_total_sixes, team_total_fours, team_highest_score,
                team_total_hundreds, team_total_fifties, team_best_bowling_wickets, team_best_bowling_runs
                FROM user_stats WHERE user_id = ?""", (p_id,))
            db_s = _auc_c.fetchone()
            _auc_conn.close()
            if db_s and db_s[0] and db_s[0] > 0:
                _m, _w, _r, _b, _wk, _sx, _4s, _hs, _huns, _50s, _bwk, _br = db_s
            else:
                _m = s.get("matches", 0)
                _w = s.get("wins", 0)
                _r = s.get("runs", 0)
                _b = s.get("balls", 0)
                _wk = s.get("wickets", 0)
                _sx = s.get("sixes", 0)
                _4s = s.get("fours", 0)
                _hs = s.get("highest", 0)
                _huns = s.get("centuries", 0)
                _50s = s.get("fifties", 0)
                _bwk = s.get("best_bowling", {}).get("wickets", 0) if isinstance(s.get("best_bowling"), dict) else 0
                _br = s.get("best_bowling", {}).get("runs", 0) if isinstance(s.get("best_bowling"), dict) else 0
        except Exception:
            _m = s.get("matches", 0)
            _w = s.get("wins", 0)
            _r = s.get("runs", 0)
            _b = s.get("balls", 0)
            _wk = s.get("wickets", 0)
            _sx = s.get("sixes", 0)
            _4s = s.get("fours", 0)
            _hs = s.get("highest", 0)
            _huns = s.get("centuries", 0)
            _50s = s.get("fifties", 0)
            _bwk = 0
            _br = 0

        _avg = round(_r / max(_m, 1), 1)
        _sr = round((_r / max(_b, 1)) * 100, 1) if _b > 0 else 0.0
        _eco = round((s.get("runs_conceded", 0) / max(s.get("balls_bowled", 1), 1)) * 6, 1) if s.get("balls_bowled", 0) > 0 else 0.0
        _win_rate = round((_w / max(_m, 1)) * 100, 1) if _m > 0 else 0.0
        _best_fig = f"{_bwk}/{_br}" if _bwk > 0 else "N/A"

        msg = (
            f"<b>PLAYER UP FOR BID!</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"👤 Player : {player_tag}\n"
            f"🪙 Base : {base} 🔷\n\n"
            f"📊 <b>CAREER STATS</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"🏟️ Matches : {_m} (Wins: {_w})\n\n"
            f"🏏 <b>Batting</b>\n"
            f"┈┈┈┈┈┈┈\n"
            f"Runs: {_r}\n"
            f"Avg: {_avg}\n"
            f"SR: {_sr}\n\n"
            f"⚾ <b>Bowling</b>\n"
            f"┈┈┈┈┈┈┈\n"
            f"Wickets: {_wk}\n"
            f"Eco: {_eco}\n"
            f"Best: {_best_fig}\n\n"
            f"⏱️ 20s Remaining (/bid amount)"
        )
    except Exception:
        # 🩹 Stats/DB card failed to build — don't let that kill the whole
        # auction. Fall back to a bare-bones (but always-correct) message.
        logger.exception("bring_next_player: rich stats card failed, using minimal fallback message")
        player_gif = None
        msg = (
            f"<b>PLAYER UP FOR BID!</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"👤 Player : {player_tag}\n"
            f"🪙 Base : {base} 🔷\n\n"
            f"⏱️ 20s Remaining (/bid amount)"
        )

    sent_player_intro = False

    # 🖼️ Try the light-theme DP + Name + Username card first.
    try:
        card_path = await generate_player_bid_card(context, player['player_id'], player['player_name'])
    except Exception:
        card_path = None
        logger.exception("bring_next_player: generate_player_bid_card raised")

    if card_path:
        try:
            with open(card_path, "rb") as _cf:
                await context.bot.send_photo(
                    chat_id,
                    photo=_cf,
                    caption=msg,
                    parse_mode=ParseMode.HTML,
                    reply_markup=quick_kb
                )
            sent_player_intro = True
        except Exception:
            logger.exception("bring_next_player: sending generated DP card failed, falling back")
        finally:
            try:
                os.remove(card_path)
            except Exception:
                pass

    if not sent_player_intro and player_gif:
        try:
            await context.bot.send_animation(
                chat_id,
                animation=player_gif,
                caption=msg,
                parse_mode=ParseMode.HTML,
                reply_markup=quick_kb
            )
            sent_player_intro = True
        except Exception:
            logger.exception("bring_next_player: send_animation failed, falling back to photo/text")

    if not sent_player_intro:
        try:
            photo_asset = MEDIA_ASSETS.get("auction_live")
        except Exception:
            photo_asset = None
        if photo_asset:
            try:
                await context.bot.send_photo(
                    chat_id,
                    photo=photo_asset,
                    caption=msg,
                    parse_mode=ParseMode.HTML,
                    reply_markup=quick_kb
                )
                sent_player_intro = True
            except Exception:
                logger.exception("bring_next_player: send_photo fallback also failed, falling back to text")

    if not sent_player_intro:
        # 🩹 Last-resort fallback: no working GIF or photo — still MUST show
        # the player + bidding buttons as plain text so the auction never
        # silently stalls with an unrecoverable error.
        try:
            await context.bot.send_message(
                chat_id,
                msg,
                parse_mode=ParseMode.HTML,
                reply_markup=quick_kb
            )
            sent_player_intro = True
        except Exception:
            # Even plain-text HTML failed (e.g. a bad tag from a weird player
            # name) — retry once with parse_mode off entirely so the auction
            # can never die silently here.
            logger.exception("bring_next_player: plain HTML send failed, retrying without parse_mode")
            await context.bot.send_message(
                chat_id,
                f"Player up for auction: {player['player_name']} — base price {base}. Use /bid [amount].",
                reply_markup=quick_kb
            )

    # Start timer — always, regardless of which message path above succeeded.
    auction.bid_end_time = time.time() + 20
    auction.bid_timer_task = asyncio.create_task(bid_timer(context, chat_id, auction))

# /soloplayers
async def soloplayers_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Fancy Solo Player List"""
    chat = update.effective_chat
    if chat.id not in active_matches: return
    match = active_matches[chat.id]

    if match.game_mode not in ["SOLO", "MAGICBALL"]:
        await update.message.reply_text("⚠️ This is not a Solo match!")
        return

    lines = [f"Players: <b>{len(match.solo_players)}/11</b>"]
    for i, p in enumerate(match.solo_players, 1):
        status = "Waiting"
        if p.is_out:
            status = "OUT"
        elif match.phase == GamePhase.SOLO_MATCH:
            if i - 1 == match.current_solo_bat_idx:
                status = "Batting"
            elif i - 1 == match.current_solo_bowl_idx:
                status = "Bowling"
            elif p.is_bowling_banned:
                status = "Banned (Bowl)"
        player_name = html.escape(p.first_name)
        lines.append(f"<b>{i}.</b> {player_name} — <i>{status}</i>")

    msg = themed("SOLO BATTLE ROSTER", lines, emoji="📜")
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

# /soloscore
async def soloscore_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """✅ ENHANCED Solo Leaderboard - Detailed & Clean"""
    chat = update.effective_chat
    
    if chat.id not in active_matches: 
        await update.message.reply_text("⚠️ No active match!")
        return
    
    match = active_matches[chat.id]
    
    if match.game_mode not in ["SOLO", "MAGICBALL"]:
        await update.message.reply_text("⚠️ This is not a Solo match!")
        return
    
    # Sort by Runs (Desc)
    sorted_players = sorted(match.solo_players, key=lambda x: x.runs, reverse=True)
    
    lines = []
    for i, p in enumerate(sorted_players, 1):
        rank = f"<b>{i}.</b>"
        
        # Status
        # 🩹 BUGFIX: this used to compare `i-1` (this player's position in the
        # runs-sorted list) against match.current_solo_bat_idx /
        # current_solo_bowl_idx, which are indices into the ORIGINAL
        # match.solo_players order (the randomized batting order), not the
        # sorted-by-runs order used here. /soloplayers gets this right
        # because it enumerates match.solo_players directly — /soloscore
        # sorts first, so the "(batting)"/"(bowling)" tag landed on
        # whichever player happened to occupy that rank position instead
        # of the actual current batter/bowler. Compare by player identity.
        status = ""
        if p.is_out: 
            status = " (out)"
        elif p is match.solo_players[match.current_solo_bat_idx] if match.current_solo_bat_idx < len(match.solo_players) else False:
            status = " (batting)"
        elif p is match.solo_players[match.current_solo_bowl_idx] if match.current_solo_bowl_idx < len(match.solo_players) else False:
            status = " (bowling)"
        
        # Stats
        sr = round((p.runs / max(p.balls_faced, 1)) * 100, 1)
        
        player_name = html.escape(p.first_name)
        lines.append(f"{rank} <b>{player_name}</b>{status}")
        lines.append(f"Runs: <b>{p.runs}</b> ({p.balls_faced} balls)")
        lines.append(f"⚡ SR: <b>{sr}</b>  •  🎯 Wickets: <b>{p.wickets}</b>")
        lines.append("")

    lines.append("<i>Top performers at a glance.</i>")
    msg = themed("SOLO BATTLE LEADERBOARD", lines, emoji="🏆")
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

async def start_solo_mechanics(context, chat_id, match):
    """Initializes Solo Match with randomized order"""
    match.phase = GamePhase.SOLO_MATCH
    
    # Randomize Order
    random.shuffle(match.solo_players)
    
    match.current_solo_bat_idx = 0
    match.current_solo_bowl_idx = 1
    match.solo_balls_this_spell = 0
    
    # Announce Order
    order_msg = "🎲 <b>BATTING ORDER</b>\n"
    order_msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    order_msg += f"Host: {html.escape(match.host_name or 'Host')}\n"
    order_msg += f"Code: <code>{match.resume_code}</code>\n\n"
    order_msg += "The batting order has been shuffled.\n"
    order_msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    for i, p in enumerate(match.solo_players, 1):
        ptag = f'<a href="tg://user?id={p.user_id}">{html.escape(p.first_name)}</a>' + _title_suffix(p.user_id)
        role = " — 🏏 Striker" if i == 1 else " — ⚾ Bowler" if i == 2 else ""
        order_msg += f"<code>{i}.</code> <b>{ptag}</b>{role}\n"
    order_msg += "\n🔥 Match starts in <b>5 seconds</b>."

    # Send with Toss/Squad Image
    await context.bot.send_photo(
        chat_id=chat_id,
        photo=MEDIA_ASSETS.get("toss"),
        caption=order_msg,
        parse_mode=ParseMode.HTML
    )
    
    await asyncio.sleep(5)
    
    # Start First Ball
    await trigger_solo_ball(context, chat_id, match)

async def trigger_solo_ball(context, chat_id, match):
    """Sets up the next ball with Timers"""
    # 🔧 GLITCH FIX: if /endmatch or /endall already ended this match, stop here —
    # this is called from timeout/rotation paths that run after long sleeps, so the
    # match could have been ended in the meantime.
    if is_match_stale(chat_id, match):
        logger.info("⛔ trigger_solo_ball aborted — match already ended.")
        return
    batter = match.solo_players[match.current_solo_bat_idx]
    bowler = match.solo_players[match.current_solo_bowl_idx]
    
    match.current_ball_data = {
        "bowler_id": bowler.user_id,
        "bowler_number": None,
        "batsman_number": None,
        "is_solo": True,
        "group_id": chat_id   # ✅ Store group_id for redirect button in DM
    }
    
    bat_tag = f'<a href=\"tg://user?id={batter.user_id}\">{html.escape(batter.first_name)}</a>' + _title_suffix(batter.user_id)
    bowl_tag = f'<a href=\"tg://user?id={bowler.user_id}\">{html.escape(bowler.first_name)}</a>' + _title_suffix(bowler.user_id)
    
    # Calculate Strike Rate
    sr = round((batter.runs / batter.balls_faced) * 100, 1) if batter.balls_faced > 0 else 0
    
    msg = themed(
        "BOWLING",
        [
            f"{bowl_tag} is running in.",
            f"Spell: <b>Ball {match.solo_balls_this_spell + 1}/3</b>",
        ],
        emoji="🔴"
    )
    
    # ✅ FIX: Use deep link ?start=bowl_{chat_id} — bare URL triggers /start welcome message
    bot_username = context.bot.username
    deliver_url = f"https://t.me/{bot_username}"
    keyboard = [[styled_button("Deliver Bowl", url=deliver_url)]]
    
    ball_gif = BALL_TIME_BOWLING_GIF
    try:
        await context.bot.send_animation(chat_id, ball_gif, caption=msg, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12442)")
        await context.bot.send_message(chat_id, msg, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)
    
    # 🆕 FEATURE: 0-6 inline number pad only — the group-redirect button
    # only shows once the delivery locks in (see bowl_number_dm_callback).
    try:
        _dm_markup = InlineKeyboardMarkup(_bowl_number_keyboard(chat_id))
    except Exception:
        _dm_markup = None

    # DM Bowler with group redirect button
    # 🩹 BUGFIX: the bowler timer used to only get created *after* the DM
    # send succeeded (both were in the same try block) — if the bowler had
    # blocked the bot or never started it, send_message raised, the
    # `except` branch just posted a warning, and match.ball_timeout_task
    # was NEVER set. With no timer running, handle_solo_timeout could
    # never fire to auto-skip/penalize that bowler, so the whole solo
    # match froze on that ball forever (only /endsolo could recover it).
    # Team mode's execute_ball already documents & follows the correct
    # pattern ("Always initialize ball data and start timer regardless of
    # DM success") — mirror it here: start the timer unconditionally,
    # handle the DM failure separately.
    match.ball_timeout_task = asyncio.create_task(
        solo_game_timer(context, chat_id, match, "bowler", bowler.first_name, seq=bump_solo_ball_seq(match))
    )
    try:
        sr_batter = round((batter.runs / max(batter.balls_faced, 1)) * 100, 1)
        dm_msg = themed(
            "YOUR TURN TO BOWL",
            [
                f"🏏 Batsman: <b>{html.escape(batter.first_name)}</b> — {batter.runs} ({batter.balls_faced}), SR {sr_batter}",
                "📩 Send a number from <code>0–6</code>.",
                "⏱ Your timer is running."
            ],
            emoji="⚔️"
        )
        await context.bot.send_message(bowler.user_id, dm_msg, parse_mode=ParseMode.HTML, reply_markup=_dm_markup)
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12473)")
        await context.bot.send_message(
            chat_id,
            themed(
                "BOWLER DM UNAVAILABLE",
                [
                    f"Cannot DM {bowl_tag} — they may not have started the bot.",
                    "⏳ Their timer is still running; a penalty applies if it expires."
                ],
                emoji="⚠️"
            ),
            parse_mode=ParseMode.HTML
        )

async def process_solo_turn_result(context, chat_id, match):
    """Calculates Solo result with FIXED Next Batsman flow"""
    # 🔧 GLITCH FIX: if /endmatch or /endall already ended this match, stop here.
    if is_match_stale(chat_id, match):
        logger.info("⛔ process_solo_turn_result aborted — match already ended.")
        return

    batter = match.solo_players[match.current_solo_bat_idx]
    bowler = match.solo_players[match.current_solo_bowl_idx]
    bat_num = match.current_ball_data["batsman_number"]
    bowl_num = match.current_ball_data["bowler_number"]
    
    bat_tag = f'<a href=\"tg://user?id={batter.user_id}\">{html.escape(batter.first_name)}</a>' + _title_suffix(batter.user_id)
    bowl_tag = f'<a href=\"tg://user?id={bowler.user_id}\">{html.escape(bowler.first_name)}</a>' + _title_suffix(bowler.user_id)

    # --- MAGIC BALL MODE INTERCEPTION ---
    is_wicket = (bat_num == bowl_num)
    runs = bat_num
    magic_msg = None

    if getattr(match, "game_mode", None) == "MAGICBALL":
        match_context = {
            "match": match,
            "batter": batter,
            "bowler": bowler,
            "batsman_num": bat_num,
            "bowler_num": bowl_num
        }
        magic_ball_result = await process_magic_ball(bat_num, bowl_num, match_context)
        if magic_ball_result and magic_ball_result.get("magic_type"):
            # 1. Handle Rewind (ball doesn't count, re-bowl)
            if magic_ball_result.get("special_flag") == "rewind":
                msg = _themed_magic_message(magic_ball_result.get("message", "⏮️ Rewind triggered!"))
                try:
                    await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
                except Exception:
                    pass
                match.current_ball_data = {}
                await trigger_solo_ball(context, chat_id, match)
                return

            # 2. Handle Ghost / Reveal Delay
            if magic_ball_result.get("reveal_delay", 0) > 0:
                msg = magic_ball_result.get("message", "")
                try:
                    await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
                except Exception:
                    pass
                await asyncio.sleep(magic_ball_result["reveal_delay"])
                
                rev_msg = themed("MAGIC REVEAL", [html.escape(str(magic_ball_result.get("reveal_message", "")))], "👻")
                if rev_msg:
                    try:
                        await context.bot.send_message(chat_id, rev_msg, parse_mode=ParseMode.HTML)
                    except Exception:
                        pass
            
            # Override outputs
            is_wicket = magic_ball_result.get("is_wicket", False)
            runs = magic_ball_result.get("runs", 0)
            magic_msg = _themed_magic_message(magic_ball_result.get("message"))

    # --- 1. WICKET LOGIC ---
    if is_wicket:
        batter.is_out = True
        match.solo_balls_this_spell = 0

        # 🎳 Bowling stats: this ball counts towards the bowler's figures
        bowler.balls_bowled += 1
        bowler.wickets += 1
        
        # Hat-trick tracking
        if not hasattr(match, 'solo_consecutive_wickets'):
            match.solo_consecutive_wickets = {}
        bowler_key = bowler.user_id
        match.solo_consecutive_wickets[bowler_key] = match.solo_consecutive_wickets.get(bowler_key, 0) + 1
        hat_trick = match.solo_consecutive_wickets[bowler_key] >= 3
        
        gif = get_random_gif(MatchEvent.WICKET)
        commentary = await get_ai_commentary_async("wicket", gc_settings.get(chat_id, {}).get("commentary_style", registered_groups.get(chat_id, {}).get("commentary_style", "english")))
        sr = round((batter.runs / max(batter.balls_faced, 1)) * 100, 1)
        
        wicket_lines = [f"🏏 <b>{html.escape(batter.first_name)}</b> is out."]
        if magic_msg:
            wicket_lines.append(f"🔮 {magic_msg}")
        wicket_lines.append(f"Final score: <b>{batter.runs} ({batter.balls_faced})</b>")
        wicket_lines.append(f"💬 <i>{commentary}</i>")
        msg = (
            "❌ <b>WICKET!</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            + "\n".join(wicket_lines) + "\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"📊 Score: <b>{sum(p.runs for p in match.solo_players)}/{sum(1 for p in match.solo_players if p.is_out)}</b>"
        )

        try:
            if gif: await context.bot.send_animation(chat_id, gif, caption=msg, parse_mode=ParseMode.HTML)
            else: await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12564)")
            await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
        
        # 🎩 Hat-trick celebration
        if hat_trick:
            ht_msg = themed(
                "HAT-TRICK!",
                [
                    f"🔥 <b>{html.escape(bowler.first_name)}</b> takes 3 consecutive wickets.",
                    "🏏 Three in a row. What a spell."
                ],
                emoji="🎩"
            )
            try:
                ht_gif = get_random_gif(MatchEvent.HAT_TRICK)
                if ht_gif:
                    await context.bot.send_animation(chat_id, ht_gif, caption=ht_msg, parse_mode=ParseMode.HTML)
                else:
                    await context.bot.send_message(chat_id, ht_msg, parse_mode=ParseMode.HTML)
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12580)")
                await context.bot.send_message(chat_id, ht_msg, parse_mode=ParseMode.HTML)
            match.solo_consecutive_wickets[bowler_key] = 0  # Reset after hat-trick
        match.current_solo_bat_idx += 1
        
        # Check if ALL OUT
        if match.current_solo_bat_idx >= len(match.solo_players):
            await end_solo_game_logic(context, chat_id, match)
            return

        # Assign New Bowler (Batsman ke next wala)
        match.current_solo_bowl_idx = (match.current_solo_bat_idx + 1) % len(match.solo_players)
        new_batter = match.solo_players[match.current_solo_bat_idx]
        new_bat_tag = f'<a href=\"tg://user?id={new_batter.user_id}\">{html.escape(new_batter.first_name)}</a>' + _title_suffix(new_batter.user_id)
        
        await asyncio.sleep(0.2)  # ⚡ SPEED FIX: was 1s
        await context.bot.send_message(
            chat_id,
            themed(
                "NEXT BATSMAN",
                [f"🏏 {new_bat_tag} walks to the crease.", "<i>Resuming shortly...</i>"],
                emoji="⚡"
            ),
            parse_mode=ParseMode.HTML
        )
        
        # 🔧 GLITCH FIX: re-check — /endmatch may have fired during the awaits above.
        if is_match_stale(chat_id, match):
            logger.info("⛔ process_solo_turn_result (wicket branch) aborted post-await — match already ended.")
            return
        await trigger_solo_ball(context, chat_id, match)
        return

    # --- 2. RUNS LOGIC ---
    else:
        batter.runs += runs
        batter.balls_faced += 1
        # 🏏 FIX: track boundaries so /mystats shows real 4s/6s instead of 0
        if runs == 4:
            batter.boundaries += 1
        elif runs == 6:
            batter.sixes += 1

        # 🎳 Bowling stats: this ball counts towards the bowler's figures
        bowler.balls_bowled += 1
        bowler.runs_conceded += runs
        
        # Reset consecutive wickets for this bowler (scored off)
        if not hasattr(match, 'solo_consecutive_wickets'):
            match.solo_consecutive_wickets = {}
        match.solo_consecutive_wickets[bowler.user_id] = 0
        
        # Map Run Events to GIFs
        events = {0: MatchEvent.DOT_BALL, 1: MatchEvent.RUNS_1, 2: MatchEvent.RUNS_2, 
                  3: MatchEvent.RUNS_3, 4: MatchEvent.RUNS_4, 5: MatchEvent.RUNS_5, 6: MatchEvent.RUNS_6}
        comm_keys = {0: "dot", 1: "single", 2: "double", 3: "triple", 4: "boundary", 5: "five", 6: "six"}
        
        gif = get_random_gif(events.get(runs, MatchEvent.DOT_BALL))
        commentary = await get_ai_commentary_async(comm_keys.get(runs, "dot"), gc_settings.get(chat_id, {}).get("commentary_style", registered_groups.get(chat_id, {}).get("commentary_style", "english")))
        sr = round((batter.runs / batter.balls_faced) * 100, 1)

        run_label = {
            0: "🏏 0 RUNS",
            1: "🏏 1 RUN",
            2: "🏏 2 RUNS",
            3: "🏏 3 RUNS",
            4: "🏏 4 RUNS!",
            5: "🏏 5 RUNS!",
            6: "🏏 6 RUNS!",
        }.get(runs, f"🏏 {runs} RUNS")
        result_lines = [f"💬 <i>{commentary}</i>"]
        if magic_msg:
            result_lines.append(html.escape(re.sub(r"<[^>]+>", "", str(magic_msg))))
        msg = (
            f"<b>{run_label}</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            + "\n".join(result_lines) + "\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"📊 Score: <b>{sum(p.runs for p in match.solo_players)}/{sum(1 for p in match.solo_players if p.is_out)}</b>"
        )

        try:
            if gif: await context.bot.send_animation(chat_id, gif, caption=msg, parse_mode=ParseMode.HTML)
            else: await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12648)")
            await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)

        # Over/Spell Rotation (Every 3 balls)
        match.solo_balls_this_spell += 1

        # ── 🎉 MILESTONE CELEBRATIONS (same as TEAM mode) ──
        await check_and_celebrate_milestones(context, chat_id, match, batter, 'batting')
        if match.solo_balls_this_spell >= 3:
            match.solo_balls_this_spell = 0
            old_idx = match.current_solo_bowl_idx
            next_idx = (old_idx + 1) % len(match.solo_players)
            
            # Bowler cannot be the current Batsman
            if next_idx == match.current_solo_bat_idx:
                next_idx = (next_idx + 1) % len(match.solo_players)
            
            match.current_solo_bowl_idx = next_idx
            new_bowler = match.solo_players[next_idx]

        # Trigger Next Ball
        # 🔧 GLITCH FIX: re-check — /endmatch may have fired during the awaits above
        # (animations, commentary calls, over-change sleeps) before we schedule the next ball.
        if is_match_stale(chat_id, match):
            logger.info("⛔ process_solo_turn_result (runs branch) aborted post-await — match already ended.")
            return
        await trigger_solo_ball(context, chat_id, match)

# --- NEW: Solo Callback Handler ---
async def solo_join_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Solo Join/Leave AND Start Game - WITH TIMER"""
    query = update.callback_query
    chat = query.message.chat
    user = query.from_user

    if chat.id not in active_matches:
        await query.answer()
        return
    match = active_matches[chat.id]
    
    # --- ACTION: START GAME ---
    if query.data == "solo_start_game":
        # 1. Check Permissions (Host-only, no group-admin bypass)
        if user.id != match.host_id:
            await query.answer(plain_alert("⚠️ Only the Host can start the match!"), show_alert=True)
            return

        # 2. Check Player Count
        if len(match.solo_players) < 2:
            await query.answer(plain_alert("⚠️ Need at least 2 players to start!"), show_alert=True)
            return

        # 3. Ask for explicit Yes/No confirmation before force-starting
        await query.answer()
        confirm_keyboard = InlineKeyboardMarkup([
            [styled_button("Yes, Force Start", callback_data="solo_start_confirm_yes"),
             styled_button("No, Cancel", callback_data="solo_start_confirm_no")]
        ])
        try:
            await context.bot.send_message(
                chat_id=chat.id,
                text=themed(
                    "FORCE START",
                    [
                        f"<b>{html.escape(user.first_name)}</b> wants to start the match now.",
                        "The remaining join timer will be skipped.",
                        f"👥 Players: <b>{len(match.solo_players)}</b>",
                        "Confirm force start?"
                    ],
                    emoji="⚠️"
                ),
                parse_mode=ParseMode.HTML,
                reply_markup=confirm_keyboard
            )
        except Exception as e:
            logger.error(f"Failed to send solo force-start confirmation: {e}")
        return

    # --- ACTION: CONFIRM START GAME (Yes/No) ---
    if query.data in ("solo_start_confirm_yes", "solo_start_confirm_no"):
        if user.id != match.host_id:
            await query.answer(plain_alert("🚫 Only the Host can confirm this!"), show_alert=True)
            return

        if query.data == "solo_start_confirm_no":
            try:
                await query.edit_message_text(
                    themed("FORCE START CANCELLED", ["The lobby will continue normally."], emoji="❌"),
                    parse_mode=ParseMode.HTML
                )
            except Exception:
                pass
            return

        if match.phase != GamePhase.SOLO_JOINING or len(match.solo_players) < 2:
            await query.answer(plain_alert("⚠️ Need at least 2 players to start!"), show_alert=True)
            return

        try:
            await query.edit_message_text("🚀 <b>FORCE START CONFIRMED</b>\n\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\nClosing registration now...",
                                           parse_mode=ParseMode.HTML)
        except Exception:
            pass

        # Cancel Timer Task before starting
        if hasattr(match, 'solo_timer_task') and match.solo_timer_task:
            match.solo_timer_task.cancel()

        # Start the Game Logic
        await start_solo_mechanics(context, chat.id, match)
        return

    # --- VALIDATION FOR JOIN/LEAVE ---
    if match.game_mode not in ["SOLO", "MAGICBALL"] or match.phase != GamePhase.SOLO_JOINING:
        await query.answer("Registration Closed!", show_alert=True)
        return

    user_tag = f'<a href=\"tg://user?id={user.id}\">{html.escape(user.first_name)}</a>' + _title_suffix(user.id)

    # --- ACTION: JOIN ---
    if query.data == "solo_join":
        # 🆕 New players must start @cricoverse_bot first (shared DB across main + clones)
        if not player_is_known(user.id):
            await require_started_main_bot(update, user, use_callback=True)
            return
        # 🚫 Bowling-timeout ban check
        ban_left = get_bowling_ban_remaining(user.id)
        if ban_left:
            await query.answer(
                plain_alert(f"🚫 Banned from joining matches for repeated bowling timeouts. Time left: {_format_ban_remaining(ban_left)}"),
                show_alert=True
            )
            return
        # Check duplicate
        for p in match.solo_players:
            if p.user_id == user.id:
                await query.answer("Already joined!", show_alert=True)
                return
        
        # Init Stats if new user
        if user.id not in player_stats: init_player_stats(user.id)
        
        # Add Player
        p = Player(user.id, user.username or "", user.first_name)
        match.solo_players.append(p)
        
        # Update the Board Image
        await update_solo_board(context, chat.id, match)

        # Popup alert to the player who tapped Join (no group spam)
        await query.answer(plain_alert(f"✅ You joined the Battleground! 🔥"), show_alert=True)

    # --- ACTION: LEAVE ---
    elif query.data == "solo_leave":
        for i, p in enumerate(match.solo_players):
            if p.user_id == user.id:
                match.solo_players.pop(i)
                
                # Update the Board Image
                await update_solo_board(context, chat.id, match)

                # Popup alert to the player who tapped Leave (no group spam)
                await query.answer(plain_alert("👋 You left the Battleground."), show_alert=True)
                return
        
        await query.answer("You are not in the list.", show_alert=True)

async def solo_join_countdown(context, chat_id, match):
    """Background Timer for Solo Joining Phase - Auto Updates Board"""
    try:
        warning_sent = False
        last_bump = time.time()
        # 🆕 Even when the per-group lobby timer is OFF (default), an empty/
        # under-filled lobby must not wait forever. Track how long the
        # player count has stayed below the 2-player minimum and — after
        # 10 minutes with no new joiner — auto-cancel the lobby, save a
        # resumable /regame snapshot, and clean up, exactly like the
        # universal in-match inactivity watchdog does for live matches.
        no_join_since = time.time()
        last_known_count = len(match.solo_players)
        LOBBY_NO_JOIN_TIMEOUT = 10 * 60
        while True:
            # Check if phase changed
            if match.phase != GamePhase.SOLO_JOINING:
                break

            # 🔧 Lobby timer is OFF by default per group (admins opt in via
            # /gcsettings). When it's off, the lobby doesn't auto-start on a
            # clock, but it still auto-cancels after 10 minutes with no new
            # joiner (see LOBBY_NO_JOIN_TIMEOUT below) — the host can still
            # force-start any time via the "🚀 START MATCH" button.
            if not get_gc_setting(match.group_id, "lobby_timer_enabled", False):
                current_count = len(match.solo_players)
                if current_count != last_known_count:
                    last_known_count = current_count
                    no_join_since = time.time()

                if current_count < 2 and (time.time() - no_join_since) >= LOBBY_NO_JOIN_TIMEOUT:
                    try:
                        resume_code = save_match_for_resume(match, chat_id, match.group_name, match.host_id)
                        extra = f"\n🔑 Resume within 12h: <code>/regame {resume_code}</code>" if resume_code else ""
                        await context.bot.send_message(
                            chat_id,
                            themed("MATCH CANCELLED", [f"No one joined for 10 minutes.{extra}"], emoji="❌"),
                            parse_mode=ParseMode.HTML
                        )
                        if match.main_message_id:
                            try:
                                await context.bot.unpin_chat_message(chat_id=chat_id, message_id=match.main_message_id)
                            except Exception:
                                pass
                    except Exception as e:
                        logger.error(f"solo_join_countdown: auto-cancel error for {chat_id}: {e}")
                    active_matches.pop(chat_id, None)
                    processing_commands.pop(chat_id, None)
                    break

                await asyncio.sleep(10)
                if match.phase == GamePhase.SOLO_JOINING and time.time() - last_bump >= 30:
                    await bump_solo_board(context, chat_id, match)
                    last_bump = time.time()
                continue

            remaining = match.solo_join_end_time - time.time()
            
            # 30 Seconds Warning
            if remaining <= 30 and remaining > 20 and not warning_sent:
                await context.bot.send_message(
                    chat_id,
                    themed("JOINING OPEN", ["<b>30 seconds</b> remain to join the match."], emoji="⏳"),
                    parse_mode=ParseMode.HTML
                )
                warning_sent = True

            # Time Up
            if remaining <= 0:
                # Check minimum players
                if len(match.solo_players) < 2:
                    await context.bot.send_message(
                        chat_id,
                        themed("MATCH CANCELLED", ["Not enough players joined."], emoji="❌"),
                        parse_mode=ParseMode.HTML
                    )
                    del active_matches[chat_id]
                else:
                    # Auto-start the game
                    await context.bot.send_message(
                        chat_id,
                        themed("TIME'S UP", ["Starting the match now..."], emoji="⏰"),
                        parse_mode=ParseMode.HTML
                    )
                    await start_solo_mechanics(context, chat_id, match)
                break
            
            # Wait 10 seconds before next update
            await asyncio.sleep(10)
            
            # Update Board
            if match.phase == GamePhase.SOLO_JOINING:
                # Every 30s: delete + resend so the board resurfaces at the
                # bottom of the chat (won't get buried under new messages).
                if time.time() - last_bump >= 30:
                    await bump_solo_board(context, chat_id, match)
                    last_bump = time.time()
                else:
                    await update_solo_board(context, chat_id, match)
            
    except asyncio.CancelledError:
        pass
    except Exception as e:
        logger.error(f"Solo timer error: {e}")

def _build_solo_lb_rows(sorted_players) -> List[str]:
    """Pre-render one HTML row per player for the solo end-game leaderboard."""
    BAR = "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
    medals = ["🥇", "🥈", "🥉"]
    rows = []
    for i, p in enumerate(sorted_players):
        rank_icon = medals[i] if i < 3 else f"<b>{i+1}.</b>"
        status = " (Not Out)" if not p.is_out else ""
        sr = round((p.runs / p.balls_faced) * 100, 1) if p.balls_faced > 0 else 0
        p_balls_bowled = getattr(p, "balls_bowled", 0)
        wkt_txt = f" | 🎳 {p.wickets}/{getattr(p, 'runs_conceded', 0)} ({format_overs(p_balls_bowled)})" if p_balls_bowled > 0 else ""
        rows.append(f"{rank_icon} <b>{html.escape(p.first_name)}</b>: {p.runs}({p.balls_faced}) SR: {sr}{status}{wkt_txt}")
    return rows


def _render_solo_lb_page(rows: List[str], page: int, per_page: int = SOLO_LB_PAGE_SIZE):
    """Returns (html_text, clamped_page, total_pages) for one page of rows."""
    total_pages = max(1, math.ceil(len(rows) / per_page))
    page = max(0, min(page, total_pages - 1))
    start = page * per_page
    chunk = rows[start:start + per_page]

    lines = list(chunk)
    if total_pages > 1:
        lines.insert(0, f"Page <b>{page + 1}/{total_pages}</b>")
    text = themed("FINAL LEADERBOARD", lines, emoji="📊")
    return _safe_truncate_html(text, 4096), page, total_pages


def _solo_lb_keyboard(chat_id: int, page: int, total_pages: int):
    """Prev/page-indicator/Next inline keyboard. None if only one page."""
    if total_pages <= 1:
        return None
    buttons = []
    if page > 0:
        buttons.append(InlineKeyboardButton("◀️ Prev", callback_data=f"soloendlb_{chat_id}_{page - 1}"))
    buttons.append(InlineKeyboardButton(f"{page + 1}/{total_pages}", callback_data="noop"))
    if page < total_pages - 1:
        buttons.append(InlineKeyboardButton("Next ▶️", callback_data=f"soloendlb_{chat_id}_{page + 1}"))
    return InlineKeyboardMarkup([buttons])


async def solo_end_leaderboard_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles ◀️/▶️ taps on the paginated solo end-game Final Leaderboard."""
    query = update.callback_query
    try:
        _, chat_id_str, page_str = query.data.split("_", 2)
        chat_id = int(chat_id_str)
        page = int(page_str)
    except Exception:
        await query.answer()
        return

    rows = _solo_lb_pages_cache.get(chat_id)
    if not rows:
        await query.answer("⚠️ Leaderboard data expired.", show_alert=True)
        return

    text, page, total_pages = _render_solo_lb_page(rows, page)
    kb = _solo_lb_keyboard(chat_id, page, total_pages)
    try:
        await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as e:
        logger.warning(f"solo_end_leaderboard_callback edit failed: {e}")
    await query.answer()


async def end_solo_game_logic(context, chat_id, match):
    """✅ FIXED: Solo End with GC Notification"""
    match.phase = GamePhase.MATCH_ENDED

    # 🔧 GLITCH FIX: cancel any lingering timer/task tied to this match so it
    # can't wake up later and act on a chat that has since moved on to a new
    # match. This mirrors what the manual /endsolo confirm handler already does.
    for _task_attr in ("ball_timeout_task", "solo_timer_task", "join_phase_task",
                       "active_ball_task", "pause_task"):
        _task = getattr(match, _task_attr, None)
        if _task:
            _task.cancel()

    # 🔧 GLITCH FIX: remove from active_matches immediately so a stray/late
    # callback checking "chat_id not in active_matches" can't mistake this
    # dead match for the currently active one.
    if active_matches.get(chat_id) is match:
        del active_matches[chat_id]
    
    # 🎨 SIMPLIFIED SOLO END FLOW (per request): the old squad-stats image,
    # Top Performers PIL card, Match Awards block, victory GIF, and paginated
    # leaderboard have ALL been removed. Solo match end now sends just two
    # things: 1) a single image with the new stylised "SOLO BATTLE CHAMPION"
    # caption, 2) the solo table scorecard right underneath it.
    await asyncio.sleep(1)
    
    sorted_players = sorted(match.solo_players, key=lambda x: x.runs, reverse=True)
    winner = sorted_players[0]

    # 🎳 Best Bowler: most wickets, tie-break by fewer runs conceded, among those who bowled
    bowled_players = [p for p in match.solo_players if getattr(p, "balls_bowled", 0) > 0]
    best_bowler = None
    if bowled_players:
        best_bowler = sorted(
            bowled_players,
            key=lambda p: (-p.wickets, getattr(p, "runs_conceded", 0))
        )[0]

    
    # Save Stats
    for p in match.solo_players:
        init_player_stats(p.user_id)
        
        if p.user_id in player_stats:
            s = player_stats[p.user_id]["solo"]
            s["matches"] += 1
            s["runs"] += p.runs
            s["balls"] += p.balls_faced
            s["wickets"] += p.wickets
            s["sixes"]   = s.get("sixes", 0) + getattr(p, "sixes", 0)
            s["fours"]   = s.get("fours", 0) + getattr(p, "boundaries", 0)
            if p.runs >= 100: s["centuries"] = s.get("centuries", 0) + 1
            elif p.runs >= 50: s["fifties"]  = s.get("fifties", 0) + 1
            if p.runs == 0 and p.is_out: s["ducks"] += 1
            if p.runs > s.get("highest", 0): s["highest"] = p.runs
            if p.runs > s.get("high_score", 0): s["high_score"] = p.runs

            # 🎳 Bowling stats
            p_balls_bowled = getattr(p, "balls_bowled", 0)
            p_runs_conceded = getattr(p, "runs_conceded", 0)
            s["runs_conceded"] = s.get("runs_conceded", 0) + p_runs_conceded
            s["balls_bowled"] = s.get("balls_bowled", 0) + p_balls_bowled
            if p_balls_bowled > 0:
                s["matches_bowled"] = s.get("matches_bowled", 0) + 1
                best_w = s.get("best_bowling_wickets", 0)
                best_r = s.get("best_bowling_runs", 0)
                if p.wickets > best_w or (p.wickets == best_w and (best_w == 0 or p_runs_conceded < best_r)):
                    s["best_bowling_wickets"] = p.wickets
                    s["best_bowling_runs"] = p_runs_conceded
            
            if p.user_id == winner.user_id: 
                s["wins"] += 1
            if p in sorted_players[:3]:
                s["top_3_finishes"] += 1
                
    save_data()

    # 🗄️ Sync solo stats to DB solo_ columns so mystats solo view has bowling data
    try:
        conn_solo = db_connect(DB_PATH)
        cs2 = conn_solo.cursor()
        for p in match.solo_players:
            uid = p.user_id
            s = player_stats.get(uid, {}).get("solo", {})
            is_win = 1 if uid == winner.user_id else 0
            is_top3 = 1 if p in sorted_players[:3] else 0
            p_balls_bowled = getattr(p, "balls_bowled", 0)
            p_runs_conceded = getattr(p, "runs_conceded", 0)
            bowled_this_match = 1 if p_balls_bowled > 0 else 0
            cs2.execute("""INSERT INTO user_stats
                (user_id, username, first_name,
                 solo_matches_played, solo_matches_won,
                 solo_total_runs, solo_total_balls_faced,
                 solo_highest_score, solo_total_sixes, solo_total_fours,
                 solo_total_hundreds, solo_total_fifties, solo_total_ducks,
                 solo_top3_finishes,
                 solo_total_wickets, solo_total_balls_bowled, solo_total_runs_conceded,
                 solo_best_bowling_wickets, solo_best_bowling_runs, solo_matches_bowled)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(user_id) DO UPDATE SET
                    username = excluded.username,
                    first_name = excluded.first_name,
                    solo_matches_played = solo_matches_played + 1,
                    solo_matches_won = solo_matches_won + ?,
                    solo_total_runs = solo_total_runs + ?,
                    solo_total_balls_faced = solo_total_balls_faced + ?,
                    solo_highest_score = MAX(solo_highest_score, ?),
                    solo_total_sixes = solo_total_sixes + ?,
                    solo_total_fours = solo_total_fours + ?,
                    solo_total_hundreds = solo_total_hundreds + ?,
                    solo_total_fifties = solo_total_fifties + ?,
                    solo_total_ducks = solo_total_ducks + ?,
                    solo_top3_finishes = solo_top3_finishes + ?,
                    solo_total_wickets = solo_total_wickets + ?,
                    solo_total_balls_bowled = solo_total_balls_bowled + ?,
                    solo_total_runs_conceded = solo_total_runs_conceded + ?,
                    solo_best_bowling_wickets = ?,
                    solo_best_bowling_runs = ?,
                    solo_matches_bowled = solo_matches_bowled + ?
            """, (
                uid, p.username or "", p.first_name,
                1, is_win,
                p.runs, p.balls_faced,
                p.runs, getattr(p, "sixes", 0), getattr(p, "boundaries", 0),
                1 if p.runs >= 100 else 0,
                1 if 50 <= p.runs < 100 else 0,
                1 if (p.runs == 0 and p.is_out) else 0,
                is_top3,
                p.wickets, p_balls_bowled, p_runs_conceded,
                s.get("best_bowling_wickets", 0), s.get("best_bowling_runs", 0), bowled_this_match,
                # ON CONFLICT UPDATE values
                is_win, p.runs, p.balls_faced, p.runs,
                getattr(p, "sixes", 0), getattr(p, "boundaries", 0),
                1 if p.runs >= 100 else 0,
                1 if 50 <= p.runs < 100 else 0,
                1 if (p.runs == 0 and p.is_out) else 0,
                is_top3,
                p.wickets, p_balls_bowled, p_runs_conceded,
                s.get("best_bowling_wickets", 0), s.get("best_bowling_runs", 0), bowled_this_match,
            ))

        # 🔧 FIX: solo matches were updating user_stats (solo_ columns) above
        # but NEVER inserting a row into match_history — that table is what
        # /botstats' Top-5-Groups, daily worm chart, and Today/7d/30d windows
        # all read from, so every solo match was invisible to those views
        # even though it was correctly tracked in user_stats.
        cs2.execute("""
            INSERT INTO match_history
            (group_id, match_type, player_of_match, match_date)
            VALUES (?, 'SOLO', ?, CURRENT_TIMESTAMP)
        """, (chat_id, winner.user_id))

        conn_solo.commit()
        conn_solo.close()
    except Exception as solo_db_err:
        logger.error(f"Solo stats DB sync error: {solo_db_err}")


    # ✅ 2. WINNER CARD — new simplified format (no icons on the stat labels,
    # just the clean themed box), sent as the caption of a single image.
    winner_sr = round((winner.runs / winner.balls_faced) * 100, 1) if winner.balls_faced > 0 else 0
    winner_tag = f'<a href=\"tg://user?id={winner.user_id}\">{html.escape(winner.first_name)}</a>' + _title_suffix(winner.user_id)
    winner_balls_bowled = getattr(winner, "balls_bowled", 0)
    winner_econ = None
    if winner_balls_bowled > 0:
        winner_econ = round((getattr(winner, "runs_conceded", 0) / winner_balls_bowled) * 6, 2)

    champion_lines = [
        f"🏆 <b>SOLO BATTLE CHAMPION</b>",
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        f"👤 Winner: {winner_tag}",
        f"💯 Score: <b>{winner.runs} ({winner.balls_faced}b)</b>",
        f"⚡ Strike Rate: <b>{winner_sr}</b>"
    ]
    if winner_balls_bowled > 0:
        champion_lines.extend([
            f"🏏 Wickets: <b>{winner.wickets}</b>",
            f"📊 Bowling: <b>{winner.wickets}/{getattr(winner, 'runs_conceded', 0)}</b> ({format_overs(winner_balls_bowled)} ov)",
            f"🔥 Economy: <b>{winner_econ}</b>"
        ])
    msg = _safe_truncate_html("\n".join(champion_lines), 1024)

    async def _send_solo_scorecard_table():
        """Solo table scorecard, sent right under the winner card — same
        rich-table-first / <pre>-fallback pattern as the team scorecard."""
        try:
            html_solo = _build_solo_scorecard_html(match)
            ok = await _tg_send_rich_message(chat_id, html_solo, reply_markup=verse_zone_markup())
            if ok:
                return
        except Exception as e:
            logger.warning(f"Solo end scorecard rich-table error: {e}")
        try:
            text_solo, _ = _build_solo_scorecard(match)
            await context.bot.send_message(chat_id, text_solo, parse_mode=ParseMode.HTML, reply_markup=verse_zone_markup())
        except Exception as e2:
            logger.error(f"Solo end scorecard fallback error: {e2}")

    # 🖼️ Prefer the real "Top Performers" card — profile photos of the best
    # batsman (winner) and best bowler pasted onto solo_top_performers_template.
    # Falls back to the static SOLO_END_PHOTO, then to a plain text message,
    # so a template/pfp-fetch hiccup never blocks the winner announcement.
    top_performers_bio = None
    try:
        top_performers_bio = await generate_solo_top_performers_image(winner, best_bowler, context)
    except Exception as e:
        logger.error(f"Error building solo top performers card: {e}")

    try:
        if top_performers_bio:
            await context.bot.send_photo(chat_id, photo=top_performers_bio, caption=msg, parse_mode=ParseMode.HTML, reply_markup=verse_zone_markup())
        else:
            await context.bot.send_photo(chat_id, photo=SOLO_END_PHOTO, caption=msg, parse_mode=ParseMode.HTML, reply_markup=verse_zone_markup())
    except Exception as e:
        logger.error(f"Error sending solo end photo: {e}")
        try:
            await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML, reply_markup=verse_zone_markup())
        except Exception as e2:
            logger.error(f"Error sending solo end fallback message: {e2}")

    await _send_solo_scorecard_table()

async def endsolo_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """End solo match - ADMIN ONLY"""
    chat_id = update.effective_chat.id
    user_id = update.effective_user.id
    
    match = active_matches.get(chat_id)
    if not match:
        await update.message.reply_text(themed("NO ACTIVE MATCH", ["There is no active match in this group."], emoji="❌"), parse_mode=ParseMode.HTML)
        return
    
    if match.phase not in [GamePhase.SOLO_JOINING, GamePhase.SOLO_MATCH]:
        await update.message.reply_text(themed("NO SOLO MATCH", ["No Solo match is running."], emoji="❌"), parse_mode=ParseMode.HTML)
        return
    
    # Check if user is admin
    try:
        member = await context.bot.get_chat_member(chat_id, user_id)
        is_admin = member.status in ['creator', 'administrator']
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 13017)")
        is_admin = False
    
    if not is_admin and user_id != match.host_id:
        await update.message.reply_text(themed("PERMISSION DENIED", ["Only admins or the Host can end the Solo match."], emoji="🚫"), parse_mode=ParseMode.HTML)
        return
    
    # Show confirmation buttons
    keyboard = InlineKeyboardMarkup([
        [
            styled_button("Yes, End Solo", callback_data=f"confirm_endsolo_{chat_id}"),
            styled_button("Cancel", callback_data="cancel_endsolo")
        ]
    ])
    
    await update.message.reply_text(
        themed(
            "END SOLO MATCH",
            [
                "Are you sure you want to end this Solo match?",
                "📊 Final results will be generated and stats will be saved."
            ],
            emoji="⚠️"
        ),
        parse_mode=ParseMode.HTML,
        reply_markup=keyboard
    )

# /extendsolo
async def extendsolo_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat
    if chat.id not in active_matches: return
    match = active_matches[chat.id]
    
    if match.game_mode not in ["SOLO", "MAGICBALL"] or match.phase != GamePhase.SOLO_JOINING:
        await update.message.reply_text(themed("CANNOT EXTEND", ["You can only extend during the joining phase."], emoji="⚠️"), parse_mode=ParseMode.HTML)
        return

    try:
        sec = int(context.args[0])
        match.solo_join_end_time += sec
        await update.message.reply_text(themed("LOBBY EXTENDED", [f"Added <b>{sec} seconds</b> to the joining timer."], emoji="✅"), parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 13052)")
        await update.message.reply_text(themed("INVALID USAGE", ["Use <code>/extendsolo [seconds]</code>."], emoji="⚠️"), parse_mode=ParseMode.HTML)


