# ══════════════════════════════════════════════════════════════════════
# 🧠 ADAPTIVE HAND-CRICKET AI ENGINE  (opponent brain)
# ----------------------------------------------------------------------
# Replaces the old hand-tuned weight tables with a single learning brain.
#
#   * Opponent modelling: blends recency-weighted frequency, order-1 and
#     order-2 Markov (pattern) models to predict the human's next number.
#   * Exploitation is throttled by a per-difficulty `skill` factor, so
#     Easy stays beatable and God-level is genuinely scary.
#   * Anti-exploitability: the AI also watches ITS OWN outputs and mixes
#     toward uniform, so a human can never read the AI the way the AI
#     reads the human.
#   * Situational batting: aggression derived from required run rate,
#     balls left and wickets left rather than 30 hard-coded tables.
#   * Long-term memory: per-user profile persists across matches, so the
#     AI walks into ball #1 already knowing your habits.
# ══════════════════════════════════════════════════════════════════════

NUMS = (0, 1, 2, 3, 4, 5, 6)

# difficulty -> (exploit, aggression, noise)
#   exploit    = how often the read is actually acted upon
#   aggression = batting risk appetite multiplier
#   noise      = pure-random ball rate (keeps it human)
AI_SKILL = {
    "easy":   {"exploit": 0.08, "aggression": 0.70, "noise": 0.22},
    "medium": {"exploit": 0.32, "aggression": 0.95, "noise": 0.10},
    "hard":   {"exploit": 0.62, "aggression": 1.15, "noise": 0.04},
    "god":    {"exploit": 0.88, "aggression": 1.35, "noise": 0.01},
}

# Long-term per-user habit memory: user_id -> {"bat": [...], "bowl": [...]}
AI_PROFILES = {}
_AI_PROFILE_CAP = 120


def _skill(difficulty):
    return AI_SKILL.get(difficulty, AI_SKILL["hard"])


def ai_remember(user_id, kind, num):
    """Record a human number into long-term profile memory (kind: bat/bowl)."""
    try:
        prof = AI_PROFILES.setdefault(int(user_id), {"bat": [], "bowl": []})
        seq = prof.setdefault("bat" if kind == "bat" else "bowl", [])
        seq.append(int(num))
        if len(seq) > _AI_PROFILE_CAP:
            del seq[:-_AI_PROFILE_CAP]
    except Exception:
        pass


def _profile_seq(user_id, kind):
    try:
        return AI_PROFILES.get(int(user_id), {}).get(kind, [])
    except Exception:
        return []


def _normalise(dist):
    total = sum(dist)
    if total <= 0:
        return [1.0 / 7] * 7
    return [x / total for x in dist]


def predict_distribution(history, long_term=None):
    """Probability the human plays each of 0..6 next.

    Blend of three models:
      * recency-weighted frequency over this match
      * order-1 Markov  (what follows their last number)
      * order-2 Markov  (what follows their last pair)
    Plus a uniform prior so nothing is ever probability zero.
    """
    history = [int(n) for n in (history or []) if 0 <= int(n) <= 6]
    combined = list(long_term or []) + history

    # --- uniform prior (Laplace smoothing) ---
    dist = [1.0] * 7

    # --- recency-weighted frequency ---
    for i, n in enumerate(combined[-24:]):
        dist[n] += 1.0 + (i * 0.28)

    # --- order-1 Markov ---
    if len(combined) >= 3:
        last = combined[-1]
        for i in range(len(combined) - 1):
            if combined[i] == last:
                dist[combined[i + 1]] += 2.4

    # --- order-2 Markov (strongest signal: real pattern play) ---
    if len(combined) >= 5:
        pair = (combined[-2], combined[-1])
        for i in range(len(combined) - 2):
            if (combined[i], combined[i + 1]) == pair:
                dist[combined[i + 2]] += 4.5

    return _normalise(dist)


def read_confidence(history, long_term=None):
    """0..1 — how sharply peaked our read is (peak vs uniform)."""
    n = len(list(long_term or [])) + len(history or [])
    if n < 2:
        return 0.0
    dist = predict_distribution(history, long_term)
    peak = max(dist)
    sharpness = max(0.0, (peak - 1.0 / 7) / (1.0 - 1.0 / 7))
    return min(1.0, sharpness * min(1.0, n / 8.0))


def _anti_predictable(dist, own_history):
    """Damp numbers the AI itself has been leaning on, so the human
    can't reverse-read the AI."""
    out = list(dist)
    for i, n in enumerate((own_history or [])[-6:]):
        if 0 <= n <= 6:
            out[n] *= 0.55 + (0.07 * i)
    return _normalise(out)


def ai_pick_bowl(match, difficulty, user_id=None):
    """AI chooses what to BOWL — it wants to match the human's shot."""
    sk = _skill(difficulty)
    hist = match.get("user_bat_history", []) or []
    long_term = _profile_seq(user_id, "bat") if user_id is not None else []

    if random.random() < sk["noise"]:
        return random.choice(NUMS)

    dist = predict_distribution(hist, long_term)
    conf = read_confidence(hist, long_term)

    # Situational pressure: at the death, humans reach for boundaries.
    balls_left = (match.get("overs", 0) * 6) - match.get("user_balls", 0)
    target = match.get("target", 0)
    if match.get("innings") == 2 and target:
        need = target - match.get("user_score", 0)
        if balls_left > 0 and need > 0:
            rrr = need / max(balls_left, 1)
            if rrr >= 4:            # must slog -> expect 4/5/6
                for n in (4, 5, 6):
                    dist[n] *= 1.9
            elif rrr <= 1.2:        # cruising -> expect 1/2/3
                for n in (1, 2, 3):
                    dist[n] *= 1.7
    if balls_left <= 2:
        for n in (4, 5, 6):
            dist[n] *= 1.5
    dist = _normalise(dist)

    # Act on the read only as often as the difficulty allows.
    if random.random() < sk["exploit"] * max(conf, 0.25):
        return max(NUMS, key=lambda n: dist[n])

    dist = _anti_predictable(dist, match.get("ai_bowl_history", []))
    return random.choices(NUMS, weights=dist)[0]


def ai_pick_bat(match, difficulty, user_id=None):
    """AI chooses its SHOT — maximise runs while dodging the human's ball."""
    sk = _skill(difficulty)
    hist = match.get("user_bowl_history", []) or []
    long_term = _profile_seq(user_id, "bowl") if user_id is not None else []

    if random.random() < sk["noise"]:
        return random.choice(NUMS)

    balls_left = max((match.get("overs", 0) * 6) - match.get("ai_balls", 0), 0)
    target = match.get("target", 0)
    chasing = bool(target) and not (
        match.get("ai_batting_first") and match.get("innings") == 1
    )
    need = (target - match.get("ai_score", 0)) if chasing else None

    # ---- situational aggression (0 = block, 1 = all-out slog) ----
    if chasing and need is not None and need <= 0:
        aggression = 0.25                      # already won, protect wicket
    elif chasing and need is not None:
        rrr = need / max(balls_left, 1)
        aggression = min(1.0, max(0.15, (rrr - 0.8) / 4.2))
        if balls_left <= 3:
            aggression = max(aggression, 0.85)
    else:
        # Setting a total: build, then accelerate as balls run out.
        used = match.get("ai_balls", 0)
        total = max(match.get("overs", 1) * 6, 1)
        aggression = 0.35 + 0.55 * (used / total)
    aggression = min(1.0, aggression * sk["aggression"])

    # Value of each shot, tilted by aggression.
    dist = [
        (1.0 - aggression) * 1.6 + 0.05,            # 0
        (1.0 - aggression) * 2.0 + 0.25,            # 1
        (1.0 - aggression) * 1.9 + 0.55,            # 2
        1.1 + aggression * 0.5,                     # 3
        0.5 + aggression * 2.6,                     # 4
        0.3 + aggression * 3.2,                     # 5
        0.2 + aggression * 4.0,                     # 6
    ]

    # Never leave exactly enough runs on the table when you can finish it.
    if chasing and need is not None and 0 < need <= 6:
        dist[need] *= 2.2

    # ---- dodge the predicted delivery (this is where wickets are saved) ----
    pred = predict_distribution(hist, long_term)
    conf = read_confidence(hist, long_term)
    strength = sk["exploit"] * max(conf, 0.2)
    for n in NUMS:
        dist[n] *= max(0.02, 1.0 - (pred[n] * strength * 3.4))

    dist = _anti_predictable(_normalise(dist), match.get("ai_bat_history_own", []))
    return random.choices(NUMS, weights=dist)[0]


def ai_log_own(match, key, num):
    """Track the AI's own numbers so it stays unpredictable."""
    seq = match.setdefault(key, [])
    seq.append(int(num))
    if len(seq) > 12:
        del seq[:-12]


