def _rc_name(uid, name, maxlen: int = 14) -> str:
    n = (name or "Player").strip() or "Player"
    if len(n) > maxlen:
        n = n[:maxlen - 1] + "…"
    try:
        return n + _title_suffix(uid)
    except Exception:
        return n


def _rc_tabs(tabs, active, cb_fmt: str, per_row: int = 4):
    """tabs = [(key, label), ...] → button rows, active tab highlighted."""
    btns = [(("• " if k == active else "") + lbl, "success" if k == active else "link", cb_fmt.format(k=k))
            for k, lbl in tabs]
    return [btns[i:i + per_row] for i in range(0, len(btns), per_row)]


def _rc_cache(store: dict, key, ttl: float, builder):
    now = time.time()
    hit = store.get(key)
    if hit and now - hit[0] < ttl:
        return hit[1]
    val = builder()
    store[key] = (now, val)
    return val


# ═══════════════════════════════════════════════════════════════════════════
# 🌐 CRICOVERSE GLOBAL NEW-LOOK LAYER
#   1. rc_restyle()        – every outgoing HTML message/caption: old ┌├└╭┃ boxes and
#                            <blockquote> frames → new "Verse" theme (▸ bullets, ┄ dividers)
#   2. rc_norm_markup()    – every outgoing inline keyboard: guaranteed colour style on each
#                            button (also raw InlineKeyboardButton sites)
#   3. rich-everywhere     – text cards (menus, tables, boards) are sent/edited as native
#                            Rich Messages with in-card coloured buttons. Auto-fallback to the
#                            normal send on ANY error. Owner kill-switch: /richui on|off
#   Messages that tag players (tg://user links) stay normal messages so pings still notify.
# ═══════════════════════════════════════════════════════════════════════════
RICH_EVERYWHERE = True          # master switch (owner can flip live with /richui on|off)
_RC_DIV = "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
_RC_BULLET = ""

_RC_PROTECT = re.compile(r"(<pre>.*?</pre>|<code>.*?</code>)", re.S)
_RC_BQ_TOKEN = re.compile(r"<blockquote(\s+expandable)?>|</blockquote>")


def _rc_strip_plain_blockquotes(text: str) -> str:
    """Remove <blockquote>…</blockquote> frames but keep <blockquote expandable> ones intact."""
    out, stack, last = [], [], 0
    for m in _RC_BQ_TOKEN.finditer(text):
        out.append(text[last:m.start()])
        last = m.end()
        tok = m.group(0)
        if tok == "</blockquote>":
            kind = stack.pop() if stack else "plain"
            out.append(tok if kind == "exp" else "")
        else:
            kind = "exp" if m.group(1) else "plain"
            stack.append(kind)
            out.append(tok if kind == "exp" else "")
    out.append(text[last:])
    return "".join(out)


_RC_RE_BORDER_ONLY = re.compile(r"^\s*[┌└╭╰├][─━┐┘╮╯┤]{3,}[┐┘╮╯┤]?\s*$")
_RC_RE_DIVIDER = re.compile(r"^\s*[─━═]{6,}\s*$")
_RC_RE_BULLET = re.compile(r"^(\s*)[├│┃└]\s?")


_RC_EDGE_PRE = re.compile(r"^((?:</?blockquote(?:\s+expandable)?>)*)")
_RC_EDGE_SUF = re.compile(r"((?:</blockquote>)*)$")


def _rc_restyle_line(line: str) -> Optional[str]:
    """Restyle one line, preserving blockquote tags glued to its start/end. None = drop line."""
    pre = _RC_EDGE_PRE.match(line).group(1)
    core = line[len(pre):]
    suf = _RC_EDGE_SUF.search(core).group(1)
    if suf:
        core = core[:len(core) - len(suf)]
    new = _rc_restyle_core(core)
    if new is None:
        return (pre + suf) or None
    return pre + new + suf


def _rc_restyle_core(line: str) -> Optional[str]:
    """Return the restyled line, or None to drop it."""
    if not line.strip():
        return line
    if _RC_RE_BORDER_ONLY.match(line):
        return _RC_DIV if line.strip()[:1] in "┌╭├" else None
    if _RC_RE_DIVIDER.match(line):
        return _RC_DIV
    s = line.strip()
    s = s.replace("➜", "—").replace("➔", "—").replace("→", "—").replace("▸", "")
    # ┌─❰ TITLE ❱   /   ╭━━ TITLE ━━🏅
    if s[:1] in "┌╭" and re.match(r"^[┌╭][─━]", s):
        inner = re.sub(r"^[┌╭][─━]+", "", s)
        inner = re.sub(r"[─━]+[^\w<>]{0,3}$", "", inner)
        inner = inner.replace("❰", "").replace("❱", "").replace("┃", "").strip()
        if not inner:
            return None
        if "<b>" not in inner:
            inner = f"<b>{inner}</b>"
        return inner + "\n\n" + _RC_DIV
    m = _RC_RE_BULLET.match(line)
    if m:
        rest = line[m.end():]
        rest = re.sub(r"\s*[│┃┐┘]\s*$", "", rest)
        if not rest.strip():
            return ""
        if _RC_RE_DIVIDER.match(rest):
            return _RC_DIV
        sub = re.match(r"^\s*[├└]\s*(.*)$", rest)          # nested tree glyph → ↳ sub-line
        if sub:
            return f"{m.group(1)}   ↳ {sub.group(1)}"
        return f"{m.group(1)}{rest}"
    # lone closing-corner glyph lines like "└" / "╰"
    if s in ("└", "╰", "┌", "╭"):
        return None
    return line


def rc_restyle(text):
    """Old box theme → new Verse theme. Never touches <pre>/<code>. Safe no-op on non-str."""
    if not text or not isinstance(text, str):
        return text
    if not any(c in text for c in "┌└├│╭╰┃━═─") and "<blockquote>" not in text:
        return text
    try:
        parts = _RC_PROTECT.split(text)
        for i in range(0, len(parts), 2):          # even indices = unprotected text
            seg = _rc_strip_plain_blockquotes(parts[i])
            lines = []
            for ln in seg.split("\n"):
                new = _rc_restyle_line(ln)
                if new is not None:
                    lines.append(new)
            seg = "\n".join(lines)
            seg = re.sub(r"(" + re.escape(_RC_DIV) + r")[ \t]*(?:\n[ \t]*)+(?=" + re.escape(_RC_DIV) + r")", "", seg)
            seg = re.sub(r"\n{3,}", "\n\n", seg)
            parts[i] = seg
        return "".join(parts).strip("\n")
    except Exception:
        logger.exception("rc_restyle failed — sending original text")
        return text


# ───────────────────────── buttons ─────────────────────────
_RC_DANGER_WORDS = ("close", "cancel", "leave", "back", "delete", "stop", "exit", "reject", "decline",
                    "remove", "surrender", "end", "ban", "no")
_RC_SUCCESS_WORDS = ("join", "start", "accept", "confirm", "yes", "done", "ready", "buy", "bat", "bowl",
                     "heads", "tails", "claim", "keep", "swap", "take", "proceed", "go")


def _rc_guess_style(btn) -> str:
    t = (getattr(btn, "text", "") or "").lower()
    cb = (getattr(btn, "callback_data", "") or "").lower() if isinstance(getattr(btn, "callback_data", ""), str) else ""
    words = set(re.findall(r"[a-z]+", t)) | set(re.findall(r"[a-z]+", cb))
    if words & set(_RC_DANGER_WORDS):
        return "danger"
    if words & set(_RC_SUCCESS_WORDS):
        return "success"
    return "primary"


def rc_norm_markup(markup):
    """Apply button colors; keep each button on the row the code placed it (original layout)."""
    try:
        if not isinstance(markup, InlineKeyboardMarkup):
            return markup
        changed = False
        rows = []
        for row in markup.inline_keyboard:
            new_row = []
            for b in row:
                nb = b
                if not getattr(b, "style", None):
                    try:
                        d = b.to_dict()
                        d.pop("style", None)
                        nb = InlineKeyboardButton(**{k: v for k, v in d.items()
                                                     if k in ("text", "callback_data", "url", "switch_inline_query",
                                                              "switch_inline_query_current_chat", "web_app", "login_url")},
                                                   style=_rc_guess_style(b))
                    except Exception:
                        nb = b
                new_row.append(nb)
                if nb is not b:
                    changed = True
            if new_row:
                rows.append(new_row)
        return InlineKeyboardMarkup(rows) if changed else markup
    except Exception:
        return markup


# ───────────────────────── rich conversion ─────────────────────────
_RC_SENT: "OrderedDict" = OrderedDict()   # (chat_id, msg_id) -> (body_html, rows)
_RC_SENT_MAX = 4000
_RC_CONSEC_FAIL = 0


def _rc_remember(chat_id, msg_id, body, rows):
    _RC_SENT[(chat_id, msg_id)] = (body, rows)
    _RC_SENT.move_to_end((chat_id, msg_id))
    while len(_RC_SENT) > _RC_SENT_MAX:
        _RC_SENT.popitem(last=False)


def _rc_rows_from_markup(markup):
    """InlineKeyboardMarkup → rows of (text, style, data|url) or None if unsupported button type."""
    return _rcm_rows(markup)
    if markup is None:
        return []
    if not isinstance(markup, InlineKeyboardMarkup):
        return None
    rows = []
    for r in markup.inline_keyboard:
        line = []
        for b in r:
            cb = getattr(b, "callback_data", None)
            if not isinstance(cb, str) or getattr(b, "url", None) or getattr(b, "web_app", None) \
                    or getattr(b, "login_url", None) or getattr(b, "switch_inline_query", None) is not None \
                    or getattr(b, "switch_inline_query_current_chat", None) is not None:
                return None
            line.append((b.text, getattr(b, "style", None) or _rc_guess_style(b), cb))
        if line:
            rows.append(line)
    return rows


_RC_TITLE_LINE = re.compile(r"^((?:[^\w<>&]|\s){0,8})<b>(.{2,80}?)</b>((?:[^\w<>&]|\s){0,8})$")


_RC_CMD_LINE = re.compile(r"^(?:[▸]\s*)?((?:<code>)?/[a-zA-Z_]{2,32}(?:@\w+)?(?:\s+[\[(@<][^—–]*?)?(?:</code>)?)\s+[—–]\s+(.+)$")


def rc_html_to_rich(text: str) -> str:
    """Telegram-HTML (b/i/u/s/a/code/pre/blockquote expandable) → Rich HTML blocks."""
    parts = re.split(r"(<pre>.*?</pre>|<blockquote expandable>.*?</blockquote>)", text, flags=re.S)
    out, first_block = [], True
    for i, seg in enumerate(parts):
        if not seg:
            continue
        if i % 2 == 1:                                    # protected block (pre / expandable quote)
            if seg.startswith("<blockquote expandable>"):
                inner = seg[len("<blockquote expandable>"):-len("</blockquote>")].strip("\n")
                head, _, rest = inner.partition("\n")
                tm = _RC_TITLE_LINE.match(head.strip()) if rest else None
                if tm:
                    summary = (tm.group(1) + tm.group(2)).strip()
                    inner = rest
                else:
                    summary = "Show more"
                out.append(rc_details(summary, rc_html_to_rich(inner)))
            else:
                out.append(seg)
            first_block = False
            continue
        for para in re.split(r"\n\s*\n", seg.strip("\n")):
            lines = para.split("\n")
            buf, cmds = [], []

            def _flush():
                if buf:
                    out.append("<p>" + "<br>".join(buf) + "</p>")
                    buf.clear()

            def _flush_cmds():
                if len(cmds) >= 2:                      # 2+ "/command — use" lines → grid table
                    _flush()
                    out.append(rc_table([["COMMAND", "WHAT IT DOES"]] + [[RcRaw(a), RcRaw(b)] for a, b in cmds],
                                        ["left", "left"], compact=False))
                else:
                    for a, b in cmds:
                        buf.append(f"{a} — {b}")
                cmds.clear()

            for ln in lines:
                cm = _RC_CMD_LINE.match(ln.strip())
                if cm:
                    cmds.append((cm.group(1).strip(), cm.group(2).strip()))
                    first_block = False
                    continue
                if cmds:
                    _flush_cmds()
                if ln.strip() == _RC_DIV:
                    _flush()
                    out.append(f"<p>{_RC_DIV}</p>")
                    continue
                if not ln.strip():
                    continue
                m = _RC_TITLE_LINE.match(ln.strip())
                if m and first_block and not buf:
                    out.append(f"<h3>{m.group(1)}{m.group(2)}{m.group(3)}</h3>".replace("  ", " "))
                    first_block = False
                    continue
                buf.append(ln)
                first_block = False
            _flush_cmds()
            _flush()
    return "".join(out)


def _rc_should_go_rich(text: str, rows) -> bool:
    if not RICH_EVERYWHERE or time.time() < _RC_OFF_UNTIL:
        return False
    if rows is None or not text:
        return False
    if "tg://user" in text:                       # keep tags/pings as normal messages
        return False
    if len(text) > 30000:
        return False
    return bool(rows) or text.count("\n") >= 3 or "<pre>" in text or "expandable" in text


def _rc_arg(args, kwargs, idx, name, default=None):
    if name in kwargs:
        return kwargs[name]
    return args[idx] if len(args) > idx else default


async def _rc_call(bot, method: str, payload: dict):
    """Raw Bot API call through PTB (keeps rate-limiter/pool) with requests fallback. Returns result or raises."""
    global _RC_OFF_UNTIL, _RC_CONSEC_FAIL
    if isinstance(payload, dict):
        rich = payload.get("rich_message")
        if isinstance(rich, dict) and isinstance(rich.get("html"), str):
            payload = dict(payload)
            rich = dict(rich)
            rich["html"] = inject_premium_emojis(rich["html"])
            payload["rich_message"] = rich
    try:
        fn = getattr(bot, "do_api_request", None)
        if fn is not None:
            res = await fn(method, api_kwargs=payload)
        else:
            res = await _rc_requests_call(method, payload)
        _RC_CONSEC_FAIL = 0
        return res
    except Exception as e:
        s = str(e).lower()
        if "not modified" in s:
            raise
        if "not found" in s or "404" in s or "method" in s and "unknown" in s:
            _RC_OFF_UNTIL = time.time() + 600
        else:
            _RC_CONSEC_FAIL += 1
            if _RC_CONSEC_FAIL >= 8:               # something is systematically wrong → cool down
                _RC_OFF_UNTIL = time.time() + 300
                _RC_CONSEC_FAIL = 0
        raise


async def _rc_requests_call(method: str, payload: dict):
    def _do():
        r = requests.post(f"https://api.telegram.org/bot{BOT_TOKEN}/{method}", json=payload, timeout=8.0)
        d = r.json()
        if not d.get("ok"):
            raise RuntimeError(d.get("description", f"http {r.status_code}"))
        return d["result"]
    return await asyncio.to_thread(_do)


def _rc_build_html(text: str, rows) -> str:
    body = rc_html_to_rich(text)
    return _rc_body_with_buttons(body, rows)


async def _rc_try_send(bot, args, kwargs):
    """Try to deliver this send_message call as a rich card. Returns a Message or None (— caller falls back)."""
    if kwargs.get("parse_mode") != ParseMode.HTML:
        return None
    chat_id = _rc_arg(args, kwargs, 0, "chat_id")
    text = _rc_arg(args, kwargs, 1, "text")
    if not isinstance(text, str) or kwargs.get("entities") or chat_id is None:
        return None
    markup = kwargs.get("reply_markup")
    rows = _rc_rows_from_markup(markup)
    styled = rc_restyle(text)
    if not _rc_should_go_rich(styled, rows):
        return None
    payload = {"chat_id": chat_id, "rich_message": {"html": _rc_build_html(styled, rows)}}
    _kb = _rc_markup(rows)
    if _kb:
        payload["reply_markup"] = _kb.to_dict()
    for k in ("message_thread_id", "disable_notification", "protect_content"):
        if kwargs.get(k) is not None:
            payload[k] = kwargs[k]
    rp = kwargs.get("reply_parameters")
    if rp is not None:
        payload["reply_parameters"] = rp.to_dict() if hasattr(rp, "to_dict") else rp
    elif kwargs.get("reply_to_message_id"):
        payload["reply_parameters"] = {"message_id": kwargs["reply_to_message_id"],
                                       "allow_sending_without_reply": True}
    try:
        res = await _rc_call(bot, "sendRichMessage", payload)
    except Exception as e:
        logger.info(f"rich send → normal send ({str(e)[:90]})")
        return None
    try:
        if isinstance(res, dict):
            msg = _telegram_module.Message.de_json(res, bot)
            mid = res["message_id"]
            real_chat = (res.get("chat") or {}).get("id", chat_id)
        else:
            msg, mid, real_chat = res, res.message_id, res.chat_id
        for cid in {chat_id, real_chat}:
            _rc_remember(cid, mid, payload["rich_message"]["html"], rows)
        return msg
    except Exception:
        logger.exception("rich send: could not build Message from result")
        return None


async def _rc_try_edit(bot, args, kwargs):
    """Rich edit for text edits. Returns True on success, None to let the normal path run."""
    if kwargs.get("inline_message_id") or kwargs.get("parse_mode") != ParseMode.HTML:
        return None
    text = _rc_arg(args, kwargs, 0, "text")
    chat_id = _rc_arg(args, kwargs, 1, "chat_id")
    message_id = _rc_arg(args, kwargs, 2, "message_id")
    if not isinstance(text, str) or chat_id is None or message_id is None:
        return None
    if (chat_id, message_id) not in _RC_SENT:
        return None                              # plain message → normal edit (caller retries rich on failure)
    rows = _rc_rows_from_markup(kwargs.get("reply_markup"))
    styled = rc_restyle(text)
    if rows is None or "tg://user" in styled:
        return None
    payload = {"chat_id": chat_id, "message_id": message_id,
               "rich_message": {"html": _rc_build_html(styled, rows)}}
    _kb = _rc_markup(rows)
    if _kb:
        payload["reply_markup"] = _kb.to_dict()
    if not _rcm_decorate(chat_id, message_id, payload, hero=True):
        return None
    try:
        await _rc_call(bot, "editMessageText", payload)
        _rc_remember(chat_id, message_id, payload["rich_message"]["html"], rows)
        return True
    except Exception as e:
        if "not modified" in str(e).lower():
            return True
        logger.info(f"rich edit → normal edit ({str(e)[:90]})")
        return None


async def _rc_try_edit_markup(bot, args, kwargs):
    """Keyboard is a normal inline keyboard now → let the regular edit_message_reply_markup handle it."""
    return None
    chat_id = _rc_arg(args, kwargs, 0, "chat_id")
    message_id = _rc_arg(args, kwargs, 1, "message_id")
    if chat_id is None or message_id is None or (chat_id, message_id) not in _RC_SENT:
        return None
    rows = _rc_rows_from_markup(kwargs.get("reply_markup"))
    if rows is None:
        return None
    old_html, _ = _RC_SENT[(chat_id, message_id)]
    body = re.sub(r"<tg-button-row.*?</tg-button-row>", "", old_html, flags=re.S)
    payload = {"chat_id": chat_id, "message_id": message_id, "rich_message": {"html": _rc_body_with_buttons(body, rows)}}
    if not _rcm_decorate(chat_id, message_id, payload):
        return None
    try:
        await _rc_call(bot, "editMessageText", payload)
        _rc_remember(chat_id, message_id, payload["rich_message"]["html"], rows)
        return True
    except Exception as e:
        if "not modified" in str(e).lower():
            return True
        return None


def rc_stored_plain(chat_id, message_id) -> str:
    """Plain Telegram-HTML-ish text of a rich card we sent (for code that appends a line to an old message)."""
    ent = _RC_SENT.get((chat_id, message_id))
    if not ent:
        return ""
    s = re.sub(r"<tg-button-row.*?</tg-button-row>", "", ent[0], flags=re.S)
    s = s.replace("<br>", "\n").replace("</p>", "\n\n").replace("<hr>", _RC_DIV + "\n")
    s = re.sub(r"<h\d>(.*?)</h\d>", r"<b>\1</b>\n", s)
    s = re.sub(r"</?(?!b\b|i\b|u\b|s\b|a\b|code\b|pre\b)[A-Za-z][^>]*>", "", s)
    return s.strip()


# ───────────────────────── Bot-level hooks (replace the old _premium_* wrappers) ─────────────────────────
def _rc_style_kwargs(args, kwargs, pos_text, key):
    """Restyle text/caption + normalise buttons, in place. Only for HTML-mode calls."""
    if kwargs.get("parse_mode") == ParseMode.HTML:
        if key in kwargs and kwargs[key]:
            kwargs[key] = rc_restyle(kwargs[key])
        elif pos_text is not None and len(args) > pos_text and isinstance(args[pos_text], str):
            args = list(args)
            args[pos_text] = rc_restyle(args[pos_text])
            args = tuple(args)
    if kwargs.get("reply_markup") is not None:
        kwargs["reply_markup"] = rc_norm_markup(kwargs["reply_markup"])
    return args, kwargs


_orig_edit_message_reply_markup = _telegram_module.Bot.edit_message_reply_markup


async def _newlook_send_message(self, *args, **kwargs):
    kwargs = dict(kwargs)
    if kwargs.get("reply_markup") is not None:
        kwargs["reply_markup"] = rc_norm_markup(kwargs["reply_markup"])
    try:
        msg = await _rc_try_send(self, args, kwargs)
    except Exception:
        logger.exception("rich send crashed — normal send")
        msg = None
    if msg is not None:
        return msg
    args, kwargs = _rc_style_kwargs(args, kwargs, 1, "text")
    args, kwargs = _premium_emojify_kwarg(kwargs, args, 1, "text")
    return await _orig_send_message(self, *args, **kwargs)


async def _newlook_edit_message_text(self, *args, **kwargs):
    kwargs = dict(kwargs)
    if kwargs.get("reply_markup") is not None:
        kwargs["reply_markup"] = rc_norm_markup(kwargs["reply_markup"])
    try:
        ok = await _rc_try_edit(self, args, kwargs)
    except Exception:
        logger.exception("rich edit crashed — normal edit")
        ok = None
    if ok:
        return True
    args, kwargs = _rc_style_kwargs(args, kwargs, 0, "text")
    args, kwargs = _premium_emojify_kwarg(kwargs, args, 0, "text")
    try:
        return await _orig_edit_message_text(self, *args, **kwargs)
    except _telegram_module.error.BadRequest as e:
        low = str(e).lower()
        if "message is not modified" in low:
            return None
        # a rich card that our registry lost (restart) can't take a plain edit → try rich once
        if RICH_EVERYWHERE and time.time() >= _RC_OFF_UNTIL and kwargs.get("parse_mode") == ParseMode.HTML \
                and not kwargs.get("inline_message_id"):
            try:
                text = _rc_arg(args, kwargs, 0, "text")
                chat_id = _rc_arg(args, kwargs, 1, "chat_id")
                message_id = _rc_arg(args, kwargs, 2, "message_id")
                rows = _rc_rows_from_markup(kwargs.get("reply_markup"))
                if isinstance(text, str) and rows is not None and chat_id is not None and message_id is not None:
                    styled = rc_restyle(text)
                    payload = {"chat_id": chat_id, "message_id": message_id,
                               "rich_message": {"html": _rc_build_html(styled, rows)}}
                    _kb = _rc_markup(rows)
                    if _kb:
                        payload["reply_markup"] = _kb.to_dict()
                    await _rc_call(self, "editMessageText", payload)
                    _rc_remember(chat_id, message_id, payload["rich_message"]["html"], rows)
                    return True
            except Exception:
                pass
        raise


async def _newlook_edit_message_reply_markup(self, *args, **kwargs):
    kwargs = dict(kwargs)
    if kwargs.get("reply_markup") is not None:
        kwargs["reply_markup"] = rc_norm_markup(kwargs["reply_markup"])
    try:
        ok = await _rc_try_edit_markup(self, args, kwargs)
    except Exception:
        ok = None
    if ok:
        return True
    try:
        return await _orig_edit_message_reply_markup(self, *args, **kwargs)
    except _telegram_module.error.BadRequest as e:
        if "message is not modified" in str(e).lower():
            return None
        raise


def _newlook_wrap_media(orig, key="caption"):
    async def _w(self, *args, **kwargs):
        kwargs = dict(kwargs)
        args, kwargs = _rc_style_kwargs(args, kwargs, None, key)
        return await orig(self, *args, **kwargs)
    return _w


async def richui_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """👑 Owner: /richui [on|off] — live kill-switch for the Rich-everywhere layer."""
    global RICH_EVERYWHERE, _RC_OFF_UNTIL
    if update.effective_user.id != OWNER_ID:
        return
    arg = (context.args[0].lower() if context.args else "")
    if arg in ("on", "off"):
        RICH_EVERYWHERE = arg == "on"
        _RC_OFF_UNTIL = 0.0
    state = "ON ✅" if RICH_EVERYWHERE and time.time() >= _RC_OFF_UNTIL else "OFF ⛔"
    await update.message.reply_text(
        f"🎨 <b>Rich UI:</b> {state}\ncached cards: <b>{len(_RC_SENT)}</b>\n"
        f"usage: <code>/richui on</code> · <code>/richui off</code>",
        parse_mode=ParseMode.HTML)



# ═══════════════════════════════════════════════════════════════════════════
# 🖼️ RICH MEDIA EVERYWHERE  — every send_photo / send_animation / send_video that has an
#     HTML caption (toss, batting, bowling, run scored, scorecards, leaderboards …) is
#     delivered as ONE rich card:  [photo / GIF / video on top] + [caption as rich body
#     (tables, <details>, headings)] + [in-card buttons].
#   • Local Path / bytes / BytesIO / InputFile are uploaded multipart once; the returned
#     file_id is cached so later sends are instant JSON calls.
#   • edit_message_caption / edit_message_media / edit_message_reply_markup keep working on
#     those cards (re-rendered via editMessageText(rich_message)); if that is impossible the
#     card is deleted and re-sent, so no old flow breaks.
#   • ANY failure → silently falls back to the old photo+caption send (per-kind cooldown after
#     repeated failures). /richui off|on switches the whole layer live.
# ═══════════════════════════════════════════════════════════════════════════
_RC_MEDIA: "OrderedDict" = OrderedDict()      # (chat_id, msg_id) -> entry dict
_RC_MEDIA_MAX = 4000
_RCM_OFF: Dict[str, float] = {"photo": 0.0, "animation": 0.0, "video": 0.0}
_RCM_FAILS: Dict[str, int] = {"photo": 0, "animation": 0, "video": 0}
_RCM_IDS: Dict[str, str] = {}                 # "kind:path" -> file_id returned by rich uploads


def _rcm_remember(chat_id, mid, ent):
    _RC_MEDIA[(chat_id, mid)] = ent
    _RC_MEDIA.move_to_end((chat_id, mid))
    while len(_RC_MEDIA) > _RC_MEDIA_MAX:
        _RC_MEDIA.popitem(last=False)


def _rcm_rows(markup):
    """InlineKeyboardMarkup — rows of (text, style, data|url). Unlike _rc_rows_from_markup, URL
    buttons are allowed (they go in the message's url keyboard). None — unsupported button type."""
    if markup is None:
        return []
    if not isinstance(markup, InlineKeyboardMarkup):
        return None
    rows = []
    for r in markup.inline_keyboard:
        line = []
        for b in r:
            if (getattr(b, "web_app", None) or getattr(b, "login_url", None) or getattr(b, "pay", None)
                    or getattr(b, "copy_text", None)
                    or getattr(b, "switch_inline_query", None) is not None
                    or getattr(b, "switch_inline_query_current_chat", None) is not None):
                return None
            url, cb = getattr(b, "url", None), getattr(b, "callback_data", None)
            if url:
                line.append((b.text, "link", url))
            elif isinstance(cb, str):
                line.append((b.text, getattr(b, "style", None) or _rc_guess_style(b), cb))
            else:
                return None
        if line:
            rows.append(line)
    return rows


def _rcm_find(obj):
    """Find (kind, file_id) of the media block in a sendRichMessage result."""
    if isinstance(obj, dict):
        t = obj.get("type")
        if t == "photo" and isinstance(obj.get("photo"), list) and obj["photo"]:
            fid = obj["photo"][-1].get("file_id")
            if fid:
                return "photo", fid
        if t in ("video", "animation") and isinstance(obj.get(t), dict) and obj[t].get("file_id"):
            return t, obj[t]["file_id"]
        for v in obj.values():
            r = _rcm_find(v)
            if r:
                return r
    elif isinstance(obj, list):
        for v in obj:
            r = _rcm_find(v)
            if r:
                return r
    return None


def _rcm_hero(kind: str, mid: str = "m0") -> str:
    if kind == "photo":
        return f'<img src="tg://photo?id={mid}"/>'
    return f'<video src="tg://video?id={mid}"></video>'


def _rcm_item(kind: str, value: str) -> dict:
    it = {"type": kind, "media": value}
    if kind == "video":
        it["supports_streaming"] = True
    return {"id": "m0", "media": it}


def _rcm_media_for(ent) -> Optional[list]:
    return [_rcm_item(ent["kind"], ent["file_id"])] if ent.get("file_id") else None


def _rcm_decorate(chat_id, mid, payload, hero: bool = False) -> bool:
    """Make an editMessageText payload for a rich MEDIA card carry its media list (+ hero if the
    html was rebuilt from text alone). Returns False if the card's media can't be referenced."""
    ent = _RC_MEDIA.get((chat_id, mid))
    if ent is None:
        return True
    media = _rcm_media_for(ent)
    if not media:
        return False
    rm = payload["rich_message"]
    if hero:
        rm["html"] = _rcm_hero(ent["kind"]) + rm["html"]
    rm["media"] = media
    return True


async def _rcm_source(kind: str, src):
    """— (value, upload|None, cache_key|None). upload = (filename, bytes). None — unsupported."""
    if isinstance(src, str) and src.startswith("file://"):
        from urllib.parse import urlparse, unquote
        src = Path(unquote(urlparse(src).path))
    if isinstance(src, str) and not src.startswith(("http://", "https://")) and len(src) < 400 \
            and os.path.isfile(src):
        src = Path(src)
    if isinstance(src, Path):
        if not src.is_file():
            return None
        key = f"{kind}:{src}"
        cached = (_RCM_IDS.get(key)
                  or (_photo_file_id_cache.get(str(src)) if kind == "photo" else None)
                  or (_animation_file_id_cache.get(str(src)) if kind == "animation" else None))
        if cached:
            return cached, None, key
        data = await asyncio.to_thread(src.read_bytes)
        return "attach://m0", (src.name, data), key
    if isinstance(src, str):
        return src, None, None                       # file_id or https URL
    name = "file." + {"photo": "jpg", "animation": "mp4", "video": "mp4"}[kind]
    if hasattr(src, "input_file_content"):           # telegram.InputFile
        return "attach://m0", (getattr(src, "filename", None) or name, src.input_file_content), None
    if isinstance(src, (bytes, bytearray)):
        return "attach://m0", (name, bytes(src)), None
    if hasattr(src, "read"):
        try:
            src.seek(0)
        except Exception:
            pass
        data = src.read()
        if isinstance(data, (bytes, bytearray)) and data:
            return "attach://m0", (getattr(src, "name", None) and os.path.basename(str(src.name)) or name, bytes(data)), None
    return None


def _rcm_post_multipart(method: str, fields: dict, upload):
    r = requests.post(f"https://api.telegram.org/bot{BOT_TOKEN}/{method}", data=fields,
                      files={"m0": upload}, timeout=90)
    try:
        d = r.json()
    except Exception:
        d = {}
    if not d.get("ok"):
        raise RuntimeError(d.get("description", f"http {r.status_code}"))
    return d["result"]


def _rcm_failed(kind: str, why):
    _RCM_FAILS[kind] = _RCM_FAILS.get(kind, 0) + 1
    logger.info(f"rich {kind} → normal send ({str(why)[:100]})")
    if _RCM_FAILS[kind] >= 3:
        _RCM_OFF[kind] = time.time() + 300
        _RCM_FAILS[kind] = 0
        logger.warning(f"rich {kind} cards disabled for 5 min after repeated failures")


async def _rcm_try_send(bot, kind: str, args, kwargs):
    """Deliver this send_photo/animation/video call as a rich media card. Message or None (— normal)."""
    if not RICH_EVERYWHERE or time.time() < _RC_OFF_UNTIL or time.time() < _RCM_OFF.get(kind, 0):
        return None
    if kwargs.get("parse_mode") != ParseMode.HTML:
        return None
    caption = kwargs.get("caption")
    chat_id = _rc_arg(args, kwargs, 0, "chat_id")
    src = _rc_arg(args, kwargs, 1, kind)
    if (not isinstance(caption, str) or not caption.strip() or chat_id is None or src is None
            or kwargs.get("caption_entities") or kwargs.get("has_spoiler")
            or kwargs.get("show_caption_above_media") or kwargs.get("business_connection_id")
            or kwargs.get("message_effect_id")):
        return None
    if "tg://user" in caption or len(caption) > 30000:
        return None
    rows = _rcm_rows(kwargs.get("reply_markup"))
    if rows is None:
        return None
    try:
        resolved = await _rcm_source(kind, src)
    except Exception as e:
        logger.info(f"rich {kind}: cannot read source ({e})")
        return None
    if resolved is None:
        return None
    value, upload, ckey = resolved

    styled = rc_restyle(caption)
    html_body = _rcm_hero(kind) + _rc_body_with_buttons(rc_html_to_rich(styled), rows)
    rich = {"html": html_body, "media": [_rcm_item(kind, value)]}
    url_kb = _rc_markup(rows, urls_only=True)
    extra = {}
    for k in ("message_thread_id", "disable_notification", "protect_content"):
        if kwargs.get(k) is not None:
            extra[k] = kwargs[k]
    rp = kwargs.get("reply_parameters")
    if rp is not None:
        extra["reply_parameters"] = rp.to_dict() if hasattr(rp, "to_dict") else rp
    elif kwargs.get("reply_to_message_id"):
        extra["reply_parameters"] = {"message_id": kwargs["reply_to_message_id"],
                                     "allow_sending_without_reply": True}

    async def _go():
        if upload is None:
            payload = {"chat_id": chat_id, "rich_message": rich, **extra}
            if url_kb:
                payload["reply_markup"] = url_kb.to_dict()
            return await _rc_call(bot, "sendRichMessage", payload)
        fields = {"chat_id": str(chat_id), "rich_message": json.dumps(rich)}
        for k, v in extra.items():
            fields[k] = json.dumps(v) if isinstance(v, (dict, list, bool)) else str(v)
        if url_kb:
            fields["reply_markup"] = json.dumps(url_kb.to_dict())
        return await asyncio.to_thread(_rcm_post_multipart, "sendRichMessage", fields, upload)

    try:
        if upload is not None and ckey:
            async with _lock_for("rich:" + ckey):     # one upload per file, others reuse its file_id
                cached = _RCM_IDS.get(ckey)
                if cached:
                    rich["media"] = [_rcm_item(kind, cached)]
                    upload = None
                res = await _go()
        else:
            res = await _go()
    except Exception as e:
        _rcm_failed(kind, e)
        return None

    _RCM_FAILS[kind] = 0
    try:
        if isinstance(res, dict):
            msg = _telegram_module.Message.de_json(res, bot)
            mid = res["message_id"]
            real_chat = (res.get("chat") or {}).get("id", chat_id)
            found = _rcm_find(res.get("rich_message", res))
        else:
            msg, mid, real_chat, found = res, res.message_id, res.chat_id, None
        fid = found[1] if found else None
        if fid and ckey and ckey not in _RCM_IDS:
            _RCM_IDS[ckey] = fid
        if isinstance(src, str) and not fid:
            fid = None if src.startswith("http") else src
        elif not fid and ckey:
            fid = _RCM_IDS.get(ckey)
        ent = {"kind": (found[0] if found else kind), "file_id": fid, "thread": kwargs.get("message_thread_id")}
        for cid in {chat_id, real_chat}:
            _rcm_remember(cid, mid, ent)
            _rc_remember(cid, mid, html_body, rows)
        return msg
    except Exception:
        logger.exception("rich media send: could not build Message from result")
        return None


def _rcm_wrap_send(kind: str, orig):
    async def _w(self, *args, **kwargs):
        kwargs = dict(kwargs)
        if kwargs.get("reply_markup") is not None:
            kwargs["reply_markup"] = rc_norm_markup(kwargs["reply_markup"])
        try:
            msg = await _rcm_try_send(self, kind, args, kwargs)
        except Exception:
            logger.exception(f"rich {kind} crashed — normal send")
            msg = None
        if msg is not None:
            return msg
        args, kwargs = _rc_style_kwargs(args, kwargs, None, "caption")
        return await orig(self, *args, **kwargs)
    return _w


async def _rcm_resend(bot, ent, chat_id, old_mid, caption, markup):
    """Last resort for a media card that can't be edited in place: send a fresh one, delete the old."""
    src = ent.get("file_id")
    if not src:
        return None
    sender = getattr(bot, "send_" + ent["kind"])
    kw = dict(caption=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    if ent.get("thread"):
        kw["message_thread_id"] = ent["thread"]
    new = await sender(chat_id, src, **kw)
    try:
        await bot.delete_message(chat_id, old_mid)
    except Exception:
        pass
    return new


async def _newlook_edit_message_caption(self, *args, **kwargs):
    kwargs = dict(kwargs)
    chat_id = _rc_arg(args, kwargs, 0, "chat_id")
    message_id = _rc_arg(args, kwargs, 1, "message_id")
    ent = _RC_MEDIA.get((chat_id, message_id)) if chat_id is not None and message_id is not None else None
    if ent is not None and not kwargs.get("inline_message_id"):
        caption = _rc_arg(args, kwargs, 3, "caption")
        if kwargs.get("reply_markup") is not None:
            kwargs["reply_markup"] = rc_norm_markup(kwargs["reply_markup"])
        rows = _rcm_rows(kwargs.get("reply_markup"))
        if isinstance(caption, str) and rows is not None and kwargs.get("parse_mode") == ParseMode.HTML \
                and "tg://user" not in caption:
            html_body = _rcm_hero(ent["kind"]) + _rc_body_with_buttons(rc_html_to_rich(rc_restyle(caption)), rows)
            media = _rcm_media_for(ent)
            if media:
                payload = {"chat_id": chat_id, "message_id": message_id,
                           "rich_message": {"html": html_body, "media": media}}
                url_kb = _rc_markup(rows, urls_only=True)
                if url_kb:
                    payload["reply_markup"] = url_kb.to_dict()
                try:
                    await _rc_call(self, "editMessageText", payload)
                    _rc_remember(chat_id, message_id, html_body, rows)
                    return True
                except Exception as e:
                    if "not modified" in str(e).lower():
                        return True
                    logger.info(f"rich caption edit failed ({str(e)[:90]}) → delete + resend")
            try:
                new = await _rcm_resend(self, ent, chat_id, message_id, rc_restyle(caption),
                                        kwargs.get("reply_markup"))
                if new is not None:
                    return new
            except Exception:
                logger.exception("rich caption resend failed")
    args, kwargs = _rc_style_kwargs(args, kwargs, None, "caption")
    return await _premium_edit_message_caption(self, *args, **kwargs)


_orig_edit_message_media = _telegram_module.Bot.edit_message_media


async def _newlook_edit_message_media(self, *args, **kwargs):
    """Media swap on a rich media card — send the new media as a fresh rich card, delete the old."""
    chat_id = _rc_arg(args, kwargs, 1, "chat_id")
    message_id = _rc_arg(args, kwargs, 2, "message_id")
    ent = _RC_MEDIA.get((chat_id, message_id)) if chat_id is not None and message_id is not None else None
    if ent is not None and not kwargs.get("inline_message_id"):
        media = _rc_arg(args, kwargs, 0, "media")
        mtype = getattr(media, "type", None)
        mtype = getattr(mtype, "value", mtype)
        if mtype in ("photo", "animation", "video"):
            try:
                sender = getattr(self, "send_" + mtype)
                kw = {"caption": getattr(media, "caption", None) or None,
                      "parse_mode": getattr(media, "parse_mode", None) or ParseMode.HTML,
                      "reply_markup": kwargs.get("reply_markup")}
                if ent.get("thread"):
                    kw["message_thread_id"] = ent["thread"]
                new = await sender(chat_id, getattr(media, "media", None), **kw)
                try:
                    await self.delete_message(chat_id, message_id)
                except Exception:
                    pass
                return new
            except Exception:
                logger.exception("rich media swap failed — trying plain edit")
    return await _orig_edit_message_media(self, *args, **kwargs)


# install hooks on Bot and ExtBot (PTB runs the Application on ExtBot)
for _cls in (_telegram_module.Bot, _telegram_module.ext.ExtBot):
    _cls.send_message = _newlook_send_message
    _cls.edit_message_text = _newlook_edit_message_text
    _cls.edit_message_caption = _newlook_edit_message_caption
    _cls.edit_message_reply_markup = _newlook_edit_message_reply_markup
    _cls.send_photo = _rcm_wrap_send("photo", _premium_send_photo)
    _cls.send_animation = _rcm_wrap_send("animation", _premium_send_animation)
    _cls.edit_message_media = _newlook_edit_message_media
    _cls.send_document = _newlook_wrap_media(_premium_send_document)
    _cls.send_video = _rcm_wrap_send("video", _premium_send_video)


async def send_new_scorecard(target_message, group_id: int, match: "Match"):
    """Tries native Telegram sendRichMessage with <table bordered striped> first.
    If supported by Bot API 10.1+, sends native RichBlockTable.
    If unsupported/error, falls back to <pre> code-block grid table as ONE message."""
    try:
        html_content = build_new_scorecard_html(match, group_id)
        ok = await _tg_send_rich_message(group_id, html_content)
        if ok:
            return
    except Exception as e:
        logger.warning(f"Rich message attempt error: {e}")

    text, _ = build_new_scorecard(match, group_id)
    if len(text) > 4096:
        await target_message.reply_text(text[:4090] + "…", parse_mode=ParseMode.HTML)
        await target_message.reply_text("…" + text[4090:], parse_mode=ParseMode.HTML)
    else:
        await target_message.reply_text(text, parse_mode=ParseMode.HTML)


async def send_final_scorecard(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    📊 PREMIUM MATCH SCORECARD - Professional Design

    The old separate "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈ RESULT —" ASCII block + duplicate innings tables
    have been removed. Winner / margin / top scorer / best bowler / MOTM /
    time taken now live INSIDE the emoji scorecard table itself (see
    _nsc_compute_result + build_new_scorecard_html). The photo caption below
    is just a short result summary, not a duplicate scorecard.
    """

    first_innings = match.batting_first
    second_innings = match.get_other_team(first_innings)

    result = _nsc_compute_result(match)

    # Keep this match reachable for the new-style scorecard's drop-down
    # buttons even after active_matches[group_id] is cleaned up.
    FINISHED_MATCH_CACHE[group_id] = match
    try:
        html_nsc = build_new_scorecard_html(match, group_id, result=result)
        ok = await _tg_send_rich_message(group_id, html_nsc, reply_markup=verse_zone_markup())
        if not ok:
            text_nsc, _ = build_new_scorecard(match, group_id, result=result)
            if len(text_nsc) > 4096:
                await context.bot.send_message(group_id, text_nsc[:4090] + "…", parse_mode=ParseMode.HTML)
                await context.bot.send_message(group_id, "…" + text_nsc[4090:], parse_mode=ParseMode.HTML, reply_markup=verse_zone_markup())
            else:
                await context.bot.send_message(group_id, text_nsc, parse_mode=ParseMode.HTML, reply_markup=verse_zone_markup())
    except Exception as nsc_end_e:
        logger.error(f"New-style scorecard (end of game) error: {nsc_end_e}")

    # Short RESULT-only caption for the worm-graph / fallback photo — the
    # full batting/bowling tables already went out in the rich message above.
    # 🎨 Rebuilt to use the bot's normal `themed()` quote-box style (same as
    # every other in-match alert) instead of a monospace <pre> "Award/Player"
    # grid — matches the rest of the bot's theme and lets Telegram render it
    # as plain text, no code-block/copy-icon clutter. Fantasy Points for this
    # match are now folded in here too, right under the result highlights.
    _RD = "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
    award_lines = []
    if result.get("motm"):
        award_lines.append(f"⭐️ Player of the Match: {html.escape(str(result['motm']))}")
    if result.get("top_scorer"):
        award_lines.append(f"⭐️ Top Scorer: {html.escape(str(result['top_scorer']))}")
    if result.get("best_bowler"):
        award_lines.append(f"🎯 Best Bowler: {html.escape(str(result['best_bowler']))}")

    msg = f"<b>{html.escape(result['winner'])} won by {result['margin']}</b>\n{_RD}"
    if award_lines:
        msg += "\n" + "\n".join(award_lines)
    if result.get("time_taken"):
        msg += f"\n\n⏱️ Time Taken: {result['time_taken']}"

    # ── 🏆 Fantasy Points (top 10 managers of THIS match) ──
    squads = getattr(match, "fantasy_squads", None) or {}
    fantasy_results = sorted(
        (
            (squad.get("name", "Player"), squad.get("match_points", 0))
            for squad in squads.values() if squad.get("players")
        ),
        key=lambda r: r[1], reverse=True
    )
    if fantasy_results:
        msg += f"\n\n🎮 <b>Dream III Points</b>\n{_RD}"
        medals = ["🥇", "🥈", "🥉"]
        for i, (name, pts) in enumerate(fantasy_results[:10]):
            medal = medals[i] if i < 3 else f"{i + 1}."
            msg += f"\n{medal} {html.escape(str(name))} — {pts} pts"

    # ── Rematch button (moved here from the removed old victory message) ──
    rematch_data = f"rematch_{group_id}_{match.total_overs}_{match.game_mode or 'TEAM'}"
    keyboard = InlineKeyboardMarkup([
        [
            styled_button("2nd Innings", callback_data=f"scorecard_worm_{group_id}_2"),
            styled_button("Rematch!", callback_data=rematch_data)
        ],
        [styled_button("🛝 Playground", url=VERSE_ZONE_URL, small_caps=False)],
    ])

    # Bug 4 Fix: Use worm graph as the OFFICIAL MATCH SCORECARD image instead of static photo
    # Remove separate worm graph message → worm is embedded in the scorecard
    try:
        worm_bio = await asyncio.to_thread(generate_worm_graph, match)
        if worm_bio:
            first_innings = match.batting_first
            await context.bot.send_photo(
                group_id,
                photo=worm_bio,
                caption=msg,
                parse_mode=ParseMode.HTML,
                reply_markup=keyboard
            )
        else:
            raise Exception("Worm graph returned None")
    except Exception as worm_e:
        logger.warning(f"Worm graph for scorecard failed, using fallback: {worm_e}")
        try:
            await context.bot.send_photo(
                group_id,
                photo=MEDIA_ASSETS.get("scorecard"),
                caption=msg,
                parse_mode=ParseMode.HTML,
                reply_markup=keyboard
            )
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 15457)")
            await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML, reply_markup=keyboard)


