# ───────────────────
async def generate_players_squad_image(match, context=None) -> Optional[BytesIO]:
    """
    ✅ TEMPLATE-BASED players/squad card.
    Uses players_template.jpg (1024x639) as background.
    Pastes:
      - Captain X pfp in the LEFT big circle
      - Captain Y pfp in the RIGHT big circle
      - Host pfp in the SMALL CENTER circle (above VS)
    """
    try:
        import os
        from PIL import Image, ImageDraw, ImageFont, ImageOps
        from io import BytesIO

        # 🔧 FIX: relative "players_template.png" only resolved if the bot's
        # CURRENT WORKING DIRECTORY happened to match cric.py's folder (e.g.
        # if run via systemd/cron/a different launch dir, this silently failed
        # and /players fell back to text-only, no photo). Now also checks the
        # SCRIPT'S OWN directory explicitly, which is where the user keeps it.
        _script_dir = os.path.dirname(os.path.abspath(__file__))
        TEMPLATE_CANDIDATES = [
            "players_template.png",
            "players_template.jpg",
            os.path.join(_script_dir, "players_template.png"),
            os.path.join(_script_dir, "players_template.jpg"),
            "/home/cricoverse/players_template.png",
            "/home/cricoverse/players_template.jpg",
        ]
        TEMPLATE_PATH = next((p for p in TEMPLATE_CANDIDATES if os.path.exists(p)), None)
        if TEMPLATE_PATH is None:
            logger.error(
                f"generate_players_squad_image: template file not found. "
                f"Checked: {TEMPLATE_CANDIDATES}. Make sure players_template.png "
                f"is placed in the same folder as cric.py ({_script_dir})."
            )
            return None

        base = Image.open(TEMPLATE_PATH).convert("RGBA")
        W, H = base.size  # native template size (auto-detected, no hardcoded assumption)
        overlay = Image.new("RGBA", (W, H), (0, 0, 0, 0))

        # ── Fetch pfp bytes ──
        async def get_pfp(uid):
            if context is None or uid is None:
                return None
            try:
                return await fetch_user_avatar_bytes(context, uid)
            except Exception:
                return None

        cap_x_id  = match.team_x.captain_id if hasattr(match.team_x, "captain_id") else None
        cap_y_id  = match.team_y.captain_id if hasattr(match.team_y, "captain_id") else None
        host_id   = getattr(match, "host_id", None)

        cap_x_bytes  = await get_pfp(cap_x_id)
        cap_y_bytes  = await get_pfp(cap_y_id)
        host_bytes   = await get_pfp(host_id)

        # ── Heavy PIL compositing runs in a worker thread so it never blocks ──
        # ── the event loop (and therefore never delays live gameplay). ──
        def _render_squad_image(base_img, overlay_img, cap_x_bytes, cap_y_bytes, host_bytes,
                                 team_x_name, team_y_name, host_name):
            def paste_circle(img_overlay, avatar_bytes, cx, cy, r, initials="?"):
                size = r * 2
                pfp = Image.new("RGBA", (size, size), (50, 50, 50, 200))
                if avatar_bytes:
                    try:
                        src = Image.open(BytesIO(avatar_bytes)).convert("RGBA")
                        src = ImageOps.fit(src, (size, size), method=Image.Resampling.LANCZOS)
                        pfp = src
                    except Exception:
                        pass
                else:
                    d = ImageDraw.Draw(pfp)
                    d.ellipse([0, 0, size-1, size-1], fill=(30, 60, 120, 255))
                    try:
                        fi = ImageFont.truetype("Roboto-Bold.ttf", size // 3)
                    except Exception:
                        fi = ImageFont.load_default(size=size // 3)
                    ib = d.textbbox((0, 0), initials[:2], font=fi)
                    d.text(((size-(ib[2]-ib[0]))//2, (size-(ib[3]-ib[1]))//2), initials[:2],
                           font=fi, fill=(255, 255, 255, 255))

                mask = Image.new("L", (size, size), 0)
                ImageDraw.Draw(mask).ellipse((0, 0, size-1, size-1), fill=255)
                circle = Image.new("RGBA", (size, size), (0, 0, 0, 0))
                circle.paste(pfp, (0, 0), mask)
                img_overlay.alpha_composite(circle, (cx - r, cy - r))

            # Template layout (native 1774 x 887) — pixel-calibrated via color-mask detection:
            # LEFT  circle (Team X cap) : cx=472,  cy=554, inner_r=145
            # RIGHT circle (Team Y cap) : cx=1291, cy=554, inner_r=145
            # CENTER small (Host)       : cx=886,  cy=290, inner_r=85
            paste_circle(overlay_img, cap_x_bytes,  472, 554, 145,
                         initials=(team_x_name or "X")[:2].upper())
            paste_circle(overlay_img, cap_y_bytes,  1291, 554, 145,
                         initials=(team_y_name or "Y")[:2].upper())
            paste_circle(overlay_img, host_bytes,   886, 290,  85,
                         initials=(host_name or "H")[:2].upper())

            # NOTE: This template has baked-in static labels ("TEAM X" / "TEAM Y" / "HOST")
            # as part of the background art, so we don't draw duplicate text on top —
            # only the profile pictures are pasted into the circles above.

            final = Image.alpha_composite(base_img, overlay_img).convert("RGB")
            bio = BytesIO()
            final.save(bio, "JPEG", quality=92)
            bio.seek(0)
            return bio

        bio = await asyncio.to_thread(
            _render_squad_image,
            base, overlay, cap_x_bytes, cap_y_bytes, host_bytes,
            match.team_x.name, match.team_y.name, getattr(match, "host_name", "H")
        )
        return bio

    except Exception as e:
        logger.error(f"generate_players_squad_image error: {e}")
        return None




