def _build_mid_match_caption(match) -> str:
    """Build caption text for mid-match live score image."""
    bat_team  = match.current_batting_team
    bowl_team = match.current_bowling_team
    if not bat_team or not bowl_team:
        return "🔴 <b>LIVE</b>"
    caption = (
        f"🔴 <b>LIVE SCORE</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🏏 <b>{bat_team.name}:</b>  {bat_team.score}/{bat_team.wickets}  ({format_overs(bat_team.balls)} ov)\n"
    )
    if match.innings == 2 and match.target > 0:
        needed = match.target - bat_team.score
        bl = (match.total_overs * 6) - bat_team.balls
        rrr = round(needed / max(bl / 6, 0.1), 2)
        caption += f"🎯 Need <b>{needed}</b> off <b>{bl}b</b>  RRR: {rrr}\n"
    # Current bowler
    if bowl_team.current_bowler_idx is not None and bowl_team.current_bowler_idx < len(bowl_team.players):
        bowler = bowl_team.players[bowl_team.current_bowler_idx]
        caption += f"⚡ <b>Current Bowler:</b> {bowler.first_name}  {bowler.wickets}/{bowler.runs_conceded}  ({format_overs(bowler.balls_bowled)})\n"
    # Current batsmen
    striker = bat_team.players[bat_team.current_batsman_idx] if bat_team.current_batsman_idx is not None else None
    nonstriker = bat_team.players[bat_team.current_non_striker_idx] if bat_team.current_non_striker_idx is not None else None
    if striker:
        sr_s = round((striker.runs / max(striker.balls_faced, 1)) * 100, 1)
        caption += f"🏏 <b>{striker.first_name}:</b> {striker.runs} ({striker.balls_faced})  SR: {sr_s}\n"
    if nonstriker:
        sr_n = round((nonstriker.runs / max(nonstriker.balls_faced, 1)) * 100, 1)
        caption += f"🔄 <b>{nonstriker.first_name}:</b> {nonstriker.runs} ({nonstriker.balls_faced})  SR: {sr_n}\n"
    if match.current_partnership_runs > 0:
        caption += f"🤝 <b>Partnership:</b> {match.current_partnership_runs} runs off {match.current_partnership_balls} balls"
    return caption




def _draw_text_centered(draw, text, cx, y, font, fill):
    bbox = draw.textbbox((0, 0), text, font=font)
    w = bbox[2] - bbox[0]
    draw.text((cx - w // 2, y), text, font=font, fill=fill)


def _draw_gradient_rect(img_draw_tuple, x1, y1, x2, y2, color_top, color_bot):
    """Vertical gradient fill on a rectangle."""
    img, draw = img_draw_tuple
    h = y2 - y1
    if h <= 0:
        return
    for i in range(h):
        t = i / h
        r = int(color_top[0] + t * (color_bot[0] - color_top[0]))
        g = int(color_top[1] + t * (color_bot[1] - color_top[1]))
        b = int(color_top[2] + t * (color_bot[2] - color_top[2]))
        draw.line([(x1, y1 + i), (x2, y1 + i)], fill=(r, g, b))


# 🎞️ GIF shown while a player card / dashboard image is being generated,
# instead of the old "Building your player card..." text message.
# Drop the file in the same folder as the jersey templates and set the name here.
CARD_GENERATION_GIF_FILENAME = "loading.gif"


def _resolve_asset_path(filename: str) -> Optional[str]:
    """Look for an asset next to the jersey templates: current working dir first,
    then the /home/cricoverse/ deployment fallback used elsewhere in this file."""
    if os.path.exists(filename):
        return filename
    fallback = f"/home/cricoverse/{filename}"
    if os.path.exists(fallback):
        return fallback
    return None


async def send_photo_generation_status(update: Update, title: str = "", detail: str = ""):
    """Small progress indicator shown while heavier PIL cards are being generated.
    Now sends a looping GIF instead of a text status message. title/detail are kept
    as no-op params so existing call sites don't need to change."""
    try:
        if update.effective_chat:
            await update.effective_chat.send_action("upload_photo")
        gif_path = _resolve_asset_path(CARD_GENERATION_GIF_FILENAME)
        if not gif_path:
            return None
        return await update.message.reply_animation(animation=Path(gif_path))
    except Exception:
        return None


async def fetch_user_avatar_bytes(context: ContextTypes.DEFAULT_TYPE, user_id: int) -> Optional[bytes]:
    """Fetch the user's largest Telegram profile photo, if available."""
    try:
        photos = await context.bot.get_user_profile_photos(user_id=user_id, limit=1)
        if not photos.total_count or not photos.photos:
            return None
        file_id = photos.photos[0][-1].file_id
        tg_file = await context.bot.get_file(file_id)
        data = await tg_file.download_as_bytearray()
        return bytes(data)
    except Exception as e:
        logger.info(f"Could not fetch profile photo for {user_id}: {e}")
        return None


def _circle_avatar(avatar_bytes: Optional[bytes], size: int, initials: str = "CV") -> Image.Image:
    """Return a circular RGBA avatar; falls back to initials."""
    avatar = Image.new("RGBA", (size, size), (24, 31, 58, 255))
    draw = ImageDraw.Draw(avatar)
    if avatar_bytes:
        try:
            src = Image.open(BytesIO(avatar_bytes)).convert("RGBA")
            src = ImageOps.fit(src, (size, size), method=Image.Resampling.LANCZOS)
            avatar = src
        except Exception:
            avatar = Image.new("RGBA", (size, size), (24, 31, 58, 255))
            draw = ImageDraw.Draw(avatar)

    if not avatar_bytes:
        for y in range(size):
            t = y / max(size - 1, 1)
            color = (
                int(32 + 28 * t),
                int(45 + 35 * t),
                int(90 + 45 * t),
                255,
            )
            draw.line([(0, y), (size, y)], fill=color)
        text = (initials or "CV")[:2].upper()
        font = _get_font(True, max(22, size // 4))
        bbox = draw.textbbox((0, 0), text, font=font)
        draw.text(((size - (bbox[2] - bbox[0])) / 2, (size - (bbox[3] - bbox[1])) / 2 - size * 0.04), text, font=font, fill=(245, 249, 255, 255))

    mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, size - 1, size - 1), fill=255)
    out = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    out.paste(avatar, (0, 0), mask)
    ring = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    rdraw = ImageDraw.Draw(ring)
    rdraw.ellipse((3, 3, size - 4, size - 4), outline=(255, 211, 80, 255), width=max(4, size // 28))
    out.alpha_composite(ring)
    return out


# ───────────────────
#  🌟 PLAYER OF THE MATCH CARD (replaces the old newspaper-headline image)
#  Just the MOTM's Telegram profile photo, centred in a gold circle,
#  with "PLAYER OF THE MATCH" + their name printed below it.
# ───────────────────
async def generate_potm_avatar_card(
    context: ContextTypes.DEFAULT_TYPE,
    user_id: Optional[int],
    display_name: str,
) -> Optional[BytesIO]:
    """Simple, clean post-match card: winner's/MOTM's DP in a circle with
    'Player of the Match' + their name below it — no more newspaper mockup.
    Square, light cream/gold theme so the player's photo/logo really pops."""
    try:
        W = H = 1000
        card = Image.new("RGBA", (W, H), (255, 255, 255, 255))
        draw = ImageDraw.Draw(card)

        # Light, soft theme background — subtle cream → pale-gold gradient.
        top_c = (255, 252, 245)
        bot_c = (247, 236, 210)
        for y in range(H):
            t = y / max(H - 1, 1)
            color = tuple(int(top_c[i] + (bot_c[i] - top_c[i]) * t) for i in range(3))
            draw.line([(0, y), (W, y)], fill=color)

        circle_size = 520
        top = 150
        cx = W // 2

        # Soft drop shadow behind the avatar circle (own transparent layer,
        # composited once, so it never smears/ghosts onto the photo itself).
        shadow_layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
        sdraw = ImageDraw.Draw(shadow_layer)
        sdraw.ellipse(
            (cx - circle_size // 2, top + 18, cx + circle_size // 2, top + circle_size + 18),
            fill=(20, 20, 20, 80),
        )
        shadow_layer = shadow_layer.filter(ImageFilter.GaussianBlur(20))
        card.alpha_composite(shadow_layer)
        draw = ImageDraw.Draw(card)

        # Rounded gold border frame around the whole card.
        border_margin = 26
        draw.rounded_rectangle(
            (border_margin, border_margin, W - border_margin, H - border_margin),
            radius=36, outline=(214, 168, 46), width=6,
        )

        avatar_bytes = None
        if user_id:
            try:
                avatar_bytes = await fetch_user_avatar_bytes(context, user_id)
            except Exception as e:
                logger.info(f"POTM avatar fetch failed for {user_id}: {e}")

        avatar = _circle_avatar(avatar_bytes, circle_size, initials=display_name)
        card.alpha_composite(avatar, (cx - circle_size // 2, top))

        label_font = _get_font(True, 42)
        label_text = "★ PLAYER OF THE MATCH ★"
        bbox = draw.textbbox((0, 0), label_text, font=label_font)
        draw.text(
            ((W - (bbox[2] - bbox[0])) / 2, top + circle_size + 55),
            label_text, font=label_font, fill=(184, 134, 11),
        )

        name_font = _get_font(True, 62)
        name_text = display_name or "Unknown"
        bbox = draw.textbbox((0, 0), name_text, font=name_font)
        if bbox[2] - bbox[0] > W - 100:
            name_font = _get_font(True, 46)
            bbox = draw.textbbox((0, 0), name_text, font=name_font)
        draw.text(
            ((W - (bbox[2] - bbox[0])) / 2, top + circle_size + 120),
            name_text, font=name_font, fill=(35, 35, 45),
        )

        bio = BytesIO()
        card.convert("RGB").save(bio, format="PNG")
        bio.seek(0)
        return bio
    except Exception as e:
        logger.error(f"generate_potm_avatar_card error: {e}")
        return None


# ───────────────────
#  🤝 PARTNERSHIP MILESTONE IMAGE (50 / 100)
#  Pastes both batsmen's Telegram profile photos into the two blank
#  circles on the "partnership_50" / "partnership_100" template.
# ───────────────────
async def generate_partnership_image(
    context: ContextTypes.DEFAULT_TYPE,
    player_left,
    player_right,
    milestone: int,
) -> Optional[BytesIO]:
    """Builds the partnership-milestone banner with both batsmen's DPs
    dropped into the two circular frames. milestone must be 50 or 100."""
    asset_key = "partnership_50" if milestone == 50 else "partnership_100"
    template_path = MEDIA_ASSETS.get(asset_key)
    if not template_path:
        logger.warning(f"⚠️ Missing template for {asset_key}, skipping partnership image")
        return None

    circles = PARTNERSHIP_TEMPLATE_CIRCLES.get(asset_key)
    if not circles:
        return None

    try:
        base = await asyncio.to_thread(lambda: Image.open(template_path).convert("RGBA"))

        left_avatar_bytes = await fetch_user_avatar_bytes(context, player_left.user_id)
        right_avatar_bytes = await fetch_user_avatar_bytes(context, player_right.user_id)

        def _compose():
            img = base.copy()
            for side, player, avatar_bytes in (
                ("left", player_left, left_avatar_bytes),
                ("right", player_right, right_avatar_bytes),
            ):
                cx, cy, r = circles[side]
                initials = "".join([w[0] for w in (player.first_name or "CV").split()[:2]]).upper() or "CV"
                size = r * 2
                avatar = _circle_avatar(avatar_bytes, size, initials)
                img.alpha_composite(avatar, (cx - r, cy - r))
            buf = BytesIO()
            img.convert("RGB").save(buf, format="JPEG", quality=92)
            buf.seek(0)
            return buf

        return await asyncio.to_thread(_compose)
    except Exception as e:
        logger.error(f"generate_partnership_image error: {e}")
        return None


async def check_and_celebrate_partnership(
    context: ContextTypes.DEFAULT_TYPE,
    chat_id: int,
    match: "Match",
) -> bool:
    """
    🤝 AUTO PARTNERSHIP MILESTONE DETECTOR — fires once per partnership when
    it crosses 50 and again when it crosses 100 (reset whenever a wicket
    falls and a new partnership begins).

    Returns True if a milestone image was sent (caller can pause the game
    for a few seconds afterward, same as the batting/bowling milestones).
    """
    bat_team = match.current_batting_team
    if not bat_team or bat_team.current_batsman_idx is None or bat_team.current_non_striker_idx is None:
        return False

    if not hasattr(match, "partnership_milestones_celebrated"):
        match.partnership_milestones_celebrated = set()

    runs = match.current_partnership_runs
    milestone = None
    if runs >= 100 and 100 not in match.partnership_milestones_celebrated:
        milestone = 100
    elif runs >= 50 and 50 not in match.partnership_milestones_celebrated:
        milestone = 50

    if milestone is None:
        return False

    match.partnership_milestones_celebrated.add(milestone)

    striker = bat_team.players[bat_team.current_batsman_idx]
    non_striker = bat_team.players[bat_team.current_non_striker_idx]

    caption = (
        f"🤝 <b>{milestone}-RUN PARTNERSHIP</b>\n\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"{html.escape(striker.first_name)} & {html.escape(non_striker.first_name)}\n"
        f"Partnership: <b>{match.current_partnership_runs}</b> runs off {match.current_partnership_balls} balls"
    )

    try:
        img = await generate_partnership_image(context, striker, non_striker, milestone)
        if img:
            await context.bot.send_photo(chat_id=chat_id, photo=img, caption=caption, parse_mode=ParseMode.HTML)
        else:
            await context.bot.send_message(chat_id=chat_id, text=caption, parse_mode=ParseMode.HTML)
        logger.info(f"🤝 Partnership milestone: {striker.first_name} & {non_striker.first_name} reached {milestone}!")
    except Exception as e:
        logger.error(f"check_and_celebrate_partnership send error: {e}")

    return True


def _clean_display_name(name: str, max_len: int = 15) -> str:
    """Helper to keep player names from breaking the layout."""
    clean = name.strip()
    return clean[:max_len] + "..." if len(clean) > max_len else clean

def _create_avatar_image(avatar_bytes: bytes, size: int, initials: str) -> Image.Image:
    """Helper to process the DP into a perfect circle, or fallback to initials."""
    result = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    mask = Image.new("L", (size, size), 0)
    draw_mask = ImageDraw.Draw(mask)
    draw_mask.ellipse((0, 0, size, size), fill=255)
    
    if avatar_bytes:
        try:
            av = Image.open(BytesIO(avatar_bytes)).convert("RGBA")
            # Crop to square first to avoid stretching
            w, h = av.size
            min_side = min(w, h)
            left = (w - min_side) / 2
            top = (h - min_side) / 2
            av = av.crop((left, top, left + min_side, top + min_side))
            av = av.resize((size, size), Image.Resampling.LANCZOS)
            result.paste(av, (0, 0), mask=mask)
            return result
        except Exception as e:
            pass
            
    # Fallback if no DP: Dark circle with neon initials
    draw_fallback = ImageDraw.Draw(result)
    draw_fallback.ellipse((0, 0, size, size), fill=(20, 30, 50, 255))
    try:
        font = ImageFont.truetype("Roboto-Bold.ttf", int(size * 0.4))
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 16289)")
        font = ImageFont.load_default(size=int(size * 0.4))
    
    # Center text
    bbox = draw_fallback.textbbox((0, 0), initials, font=font)
    tw = bbox[2] - bbox[0]
    th = bbox[3] - bbox[1]
    draw_fallback.text(((size - tw) / 2, (size - th) / 2 - (size * 0.05)), initials, font=font, fill=(0, 229, 255, 255))
    result.putalpha(mask)
    return result

async def fetch_overall_stats_snapshot(user_id: int, name: str, stats: dict, avatar_bytes: bytes = None, mode: str = "overall") -> BytesIO:
    """
    ULTIMATE GOD-LEVEL CRICKET CARD
    Features: Deep night theme, stadium neon glows, player DP, frosted glass panels.
    """
    try:
        SC = 2  # Super-sampling scale for high resolution
        W, H = 1200 * SC, 740 * SC
        img = Image.new("RGBA", (W, H), (8, 12, 24, 255)) # Deepest Night Blue
        draw = ImageDraw.Draw(img, "RGBA")

        # ── 1. STADIUM FLOODLIGHT GLOWS (Background Effects) ──
        glow_layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
        glow_draw = ImageDraw.Draw(glow_layer)
        
        # Neon Cyan Glow (Top Left behind DP)
        glow_draw.ellipse((-300*SC, -300*SC, 600*SC, 600*SC), fill=(0, 229, 255, 30))
        # Neon Green/Purple Glow (Bottom Right)
        glow_draw.ellipse((W - 500*SC, H - 400*SC, W + 300*SC, H + 400*SC), fill=(57, 255, 20, 20))
        
        glow_layer = glow_layer.filter(ImageFilter.GaussianBlur(150))
        img.paste(glow_layer, (0, 0), glow_layer)

        # ── COLORS & FONTS ──
        WHITE = (255, 255, 255, 255)
        MUTED = (148, 163, 184, 255)
        CYAN  = (0, 229, 255, 255)
        GREEN = (57, 255, 20, 255)
        RED   = (255, 60, 90, 255)
        GLASS_PANEL = (20, 30, 45, 180) 
        GLASS_OUTLINE = (0, 229, 255, 60)

        # Attempt to use local fonts, fallback to default
        try:
            f_title = ImageFont.truetype("Roboto-Bold.ttf", 62 * SC)
            f_label = ImageFont.truetype("Roboto-Regular.ttf", 20 * SC)
            f_value = ImageFont.truetype("Roboto-Bold.ttf", 44 * SC)
            f_small = ImageFont.truetype("Roboto-Regular.ttf", 22 * SC)
            f_mode  = ImageFont.truetype("Roboto-Bold.ttf", 26 * SC)
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 16339)")
            f_title = ImageFont.load_default(size=62 * SC)
            f_label = ImageFont.load_default(size=20 * SC)
            f_value = ImageFont.load_default(size=44 * SC)
            f_small = ImageFont.load_default(size=22 * SC)
            f_mode  = ImageFont.load_default(size=26 * SC)

        # ── 2. WATERMARK (Crossed Bats) ──
        def _draw_bats(cx, cy, size, alpha):
            w_color = (255, 255, 255, alpha)
            hw, bw = int(3 * SC), int(10 * SC)
            # Bat 1
            draw.line([(cx - size//2, cy - size//2), (cx - size//8, cy - size//8)], fill=w_color, width=hw)
            draw.line([(cx - size//8, cy - size//8), (cx + size//2, cy + size//2)], fill=w_color, width=bw)
            # Bat 2
            draw.line([(cx + size//2, cy - size//2), (cx + size//8, cy - size//8)], fill=w_color, width=hw)
            draw.line([(cx + size//8, cy - size//8), (cx - size//2, cy + size//2)], fill=w_color, width=bw)

        _draw_bats(W - 250*SC, 200*SC, 220*SC, 8)

        # ── 3. OUTER CARD FRAME ──
        draw.rounded_rectangle([30*SC, 30*SC, W-30*SC, H-30*SC], radius=30*SC, outline=GLASS_OUTLINE, width=2*SC)

        # ── 4. HEADER DETAILS ──
        header_txt = "🏏 CRICORA ULTIMATE  |  " + mode.upper() + " STATS"
        draw.text((60*SC, 50*SC), header_txt, font=f_mode, fill=CYAN)
        draw.line([(60*SC, 90*SC), (W-60*SC, 90*SC)], fill=(255, 255, 255, 30), width=1*SC)

        # ── 5. PLAYER DP (AVATAR) WITH NEON RING ──
        av_size = 200 * SC
        initials = "".join(part[:1] for part in (name or "P").split()[:2]).upper()
        avatar = _create_avatar_image(avatar_bytes, av_size, initials)
        
        av_x, av_y = 60 * SC, 130 * SC
        img.alpha_composite(avatar, (av_x, av_y))

        # Multiple Neon Glowing Rings around DP
        draw.ellipse([av_x-4*SC, av_y-4*SC, av_x+av_size+4*SC, av_y+av_size+4*SC], outline=CYAN, width=3*SC)
        draw.ellipse([av_x-12*SC, av_y-12*SC, av_x+av_size+12*SC, av_y+av_size+12*SC], outline=(0, 229, 255, 50), width=1*SC)

        # ── 6. PLAYER NAME & SUMMARY ──
        text_x = 310 * SC
        safe_name = _clean_display_name(name or "Player", 18).upper()
        draw.text((text_x, 140*SC), safe_name, font=f_title, fill=WHITE)
        draw.text((text_x, 220*SC), f"ID: {user_id}", font=f_small, fill=MUTED)

        # Win/Loss Pill
        matches = stats.get("matches", 0)
        wins    = stats.get("wins", 0)
        losses  = stats.get("losses", max(matches - wins, 0))
        win_rate = stats.get("win_rate", 0)
        
        draw.rounded_rectangle([text_x, 260*SC, text_x + 280*SC, 320*SC], radius=15*SC, fill=GLASS_PANEL, outline=GLASS_OUTLINE, width=1*SC)
        wl_color = GREEN if wins >= losses else RED
        draw.text((text_x + 20*SC, 275*SC), f"{wins}W - {losses}L", font=f_value, fill=wl_color)
        draw.text((text_x + 190*SC, 282*SC), f"{win_rate}%", font=f_small, fill=MUTED)

        # Form tracker
        form = stats.get("form", [])
        if form:
            fx = text_x + 310*SC
            draw.text((fx, 270*SC), "FORM:", font=f_label, fill=MUTED)
            fx += 80*SC
            for res in form[-5:]:
                fc = GREEN if res == "W" else RED
                draw.ellipse([fx, 275*SC, fx+16*SC, 291*SC], fill=fc)
                fx += 24*SC

        # ── 7. GLASS STATS GRID (4x2) ──
        # Extract variables safely
        runs = stats.get("runs", 0)
        hs = stats.get("highest", 0)
        avg = stats.get("average", 0)
        sr = stats.get("strike_rate", 0)
        wickets = stats.get("wickets", 0)
        fours = stats.get("fours", 0)
        sixes = stats.get("sixes", 0)
        mom = stats.get("mom", 0)

        stat_cards = [
            ("TOTAL MATCHES", str(matches), CYAN),
            ("TOTAL RUNS", str(runs), GREEN),
            ("HIGHEST SCORE", f"{hs}*", WHITE),
            ("STRIKE RATE", f"{sr}", CYAN),
            ("BATTING AVG", str(avg), WHITE),
            ("TOTAL WICKETS", str(wickets), GREEN),
            ("BOUNDARIES (4s/6s)", f"{fours} / {sixes}", WHITE),
            ("POTM AWARDS", str(mom), CYAN),
        ]

        grid_y = 390 * SC
        card_w, card_h = 250 * SC, 110 * SC
        gap_x, gap_y = 22 * SC, 22 * SC
        start_x = 60 * SC

        for i, (label, value, color) in enumerate(stat_cards):
            col = i % 4
            row = i // 4
            x1 = start_x + col * (card_w + gap_x)
            y1 = grid_y + row * (card_h + gap_y)
            
            # Draw Glass Tile
            draw.rounded_rectangle([x1, y1, x1+card_w, y1+card_h], radius=16*SC, fill=GLASS_PANEL, outline=(255,255,255,20), width=1*SC)
            
            # Left edge neon accent
            draw.rounded_rectangle([x1, y1, x1+6*SC, y1+card_h], radius=6*SC, fill=color)
            
            # Text layout inside tile
            draw.text((x1 + 24*SC, y1 + 18*SC), str(value), font=f_value, fill=WHITE)
            draw.text((x1 + 24*SC, y1 + 72*SC), label, font=f_label, fill=MUTED)

        # ── 8. FOOTER ──
        footer_y = H - 80*SC
        draw.line([(60*SC, footer_y), (W-60*SC, footer_y)], fill=(255, 255, 255, 30), width=1*SC)
        
        brand_txt = "⚡ POWERED BY CRICORA ENGINE"
        bb = draw.textbbox((0,0), brand_txt, font=f_small)
        draw.text(((W - (bb[2]-bb[0]))//2, footer_y + 20*SC), brand_txt, font=f_small, fill=CYAN)

        # ── 9. FINALIZE & EXPORT ──
        final = img.convert("RGB").resize((1200, 740), Image.Resampling.LANCZOS)
        bio = BytesIO()
        final.save(bio, "PNG", optimize=True)
        bio.seek(0)
        return bio
        
    except Exception as e:
        import logging
        logging.getLogger(__name__).error("God-Level Stats image generation error: " + str(e))
        return None

# ───────────────────
#  MOMENTUM IMAGE  (4K)
# ───────────────────
def _draw_rounded_rect(draw, xy, radius, fill=None, outline=None, width=1):
    """Draw a rectangle with rounded corners."""
    x1, y1, x2, y2 = xy
    r = radius
    if fill:
        draw.rectangle([x1+r, y1, x2-r, y2], fill=fill)
        draw.rectangle([x1, y1+r, x2, y2-r], fill=fill)
        draw.ellipse([x1, y1, x1+2*r, y1+2*r], fill=fill)
        draw.ellipse([x2-2*r, y1, x2, y1+2*r], fill=fill)
        draw.ellipse([x1, y2-2*r, x1+2*r, y2], fill=fill)
        draw.ellipse([x2-2*r, y2-2*r, x2, y2], fill=fill)
    if outline:
        draw.arc([x1, y1, x1+2*r, y1+2*r], 180, 270, fill=outline, width=width)
        draw.arc([x2-2*r, y1, x2, y1+2*r], 270, 360, fill=outline, width=width)
        draw.arc([x1, y2-2*r, x1+2*r, y2], 90, 180, fill=outline, width=width)
        draw.arc([x2-2*r, y2-2*r, x2, y2], 0, 90, fill=outline, width=width)
        draw.line([x1+r, y1, x2-r, y1], fill=outline, width=width)
        draw.line([x1+r, y2, x2-r, y2], fill=outline, width=width)
        draw.line([x1, y1+r, x1, y2-r], fill=outline, width=width)
        draw.line([x2, y1+r, x2, y2-r], fill=outline, width=width)


def _draw_rounded_rect_rgba(draw, xy, radius, fill=None, outline=None, width=1):
    """Draw a rounded rect on an RGBA ImageDraw (supports alpha fill tuples)."""
    _draw_rounded_rect(draw, xy, radius, fill=fill, outline=outline, width=width)


# ───────────────────
#  OVER-BY-OVER BAR CHART  (replaces static MINI_SCORECARD_PHOTO)
# ───────────────────
from PIL import Image, ImageDraw, ImageFilter
from io import BytesIO
from typing import Optional

def _draw_neo_bar(draw, x1, x2, runs, max_runs, chart_h, pad_t, color, wkts, font):
    """Draws a rounded, glowing bar with wicket indicators."""
    bh = max(int(runs / max_runs * chart_h), 10)
    y2 = pad_t + chart_h
    y1 = y2 - bh
    
    # 1. Soft Shadow
    draw.rectangle([x1+4, y1+4, x2+4, y2], fill=(0, 0, 0, 80))
    
    # 2. Main Bar Gradient (Glass effect)
    for i in range(bh):
        ratio = i / bh
        # Lighten the top, darken the bottom
        current_color = tuple(int(c * (0.4 + 0.6 * (1 - ratio))) for c in color)
        draw.line([(x1, y1 + i), (x2, y1 + i)], fill=current_color)
    
    # 3. Top Highlight Line
    draw.line([(x1, y1), (x2, y1)], fill=(255, 255, 255, 200), width=3)
    
    # 4. Run Label
    txt = str(runs)
    tw = draw.textbbox((0, 0), txt, font=font)[2]
    draw.text(((x1 + x2)//2 - tw//2, y1 - 50), txt, font=font, fill=(255, 255, 255))
    
    # 5. Wicket Glow (If any)
    if wkts > 0:
        rad = 18
        cx, cy = (x1 + x2) // 2, y1 - 85
        draw.ellipse([cx-rad, cy-rad, cx+rad, cy+rad], fill=(255, 50, 50))
        draw.text((cx-8, cy-12), str(wkts), font=font, fill=(255, 255, 255))

def _draw_glowing_text(draw, text, x, y, font, fill, glow_color=None, glow_radius=12):
    """Draw text with a soft glow effect."""
    if glow_color:
        for dx in range(-glow_radius, glow_radius+1, 4):
            for dy in range(-glow_radius, glow_radius+1, 4):
                alpha = max(0, 1 - (abs(dx)+abs(dy))/(glow_radius*2))
                gc = tuple(int(c * alpha * 0.6) for c in glow_color)
                if any(c > 0 for c in gc):
                    draw.text((x+dx, y+dy), text, font=font, fill=gc)
    draw.text((x, y), text, font=font, fill=fill)


def _draw_text_centered_glow(draw, text, cx, y, font, fill, glow_color=None):
    """Centered text with optional glow."""
    bbox = draw.textbbox((0, 0), text, font=font)
    w = bbox[2] - bbox[0]
    _draw_glowing_text(draw, text, cx - w//2, y, font, fill, glow_color, glow_radius=18)


def _draw_multi_gradient_bg(img, colors):
    """Draw a multi-stop vertical gradient background."""
    draw = ImageDraw.Draw(img)
    W, H = img.size
    n = len(colors) - 1
    seg_h = H // n
    for si in range(n):
        c1, c2 = colors[si], colors[si+1]
        sy = si * seg_h
        ey = (si+1) * seg_h if si < n-1 else H
        for i in range(ey - sy):
            t = i / max(ey - sy - 1, 1)
            r = int(c1[0] + t*(c2[0]-c1[0]))
            g = int(c1[1] + t*(c2[1]-c1[1]))
            b = int(c1[2] + t*(c2[2]-c1[2]))
            draw.line([(0, sy+i),(W, sy+i)], fill=(r,g,b))

def generate_leaderboard_image(title: str, rows: list, metric: str, offset: int = 0) -> Optional[BytesIO]:
    """🏆 Generate a readable leaderboard image (2x scaled for clarity)."""
    try:
        SC = 2
        ROW_H = 144
        TITLE_BAR = 160
        FOOTER_H = 72
        W = 1000 * SC
        H = min(TITLE_BAR + len(rows) * ROW_H + FOOTER_H, 900 * SC)
        img = Image.new("RGB", (W, H), (8, 10, 24))
        draw = ImageDraw.Draw(img)

        for y in range(H):
            t = y / H
            draw.line([(0, y), (W, y)], fill=(int(8 + t*12), int(10 + t*15), int(24 + t*20)))

        fn_title = _get_font(True, 84)
        fn_bold  = _get_font(True, 64)
        fn_reg   = _get_font(False, 56)
        fn_sm    = _get_font(False, 48)

        GOLD   = (255, 200, 50)
        SILVER = (192, 192, 210)
        BRONZE = (205, 127, 50)
        WHITE  = (230, 240, 255)
        GRAY   = (140, 160, 200)
        ACCENT = (80, 160, 255)

        draw.rectangle([(0, 0), (W, TITLE_BAR)], fill=(20, 25, 60))
        draw.rectangle([(0, TITLE_BAR - 8), (W, TITLE_BAR)], fill=GOLD)
        draw.text((48, 32), "🏆", font=fn_title, fill=GOLD)
        title_clean = title.replace("—", "-").replace("🏃", "").replace("⚾", "").replace("🏆", "").replace("🎯","").replace("🚀","").replace("🌟","").strip()
        draw.text((160, 40), title_clean, font=fn_bold, fill=WHITE)

        medals_colors = [GOLD, SILVER, BRONZE]

        y = TITLE_BAR
        for i, row in enumerate(rows):
            rank = offset + i + 1
            row_color = (18, 22, 48) if i % 2 == 0 else (22, 28, 58)
            draw.rectangle([(20, y), (W - 20, y + ROW_H - 4)], fill=row_color)

            # Rank badge
            if rank <= 3:
                draw.ellipse([(36, y + 16), (136, y + 116)], fill=medals_colors[rank - 1])
                draw.text((56 if rank < 10 else 44, y + 36), f"#{rank}", font=fn_bold, fill=(10, 10, 20))
            else:
                draw.ellipse([(36, y + 16), (136, y + 116)], fill=(40, 50, 90))
                txt = f"#{rank}"
                draw.text((44 if rank >= 10 else 56, y + 40), txt, font=fn_sm, fill=GRAY)

            # Name + stat
            # 🔧 FIX: _lb_query() rows are (user_id, first_name, username, ...) —
            # the username column was missing from every unpack below, which
            # made this function raise on every real leaderboard row (silently
            # caught -> returned None -> no photo ever sent). Also added the
            # missing 'fours' branch and a 'ccc' branch (dict rows, not tuples).
            if metric == "ccc":
                name = row.get("first_name") or "Player"
                rating = row.get("rating", 0)
                name_str = name[:22]
                draw.text((150, y + 20), name_str, font=fn_bold, fill=WHITE)
                draw.text((150, y + 76), f"⭐ {rating} rating", font=fn_sm, fill=ACCENT)
            elif metric == "runs":
                uid, name, uname, val1, val2 = row
                avg = round(val1 / max(val2, 1), 1)
                name_str = (name or "Player")[:22]
                draw.text((150, y + 20), name_str, font=fn_bold, fill=WHITE)
                draw.text((150, y + 76), f"{val1} runs  •  avg {avg}", font=fn_sm, fill=ACCENT)
            elif metric == "wickets":
                uid, name, uname, val, tbb, trc = row
                name_str = (name or "Player")[:22]
                draw.text((150, y + 20), name_str, font=fn_bold, fill=WHITE)
                draw.text((150, y + 76), f"{val} wickets", font=fn_sm, fill=ACCENT)
            elif metric == "fours":
                uid, name, uname, val, tr, tb = row
                name_str = (name or "Player")[:22]
                draw.text((150, y + 20), name_str, font=fn_bold, fill=WHITE)
                draw.text((150, y + 76), f"{val} fours", font=fn_sm, fill=ACCENT)
            elif metric == "wins":
                uid, name, uname, tw, tp = row
                name_str = (name or "Player")[:22]
                draw.text((150, y + 20), name_str, font=fn_bold, fill=WHITE)
                draw.text((150, y + 76), f"{tw} wins  /  {tp} played", font=fn_sm, fill=ACCENT)
            elif metric == "winrate":
                uid, name, uname, tw, tp = row
                wr = round(tw / max(tp, 1) * 100, 1)
                name_str = (name or "Player")[:22]
                draw.text((150, y + 20), name_str, font=fn_bold, fill=WHITE)
                draw.text((150, y + 76), f"{wr}%  ({tw}/{tp})", font=fn_sm, fill=ACCENT)
            elif metric == "sixes":
                uid, name, uname, val, tr, tb = row
                name_str = (name or "Player")[:22]
                draw.text((150, y + 20), name_str, font=fn_bold, fill=WHITE)
                draw.text((150, y + 76), f"{val} sixes", font=fn_sm, fill=ACCENT)
            elif metric == "mom":
                uid, name, uname, val = row
                name_str = (name or "Player")[:22]
                draw.text((150, y + 20), name_str, font=fn_bold, fill=WHITE)
                draw.text((150, y + 76), f"{val} MOM awards", font=fn_sm, fill=ACCENT)

            y += ROW_H

        draw.rectangle([(0, H - FOOTER_H), (W, H)], fill=(15, 18, 40))
        draw.text((40, H - FOOTER_H + 12), "CRICOVERSE  •  Global Leaderboard", font=fn_sm, fill=GRAY)

        bio = BytesIO()
        img.save(bio, "PNG", optimize=True)
        bio.seek(0)
        return bio
    except Exception as e:
        logger.error(f"Leaderboard image error: {e}")
        return None


def generate_points_table_image(group_id: int) -> Optional[BytesIO]:
    """
    ☀️ CLEAN SCOREBOARD-STYLE POINTS TABLE — LIGHT THEME:
    • Plain white background, thin-bordered table rows (broadcast graphic look)
    • Colored numbered badge per team (no jersey artwork)
    • Bold plain-text title, no emoji clutter
    """
    try:
        pts = tournament_points.get(group_id, {})
        if not pts: return None

        sorted_teams = sorted(pts.items(), key=lambda x: (-x[1].get("pts", 0), -x[1].get("nrr", 0.0)))

        SC = 2
        ROW_H, HEADER_H, TOPBAR_H, FOOTER_H = 68*SC, 60*SC, 90*SC, 40*SC
        W = 1000 * SC
        H = TOPBAR_H + HEADER_H + (len(sorted_teams) * ROW_H) + FOOTER_H + 30*SC

        img = Image.new("RGB", (W, H), (255, 255, 255))
        draw = ImageDraw.Draw(img)

        INK      = (17, 24, 39)
        GRAY     = (100, 116, 139)
        BORDER   = (226, 232, 240)
        HEADFILL = (230, 238, 250)
        GREEN    = (16, 163, 96)
        RED      = (220, 38, 51)
        ORANGE   = (217, 119, 6)
        BLUE     = (37, 99, 235)
        badge_colors = [(37, 99, 235), (220, 38, 51), (217, 158, 10), (124, 58, 237),
                         (234, 88, 12), (13, 148, 136), (219, 39, 119), (5, 150, 105)]

        fn_title = _get_font(True, 34 * SC)
        fn_hdr   = _get_font(True, 17 * SC)
        fn_bold  = _get_font(True, 19 * SC)
        fn_reg   = _get_font(False, 18 * SC)
        fn_sm    = _get_font(False, 14 * SC)

        # ── Top bar: plain bold title, no emoji ──
        draw.text((W//2, TOPBAR_H//2), "POINTS TABLE", font=fn_title, fill=INK, anchor="mm")
        # small tournament pill, top-right
        pill_txt = "TOURNAMENT"
        bbox = draw.textbbox((0, 0), pill_txt, font=fn_sm)
        pw, ph = bbox[2]-bbox[0], bbox[3]-bbox[1]
        ppad_x, ppad_y = 14*SC, 8*SC
        px2, py2 = W - 30*SC, TOPBAR_H//2
        draw.rounded_rectangle(
            [px2 - pw - ppad_x*2, py2 - ph//2 - ppad_y, px2, py2 + ph//2 + ppad_y],
            radius=14*SC, fill=(236, 253, 245), outline=(16, 163, 96), width=2
        )
        draw.text((px2 - pw - ppad_x, py2), pill_txt, font=fn_sm, fill=(5, 122, 85), anchor="lm")

        draw.line([(30*SC, TOPBAR_H), (W-30*SC, TOPBAR_H)], fill=BORDER, width=2)

        # ── Column headers ──
        cols   = ["#", "TEAM", "P", "W", "L", "T", "NR", "NRR", "PTS"]
        col_x  = [50*SC, 100*SC, 430*SC, 500*SC, 570*SC, 640*SC, 705*SC, 775*SC, 890*SC]
        header_y = TOPBAR_H
        draw.rectangle([(30*SC, header_y), (W-30*SC, header_y+HEADER_H)], fill=HEADFILL)
        for cx, ch in zip(col_x, cols):
            draw.text((cx, header_y + HEADER_H//2), ch, font=fn_hdr, fill=(51, 65, 100), anchor="lm")
        draw.rectangle([(30*SC, header_y), (W-30*SC, header_y+HEADER_H)], outline=BORDER, width=2)

        # ── Data rows ──
        curr_y = header_y + HEADER_H
        for idx, (name, stats) in enumerate(sorted_teams):
            row_top = curr_y
            row_bot = curr_y + ROW_H
            draw.rectangle([(30*SC, row_top), (W-30*SC, row_bot)],
                            fill=(255, 255, 255) if idx % 2 == 0 else (248, 250, 253),
                            outline=BORDER, width=1)

            mid_y = (row_top + row_bot) // 2
            badge_color = badge_colors[idx % len(badge_colors)]

            draw.text((col_x[0], mid_y), str(idx+1), font=fn_bold, fill=INK, anchor="lm")

            # numbered badge circle instead of a jersey graphic
            badge_r = 15*SC
            bcx, bcy = col_x[1] + badge_r, mid_y
            draw.ellipse([bcx-badge_r, bcy-badge_r, bcx+badge_r, bcy+badge_r], fill=badge_color)
            num_txt = f"{idx+1:02d}"
            draw.text((bcx, bcy), num_txt, font=_get_font(True, 12*SC), fill=(255, 255, 255), anchor="mm")
            draw.text((col_x[1] + badge_r*2 + 14*SC, mid_y), name[:20].upper(), font=fn_bold, fill=INK, anchor="lm")

            draw.text((col_x[2], mid_y), str(stats.get("played", 0)), font=fn_reg, fill=INK, anchor="lm")
            draw.text((col_x[3], mid_y), str(stats.get("won", 0)), font=fn_reg, fill=GREEN, anchor="lm")
            draw.text((col_x[4], mid_y), str(stats.get("lost", 0)), font=fn_reg, fill=RED, anchor="lm")
            draw.text((col_x[5], mid_y), str(stats.get("tied", 0)), font=fn_reg, fill=ORANGE, anchor="lm")
            draw.text((col_x[6], mid_y), str(stats.get("no_result", 0)), font=fn_reg, fill=GRAY, anchor="lm")

            nrr = stats.get("nrr", 0.0)
            nrr_txt = f"{nrr:+.3f}"
            draw.text((col_x[7], mid_y), nrr_txt, font=fn_reg, fill=(GREEN if nrr >= 0 else RED), anchor="lm")

            pts_val = stats.get("pts", 0)
            draw.text((col_x[8], mid_y), str(pts_val), font=fn_bold, fill=BLUE, anchor="lm")

            curr_y += ROW_H

        draw.line([(30*SC, curr_y), (W-30*SC, curr_y)], fill=BORDER, width=2)
        draw.text((30*SC, curr_y + 14*SC), "CricoVerse Premium League  •  Win: 2 pts | Tie: 1 pt | Loss: 0 pts",
                   font=fn_sm, fill=GRAY)

        final_w, final_h = W // SC, H // SC
        img = img.resize((final_w, final_h), Image.Resampling.LANCZOS)

        bio = BytesIO()
        img.save(bio, "PNG", optimize=True)
        bio.seek(0)
        return bio

    except Exception as e:
        print(f"Points Table Error: {e}")
        return None

def generate_tour_leaderboard_image(group_id: int) -> Optional[BytesIO]:
    """
    ☀️ ULTIMATE TOURNAMENT LEADERBOARD — LIGHT THEME:
    • Vivid gradient banner + 2x2 clean white cards with soft drop-shadows
    • Medal badges (🥇🥈🥉) for top 3 in each category
    • Player names resolve from user_data instead of showing raw ids
    • Always shows the top 5 of each category
    """
    try:
        def _pname(pid, match_id=None):
            return _tour_resolve_name(pid, group_id, match_id)

        all_runs, all_wickets, all_sixes, all_fours = {}, {}, {}, {}

        for match_id, stats in tour_match_stats.get(group_id, {}).items():
            for pid, runs in stats.get("player_runs", {}).items():
                all_runs.setdefault(pid, {"pid": pid, "name": _pname(pid, match_id), "total": 0})["total"] += runs
            for pid, wkts in stats.get("player_wickets", {}).items():
                all_wickets.setdefault(pid, {"pid": pid, "name": _pname(pid, match_id), "total": 0})["total"] += wkts
            for pid, sixes in stats.get("player_sixes", {}).items():
                all_sixes.setdefault(pid, {"pid": pid, "name": _pname(pid, match_id), "total": 0})["total"] += sixes
            for pid, fours in stats.get("player_fours", {}).items():
                all_fours.setdefault(pid, {"pid": pid, "name": _pname(pid, match_id), "total": 0})["total"] += fours

        top_runs  = sorted(all_runs.values(), key=lambda x: -x["total"])[:5]
        top_wkts  = sorted(all_wickets.values(), key=lambda x: -x["total"])[:5]
        top_sixes = sorted(all_sixes.values(), key=lambda x: -x["total"])[:5]
        top_fours = sorted(all_fours.values(), key=lambda x: -x["total"])[:5]

        SC = 2
        W, H = 1100 * SC, 860 * SC
        img = Image.new("RGBA", (W, H), (246, 248, 252, 255))
        draw = ImageDraw.Draw(img)

        for y in range(H):
            t = y / H
            r = int(246 - 8 * t)
            g = int(248 - 6 * t)
            b = int(252 - 4 * t)
            draw.line([(0, y), (W, y)], fill=(r, g, b, 255))

        INK    = (23, 30, 48, 255)
        GOLD   = (196, 138, 12, 255)
        GRAY   = (100, 116, 139, 255)
        GREEN  = (16, 163, 96, 255)
        CARD   = (255, 255, 255, 255)
        BORDER = (226, 232, 240, 255)
        medal_colors = [GOLD, (120, 128, 145, 255), (176, 98, 40, 255), (37, 99, 235, 255), (16, 163, 96, 255)]

        fn_title = _get_font(True, 46 * SC)
        fn_sub   = _get_font(False, 20 * SC)
        fn_hdr   = _get_font(True, 28 * SC)
        fn_bold  = _get_font(True, 26 * SC)
        fn_reg   = _get_font(False, 22 * SC)
        fn_sm    = _get_font(False, 18 * SC)

        # ── Vivid gradient banner (blue → violet) ──
        HEADER_H = 110 * SC
        banner = Image.new("RGBA", (W, HEADER_H), (0, 0, 0, 0))
        bdraw = ImageDraw.Draw(banner)
        for x in range(0, W, 4):
            t = x / W
            r = int(37 + (109 - 37) * t)
            g = int(99 + (40 - 99) * t)
            b = int(235 + (217 - 235) * t)
            bdraw.rectangle([x, 0, x+4, HEADER_H], fill=(r, g, b, 255))
        glow = Image.new("RGBA", (W, HEADER_H), (0, 0, 0, 0))
        gdraw = ImageDraw.Draw(glow)
        gdraw.ellipse([W*0.55, -50*SC, W*1.02, HEADER_H*1.5], fill=(255, 255, 255, 45))
        glow = glow.filter(ImageFilter.GaussianBlur(30*SC))
        banner.alpha_composite(glow, (0, 0))
        img.alpha_composite(banner, (0, 0))
        draw = ImageDraw.Draw(img)

        draw.text((26*SC, 22*SC), "TOURNAMENT LEADERBOARD", font=fn_title, fill=(255, 255, 255, 255))
        draw.text((28*SC, HEADER_H - 34*SC), "Top 5 performers across the tournament", font=fn_sub, fill=(226, 232, 250, 255))

        sections = [
            ("TOP RUN SCORERS", top_runs, "runs", (37, 99, 235)),
            ("TOP WICKET TAKERS", top_wkts, "wkts", (220, 38, 51)),
            ("MOST SIXES", top_sixes, "sixes", (217, 119, 6)),
            ("MOST FOURS", top_fours, "fours", (16, 163, 96)),
        ]

        pad = 22 * SC
        half_w = (W - pad*3) // 2
        card_h = 320 * SC
        y0 = HEADER_H + 20*SC

        for sec_idx, (sec_title, sec_rows, unit, tint) in enumerate(sections):
            col = sec_idx % 2
            row = sec_idx // 2
            sx = pad + col * (half_w + pad)
            sy = y0 + row * (card_h + pad)

            # soft blurred shadow behind card
            shadow = Image.new("RGBA", (W, H), (0, 0, 0, 0))
            ImageDraw.Draw(shadow).rounded_rectangle(
                [sx, sy+8*SC, sx+half_w, sy+card_h+8*SC], radius=18*SC, fill=(60, 70, 100, 45)
            )
            shadow = shadow.filter(ImageFilter.GaussianBlur(10*SC))
            img.alpha_composite(shadow, (0, 0))
            draw = ImageDraw.Draw(img)

            # clean white card
            draw.rounded_rectangle([sx, sy, sx+half_w, sy+card_h], radius=18*SC,
                                    fill=CARD, outline=(tint[0], tint[1], tint[2], 200), width=2*SC)

            # section header strip — drawn on its own layer so the alpha tint
            # actually blends softly instead of overwriting the pixels solid
            strip_layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
            ImageDraw.Draw(strip_layer).rounded_rectangle(
                [sx+8*SC, sy+8*SC, sx+half_w-8*SC, sy+56*SC], radius=12*SC,
                fill=(tint[0], tint[1], tint[2], 30)
            )
            img.alpha_composite(strip_layer, (0, 0))
            draw = ImageDraw.Draw(img)
            draw.text((sx+22*SC, sy+16*SC), sec_title, font=fn_hdr, fill=(tint[0], tint[1], tint[2], 255))

            row_y = sy + 72*SC
            if not sec_rows:
                draw.text((sx+22*SC, row_y+10*SC), "No data yet - play some matches!", font=fn_reg, fill=GRAY)
            else:
                for ri, d in enumerate(sec_rows[:5]):
                    mc = medal_colors[ri]
                    # plain numbered circle badge instead of medal emoji
                    badge_r = 14*SC
                    bcx, bcy = sx+18*SC+badge_r, row_y+14*SC
                    draw.ellipse([bcx-badge_r, bcy-badge_r, bcx+badge_r, bcy+badge_r], fill=mc)
                    draw.text((bcx, bcy), str(ri+1), font=_get_font(True, 16*SC), fill=(255, 255, 255), anchor="mm")
                    name = str(d.get("name", "?"))[:16]
                    draw.text((sx+90*SC, row_y), name, font=fn_bold, fill=INK)
                    draw.text((sx+half_w-140*SC, row_y+2*SC), f"{d['total']} {unit}", font=fn_reg, fill=GREEN)
                    if ri < 4:
                        draw.line([sx+18*SC, row_y+42*SC, sx+half_w-18*SC, row_y+42*SC], fill=BORDER, width=1*SC)
                    row_y += 48*SC

        # Footer
        draw.rectangle([(0, H - 42*SC), (W, H)], fill=(238, 242, 248, 255))
        draw.line([(0, H - 42*SC), (W, H - 42*SC)], fill=BORDER, width=1*SC)
        draw.text((26*SC, H - 32*SC), "CRICOVERSE TOURNAMENT STATS", font=fn_sm, fill=GRAY)

        final_w, final_h = W // SC, H // SC
        img = img.convert("RGB").resize((final_w, final_h), Image.Resampling.LANCZOS)

        bio = BytesIO()
        img.save(bio, "PNG", optimize=True)
        bio.seek(0)
        return bio
    except Exception as e:
        logger.error(f"Tour leaderboard image error: {e}")
        return None


def generate_momentum_image(match) -> Optional[BytesIO]:
    """
    🏎️ Single big speedometer-style WIN PROBABILITY gauge.
    New light UI palette, flat blue/red arcs, 16:8 (2:1) canvas.
    """
    try:
        import math
        from io import BytesIO
        from PIL import Image, ImageDraw

        SC = 2
        W, H = 1600 * SC, 800 * SC   # 16:8 → 2:1

        C_BG      = (246, 248, 252)   # #F6F8FC
        C_CARD    = (255, 255, 255)   # #FFFFFF
        C_BORDER  = (229, 231, 235)   # #E5E7EB
        C_MAIN    = (17, 24, 39)      # #111827
        C_SEC     = (100, 116, 139)   # #64748B
        C_X       = (37, 99, 235)     # #2563EB  Team X
        C_Y       = (239, 51, 64)     # #EF3340  Team Y
        C_GRID    = (226, 232, 240)   # #E2E8F0

        img = Image.new('RGB', (W, H), C_BG)
        draw = ImageDraw.Draw(img)

        tx_name = match.team_x.name[:16]
        ty_name = match.team_y.name[:16]

        f_hdr  = _get_font(True,  40*SC)
        f_sub  = _get_font(False, 22*SC)
        f_med  = _get_font(True,  26*SC)
        f_sml  = _get_font(False, 18*SC)
        f_num  = _get_font(True,  56*SC)

        # Card
        pad = 20*SC
        _draw_rounded_rect(draw, (pad, pad, W-pad, H-pad), radius=24*SC, fill=C_CARD, outline=C_BORDER, width=2*SC)

        # Header
        _draw_text_centered(draw, "MOMENTUM DASHBOARD", W//2, 34*SC, f_hdr, C_MAIN)
        _draw_text_centered(draw, f"{tx_name}  vs  {ty_name}", W//2, 84*SC, f_sub, C_SEC)

        def win_prob(team, opp):
            if match.innings == 1:
                rr_t = team.score / max(team.balls / 6, 0.1)
                rr_o = opp.score / max(opp.balls / 6, 0.1) if opp.balls > 0 else rr_t
                base = 50 + (rr_t - rr_o) * 5
                wkt_pen = team.wickets * 2
                return max(5, min(95, base - wkt_pen))
            else:
                needed = max(0, match.target - team.score)
                bl = (match.total_overs * 6) - (opp.balls)
                if bl <= 0:
                    return 95 if team.score >= match.target else 5
                rrr = needed / bl * 6
                crr = team.score / max(team.balls / 6, 0.1)
                base = 50 + (crr - rrr) * 6
                wkt_pen = team.wickets * 3
                return max(5, min(95, base - wkt_pen))

        bat_team  = match.current_batting_team  or match.team_x
        bowl_team = match.current_bowling_team or match.team_y
        wp_bat  = win_prob(bat_team, bowl_team)
        wp_bowl = 100 - wp_bat

        # Map probabilities to fixed team identity: Team X is always blue, Team Y is always red
        wp_x = wp_bat if bat_team == match.team_x else wp_bowl
        wp_y = 100 - wp_x

        cx, cy = W // 2, int(H * 0.62)
        radius = int(H * 0.30)
        sa, ea = 180, 360   # bottom semicircle sweep
        span = ea - sa

        # Track arc (flat grid color)
        draw.arc([(cx-radius, cy-radius), (cx+radius, cy+radius)], sa, ea, fill=C_GRID, width=int(14*SC))

        # Blue half — flat color (Team X win%)
        blue_deg = span * wp_x / 100
        blue_end = sa + blue_deg
        draw.arc([(cx-radius, cy-radius), (cx+radius, cy+radius)], sa, blue_end, fill=C_X, width=int(14*SC))

        # Red half — flat color (Team Y win%)
        draw.arc([(cx-radius, cy-radius), (cx+radius, cy+radius)], blue_end, ea, fill=C_Y, width=int(14*SC))

        # Tick marks
        for tick_p in range(0, 101, 10):
            ta = math.radians(sa + span * tick_p / 100)
            is_major = tick_p % 20 == 0
            t_in  = radius + (3*SC if is_major else 6*SC)
            t_out = radius + (16*SC if is_major else 11*SC)
            tx1 = cx + int(t_in  * math.cos(ta)); ty1 = cy + int(t_in  * math.sin(ta))
            tx2 = cx + int(t_out * math.cos(ta)); ty2 = cy + int(t_out * math.sin(ta))
            draw.line([(tx1, ty1), (tx2, ty2)], fill=C_SEC if is_major else C_GRID, width=int(3*SC) if is_major else int(2*SC))

        # Needle
        needle_angle = math.radians(sa + span * wp_x / 100)
        needle_len = radius - int(10*SC)
        nx = cx + int(needle_len * math.cos(needle_angle))
        ny = cy + int(needle_len * math.sin(needle_angle))
        draw.line([(cx, cy), (nx, ny)], fill=C_MAIN, width=int(5*SC))
        draw.ellipse([(cx-int(9*SC), cy-int(9*SC)), (cx+int(9*SC), cy+int(9*SC))], fill=C_MAIN)
        draw.ellipse([(cx-int(4*SC), cy-int(4*SC)), (cx+int(4*SC), cy+int(4*SC))], fill=C_CARD)

        # Title above dial
        _draw_text_centered(draw, "WIN PROBABILITY", cx, cy - radius - int(34*SC), f_med, C_MAIN)

        # Divider under dial
        div_y = cy + int(10*SC)
        draw.line([(cx - radius - int(30*SC), div_y), (cx + radius + int(30*SC), div_y)], fill=C_BORDER, width=int(2*SC))

        # Side labels + percentages — Team X (blue) on the left, Team Y (red) on the right
        _draw_text_centered(draw, match.team_x.name[:14], cx - radius - int(20*SC), div_y + int(14*SC), f_med, C_X)
        _draw_text_centered(draw, f"{wp_x:.0f}%", cx - radius - int(20*SC), div_y + int(42*SC), f_num, C_X)

        _draw_text_centered(draw, match.team_y.name[:14], cx + radius + int(20*SC), div_y + int(14*SC), f_med, C_Y)
        _draw_text_centered(draw, f"{wp_y:.0f}%", cx + radius + int(20*SC), div_y + int(42*SC), f_num, C_Y)

        # Slight-edge pill
        leader_name = match.team_x.name[:14] if wp_x >= wp_y else match.team_y.name[:14]
        pill_txt = f"Slight edge: {leader_name}"
        bbox = draw.textbbox((0, 0), pill_txt, font=f_sml)
        pw, ph = bbox[2]-bbox[0], bbox[3]-bbox[1]
        ppad_x, ppad_y = 16*SC, 8*SC
        pcx = cx
        pcy = div_y + int(14*SC)
        _draw_rounded_rect(draw, (pcx-pw//2-ppad_x, pcy-ph//2-ppad_y, pcx+pw//2+ppad_x, pcy+ph//2+ppad_y),
                            radius=16*SC, fill=C_BG, outline=C_BORDER, width=2)
        draw.text((pcx-pw//2, pcy-ph//2-4), pill_txt, font=f_sml, fill=C_SEC)

        # Footer
        footer_y = H - pad - int(30*SC)
        draw.line([(pad+int(20*SC), footer_y), (W-pad-int(20*SC), footer_y)], fill=C_BORDER, width=2)
        _draw_text_centered(draw, f"Cricora  |  {match.group_name[:30]}  |  Ultra Analytics",
                            W//2, footer_y + int(8*SC), f_sml, C_SEC)

        bio = BytesIO()
        img.save(bio, 'PNG', optimize=False)
        bio.seek(0)
        return bio

    except Exception as e:
        logger.error(f"generate_momentum_image error: {e}")
        import traceback; logger.error(traceback.format_exc())
        return None


