async def groupapprove_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔐 Approve Tournament Mode (Owner / Second Approver)"""
    user = update.effective_user
    if user.id not in [OWNER_ID, SECOND_APPROVER_ID]:
        return

    chat = update.effective_chat

    if chat.type == "private":
        if not context.args:
            return
        try:
            group_id = int(context.args[0])
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 20528)")
            return
    else:
        group_id = chat.id

    TOURNAMENT_APPROVED_GROUPS.add(group_id)

    try:
        group_name = (await context.bot.get_chat(group_id)).title
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 20537)")
        group_name = "Unknown Group"

    conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
    c = conn.cursor()
    expires_at = (datetime.now() + timedelta(days=30)).isoformat()
    c.execute('INSERT OR REPLACE INTO tournament_groups (group_id, group_name, approved_at, expires_at, reminder_sent) VALUES (?, ?, CURRENT_TIMESTAMP, ?, 0)',
              (group_id, group_name, expires_at))
    conn.commit()
    conn.close()

    save_data()

    expiry_date = (datetime.now() + timedelta(days=30)).strftime("%d %b %Y")

    # ── Notify the approved group ──
    try:
        sent = await context.bot.send_message(
            chat_id=group_id,
            text=themed(
                "PREMIUM ACCESS ACTIVATED",
                [
                    "✅ This group is now authorized for <b>Tournament & Auction</b> features.",
                    f"📅 Valid until: <b>{expiry_date}</b>",
                    "🏆 Use <code>/game</code> — Tournament Mode to get started.",
                    "⚠️ Authorization expires after 1 month. Contact the owner to renew.",
                ],
                "🎉",
            ),
            parse_mode=ParseMode.HTML
        )
        try:
            await context.bot.pin_chat_message(chat_id=group_id, message_id=sent.message_id, disable_notification=False)
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 20569)")
            pass
    except Exception as e:
        logger.warning(f"Could not notify group {group_id}: {e}")

    # ── Notify support group ──
    try:
        await context.bot.send_message(
            chat_id=SUPPORT_GROUP_ID,
            text=themed(
                "GROUP APPROVED",
                [
                    f"📛 Group: <b>{html.escape(group_name)}</b>",
                    f"🆔 ID: <code>{group_id}</code>",
                    f"📅 Expires: {expiry_date}",
                    f"👤 Approved by: {html.escape(user.first_name)}",
                ],
                "✅",
            ),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.warning(f"Could not notify support group: {e}")

    await update.message.reply_text(
        themed(
            "TOURNAMENT APPROVED",
            [
                f"🆔 Group: <b>{html.escape(group_name)}</b> (<code>{group_id}</code>)",
                f"📅 Valid until: {expiry_date}",
            ],
            "✅",
        ),
        parse_mode=ParseMode.HTML
    )

async def unapprove_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🚫 Owner removes tournament approval"""
    user = update.effective_user
    if not has_power(user.id, "groups"):
        return
    
    chat = update.effective_chat
    
    if chat.type == "private":
        if not context.args:
            await update.message.reply_text(
                "📋 <b>USAGE:</b>\n"
                "<code>/unapprove [group_id]</code>",
                parse_mode=ParseMode.HTML
            )
            return
        group_id = int(context.args[0])
    else:
        group_id = chat.id
    
    TOURNAMENT_APPROVED_GROUPS.discard(group_id)
    
    # Remove from database
    conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
    c = conn.cursor()
    c.execute('DELETE FROM tournament_groups WHERE group_id = ?', (group_id,))
    conn.commit()
    conn.close()
    
    save_data()
    
    await update.message.reply_text(
        themed(
            "TOURNAMENT UNAPPROVED",
            [
                f"🆔 Group ID: <code>{group_id}</code>",
                "⚠️ Status: Tournament access revoked.",
            ],
            "❌",
        ),
        parse_mode=ParseMode.HTML
    )

async def unapprovegroup_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔒 Owner revokes tournament approval from a group and locks all premium commands"""
    user = update.effective_user

    # ── Only bot owner can use this ──
    if not has_power(user.id, "groups"):
        return

    chat = update.effective_chat

    # ── Resolve group_id ──
    if chat.type == "private":
        if not context.args:
            await update.message.reply_text(
                "📋 <b>USAGE:</b>\n"
                "<code>/unapprovegroup &lt;group_id&gt;</code>\n\n"
                "🔒 Revokes tournament & auction access from the group.\n"
                "All premium commands get locked immediately.",
                parse_mode=ParseMode.HTML
            )
            return
        try:
            group_id = int(context.args[0])
        except ValueError:
            await update.message.reply_text(
                "❌ <b>Invalid group ID!</b>\nPlease provide a valid numeric group ID.",
                parse_mode=ParseMode.HTML
            )
            return
    else:
        group_id = chat.id

    # ── Check if it was actually approved ──
    was_approved = group_id in TOURNAMENT_APPROVED_GROUPS

    # ── Remove from memory ──
    TOURNAMENT_APPROVED_GROUPS.discard(group_id)

    # ── Remove from database ──
    conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
    c = conn.cursor()
    c.execute('DELETE FROM tournament_groups WHERE group_id = ?', (group_id,))
    conn.commit()
    conn.close()

    save_data()

    # ── Try to get group name ──
    try:
        group_info = await context.bot.get_chat(group_id)
        group_name = group_info.title or "Unknown Group"
    except Exception:
        group_name = "Unknown Group"

    # ── Notify the group that access has been revoked ──
    try:
        await context.bot.send_message(
            chat_id=group_id,
            text=themed(
                "PREMIUM ACCESS REVOKED",
                [
                    "⚠️ This group's <b>Tournament & Auction</b> access has been deactivated by the bot owner.",
                    "🚫 Auction and tournament commands are now locked in this group.",
                    "📞 To restore access, contact the Bot Owner:",
                    f'<a href="tg://user?id={OWNER_ID}">🔗 Click Here to Contact Owner</a>',
                ],
                "🔒",
            ),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.warning(f"Could not notify group {group_id} about unapproval: {e}")

    # ── Notify support group ──
    try:
        await context.bot.send_message(
            chat_id=SUPPORT_GROUP_ID,
            text=themed(
                "GROUP UNAPPROVED",
                [
                    f"📛 Group: <b>{html.escape(group_name)}</b>",
                    f"🆔 ID: <code>{group_id}</code>",
                    f"👤 Revoked by: {html.escape(user.first_name)}",
                    f"🕐 Time: {datetime.now().strftime('%d %b %Y, %H:%M')}",
                    "⚠️ All premium commands are now locked in that group.",
                ],
                "🔒",
            ),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.warning(f"Could not notify support group about unapproval: {e}")

    # ── Confirm to owner ──
    status_note = "✅ Was approved — now revoked." if was_approved else "ℹ️ Was not approved (cleaned up anyway)."
    await update.message.reply_text(
        themed(
            "GROUP UNAPPROVED",
            [
                f"📛 Group: <b>{html.escape(group_name)}</b>",
                f"🆔 Group ID: <code>{group_id}</code>",
                f"📌 Status: {status_note}",
                "🚫 All tournament & auction commands are now locked in that group.",
                "📞 Group members will see a message to contact you to unlock.",
            ],
            "🔒",
        ),
        parse_mode=ParseMode.HTML
    )


async def groupunapprove_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    🔒 /groupunapprove <group_id>  — revoke a single group (same as /unapprovegroup)
    🔒 /groupunapprove all         — revoke EVERY currently-approved group in one shot
    """
    user = update.effective_user
    if not has_power(user.id, "groups"):
        return

    if not context.args:
        await update.message.reply_text(
            "📋 <b>USAGE:</b>\n"
            "<code>/groupunapprove &lt;group_id&gt;</code> — revoke one group\n"
            "<code>/groupunapprove all</code> — revoke ALL approved groups\n\n"
            "🔒 Revokes tournament & auction access immediately.",
            parse_mode=ParseMode.HTML
        )
        return

    if context.args[0].strip().lower() == "all":
        group_ids = list(TOURNAMENT_APPROVED_GROUPS)
        if not group_ids:
            await update.message.reply_text("ℹ️ No groups are currently approved.")
            return

        status_msg = await update.message.reply_text(
            f"⏳ Revoking premium access for <b>{len(group_ids)}</b> group{'s' if len(group_ids) != 1 else ''}...",
            parse_mode=ParseMode.HTML
        )

        conn = await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
        c = conn.cursor()
        c.execute('DELETE FROM tournament_groups')
        conn.commit()
        conn.close()

        TOURNAMENT_APPROVED_GROUPS.clear()
        save_data()

        notified = 0
        for gid in group_ids:
            try:
                await context.bot.send_message(
                    chat_id=gid,
                    text=themed(
                        "PREMIUM ACCESS REVOKED",
                        [
                            "⚠️ This group's <b>Tournament & Auction</b> access has been deactivated by the bot owner.",
                            "🚫 All tournament/auction commands are now locked in this group.",
                            "📞 To restore access, contact the Bot Owner:",
                            f'<a href="tg://user?id={OWNER_ID}">🔗 Click Here to Contact Owner</a>',
                        ],
                        "🔒",
                    ),
                    parse_mode=ParseMode.HTML
                )
                notified += 1
            except Exception as e:
                logger.warning(f"Could not notify group {gid} about bulk unapproval: {e}")

        try:
            await context.bot.send_message(
                chat_id=SUPPORT_GROUP_ID,
                text=themed(
                    "ALL GROUPS UNAPPROVED",
                    [
                        f"🆔 Count: {len(group_ids)}",
                        f"👤 Revoked by: {html.escape(user.first_name)}",
                        f"🕐 Time: {datetime.now().strftime('%d %b %Y, %H:%M')}",
                    ],
                    "🔒",
                ),
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.warning(f"Could not notify support group about bulk unapproval: {e}")

        await status_msg.edit_text(
            themed(
                "ALL GROUPS UNAPPROVED",
                [
                    f"🆔 Total revoked: {len(group_ids)}",
                    f"📨 Notified: {notified}",
                    "🚫 Every group's tournament & auction access is now locked.",
                ],
                "🔒",
            ),
            parse_mode=ParseMode.HTML
        )
        return

    # ── Single group_id path → reuse the existing single-group revoke logic ──
    await unapprovegroup_command(update, context)


async def start_auction_live_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🎯 Start auction live callback"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    
    if chat.id not in active_auctions:
        await query.answer(plain_alert("❌ No active auction!"), show_alert=True)
        return
    
    auction = active_auctions[chat.id]
    
    # Validate before starting
    if not auction.auctioneer_id:
        await query.answer(plain_alert("⚠️ Please select an auctioneer first!"), show_alert=True)
        return
    
    if len(auction.teams) < 2:
        await query.answer(plain_alert("⚠️ Need at least 2 teams!"), show_alert=True)
        return
    
    if len(auction.player_pool) == 0:
        await query.answer(plain_alert("⚠️ Add players first using /aucplayer!"), show_alert=True)
        return
    
    # Start auction
    auction.phase = AuctionPhase.AUCTION_LIVE
    
    await query.edit_message_text(
        text=(
            "🎤〔 <b>AUCTION IS NOW LIVE!</b> 〕🎤\n\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            "  🔨 BIDDING OPEN  \n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            "🏃‍♂️ First player coming up any moment!\n"
            "⌨️ Use <code>/bid [amount]</code> to place bids!\n\n"
            "🍀 <i>May the best team win!</i>"
        ),
        parse_mode=ParseMode.HTML
    )
    
    # Start bringing players
    await asyncio.sleep(2)
    await bring_next_player(context, chat.id, auction)

def _auc_config_text(auction: "Auction", user_tag: str) -> str:
    return (
        f"<blockquote>🎤〔 <b>AUCTIONEER CONFIRMED!</b> 〕🎤\n\n"
        f"✅ {user_tag} is now the auctioneer!\n\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"⚙️ <b>SET AUCTION CONFIG</b>\n"
        f"Adjust with the buttons, then Proceed.\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        f"🪙 <b>Purse per team:</b> {auction.default_purse}\n"
        f"👥 <b>Max players per team:</b> {auction.max_players_per_team}\n"
        f"</blockquote>"
    )

AUC_MIN_PURSE = 100
AUC_MAX_PURSE = 100000
AUC_PURSE_STEP = 100
AUC_MIN_PLAYERS_PER_TEAM = 2
AUC_MAX_PLAYERS_PER_TEAM = 25

def _auc_config_kb(chat_id: int, auction: "Auction" = None) -> InlineKeyboardMarkup:
    coins_at_min = auction is not None and auction.default_purse <= AUC_MIN_PURSE
    coins_at_max = auction is not None and auction.default_purse >= AUC_MAX_PURSE
    players_at_min = auction is not None and auction.max_players_per_team <= AUC_MIN_PLAYERS_PER_TEAM
    players_at_max = auction is not None and auction.max_players_per_team >= AUC_MAX_PLAYERS_PER_TEAM
    return InlineKeyboardMarkup([
        [
            styled_button("➖" if not coins_at_min else "▪️", callback_data=f"auccfg_coins_minus_{chat_id}"),
            styled_button(f"🪙 {auction.default_purse}" if auction else "Coins", callback_data="noop"),
            styled_button("➕" if not coins_at_max else "▪️", callback_data=f"auccfg_coins_plus_{chat_id}"),
        ],
        [
            styled_button("➖" if not players_at_min else "▪️", callback_data=f"auccfg_players_minus_{chat_id}"),
            styled_button(f"👥 {auction.max_players_per_team}" if auction else "Players", callback_data="noop"),
            styled_button("➕" if not players_at_max else "▪️", callback_data=f"auccfg_players_plus_{chat_id}"),
        ],
        [styled_button("PROCEED AND CONTINUE", callback_data=f"auccfg_proceed_{chat_id}")]
    ])

async def _edit_auction_setup_message(query, text: str, reply_markup=None):
    """Edit an auction setup message regardless of whether it is a text or media message."""
    msg = query.message
    kwargs = {"parse_mode": ParseMode.HTML}
    if reply_markup is not None:
        kwargs["reply_markup"] = reply_markup

    # Media messages (photo/animation/video) have captions; normal messages have text.
    if getattr(msg, "caption", None) is not None:
        return await msg.edit_caption(caption=text, **kwargs)
    return await msg.edit_text(text=text, **kwargs)


async def become_auctioneer_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🎤 Set auctioneer, then move into purse/squad-size config step"""
    query = update.callback_query
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_auctions:
        await query.answer()
        return
    
    auction = active_auctions[chat.id]

    if auction.auctioneer_id:
        await query.answer(plain_alert("⚠️ An auctioneer has already been selected!"), show_alert=True)
        return

    await query.answer(plain_alert("✅ You are now the Auctioneer!"))

    auction.auctioneer_id = user.id
    auction.auctioneer_name = user.first_name
    auction.setup_stage = "config"
    
    user_tag = get_user_tag(user)
    
    await _edit_auction_setup_message(
        query,
        _auc_config_text(auction, user_tag),
        _auc_config_kb(chat.id, auction)
    )

async def auction_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """⚙️ Handle +/- coins/players buttons and the Proceed button of the config step"""
    query = update.callback_query
    user = query.from_user
    parts = query.data.split("_")  # auccfg_<field>_<op>_<chatid>  OR  auccfg_proceed_<chatid>
    try:
        chat_id = int(parts[-1])
    except (ValueError, IndexError):
        await query.answer(plain_alert("❌ Invalid data."), show_alert=True)
        return

    if chat_id not in active_auctions:
        await query.answer(plain_alert("❌ No active auction!"), show_alert=True)
        return

    auction = active_auctions[chat_id]

    if user.id != auction.auctioneer_id:
        await query.answer(plain_alert("🚫 Only the Auctioneer can change this!"), show_alert=True)
        return

    if parts[1] == "proceed":
        await query.answer(plain_alert("➡️ Moving to bidder selection..."))
        auction.setup_stage = "bidder"
        await _edit_auction_setup_message(
            query,
            (
                f"<blockquote>👥〔 <b>SELECT BIDDERS</b> 〕👥\n\n"
                f"🪙 Purse: <b>{auction.default_purse}</b>  |  👤 Max Players: <b>{auction.max_players_per_team}</b>\n"
                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
                f"Reply to each team's bidder with:\n"
                f"<code>/bidder [TeamName]</code>\n\n"
                f"<b>Example:</b> <code>/bidder Mumbai Indians</code>\n\n"
                f"Add at least 2 teams, then tap Proceed.\n"
                f"</blockquote>"
            ),
            InlineKeyboardMarkup([[
                styled_button("PROCEED AND CONTINUE", callback_data=f"auccfg_bidderdone_{chat_id}")
            ]])
        )
        return

    if parts[1] == "bidderdone":
        if len(auction.teams) < 2:
            await query.answer(plain_alert("⚠️ Need at least 2 teams with bidders assigned!"), show_alert=True)
            return
        await query.answer(plain_alert("➡️ Moving to player addition..."))
        auction.setup_stage = "player"
        await _edit_auction_setup_message(
            query,
            (
                f"<blockquote>🏏〔 <b>ADD PLAYERS FOR AUCTION</b> 〕🏏\n\n"
                f"📊 Teams Ready: <b>{len(auction.teams)}</b>\n"
                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
                f"Reply to each player with:\n"
                f"<code>/aucplayer</code>\n\n"
                f"You'll set that player's base price, then confirm Yes/No.\n"
                f"Add all players, then tap Proceed to go live.\n"
                f"</blockquote>"
            ),
            InlineKeyboardMarkup([[
                styled_button("PROCEED AND CONTINUE", callback_data=f"auccfg_playerdone_{chat_id}")
            ]])
        )
        return

    if parts[1] == "playerdone":
        if len(auction.player_pool) == 0:
            await query.answer(plain_alert("⚠️ Add at least one player with /aucplayer!"), show_alert=True)
            return
        await query.answer(plain_alert("🎤 Auction going live!"))
        auction.phase = AuctionPhase.AUCTION_LIVE
        await _edit_auction_setup_message(
            query,
                "<blockquote>🎤〔 <b>AUCTION IS NOW LIVE!</b> 〕🎤\n\n"
                "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                "  🔨 BIDDING OPEN  \n"
                "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
                "🏃‍♂️ First player coming up any moment!\n"
                "⌨️ Use <code>/bid [amount]</code> or the quick-bid buttons!\n\n"
                "🍀 <i>May the best team win!</i></blockquote>"

        )
        await asyncio.sleep(2)
        await bring_next_player(context, chat_id, auction)
        return

    # +/- coins/players
    field = parts[1]       # "coins" or "players"
    op = parts[2]           # "minus" or "plus"
    delta = AUC_PURSE_STEP if field == "coins" else 1
    if op == "minus":
        delta = -delta

    if field == "coins":
        new_val = auction.default_purse + delta
        if new_val < AUC_MIN_PURSE:
            await query.answer(plain_alert(f"🚫 Minimum purse is {AUC_MIN_PURSE}!"), show_alert=True)
            return
        if new_val > AUC_MAX_PURSE:
            await query.answer(plain_alert(f"🚫 Maximum purse is {AUC_MAX_PURSE}!"), show_alert=True)
            return
        auction.default_purse = new_val
    else:
        new_val = auction.max_players_per_team + delta
        if new_val < AUC_MIN_PLAYERS_PER_TEAM:
            await query.answer(plain_alert(f"🚫 Minimum is {AUC_MIN_PLAYERS_PER_TEAM} players per team!"), show_alert=True)
            return
        if new_val > AUC_MAX_PLAYERS_PER_TEAM:
            await query.answer(plain_alert(f"🚫 Maximum is {AUC_MAX_PLAYERS_PER_TEAM} players per team!"), show_alert=True)
            return
        auction.max_players_per_team = new_val

    await query.answer()
    user_tag = get_user_tag(user)
    try:
        await _edit_auction_setup_message(
            query,
            _auc_config_text(auction, user_tag),
            _auc_config_kb(chat_id, auction)
        )
    except Exception:
        pass

async def noop_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Purely decorative button (e.g. the 'Coins'/'Players' label) — do nothing."""
    await update.callback_query.answer()

def _auc_username_tag(pid) -> str:
    """Look up @username for a player_id from the global user_data cache
    (populated for anyone who's ever messaged in any group the bot is in —
    see global_username_cache_updater). Falls back to '—' if unknown."""
    if not pid:
        return "—"
    ud = user_data.get(pid, {})
    uname = ud.get("username", "")
    return f"@{uname}" if uname else "—"


def _build_unsold_rich_html(unsold_players) -> str:
    """CCC/fantasylb-style sendRichMessage HTML: a real collapsible
    <details><table> dropdown instead of a plain <pre> text grid."""
    trs = ""
    for i, player_data in enumerate(unsold_players, 1):
        name = player_data if isinstance(player_data, str) else player_data.get('player_name', 'Unknown')
        base = "" if isinstance(player_data, str) else player_data.get('base_price', player_data.get('price', ''))
        pid = "" if isinstance(player_data, str) else player_data.get('player_id', '')
        uname = _auc_username_tag(pid)
        trs += (
            f"<tr><td align='center'>{i}</td>"
            f"<td>{html.escape(str(name))}</td>"
            f"<td align='center'>{pid or '—'}</td>"
            f"<td align='center'>{html.escape(uname)}</td>"
            f"<td align='right'>{html.escape(str(base))}</td></tr>"
        )
    table = (
        "<table bordered striped>"
        "<tr><th>#️⃣</th><th>🧢 Player</th><th>🆔 User ID</th><th>👤 Username</th><th>💰 Base Price</th></tr>"
        f"{trs}</table>"
    )
    return (
        "<h3>❌ UNSOLD PLAYERS</h3>"
        f"<details><summary>❌ Unsolds ({len(unsold_players)})</summary>"
        f"{table}</details>"
        f"<footer>📊 Total Unsold: {len(unsold_players)}</footer>"
    )


def _build_unsold_fallback_text(unsold_players) -> str:
    """Plain-text fallback if sendRichMessage isn't supported — same
    CCC-style collapsed <blockquote expandable><pre> table as other
    fallback paths (fantasylb, end_auction scorecard, etc.)."""
    fb_header = f"❌ <b>Unsolds ({len(unsold_players)})</b>"
    fb_table = (
        f"{_auc_pad('#', 4)}{_auc_pad('🧢 Player', 16)}{_auc_pad('🆔 ID', 12)}{_auc_pad('👤 Username', 16)}{_auc_rpad('💰 Price', 8)}\n"
        + ("—" * 56) + "\n"
    )
    for i, player_data in enumerate(unsold_players, 1):
        name = player_data if isinstance(player_data, str) else player_data.get('player_name', 'Unknown')
        base = "" if isinstance(player_data, str) else player_data.get('base_price', player_data.get('price', ''))
        pid = "" if isinstance(player_data, str) else player_data.get('player_id', '')
        uname = _auc_username_tag(pid)
        fb_table += f"{_auc_pad(i, 4)}{_auc_pad(name, 16)}{_auc_pad(pid or '—', 12)}{_auc_pad(uname, 16)}{_auc_rpad(base, 8)}\n"
    fb = f"<blockquote expandable>{fb_header}\n<pre>{fb_table}</pre></blockquote>"
    fb += f"\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n📊 <b>Total Unsold:</b> {len(unsold_players)}"
    return fb


async def unsold_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """❌ List unsold players — CCC/fantasylb-style native <table>+<details>
    dropdown (sendRichMessage), falling back to a plain expandable text
    table if Rich Messages aren't supported."""
    chat = update.effective_chat
    if chat.id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\n"
            "Start an auction first with /auction",
            parse_mode=ParseMode.HTML
        )
        return
    auction = active_auctions[chat.id]
    if not auction.unsold_players:
        await update.message.reply_text(
            "✅ <b>NO UNSOLD PLAYERS YET!</b>\n\n"
            "All players have been sold so far.",
            parse_mode=ParseMode.HTML
        )
        return

    html_content = _build_unsold_rich_html(auction.unsold_players)
    ok = await _tg_send_rich_message(chat.id, html_content)

    if not ok:
        fallback = _build_unsold_fallback_text(auction.unsold_players)
        await update.message.reply_text(fallback, parse_mode=ParseMode.HTML)

async def bring_back_unsold_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔄 Bring back unsold players"""
    query = update.callback_query
    chat = query.message.chat
    
    if chat.id not in active_auctions:
        await query.answer(plain_alert("❌ No active auction!"), show_alert=True)
        return
        
    auction = active_auctions[chat.id]
    
    if not auction.unsold_players:
        await query.answer(plain_alert("✅ No unsold players to bring back!"), show_alert=True)
        return
    
    # Move unsold back to player pool
    for player in auction.unsold_players:
        if isinstance(player, dict):
            auction.player_pool.append(player)
    
    count = len(auction.unsold_players)
    auction.unsold_players.clear()
    
    await query.answer(plain_alert(f"✅ {count} players added back to pool!"), show_alert=True)
    await query.message.edit_text(
        f"🔄 <b>UNSOLD PLAYERS RESTORED!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        f"📦 <b>Players Added Back:</b> {count}\n"
        f"📊 <b>Total Pool Size:</b> {len(auction.player_pool)}\n\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        parse_mode=ParseMode.HTML
    )

async def auc_confirm_sold_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """✅ Auctioneer confirms a sold player."""
    query = update.callback_query
    user = query.from_user
    parts = query.data.split("_")  # auc_confirm_sold_chatid
    try:
        chat_id = int(parts[-1])
    except (ValueError, IndexError):
        await query.answer(plain_alert("❌ Invalid data."), show_alert=True)
        return

    if chat_id not in active_auctions:
        await query.answer(plain_alert("❌ No active auction!"), show_alert=True)
        return

    auction = active_auctions[chat_id]
    if user.id != auction.auctioneer_id:
        await query.answer(plain_alert("🚫 Only the Auctioneer can confirm!"), show_alert=True)
        return

    if not getattr(auction, 'pending_sold_confirmation', False):
        await query.answer(plain_alert("⚠️ Already processed."), show_alert=True)
        return

    # Trigger event-driven confirmation
    auction.confirm_action = "confirm"
    if hasattr(auction, 'sold_confirm_event'):
        auction.sold_confirm_event.set()
        
    await query.answer(plain_alert("✅ Player sold and confirmed!"))

