async def pause_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """⏸ Pause the auction timer"""
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_auctions:
        await update.message.reply_text("🚫 No active auction!", parse_mode=ParseMode.HTML)
        return
        
    auction = active_auctions[chat.id]
    
    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🚧 <b>ACCESS DENIED!</b>\n\n"
            "Only Auctioneer/Host can pause the auction.",
            parse_mode=ParseMode.HTML
        )
        return
    if getattr(auction, 'is_paused', False):
        await update.message.reply_text("⏸ Auction is already paused! Use /resume to continue.", parse_mode=ParseMode.HTML)
        return

    # Remember how many seconds were left so /resume can restore them
    remaining = None
    if auction.bid_timer_task and auction.bid_end_time:
        remaining = max(5, int(auction.bid_end_time - time.time()))
    auction.pause_remaining_secs = remaining
    auction.is_paused = True

    if auction.bid_timer_task:
        auction.bid_timer_task.cancel()
        auction.bid_timer_task = None

    await update.message.reply_text(
        "⏸ <b>AUCTION PAUSED!</b>\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        "⏱ Timer stopped. No bids will be accepted.\n"
        "▶️ Use /resume to continue.\n\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        parse_mode=ParseMode.HTML
    )

async def resume_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """▶️ Resume the auction"""
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_auctions:
        await update.message.reply_text("🚫 No active auction!", parse_mode=ParseMode.HTML)
        return
        
    auction = active_auctions[chat.id]
    
    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🚧 <b>ACCESS DENIED!</b>\n\n"
            "Only Auctioneer/Host can resume the auction.",
            parse_mode=ParseMode.HTML
        )
        return
    if not getattr(auction, 'is_paused', False):
        await update.message.reply_text("⚠️ Auction isn't paused right now.", parse_mode=ParseMode.HTML)
        return

    if auction.phase == AuctionPhase.AUCTION_LIVE:
        secs = getattr(auction, 'pause_remaining_secs', None) or 20
        auction.is_paused = False
        auction.pause_remaining_secs = None
        if auction.bid_timer_task:
            auction.bid_timer_task.cancel()
        auction.bid_end_time = time.time() + secs
        auction.bid_timer_task = asyncio.create_task(bid_timer(context, chat.id, auction, initial_secs=secs))

        await update.message.reply_text(
            f"▶️ <b>AUCTION RESUMED!</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            f"⏱ Timer: {secs} seconds\n"
            "💰 Bidding is now active!\n\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
    else:
        auction.is_paused = False
        auction.pause_remaining_secs = None
        await update.message.reply_text("▶️ Auction unpaused, but bidding round isn't live right now.", parse_mode=ParseMode.HTML)

async def cancelbid_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔄 Cancel last bid"""
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_auctions:
        await update.message.reply_text("🚫 No active auction!", parse_mode=ParseMode.HTML)
        return
    auction = active_auctions[chat.id]
    # Permission check
    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🚧 <b>ACCESS DENIED!</b>\n\n"
            "Only Auctioneer can cancel bids!",
            parse_mode=ParseMode.HTML
        )
        return

    # 🆕 /cancelbid @player  (or reply to a real player, or /cancelbid <name>)
    # Undoes an ALREADY-SOLD player: pulls them out of their team, refunds
    # the team's purse, and drops them back into the pool for re-auction.
    # (This is different from the no-args form below, which only resets the
    # *currently live* bid to base price.)
    args = context.args or []
    replied = update.message.reply_to_message
    if args or (replied and replied.from_user):
        query_id = None
        query_name = None
        if replied and replied.from_user:
            query_id = replied.from_user.id
            query_name = replied.from_user.first_name
        else:
            raw = " ".join(args).strip()
            if raw.startswith("@"):
                raw = raw[1:]
            query_name = raw
            if raw.isdigit():
                query_id = int(raw)

        match = None
        for sp in auction.sold_players:
            if query_id is not None and sp.get("player_id") == query_id:
                match = sp
                break
        if match is None and query_name:
            # 🩹 exact name first — substring-only matching let e.g. "an" hit
            # the wrong player and refund/cancel someone else's sale
            _q = query_name.lower()
            for sp in auction.sold_players:
                if str(sp.get("player_name", "")).lower() == _q:
                    match = sp
                    break
            if match is None:
                for sp in auction.sold_players:
                    if _q in str(sp.get("player_name", "")).lower():
                        match = sp
                        break

        if not match:
            await update.message.reply_text(
                "🚫 <b>PLAYER NOT FOUND!</b>\n\n"
                "No <b>SOLD</b> player matches that name/user. "
                "(Use plain <code>/cancelbid</code> with no args to undo the current live bid instead.)",
                parse_mode=ParseMode.HTML
            )
            return

        team_name = match.get("team")
        team = auction.teams.get(team_name)
        if not team:
            await update.message.reply_text("⚠️ Internal error: that player's team no longer exists.", parse_mode=ParseMode.HTML)
            return

        price = match.get("price", 0)
        pid = match.get("player_id")
        pname = match.get("player_name")

        # Remove from the team roster + refund the purse they spent
        team.players = [p for p in team.players if p.get("player_id") != pid]
        team.purse_remaining += price
        team.total_spent -= price

        # Drop from the global sold list
        auction.sold_players = [sp for sp in auction.sold_players if sp is not match]
        # 🩹 also drop the stale "sold" row from auction_history — it was left
        # behind, so summaries/history showed the sale AND the re-sale.
        for _i in range(len(auction.auction_history) - 1, -1, -1):
            _h = auction.auction_history[_i]
            if _h.get("player_id") == pid and _h.get("sold") and _h.get("team") == team_name:
                del auction.auction_history[_i]
                break

        # Send the player back into the pool so they can be re-auctioned
        auction.player_pool.append({
            "player_id": pid,
            "player_name": pname,
            "base_price": match.get("base_price", price),
        })

        await update.message.reply_text(
            f"🔄 <b>PLAYER AUCTION CANCELLED!</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            f"👤 <b>Player:</b> {html.escape(str(pname))}\n"
            f"🏏 <b>Removed From:</b> {team_name}\n"
            f"💰 <b>Refunded:</b> {price} (purse restored)\n"
            f"📥 Sent back to the pool for re-auction.\n\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
        return

    # ── Below: original behaviour — cancel the CURRENT LIVE bid ──
    # Must be in live bidding phase
    if auction.phase != AuctionPhase.AUCTION_LIVE:
        await update.message.reply_text(
            "⚠️ <b>NO LIVE BIDDING!</b>\n\n"
            "Cannot cancel bids outside live auction.",
            parse_mode=ParseMode.HTML
        )
        return
    # Reset bid state
    old_bid = auction.current_highest_bid
    auction.current_highest_bid = auction.current_base_price
    auction.current_highest_bidder = None
    # Reset bid timer
    if auction.bid_timer_task:
        auction.bid_timer_task.cancel()
    auction.bid_end_time = time.time() + 20
    auction.bid_timer_task = asyncio.create_task(bid_timer(context, chat.id, auction))
    await update.message.reply_text(
        f"🔄 <b>LAST BID CANCELLED!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        f"❌ <b>Cancelled Bid:</b> {old_bid}\n"
        f"💰 <b>Reset to Base:</b> {auction.current_base_price}\n"
        f"⏱ <b>Timer Reset:</b> 20s\n\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        parse_mode=ParseMode.HTML
    )

async def transferplayer_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔁 /transferplayer @player [price]  (or reply to a real player with
    /transferplayer [price])
    Moves an ALREADY-SOLD auction player from their current team to a
    different team for the given price. Detects the player's current team
    automatically and shows tap-to-pick buttons for every other team."""
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_auctions:
        await update.message.reply_text("🚫 No active auction!", parse_mode=ParseMode.HTML)
        return
    auction = active_auctions[chat.id]

    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🚧 <b>ACCESS DENIED!</b>\n\nOnly the Auctioneer can transfer players!",
            parse_mode=ParseMode.HTML
        )
        return

    args = context.args or []
    replied = update.message.reply_to_message

    query_id = None
    query_name = None
    price = None

    if replied and replied.from_user:
        if not args or not args[0].replace('.', '', 1).isdigit():
            await update.message.reply_text(
                "ℹ️ Usage: <code>/transferplayer [price]</code> (as a reply) "
                "or <code>/transferplayer @player [price]</code>",
                parse_mode=ParseMode.HTML
            )
            return
        query_id = replied.from_user.id
        query_name = replied.from_user.first_name
        price = int(float(args[0]))
    else:
        if len(args) < 2 or not args[-1].replace('.', '', 1).isdigit():
            await update.message.reply_text(
                "ℹ️ Usage: <code>/transferplayer @player [price]</code> "
                "or reply to a player with <code>/transferplayer [price]</code>",
                parse_mode=ParseMode.HTML
            )
            return
        price = int(float(args[-1]))
        query_name = " ".join(args[:-1]).lstrip("@").strip()
        if query_name.isdigit():
            query_id = int(query_name)

    if price is None or price <= 0:
        await update.message.reply_text("⚠️ Transfer price must be positive.", parse_mode=ParseMode.HTML)
        return

    # Auto-detect the player's CURRENT team from the sold list
    match = None
    for sp in auction.sold_players:
        if query_id is not None and sp.get("player_id") == query_id:
            match = sp
            break
        if query_name and query_name.lower() in str(sp.get("player_name", "")).lower():
            match = sp
            break

    if not match:
        await update.message.reply_text(
            "🚫 <b>PLAYER NOT FOUND!</b>\n\nThat player isn't SOLD to any team yet, so there's nothing to transfer.",
            parse_mode=ParseMode.HTML
        )
        return

    current_team_name = match.get("team")
    other_teams = [t for t in auction.teams.keys() if t != current_team_name]
    if not other_teams:
        await update.message.reply_text("⚠️ There's no other team to transfer this player to!", parse_mode=ParseMode.HTML)
        return

    transfer_pending[chat.id] = {
        "player_id": match.get("player_id"),
        "player_name": match.get("player_name"),
        "from_team": current_team_name,
        "price": price,
        "auctioneer_id": user.id,
        "teams": other_teams,
    }

    keyboard = [
        [styled_button(f"➡️ {t}", callback_data=f"trplayer_{chat.id}_{i}")]
        for i, t in enumerate(other_teams)
    ]

    await update.message.reply_text(
        f"🔁 <b>TRANSFER PLAYER</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        f"👤 <b>Player:</b> {html.escape(str(match.get('player_name')))}\n"
        f"🏏 <b>Current Team:</b> {current_team_name}\n"
        f"💰 <b>Transfer Price:</b> {price}\n\n"
        f"👇 Tap the team to move this player to:\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        reply_markup=InlineKeyboardMarkup(keyboard),
        parse_mode=ParseMode.HTML
    )


async def transferplayer_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles the destination-team tap for /transferplayer."""
    query = update.callback_query
    user = query.from_user
    parts = query.data.split("_")  # trplayer_chatid_idx
    try:
        chat_id = int(parts[1])
        idx = int(parts[2])
    except (ValueError, IndexError):
        await query.answer(plain_alert("❌ Invalid data."), show_alert=True)
        return

    if chat_id not in active_auctions:
        await query.answer(plain_alert("❌ No active auction!"), show_alert=True)
        return
    auction = active_auctions[chat_id]

    pending = transfer_pending.get(chat_id)
    if not pending:
        await query.answer(plain_alert("⌛ This transfer request has expired."), show_alert=True)
        return
    if user.id != pending.get("auctioneer_id"):
        await query.answer(plain_alert("🚧 Only the auctioneer who started this transfer can confirm it."), show_alert=True)
        return

    other_teams = pending.get("teams", [])
    if idx < 0 or idx >= len(other_teams):
        await query.answer(plain_alert("❌ Invalid team selection."), show_alert=True)
        return

    new_team_name = other_teams[idx]
    new_team = auction.teams.get(new_team_name)
    old_team = auction.teams.get(pending["from_team"])
    if not new_team or not old_team:
        await query.answer(plain_alert("⚠️ One of the teams no longer exists."), show_alert=True)
        transfer_pending.pop(chat_id, None)
        return

    price = pending["price"]
    pid = pending["player_id"]
    pname = pending["player_name"]

    if price > new_team.purse_remaining:
        await query.answer(plain_alert(f"💰 {new_team_name} doesn't have enough purse ({new_team.purse_remaining})!"), show_alert=True)
        return
    if len(new_team.players) >= getattr(auction, 'max_players_per_team', 11):
        await query.answer(plain_alert(f"🚫 {new_team_name}'s squad is already full!"), show_alert=True)
        return

    # Remove from old team + refund whatever they'd originally paid
    old_price = 0
    for p in old_team.players:
        if p.get("player_id") == pid:
            old_price = p.get("price", 0)
            break
    old_team.players = [p for p in old_team.players if p.get("player_id") != pid]
    old_team.purse_remaining += old_price
    old_team.total_spent -= old_price

    # Add to the new team at the transfer price
    new_team.add_player(pid, pname, price)

    # Keep the global sold-players record in sync
    for sp in auction.sold_players:
        if sp.get("player_id") == pid and sp.get("team") == pending["from_team"]:
            sp["team"] = new_team_name
            sp["price"] = price
            break

    transfer_pending.pop(chat_id, None)

    await query.answer(plain_alert(f"✅ {pname} transferred to {new_team_name}!"))
    await query.edit_message_text(
        f"✅ <b>TRANSFER COMPLETE!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        f"👤 <b>Player:</b> {html.escape(str(pname))}\n"
        f"🏏 <b>From:</b> {pending['from_team']}\n"
        f"🏏 <b>To:</b> {new_team_name}\n"
        f"💰 <b>Price:</b> {price}\n\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        parse_mode=ParseMode.HTML
    )


async def wallet_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """💰 Show remaining purse"""
    chat = update.effective_chat
    if chat.id not in active_auctions:
        await update.message.reply_text("🚫 No active auction!", parse_mode=ParseMode.HTML)
        return
    auction = active_auctions[chat.id]
    msg = "💰 <b>TEAM WALLETS</b>\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
    sorted_teams = sorted(
        auction.teams.values(),
        key=lambda x: x.purse_remaining,
        reverse=True
    )
    for i, team in enumerate(sorted_teams, 1):
        emoji = "🥇" if i == 1 else "🥈" if i == 2 else "🥉" if i == 3 else "🏏"
        # 🩹 BUGFIX: was hardcoded `1000 - purse_remaining`, which only gave
        # the right "spent" figure when the auction's configured starting
        # purse happened to be exactly 1000 (default_purse is adjustable
        # 100–100000 in the setup wizard). Use the tracked total instead.
        spent = team.total_spent
        
        msg += f"{emoji} <b>{team.name}</b>\n"
        msg += f"   💰 Purse: <b>{team.purse_remaining}</b>\n"
        msg += f"   💸 Spent: {spent}\n"
        msg += f"   👥 Players: {len(team.players)}\n\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

