async def bidder_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """👥 Assign bidder - WORKS WITHOUT BOT START"""
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_auctions:
        await update.message.reply_text(
            "❌ <b>NO ACTIVE AUCTION!</b>\n\n"
            "Start an auction first with /auction",
            parse_mode=ParseMode.HTML
        )
        return
    
    auction = active_auctions[chat.id]
    
    # Only auctioneer can assign
    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🎤 <b>AUCTIONEER ONLY!</b>\n\n"
            "Only the auctioneer can assign bidders!",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Parse team name
    if not context.args:
        await update.message.reply_text(
            "Reply to a user with:\n"
            "<code>/bidder [TeamName]</code>\n\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            "<code>/bidder Mumbai Indians</code>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
        return
    
    team_name = " ".join(context.args)
    
    # Get target user
    target_user = None
    if update.message.reply_to_message:
        target_user = update.message.reply_to_message.from_user
    else:
        await update.message.reply_text(
            "⚠️ <b>REPLY REQUIRED!</b>\n\n"
            "Reply to the user you want to assign as bidder!",
            parse_mode=ParseMode.HTML
        )
        return
    
    # ✅ FIX: Auto-register bidder if not in database
    # 🔒 Privacy: only if they've actually started the bot themselves.
    if target_user.id not in user_data and await check_user_started_bot(context.bot, target_user.id):
        user_data[target_user.id] = {
            "user_id": target_user.id,
            "username": target_user.username or "",
            "first_name": target_user.first_name,
            "started_at": datetime.now().isoformat(),
            "total_matches": 0
        }
        init_player_stats(target_user.id)
        save_data()
        logger.info(f"✅ Auto-registered {target_user.first_name} as bidder")
    
    # Create team if not exists
    if team_name not in auction.teams:
        auction.teams[team_name] = AuctionTeam(team_name, starting_purse=auction.default_purse)
    
    team = auction.teams[team_name]
    team.bidder_id = target_user.id
    team.bidder_name = target_user.first_name
    
    target_tag = get_user_tag(target_user)
    
    await update.message.reply_text(
        f"<blockquote>✅ <b>BIDDER ASSIGNED!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🏏 <b>Team:</b> {team_name}\n"
        f"👤 <b>Bidder:</b> {target_tag}\n"
        f"💰 <b>Starting Purse:</b> {auction.default_purse}\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"📊 <b>Total Teams:</b> {len(auction.teams)}\n"
        f"</blockquote>",
        parse_mode=ParseMode.HTML
    )

async def addvc_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """👑 /addvc username/userid/reply [team name] — AUCTIONEER ONLY.
    Directly retains a player into the given team's squad (no bidding, price
    0, tagged RETAINED) and marks them as that team's Vice Captain. Shows up
    in the team's squad immediately and (once /assist vc is turned on) can
    bid on behalf of that team."""
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\nStart an auction first.",
            parse_mode=ParseMode.HTML
        )
        return
    auction = active_auctions[chat.id]

    # Auctioneer-only
    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🎤 <b>AUCTIONEER ONLY!</b>\n\nOnly the auctioneer can add a Vice Captain!",
            parse_mode=ParseMode.HTML
        )
        return

    args = list(context.args) if context.args else []
    usage = (
        "📋 <b>USAGE</b>\n"
        "<code>/addvc</code> (reply to user) <code>[team name]</code>\n"
        "<code>/addvc @username [team name]</code>\n"
        "<code>/addvc 123456789 [team name]</code>\n\n"
        "<code>/addvc @rahul Mumbai Indians</code>"
    )

    target_id = None
    target_name = None

    if update.message.reply_to_message:
        target_user = update.message.reply_to_message.from_user
        target_id = target_user.id
        target_name = target_user.first_name
        team_args = args
    else:
        if not args:
            await update.message.reply_text(usage, parse_mode=ParseMode.HTML)
            return
        first = args[0]
        if first.startswith("@"):
            uname = first[1:].lower()
            found = None
            for uid, data in user_data.items():
                if (data.get("username") or "").lower() == uname:
                    found = uid
                    target_name = data.get("first_name", uname)
                    break
            if not found:
                await update.message.reply_text(
                    "❌ <b>NOT FOUND!</b>\n\nCouldn't resolve that username — try replying to their message, or use their numeric user ID instead.",
                    parse_mode=ParseMode.HTML
                )
                return
            target_id = found
            team_args = args[1:]
        elif first.isdigit():
            target_id = int(first)
            target_name = user_data.get(target_id, {}).get("first_name", str(target_id))
            team_args = args[1:]
        else:
            await update.message.reply_text(usage, parse_mode=ParseMode.HTML)
            return

    if not team_args:
        await update.message.reply_text(usage, parse_mode=ParseMode.HTML)
        return
    team_name = " ".join(team_args)

    if team_name not in auction.teams:
        await update.message.reply_text(
            "❌ <b>TEAM NOT FOUND!</b>\n\nPlease check the team name and try again.",
            parse_mode=ParseMode.HTML
        )
        return
    team = auction.teams[team_name]

    # Auto-register the player if unseen before (same as /bidder)
    # 🔒 Privacy: only if they've actually started the bot themselves.
    if target_id not in user_data and await check_user_started_bot(context.bot, target_id):
        user_data[target_id] = {
            "user_id": target_id,
            "username": "",
            "first_name": target_name or str(target_id),
            "started_at": datetime.now().isoformat(),
            "total_matches": 0
        }
        init_player_stats(target_id)
        save_data()

    # Remove this player from any OTHER team's squad first (a player can only
    # be retained into one team), and clear a stale VC tag if they were VC
    # of a different team before.
    for t in auction.teams.values():
        t.players = [p for p in t.players if p.get('player_id') != target_id]
        if t.vice_captain_id == target_id:
            t.vice_captain_id = None
            t.vice_captain_name = ""

    # Retain into this team — price 0, no purse deducted, like a retention
    if not any(p.get('player_id') == target_id for p in team.players):
        team.players.append({
            "player_id": target_id,
            "player_name": target_name or str(target_id),
            "price": 0,
            "retained": True,
        })

    team.vice_captain_id = target_id
    team.vice_captain_name = target_name or str(target_id)

    target_tag = f'<a href="tg://user?id={target_id}">{html.escape(str(target_name or target_id))}</a>' + _title_suffix(target_id)

    await update.message.reply_text(
        f"<blockquote>👑 <b>VICE CAPTAIN ADDED!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🏏 <b>Team:</b> {html.escape(team_name)}\n"
        f"🎗️ <b>Vice Captain:</b> {target_tag}\n"
        f"📦 <b>Retained into squad</b> (no purse deducted)\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"👥 <b>Squad Size:</b> {len(team.players)}\n"
        f"</blockquote>",
        parse_mode=ParseMode.HTML
    )

async def aucplayer_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🤝 Bulk add players to auction"""
    
    # 🔁 /aucplayer unsold -> re-queue ALL unsold players back into the pool for re-auction
    if context.args and context.args[0].lower() == "unsold":
        chat = update.effective_chat
        user = update.effective_user
        if chat.id not in active_auctions:
            await update.message.reply_text(
                "🚫 <b>NO ACTIVE AUCTION!</b>\n\nStart an auction first with /auction",
                parse_mode=ParseMode.HTML
            )
            return
        auction = active_auctions[chat.id]
        if user.id != auction.auctioneer_id:
            await update.message.reply_text(
                "🚫 <b>AUCTIONEER ONLY!</b>\n\nOnly the auctioneer can re-queue unsold players!",
                parse_mode=ParseMode.HTML
            )
            return
        if not auction.unsold_players:
            await update.message.reply_text(
                "✅ <b>NO UNSOLD PLAYERS!</b>\n\nThere's nothing to re-auction right now.",
                parse_mode=ParseMode.HTML
            )
            return
        count = 0
        for player in auction.unsold_players:
            if isinstance(player, dict):
                auction.player_pool.append(player)
                count += 1
        auction.unsold_players.clear()
        await update.message.reply_text(
            f"<blockquote>🔁 <b>UNSOLD PLAYERS RE-QUEUED!</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            f"📦 <b>Added Back to Pool:</b> {count}\n"
            f"📊 <b>Total Pool Size:</b> {len(auction.player_pool)}\n\n"
            f"They'll come up for bidding again in order.\n"
            f"</blockquote>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # 🧑/👤 Ask whether these are Ideal (imaginary) players or Real (Telegram) players
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\n"
            "Start an auction first with /auction",
            parse_mode=ParseMode.HTML
        )
        return
    auction = active_auctions[chat.id]
    # 🎤 Only Auctioneer can add players
    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🚫 <b>AUCTIONEER ONLY!</b>\n\n"
            "Only the auctioneer can add players!",
            parse_mode=ParseMode.HTML
        )
        return

    if not context.args and not update.message.reply_to_message:
        await update.message.reply_text(
            "📌 <b>BULK ADD PLAYER USAGE</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            "<b>Reply Method:</b>\n"
            "<code>/aucplayer</code>\n\n"
            "<b>Single Player:</b>\n"
            "<code>/aucplayer @username</code>\n\n"
            "<b>Multiple Players:</b>\n"
            "<code>/aucplayer @u1 @u2 @u3</code>\n\n"
            "<b>Using ID:</b>\n"
            "<code>/aucplayer 123456789</code>\n\n"
            "<b>Mixed Method:</b>\n"
            "<code>/aucplayer @u1 123456 @u2</code>\n\n"
            "<b>Ideal (imaginary) Players:</b>\n"
            "<code>/aucplayer rohit virat kohli</code>\n"
            "(choose 🧑 Ideal Player when asked — no user ID/username needed)\n\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
        return

    # Stash the raw command so we know what to do once a mode is picked
    aucplayer_pending[chat.id] = {
        "args": list(context.args) if context.args else [],
        "message": update.message,
        "auctioneer_id": user.id,
    }

    keyboard = [
        [
            styled_button("Ideal Player", callback_data="aucmode_ideal"),
            styled_button("Real Player", callback_data="aucmode_real"),
        ]
    ]
    await update.message.reply_text(
        "🏏 <b>WHAT KIND OF PLAYER(S)?</b>\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        "🧑 <b>Ideal Player</b> — made-up/imaginary players, just names, no Telegram user needed.\n"
        "👤 <b>Real Player</b> — actual Telegram users, needs userid/username/@mention/reply.\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        reply_markup=InlineKeyboardMarkup(keyboard),
        parse_mode=ParseMode.HTML
    )

async def aucplayer_mode_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🧑/👤 Handle Ideal vs Real player mode selection for /aucplayer"""
    query = update.callback_query
    chat = query.message.chat
    user = query.from_user
    pending = aucplayer_pending.get(chat.id)
    if not pending:
        # 🩹 BUGFIX: this used to fire even for a genuine, still-processing
        # first tap — "Real Player" resolves usernames via get_chat() calls
        # (network round-trips) before it can edit the message, so with no
        # visible feedback in that window a lot of hosts double-tapped the
        # same button out of impatience. The FIRST tap had already deleted
        # aucplayer_pending and was quietly working — the second tap just
        # found it gone and wrongly told the host to restart the whole
        # flow. Buttons are now stripped the instant the first tap lands
        # (see below), so a second tap on the same message is no longer
        # even possible in normal use — this alert is now the genuine
        # "actually expired / stale button" case, so the wording no longer
        # implies something went wrong.
        await query.answer(plain_alert("⏳ Already processing (or this button expired). If nothing happens in a few seconds, run /aucplayer again."), show_alert=True)
        return
    # 🔧 CHANGED: dropped the "only the auctioneer who ran /aucplayer can
    # tap this" restriction — for a 100-player bulk add, any teammate
    # helping the auctioneer can now tap Ideal/Real without getting denied.
    # The buttons vanish the instant ANY single tap lands (see below), so
    # two people racing to tap can't double-process either — whoever's tap
    # reaches the server first wins cleanly, the other just sees the
    # "already processing" message above instead of an error.
    await query.answer()

    if chat.id not in active_auctions:
        aucplayer_pending.pop(chat.id, None)
        await query.message.edit_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\nStart an auction first with /auction",
            parse_mode=ParseMode.HTML
        )
        return
    auction = active_auctions[chat.id]

    mode = query.data.split("_", 1)[-1]  # "ideal" or "real"
    args = pending["args"]
    orig_message = pending["message"]
    # 🩹 .pop() not del: if two teammates tap Ideal/Real within the same
    # instant, both can pass the `if not pending` check above before either
    # deletes it. pop(..., None) makes the SECOND one a harmless no-op
    # instead of a KeyError crash — whoever's pop actually returns the
    # dict "wins" and proceeds; the loser's pop returns None and it just
    # falls through to answer/processing text with nothing left to do.
    won_race = aucplayer_pending.pop(chat.id, None) is not None
    if not won_race:
        return

    # 🩹 BUGFIX: strip the buttons + show a "processing" placeholder RIGHT
    # NOW, before the (potentially slow, for Real Player) username lookups
    # below — this is what actually stops the double-tap race described
    # above, since the button physically can't be tapped again once it's
    # gone from the message.
    try:
        await query.message.edit_text(
            "⏳ <b>Processing…</b>\n\nAdding player(s), one moment.",
            parse_mode=ParseMode.HTML
        )
    except Exception:
        pass

    if mode == "ideal":
        await process_ideal_aucplayer(query.message, args, auction)
    else:
        await process_real_aucplayer(query.message, context, orig_message, args, auction)


def _bulk_add_names_block(users_or_names, limit: int = 25) -> str:
    """Render a numbered 'players to add' list, capped at `limit` lines with
    a '+N more' summary after that. Telegram messages have a hard 4096-char
    cap — with a 100-player bulk add, listing every single name could blow
    past that and make edit_text() fail silently (message just never
    updates). Capping the visible list keeps every bulk-add message safe
    regardless of how many players are in it."""
    names = [getattr(u, "first_name", None) or str(u) for u in users_or_names]
    lines = [f" {i}. {html.escape(n)}\n" for i, n in enumerate(names[:limit], 1)]
    block = "".join(lines)
    if len(names) > limit:
        block += f" <i>… and {len(names) - limit} more</i>\n"
    return block


async def process_ideal_aucplayer(reply_target, args, auction):
    """🧑 Add imaginary/ideal players — just names, no userid/username needed"""
    if not args:
        await reply_target.edit_text(
            "📌 <b>IDEAL PLAYER USAGE</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            "<code>/aucplayer rohit</code>\n"
            "<code>/aucplayer rohit virat kohli</code>\n\n"
            "Just give plain names — no @username or userid required.\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
        return

    class IdealUser:
        def __init__(self, name):
            # Negative-range synthetic ID so it never collides with a real Telegram user id
            self.id = -(abs(hash(name.lower())) % 1_000_000_000 + 1)
            self.first_name = name
            self.username = None

    target_users = [IdealUser(name) for name in args]

    # Remove duplicates (by generated id, i.e. by name)
    seen = set()
    unique_users = []
    for u in target_users:
        if u.id not in seen:
            seen.add(u.id)
            unique_users.append(u)

    added = []
    skipped = []
    for target_user in unique_users:
        if auction.player_already_in_auction(target_user.id):
            skipped.append(target_user.first_name)
            continue
        added.append(target_user)

    if not added:
        await reply_target.edit_text(
            f"⚠️ <b>ALL PLAYERS ALREADY IN POOL!</b>\n\n"
            f"⏭️ <b>Skipped:</b> {', '.join(skipped)}",
            parse_mode=ParseMode.HTML
        )
        return

    if not hasattr(auction, "pending_bulk_add"):
        auction.pending_bulk_add = []
    auction.pending_bulk_add = added
    # 🩹 BUGFIX: see process_real_aucplayer for the full explanation — this
    # used to unconditionally overwrite phase, which broke live bidding
    # when /addauctionplayer (Ideal mode) was used MID-AUCTION. Remember
    # the real phase so bulk_base_price_callback can restore it.
    auction._phase_before_bulk_add = auction.phase
    auction.phase = AuctionPhase.PLAYER_ADDITION

    keyboard = [
        [
            styled_button("Base: 10", callback_data="bulk_base_10"),
            styled_button("Base: 20", callback_data="bulk_base_20")
        ],
        [
            styled_button("Base: 30", callback_data="bulk_base_30"),
            styled_button("Base: 50", callback_data="bulk_base_50")
        ]
    ]
    msg = f"📦 <b>BULK ADD → {len(added)} IDEAL PLAYERS</b>\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += "🧑 <b>Players to Add:</b>\n"
    msg += _bulk_add_names_block(added)
    if skipped:
        msg += "\n⚠️ <b>Skipped (Already in pool):</b>\n"
        msg += f" {', '.join(skipped[:25])}"
        if len(skipped) > 25:
            msg += f" <i>… and {len(skipped) - 25} more</i>"
        msg += "\n"
    msg += "\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += "💰 <b>Select Base Price (Same for All):</b>"
    await reply_target.edit_text(
        msg,
        reply_markup=InlineKeyboardMarkup(keyboard),
        parse_mode=ParseMode.HTML
    )

async def process_real_aucplayer(reply_target, context, orig_message, args, auction):
    """👤 Add real Telegram-user players via @mention / username / userid / reply"""
    target_users = []
    chat_id = orig_message.chat.id
    # Method 1: Reply -> Add that user
    if orig_message.reply_to_message:
        target_users.append(orig_message.reply_to_message.from_user)

    # 🚀 SPEED/RELIABILITY FIX: with a 100-player bulk add, resolving every
    # @username / userid with a fully SEQUENTIAL await get_chat() per player
    # could take 1-2+ minutes and made it easy to trip Telegram's flood
    # limits on rapid identical-endpoint calls (each failure just silently
    # dropped that one player with no clear feedback). These now resolve
    # CONCURRENTLY (capped at 8 at once, so we still stay well under
    # Telegram's rate limits) and a flood-wait (RetryAfter) is honored with
    # a single retry instead of just dropping the player.
    _resolve_sem = asyncio.Semaphore(8)
    # 🩹 BUGFIX: neither @username nor numeric-ID resolution below actually
    # worked for anyone who hadn't /start'd the bot — get_chat() only
    # succeeds for users the bot already has a record of (a prior DM), so
    # someone sitting right there in the group with a public username still
    # silently failed to resolve and just vanished from the bulk add, with
    # no error explaining why. /add's resolver (_resolve_user_in_chat)
    # already solved this properly: get_chat_member(chat_id, uid) works for
    # ANY current group member regardless of bot-start status. Try that
    # first here too — via a user_data username→id hint, or by scanning
    # the group's admin list as a last resort for a username we have no
    # cached id for — before ever falling back to the bot-start-dependent
    # get_chat().
    unresolved_usernames = []

    async def _resolve_mention(username: str):
        async with _resolve_sem:
            uid_hint = None
            for uid, data in user_data.items():
                if data.get("username", "").lower() == username.lower():
                    uid_hint = uid
                    break
            # Try 1: resolve within THIS group — works for any current
            # member, started-bot or not, as long as we already have (or can
            # find) their numeric id.
            if uid_hint is not None:
                try:
                    member = await context.bot.get_chat_member(chat_id, uid_hint)
                    if not member.user.is_bot:
                        return member.user
                except Exception:
                    pass
            # Try 2: some group admins are resolvable by username directly
            # via get_chat_administrators, with no id hint needed at all.
            try:
                admins = await context.bot.get_chat_administrators(chat_id)
                for a in admins:
                    if (a.user.username or "").lower() == username.lower() and not a.user.is_bot:
                        return a.user
            except Exception:
                pass
            # Try 3: direct fetch by username (only works if the bot already
            # has a record of them from a prior DM elsewhere).
            try:
                return await context.bot.get_chat(f"@{username}")
            except RetryAfter as e:
                await asyncio.sleep(e.retry_after + 0.5)
                try:
                    return await context.bot.get_chat(f"@{username}")
                except Exception as e2:
                    logger.warning(f"Could not fetch @{username} after flood-wait retry: {e2}")
            except Exception as e:
                logger.warning(f"Could not fetch @{username} directly: {e}")

            if uid_hint is not None:
                class BasicUser:
                    def __init__(self, uid, uname, fname):
                        self.id = int(uid)
                        self.first_name = fname
                        self.username = uname
                        self.is_bot = False
                return BasicUser(uid_hint, username, user_data.get(uid_hint, {}).get("first_name", "Player"))
            unresolved_usernames.append(username)
            logger.warning(f"User @{username} not found in database or group")
            return None

    async def _resolve_id(arg: str):
        async with _resolve_sem:
            uid_int = int(arg)
            # Try 1: resolve within THIS group first — works even if they
            # never started the bot, as long as they're a current member.
            try:
                member = await context.bot.get_chat_member(chat_id, uid_int)
                if not member.user.is_bot:
                    return member.user
            except Exception:
                pass
            try:
                return await context.bot.get_chat(uid_int)
            except RetryAfter as e:
                await asyncio.sleep(e.retry_after + 0.5)
                try:
                    return await context.bot.get_chat(uid_int)
                except Exception as e2:
                    logger.warning(f"Could not fetch user with ID {arg} after flood-wait retry: {e2}")
            except Exception as e:
                logger.warning(f"Could not fetch user with ID {arg}: {e}")
            class BasicUser:
                def __init__(self, uid):
                    self.id = int(uid)
                    self.first_name = f"Player_{uid}"
                    self.username = None
                    self.is_bot = False
            return BasicUser(arg)

    resolve_tasks = []
    # Method 2: Mentions / Text Mentions / IDs
    if orig_message.entities or args:
        if orig_message.entities:
            for entity in orig_message.entities:
                if entity.type == "mention":
                    username = orig_message.text[entity.offset:entity.offset + entity.length].replace("@", "")
                    resolve_tasks.append(_resolve_mention(username))
                elif entity.type == "text_mention":
                    target_users.append(entity.user)
        if args:
            for arg in args:
                if arg.isdigit():
                    resolve_tasks.append(_resolve_id(arg))

    if resolve_tasks:
        resolved = await asyncio.gather(*resolve_tasks, return_exceptions=True)
        for r in resolved:
            if r is not None and not isinstance(r, Exception):
                target_users.append(r)

    if not target_users:
        if unresolved_usernames:
            await reply_target.edit_text(
                "🚫 <b>COULDN'T RESOLVE ANY USERNAME!</b>\n"
                "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
                f"⚠️ Not found: {', '.join('@'+u for u in unresolved_usernames)}\n\n"
                "They need to be a current member of this group (or have DM'd the bot once) "
                "for the username to resolve. If they're in the group, try their numeric "
                "user ID instead, or reply directly to one of their messages.\n"
                "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
                parse_mode=ParseMode.HTML
            )
            return
        await reply_target.edit_text(
            "📌 <b>BULK ADD PLAYER USAGE</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            "<b>Reply Method:</b>\n"
            "<code>/aucplayer</code>\n\n"
            "<b>Single Player:</b>\n"
            "<code>/aucplayer @username</code>\n\n"
            "<b>Multiple Players:</b>\n"
            "<code>/aucplayer @u1 @u2 @u3</code>\n\n"
            "<b>Using ID:</b>\n"
            "<code>/aucplayer 123456789</code>\n\n"
            "<b>Mixed Method:</b>\n"
            "<code>/aucplayer @u1 123456 @u2</code>\n\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
        return
    # Remove duplicates
    seen = set()
    unique_users = []
    for u in target_users:
        if u.id not in seen:
            seen.add(u.id)
            unique_users.append(u)
    # Process each user
    added = []
    skipped = []
    for target_user in unique_users:
        # Check if already in auction (pool, already sold, or already unsold)
        if auction.player_already_in_auction(target_user.id):
            skipped.append(target_user.first_name)
            continue
        
        # ✅ AUTO-REGISTER: only persist a profile for players who've actually
        # started the bot themselves (🔒 privacy) — others still join the
        # auction pool below (in-memory) without leaving a DB record.
        _started_for_auction = await check_user_started_bot(context.bot, target_user.id)
        if _started_for_auction and target_user.id not in user_data:
            user_data[target_user.id] = {
                "user_id": target_user.id,
                "username": getattr(target_user, 'username', None) or "",
                "first_name": getattr(target_user, 'first_name', None) or "Player",
                "started_at": datetime.now().isoformat(),
                "total_matches": 0
            }
            logger.info(f"✅ Auto-registered {target_user.first_name or 'Unknown'} (ID: {target_user.id}) for auction")
        
        # Initialize stats if not present
        if _started_for_auction and target_user.id not in player_stats:
            init_player_stats(target_user.id)
            save_data()
            logger.info(f"✅ Initialized stats for {target_user.first_name or 'Unknown'}")
        
        added.append(target_user)
    if not added:
        await reply_target.edit_text(
            f"⚠️ <b>ALL PLAYERS ALREADY IN POOL!</b>\n\n"
            f"⏭️ <b>Skipped:</b> {', '.join(skipped)}",
            parse_mode=ParseMode.HTML
        )
        return
    # Store pending bulk players
    if not hasattr(auction, "pending_bulk_add"):
        auction.pending_bulk_add = []
    auction.pending_bulk_add = added
    # 🩹 BUGFIX: this used to unconditionally set phase=PLAYER_ADDITION,
    # which — when /addauctionplayer is used MID-AUCTION while a player is
    # already up for live bidding (phase == AUCTION_LIVE) — silently broke
    # bidding: /bid and the quick-bid buttons both require
    # phase == AUCTION_LIVE, so every bid started getting rejected with
    # "BIDDING NOT OPEN", is_paused was never set (so /resumeauction had
    # nothing to resume), and current_player_id stayed set (so /nextplayer
    # refused with "player already up for bidding"). The auction looked
    # completely stuck with no error and no obvious recovery. Now we just
    # remember whatever phase we were actually in and hand it back to
    # bulk_base_price_callback to restore once the pool-add is done.
    auction._phase_before_bulk_add = auction.phase
    auction.phase = AuctionPhase.PLAYER_ADDITION
    # Base price options
    keyboard = [
        [
            styled_button("Base: 10", callback_data="bulk_base_10"),
            styled_button("Base: 20", callback_data="bulk_base_20")
        ],
        [
            styled_button("Base: 30", callback_data="bulk_base_30"),
            styled_button("Base: 50", callback_data="bulk_base_50")
        ]
    ]
    msg = f"📦 <b>BULK ADD → {len(added)} PLAYERS</b>\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += "🎯 <b>Players to Add:</b>\n"
    msg += _bulk_add_names_block(added)
    if skipped:
        msg += "\n⚠️ <b>Skipped (Already in pool):</b>\n"
        msg += f" {', '.join(skipped[:25])}"
        if len(skipped) > 25:
            msg += f" <i>… and {len(skipped) - 25} more</i>"
        msg += "\n"
    if unresolved_usernames:
        msg += "\n🚫 <b>Couldn't resolve (not in this group / never messaged the bot):</b>\n"
        msg += f" {', '.join('@'+u for u in unresolved_usernames[:25])}"
        if len(unresolved_usernames) > 25:
            msg += f" <i>… and {len(unresolved_usernames) - 25} more</i>"
        msg += "\n"
    msg += "\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += "💰 <b>Select Base Price (Same for All):</b>"
    await reply_target.edit_text(
        msg,
        reply_markup=InlineKeyboardMarkup(keyboard),
        parse_mode=ParseMode.HTML
    )

async def bulk_base_price_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """💰 Handle bulk base price selection"""
    query = update.callback_query
    await query.answer()
    chat = query.message.chat
    if chat.id not in active_auctions:
        return
    auction = active_auctions[chat.id]
    if not hasattr(auction, "pending_bulk_add") or not auction.pending_bulk_add:
        await query.message.edit_text(
            "🚫 <b>NO PENDING PLAYERS!</b>\n\n"
            "No players to add.",
            parse_mode=ParseMode.HTML
        )
        return
    # Extract base price
    price = int(query.data.split("_")[-1])
    # Add players to pool
    added_count = 0
    resold_skipped = []
    for target_user in auction.pending_bulk_add:
        # 🩹 BUGFIX: re-check right at commit time, not just when the bulk
        # list was first built — the confirmation step (picking a base
        # price) takes real time, during which the player could've been
        # sold/unsold via a live match happening in parallel. Re-checking
        # here closes that gap instead of trusting a stale "not a duplicate"
        # verdict from a minute or more ago.
        if auction.player_already_in_auction(target_user.id):
            resold_skipped.append(target_user.first_name)
            continue
        auction.player_pool.append({
            "player_id": target_user.id,
            "player_name": target_user.first_name,
            "base_price": price
        })
        added_count += 1
    # Clear pending buffer
    auction.pending_bulk_add = []
    # 🩹 BUGFIX: restore whatever phase the auction was actually in before
    # this bulk-add started, instead of blindly forcing BIDDER_SELECTION.
    # If a player was live for bidding (phase == AUCTION_LIVE) when
    # /addauctionplayer was used mid-auction, this puts bidding back the
    # way it was — /bid and quick-bid buttons work again immediately, no
    # /nextplayer or /resumeauction needed.
    restore_phase = getattr(auction, '_phase_before_bulk_add', None)
    if hasattr(auction, '_phase_before_bulk_add'):
        del auction._phase_before_bulk_add
    auction.phase = restore_phase if restore_phase is not None else AuctionPhase.BIDDER_SELECTION
    _mid_live_note = (
        "\n🔴 <b>Live bidding continues unaffected!</b>" if restore_phase == AuctionPhase.AUCTION_LIVE else ""
    )
    _resold_note = (
        f"\n⚠️ <b>Skipped (became sold/unsold while you were choosing a price):</b> {', '.join(resold_skipped)}"
        if resold_skipped else ""
    )
    await query.message.edit_text(
        f"✅ <b>BULK ADD COMPLETE!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        f"📦 <b>Players Added:</b> {added_count}\n"
        f"💰 <b>Base Price:</b> {price} (Each)\n\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"📊 <b>Total Pool Size:</b> {len(auction.player_pool)}"
        f"{_mid_live_note}"
        f"{_resold_note}\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        parse_mode=ParseMode.HTML
    )

