async def notify_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔔 /notify — Subscribe (in a group) to a DM whenever someone starts a game
    in this group. Subscription auto-expires after GROUP_NOTIFY_EXPIRY_DAYS."""
    chat = update.effective_chat
    user = update.effective_user

    if chat.type == "private":
        await update.message.reply_text("⚠️ Use /notify inside a group to subscribe to its game-start alerts.")
        return

    subs = group_notify_subscribers.setdefault(str(chat.id), {})
    if str(user.id) in subs:
        await update.message.reply_text(
            f"🔔 You're already subscribed to game-start alerts for <b>{html.escape(chat.title or 'this group')}</b>.\n"
            f"<i>Use /notify again after it expires (in {GROUP_NOTIFY_EXPIRY_DAYS} days) to renew.</i>",
            parse_mode=ParseMode.HTML
        )
        return

    subs[str(user.id)] = datetime.now().isoformat()
    save_data()

    try:
        await context.bot.send_message(
            user.id,
            f"🔔 <b>Subscribed!</b>\nYou'll get a DM whenever a game starts in "
            f"<b>{html.escape(chat.title or 'this group')}</b> for the next {GROUP_NOTIFY_EXPIRY_DAYS} days.",
            parse_mode=ParseMode.HTML
        )
        await update.message.reply_text(f"✅ {user.first_name}, you'll be notified in DM when a game starts here (valid {GROUP_NOTIFY_EXPIRY_DAYS} days).")
    except Exception:
        await update.message.reply_text(
            "⚠️ Subscribed, but I couldn't DM you — please start the bot in DM first so I can notify you.",
            parse_mode=ParseMode.HTML
        )


async def notify_group_game_started(context: ContextTypes.DEFAULT_TYPE, group_id: int, group_title: str) -> None:
    """📣 DMs everyone subscribed via /notify for this group that a game has started —
    skips/removes subscriptions older than GROUP_NOTIFY_EXPIRY_DAYS."""
    subs = group_notify_subscribers.get(str(group_id), {})
    if not subs:
        return

    now = datetime.now()
    expired = []
    keyboard = InlineKeyboardMarkup([[
        styled_button("Stop notifying me", callback_data=f"groupnotify_stop_{group_id}")
    ]])

    for uid_str, ts in list(subs.items()):
        try:
            subscribed_at = datetime.fromisoformat(ts)
        except Exception:
            expired.append(uid_str)
            continue
        if (now - subscribed_at).days > GROUP_NOTIFY_EXPIRY_DAYS:
            expired.append(uid_str)
            continue
        try:
            await context.bot.send_message(
                int(uid_str),
                f"🏏 <b>A game just started!</b>\n"
                f"📍 Group: <b>{html.escape(group_title or 'Group')}</b>\n"
                f"<i>Join in if you're free!</i>",
                parse_mode=ParseMode.HTML,
                reply_markup=keyboard
            )
        except Exception:
            pass

    if expired:
        for uid_str in expired:
            subs.pop(uid_str, None)
        save_data()


async def groupnotify_stop_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔕 groupnotify_stop_{group_id} — unsubscribe from that group's game-start alerts."""
    query = update.callback_query
    user = query.from_user
    group_id = query.data.split("_")[-1]

    subs = group_notify_subscribers.get(group_id, {})
    subs.pop(str(user.id), None)
    save_data()

    await query.answer("🔕 You won't be notified for this group anymore.", show_alert=True)
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass


async def _resolve_user_in_chat(context: ContextTypes.DEFAULT_TYPE, chat_id: int, arg: str, uid_hint: Optional[int] = None):
    """🔧 BUGFIX: robust resolver for /add /remove /shift that no longer depends
    on the target having /start'd the bot.

    Telegram's `get_chat` only succeeds for users the bot already has some
    record of (i.e. they DM'd the bot at some point) — that's why plain
    @username / user_id lookups were silently failing (and dropping) for
    anyone who hadn't pressed /start, which is exactly what bulk /add was
    failing on. `get_chat_member(chat_id, user_id)` has no such requirement:
    it works for ANY member currently in the group, started-bot or not, as
    long as the bot itself is in that group. We try that first and only
    fall back to get_chat for the (rarer) case of a public username outside
    this chat.
    """
    if uid_hint is not None:
        try:
            member = await context.bot.get_chat_member(chat_id, uid_hint)
            u = member.user
            if not u.is_bot:
                return (u.id, u.username or "", u.first_name or str(u.id))
        except Exception:
            pass
    try:
        chat_obj = await context.bot.get_chat(arg)
        return (chat_obj.id, chat_obj.username or "", chat_obj.first_name or arg.lstrip("@"))
    except Exception:
        return None


async def _collect_add_remove_targets(update: Update, context: ContextTypes.DEFAULT_TYPE) -> list:
    """Shared target parser for /add, /remove, /shift: supports reply-to-message,
    @username, plain-text @mentions, text_mentions (tagged users w/o a username),
    and numeric user_id — with dedup. Returns list of (user_id, username, first_name).

    🔧 Doesn't matter if the tagged player has ever /start'd the bot: text_mention
    entities carry Telegram's own User object (used when Telegram tags someone who
    has no username), a plain numeric user_id is resolved via get_chat_member
    (works for any current group member regardless of bot-start), and @username
    falls back the same way once we know the id, or via get_chat as a last resort.
    """
    targets = []
    failed = []
    chat_id = update.effective_chat.id

    # 1) Reply target — always available from Telegram directly.
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        ru = update.message.reply_to_message.from_user
        if not ru.is_bot:
            targets.append((ru.id, ru.username or "", ru.first_name or str(ru.id)))

    # 2) text_mention entities in the command text — Telegram hands us the full
    # User object for these (used when a user has no @username to tag by), so
    # no /start or user_data lookup is needed at all.
    for entity in (update.message.entities or []):
        if entity.type == "text_mention" and entity.user and not entity.user.is_bot:
            eu = entity.user
            targets.append((eu.id, eu.username or "", eu.first_name or str(eu.id)))

    # 3) Plain args: @username or numeric user_id — resolved against the
    # group itself first (get_chat_member), so it works even if that player
    # has never opened a DM with the bot.
    for arg in (context.args or []):
        if arg.startswith("@"):
            uname = arg[1:].lower()
            uid_hint = None
            for uid, data in user_data.items():
                if data.get("username", "").lower() == uname:
                    uid_hint = uid
                    break
            resolved = await _resolve_user_in_chat(context, chat_id, arg, uid_hint)
            if resolved:
                targets.append(resolved)
            else:
                failed.append(arg)
        elif arg.lstrip("-").isdigit():
            uid_int = int(arg)
            resolved = await _resolve_user_in_chat(context, chat_id, str(uid_int), uid_int)
            if resolved:
                targets.append(resolved)
            else:
                failed.append(arg)

    seen = set()
    unique_targets = []
    for t in targets:
        if t[0] not in seen:
            seen.add(t[0])
            unique_targets.append(t)

    # 🔧 Surface anything that couldn't be resolved instead of silently
    # dropping it — this was the "some bulk-add players just don't show up,
    # no error" complaint. Most likely cause if this fires: that user isn't
    # currently a member of this group.
    if failed:
        try:
            await update.message.reply_text(
                f"⚠️ Couldn't resolve: {', '.join(failed)} — make sure they're in this group.",
            )
        except Exception:
            pass

    return unique_targets


async def add_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """➕ Smart add: editing phase -> uses editing_team; live match -> reply or /add @user1 @user2 then team picker"""
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_matches:
        await update.message.reply_text(themed("🚫 NO MATCH", ["No active match found."], "🚫"), parse_mode=ParseMode.HTML)
        return
    match = active_matches[chat.id]

    # ── SOLO MODE: /add is disabled — use /join instead (host approves via buttons) ──
    if getattr(match, "game_mode", "TEAM") in ("SOLO", "MAGICBALL") and match.phase == GamePhase.SOLO_MATCH:
        await update.message.reply_text(
            themed("ℹ️ USE /join INSTEAD", [
                "<code>/add</code> isn't available in Solo Mode.",
                "Player should send <code>/join</code> — host gets Accept/Reject buttons.",
            ], "ℹ️"),
            parse_mode=ParseMode.HTML
        )
        return

    # ── EDITING PHASE, TEAM EDIT LOBBY, or LIVE MATCH — same bulk add + team-picker flow ──
    if match.phase not in (GamePhase.TEAM_JOINING, GamePhase.TEAM_EDIT, GamePhase.MATCH_IN_PROGRESS):
        await update.message.reply_text(themed("⚠️ WRONG PHASE", ["Cannot add players in the current match phase."], "⚠️"), parse_mode=ParseMode.HTML)
        return

    if user.id != match.host_id:
        await update.message.reply_text(themed("🚧 HOST ONLY", ["Only the host can add players mid-game."], "🚧"), parse_mode=ParseMode.HTML)
        return

    # Collect target users: reply + text_mentions + @username/user_id args
    # (mass support; resolves players even if they've never /start'd the bot).
    targets = await _collect_add_remove_targets(update, context)

    if not targets:
        await update.message.reply_text(
            themed("➕ ADD PLAYER(S)", [
                "Reply to a message + <code>/add</code>",
                "By tag/username (mass): <code>/add @u1 @u2 ...</code>",
                "By user ID (mass): <code>/add id1 id2 ...</code>",
                "Works even if they never started the bot.",
            ], "➕"),
            parse_mode=ParseMode.HTML
        )
        return

    # Filter out already-in-team players
    valid_targets = []
    already_in = []
    banned_names = []
    for (uid, uname, fname) in targets:
        if is_user_banned(uid):
            banned_names.append(fname)
        elif match.team_x.get_player(uid) or match.team_y.get_player(uid):
            already_in.append(fname)
        else:
            valid_targets.append((uid, uname, fname))

    warning_parts = []
    if banned_names:
        warning_parts.append(f"🚫 Banned from the bot (can't be added): {html.escape(', '.join(banned_names))}")
    if already_in:
        warning_parts.append(f"⚠️ Already in a team: {', '.join(already_in)}")
    warning = "\n".join(warning_parts)

    if not valid_targets:
        if banned_names:
            await update.message.reply_text(
                themed("🚫 USER BANNED", [
                    "\n".join(f"<b>{html.escape(n)}</b> is banned from the bot." for n in banned_names),
                    "They can't be added to any game.",
                ], "🚫"),
                parse_mode=ParseMode.HTML
            )
        else:
            await update.message.reply_text(
                themed("⚠️ NOTHING TO ADD", [warning or "All mentioned players are already in a team."], "⚠️"),
                parse_mode=ParseMode.HTML
            )
        return

    # Store pending in bot_data
    pending_key = f"addpending_{chat.id}_{user.id}"
    context.bot_data[pending_key] = valid_targets  # list of (uid, uname, fname)

    names_display = ", ".join(f"<b>{html.escape(t[2])}</b>" for t in valid_targets)

    keyboard = InlineKeyboardMarkup([[
        styled_button(f"{match.team_x.name}", callback_data=f"addpick_X_{chat.id}_{user.id}"),
        styled_button(f"{match.team_y.name}", callback_data=f"addpick_Y_{chat.id}_{user.id}"),
    ]])

    add_lines = [f"👤 Player(s): {names_display}"]
    if warning:
        add_lines.append(warning)
    add_lines.append("👇 Choose their team:")

    await update.message.reply_text(
        themed("➕ CHOOSE TEAM", add_lines, "➕"),
        parse_mode=ParseMode.HTML,
        reply_markup=keyboard
    )


async def addpick_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle team picker for /add command"""
    query = update.callback_query
    await query.answer()
    user = query.from_user
    parts = query.data.split("_")
    # addpick_X_chatid_userid
    if len(parts) < 4:
        await query.answer(plain_alert("❌ Invalid data."), show_alert=True)
        return
    team_letter = parts[1]
    try:
        chat_id = int(parts[2])
        host_id = int(parts[3])
    except (ValueError, IndexError):
        await query.answer(plain_alert("❌ Invalid data."), show_alert=True)
        return

    if user.id != host_id:
        await query.answer(plain_alert("🚫 Only the host can pick the team!"), show_alert=True)
        return

    if chat_id not in active_matches:
        await query.message.edit_text(themed("❌ NO MATCH", ["No active match."], "❌"), parse_mode=ParseMode.HTML)
        return
    match = active_matches[chat_id]
    team = match.team_x if team_letter == "X" else match.team_y

    pending_key = f"addpending_{chat_id}_{host_id}"
    targets = context.bot_data.pop(pending_key, [])

    if not targets:
        await query.message.edit_text(themed("⚠️ SESSION EXPIRED", ["Please use /add again."], "⚠️"), parse_mode=ParseMode.HTML)
        return

    added = []
    skipped = []
    banned_skipped = []

    for (uid, uname, fname) in targets:
        if is_user_banned(uid):
            banned_skipped.append(fname)
            continue
        if match.team_x.get_player(uid) or match.team_y.get_player(uid):
            skipped.append(fname)
            continue
        # 🔒 Privacy: only persist a profile for players who've started the bot.
        if uid not in user_data and await check_user_started_bot(context.bot, uid):
            user_data[uid] = {
                "user_id": uid, "username": uname, "first_name": fname,
                "started_at": datetime.now().isoformat(), "total_matches": 0
            }
            init_player_stats(uid)
            save_data()
        new_player = Player(uid, uname, fname)
        team.add_player(new_player)
        added.append(fname)

    lines = [f"🎯 Added to Team {team_letter} ({html.escape(team.name)}): " + (", ".join(f"<b>{html.escape(n)}</b>" for n in added) if added else "None")]
    if skipped:
        lines.append(f"⚠️ Already in team (skipped): {', '.join(skipped)}")
    if banned_skipped:
        lines.append(f"🚫 Banned from the bot (not added): {html.escape(', '.join(banned_skipped))}")
    lines.append(f"📊 Team size: <b>{len(team.players)}</b>")

    await query.message.edit_text(
        themed("✅ PLAYER(S) ADDED", lines, "✅"),
        parse_mode=ParseMode.HTML
    )

    if match.phase == GamePhase.TEAM_EDIT:
        await update_team_edit_message(context, chat_id, match)


async def remove_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """➖ /remove [serial_number] — then choose which team via buttons."""
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_matches:
        await update.message.reply_text(
            themed("🚫 NO MATCH", ["No active match found."], "❌"),
            parse_mode=ParseMode.HTML
        )
        return
    match = active_matches[chat.id]

    # ── SOLO MODE: /remove is disabled — solo lineup is managed via /join (host approves) ──
    if getattr(match, "game_mode", "TEAM") in ("SOLO", "MAGICBALL") and match.phase == GamePhase.SOLO_MATCH:
        await update.message.reply_text(
            themed("ℹ️ USE /join INSTEAD", [
                "<code>/remove</code> isn't available in Solo Mode.",
                "Reject a <code>/join</code> request instead of removing someone after.",
            ], "ℹ️"),
            parse_mode=ParseMode.HTML
        )
        return

    # ── EDITING PHASE, TEAM EDIT LOBBY, or LIVE MATCH — same flow (serial, reply, @username, user_id, tag; bulk supported) ──
    if match.phase not in (GamePhase.TEAM_JOINING, GamePhase.TEAM_EDIT, GamePhase.MATCH_IN_PROGRESS):
        await update.message.reply_text(
            themed("⚠️ WRONG PHASE", ["Cannot remove players in the current match phase."], "⚠️"),
            parse_mode=ParseMode.HTML
        )
        return

    if user.id != match.host_id:
        await update.message.reply_text(
            themed("🚧 HOST ONLY", ["Only the <b>host</b> can remove players mid-game."], "🚧"),
            parse_mode=ParseMode.HTML
        )
        return

    # ── Bulk removal via reply / @username / tag(text_mention) / user_id — no
    # team picker needed, the player's current team is detected automatically.
    # Small plain numbers (no @, not from a reply/tag, < 1000) are treated as
    # SERIAL NUMBERS instead — bulk supported too, e.g. /remove 1 5, since
    # real Telegram user IDs are much larger than a squad's serial numbers
    # ever will be. ──
    bulk_targets = []
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        ru = update.message.reply_to_message.from_user
        if not ru.is_bot:
            bulk_targets.append((ru.id, ru.username or "", ru.first_name or str(ru.id)))
    for entity in (update.message.entities or []):
        if entity.type == "text_mention" and entity.user and not entity.user.is_bot:
            eu = entity.user
            bulk_targets.append((eu.id, eu.username or "", eu.first_name or str(eu.id)))

    serials = []
    for arg in (context.args or []):
        if arg.startswith("@"):
            uname = arg[1:].lower()
            uid_hint = None
            for uid, data in user_data.items():
                if data.get("username", "").lower() == uname:
                    uid_hint = uid
                    break
            # 🔧 same fix as /add: resolve via get_chat_member first so this
            # works even for group members who never /start'd the bot.
            resolved = await _resolve_user_in_chat(context, chat.id, arg, uid_hint)
            if resolved:
                bulk_targets.append(resolved)
        elif arg.lstrip("-").isdigit():
            num = int(arg)
            if num >= 1000:
                uid_int = num
                resolved = await _resolve_user_in_chat(context, chat.id, str(uid_int), uid_int)
                if resolved:
                    bulk_targets.append(resolved)
                else:
                    bulk_targets.append((uid_int, "", str(uid_int)))
            else:
                serials.append(num)

    seen = set()
    bulk_targets = [t for t in bulk_targets if not (t[0] in seen or seen.add(t[0]))]

    # Resolve bulk serial numbers (e.g. "/remove 1 5") against both teams —
    # only used when nothing else (reply/tag/@username/user_id) was given,
    # so a lone "/remove 3" still falls through to the old team-picker flow
    # below (ambiguous which team serial #3 refers to).
    if serials and not bulk_targets and len(serials) > 1:
        for s in serials:
            px = match.team_x.players[s - 1] if 0 < s <= len(match.team_x.players) else None
            py = match.team_y.players[s - 1] if 0 < s <= len(match.team_y.players) else None
            if px:
                bulk_targets.append((px.user_id, getattr(px, "username", "") or "", px.first_name))
            if py:
                bulk_targets.append((py.user_id, getattr(py, "username", "") or "", py.first_name))
        seen = set()
        bulk_targets = [t for t in bulk_targets if not (t[0] in seen or seen.add(t[0]))]

    if bulk_targets:
        removed, not_found, blocked_host, blocked_active = [], [], [], []
        for (uid, uname, fname) in bulk_targets:
            team_letter = None
            if match.team_x.get_player(uid):
                team_letter = "X"
            elif match.team_y.get_player(uid):
                team_letter = "Y"
            if team_letter is None:
                not_found.append(fname)
                continue
            if uid == match.host_id:
                blocked_host.append(fname)
                continue
            team = match.team_x if team_letter == "X" else match.team_y
            # 🩹 BUGFIX: remove_player_team_callback (the single-serial /remove
            # flow) explicitly blocks removing whoever is currently batting or
            # bowling — because Team.remove_player() resets their idx to None,
            # and nothing in either removal path then prompts for a
            # replacement striker/bowler. That left the match with no one
            # able to act and no timer running — frozen until manual
            # /endmatch. This bulk path (reply/@username/user-id/multi-serial)
            # never had that guard at all. Match the single-serial behavior.
            if team is match.current_batting_team and match.phase == GamePhase.MATCH_IN_PROGRESS:
                s_id = team.players[team.current_batsman_idx].user_id if team.current_batsman_idx is not None else None
                ns_id = team.players[team.current_non_striker_idx].user_id if team.current_non_striker_idx is not None else None
                if uid in (s_id, ns_id):
                    blocked_active.append(f"{fname} (batting)")
                    continue
            if team is match.current_bowling_team and match.phase == GamePhase.MATCH_IN_PROGRESS:
                b_id = team.players[team.current_bowler_idx].user_id if team.current_bowler_idx is not None else None
                if uid == b_id:
                    blocked_active.append(f"{fname} (bowling)")
                    continue
            team.remove_player(uid)
            removed.append(f"{fname} (Team {team_letter})")

        lines = []
        if removed:
            lines.append(f"🎯 Removed: {', '.join(removed)}")
        if blocked_host:
            lines.append(f"🚧 Host can't remove themselves mid-match: {', '.join(blocked_host)}")
        if blocked_active:
            lines.append(f"🚧 Currently batting/bowling, can't remove: {', '.join(blocked_active)}")
        if not_found:
            lines.append(f"⚠️ Not found in any team: {', '.join(not_found)}")
        await update.message.reply_text(
            themed("➖ REMOVED", lines or ["Nothing to remove."], "➖"),
            parse_mode=ParseMode.HTML
        )
        if match.phase == GamePhase.TEAM_EDIT:
            await update_team_edit_message(context, chat.id, match)
        return

    if not context.args:
        await update.message.reply_text(
            themed("📋 REMOVE PLAYER", [
                "<code>/remove [serial]</code> — pick team via buttons",
                "Bulk: <code>/remove</code> (reply), <code>/remove @u1 @u2</code>, <code>/remove id1 id2</code>, <code>/remove 1 5</code>",
                "🧊 Team X: " + (", ".join(f"{i}.{p.first_name}" for i, p in enumerate(match.team_x.players, 1)) or "—"),
                "🔥 Team Y: " + (", ".join(f"{i}.{p.first_name}" for i, p in enumerate(match.team_y.players, 1)) or "—"),
            ], "📋"),
            parse_mode=ParseMode.HTML
        )
        return

    try:
        serial = int(context.args[0])
    except ValueError:
        await update.message.reply_text(
            themed("❌ INVALID", ["Give a valid serial number. Example: <code>/remove 3</code>"], "❌"),
            parse_mode=ParseMode.HTML
        )
        return

    # Show team selection buttons
    preview_lines = [
        f"🔢 Serial: <b>#{serial}</b> — choose the team:",
        "🧊 Team X: " + (match.team_x.players[serial - 1].first_name if 0 < serial <= len(match.team_x.players) else "—"),
        "🔥 Team Y: " + (match.team_y.players[serial - 1].first_name if 0 < serial <= len(match.team_y.players) else "—"),
    ]
    keyboard = InlineKeyboardMarkup([[
        styled_button("Team X", callback_data=f"remove_player_X_{chat.id}_{serial}"),
        styled_button("Team Y", callback_data=f"remove_player_Y_{chat.id}_{serial}"),
    ]])
    await update.message.reply_text(
        themed("➖ REMOVE PLAYER", preview_lines, "➖"),
        parse_mode=ParseMode.HTML,
        reply_markup=keyboard
    )


async def shift_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔀 /shift @username or /shift user_id (or reply) — auto-detects which
    team a player is currently in and moves them to the OTHER team. Works
    both during Team Edit (lobby) and mid-game (Team Mode)."""
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_matches:
        await update.message.reply_text(themed("🚫 NO MATCH", ["No active match found."], "🚫"), parse_mode=ParseMode.HTML)
        return
    match = active_matches[chat.id]

    if getattr(match, "game_mode", "TEAM") in ("SOLO", "MAGICBALL"):
        await update.message.reply_text(themed("⚠️ TEAM MODE ONLY", ["/shift only works for Team Mode (two teams)."], "⚠️"), parse_mode=ParseMode.HTML)
        return

    if match.phase not in (GamePhase.TEAM_JOINING, GamePhase.TEAM_EDIT, GamePhase.MATCH_IN_PROGRESS):
        await update.message.reply_text(themed("⚠️ WRONG PHASE", ["Cannot shift players in the current match phase."], "⚠️"), parse_mode=ParseMode.HTML)
        return

    if user.id != match.host_id:
        await update.message.reply_text(
            themed("🚧 HOST ONLY", ["Only the host can shift players between teams."], "🚧"),
            parse_mode=ParseMode.HTML
        )
        return

    targets = await _collect_add_remove_targets(update, context)
    if not targets:
        await update.message.reply_text(
            themed("🔀 SHIFT PLAYER(S)", [
                "Reply to a message + <code>/shift</code>",
                "By tag/username (bulk): <code>/shift @u1 @u2 ...</code>",
                "By user ID (bulk): <code>/shift id1 id2 ...</code>",
                "Auto-detects current team, moves to the other one.",
            ], "🔀"),
            parse_mode=ParseMode.HTML
        )
        return

    shifted, blocked, not_found = [], [], []
    for (uid, uname, fname) in targets:
        from_team, other_team, from_letter, other_letter = None, None, None, None
        if match.team_x.get_player(uid):
            from_team, other_team, from_letter, other_letter = match.team_x, match.team_y, "X", "Y"
        elif match.team_y.get_player(uid):
            from_team, other_team, from_letter, other_letter = match.team_y, match.team_x, "Y", "X"

        if from_team is None:
            not_found.append(fname)
            continue

        if uid == match.host_id:
            blocked.append(f"{fname} (host can't be shifted)")
            continue

        # Don't shift a player mid-over — they're actively involved right now
        idx = next((i for i, p in enumerate(from_team.players) if p.user_id == uid), None)
        if idx is not None and idx in (
            from_team.current_batsman_idx, from_team.current_non_striker_idx, from_team.current_bowler_idx
        ):
            blocked.append(f"{fname} (currently batting/bowling)")
            continue

        player_obj = from_team.get_player(uid)
        from_team.remove_player(uid)
        other_team.add_player(player_obj)
        shifted.append(f"{fname}: Team {from_letter} → Team {other_letter}")

    lines = []
    if shifted:
        lines.append(f"🔀 Shifted: {', '.join(shifted)}")
    if blocked:
        lines.append(f"🚧 Skipped (in play right now): {', '.join(blocked)}")
    if not_found:
        lines.append(f"⚠️ Not found in any team: {', '.join(not_found)}")

    await update.message.reply_text(
        themed("🔀 PLAYER(S) SHIFTED", lines or ["Nothing to shift."], "🔀"),
        parse_mode=ParseMode.HTML
    )

    if match.phase == GamePhase.TEAM_EDIT:
        await update_team_edit_message(context, chat.id, match)


async def remove_player_team_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle team selection for /remove [serial] command."""
    query = update.callback_query
    await query.answer()

    user = query.from_user
    data = query.data  # remove_player_X_<group_id>_<serial>

    try:
        parts = data.split("_")
        team_letter = parts[2]          # X or Y
        group_id = int(parts[3])
        serial = int(parts[4])
    except Exception:
        await query.answer("Invalid data!", show_alert=True)
        return

    if group_id not in active_matches:
        await query.answer("No active match!", show_alert=True)
        return

    match = active_matches[group_id]

    if user.id != match.host_id:
        await query.answer("Only the host can remove players!", show_alert=True)
        return

    team = match.team_x if team_letter == "X" else match.team_y

    if serial < 1 or serial > len(team.players):
        try:
            await query.edit_message_text(
                themed("⚠️ NOT FOUND", [f"Player #{serial} not found in Team {team_letter}."], "⚠️"),
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        return

    player = team.players[serial - 1]

    # Host can never remove themselves mid-game
    if player.user_id == match.host_id:
        await query.edit_message_text(
            themed("🚧 BLOCKED", ["The host cannot remove themselves mid-match."], "🚧"),
            parse_mode=ParseMode.HTML,
        )
        return

    # Prevent removing active players
    if team == match.current_batting_team:
        s_id = team.players[team.current_batsman_idx].user_id if team.current_batsman_idx is not None else None
        ns_id = team.players[team.current_non_striker_idx].user_id if team.current_non_striker_idx is not None else None
        if player.user_id in (s_id, ns_id):
            await query.edit_message_text(
                themed("🚧 BLOCKED", [f"{player.first_name} is currently <b>batting</b> and cannot be removed."], "🚧"),
                parse_mode=ParseMode.HTML,
            )
            return
    if team == match.current_bowling_team:
        b_id = team.players[team.current_bowler_idx].user_id if team.current_bowler_idx is not None else None
        if player.user_id == b_id:
            await query.edit_message_text(
                themed("🚧 BLOCKED", [f"{player.first_name} is currently <b>bowling</b> and cannot be removed."], "🚧"),
                parse_mode=ParseMode.HTML,
            )
            return

    team.remove_player(player.user_id)

    try:
        await query.edit_message_text(
            themed("✅ PLAYER REMOVED", [
                f"👤 <b>{html.escape(player.first_name)}</b> removed from <b>Team {team_letter}</b>.",
                f"📊 Team {team_letter} now has {len(team.players)} players.",
            ], "✅"),
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        pass

    if match.phase == GamePhase.TEAM_EDIT:
        await update_team_edit_message(context, group_id, match)



async def mid_game_add_logic(update: Update, context: ContextTypes.DEFAULT_TYPE, team_name: str):
    """🤝 Unified Add Logic (Reply / Username / ID) — Host Only"""
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_matches:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE MATCH!</b>\n\n"
            "Start a match first.",
            parse_mode=ParseMode.HTML
        )
        return
    match = active_matches[chat.id]
    if user.id != match.host_id:
        await update.message.reply_text(
            "🚧 <b>HOST ONLY!</b>\n\n"
            "Only the host can add players mid-game!",
            parse_mode=ParseMode.HTML
        )
        return
    if match.phase != GamePhase.MATCH_IN_PROGRESS:
        await update.message.reply_text(
            "⏳ <b>MATCH NOT IN PROGRESS!</b>\n\n"
            "Can only add players during live match!",
            parse_mode=ParseMode.HTML
        )
        return
    # Identify target user
    target_user = None
    if update.message.reply_to_message:
        target_user = update.message.reply_to_message.from_user
    elif context.args:
        arg = context.args[0]
        if arg.startswith("@"):
            username = arg[1:].lower()
            for uid, data in user_data.items():
                if data.get("username", "").lower() == username:
                    try:
                        target_user = await context.bot.get_chat(uid)
                    except Exception as e:
                        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 22186)")
                        pass
                    break
        elif arg.isdigit():
            try:
                target_user = await context.bot.get_chat(int(arg))
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 22192)")
                pass
    if not target_user:
        await update.message.reply_text(
            f"ℹ️ <b>ADD PLAYER USAGE</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            f"<b>Reply Method:</b>\n"
            f"<code>/add{team_name.lower()}</code>\n\n"
            f"<b>Username Method:</b>\n"
            f"<code>/add{team_name.lower()} @username</code>\n\n"
            f"<b>User ID Method:</b>\n"
            f"<code>/add{team_name.lower()} 123456789</code>\n\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
        return
    team = match.team_x if team_name == "X" else match.team_y
    if is_user_banned(target_user.id):
        await update.message.reply_text(
            themed("🚫 USER BANNED", [
                f"<b>{html.escape(target_user.first_name or str(target_user.id))}</b> is banned from the bot.",
                "They can't be added to any game.",
            ], "🚫"),
            parse_mode=ParseMode.HTML
        )
        return
    if match.team_x.get_player(target_user.id) or match.team_y.get_player(target_user.id):
        await update.message.reply_text(
            "⚠️ <b>PLAYER ALREADY IN A TEAM!</b>\n\n"
            "This player is already assigned.",
            parse_mode=ParseMode.HTML
        )
        return
    # ✅ Check if player has started the bot before adding
    bot_username = context.bot.username
    started = await check_user_started_bot(context.bot, target_user.id)

    # 🔒 Privacy: only persist a permanent profile for players who've started
    # the bot themselves — others still join the match in-memory below.
    if started and target_user.id not in user_data:
        user_data[target_user.id] = {
            "user_id": target_user.id,
            "username": target_user.username or "",
            "first_name": target_user.first_name,
            "started_at": datetime.now().isoformat(),
            "total_matches": 0
        }
        init_player_stats(target_user.id)
        save_data()

    new_player = Player(target_user.id, target_user.username or "", target_user.first_name)
    team.add_player(new_player)
    target_tag = get_user_tag(target_user)

    not_started_warning = ""
    if not started:
        not_started_warning = (
            f"\n\n⚠️ <b>Warning:</b> {html.escape(target_user.first_name)} hasn't started the bot!\n"
            f"👉 Ask them to start: <a href='https://t.me/{bot_username}'>@{bot_username}</a>\n"
            f"<i>They won't receive bowl/bat DMs until they do!</i>"
        )

    team_label = "X" if team == match.team_x else "Y"
    await update.message.reply_text(
        f"✅ <b>PLAYER ADDED!</b>\n"
        f"<b>TEAM {team_label}</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"👤 Added: {target_tag}\n"
        f"👥 Team Size: {len(team.players)}\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"{not_started_warning}",
        parse_mode=ParseMode.HTML,
        disable_web_page_preview=True
    )

async def mid_game_remove_logic(update: Update, context: ContextTypes.DEFAULT_TYPE, team_name: str):
    """🗑 Unified Remove Logic — Host Only"""
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_matches:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE MATCH!</b>\n\n"
            "Start a match first.",
            parse_mode=ParseMode.HTML
        )
        return
    match = active_matches[chat.id]
    if user.id != match.host_id:
        await update.message.reply_text(
            "🚧 <b>HOST ONLY!</b>\n\n"
            "Only the host can remove players mid-game!",
            parse_mode=ParseMode.HTML
        )
        return
    if match.phase != GamePhase.MATCH_IN_PROGRESS:
        await update.message.reply_text(
            "⏳ <b>MATCH NOT IN PROGRESS!</b>\n\n"
            "Can only remove players during match!",
            parse_mode=ParseMode.HTML
        )
        return
    target_user_id = None
    if update.message.reply_to_message:
        target_user_id = update.message.reply_to_message.from_user.id
    elif context.args:
        arg = context.args[0]
        if arg.startswith("@"):
            username = arg[1:].lower()
            for uid, data in user_data.items():
                if data.get("username", "").lower() == username:
                    target_user_id = uid
                    break
        elif arg.isdigit():
            target_user_id = int(arg)
    if not target_user_id:
        await update.message.reply_text(
            f"ℹ️ <b>REMOVE PLAYER USAGE</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            f"<b>Reply Method:</b>\n"
            f"<code>/remove{team_name.lower()}</code>\n\n"
            f"<b>Username Method:</b>\n"
            f"<code>/remove{team_name.lower()} @username</code>\n\n"
            f"<b>User ID Method:</b>\n"
            f"<code>/remove{team_name.lower()} 123456789</code>\n\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
        return
    team = match.team_x if team_name == "X" else match.team_y
    player = team.get_player(target_user_id)
    if not player:
        await update.message.reply_text(
            f"⚠️ <b>PLAYER NOT FOUND!</b>\n\n"
            f"Player is not in Team {team_name}!",
            parse_mode=ParseMode.HTML
        )
        return
    if target_user_id == match.host_id:
        await update.message.reply_text(
            "🚧 <b>HOST CAN'T REMOVE THEMSELVES!</b>\n\n"
            "The host cannot remove themselves mid-match.",
            parse_mode=ParseMode.HTML
        )
        return
    # Prevent removing active players
    if team == match.current_batting_team:
        if team.current_batsman_idx is not None and team.players[team.current_batsman_idx].user_id == target_user_id:
            await update.message.reply_text(
                "🚧 <b>CANNOT REMOVE STRIKER!</b>\n\n"
                "Current striker cannot be removed.",
                parse_mode=ParseMode.HTML
            )
            return
        if team.current_non_striker_idx is not None and team.players[team.current_non_striker_idx].user_id == target_user_id:
            await update.message.reply_text(
                "🚧 <b>CANNOT REMOVE NON-STRIKER!</b>\n\n"
                "Current non-striker cannot be removed.",
                parse_mode=ParseMode.HTML
            )
            return
    if team == match.current_bowling_team:
        if team.current_bowler_idx is not None and team.players[team.current_bowler_idx].user_id == target_user_id:
            await update.message.reply_text(
                "🚧 <b>CANNOT REMOVE BOWLER!</b>\n\n"
                "Current bowler cannot be removed.",
                parse_mode=ParseMode.HTML
            )
            return
    team.remove_player(target_user_id)
    await update.message.reply_text(
        f"❎ <b>PLAYER REMOVED!</b>\n"
        f"<b>TEAM {team_name}</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🎯 Player: {player.first_name}\n"
        f"📊 Team Size: {len(team.players)}\n"
        f"<i>Removed by Host mid-game</i>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        parse_mode=ParseMode.HTML
    )


async def team_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /team [team_name] — Show auction team details
    Displays: Full squad, remaining purse, bought players, slots left
    """
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\nStart an auction first.",
            parse_mode=ParseMode.HTML
        )
        return

    auction = active_auctions[chat.id]

    if not auction.teams:
        await update.message.reply_text(
            "⚠️ <b>No teams registered yet!</b>\n\nTeams will appear once bidders join.",
            parse_mode=ParseMode.HTML
        )
        return

    # If a specific team name is requested
    team_name_query = " ".join(context.args).strip() if context.args else None

    if team_name_query:
        # Find matching team (case-insensitive)
        matched = None
        for tname, tobj in auction.teams.items():
            if tname.lower() == team_name_query.lower():
                matched = (tname, tobj)
                break
        if not matched:
            team_list = "\n".join(f"• {t}" for t in auction.teams.keys())
            await update.message.reply_text(
                f"❌ Team <b>{html.escape(team_name_query)}</b> not found.\n\n"
                f"📋 <b>Available teams:</b>\n{team_list}",
                parse_mode=ParseMode.HTML
            )
            return
        teams_to_show = [matched]
        single_team_mode = True
    else:
        # Show all teams
        teams_to_show = list(auction.teams.items())
        single_team_mode = False

    def _team_table(team) -> str:
        # Telegram's HTML mode has no real <table> tag — a monospaced
        # <pre> block with padded columns is the closest real equivalent
        # and is what actually renders as an aligned "table" in-app.
        t = f"{_auc_pad('#', 5)}{_auc_pad('Player', 20)}{_auc_rpad('Price', 9)}\n"
        t += ("—" * 34) + "\n"
        total_spent_shown = 0
        for i, p in enumerate(team.players, 1):
            price = p.get('price', 0)
            total_spent_shown += price
            pname = p.get('player_name', 'Unknown')
            if p.get('player_id') == getattr(team, 'vice_captain_id', None):
                pname += " (VC)"
            t += f"{_auc_pad(i, 5)}{_auc_pad(pname, 20)}{_auc_rpad(price, 9)}\n"
        if not team.players:
            t += "  No players bought yet\n"
        else:
            t += ("—" * 34) + "\n"
            t += f"{_auc_pad('', 5)}{_auc_pad('TOTAL SPENT', 20)}{_auc_rpad(total_spent_shown, 9)}\n"
        return t

    # CCC-style: sort by purse spent so the biggest-spending team leads.
    teams_sorted = sorted(teams_to_show, key=lambda kv: kv[1].total_spent, reverse=True)

    # ── 1) Try the native CCC-style rich table first (real <table> inside a
    # collapsible <details> per team — same primitive /ccc and /fantasylb use)
    def _team_row_table_html(team) -> str:
        if not team.players:
            return "<p><i>No players bought yet</i></p>"
        trs = ""
        for i, p in enumerate(team.players, 1):
            p_name = html.escape(str(p.get('player_name', 'Unknown'))[:18])
            if p.get('player_id') == getattr(team, 'vice_captain_id', None):
                p_name += " (VC)"
            trs += (
                f"<tr><td align='center'>{i}</td>"
                f"<td>{p_name}</td>"
                f"<td align='right'>{p.get('price', 0):,}</td></tr>"
            )
        return (
            "<table bordered striped>"
            "<tr><th>#️⃣</th><th>🏏 Player</th><th>💰 Price</th></tr>"
            f"{trs}</table>"
        )

    def _build_team_rich_html() -> str:
        blocks = ""
        for i, (tname, team) in enumerate(teams_sorted, 1):
            medal = "🥇" if i == 1 else "🥈" if i == 2 else "🥉" if i == 3 else f"{i}️⃣"
            bidder_plain = html.escape(team.bidder_name or tname)
            vc_suffix = ""
            if getattr(team, 'vice_captain_name', None):
                vc_suffix = f" ↳ ({html.escape(team.vice_captain_name)} — Vice Captain)"
            summary = (
                f"{medal} {html.escape(tname.upper())}  ·  👑 {bidder_plain}{vc_suffix}  ·  "
                f"💰 {team.purse_remaining:,} left  ·  👥 {len(team.players)} bought"
            )
            blocks += f"<details><summary>{summary}</summary>{_team_row_table_html(team)}</details>"
        title = "🏆 <h3>AUCTION TEAMS</h3>" if not single_team_mode else f"<h3>🏆 TEAM — {html.escape(teams_sorted[0][0].upper())}</h3>"
        return f"{title}{blocks}<footer>🏆 CRICOVERSE AUCTION 🎮</footer>"

    html_content = _build_team_rich_html()
    ok = await _tg_send_rich_message(chat.id, html_content)
    if ok:
        return

    # ── 2) Fallback: <blockquote expandable><pre>table</pre></blockquote>
    # per team (same pattern /ccc and /fantasylb fall back to when the
    # client doesn't support native rich tables).
    section_blocks = []
    for i, (tname, team) in enumerate(teams_sorted, 1):
        bidder_plain = team.bidder_name or tname
        medal = "🥇" if i == 1 else "🥈" if i == 2 else "🥉" if i == 3 else f"{i}."
        vc_line = ""
        if getattr(team, 'vice_captain_name', None):
            vc_line = f"\n   ↳ ({html.escape(team.vice_captain_name)} — Vice Captain)"
        team_header = (
            f"{medal} <b>{html.escape(tname.upper())}</b>\n"
            f"👑 Bidder: {html.escape(bidder_plain)}{vc_line}\n"
            f"💰 Purse Left: {team.purse_remaining} 🔷  ·  "
            f"👥 Squad: {len(team.players)}"
        )
        team_table = _team_table(team)
        # Telegram's real "collapsible" primitive is <blockquote expandable>
        # (there's no <details> tag) — every team now gets one consistently,
        # top team included, so the whole /team view stays compact and tidy
        # with a tap-to-expand roster + aligned table inside.
        block = f"<blockquote expandable>{team_header}\n<pre>{team_table}</pre></blockquote>"
        section_blocks.append(block)

    title_line = "🏆 <b>AUCTION TEAMS</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    pages = []
    current = title_line
    for block in section_blocks:
        if len(current) + len(block) + 2 > 3900:
            pages.append(current)
            current = "<i>(continued...)</i>\n\n" + block
        else:
            current += ("" if current == title_line else "\n\n") + block
    pages.append(current)

    for idx, page_text in enumerate(pages):
        await update.message.reply_text(
            page_text, parse_mode=ParseMode.HTML,
            reply_to_message_id=update.message.message_id if idx == 0 else None
        )


def _auc_pad(s, w):
    s = html.escape(str(s))
    return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))


def _auc_rpad(s, w):
    s = str(s)
    return (s[: max(w - 1, 1)] + "…") if len(s) > w else (" " * (w - len(s))) + s


def _build_auction_summary_pages(auction: "Auction") -> list:
    """Build paginated pages for auction summary (/list) as three tables:
    Auction Summary (Player/Sold To/Price), Current Purse (Team/Purse/Players),
    Unsold Players (Player/Base Price)."""
    sold_players = auction.sold_players
    unsold_players = auction.unsold_players
    remaining = auction.player_pool
    sold_count = len(sold_players)
    unsold_count = len(unsold_players)
    remaining_count = len(remaining)
    total = sold_count + unsold_count + remaining_count

    header = (
        f"📊 <b>AUCTION SUMMARY</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"✅ Sold: <b>{sold_count}</b>  |  ❌ Unsold: <b>{unsold_count}</b>  |  ⏳ Remaining: <b>{remaining_count}</b>  |  📦 Total: <b>{total}</b>\n"
    )

    # ── Auction Summary table: Player | Role | Sold To | Price ──
    sold_header = f"{_auc_pad('Player', 16)}{_auc_pad('Sold To', 16)}{_auc_rpad('Price', 8)}\n"
    sold_table = sold_header + ("—" * 45) + "\n"
    for sp in sold_players:
        p_name = sp.get('player_name', 'Unknown')
        p_id = sp.get('player_id')
        role = compute_player_role(p_id) if p_id else "Unranked"
        sold_table += f"{_auc_pad(p_name, 16)}{_auc_pad(sp.get('team', '?'), 16)}{_auc_rpad(sp.get('price', 0), 8)}\n"
    if not sold_players:
        sold_table += "  No players sold yet\n"

    # ── Current Purse table: Team | Purse | Players ──
    purse_table = ""
    if auction.teams:
        purse_header = f"{_auc_pad('Team', 16)}{_auc_rpad('Purse', 10)}{_auc_rpad('Players', 9)}\n"
        purse_table = purse_header + ("—" * 35) + "\n"
        for tname, tobj in sorted(auction.teams.items(), key=lambda x: x[1].purse_remaining, reverse=True):
            purse_table += f"{_auc_pad(tname, 16)}{_auc_rpad(tobj.purse_remaining, 10)}{_auc_rpad(len(tobj.players), 9)}\n"

    # ── Unsold Players table: Player | Role | Base Price ──
    unsold_header = f"{_auc_pad('Player', 20)}{_auc_rpad('Base Price', 12)}\n"
    unsold_table = unsold_header + ("—" * 38) + "\n"
    for up in unsold_players:
        u_name = up.get('player_name', 'Unknown') if isinstance(up, dict) else str(up)
        u_id = up.get('player_id') if isinstance(up, dict) else None
        base = up.get('base_price', 0) if isinstance(up, dict) else 0
        role = compute_player_role(u_id) if u_id else "Unranked"
        unsold_table += f"{_auc_pad(u_name, 20)}{_auc_rpad(base, 12)}\n"
    if not unsold_players:
        unsold_table += "  No unsold players\n"

    pages = []
    PAGE_LIMIT = 3500

    def new_page_base():
        return f"📊 <b>AUCTION SUMMARY</b> (cont.)\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"

    current = header + "\n<b>Auction Summary</b>\n" + f"<pre>{sold_table}</pre>"
    purse_block = ("\n<b>Current Purse</b>\n" + f"<pre>{purse_table}</pre>") if purse_table else ""
    unsold_block = "\n<b>Unsold Players</b>\n" + f"<pre>{unsold_table}</pre>"

    if len(current) + len(purse_block) > PAGE_LIMIT:
        pages.append(current)
        current = new_page_base() + purse_block
    else:
        current += purse_block

    if len(current) + len(unsold_block) > PAGE_LIMIT:
        pages.append(current)
        current = new_page_base() + unsold_block
    else:
        current += unsold_block

    # Remaining pool list
    if remaining:
        rem_line = "\n<b>Remaining Pool:</b> " + ", ".join(html.escape(rp.get('player_name', '?')) for rp in remaining)
        if len(current) + len(rem_line) > PAGE_LIMIT:
            pages.append(current)
            current = new_page_base() + rem_line
        else:
            current += rem_line

    pages.append(current)
    return pages


def _auction_list_keyboard(chat_id: int, page_idx: int, total_pages: int) -> InlineKeyboardMarkup:
    """Prev / page indicator / Next keyboard for auction summary."""
    nav = []
    if page_idx > 0:
        nav.append(styled_button("Prev", callback_data=f"auclist_{chat_id}_{page_idx - 1}"))
    nav.append(styled_button(f"{page_idx + 1}/{total_pages}", callback_data="noop"))
    if page_idx < total_pages - 1:
        nav.append(styled_button("Next", callback_data=f"auclist_{chat_id}_{page_idx + 1}"))
    close = [styled_button("Close", callback_data="auclist_close")]
    return InlineKeyboardMarkup([nav, close])


async def auclist_page_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Prev/Next for auction summary pagination."""
    query = update.callback_query
    await query.answer()
    try:
        # Format: auclist_{chat_id}_{page_idx}
        data = query.data[len("auclist_"):]  # "{chat_id}_{page_idx}"
        last_us = data.rfind("_")
        chat_id = int(data[:last_us])
        page_idx = int(data[last_us + 1:])
    except (IndexError, ValueError):
        return

    if chat_id not in active_auctions:
        await query.answer("Auction ended!", show_alert=True)
        return

    auction = active_auctions[chat_id]
    pages = _build_auction_summary_pages(auction)
    total_pages = len(pages)

    if page_idx < 0 or page_idx >= total_pages:
        await query.answer("Invalid page!", show_alert=True)
        return

    page_text = pages[page_idx] + f"\n\n<i>Page {page_idx + 1} of {total_pages}</i>"
    kb = _auction_list_keyboard(chat_id, page_idx, total_pages)
    try:
        await query.edit_message_text(page_text, parse_mode=ParseMode.HTML, reply_markup=kb, disable_web_page_preview=True)
    except Exception as e:
        logger.error(f"auclist_page_callback error: {e}")


async def auclist_close_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Close/delete auction summary message."""
    query = update.callback_query
    await query.answer()
    try:
        await query.message.delete()
    except Exception:
        try:
            await query.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass


async def auction_list_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """📋 /list — Send paginated auction summary to the group chat"""
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\nStart an auction first.",
            parse_mode=ParseMode.HTML
        )
        return

    auction = active_auctions[chat.id]

    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🚧 <b>ACCESS DENIED!</b>\n\nOnly Auctioneer/Host can use /list.",
            parse_mode=ParseMode.HTML
        )
        return

    pages = _build_auction_summary_pages(auction)
    total_pages = len(pages)
    first_page = pages[0] + f"\n\n<i>Page 1 of {total_pages}</i>"
    kb = _auction_list_keyboard(chat.id, 0, total_pages)
    await update.message.reply_text(first_page, parse_mode=ParseMode.HTML, reply_markup=kb, disable_web_page_preview=True)


async def pauseauction_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """⏸ Pause auction timer (Auctioneer/Host Only)"""
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\n"
            "Start an auction first.",
            parse_mode=ParseMode.HTML
        )
        return
    auction = active_auctions[chat.id]
    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🚧 <b>ACCESS DENIED!</b>\n\n"
            "Only Auctioneer/Host can pause!",
            parse_mode=ParseMode.HTML
        )
        return
    if getattr(auction, 'is_paused', False):
        await update.message.reply_text("⏸ Auction is already paused! Use /resumeauction to continue.", parse_mode=ParseMode.HTML)
        return

    remaining = None
    if auction.bid_timer_task and auction.bid_end_time:
        remaining = max(5, int(auction.bid_end_time - time.time()))
    auction.pause_remaining_secs = remaining
    auction.is_paused = True

    if auction.bid_timer_task:
        auction.bid_timer_task.cancel()
        auction.bid_timer_task = None
    
    # Build sold players list
    sold_count = len(auction.sold_players)
    remaining_count = len(auction.player_pool)
    total_auctioned = sold_count + len(auction.unsold_players)
    
    sold_summary = ""
    if auction.sold_players:
        sold_summary = " |  🔨 RECENTLY SOLD\n |  ┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        for sp in auction.sold_players[-5:]:
            p_id = sp.get('player_id', '')
            p_name = sp.get('player_name', 'Unknown')
            p_tag = f'<a href=\"tg://user?id={p_id}\">{html.escape(p_name)}</a>' + _title_suffix(p_id)
            sold_summary += f"┃ ├  👤 {p_tag} ➔ {sp.get('team','?')} ({sp.get('price',0)} 🔷)\n"
        if sold_count > 5:
            sold_summary += f"┃ └  <i>... and {sold_count - 5} more</i>\n"
        sold_summary += " |  \n"

    remaining_list = ""
    if auction.player_pool:
        remaining_list = " |  📋 REMAINING PLAYERS\n |  ┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n |  "
        rp_names = [f"▫️ {html.escape(rp['player_name'])}" for rp in auction.player_pool[:5]]
        remaining_list += "  |  ".join(rp_names)
        if remaining_count > 5:
            remaining_list += f"  |  <i>+{remaining_count - 5} more</i>"
        remaining_list += "\n |  \n"

    pause_lines = [
        f"🟢 Sold players: <b>{sold_count}</b>",
        f"🔴 Unsold players: <b>{len(auction.unsold_players)}</b>",
        f"⏳ Remaining pool: <b>{remaining_count}</b>",
    ]
    if sold_count:
        for sp in auction.sold_players[-5:]:
            pid = sp.get('player_id', '')
            pname = sp.get('player_name', 'Unknown')
            ptag = f'<a href="tg://user?id={pid}">{html.escape(pname)}</a>' + _title_suffix(pid)
            pause_lines.append(f"👤 Sold: {ptag} → {html.escape(str(sp.get('team','?')))} ({sp.get('price',0)} 🔷)")
    if auction.player_pool:
        pause_lines.append("📋 Next: " + " · ".join(html.escape(rp['player_name']) for rp in auction.player_pool[:5]))
    pause_lines.append("Use <code>/resumeauction</code> to continue.")
    msg = themed("AUCTION PAUSED", pause_lines, "⏸️")
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

async def resumeauction_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """▶ Resume auction timer (Auctioneer/Host Only)"""
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\n"
            "Start an auction first.",
            parse_mode=ParseMode.HTML
        )
        return
    auction = active_auctions[chat.id]
    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🚧 <b>ACCESS DENIED!</b>\n\n"
            "Only Auctioneer/Host can resume!",
            parse_mode=ParseMode.HTML
        )
        return
    if not getattr(auction, 'is_paused', False):
        await update.message.reply_text(
            "⚠️ <b>CANNOT RESUME!</b>\n\n"
            "Auction isn't paused right now.",
            parse_mode=ParseMode.HTML
        )
        return

    if auction.phase == AuctionPhase.AUCTION_LIVE:
        secs = getattr(auction, 'pause_remaining_secs', None) or 20
        auction.is_paused = False
        auction.pause_remaining_secs = None
        if auction.bid_timer_task:
            auction.bid_timer_task.cancel()
        auction.bid_end_time = time.time() + secs
        auction.bid_timer_task = asyncio.create_task(bid_timer(context, chat.id, auction, initial_secs=secs))
        await update.message.reply_text(
            f"▶️ <b>AUCTION RESUMED!</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            f"⏱ <b>Timer:</b> {secs} seconds\n"
            "💰 Bidding is now active!\n\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
    else:
        auction.is_paused = False
        auction.pause_remaining_secs = None
        await update.message.reply_text(
            "▶️ Auction unpaused, but no bidding round is live right now.",
            parse_mode=ParseMode.HTML
        )

async def refreshgif_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🆕 OWNER-ONLY: clear a bad cached animation file_id so the NEXT send
    re-uploads the file from disk instead of reusing the stale one.

    Why this exists: once Telegram accepts a video-format .mp4 as a VIDEO
    (or DOCUMENT) instead of an ANIMATION — usually because it still has an
    audio track, isn't yuv420p, or doesn't have the moov atom up front
    (faststart) — that specific file_id is stuck that way FOREVER. The
    logs then show the "was sent but Telegram returned it as a VIDEO/
    DOCUMENT, not an animation" warning on every single send, even after
    you fix and re-encode the .mp4 on disk, because the OLD (bad) file_id
    is still sitting in file_id_cache.json and keeps getting reused.

    Usage: /refreshgif bowling.mp4  (matches by filename, wherever it is
    under cricoverse_images/). Re-encode the file first with something like:
        ffmpeg -i bowling.mp4 -an -vf format=yuv420p -movflags +faststart bowling_fixed.mp4
    then overwrite the original filename on disk, then run this command."""
    user = update.effective_user
    if user.id != OWNER_ID:
        await update.message.reply_text("🚧 Owner only.", parse_mode=ParseMode.HTML)
        return

    if not context.args:
        await update.message.reply_text(
            "Usage: <code>/refreshgif filename.mp4</code>\n\n"
            f"Currently cached: {len(_animation_file_id_cache)} animation file(s).",
            parse_mode=ParseMode.HTML
        )
        return

    target = context.args[0].strip().lower()
    removed = [k for k in list(_animation_file_id_cache.keys()) if os.path.basename(k).lower() == target]
    if not removed:
        # Fall back to a substring match in case the exact filename casing/
        # path differs from what's cached.
        removed = [k for k in list(_animation_file_id_cache.keys()) if target in k.lower()]

    if not removed:
        await update.message.reply_text(
            f"⚠️ No cached entry matched <code>{html.escape(target)}</code>.\n"
            f"Cached files: {', '.join(os.path.basename(k) for k in _animation_file_id_cache) or '(none)'}",
            parse_mode=ParseMode.HTML
        )
        return

    for k in removed:
        del _animation_file_id_cache[k]
    _save_file_id_cache()

    await update.message.reply_text(
        f"✅ Cleared {len(removed)} cached file_id(s) for <code>{html.escape(target)}</code>.\n"
        f"Next time it's sent, it'll re-upload fresh from disk.",
        parse_mode=ParseMode.HTML
    )


async def nextplayer_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🎯 Manually bring the next player up (Auctioneer/Host Only).
    🩹 BUGFIX: this command didn't exist at all — the "ERROR BRINGING NEXT
    PLAYER!" message told hosts to run /nextplayer, but there was no
    handler for it anywhere, so a failed auto-advance permanently stalled
    the auction with no way to recover except restarting it. This is that
    missing recovery path."""
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\nStart an auction first.",
            parse_mode=ParseMode.HTML
        )
        return

    auction = active_auctions[chat.id]

    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🚧 <b>ACCESS DENIED!</b>\n\nOnly the Auctioneer/Host can bring the next player!",
            parse_mode=ParseMode.HTML
        )
        return

    if getattr(auction, 'is_paused', False):
        await update.message.reply_text(
            "⏸ Auction is paused. Use /resumeauction first.",
            parse_mode=ParseMode.HTML
        )
        return

    if auction.pending_sold_confirmation:
        await update.message.reply_text(
            "⏳ Still waiting on SOLD confirmation for the current player — use /confirmsold or /rejectsold first.",
            parse_mode=ParseMode.HTML
        )
        return

    if auction.current_player_id is not None:
        await update.message.reply_text(
            "⚠️ A player is already up for bidding right now — /nextplayer only helps when the "
            "auction is stuck between players (e.g. right after an \"ERROR BRINGING NEXT PLAYER!\" message).",
            parse_mode=ParseMode.HTML
        )
        return

    if auction.bid_timer_task:
        auction.bid_timer_task.cancel()
        auction.bid_timer_task = None

    try:
        await bring_next_player(context, chat.id, auction)
    except Exception as e:
        logger.error(f"/nextplayer manual retry failed: {e}")
        await update.message.reply_text(
            "⚠️ <b>STILL FAILING!</b>\n\nSomething is wrong with the player data or media — please contact the bot admin.",
            parse_mode=ParseMode.HTML
        )

async def base_price_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """💰 Handle base price selection"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    
    if chat.id not in active_auctions:
        return
    
    auction = active_auctions[chat.id]
    
    # Extract price
    price = int(query.data.split("_")[1])
    
    # Add to pool
    auction.player_pool.append({
        "player_id": auction.current_player_id,
        "player_name": auction.current_player_name,
        "base_price": price
    })
    
    auction.current_player_id = None
    auction.current_player_name = ""
    auction.phase = AuctionPhase.BIDDER_SELECTION
    
    await query.message.edit_text(
        f"✅ <b>PLAYER ADDED TO POOL!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        f"👤 <b>Name:</b> {auction.player_pool[-1]['player_name']}\n"
        f"💰 <b>Base Price:</b> {price}\n\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"📊 <b>Total Players in Pool:</b> {len(auction.player_pool)}\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        parse_mode=ParseMode.HTML
    )

async def bid_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """💰 Place Bid - FIXED: Proper Timer Reset"""
    chat_id = update.effective_chat.id
    user_id = update.effective_user.id
    
    if chat_id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\n"
            "Start an auction first.",
            parse_mode=ParseMode.HTML
        )
        return
        
    # Check outside the lock to reject silently during confirmation phase
    auction = active_auctions[chat_id]
    if getattr(auction, 'bids_frozen', False) or getattr(auction, 'pending_sold_confirmation', False):
        return
    if getattr(auction, 'is_paused', False):
        await update.message.reply_text(
            "⏸ <b>AUCTION IS PAUSED!</b>\n\nWait for the host to /resumeauction before bidding.",
            parse_mode=ParseMode.HTML
        )
        return
    
    async with auction_locks[chat_id]:  # ✅ Fixed bracket notation
        auction = active_auctions[chat_id]
        
        if getattr(auction, 'is_paused', False):
            return
        
        if auction.phase != AuctionPhase.AUCTION_LIVE:
            await update.message.reply_text(
                "⏳ <b>BIDDING NOT OPEN!</b>\n\n"
                "Wait for the next player.",
                parse_mode=ParseMode.HTML
            )
            return

        # 🩹 BUGFIX: same fix as quickbid_callback — reject a bid that lands
        # during the ~7s gap between SOLD resolving and the next player
        # actually being brought up (current_player_id is None but phase is
        # still AUCTION_LIVE). Otherwise it starts a phantom bid_timer_task
        # that races with the real one for the new player and corrupts it.
        if auction.current_player_id is None:
            return
        
        team = next((t for t in auction.teams.values() if t.bidder_id == user_id), None)
        team_name = next((n for n, t in auction.teams.items() if t.bidder_id == user_id), None)
        
        # Check if auctioneer is assisting OR if user is an assisted bidder
        if not team:
            # Check if user is auctioneer and has assist mode enabled for any team
            if user_id == auction.auctioneer_id:
                for t_name, t_obj in auction.teams.items():
                    if auction.assist_mode.get(t_name):
                        team_name = t_name
                        team = t_obj
                        break
            
            # NEW: Check if user is an assisted bidder (can bid for their own team when assist mode is on)
            if not team and hasattr(auction, 'assisted_bidders'):
                for t_name, bidder_id in auction.assisted_bidders.items():
                    if bidder_id == user_id and auction.assist_mode.get(t_name):
                        team_name = t_name
                        team = auction.teams[t_name]
                        break

            # 🆕 /assist vc — if globally enabled, any team's Vice Captain
            # can bid on their own team's behalf too.
            if not team and getattr(auction, 'vc_assist_enabled', False):
                for t_name, t_obj in auction.teams.items():
                    if getattr(t_obj, 'vice_captain_id', None) == user_id:
                        team_name = t_name
                        team = t_obj
                        break
            
            if not team:
                await update.message.reply_text(
                    "❌ <b>NOT A TEAM OWNER!</b>\n\n"
                    "You are not authorized to bid!",
                    parse_mode=ParseMode.HTML
                )
                return
        
        try:
            amount = int(context.args[0])
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 22892)")
            await update.message.reply_text(
                "⚠️ <b>INVALID BID!</b>\n\n"
                "<b>Usage:</b> <code>/bid [amount]</code>",
                parse_mode=ParseMode.HTML
            )
            return
        
        if amount <= auction.current_highest_bid:
            await update.message.reply_text(
                f"🚫 <b>BID TOO LOW!</b>\n\n"
                f"Bid must be higher than <b>{auction.current_highest_bid}</b>!",
                parse_mode=ParseMode.HTML
            )
            return
        
        # ✅ NEW: Same team cannot override their own bid unless another team has bid
        if auction.current_highest_bidder and auction.current_highest_bidder == team_name:
            # Check if the current highest bid is same as base price (no other team bid yet after us)
            # Allow override only if another team placed a bid after ours
            # We track this via auction.last_bid_teams list
            last_bid_teams = getattr(auction, 'last_bid_teams', [])
            # If the last 2 bids are both from the same team, block
            if len(last_bid_teams) >= 1 and last_bid_teams[-1] == team_name:
                await update.message.reply_text(
                    f"🚫 <b>CANNOT OVERBID YOURSELF!</b>\n\n"
                    f"💼 <b>{team_name}</b> is already the highest bidder at <b>{auction.current_highest_bid}</b>.\n"
                    f"Wait for another team to bid before raising your own bid!",
                    parse_mode=ParseMode.HTML
                )
                return
        
        if amount > team.purse_remaining:
            await update.message.reply_text(
                f"💰 <b>INSUFFICIENT FUNDS!</b>\n\n"
                f"Your purse: <b>{team.purse_remaining}</b>\n"
                f"Your bid: <b>{amount}</b>",
                parse_mode=ParseMode.HTML
            )
            return

        if len(team.players) >= getattr(auction, 'max_players_per_team', 11):
            await update.message.reply_text(
                f"🚫 <b>SQUAD FULL!</b>\n\n"
                f"<b>{team_name}</b> already has the max {auction.max_players_per_team} players!",
                parse_mode=ParseMode.HTML
            )
            return
        
        # Update Bid
        auction.current_highest_bid = amount
        auction.current_highest_bidder = team_name
        # Track bid history for same-team override prevention
        if not hasattr(auction, 'last_bid_teams'):
            auction.last_bid_teams = []
        auction.last_bid_teams.append(team_name)
        if len(auction.last_bid_teams) > 10:
            auction.last_bid_teams = auction.last_bid_teams[-10:]

        # Store latest bidder info so bid_timer shows it merged into ONE message
        auction.last_bidder_tag = get_user_tag(update.effective_user)
        auction.last_team_name = team_name

        # Log this bid for the live log
        if not hasattr(auction, 'live_bid_log'):
            auction.live_bid_log = []
        auction.live_bid_log.append({"team": team_name, "bidder": auction.last_bidder_tag, "amount": amount})

        # Reset Timer: Cancel old, set new end time, start new task
        # (bid_timer sends a single merged countdown+bid message — no separate confirmation message)
        if auction.bid_timer_task:
            auction.bid_timer_task.cancel()
            auction.bid_timer_task = None
        
        auction.bid_end_time = time.time() + 20
        auction.bid_timer_task = asyncio.create_task(bid_timer(context, chat_id, auction))

        # 🐛 SPEED FIX: delete the /bid command message right away instead of
        # waiting on the (slower) history-log edit below first.
        try:
            await update.message.delete()
        except Exception:
            pass

    # 🐛 SPEED FIX: fire-and-forget, OUTSIDE the lock — a Telegram message-edit
    # API call was previously awaited INSIDE the lock before anything else
    # could happen, which is why bids felt slow (every other bid had to wait
    # for this network round-trip to finish first).
    asyncio.create_task(_update_auction_history_message(context, chat_id, auction))


async def quickbid_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """⚡ Handle quick bid buttons (+3, +5, +10) in auction"""
    query = update.callback_query
    user = query.from_user
    parts = query.data.split("_")  # quickbid_chatid_amount
    if len(parts) < 3:
        await query.answer(plain_alert("❌ Invalid data."), show_alert=True)
        return
    try:
        chat_id = int(parts[1])
        amount = int(parts[2])
    except (ValueError, IndexError):
        await query.answer(plain_alert("❌ Invalid data."), show_alert=True)
        return

    if chat_id not in active_auctions:
        await query.answer(plain_alert("❌ No active auction!"), show_alert=True)
        return

    # Check outside lock to reject silently during confirmation phase
    auction = active_auctions[chat_id]
    if getattr(auction, 'bids_frozen', False) or getattr(auction, 'pending_sold_confirmation', False):
        await query.answer()  # Silent answer to stop loading spinner
        return
    if getattr(auction, 'is_paused', False):
        await query.answer(plain_alert("⏸ Auction is paused! Wait for host to resume."), show_alert=True)
        return

    async with auction_locks[chat_id]:
        auction = active_auctions[chat_id]
        if getattr(auction, 'is_paused', False):
            await query.answer(plain_alert("⏸ Auction is paused! Wait for host to resume."), show_alert=True)
            return
        if auction.phase != AuctionPhase.AUCTION_LIVE:
            await query.answer("⏳ Bidding not open right now!", show_alert=True)
            return

        # 🩹 BUGFIX (root cause of "next player aaya but bid doesn't work,
        # bot randomly says SOLD"): the ~7s gap between a SOLD confirmation
        # resolving and bring_next_player() actually bringing up the new
        # player has current_player_id = None while phase is STILL
        # AUCTION_LIVE. There was no guard for that — a stray tap on the
        # PREVIOUS player's still-visible quickbid buttons during that gap
        # would sail through every check below, get accepted as a real bid,
        # and spin up its own bid_timer_task. That phantom timer then kept
        # running in parallel with the real timer bring_next_player starts
        # for the new player, and ~20s later "resolved" using whatever the
        # NEW player's live state happened to be at that moment — which is
        # exactly the confusing "bid stopped working + a SOLD alert fired
        # out of nowhere" symptom. Reject any bid while no player is
        # actually up, silently (no alert — the tap just came in too early).
        if auction.current_player_id is None:
            await query.answer()
            return
        
        # Block bids during auctioneer confirmation window (double check inside lock)
        if getattr(auction, 'bids_frozen', False) or getattr(auction, 'pending_sold_confirmation', False):
            await query.answer()
            return
            
        team = next((t for t in auction.teams.values() if t.bidder_id == user.id), None)
        team_name = next((n for n, t in auction.teams.items() if t.bidder_id == user.id), None)

        if not team:
            # Check assisted bidders
            if hasattr(auction, 'assisted_bidders'):
                for t_name, bidder_id in auction.assisted_bidders.items():
                    if bidder_id == user.id and auction.assist_mode.get(t_name):
                        team_name = t_name
                        team = auction.teams[t_name]
                        break
            # 🆕 /assist vc — globally enabled Vice Captain bidding
            if not team and getattr(auction, 'vc_assist_enabled', False):
                for t_name, t_obj in auction.teams.items():
                    if getattr(t_obj, 'vice_captain_id', None) == user.id:
                        team_name = t_name
                        team = t_obj
                        break
            if not team:
                await query.answer(plain_alert("❌ You are not a team bidder!"), show_alert=True)
                return

        # 🆕 FEATURE (same idea as the bowler DM number-pad): on a laggy
        # connection the bidder can tap the same quick-bid button many times
        # before their client shows the result. Their FIRST tap already went
        # through and became the current highest bid — every repeat tap of
        # that exact same amount by the exact same bidder is just that one
        # click arriving late/again, not a real new bid attempt. Silently
        # ignore it (clear the loading spinner only) instead of showing the
        # "Bid must be > X!" error, which would be a confusing/wrong message
        # for what is really just a duplicate of their own accepted bid.
        if auction.current_highest_bidder == team_name and amount == auction.current_highest_bid:
            await query.answer()
            return

        if amount <= auction.current_highest_bid:
            await query.answer(plain_alert(f"🚫 Bid must be > {auction.current_highest_bid}!"), show_alert=True)
            return

        # Same-team overbid check
        if auction.current_highest_bidder == team_name:
            last_bid_teams = getattr(auction, 'last_bid_teams', [])
            if last_bid_teams and last_bid_teams[-1] == team_name:
                await query.answer(plain_alert(f"🚫 You're already highest bidder at {auction.current_highest_bid}!"), show_alert=True)
                return

        if amount > team.purse_remaining:
            await query.answer(plain_alert(f"💰 Insufficient purse! You have {team.purse_remaining}"), show_alert=True)
            return

        if len(team.players) >= getattr(auction, 'max_players_per_team', 11):
            await query.answer(plain_alert(f"🚫 {team_name} squad is full ({auction.max_players_per_team})!"), show_alert=True)
            return

        # Place bid
        auction.current_highest_bid = amount
        auction.current_highest_bidder = team_name
        if not hasattr(auction, 'last_bid_teams'):
            auction.last_bid_teams = []
        auction.last_bid_teams.append(team_name)
        if len(auction.last_bid_teams) > 10:
            auction.last_bid_teams = auction.last_bid_teams[-10:]

        # Store latest bidder info so bid_timer shows it merged into ONE message
        auction.last_bidder_tag = get_user_tag(user)
        auction.last_team_name = team_name

        # Log this bid for the live log
        if not hasattr(auction, 'live_bid_log'):
            auction.live_bid_log = []
        auction.live_bid_log.append({"team": team_name, "bidder": auction.last_bidder_tag, "amount": amount})

        if auction.bid_timer_task:
            auction.bid_timer_task.cancel()
        auction.bid_end_time = time.time() + 20
        auction.bid_timer_task = asyncio.create_task(bid_timer(context, chat_id, auction))

        # 🐛 SPEED FIX: answer the button immediately so the user's tap feels
        # instant. The history-log message edit below is a real Telegram API
        # call (network round-trip) — it used to be awaited BEFORE answer(),
        # which is exactly why bidding felt slow, especially with multiple
        # people bidding back-to-back (they were all queued behind this edit
        # while still holding the auction lock).
        await query.answer(plain_alert(f"✅ Bid placed: {amount} 🔷!"), show_alert=False)

    # 🐛 SPEED FIX: fire-and-forget, OUTSIDE the lock — so it never blocks the
    # next person's bid, and never delays this callback's response.
    asyncio.create_task(_update_auction_history_message(context, chat_id, auction))


async def _update_auction_history_message(context, chat_id: int, auction):
    """🚫 REMOVED: the running auction history log message has been removed per user request
    to keep the auction real-time and fast (no pinned/edited log message anymore).
    Kept as a no-op so existing call sites don't need to change."""
    return


async def bid_timer(context: ContextTypes.DEFAULT_TYPE, chat_id: int, auction: Auction, initial_secs: int = 20):
    """⏳ Bid Timer with live countdown + merged bid info (single photo message) + history log"""
    try:
        # ── Live countdown: edit a single merged message every 5 seconds ──
        # 🩹 BUGFIX: this used to be hardcoded to 20 regardless of caller —
        # /pauseauction + /resumeauction computed and *displayed* the real
        # remaining seconds, but the actual timer silently always ran a
        # fresh 20s countdown, so the on-screen "Timer: Ns" was a lie.
        countdown_secs = max(int(initial_secs), 1) if initial_secs else 20
        reminder_sent = False

        def countdown_text(s):
            color = "🔴" if s <= 5 else ("🟡" if s <= 10 else "🟢")
            p_tag = f'<a href="tg://user?id={auction.current_player_id}">{auction.current_player_name}</a>' + _title_suffix(auction.current_player_id)
            last_bidder_tag = getattr(auction, "last_bidder_tag", None)
            last_team_name = getattr(auction, "last_team_name", None)

            if last_bidder_tag and last_team_name:
                _team_obj = auction.teams.get(last_team_name)
                purse_left = _team_obj.purse_remaining if _team_obj else "?"
                parts = [
                    f"⚡ <b>NEW BID! ({auction.current_highest_bid} 🔷)</b>",
                    "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
                    f"👤 Player: {p_tag}",
                    f"💰 Bid: <b>{auction.current_highest_bid} 🔷</b>",
                    "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
                    f"🚩 Team: <b>{html.escape(last_team_name)}</b>",
                    f"👑 Leader: {last_bidder_tag}",
                    "",
                    f"{color} <i>{s}s remaining</i>",
                ]
            else:
                parts = [
                    "💰 <b>WAITING FOR BIDS!</b>",
                    "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
                    f"🔨 Player: {p_tag}",
                    f"🪙 Base price: <b>{auction.current_base_price} 🔷</b>",
                    "👑 Leader: None",
                    "",
                    f"{color} <i>{s}s remaining · /bid [amount]</i>",
                ]
            return "\n".join(parts)

        def quick_kb_markup():
            amount = auction.current_highest_bid
            next_3 = amount + 3
            next_5 = amount + 5
            next_10 = amount + 10
            return InlineKeyboardMarkup([
                [
                    styled_button(f"+3 ({next_3})", callback_data=f"quickbid_{chat_id}_{next_3}"),
                    styled_button(f"+5 ({next_5})", callback_data=f"quickbid_{chat_id}_{next_5}"),
                ],
                [
                    styled_button(f"+10 ({next_10})", callback_data=f"quickbid_{chat_id}_{next_10}"),
                ]
            ])

        # Send initial merged countdown+bid message as plain TEXT (no photo/GIF)
        # so each new bid doesn't have to re-upload media — keeps bidding fast.
        try:
            cd_msg = await context.bot.send_message(
                chat_id, text=countdown_text(countdown_secs), parse_mode=ParseMode.HTML,
                reply_markup=quick_kb_markup()
            )
            auction.countdown_message_id = cd_msg.message_id
        except Exception:
            auction.countdown_message_id = None

        # Tick every 5 seconds, update countdown — buttons re-attached on EVERY edit so they never disappear
        elapsed = 0
        while elapsed < countdown_secs:
            await asyncio.sleep(5)
            elapsed += 5
            remaining = countdown_secs - elapsed
            if auction.phase != AuctionPhase.AUCTION_LIVE:
                break
            if auction.countdown_message_id:
                try:
                    await context.bot.edit_message_text(
                        chat_id=chat_id,
                        message_id=auction.countdown_message_id,
                        text=countdown_text(max(remaining, 0)),
                        parse_mode=ParseMode.HTML,
                        reply_markup=quick_kb_markup()
                    )
                except Exception:
                    pass  # message may have been deleted or edited externally

            # 🔔 One-time reminder once remaining hits ~10s.
            # 🩹 BUGFIX: was `remaining == 10`, an exact match on a value
            # that only lands cleanly when the timer started as a multiple
            # of 5 (always true for the default 20s, but resumed timers can
            # start at an odd remaining value like 13s, in which case
            # `remaining` ticks 13→8 and 10 is skipped entirely, so the
            # reminder never fired).
            if not reminder_sent and remaining <= 10:
                reminder_sent = True
                try:
                    await context.bot.send_message(
                        chat_id,
                        f"⏰ <b>10 seconds left</b> to bid on <b>{auction.current_player_name}</b>! Hurry up! 🔷",
                        parse_mode=ParseMode.HTML
                    )
                except Exception:
                    pass

        # ── Resolve Bid ──
        enter_confirm = False
        unsold_next_up = False
        async with auction_locks[chat_id]:
            if auction.phase != AuctionPhase.AUCTION_LIVE:
                return

            # Delete countdown message cleanly
            if auction.countdown_message_id:
                try:
                    await context.bot.delete_message(chat_id, auction.countdown_message_id)
                except Exception:
                    pass
                auction.countdown_message_id = None

            if auction.current_highest_bid > auction.current_base_price:
                # ── SOLD — Ask auctioneer to confirm ──
                auction.bids_frozen = True  # freeze bids during confirmation window
                auction.pending_sold_confirmation = True
                
                # Setup event
                auction.sold_confirm_event = asyncio.Event()
                auction.confirm_action = None
                enter_confirm = True

                _pid  = auction.current_player_id
                _pname = auction.current_player_name
                _price = auction.current_highest_bid
                _base = auction.current_base_price  # 🩹 keep original base for cancelbid/reject re-queue
                _bidder = auction.current_highest_bidder
                _team = auction.teams[_bidder]

                player_tag = f'<a href=\"tg://user?id={_pid}\">{html.escape(_pname)}</a>' + _title_suffix(_pid)
                confirm_msg = themed(
                    "SOLD?",
                    [
                        f"👤 Player: {player_tag}",
                        f"💰 Bid: <b>{_price} 🔷</b> by <b>{html.escape(_bidder)}</b>",
                        "⏱ Auctioneer has 10 seconds to confirm.",
                        "Auto-confirms if no response.",
                        "Use <code>/confirmsold</code> or <code>/rejectsold</code>.",
                    ],
                    "🔨"
                )
                kb = InlineKeyboardMarkup([[
                    styled_button("SOLD!", callback_data=f"auc_confirm_sold_{chat_id}"),
                    styled_button("Reject", callback_data=f"auc_reject_sold_{chat_id}"),
                ]])
                try:
                    conf_m = await context.bot.send_message(chat_id, confirm_msg, parse_mode=ParseMode.HTML, reply_markup=kb)
                    conf_mid = conf_m.message_id
                except Exception:
                    conf_mid = None
            else:
                # ── UNSOLD ──
                auction.unsold_players.append({
                    "player_id": auction.current_player_id,
                    "player_name": auction.current_player_name,
                    "base_price": auction.current_base_price
                })
                auction.auction_history.append({
                    "player_id": auction.current_player_id,
                    "player_name": auction.current_player_name,
                    "team": None,
                    "price": auction.current_base_price,
                    "sold": False
                })

                player_tag = f'<a href=\"tg://user?id={auction.current_player_id}\">{html.escape(auction.current_player_name)}</a>' + _title_suffix(auction.current_player_id)
                msg = themed(
                    "AUCTION — UNSOLD",
                    [
                        f"🔴 Player: {player_tag}",
                        f"🪙 Base price: <b>{auction.current_base_price} 🔷</b>",
                        "❌ No bids were placed.",
                        f"📊 Total unsold: <b>{len(auction.unsold_players)}</b>",
                        "⏳ Next player coming up.",
                    ],
                    "🔨"
                )
                try:
                    await context.bot.send_animation(chat_id, _auction_gif("auction_unsold"), caption=msg, parse_mode=ParseMode.HTML)
                except Exception:
                    await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)

                # Update history log message
                await _update_auction_history_message(context, chat_id, auction)

                # Reset state
                auction.current_player_id = None
                auction.current_player_name = ""
                auction.current_highest_bid = 0
                auction.current_highest_bidder = None
                auction.bid_timer_task = None
                unsold_next_up = True

        # 🐛 FIX: bring the next player up OUTSIDE the auction lock.
        # Previously this sleep(7) + bring_next_player() call sat *inside*
        # `async with auction_locks[chat_id]:`, which held the lock for the
        # whole 7s wait plus bring_next_player's network/DB calls. Any bid
        # coming in during that window just hung waiting on the lock, and if
        # bring_next_player raised anything it bubbled up to the generic
        # `except Exception` below and got misreported as a "TIMER ERROR"
        # even though it had nothing to do with the timer.
        if unsold_next_up:
            await asyncio.sleep(7)
            try:
                await bring_next_player(context, chat_id, auction)
            except Exception as e:
                logger.error(f"bring_next_player (unsold) error: {e}")
                await context.bot.send_message(
                    chat_id,
                    "⚠️ <b>ERROR BRINGING NEXT PLAYER!</b>\n\nPlease use /nextplayer or contact host.",
                    parse_mode=ParseMode.HTML
                )

        if enter_confirm:
            # Wait 10 seconds or until event is set (outside the lock)
            try:
                await asyncio.wait_for(auction.sold_confirm_event.wait(), timeout=10.0)
            except asyncio.TimeoutError:
                auction.confirm_action = "timeout"

            # Acquire lock to finalize state safely
            async with auction_locks[chat_id]:
                # If auction object is no longer active in active_auctions, exit
                if chat_id not in active_auctions or active_auctions[chat_id] is not auction:
                    return

                action = auction.confirm_action or "timeout"
                auction.pending_sold_confirmation = False
                auction.bids_frozen = False

                if action in ("confirm", "timeout"):
                    # Finalize sale
                    _team.add_player(_pid, _pname, _price)
                    auction.sold_players.append({"player_id": _pid, "player_name": _pname, "price": _price, "team": _bidder, "base_price": _base})
                    auction.auction_history.append({"player_id": _pid, "player_name": _pname, "team": _bidder, "price": _price, "sold": True})
                    
                    final_msg = (
                        f"🔨 <b>SOLD!</b> ({'Auctioneer Confirmed' if action == 'confirm' else 'Auto-Confirmed'}) → {_bidder}\n\n"
                        f"👤 {player_tag}\n"
                        f"💰 Final Price: <b>{_price} 🔷</b>\n"
                        f"💼 Purse Remaining: <b>{_team.purse_remaining}</b>  ·  Squad: <b>{len(_team.players)}</b>\n\n"
                        f"🎯 Next player coming up..."
                    )
                    
                    if conf_mid:
                        try:
                            await context.bot.edit_message_text(chat_id=chat_id, message_id=conf_mid, text=final_msg, parse_mode=ParseMode.HTML)
                        except Exception:
                            pass

                    final_anim_msg = (
                        f"🔨 <b>AUCTION: SOLD!</b>\n"
                        f"<blockquote>┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                        f"👤 Player : {player_tag}\n"
                        f"🎯 Buyer  : {_bidder}\n"
                        f"💰 Price  : {_price} 🔷\n"
                        f"</blockquote>\n"
                        f"💳 <b>WALLET DETAILS</b>\n"
                        f"<blockquote>┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                        f"💵 Purse  : {_team.purse_remaining} 🔷\n"
                        f"👥 Squad  : {len(_team.players)}\n"
                        f"</blockquote>\n"
                        f"⏳ Next player coming up..."
                    )
                    try:
                        sold_gif = _auction_gif("auction_sold")
                        await context.bot.send_animation(chat_id, sold_gif, caption=final_anim_msg, parse_mode=ParseMode.HTML)
                    except Exception:
                        await context.bot.send_message(chat_id, final_anim_msg, parse_mode=ParseMode.HTML)

                elif action == "reject":
                    # Put player back to front of pool for re-auction
                    auction.player_pool.insert(0, {"player_id": _pid, "player_name": _pname, "base_price": _base})
                    
                    reject_msg = (
                        f"❌ <b>SALE REJECTED</b> by Auctioneer!\n\n"
                        f"👤 <b>{_pname}</b> goes back to bidding.\n"
                        f"🎯 Next player coming up..."
                    )
                    if conf_mid:
                        try:
                            await context.bot.edit_message_text(chat_id=chat_id, message_id=conf_mid, text=reject_msg, parse_mode=ParseMode.HTML)
                        except Exception:
                            pass

                # Update history log message
                await _update_auction_history_message(context, chat_id, auction)

                # Reset state
                auction.current_player_id = None
                auction.current_player_name = ""
                auction.current_highest_bid = 0
                auction.current_highest_bidder = None
                auction.bid_timer_task = None

            # 🐛 FIX: same lock-holding bug as the UNSOLD path above — bring
            # the next player up AFTER releasing the lock, not while still
            # holding it.
            await asyncio.sleep(7)
            try:
                await bring_next_player(context, chat_id, auction)
            except Exception as e:
                logger.error(f"bring_next_player (sold) error: {e}")
                await context.bot.send_message(
                    chat_id,
                    "⚠️ <b>ERROR BRINGING NEXT PLAYER!</b>\n\nPlease use /nextplayer or contact host.",
                    parse_mode=ParseMode.HTML
                )

    except asyncio.CancelledError:
        # ⚡ REAL-TIME FIX: a new bid came in — do NOT delete the old message.
        # Just strip its buttons (so it becomes a static snapshot of that
        # moment) and leave it in the chat. The new bid_timer task that
        # cancelled us will send a brand-new message with fresh quick-bid
        # buttons right away, so bidding feels instant.
        if auction.countdown_message_id:
            try:
                await context.bot.edit_message_reply_markup(
                    chat_id=chat_id,
                    message_id=auction.countdown_message_id,
                    reply_markup=None
                )
            except Exception:
                pass
            auction.countdown_message_id = None
    except Exception as e:
        logger.error(f"Bid timer error: {e}")
        await context.bot.send_message(
            chat_id,
            "⚠️ <b>TIMER ERROR!</b>\n\nAuction paused. Please contact host.",
            parse_mode=ParseMode.HTML
        )

async def changeauctioneer_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔄 Change auctioneer.
    • CURRENT AUCTIONEER: reply to the new person with /changeauctioneer (or /changeauctioner)
      → they become the auctioneer instantly.
    • Bidders: same command, but needs 4 bidder votes (old behaviour)."""
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\n"
            "Start an auction first.",
            parse_mode=ParseMode.HTML
        )
        return
    auction = active_auctions[chat.id]
    is_current_auctioneer = (user.id == auction.auctioneer_id)
    # Only the auctioneer (instant) or bidders (vote) can use this
    is_bidder = any(team.bidder_id == user.id for team in auction.teams.values())
    if not is_current_auctioneer and not is_bidder:
        await update.message.reply_text(
            "⚠️ <b>NOT ALLOWED!</b>\n\n"
            "Only the current auctioneer (instant) or bidders (vote) can change the auctioneer!",
            parse_mode=ParseMode.HTML
        )
        return
    # Must reply to a user
    if not update.message.reply_to_message or not update.message.reply_to_message.from_user:
        await update.message.reply_text(
            "⚠️ <b>REPLY REQUIRED!</b>\n\n"
            "Reply to the user you want as new auctioneer with <code>/changeauctioneer</code>!",
            parse_mode=ParseMode.HTML
        )
        return
    new_auctioneer = update.message.reply_to_message.from_user
    if new_auctioneer.is_bot:
        await update.message.reply_text("⚠️ A bot can't be the auctioneer!")
        return
    if new_auctioneer.id == auction.auctioneer_id:
        await update.message.reply_text("⚠️ This user is already the auctioneer!")
        return

    # ⚡ Current auctioneer hands over directly — no votes needed.
    if is_current_auctioneer:
        old_name = auction.auctioneer_name or user.first_name
        auction.auctioneer_id = new_auctioneer.id
        auction.auctioneer_name = new_auctioneer.first_name
        auction.auctioneer_change_votes.clear()
        await update.message.reply_text(
            f"✅ <b>AUCTIONEER CHANGED!</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            f"📢 <b>Old Auctioneer:</b> {html.escape(old_name)}\n"
            f"🎤 <b>New Auctioneer:</b> {get_user_tag(new_auctioneer)}\n\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
        return
    # Register vote
    auction.auctioneer_change_votes.add(user.id)
    # Check vote threshold (4 votes needed)
    if len(auction.auctioneer_change_votes) >= 4:
        old_name = auction.auctioneer_name
        auction.auctioneer_id = new_auctioneer.id
        auction.auctioneer_name = new_auctioneer.first_name
        auction.auctioneer_change_votes.clear()
        await update.message.reply_text(
            f"✅ <b>AUCTIONEER CHANGED!</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            f"📢 <b>Old Auctioneer:</b> {old_name}\n"
            f"🎤 <b>New Auctioneer:</b> {get_user_tag(new_auctioneer)}\n\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )
    else:
        votes_needed = 4 - len(auction.auctioneer_change_votes)
        await update.message.reply_text(
            f"🗳️ <b>VOTE RECORDED!</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            f"✅ <b>Votes Received:</b> {len(auction.auctioneer_change_votes)}/4\n"
            f"⏳ <b>Votes Needed:</b> {votes_needed} more\n\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
            parse_mode=ParseMode.HTML
        )

async def assist_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🤝 Auctioneer assists a bidder"""
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_auctions:
        await update.message.reply_text(
            "🚫 <b>NO ACTIVE AUCTION!</b>\n\n"
            "Start an auction first.",
            parse_mode=ParseMode.HTML
        )
        return
    auction = active_auctions[chat.id]
    # Only Auctioneer Access
    if user.id != auction.auctioneer_id:
        await update.message.reply_text(
            "🎤 <b>AUCTIONEER ONLY!</b>\n\n"
            "Only the auctioneer can use assist mode!",
            parse_mode=ParseMode.HTML
        )
        return
    # Status View (No Args)
    if not context.args:
        status_lines = []
        for team_name, team in auction.teams.items():
            status = "✅ ON" if auction.assist_mode.get(team_name) else "❌ OFF"
            status_lines.append(f"🏏 <b>{html.escape(team_name)}</b>: {status}")
        vc_status = "✅ ON" if getattr(auction, 'vc_assist_enabled', False) else "❌ OFF"
        status_lines.append(f"👑 Vice Captain Bidding: {vc_status}")
        status_lines.extend([
            "📋 Usage:",
            "<code>/assist [team_name]</code>",
            "<code>/assist vc</code> — enable VC bidding",
            "<code>/assist vcoff</code> — disable VC bidding",
        ])
        msg = themed("ASSIST MODE", status_lines, "🤝")
        await update.message.reply_text(msg, parse_mode=ParseMode.HTML)
        return

    # 🆕 /assist vc | /assist vcoff — global Vice Captain bidding toggle,
    # separate from the per-team assist_mode below.
    if len(context.args) == 1 and context.args[0].lower() in ("vc", "vcoff"):
        turn_on = context.args[0].lower() == "vc"
        auction.vc_assist_enabled = turn_on
        status = "ENABLED" if turn_on else "DISABLED"
        emoji = "✅" if turn_on else "❌"
        detail = (
            "Every team's Vice Captain can now bid on their own team's behalf, alongside the bidder."
            if turn_on else
            "Vice Captains can no longer bid — only the assigned bidder (and per-team /assist) can."
        )
        await update.message.reply_text(
            themed("VICE CAPTAIN BIDDING", [detail, f"Status: <b>{status}</b>"], emoji),
            parse_mode=ParseMode.HTML
        )
        return

    # Method 1: Reply to user + team name (NEW FEATURE)
    if update.message.reply_to_message and context.args:
        team_name = " ".join(context.args)
        target_user = update.message.reply_to_message.from_user
        
        if team_name not in auction.teams:
            await update.message.reply_text(
                "❌ <b>TEAM NOT FOUND!</b>\n\n"
                "Please check the team name and try again.",
                parse_mode=ParseMode.HTML
            )
            return
        
        # Initialize assisted_bidders if not exists
        if not hasattr(auction, 'assisted_bidders'):
            auction.assisted_bidders = {}
        
        current = auction.assist_mode.get(team_name, False)
        auction.assist_mode[team_name] = not current
        
        # Store bidder ID who can also bid
        if not current:
            auction.assisted_bidders[team_name] = target_user.id
        else:
            if team_name in auction.assisted_bidders:
                del auction.assisted_bidders[team_name]
        
        status = "ENABLED" if not current else "DISABLED"
        emoji = "✅" if not current else "❌"
        target_tag = f'<a href=\"tg://user?id={target_user.id}\">{html.escape(target_user.first_name)}</a>' + _title_suffix(target_user.id)
        assist_message = '🎤 Auctioneer can bid on their behalf!\n👤 Bidder can also bid using bid [amount]!' if not current else '❌ Assist mode turned off.'
        
        await update.message.reply_text(
            themed(
                "ASSIST MODE",
                [
                    f"Status: <b>{status}</b>",
                    f"🏏 Team: <b>{html.escape(team_name)}</b>",
                    f"👤 Bidder: {target_tag}",
                    assist_message,
                ],
                emoji,
            ),
            parse_mode=ParseMode.HTML
        )
        return
    
    # Method 2: Just team name (backward compatibility)
    team_name = " ".join(context.args)
    if team_name not in auction.teams:
        await update.message.reply_text(
            "❌ <b>TEAM NOT FOUND!</b>\n\n"
            "Please check the team name and try again.",
            parse_mode=ParseMode.HTML
        )
        return
    current = auction.assist_mode.get(team_name, False)
    auction.assist_mode[team_name] = not current
    status = "ENABLED" if not current else "DISABLED"
    emoji = "✅" if not current else "❌"
    await update.message.reply_text(
        themed(
            "ASSIST MODE",
            [
                f"Status: <b>{status}</b>",
                f"🏏 Team: <b>{html.escape(team_name)}</b>",
                ('🎤 You can now bid on their behalf!' if not current else '❌ Assist mode turned off.'),
            ],
            emoji,
        ),
        parse_mode=ParseMode.HTML
    )

async def aucsummary_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """📊 Show auction summary"""
    chat = update.effective_chat
    if chat.id not in active_auctions:
        await update.message.reply_text(
            "❌ <b>NO ACTIVE AUCTION!</b>\n\n"
            "Start an auction first.",
            parse_mode=ParseMode.HTML
        )
        return
    auction = active_auctions[chat.id]
    msg = "📊 <b>AUCTION SUMMARY</b>\n"
    msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
    for team_name, team in auction.teams.items():
        msg += f"🏏 <b>{team_name}</b>\n"
        msg += f"💰 <b>Purse:</b> {team.purse_remaining}/1000\n"
        msg += f"👥 <b>Players:</b> {len(team.players)}\n\n"
        if team.players:
            msg += "<b>Squad:</b>\n"
            for p in team.players:
                msg += f" • {p['player_name']} (💰{p['price']})\n"
            msg += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
    msg += f"📊 <b>Players in Pool:</b> {len(auction.player_pool)}\n"
    msg += f"❌ <b>Unsold Players:</b> {len(auction.unsold_players)}"
    
    # Send with pagination if needed
    if len(msg) <= 4096:
        await update.message.reply_text(msg, parse_mode=ParseMode.HTML)
    else:
        # Split into chunks
        lines = msg.split("\n")
        chunk = ""
        for line in lines:
            if len(chunk) + len(line) + 1 > 4000:
                await update.message.reply_text(chunk, parse_mode=ParseMode.HTML)
                chunk = line + "\n"
            else:
                chunk += line + "\n"
        if chunk.strip():
            await update.message.reply_text(chunk, parse_mode=ParseMode.HTML)

async def end_auction(context: ContextTypes.DEFAULT_TYPE, chat_id: int, auction: Auction):
    """🏆 End auction with COMPLETE SCORECARD"""
    _capture_pre_end_blob(chat_id, auction)          # state BEFORE conclusion (no-op if already taken)
    auction.phase = AuctionPhase.AUCTION_ENDED
    # 🎬 ENDING GIF
    end_gif = GIFS.get("auction_end")
    _ended_by_name = getattr(auction, 'auctioneer_name', None) or "Auctioneer"
    msg = (
        "🏆 <b>AUCTION COMPLETE!</b>\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        "🎉 All players have been auctioned!\n\n"
        f"👤 <b>Ended by:</b> {html.escape(_ended_by_name)}\n\n"
        "📊 Preparing Final Scorecard...\n\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
    )
    try:
        await context.bot.send_animation(
            chat_id,
            animation=end_gif,
            caption=msg,
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 23640)")
        await context.bot.send_photo(
            chat_id,
            photo=MEDIA_ASSETS.get("auction_end"),
            caption=msg,
            parse_mode=ParseMode.HTML
        )
    await asyncio.sleep(3)
    # 📋 COMPLETE SCORECARD — same approach as /fantasylb: try a native
    # <table>+<details> rich message first; fall back to the text-table
    # <blockquote expandable> pages only if the rich send fails.
    header_block = "🏆 <b>AUCTION FINAL SCORECARD</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    footer_block = "\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n🎉 <b>Thank you for participating!</b>"

    # Sort teams by total spent
    sorted_teams = sorted(
        auction.teams.values(),
        key=lambda x: x.total_spent,
        reverse=True
    )

    def _team_table(team) -> str:
        sorted_players = sorted(team.players, key=lambda x: x['price'], reverse=True)
        t = f"{_auc_pad('#', 4)}{_auc_pad('🧢 Player', 14)}{_auc_pad('🆔 ID', 12)}{_auc_pad('👤 Username', 16)}{_auc_rpad('💰 Price', 8)}\n"
        t += ("—" * 54) + "\n"
        for j, p in enumerate(sorted_players, 1):
            pid = p.get('player_id', '')
            uname = _auc_username_tag(pid)
            t += f"{_auc_pad(j, 4)}{_auc_pad(p['player_name'], 14)}{_auc_pad(pid or '—', 12)}{_auc_pad(uname, 16)}{_auc_rpad(p['price'], 8)}\n"
        if not sorted_players:
            t += "  No players bought\n"
        return t

    def _team_table_rows(team) -> str:
        sorted_players = sorted(team.players, key=lambda x: x['price'], reverse=True)
        if not sorted_players:
            return "<tr><td colspan='5'><i>No players bought</i></td></tr>"
        rows = ""
        for j, p in enumerate(sorted_players, 1):
            pid = p.get('player_id', '')
            uname = _auc_username_tag(pid)
            rows += (
                f"<tr><td align='center'>{j}</td>"
                f"<td>{html.escape(p['player_name'])}</td>"
                f"<td align='center'>{pid or '—'}</td>"
                f"<td align='center'>{html.escape(uname)}</td>"
                f"<td align='right'>{p['price']}</td></tr>"
            )
        return rows

    # ── Try native rich table+dropdown first (same as /fantasylb) ──
    rich_blocks = ""
    for i, team in enumerate(sorted_teams, 1):
        medal = "🥇" if i == 1 else "🥈" if i == 2 else "🥉" if i == 3 else f"{i}."
        captain_name = getattr(team, 'captain_name', '') or "—"
        vc_name = getattr(team, 'vice_captain_name', '') or "—"
        header_line = (
            f"{medal} <b>Team:</b> {html.escape(team.name)}\n"
            f"👑 <b>Captain :</b> {html.escape(captain_name)}\n"
            f"🎗️ <b>Vice Cap:</b> {html.escape(vc_name)}"
        )
        summary = f"📋 Team (Spent: {team.total_spent} | Left: {team.purse_remaining})"
        table = (
            "<table bordered striped><tr><th>#</th><th>🧢 Player</th><th>🆔 ID</th><th>👤 Username</th><th>💰 Price</th></tr>"
            f"{_team_table_rows(team)}</table>"
        )
        rich_blocks += f"{header_line}\n<details><summary>{summary}</summary>{table}</details>\n"

    if auction.unsold_players:
        rows = ""
        for i, player_data in enumerate(auction.unsold_players, 1):
            name = player_data if isinstance(player_data, str) else player_data.get('player_name', 'Unknown')
            base = "" if isinstance(player_data, str) else player_data.get('base_price', player_data.get('price', ''))
            pid = "" if isinstance(player_data, str) else player_data.get('player_id', '')
            uname = _auc_username_tag(pid)
            rows += (
                f"<tr><td align='center'>{i}</td>"
                f"<td>{html.escape(str(name))}</td>"
                f"<td align='center'>{pid or '—'}</td>"
                f"<td align='center'>{html.escape(uname)}</td>"
                f"<td align='right'>{base}</td></tr>"
            )
        unsold_table = (
            "<table bordered striped><tr><th>#</th><th>🧢 Player</th><th>🆔 ID</th><th>👤 Username</th><th>💰 Base</th></tr>"
            f"{rows}</table>"
        )
        rich_blocks += f"<details><summary>❌ Unsolds ({len(auction.unsold_players)})</summary>{unsold_table}</details>"

    rich_html = (
        "<h3>🏆 AUCTION FINAL SCORECARD</h3>"
        f"{rich_blocks}"
        "<footer>🎉 Thank you for participating!</footer>"
    )
    rich_ok = await _tg_send_rich_message(chat_id, rich_html)

    if not rich_ok:
        # Build one self-contained HTML block per team — every team is a collapsed
        # "▾ 🥇 TeamName" dropdown that opens into its table, exactly like /fantasylb's
        # "▾ 📊 Top Managers" dropdown when the native rich table isn't available.
        section_blocks = []
        for i, team in enumerate(sorted_teams, 1):
            medal = "🥇" if i == 1 else "🥈" if i == 2 else "🥉" if i == 3 else f"{i}."
            captain_name = getattr(team, 'captain_name', '') or "—"
            vc_name = getattr(team, 'vice_captain_name', '') or "—"
            team_header = (
                f"{medal} <b>Team:</b> {html.escape(team.name)}\n"
                f"👑 <b>Captain :</b> {html.escape(captain_name)}\n"
                f"🎗️ <b>Vice Cap:</b> {html.escape(vc_name)}\n"
                f"📋 Team (Spent: {team.total_spent} | Left: {team.purse_remaining})"
            )
            team_table = _team_table(team)
            block = f"<blockquote expandable>{team_header}\n<pre>{team_table}</pre></blockquote>"
            section_blocks.append(block)

        # ❌ UNSOLD SUMMARY — also a collapsed "▾ Unsolds" dropdown, same as CCC sections
        if auction.unsold_players:
            unsold_header = f"❌ <b>Unsolds ({len(auction.unsold_players)})</b>"
            unsold_table = f"{_auc_pad('#', 4)}{_auc_pad('🧢 Player', 14)}{_auc_pad('🆔 ID', 12)}{_auc_pad('👤 Username', 16)}{_auc_rpad('💰 Price', 8)}\n"
            unsold_table += ("—" * 54) + "\n"
            for i, player_data in enumerate(auction.unsold_players, 1):
                name = player_data if isinstance(player_data, str) else player_data.get('player_name', 'Unknown')
                base = "" if isinstance(player_data, str) else player_data.get('base_price', player_data.get('price', ''))
                pid = "" if isinstance(player_data, str) else player_data.get('player_id', '')
                uname = _auc_username_tag(pid)
                unsold_table += f"{_auc_pad(i, 4)}{_auc_pad(name, 14)}{_auc_pad(pid or '—', 12)}{_auc_pad(uname, 16)}{_auc_rpad(base, 8)}\n"
            unsold_block = f"<blockquote expandable>{unsold_header}\n<pre>{unsold_table}</pre></blockquote>"
            section_blocks.append(unsold_block)

        # Send with pagination by whole section (team/unsold block) — never split
        # a block mid-tag, since each is a self-contained <blockquote expandable>.
        pages = []
        current = header_block
        for block in section_blocks:
            if len(current) + len(block) + 2 > 3900:
                pages.append(current)
                current = "<i>(continued...)</i>\n\n" + block
            else:
                current += "\n\n" + block
        current += footer_block
        pages.append(current)

        for page_text in pages:
            await context.bot.send_message(chat_id, page_text, parse_mode=ParseMode.HTML)
    # 💾 BUGFIX: auction results (sold players → team, price) were never
    # actually persisted anywhere. save_auction_results_to_db() existed but
    # was never called from here, so /auctionresults, /exportauction and
    # any stats built on top of `auction_results` always came back empty.
    try:
        await save_auction_results_to_db(chat_id, auction)
    except Exception as e:
        logger.error(f"end_auction: failed to save auction results to DB: {e}")
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text="⚠️ Auction finished, but saving the results to the database failed. Ask the owner to check logs.",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass

    # Cleanup
    if chat_id in active_auctions:
        del active_auctions[chat_id]
    # 🔑 Natural end → instead of discarding the /reauction snapshot, keep a
    # FINAL copy around for 7 days as a recovery safety-net. The Auctioneer
    # of this specific auction can pull it back with /reauction <code>
    # during that window; after 7 days the cleanup job auto-deletes it,
    # same as any other expired snapshot.
    #
    # 🩹 BUGFIX (save-before-discard): this used to discard the OLD
    # short-TTL snapshot BEFORE saving the new 7-day one. If the new save
    # ever failed for any reason (e.g. a leftover unpicklable object on the
    # auction from an in-progress /addauctionplayer that never finished),
    # the old snapshot was already gone — so /reauction had literally
    # nothing to find and always said "Invalid or expired", even though
    # the auction had just fully, successfully completed. Now we save the
    # new snapshot FIRST and only discard the old one once that succeeds,
    # so a save failure never leaves the group with zero recoverable code.
    old_code = getattr(auction, 'resume_code', None) or ""
    _pre_blob = _PRE_END_BLOBS.pop(chat_id, None)
    final_code = await asyncio.to_thread(save_auction_for_resume, auction, AUCTION_NATURAL_END_TTL_HOURS, True, _pre_blob)
    _auction_fp_seen.pop(chat_id, None)
    if final_code:
        if old_code and old_code != final_code:
            _discard_resumable_auction(old_code)
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text=(
                    f"💾 <b>Auction saved!</b>\n"
                    f"Resume code: <code>{final_code}</code>\n"
                    f"The Auctioneer can bring it back with "
                    f"<code>/reauction {final_code}</code> in this same group, within the next "
                    f"<b>7 days</b> — after that it's auto-deleted."
                ),
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.debug(f"Could not announce final auction resume code: {e}")
    else:
        # Save genuinely failed even after the pending_bulk_add sanitize —
        # tell the group plainly instead of leaving them to hit a silent
        # "Invalid or expired" wall with no explanation.
        logger.error(f"end_auction: save_auction_for_resume returned None for group {chat_id} — no resumable snapshot saved.")
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text="⚠️ Couldn't save a resumable snapshot for this auction. /reauction won't be available for it.",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass


def _fetch_stats_view_data(target_id: int):
    """Blocking DB reads for stats_view_callback — always call this via
    asyncio.to_thread, never directly on the event loop."""
    conn= db_connect(DB_PATH)
    c = conn.cursor()

    c.execute("SELECT * FROM user_stats WHERE user_id = ?", (target_id,))
    db_stats = c.fetchone()

    # Count solo matches
    c.execute("""
        SELECT COUNT(*) FROM match_history 
        WHERE match_type = 'SOLO' 
        AND (player_of_match = ? OR group_id IN 
            (SELECT group_id FROM match_history WHERE match_type = 'SOLO'))
    """, (target_id,))
    row = c.fetchone()
    solo_matches = row[0] if row else 0

    # Count solo wins (top 3 finishes)
    c.execute("""
        SELECT COUNT(*) FROM match_history 
        WHERE match_type = 'SOLO' AND player_of_match = ?
    """, (target_id,))
    row = c.fetchone()
    solo_wins = row[0] if row else 0

    # Solo bowling stats (dedicated named-column query — kept separate from the
    # positional SELECT * above so new solo_* columns never shift that unpack).
    c.execute("""
        SELECT solo_total_wickets, solo_total_balls_bowled, solo_total_runs_conceded,
               solo_best_bowling_wickets, solo_best_bowling_runs, solo_matches_bowled
        FROM user_stats WHERE user_id = ?
    """, (target_id,))
    solo_bowl_row = c.fetchone()
    solo_bowling = {
        "wickets": solo_bowl_row[0] if solo_bowl_row else 0,
        "balls_bowled": solo_bowl_row[1] if solo_bowl_row else 0,
        "runs_conceded": solo_bowl_row[2] if solo_bowl_row else 0,
        "best_wickets": solo_bowl_row[3] if solo_bowl_row else 0,
        "best_runs": solo_bowl_row[4] if solo_bowl_row else 0,
        "matches_bowled": solo_bowl_row[5] if solo_bowl_row else 0,
    }

    conn.close()
    return db_stats, solo_matches, solo_wins, solo_bowling


async def stats_view_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles Stats Menu Clicks with Tree-Style Formatting - DATABASE VERSION"""
    query = update.callback_query
    await query.answer()
    
    try:
        parts = query.data.split("_")
        mode = parts[2]  # 'solo' or 'team'
        target_id = int(parts[3])
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 23746)")
        return

    # ========== FETCH FROM DATABASE ==========
    # 🔧 SCALE FIX: runs in a background thread so this group's stats lookup
    # never blocks ball-processing/messages in other groups.
    db_stats, solo_matches, solo_wins, solo_bowling = await asyncio.to_thread(_fetch_stats_view_data, target_id)
    
    # Get Player Name
    try:
        chat = await context.bot.get_chat(target_id)
        name = chat.first_name
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 23758)")
        name = "Player"

    # ========== PARSE DATABASE STATS ==========
    if db_stats:
        (user_id, username, first_name, total_runs, total_balls_faced, total_fours,
         total_sixes, total_fifties, total_hundreds, highest_score, times_not_out,
         total_wickets, total_balls_bowled, total_runs_conceded, total_maidens,
         best_bowling_wickets, best_bowling_runs, five_wicket_hauls,
         matches_played, matches_won, player_of_match_count, last_updated) = db_stats
    else:
        # No stats found
        await query.message.edit_text(
            "📊 No stats found!\n"
            "Play some matches to build your profile! 🏏"
        )
        return

    # ========== MODE-SPECIFIC STATS ==========
    if mode == "solo":
        # SOLO MODE STATS
        matches = solo_matches if solo_matches > 0 else matches_played
        runs = total_runs
        balls = total_balls_faced
        highest = highest_score
        wins = solo_wins
        
        # Bowling stats (not used in solo)
        wickets = 0
        centuries = total_hundreds
        fifties = total_fifties
        ducks = 0  # Track this if you want
        mom = 0
        fours = total_fours
        sixes = total_sixes
        
        # Calculations
        bat_avg = round(runs / max(1, matches), 2)
        bat_sr = round((runs / balls * 100), 2) if balls > 0 else 0.0
        win_rate = round((wins / matches * 100), 2) if matches > 0 else 0.0
        top3 = wins  # Assuming wins = top 3 finishes in solo

        # Bowling stats (now tracked for solo mode)
        solo_wkts = solo_bowling["wickets"]
        solo_balls_bowled = solo_bowling["balls_bowled"]
        solo_runs_conceded = solo_bowling["runs_conceded"]
        solo_overs_text = format_overs(solo_balls_bowled)
        solo_economy = round((solo_runs_conceded / solo_balls_bowled) * 6, 2) if solo_balls_bowled > 0 else 0.0
        solo_bowl_avg = round(solo_runs_conceded / solo_wkts, 2) if solo_wkts > 0 else 0.0
        solo_best_bowl = (
            f"{solo_bowling['best_wickets']}/{solo_bowling['best_runs']}"
            if solo_bowling["matches_bowled"] > 0 else "N/A"
        )

        # Image Data
        img_data = {
            "matches": matches,
            "runs": runs,
            "average": bat_avg,
            "strike_rate": bat_sr,
            "centuries": centuries,
            "wickets": solo_wkts,
            "highest": highest
        }

        # Caption
        caption = (
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"👤 <b>SOLO CAREER PROFILE</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"📛 <b>Player:</b> “{name.upper()}”\n"
            f"🆔 <b>ID:</b> “<code>{target_id}</code>”\n\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"<b>📈 PLAYER RECORD 🥎</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"📊 Matches: “{matches}”\n"
            f"✅ Wins: “{wins}”\n"
            f"📈 Win Rate: “{win_rate}%”\n"
            f"🥉 Top 3 Finishes: “{top3}”\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"🏏 <b>BATTING SKILLS</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"🏃 <b>Total Runs:</b> “{runs}”\n"
            f"⚾ <b>Balls Faced:</b> “{balls}”\n"
            f"⚡ <b>Strike Rate:</b> “{bat_sr}”\n"
            f"🚀 <b>High Score:</b> “{highest}”\n"
            f"4️⃣ <b>Fours:</b> “{fours}” | 6️⃣ <b>Sixes:</b> “{sixes}”\n"
            f"💯 <b>100s:</b> “{centuries}” | ⁵⁰ <b>50s:</b> “{fifties}”\n"
            f"🦆 <b>Ducks:</b> “{ducks}”\n\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"⚾ <b>BOWLING SKILLS</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"🎳 <b>Wickets:</b> “{solo_wkts}”\n"
            f"🎯 <b>Overs Bowled:</b> “{solo_overs_text}”\n"
            f"🏏 <b>Runs Conceded:</b> “{solo_runs_conceded}”\n"
            f"💰 <b>Economy:</b> “{solo_economy}”\n"
            f"📉 <b>Bowling Avg:</b> “{solo_bowl_avg if solo_wkts > 0 else 'N/A'}”\n"
            f"🏆 <b>Best Bowling:</b> “{solo_best_bowl}”"
        )

    elif mode == "team":
        # TEAM MODE STATS
        matches = matches_played
        runs = total_runs
        balls = total_balls_faced
        highest = highest_score
        wins = matches_won
        wickets = total_wickets
        centuries = total_hundreds
        fifties = total_fifties
        ducks = 0  # Track this if you want
        mom = player_of_match_count
        fours = total_fours
        sixes = total_sixes
        
        # Bowling stats
        runs_conceded = total_runs_conceded
        balls_bowled = total_balls_bowled
        hat_tricks = 0  # Track this if you want
        five_wkts = five_wicket_hauls
        best_bowl = f"{best_bowling_wickets}/{best_bowling_runs}" if best_bowling_wickets > 0 else "N/A"
        
        # Calculations
        outs = matches - times_not_out
        bat_avg = round(runs / max(1, outs), 2)
        bat_sr = round((runs / balls * 100), 2) if balls > 0 else 0.0
        
        # Bowling calculations
        overs_text = f"{balls_bowled // 6}.{balls_bowled % 6}"
        economy = round((runs_conceded / balls_bowled) * 6, 2) if balls_bowled > 0 else 0.0
        bowl_avg = round(runs_conceded / wickets, 2) if wickets > 0 else 0.0
        
        # Captaincy (track this if you want)
        cap_matches = 0
        cap_wins = 0
        cap_rate = 0.0

        # Image Data
        img_data = {
            "matches": matches,
            "runs": runs,
            "average": bat_avg,
            "strike_rate": bat_sr,
            "centuries": centuries,
            "wickets": wickets,
            "highest": highest
        }

        # Caption
        caption = (
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"👥 <b>TEAM CAREER PROFILE</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"📛 <b>Player:</b> “{name.upper()}”\n"
            f"🆔 <b>ID:</b> “<code>{target_id}</code>”\n\n"
            f"<b>📈 PLAYER RECORD 🥎</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"📊 Matches: “{matches}”\n"
            f"✅ Wins: “{wins}” | ❌ Losses: “{matches - wins}”\n"
            f"👑 Captaincy: “{cap_wins}/{cap_matches}” Wins (“{cap_rate}%”)\n"
            f"🏅 Man of Match: “{mom}”\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"<b>🏏 BATTING ARSENAL 🥎</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"🏏 Runs: “{runs}” | 🥎 Balls: “{balls}”\n"
            f"📈 Average: “{bat_avg}”\n"
            f"⚡ Strike Rate: “{bat_sr}”\n"
            f"🔝 Highest Score: “{highest}”\n"
            f"💥 Fours: “{fours}” | 🚀 Sixes: “{sixes}”\n"
            f"💯 100s: “{centuries}” | ✨ 50s: “{fifties}”\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"<b>🥎 BOWLING ATTACK 🥎</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"🎯 Wickets: “{wickets}”\n"
            f"⏳ Overs: “{overs_text}” | 📉 Economy: “{economy}”\n"
            f"📊 Average: “{bowl_avg}”\n"
            f"💎 Best Figures: “{best_bowl}”\n"
            f"🎩 Hat-tricks: “{hat_tricks}”\n"
            f"🔥 5-Wickets: “{five_wkts}”\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
        )

    # ========== GENERATE IMAGE ==========
    avatar_bytes = await fetch_user_avatar_bytes(context, target_id)
    photo_bio = await generate_stats_image(target_id, name, img_data, avatar_bytes, mode)

    # ========== SEND ==========
    keyboard = [[styled_button("Back to Menu", callback_data=f"stats_main_{target_id}")]]
    reply_markup = InlineKeyboardMarkup(keyboard)

