async def power_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """👑 Owner picks exactly which permissions a user gets, via buttons"""
    user_id = update.effective_user.id

    if user_id != OWNER_ID:
        await update.message.reply_text("❌ Only owner can use this command!")
        return

    if not context.args or len(context.args) != 1:
        await update.message.reply_text(
            "❌ <b>Usage:</b> <code>/power &lt;user_id&gt;</code>\n\n"
            "Opens a permission picker so you can choose exactly what "
            "powers to grant that user.\n\n"
            "Example: <code>/power 123456789</code>",
            parse_mode=ParseMode.HTML
        )
        return

    try:
        target_user_id = int(context.args[0])
    except ValueError:
        await update.message.reply_text("❌ Invalid user ID!")
        return

    if target_user_id == OWNER_ID:
        await update.message.reply_text("❌ Owner already has full power!")
        return

    # Pre-check existing perms (if user already has some power, start from there)
    existing = set(POWERED_USERS.get(target_user_id, set()))
    power_pending[target_user_id] = {"perms": existing, "owner_id": user_id}

    msg = await update.message.reply_text(
        _power_picker_text(target_user_id),
        reply_markup=_power_picker_keyboard(target_user_id),
        parse_mode=ParseMode.HTML
    )
    power_pending[target_user_id]["message"] = msg


def _power_picker_text(target_user_id: int) -> str:
    pending = power_pending.get(target_user_id, {"perms": set()})
    selected = pending["perms"]
    lines = [
        "👑 <b>GRANT POWER</b>",
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
        f"👤 <b>User ID:</b> <code>{target_user_id}</code>",
        "",
        "Tap to toggle which permissions to grant, then hit ✅ Done.",
        "",
    ]
    for key, label in POWER_PERMISSIONS:
        check = "✅" if key in selected else "◻️"
        lines.append(f"{check} {label}")
    lines.append("┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈")
    return "\n".join(lines)


def _power_picker_keyboard(target_user_id: int) -> InlineKeyboardMarkup:
    pending = power_pending.get(target_user_id, {"perms": set()})
    selected = pending["perms"]
    rows = []
    for key, label in POWER_PERMISSIONS:
        check = "✅" if key in selected else "◻️"
        rows.append([styled_button(f"{check} {label}", callback_data=f"pwrsel_{key}_{target_user_id}")])
    rows.append([styled_button("Done & Proceed", callback_data=f"pwrdone_{target_user_id}")])
    return InlineKeyboardMarkup(rows)


async def power_select_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Toggle a single permission checkbox in the /power picker"""
    query = update.callback_query
    # 🩹 BUGFIX: was split("_") + parts[1]/parts[2], which broke for any
    # permission key containing an underscore — "auctionset_view" became
    # key="auctionset", target="view" → int("view") ValueError, so that
    # permission could never be toggled in the /power picker. The target id
    # is always the LAST segment; the key is everything between.
    parts = query.data.split("_")  # pwrsel, <key...>, <target_id>
    perm_key = "_".join(parts[1:-1])
    target_user_id = int(parts[-1])

    pending = power_pending.get(target_user_id)
    if not pending:
        await query.answer(plain_alert("🚫 This request expired. Run /power again."), show_alert=True)
        return
    if query.from_user.id != pending.get("owner_id"):
        await query.answer(plain_alert("🚫 Only the owner who started this can use it!"), show_alert=True)
        return

    if perm_key in pending["perms"]:
        pending["perms"].discard(perm_key)
    else:
        pending["perms"].add(perm_key)

    await query.answer()
    await query.message.edit_text(
        _power_picker_text(target_user_id),
        reply_markup=_power_picker_keyboard(target_user_id),
        parse_mode=ParseMode.HTML
    )


async def power_done_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """✅ Finalize granting the selected permissions"""
    query = update.callback_query
    target_user_id = int(query.data.split("_", 1)[1])

    pending = power_pending.get(target_user_id)
    if not pending:
        await query.answer(plain_alert("🚫 This request expired. Run /power again."), show_alert=True)
        return
    if query.from_user.id != pending.get("owner_id"):
        await query.answer(plain_alert("🚫 Only the owner who started this can use it!"), show_alert=True)
        return

    selected = pending["perms"]
    del power_pending[target_user_id]
    await query.answer()

    if not selected:
        await query.message.edit_text(
            f"❌ <b>NO PERMISSIONS SELECTED</b>\n\n"
            f"Nothing was granted to <code>{target_user_id}</code>. Run /power again to retry.",
            parse_mode=ParseMode.HTML
        )
        return

    POWERED_USERS[target_user_id] = selected

    # 💾 Persist so it survives restarts
    try:
        _conn = db_connect(DB_FILE)
        _c = _conn.cursor()
        _c.execute(
            "INSERT INTO powered_users (user_id, permissions) VALUES (?, ?) "
            "ON CONFLICT(user_id) DO UPDATE SET permissions=excluded.permissions",
            (target_user_id, ",".join(sorted(selected)))
        )
        _conn.commit()
        _conn.close()
    except Exception as e:
        logger.error(f"Failed to persist powered user {target_user_id}: {e}")

    perm_lines = "\n".join(f"  ✓ {label}" for key, label in POWER_PERMISSIONS if key in selected)
    await query.message.edit_text(
        f"✅ <b>POWER GRANTED!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"👤 <b>User ID:</b> <code>{target_user_id}</code>\n\n"
        f"⚡ <b>Permissions:</b>\n{perm_lines}\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"Total powered users: {len(POWERED_USERS)}",
        parse_mode=ParseMode.HTML
    )
    logger.info(f"Power granted to {target_user_id} by {query.from_user.id}: {selected}")


async def rmpower_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """👑 Owner picks a powered user from a button list to remove"""
    user_id = update.effective_user.id

    if user_id != OWNER_ID:
        await update.message.reply_text("❌ Only owner can use this command!")
        return

    if not POWERED_USERS:
        await update.message.reply_text("📋 No powered users yet!\n\nUse /power <user_id> to add one.")
        return

    await update.message.reply_text(
        "👑 <b>REMOVE POWER</b>\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        "Tap a user below to remove ALL their power:",
        reply_markup=await _unpower_keyboard(context),
        parse_mode=ParseMode.HTML
    )


async def _unpower_keyboard(context: ContextTypes.DEFAULT_TYPE) -> InlineKeyboardMarkup:
    rows = []
    for uid in sorted(POWERED_USERS.keys()):
        name = str(uid)
        try:
            chat = await context.bot.get_chat(uid)
            display = chat.full_name or chat.username or str(uid)
            name = f"{display} ({uid})"
        except Exception:
            pass
        rows.append([styled_button(f"{name}", callback_data=f"unpwr_{uid}")])
    return InlineKeyboardMarkup(rows)


async def unpower_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """❌ Remove a user's power when the owner taps their button"""
    query = update.callback_query
    if query.from_user.id != OWNER_ID:
        await query.answer(plain_alert("🚫 Only owner can use this!"), show_alert=True)
        return

    target_user_id = int(query.data.split("_", 1)[1])
    await query.answer()

    if target_user_id not in POWERED_USERS:
        await query.message.edit_text("❌ That user doesn't have power anymore!")
        return

    del POWERED_USERS[target_user_id]

    try:
        _conn = db_connect(DB_FILE)
        _c = _conn.cursor()
        _c.execute("DELETE FROM powered_users WHERE user_id=?", (target_user_id,))
        _conn.commit()
        _conn.close()
    except Exception as e:
        logger.error(f"Failed to un-persist powered user {target_user_id}: {e}")

    logger.info(f"Power removed from {target_user_id} by {query.from_user.id}")

    if not POWERED_USERS:
        await query.message.edit_text(
            f"✅ <b>Power removed from</b> <code>{target_user_id}</code>\n\n"
            f"📋 No powered users left.",
            parse_mode=ParseMode.HTML
        )
        return

    await query.message.edit_text(
        f"✅ <b>Power removed from</b> <code>{target_user_id}</code>\n\n"
        f"👑 <b>REMOVE POWER</b>\n"
        f"Tap a user below to remove ALL their power:",
        reply_markup=await _unpower_keyboard(context),
        parse_mode=ParseMode.HTML
    )


