async def broadcast_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Broadcast via FORWARD (Not Copy) — runs in background
    Usage: Reply to ANY message with /broadcast
    """
    user = update.effective_user
    if not has_power(user.id, "broadcast"):
        return

    if not update.message.reply_to_message:
        await update.message.reply_text(
            "⚠️ <b>Usage:</b> Reply to any message with <code>/broadcast</code>\n\n"
            "Bot will forward that message to all users & groups.",
            parse_mode=ParseMode.HTML
        )
        return

    target_message = update.message.reply_to_message

    status_msg = await update.message.reply_text(
        "📢 <b>BROADCAST STARTED</b>\n"
        "⏳ <i>Running in background — you'll get a report when done.</i>",
        parse_mode=ParseMode.HTML
    )

    async def _do_broadcast():
        success_groups = fail_groups = success_users = fail_users = 0

        for chat_id in list(registered_groups.keys()):
            if chat_id in banned_groups:
                fail_groups += 1
                continue
            try:
                await context.bot.forward_message(
                    chat_id=chat_id,
                    from_chat_id=target_message.chat_id,
                    message_id=target_message.message_id
                )
                success_groups += 1
                await asyncio.sleep(0.05)
            except Exception as e:
                fail_groups += 1
                logger.debug(f"Broadcast group {chat_id} failed: {e}")

        for uid in list(user_data.keys()):
            try:
                await context.bot.forward_message(
                    chat_id=uid,
                    from_chat_id=target_message.chat_id,
                    message_id=target_message.message_id
                )
                success_users += 1
                await asyncio.sleep(0.05)
            except Exception as e:
                fail_users += 1
                logger.debug(f"Broadcast user {uid} failed: {e}")

        total_groups = len(registered_groups)
        total_users = len(user_data)
        banned_count = len(banned_groups)
        report = (
            "✅ <b>BROADCAST COMPLETE!</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            "👥 <b>GROUPS</b>\n"
            f"   ✅ Sent: <code>{success_groups}</code>\n"
            f"   ❌ Failed: <code>{fail_groups}</code>\n"
            f"   🚫 Banned: <code>{banned_count}</code>\n"
            f"   📊 Total: <code>{total_groups}</code>\n\n"
            "👤 <b>USERS (DMs)</b>\n"
            f"   ✅ Sent: <code>{success_users}</code>\n"
            f"   ❌ Failed: <code>{fail_users}</code>\n"
            f"   📊 Total: <code>{total_users}</code>\n\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"📌 <i>Message forwarded as-is (not copied)</i>"
        )
        try:
            await context.bot.edit_message_text(
                chat_id=update.message.chat_id,
                message_id=status_msg.message_id,
                text=report,
                parse_mode=ParseMode.HTML
            )
        except Exception:
            await context.bot.send_message(update.message.chat_id, report, parse_mode=ParseMode.HTML)

    asyncio.create_task(_do_broadcast())


async def broadcastbtn_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Broadcast WITH custom inline buttons that the owner types out.
    Usage: Reply to any message with:
        /broadcastbtn Label - https://link | Label2 - https://link2
    - Separate buttons on the SAME row with a single "|"
    - Start a NEW row with "||"
    Example:
        /broadcastbtn Join Channel - https://t.me/xyz || Contact Owner - https://t.me/owner
    """
    user = update.effective_user
    if not has_power(user.id, "broadcast"):
        return

    if not update.message.reply_to_message:
        await update.message.reply_text(
            "⚠️ <b>Usage:</b> Reply to any message with:\n"
            "<code>/broadcastbtn Label - https://link | Label2 - https://link2</code>\n\n"
            "• Separate buttons with <code>|</code> — same row\n"
            "• Use <code>||</code> — start a new row\n\n"
            "Example:\n"
            "<code>/broadcastbtn Join Channel - https://t.me/xyz || Contact Owner - https://t.me/owner</code>",
            parse_mode=ParseMode.HTML
        )
        return

    args_text = update.message.text.split(None, 1)
    args_text = args_text[1] if len(args_text) > 1 else ""

    if not args_text.strip():
        await update.message.reply_text(
            "⚠️ Please type the buttons after the command. Send <code>/broadcastbtn</code> with no reply to see the format.",
            parse_mode=ParseMode.HTML
        )
        return

    # Parse "Label - url | Label2 - url2 || Label3 - url3" into keyboard rows
    keyboard = []
    for row_text in args_text.split("||"):
        row = []
        for btn_text in row_text.split("|"):
            btn_text = btn_text.strip()
            if not btn_text or " - " not in btn_text:
                continue
            label, url = btn_text.rsplit(" - ", 1)
            label, url = label.strip(), url.strip()
            if label and url:
                row.append(styled_button(label, url=url))
        if row:
            keyboard.append(row)

    if not keyboard:
        await update.message.reply_text(
            "⚠️ Couldn't parse any buttons. Format: <code>Label - https://link</code>, separated by <code>|</code> / <code>||</code>.",
            parse_mode=ParseMode.HTML
        )
        return

    reply_markup = InlineKeyboardMarkup(keyboard)
    target_message = update.message.reply_to_message

    status_msg = await update.message.reply_text(
        "📢 <b>BROADCAST (WITH BUTTONS) STARTED</b>\n"
        "⏳ <i>Running in background — you'll get a report when done.</i>",
        parse_mode=ParseMode.HTML
    )

    async def _do_broadcast_btn():
        success_groups = fail_groups = success_users = fail_users = 0

        # copy_message (not forward) is required — only copies support attaching
        # a NEW reply_markup, so the buttons actually show up on the sent copy.
        for chat_id in list(registered_groups.keys()):
            if chat_id in banned_groups:
                fail_groups += 1
                continue
            try:
                await context.bot.copy_message(
                    chat_id=chat_id,
                    from_chat_id=target_message.chat_id,
                    message_id=target_message.message_id,
                    reply_markup=reply_markup
                )
                success_groups += 1
                await asyncio.sleep(0.05)
            except Exception as e:
                fail_groups += 1
                logger.debug(f"Broadcast(btn) group {chat_id} failed: {e}")

        for uid in list(user_data.keys()):
            try:
                await context.bot.copy_message(
                    chat_id=uid,
                    from_chat_id=target_message.chat_id,
                    message_id=target_message.message_id,
                    reply_markup=reply_markup
                )
                success_users += 1
                await asyncio.sleep(0.05)
            except Exception as e:
                fail_users += 1
                logger.debug(f"Broadcast(btn) user {uid} failed: {e}")

        total_groups = len(registered_groups)
        total_users = len(user_data)
        banned_count = len(banned_groups)
        report = (
            "✅ <b>BROADCAST (WITH BUTTONS) COMPLETE!</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            "👥 <b>GROUPS</b>\n"
            f"   ✅ Sent: <code>{success_groups}</code>\n"
            f"   ❌ Failed: <code>{fail_groups}</code>\n"
            f"   🚫 Banned: <code>{banned_count}</code>\n"
            f"   📊 Total: <code>{total_groups}</code>\n\n"
            "👤 <b>USERS (DMs)</b>\n"
            f"   ✅ Sent: <code>{success_users}</code>\n"
            f"   ❌ Failed: <code>{fail_users}</code>\n"
            f"   📊 Total: <code>{total_users}</code>\n\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
        )
        try:
            await context.bot.edit_message_text(
                chat_id=update.message.chat_id,
                message_id=status_msg.message_id,
                text=report,
                parse_mode=ParseMode.HTML
            )
        except Exception:
            await context.bot.send_message(update.message.chat_id, report, parse_mode=ParseMode.HTML)

    asyncio.create_task(_do_broadcast_btn())



def _fetch_botstats_data():
    """All the blocking sqlite reads for /botstats — always call via
    asyncio.to_thread, never directly on the event loop (owner-only command,
    but a dozen sequential queries here used to freeze every group's game
    for however long this took).

    🔧 EXPANDED: now also pulls match-type breakdown, time-windowed activity
    (today/7d/30d), top active groups, top players by runs, DB file sizes,
    and per-table row counts — everything the owner needs for a real
    analytics dashboard instead of just raw totals."""
    conn = db_connect(DB_PATH)
    c = conn.cursor()

    def _safe_scalar(query, default=0):
        try:
            c.execute(query)
            row = c.fetchone()
            return row[0] if row and row[0] is not None else default
        except Exception:
            return default

    # ── Core totals ──
    db_users = _safe_scalar('SELECT COUNT(DISTINCT user_id) FROM user_stats')
    db_matches = _safe_scalar('SELECT COUNT(*) FROM match_history')
    if not db_matches:
        db_matches_raw = _safe_scalar('SELECT SUM(team_matches_played) FROM user_stats')
        db_matches = db_matches_raw // 2 if db_matches_raw > 1 else db_matches_raw
    db_runs = _safe_scalar('SELECT SUM(COALESCE(total_runs,0) + COALESCE(team_total_runs,0)) FROM user_stats')
    db_wickets = _safe_scalar('SELECT SUM(COALESCE(total_wickets,0) + COALESCE(team_total_wickets,0)) FROM user_stats')
    db_sixes = _safe_scalar('SELECT SUM(COALESCE(total_sixes,0) + COALESCE(team_total_sixes,0)) FROM user_stats')
    db_fours = _safe_scalar('SELECT SUM(COALESCE(total_fours,0) + COALESCE(team_total_fours,0)) FROM user_stats')
    db_hundreds = _safe_scalar('SELECT SUM(COALESCE(total_hundreds,0)) FROM user_stats')
    db_fifties = _safe_scalar('SELECT SUM(COALESCE(total_fifties,0)) FROM user_stats')
    db_dm_users = _safe_scalar('SELECT COUNT(DISTINCT user_id) FROM users')

    # 🔧 NEW: "Players" — users who have ACTUALLY PLAYED at least one game,
    # as opposed to total_users below (which counts anyone the bot has ever
    # merely seen: touched via init_player_stats for team/auction adds,
    # someone else's /stats lookup, etc., OR anyone who's sent one message
    # in a group the bot is in — see global_username_cache_updater). This
    # counts only user_stats rows with a real team/solo match played, unioned
    # with ai_stats rows with a real AI match played.
    db_played_users = _safe_scalar('''
        SELECT COUNT(DISTINCT user_id) FROM (
            SELECT user_id FROM user_stats
            WHERE COALESCE(team_matches_played,0) > 0 OR COALESCE(solo_matches_played,0) > 0
            UNION
            SELECT user_id FROM ai_stats WHERE COALESCE(total_matches,0) > 0
        )
    ''')

    # ── Groups ──
    total_groups = _safe_scalar('SELECT COUNT(*) FROM groups') or len(registered_groups)

    # ── AI mode ──
    try:
        c.execute('SELECT COUNT(*), SUM(total_matches), SUM(wins) FROM ai_stats')
        ai_row = c.fetchone()
        ai_players = ai_row[0] or 0
        ai_total = ai_row[1] or 0
        ai_wins = ai_row[2] or 0
    except Exception:
        ai_players = ai_total = ai_wins = 0

    # ── Match-type breakdown (Solo vs Team vs anything else logged) ──
    match_type_breakdown = {}
    try:
        c.execute("SELECT match_type, COUNT(*) FROM match_history GROUP BY match_type")
        for mtype, cnt in c.fetchall():
            match_type_breakdown[mtype or "UNKNOWN"] = cnt
    except Exception:
        pass
    # 🔧 FIX: match_history can be empty (e.g. legacy-imported totals, or a
    # fresh DB) even though user_stats already carries real lifetime counts —
    # same situation that forces db_matches to fall back below. Without this,
    # the pie chart / Solo-Team-Other line showed "No data" even when the
    # headline "Matches: N" total was clearly non-zero. Fall back to the
    # per-user aggregate columns so the split reflects reality.
    if not match_type_breakdown:
        fb_team = _safe_scalar('SELECT SUM(COALESCE(team_matches_played,0)) FROM user_stats')
        fb_solo = _safe_scalar('SELECT SUM(COALESCE(solo_matches_played,0)) FROM user_stats')
        # team_matches_played is summed per-player (2x per match), so halve it
        fb_team = fb_team // 2 if fb_team > 1 else fb_team
        if fb_team or fb_solo:
            match_type_breakdown = {"TEAM": fb_team, "SOLO": fb_solo}

    # ── Time-windowed match activity (today / 7d / 30d) ──
    matches_today = _safe_scalar(
        "SELECT COUNT(*) FROM match_history WHERE date(match_date) = date('now')"
    )
    matches_7d = _safe_scalar(
        "SELECT COUNT(*) FROM match_history WHERE match_date >= datetime('now', '-7 days')"
    )
    matches_30d = _safe_scalar(
        "SELECT COUNT(*) FROM match_history WHERE match_date >= datetime('now', '-30 days')"
    )
    # Earliest tracked match timestamp — used as a fallback denominator for
    # "Avg/day" when there's been no activity in the last 30 days at all.
    first_match_date = _safe_scalar("SELECT MIN(match_date) FROM match_history", default=None)

    # ── Top 5 most active groups (by match count) ──
    top_groups = []
    try:
        c.execute("""
            SELECT group_id, COUNT(*) as cnt FROM match_history
            GROUP BY group_id ORDER BY cnt DESC LIMIT 5
        """)
        top_groups = c.fetchall()
    except Exception:
        pass

    # ── Daily breakdown: matches per day (last 7 days) ──
    daily_matches = []
    try:
        c.execute("""
            SELECT date(match_date) AS d, COUNT(*) AS cnt
            FROM match_history
            WHERE match_date >= datetime('now', '-13 days')
            GROUP BY d ORDER BY d ASC
        """)
        daily_matches = c.fetchall()
    except Exception:
        pass

    # ── Daily breakdown: new users per day (last 14 days) ──
    # 🔧 FIX: the `users` SQL table is just (user_id, data BLOB) — it never
    # had a started_at/joined_at/etc column, so the old PRAGMA-based lookup
    # here always found nothing and this line stayed flat 0 forever. The
    # real per-user "first started the bot" timestamp lives in the in-memory
    # user_data dict (already loaded at startup), so build the daily counts
    # from there instead.
    daily_new_users = []
    try:
        _new_user_day_counts: Dict[str, int] = defaultdict(int)
        _cutoff = datetime.now() - timedelta(days=13)
        for _uid, _udata in user_data.items():
            _raw = _udata.get("started_at") if isinstance(_udata, dict) else None
            if not _raw:
                continue
            try:
                _dt = datetime.fromisoformat(_raw)
            except Exception:
                continue
            if _dt >= _cutoff:
                _new_user_day_counts[_dt.date().isoformat()] += 1
        daily_new_users = sorted(_new_user_day_counts.items())
    except Exception:
        pass

    # ── Daily breakdown: runs scored per day (last 7 days) — from match_history score columns ──
    daily_runs = []
    try:
        c.execute("""
            SELECT date(match_date) AS d,
                   SUM(
                       COALESCE(CAST(substr(team_x_score, 1, instr(team_x_score||'/', '/') - 1) AS INTEGER), 0) +
                       COALESCE(CAST(substr(team_y_score, 1, instr(team_y_score||'/', '/') - 1) AS INTEGER), 0)
                   ) AS runs
            FROM match_history
            WHERE match_date >= datetime('now', '-13 days')
            GROUP BY d ORDER BY d ASC
        """)
        daily_runs = c.fetchall()
    except Exception:
        pass

    # ── Top 5 players by combined runs ──
    top_players = []
    try:
        c.execute("""
            SELECT user_id, first_name,
                   COALESCE(total_runs,0) + COALESCE(team_total_runs,0) AS runs
            FROM user_stats
            ORDER BY runs DESC LIMIT 5
        """)
        top_players = c.fetchall()
    except Exception:
        pass

    # ── Per-table row counts (helps spot bloat / dead tables) ──
    table_counts = {}
    try:
        c.execute("SELECT name FROM sqlite_master WHERE type='table'")
        table_names = [r[0] for r in c.fetchall()]
        for t in table_names:
            table_counts[t] = _safe_scalar(f"SELECT COUNT(*) FROM {t}")
    except Exception:
        pass

    conn.close()

    # ── DB file sizes (main DB + tournament DB if present) ──
    db_size_mb = 0.0
    tour_db_size_mb = 0.0
    try:
        db_size_mb = round(os.path.getsize(DB_PATH) / (1024 * 1024), 2)
    except Exception:
        pass
    try:
        tour_db_size_mb = round(os.path.getsize(TOURNAMENT_DB_PATH) / (1024 * 1024), 2)
    except Exception:
        pass

    return {
        "db_users": db_users, "db_matches": db_matches, "db_runs": db_runs,
        "db_wickets": db_wickets, "db_sixes": db_sixes, "db_fours": db_fours,
        "db_hundreds": db_hundreds, "db_fifties": db_fifties,
        "db_dm_users": db_dm_users, "db_played_users": db_played_users, "total_groups": total_groups,
        "ai_players": ai_players, "ai_total": ai_total, "ai_wins": ai_wins,
        "match_type_breakdown": match_type_breakdown,
        "matches_today": matches_today, "matches_7d": matches_7d, "matches_30d": matches_30d,
        "first_match_date": first_match_date,
        "top_groups": top_groups, "top_players": top_players,
        "daily_matches": daily_matches, "daily_new_users": daily_new_users, "daily_runs": daily_runs,
        "table_counts": table_counts,
        "db_size_mb": db_size_mb, "tour_db_size_mb": tour_db_size_mb,
    }


# ══════════════════════════ 📊 BOTSTATS CHART HELPERS ══════════════════════════

_BOTSTATS_SESSIONS: Dict[int, dict] = {}   # message_id -> {"pages": [...], "idx": int, "owner": user_id}

BG = (13, 18, 32)
GRID = (42, 51, 80)
TEXT = (232, 236, 255)
MUTED = (136, 146, 184)
GOLD = (255, 210, 63)
BLUE = (59, 167, 255)
ORANGE = (255, 176, 32)
PURPLE = (168, 85, 247)
RED = (255, 84, 112)

def _chart_canvas(w=900, h=650):
    img = Image.new("RGB", (w, h), BG)
    draw = ImageDraw.Draw(img)
    return img, draw

def _text_w(draw, text, font):
    try:
        bbox = draw.textbbox((0, 0), text, font=font)
        return bbox[2] - bbox[0]
    except Exception:
        return len(text) * (font.size // 2)

def _chart_title(draw, w, title):
    f = _get_font(True, 30)
    tw = _text_w(draw, title, f)
    draw.text(((w - tw) // 2, 22), title, font=f, fill=GOLD)

def _to_buf(img):
    buf = BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    # 🔧 FIX: a raw BytesIO has no filename. Telegram's upload can silently
    # reject/mis-handle a photo with no name+extension, which made
    # _render_chart_for_page's caller quietly fail and fall back to the
    # static leaderboard.jpg every time — i.e. the /botstats charts never
    # actually appeared to update. Naming the buffer fixes the upload.
    buf.name = "chart.png"
    return buf


def _render_pie_chart(match_type_breakdown: dict) -> BytesIO:
    """PIE CHART — Solo vs Team vs Other match-type split."""
    solo = match_type_breakdown.get("SOLO", 0)
    team = match_type_breakdown.get("TEAM", 0)
    other = sum(v for k, v in match_type_breakdown.items() if k not in ("SOLO", "TEAM"))

    segs = [(v, l, c) for v, l, c in
            [(solo, "Solo", BLUE), (team, "Team", ORANGE), (other, "Other", PURPLE)] if v > 0]
    total = sum(v for v, _, _ in segs)

    w, h = 900, 650
    img, draw = _chart_canvas(w, h)
    _chart_title(draw, w, "Match-Type Split")

    cx, cy, r = 300, 360, 190
    bbox = [cx - r, cy - r, cx + r, cy + r]

    if not segs or total == 0:
        draw.ellipse(bbox, fill=(58, 66, 102))
        f = _get_font(False, 22)
        msg = "No data yet"
        tw = _text_w(draw, msg, f)
        draw.text((cx - tw // 2, cy - 12), msg, font=f, fill=MUTED)
    else:
        start = -90
        f_pct = _get_font(True, 20)
        for val, label, color in segs:
            sweep = 360 * val / total
            end = start + sweep
            draw.pieslice(bbox, start=start, end=end, fill=color, outline=BG, width=3)
            mid = math.radians((start + end) / 2)
            lx = cx + int((r * 0.62) * math.cos(mid))
            ly = cy + int((r * 0.62) * math.sin(mid))
            pct_txt = f"{val/total*100:.1f}%"
            tw = _text_w(draw, pct_txt, f_pct)
            draw.text((lx - tw // 2, ly - 10), pct_txt, font=f_pct, fill=(20, 24, 40))
            start = end
        draw.ellipse([cx - r * 0.45, cy - r * 0.45, cx + r * 0.45, cy + r * 0.45], fill=BG, outline=GRID, width=2)
        f_tot = _get_font(True, 26)
        tot_txt = f"{total:,}"
        tw = _text_w(draw, tot_txt, f_tot)
        draw.text((cx - tw // 2, cy - 26), tot_txt, font=f_tot, fill=TEXT)
        f_sub = _get_font(False, 15)
        sub_txt = "matches"
        tw = _text_w(draw, sub_txt, f_sub)
        draw.text((cx - tw // 2, cy + 4), sub_txt, font=f_sub, fill=MUTED)

    # Legend
    f_leg = _get_font(False, 19)
    ly0 = 240
    lx0 = 620
    legend_items = segs if segs else [(0, "No data", (58, 66, 102))]
    for i, (val, label, color) in enumerate(legend_items):
        y = ly0 + i * 46
        draw.rounded_rectangle([lx0, y, lx0 + 26, y + 26], radius=6, fill=color)
        txt = f"{label}  —  {val:,}" if val else label
        draw.text((lx0 + 38, y + 3), txt, font=f_leg, fill=TEXT)

    return _to_buf(img)


def _render_worm_chart(daily_matches: list, daily_new_users: list) -> BytesIO:
    """WORM CHART — cumulative growth curve (matches & new users), last 14 days."""
    dm_map = {row[0]: row[1] for row in daily_matches}
    du_map = {row[0]: row[1] for row in daily_new_users}
    today_d = datetime.now().date()
    days, m_cum, u_cum = [], [], []
    m_run = u_run = 0
    for i in range(13, -1, -1):
        d = (today_d - timedelta(days=i)).isoformat()
        m_run += dm_map.get(d, 0)
        u_run += du_map.get(d, 0)
        days.append("Today" if i == 0 else (today_d - timedelta(days=i)).strftime("%d %b"))
        m_cum.append(m_run)
        u_cum.append(u_run)

    w, h = 980, 650
    img, draw = _chart_canvas(w, h)
    _chart_title(draw, w, "Growth Worm — 14 Day Cumulative Trend")

    pad_l, pad_r, pad_t, pad_b = 70, 40, 90, 90
    plot_w = w - pad_l - pad_r
    plot_h = h - pad_t - pad_b
    max_m = max(m_cum) if m_cum and max(m_cum) > 0 else 1
    max_u = max(u_cum) if u_cum and max(u_cum) > 0 else 1
    max_val = max(max_m, max_u)

    f_axis = _get_font(False, 14)
    f_val = _get_font(True, 16)

    # gridlines + y labels
    for gi in range(5):
        gy = pad_t + plot_h - (plot_h * gi / 4)
        draw.line([(pad_l, gy), (w - pad_r, gy)], fill=GRID, width=1)
        val_lbl = str(int(max_val * gi / 4))
        draw.text((pad_l - 8 - _text_w(draw, val_lbl, f_axis), gy - 7), val_lbl, font=f_axis, fill=MUTED)

    n = len(days)
    step = plot_w / max(1, n - 1)

    def pt(i, val):
        x = pad_l + i * step
        y = pad_t + plot_h - (plot_h * val / max_val if max_val else 0)
        return x, y

    m_pts = [pt(i, v) for i, v in enumerate(m_cum)]
    u_pts = [pt(i, v) for i, v in enumerate(u_cum)]

    # filled area under matches curve
    if len(m_pts) > 1:
        poly = m_pts + [(m_pts[-1][0], pad_t + plot_h), (m_pts[0][0], pad_t + plot_h)]
        overlay = Image.new("RGBA", img.size, (0, 0, 0, 0))
        odraw = ImageDraw.Draw(overlay)
        odraw.polygon(poly, fill=(59, 167, 255, 45))
        img.paste(Image.alpha_composite(img.convert("RGBA"), overlay).convert("RGB"))
        draw = ImageDraw.Draw(img)

    # lines
    if len(m_pts) > 1:
        draw.line(m_pts, fill=BLUE, width=4, joint="curve")
    if len(u_pts) > 1:
        # dashed line for users
        for i in range(len(u_pts) - 1):
            x1, y1 = u_pts[i]
            x2, y2 = u_pts[i + 1]
            segs_n = 6
            for s in range(segs_n):
                if s % 2 == 0:
                    sx1 = x1 + (x2 - x1) * s / segs_n
                    sy1 = y1 + (y2 - y1) * s / segs_n
                    sx2 = x1 + (x2 - x1) * (s + 1) / segs_n
                    sy2 = y1 + (y2 - y1) * (s + 1) / segs_n
                    draw.line([(sx1, sy1), (sx2, sy2)], fill=GOLD, width=3)

    # markers
    for x, y in m_pts:
        draw.ellipse([x - 4, y - 4, x + 4, y + 4], fill=BLUE, outline=BG)
    for x, y in u_pts:
        draw.ellipse([x - 3, y - 3, x + 3, y + 3], fill=GOLD, outline=BG)

    # end-value annotations
    if m_pts:
        draw.text((m_pts[-1][0] + 8, m_pts[-1][1] - 20), f"{m_cum[-1]:,}", font=f_val, fill=BLUE)
    if u_pts:
        draw.text((u_pts[-1][0] + 8, u_pts[-1][1] + 4), f"{u_cum[-1]:,}", font=f_val, fill=GOLD)

    # x labels (every 2nd day to avoid crowding)
    for i, (x, _) in enumerate(m_pts):
        if i % 2 == 0 or i == n - 1:
            lbl = days[i]
            tw = _text_w(draw, lbl, f_axis)
            draw.text((x - tw / 2, pad_t + plot_h + 10), lbl, font=f_axis, fill=MUTED)

    # legend
    f_leg = _get_font(False, 16)
    draw.rounded_rectangle([pad_l, 58, pad_l + 22, 76], radius=4, fill=BLUE)
    draw.text((pad_l + 30, 56), "Cumulative Matches", font=f_leg, fill=TEXT)
    lx2 = pad_l + 30 + _text_w(draw, "Cumulative Matches", f_leg) + 40
    draw.rounded_rectangle([lx2, 58, lx2 + 22, 76], radius=4, fill=GOLD)
    draw.text((lx2 + 30, 56), "Cumulative New Users", font=f_leg, fill=TEXT)

    return _to_buf(img)


def _render_compare_chart(top_players: list) -> BytesIO:
    """GROUPED COMPARISON BAR CHART — Top 5 players compared on Runs / Wickets / Sixes."""
    w, h = 980, 650
    img, draw = _chart_canvas(w, h)
    _chart_title(draw, w, "Player Comparison — Top 5")

    top5 = top_players[:5] if top_players else []
    pad_l, pad_r, pad_t, pad_b = 70, 40, 100, 110
    plot_w = w - pad_l - pad_r
    plot_h = h - pad_t - pad_b
    f_axis = _get_font(False, 14)
    f_name = _get_font(True, 15)
    f_val = _get_font(True, 13)

    if not top5:
        f = _get_font(False, 22)
        msg = "No player data yet"
        tw = _text_w(draw, msg, f)
        draw.text(((w - tw) // 2, h // 2), msg, font=f, fill=MUTED)
        return _to_buf(img)

    rows = []
    for uid, fname, runs in top5:
        ps = player_stats.get(uid, {}) if 'player_stats' in globals() else {}
        team_s = ps.get("team", {}) if isinstance(ps, dict) else {}
        solo_s = ps.get("solo", {}) if isinstance(ps, dict) else {}
        wkts = (team_s.get("wickets", 0) or 0) + (solo_s.get("wickets", 0) or 0)
        sixes = (team_s.get("sixes", 0) or 0) + (solo_s.get("sixes", 0) or 0)
        rows.append(((fname or str(uid))[:12], runs, wkts, sixes))

    max_val = max([max(r[1], r[2], r[3]) for r in rows] + [1])

    # gridlines
    for gi in range(5):
        gy = pad_t + plot_h - (plot_h * gi / 4)
        draw.line([(pad_l, gy), (w - pad_r, gy)], fill=GRID, width=1)
        val_lbl = str(int(max_val * gi / 4))
        draw.text((pad_l - 8 - _text_w(draw, val_lbl, f_axis), gy - 7), val_lbl, font=f_axis, fill=MUTED)

    group_w = plot_w / len(rows)
    bar_w = group_w / 5.5

    for i, (name, runs, wkts, sixes) in enumerate(rows):
        gx = pad_l + i * group_w + group_w / 2
        for j, (val, color) in enumerate([(runs, BLUE), (wkts, RED), (sixes, GOLD)]):
            bx = gx + (j - 1) * (bar_w + 6)
            bh = plot_h * (val / max_val) if max_val else 0
            by = pad_t + plot_h - bh
            draw.rounded_rectangle([bx - bar_w / 2, by, bx + bar_w / 2, pad_t + plot_h], radius=4, fill=color)
            if val > 0:
                vtxt = f"{val:,}"
                tw = _text_w(draw, vtxt, f_val)
                draw.text((bx - tw / 2, by - 18), vtxt, font=f_val, fill=TEXT)
        tw = _text_w(draw, name, f_name)
        draw.text((gx - tw / 2, pad_t + plot_h + 12), name, font=f_name, fill=TEXT)

    # legend
    f_leg = _get_font(False, 16)
    lx = pad_l
    ly = 58
    for label, color in [("Runs", BLUE), ("Wickets", RED), ("Sixes", GOLD)]:
        draw.rounded_rectangle([lx, ly, lx + 22, ly + 18], radius=4, fill=color)
        draw.text((lx + 30, ly - 2), label, font=f_leg, fill=TEXT)
        lx += 30 + _text_w(draw, label, f_leg) + 36

    return _to_buf(img)


def _botstats_nav_keyboard(idx: int, total: int) -> InlineKeyboardMarkup:
    row = []
    if idx > 0:
        row.append(styled_button("Back", callback_data=f"bstats_nav_{idx-1}"))
    row.append(styled_button(f"{idx+1}/{total}", callback_data="bstats_noop"))
    if idx < total - 1:
        row.append(styled_button("Next", callback_data=f"bstats_nav_{idx+1}"))
    row2 = [styled_button("Refresh", callback_data="bstats_refresh"),
            styled_button("Close", callback_data="bstats_close")]
    return InlineKeyboardMarkup([row, row2])


def _build_botstats_pages(data: dict) -> list:
    """Builds ordered list of {caption, chart} dicts for the paginated dashboard."""
    # 🔧 FIX: was max(db_users, mem_users, db_dm_users) — that's not a real
    # distinct-user count, just whichever of three overlapping-but-different
    # sources happened to be biggest. mem_users (len(player_stats)) balloons
    # every time ANYONE is added to a team/auction/match via init_player_stats()
    # even if they never DM'd /start, so "Total Users" spiked way faster than
    # actual bot starts and didn't reflect a real union of known users.
    # Proper fix: union the actual user_id sets instead of comparing counts.
    total_users = len(set(player_stats.keys()) | set(user_data.keys()))
    total_matches = data["db_matches"]
    total_runs = data["db_runs"]
    total_wickets = data["db_wickets"]
    total_sixes = data["db_sixes"]
    total_fours = data["db_fours"]

    active_match_count = len(active_matches)
    active_auction_count = len(active_auctions)
    active_tour_count = len(active_tournaments) if 'active_tournaments' in globals() else 0
    total_banned = len(banned_groups)
    active_groups = max(0, data["total_groups"] - total_banned)

    cpu = memory = disk = 0
    proc_mem_mb = 0
    if psutil:
        try:
            cpu = psutil.cpu_percent(0.2)
            memory = psutil.virtual_memory().percent
            disk = psutil.disk_usage('/').percent
            proc_mem_mb = round(psutil.Process(os.getpid()).memory_info().rss / (1024 * 1024), 1)
        except Exception:
            pass

    uptime_secs = int(time.time() - bot_start_time) if 'bot_start_time' in globals() else 0
    up_d, _rem = divmod(uptime_secs, 86400)
    up_h, _rem = divmod(_rem, 3600)
    up_m, up_s = divmod(_rem, 60)
    uptime_str = f"{up_d}d {up_h}h {up_m}m {up_s}s" if up_d else f"{up_h}h {up_m}m {up_s}s"

    mtb = data["match_type_breakdown"]
    solo_matches = mtb.get("SOLO", 0)
    team_matches = mtb.get("TEAM", 0)
    other_matches = sum(v for k, v in mtb.items() if k not in ("SOLO", "TEAM"))

    days_running = max(1, uptime_secs // 86400) if uptime_secs else 1
    # 🔧 FIX: was total_matches / days_running, where days_running is BOT
    # PROCESS UPTIME — after any restart within 24h this floors to 1 day,
    # so avg/day showed the entire lifetime total (e.g. "3002.0") instead of
    # a real daily rate. Prefer a real recent rate (last 30 days); if there's
    # genuinely no tracked activity in that window, use the actual span since
    # the first tracked match instead of process uptime; only fall back to
    # uptime as an absolute last resort (fresh DB, no history at all yet).
    if data.get("matches_30d"):
        avg_matches_per_day = round(data["matches_30d"] / 30, 1)
    elif data.get("first_match_date"):
        try:
            _first_dt = datetime.fromisoformat(str(data["first_match_date"]).replace("Z", ""))
            _span_days = max(1, (datetime.now() - _first_dt).days)
            avg_matches_per_day = round(total_matches / _span_days, 1)
        except Exception:
            avg_matches_per_day = round(total_matches / days_running, 1) if days_running else total_matches
    else:
        avg_matches_per_day = round(total_matches / days_running, 1) if days_running else total_matches

    pages = []

    # ── PAGE 1 — OVERVIEW ──
    p1 = "🏏 <b>CRICOVERSE — BOT STATS</b>\n"
    p1 += "<blockquote>— ⚙️ SYSTEM \n"
    p1 += f"├ ⚡ Ping: <b>{data.get('ping_ms', 0)}ms</b>\n"
    p1 += f"├ 💻 CPU: <b>{cpu}%</b>  ┊  🧠 RAM: <b>{memory}%</b>  ┊  💾 Disk: <b>{disk}%</b>\n"
    p1 += f"├ ⏱️ Uptime: <b>{uptime_str}</b>\n"
    p1 += "</blockquote>\n"
    p1 += "<blockquote>— 👥 USERS & GROUPS \n"
    p1 += f"├ 👤 Total Users: <b>{total_users:,}</b>  ┊  💬 DM Users: <b>{data['db_dm_users']:,}</b>\n"
    p1 += f"├ 🎮 Players (played ≥1 game): <b>{data['db_played_users']:,}</b>\n"
    p1 += f"├ 🏘️ Groups: <b>{data['total_groups']}</b>  ┊  ✅ Active: <b>{active_groups}</b>  ┊  🚫 Banned: <b>{total_banned}</b>\n"
    p1 += "</blockquote>\n"
    p1 += "<blockquote>— 🔴 LIVE NOW \n"
    p1 += f"├ 🏏 Matches: <b>{active_match_count}</b>  ┊  🎪 Auctions: <b>{active_auction_count}</b>  ┊  🏆 Tournaments: <b>{active_tour_count}</b>\n"
    p1 += "</blockquote>\n"
    p1 += "✅ <i>All systems operational</i>"
    pages.append({"caption": p1, "chart": None})

    # ── PAGE 2 — CRICKET STATS + PIE CHART ──
    p2 = "🏏 <b>CRICKET STATS</b>\n"
    p2 += "<blockquote>— 📊 TOTALS \n"
    p2 += f"├ 🎮 Matches: <b>{total_matches:,}</b>\n"
    p2 += f"├ 🏃 Runs: <b>{total_runs:,}</b>  ┊  ⚾ Wickets: <b>{total_wickets:,}</b>\n"
    p2 += f"├ 🚀 Sixes: <b>{total_sixes:,}</b>  ┊  🔥 Fours: <b>{total_fours:,}</b>\n"
    p2 += f"├ 💯 Hundreds: <b>{data['db_hundreds']:,}</b>  ┊  5️⃣0️⃣ Fifties: <b>{data['db_fifties']:,}</b>\n"
    p2 += "</blockquote>\n"
    p2 += "<blockquote>— 🎯 MATCH-TYPE SPLIT \n"
    p2 += f"├ ⚔️ Solo: <b>{solo_matches:,}</b>  ┊  👥 Team: <b>{team_matches:,}</b>  ┊  🎲 Other: <b>{other_matches:,}</b>\n"
    p2 += "</blockquote>\n"
    p2 += "<blockquote>— 🤖 AI MODE \n"
    p2 += f"├ 👾 Players: <b>{data['ai_players']}</b>  ┊  🎮 Matches: <b>{data['ai_total']}</b>  ┊  🏆 Wins: <b>{data['ai_wins']}</b>\n"
    p2 += "</blockquote>"
    pages.append({"caption": p2, "chart": ("pie", data["match_type_breakdown"])})

    # ── PAGE 3 — WORM CHART (CUMULATIVE GROWTH) ──
    p3 = "🪱 <b>GROWTH WORM (14-Day Cumulative)</b>\n"
    p3 += "<blockquote>— 📅 WINDOW \n"
    p3 += f"├ 📅 Today: <b>{data['matches_today']:,}</b>  ┊  🗓️ 7d: <b>{data['matches_7d']:,}</b>  ┊  🗓️ 30d: <b>{data['matches_30d']:,}</b>\n"
    p3 += f"├ 📊 Avg/day: <b>{avg_matches_per_day}</b>\n"
    p3 += "</blockquote>\n"
    p3 += "📉 <i>Solid line = cumulative matches · Dashed line = cumulative new users, last 14 days</i>"
    pages.append({"caption": p3, "chart": ("worm", (data["daily_matches"], data["daily_new_users"]))})

    # ── PAGE 4 — TOP GROUPS & PLAYER COMPARISON ──
    p4 = "⚔️ <b>TOP GROUPS & PLAYER COMPARISON</b>\n"
    p4 += "<blockquote>— 🏘️ TOP 5 GROUPS \n"
    if data["top_groups"]:
        for i, (gid, cnt) in enumerate(data["top_groups"], 1):
            g_name = registered_groups.get(gid, {}).get("group_name") if isinstance(registered_groups.get(gid), dict) else None
            label = html.escape(g_name) if g_name else f"ID {gid}"
            p4 += f"├ {i}. {label} → <b>{cnt}</b> matches\n"
    else:
        p4 += "<i>No match history yet.</i>\n"
    p4 += "</blockquote>\n"
    p4 += "📊 <i>Chart below: Top 5 players compared on Runs / Wickets / Sixes</i>"
    pages.append({"caption": p4, "chart": ("compare", data["top_players"])})

    # ── PAGE 5 — SYSTEM / DATABASE / HOST ──
    tc = data["table_counts"]
    p5 = "🖥️ <b>DATABASE & HOST INFO</b>\n"
    p5 += "<blockquote>— 🗄️ DATABASE \n"
    p5 += f"├ 💽 Main DB: <b>{data['db_size_mb']} MB</b>  ┊  🏆 Tournament DB: <b>{data['tour_db_size_mb']} MB</b>\n"
    if tc:
        for tname in sorted(tc, key=lambda k: -tc[k])[:6]:
            p5 += f"├ • {html.escape(tname)}: <b>{tc[tname]:,}</b> rows\n"
    p5 += "</blockquote>\n"
    p5 += "<blockquote>— 🖥️ RUNTIME \n"
    p5 += f"├ 🐍 Python: <b>{platform.python_version()}</b>\n"
    p5 += f"├ 💻 OS: <b>{platform.system()} {platform.release()}</b>\n"
    try:
        import telegram as _tg_mod
        ptb_ver = getattr(_tg_mod, "__version__", "?")
    except Exception:
        ptb_ver = "?"
    p5 += f"├ 📦 python-telegram-bot: <b>{ptb_ver}</b>\n"
    p5 += f"├ 🧠 Process RAM: <b>{proc_mem_mb} MB</b>\n"
    jq_running = bool(application.job_queue.jobs()) if ('application' in globals() and application and application.job_queue) else False
    p5 += f"├ ⚙️ Job Queue: <b>{'Running' if jq_running else 'Unknown/Idle'}</b>\n"
    p5 += f"├ 🧵 Caches → Matches: <b>{len(active_matches)}</b>, Auctions: <b>{len(active_auctions)}</b>, Groups: <b>{len(registered_groups)}</b>\n"
    p5 += "</blockquote>"
    pages.append({"caption": p5, "chart": None})

    # ── PAGE 6 — JERSEY STATS ──
    JERSEY_TOTAL_SLOTS = 1000  # numbers 0-999
    allotted = []
    for uid, udata in user_data.items():
        num = udata.get("jersey_number")
        if num is not None:
            allotted.append((num, uid))
    total_allotted = len(allotted)
    total_empty = max(JERSEY_TOTAL_SLOTS - total_allotted, 0)

    # "Demand" = how many people are waiting via the notify-me-when-free subscription
    # (only counts still-taken numbers, since subscriptions are popped on release)
    try:
        demand_source = jersey_release_subscribers
    except NameError:
        demand_source = {}
    demand_counts = []
    for num_str, subs in demand_source.items():
        try:
            num = int(num_str)
        except Exception:
            continue
        if find_user_id_by_jersey(num) is not None and subs:
            demand_counts.append((num, len(subs)))
    demand_counts.sort(key=lambda x: -x[1])
    top_demand = demand_counts[:5]

    p6 = "🎽 <b>JERSEY STATS</b>\n"
    p6 += "<blockquote>— 📦 INVENTORY \n"
    p6 += f"├ 🎽 Total Slots: <b>{JERSEY_TOTAL_SLOTS}</b> (#0-#999)\n"
    p6 += f"├ ✅ Allotted: <b>{total_allotted}</b>  ┊  🆓 Empty: <b>{total_empty}</b>\n"
    fill_pct = round((total_allotted / JERSEY_TOTAL_SLOTS) * 100, 1) if JERSEY_TOTAL_SLOTS else 0
    p6 += f"├ 📊 Fill Rate: <b>{fill_pct}%</b>\n"
    p6 += "</blockquote>\n"
    p6 += "<blockquote>— 🔥 MOST IN-DEMAND \n"
    if top_demand:
        for i, (num, cnt) in enumerate(top_demand, 1):
            holder_id = find_user_id_by_jersey(num)
            holder_name = user_data.get(holder_id, {}).get("first_name", "?") if holder_id else "?"
            p6 += f"├ {i}. 🎽 #{num} ({html.escape(str(holder_name))}) → <b>{cnt}</b> waiting\n"
    else:
        p6 += "<i>No pending \"notify me\" requests right now.</i>\n"
    p6 += "</blockquote>\n"
    if top_demand:
        hottest_num, hottest_cnt = top_demand[0]
        p6 += f"🏆 <i>Hottest jersey right now: #{hottest_num} — {hottest_cnt} people want it.</i>"
    else:
        p6 += "🏆 <i>No hot jersey yet — demand shows up here once people tap \"Notify me when free\".</i>"
    pages.append({"caption": p6, "chart": None})

    return pages


def _render_chart_for_page(page: dict) -> Optional[BytesIO]:
    chart = page.get("chart")
    if not chart:
        return None
    kind, payload = chart
    try:
        if kind == "pie":
            return _render_pie_chart(payload)
        elif kind == "worm":
            return _render_worm_chart(payload[0], payload[1])
        elif kind == "compare":
            return _render_compare_chart(payload)
    except Exception as e:
        logger.error(f"botstats chart render failed ({kind}): {e}")
    return None


async def _send_botstats_page(context: ContextTypes.DEFAULT_TYPE, chat_id: int, pages: list, idx: int,
                                owner_id: int, edit_message=None):
    """Sends (or edits into) the given page — photo+caption if it has a chart, else plain text."""
    page = pages[idx]
    caption = page["caption"]
    kb = _botstats_nav_keyboard(idx, len(pages))
    chart_buf = _render_chart_for_page(page)

    if edit_message is not None:
        try:
            if chart_buf:
                from telegram import InputMediaPhoto
                await edit_message.edit_media(
                    media=InputMediaPhoto(chart_buf, caption=caption, parse_mode=ParseMode.HTML),
                    reply_markup=kb
                )
            else:
                await edit_message.edit_media(
                    media=InputMediaPhoto(MEDIA_ASSETS.get("botstats"), caption=caption, parse_mode=ParseMode.HTML),
                    reply_markup=kb
                )
            return edit_message
        except Exception as e:
            logger.warning(f"botstats edit_media failed, falling back to delete+resend: {e}")
            try:
                await edit_message.delete()
            except Exception:
                pass

    try:
        if chart_buf:
            sent = await context.bot.send_photo(chat_id, photo=chart_buf, caption=caption,
                                                 parse_mode=ParseMode.HTML, reply_markup=kb)
        else:
            asset = MEDIA_ASSETS.get("botstats")
            if asset:
                sent = await context.bot.send_photo(chat_id, photo=asset, caption=caption,
                                                     parse_mode=ParseMode.HTML, reply_markup=kb)
            else:
                sent = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as e:
        logger.error(f"botstats send failed, falling back to text: {e}")
        sent = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=kb)

    _BOTSTATS_SESSIONS[sent.message_id] = {"pages": pages, "idx": idx, "owner": owner_id}
    return sent


def _find_phantom_user_ids() -> list:
    """
    'Phantom' user = present in player_stats but is NOT a genuine user:
    never /start'd the bot (not in user_data) AND never actually played
    a ball (team matches == 0 AND solo matches == 0). These get created
    as a side-effect of init_player_stats() being called when someone is
    merely added to a team/auction/tournament — they inflate Total Users
    without being a real person who ever touched the bot.

    Genuine = did /start (in user_data) OR has matches > 0 in either mode.
    """
    phantoms = []
    for uid, stats in player_stats.items():
        if uid in user_data:
            continue  # started the bot — genuine
        team_matches = (stats.get("team") or {}).get("matches", 0)
        solo_matches = (stats.get("solo") or {}).get("matches", 0)
        if team_matches == 0 and solo_matches == 0:
            phantoms.append(uid)
    return phantoms


def _delete_phantom_users_sync(uids: list) -> int:
    """Removes phantom rows from the player_stats table (SQL) and in-memory dict."""
    if not uids:
        return 0
    removed = 0
    try:
        conn = db_connect(DB_FILE)
        c = conn.cursor()
        for uid in uids:
            c.execute("DELETE FROM player_stats WHERE user_id = ?", (uid,))
            removed += 1
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"Phantom user cleanup DB delete failed: {e}")
    for uid in uids:
        player_stats.pop(uid, None)
    return removed


async def cleanup_phantoms_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🧹 OWNER ONLY — removes phantom users (added via team/auction/tournament
    but who never /start'd the bot and never played a ball) from player_stats,
    so Total Users reflects only genuine users."""
    user = update.effective_user
    if not has_power(user.id, "stats"):
        await update.message.reply_text(
            "🚫 <b>Access Denied!</b>\n\nOnly the bot owner can run this.",
            parse_mode=ParseMode.HTML
        )
        return

    before_total = len(set(player_stats.keys()) | set(user_data.keys()))
    phantoms = await asyncio.to_thread(_find_phantom_user_ids)

    if not phantoms:
        await update.message.reply_text(
            "✅ <b>No phantom users found.</b>\nDatabase is already clean.",
            parse_mode=ParseMode.HTML
        )
        return

    confirm_kb = InlineKeyboardMarkup([[
        styled_button(f"🧹 Remove {len(phantoms)} phantom(s)", callback_data="cleanup_phantoms_confirm"),
        styled_button("❌ Cancel", callback_data="cleanup_phantoms_cancel"),
    ]])
    context.bot_data["_phantom_uids_pending"] = phantoms
    await update.message.reply_text(
        f"🔍 <b>Phantom Users Found:</b> <code>{len(phantoms)}</code>\n"
        f"👤 Current Total Users: <code>{before_total:,}</code>\n"
        f"👤 Total Users after cleanup: <code>{before_total - len(phantoms):,}</code>\n\n"
        f"These are users who never /started the bot and never played a single ball "
        f"(just got added to a team/auction/tournament somewhere).",
        parse_mode=ParseMode.HTML,
        reply_markup=confirm_kb
    )


async def cleanup_phantoms_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if query.from_user.id != OWNER_ID and not has_power(query.from_user.id, "stats"):
        await query.answer("🚫 Access Denied!", show_alert=True)
        return
    await query.answer()

    if query.data == "cleanup_phantoms_cancel":
        context.bot_data.pop("_phantom_uids_pending", None)
        await query.edit_message_text("❌ Cleanup cancelled.")
        return

    phantoms = context.bot_data.pop("_phantom_uids_pending", None)
    if not phantoms:
        await query.edit_message_text("⚠️ Nothing pending — list may have expired. Run /cleanup_phantoms again.")
        return

    removed = await asyncio.to_thread(_delete_phantom_users_sync, phantoms)
    new_total = len(set(player_stats.keys()) | set(user_data.keys()))
    await query.edit_message_text(
        f"✅ <b>Cleanup Done!</b>\n"
        f"🧹 Removed: <code>{removed}</code> phantom users\n"
        f"👤 New Total Users: <code>{new_total:,}</code>",
        parse_mode=ParseMode.HTML
    )


async def botstats_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏏 ADVANCED bot statistics & analytics dashboard — OWNER ONLY.

    📊 Paginated multi-page dashboard with 📈 growth line chart, 🥧 pie chart
    (match-type split), 🏆 top-players bar chart, and ⬅️➡️ Next/Back
    navigation buttons — all metrics rendered in clean aligned blockquote
    cards instead of one giant wall of text.
    """
    user = update.effective_user
    if not has_power(user.id, "stats"):
        await update.message.reply_text(
            "🚫 <b>Access Denied!</b>\n\nOnly the bot owner can view bot stats.",
            parse_mode=ParseMode.HTML
        )
        return

    t0 = time.time()
    loading = await update.message.reply_text("⏳ <b>Building dashboard...</b>", parse_mode=ParseMode.HTML)

    data = await asyncio.to_thread(_fetch_botstats_data)
    data["ping_ms"] = round((time.time() - t0) * 1000, 2)

    pages = await asyncio.to_thread(_build_botstats_pages, data)

    try:
        await loading.delete()
    except Exception:
        pass

    await _send_botstats_page(context, update.effective_chat.id, pages, 0, user.id)


async def botstats_nav_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles ⬅️ Back / Next ➡️ / 🔄 Refresh / ❌ Close on the /botstats dashboard."""
    query = update.callback_query
    user = query.from_user
    if not has_power(user.id, "stats"):
        await query.answer(plain_alert("🚫 Owner only!"), show_alert=True)
        return

    msg_id = query.message.message_id
    session = _BOTSTATS_SESSIONS.get(msg_id)

    if query.data == "bstats_noop":
        await query.answer()
        return

    if query.data == "bstats_close":
        await query.answer(plain_alert("Closed ✅"))
        try:
            await query.message.delete()
        except Exception:
            pass
        _BOTSTATS_SESSIONS.pop(msg_id, None)
        return

    if query.data == "bstats_refresh":
        await query.answer(plain_alert("🔄 Refreshing..."))
        data = await asyncio.to_thread(_fetch_botstats_data)
        data["ping_ms"] = 0
        pages = await asyncio.to_thread(_build_botstats_pages, data)
        idx = session["idx"] if session else 0
        await _send_botstats_page(context, query.message.chat_id, pages, idx, user.id, edit_message=query.message)
        _BOTSTATS_SESSIONS[msg_id] = {"pages": pages, "idx": idx, "owner": user.id}
        return

    if not session:
        await query.answer("Session expired — run /botstats again.", show_alert=True)
        return

    await query.answer()
    new_idx = int(query.data.rsplit("_", 1)[1])
    new_idx = max(0, min(new_idx, len(session["pages"]) - 1))
    session["idx"] = new_idx
    await _send_botstats_page(context, query.message.chat_id, session["pages"], new_idx, user.id, edit_message=query.message)


async def dailystats_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """📅 Quick daily-only breakdown (matches/new users/runs for last 7 days) — OWNER ONLY.
    Same underlying data as the DEEP ANALYTICS section of /botstats, but as
    a standalone command for a fast daily check without the full dashboard."""
    user = update.effective_user
    if not has_power(user.id, "stats"):
        await update.message.reply_text(
            "🚫 <b>Access Denied!</b>\n\nOnly the bot owner can view daily stats.",
            parse_mode=ParseMode.HTML
        )
        return

    msg = await update.message.reply_text("⏳ <b>Fetching daily stats...</b>", parse_mode=ParseMode.HTML)
    data = await asyncio.to_thread(_fetch_botstats_data)

    dm_map = {row[0]: row[1] for row in data["daily_matches"]}
    du_map = {row[0]: row[1] for row in data["daily_new_users"]}
    dr_map = {row[0]: (row[1] or 0) for row in data["daily_runs"]}

    text = "📅 <b>DAILY STATS (Last 7 Days)</b>\n"
    text += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    rows = []
    today_d = datetime.now().date()
    total_m = total_u = total_r = 0
    if dm_map or du_map or dr_map:
        for i in range(6, -1, -1):
            d = (today_d - timedelta(days=i)).isoformat()
            day_label = "Today" if i == 0 else ("Yesterday" if i == 1 else d)
            m_cnt = dm_map.get(d, 0)
            u_cnt = du_map.get(d, 0)
            r_cnt = dr_map.get(d, 0)
            total_m += m_cnt
            total_u += u_cnt
            total_r += r_cnt
            text += f"• {day_label}: 🎮 <b>{m_cnt}</b> matches  ┊  👤 <b>{u_cnt}</b> new users  ┊  🏃 <b>{r_cnt:,}</b> runs\n"
            rows.append([day_label, str(m_cnt), str(u_cnt), f"{r_cnt:,}"])
        text += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        text += f"📊 <b>7-Day Total:</b> {total_m} matches  ┊  {total_u} new users  ┊  {total_r:,} runs\n"
        avg_m = round(total_m / 7, 1)
        text += f"📈 <b>Avg/day:</b> {avg_m} matches"
    else:
        text += "<i>No match history yet for a daily breakdown.</i>"

    try:
        await msg.delete()
    except Exception:
        pass

    if rows:
        await send_rich_table_message(
            update.effective_chat.id,
            headers=["Day", "Matches", "New Users", "Runs"],
            rows=rows,
            title="📅 DAILY STATS (Last 7 Days)",
            footer=f"📈 Avg/day: {round(total_m / 7, 1)} matches",
            fallback_html=text,
        )
    else:
        await update.effective_chat.send_message(text, parse_mode=ParseMode.HTML)


async def backup_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """📦 Enhanced Manual Backup Command with Multi-DB Support"""
    user = update.effective_user
    
    # Security: Only owner can backup
    if not has_power(user.id, "backup"): 
        await update.message.reply_text("🚫 <b>Access Denied!</b>\n\nOnly bot owner can create backups.", parse_mode=ParseMode.HTML)
        return

    # Status message
    status = await update.message.reply_text("⏳ <b>Creating backup...</b>", parse_mode=ParseMode.HTML)
    
    # Save latest data
    save_data()
    
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        backup_files = []
        
        # 1. Main Database Backup
        if os.path.exists(DB_FILE):
            main_db_name = f"cricoverse_main_{timestamp}.db"
            backup_files.append((DB_FILE, main_db_name, "Main Database"))
        
        # 2. Tournament Database Backup
        if os.path.exists(TOURNAMENT_DB_PATH):
            tournament_db_name = f"cricoverse_tournament_{timestamp}.db"
            backup_files.append((TOURNAMENT_DB_PATH, tournament_db_name, "Tournament Database"))
        
        if not backup_files:
            await status.edit_text("⚠️ <b>No database files found!</b>", parse_mode=ParseMode.HTML)
            return
        
        # Update status
        await status.edit_text(
            f"📦 <b>Backup in Progress...</b>\n\n"
            f"📁 Files to backup: <b>{len(backup_files)}</b>\n"
            f"⏰ Timestamp: <code>{timestamp}</code>",
            parse_mode=ParseMode.HTML
        )
        
        # Send each database file
        for db_path, db_name, db_type in backup_files:
            with open(db_path, 'rb') as f:
                # Get file size
                file_size = os.path.getsize(db_path)
                size_mb = round(file_size / (1024 * 1024), 2)
                
                caption = (
                    f"💾 <b>{db_type} Backup</b>\n"
                    f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
                    f"📅 <b>Date:</b> {datetime.now().strftime('%d %B %Y')}\n"
                    f"⏰ <b>Time:</b> {datetime.now().strftime('%H:%M:%S')}\n"
                    f"📊 <b>Size:</b> {size_mb} MB\n"
                    f"📝 <b>File:</b> <code>{db_name}</code>\n\n"
                    f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                    f"✅ <b>Backup Created Successfully!</b>"
                )
                
                await update.message.reply_document(
                    document=f,
                    filename=db_name,
                    caption=caption,
                    parse_mode=ParseMode.HTML
                )
        
        # Get database statistics
        conn= await asyncio.to_thread(db_connect, DB_PATH)
        c = conn.cursor()
        
        c.execute('SELECT COUNT(DISTINCT user_id) FROM user_stats')
        total_users = c.fetchone()[0] or 0
        c.execute('SELECT SUM(matches_played) FROM user_stats')
        total_matches = c.fetchone()[0] or 0
        c.execute('SELECT COUNT(*) FROM groups')
        total_groups = c.fetchone()[0] or 0
        
        conn.close()
        
        # Final summary
        summary = (
            f"✅ <b>Backup Complete!</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            f"📦 <b>Backed up:</b> {len(backup_files)} database(s)\n"
            f"👥 <b>Total Users:</b> {total_users}\n"
            f"🏏 <b>Total Matches:</b> {total_matches}\n"
            f"🏘️ <b>Total Groups:</b> {total_groups}\n\n"
            f"💡 <b>Tip:</b> Use /restore by replying to the backup file to restore data.\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
        )
        
        await status.edit_text(summary, parse_mode=ParseMode.HTML)
        
    except Exception as e:
        logger.error(f"Backup failed: {e}")
        await status.edit_text(
            f"❌ <b>Backup Failed!</b>\n\n"
            f"Error: <code>{str(e)}</code>",
            parse_mode=ParseMode.HTML
        )

async def check_and_celebrate_milestones(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match, player: Player, event_type: str):
    """
    🎉 AUTO MILESTONE DETECTOR - FIXED: Only triggers ONCE per milestone
    """
    
    # Initialize milestone tracking if not exists
    if not hasattr(player, 'milestones_celebrated'):
        player.milestones_celebrated = set()
    
    if event_type == 'batting':
        # ✅ Check for 50 (Only once)
        if player.runs >= 50 and '50' not in player.milestones_celebrated:
            player.milestones_celebrated.add('50')
            await send_milestone_gif(context, chat_id, player, "half_century", match.game_mode)
            logger.info(f"🎉 Milestone: {player.first_name} scored 50!")
            await asyncio.sleep(5)
            
        # ✅ Check for 100 (Only once)
        elif player.runs >= 100 and '100' not in player.milestones_celebrated:
            player.milestones_celebrated.add('100')
            await send_milestone_gif(context, chat_id, player, "century", match.game_mode)
            logger.info(f"🎉 Milestone: {player.first_name} scored 100!")
            await asyncio.sleep(5)
            
    elif event_type == 'bowling':
        # ✅ Check for Hat-trick (Only once) - 3 CONSECUTIVE wickets
        if player.consecutive_wickets == 3 and 'hatrick' not in player.milestones_celebrated:
            player.milestones_celebrated.add('hatrick')
            player.has_hat_trick = True
            await send_milestone_gif(context, chat_id, player, "hatrick", match.game_mode)
            logger.info(f"🎩 HAT-TRICK! {player.first_name} took 3 consecutive wickets!")
            await asyncio.sleep(5)


