# 2. Automated Backup Job (Background Task)
async def auto_backup_job(context: ContextTypes.DEFAULT_TYPE):
    """Automatic Background Backup — with flood-safe retry so a temporary
    Telegram rate-limit doesn't silently drop the backup."""
    save_data() # Ensure latest data is saved to DB
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d_%H-%M")
        file_name = f"cricoverse_auto_{timestamp}.db"

        if os.path.exists(DB_FILE):
            for attempt in range(3):
                try:
                    with open(DB_FILE, 'rb') as f:
                        await context.bot.send_document(
                            chat_id=OWNER_ID,
                            document=f,
                            filename=file_name,
                            caption=f"🤖 <b>Auto SQL Backup</b>\n📅 {timestamp}",
                            parse_mode=ParseMode.HTML
                        )
                    break
                except RetryAfter as flood_err:
                    wait_s = getattr(flood_err, "retry_after", 5)
                    logger.warning(f"Backup flood-limited, retrying in {wait_s}s (attempt {attempt + 1}/3)")
                    await asyncio.sleep(wait_s + 1)
                except Exception as send_err:
                    logger.error(f"Backup send attempt {attempt + 1} failed: {send_err}")
                    await asyncio.sleep(2 ** attempt)

            # 📤 Also send the same backup to the bot support group every hour,
            # so the DB is available there too, not just in owner DM.
            if SUPPORT_GROUP_ID:
                for attempt in range(3):
                    try:
                        with open(DB_FILE, 'rb') as f:
                            await context.bot.send_document(
                                chat_id=SUPPORT_GROUP_ID,
                                document=f,
                                filename=file_name,
                                caption=f"🤖 <b>Auto SQL Backup</b>\n📅 {timestamp}",
                                parse_mode=ParseMode.HTML
                            )
                        break
                    except RetryAfter as flood_err:
                        wait_s = getattr(flood_err, "retry_after", 5)
                        logger.warning(f"Support-group backup flood-limited, retrying in {wait_s}s (attempt {attempt + 1}/3)")
                        await asyncio.sleep(wait_s + 1)
                    except Exception as send_err:
                        logger.error(f"Support-group backup send attempt {attempt + 1} failed: {send_err}")
                        await asyncio.sleep(2 ** attempt)
    except Exception as e:
        logger.error(f"Auto backup failed: {e}")


async def midnight_backup_job(context: ContextTypes.DEFAULT_TYPE):
    """🌙 Runs once every day at 12:00 AM IST — sends the DB backup to the
    support group specifically (separate from the hourly auto_backup_job,
    so there's always a clearly-labelled midnight copy)."""
    save_data()
    try:
        ist_now = datetime.utcnow() + timedelta(hours=5, minutes=30)
        timestamp = ist_now.strftime("%Y-%m-%d_%H-%M")
        file_name = f"cricoverse_midnight_{timestamp}.db"

        if os.path.exists(DB_FILE) and SUPPORT_GROUP_ID:
            for attempt in range(3):
                try:
                    with open(DB_FILE, 'rb') as f:
                        await context.bot.send_document(
                            chat_id=SUPPORT_GROUP_ID,
                            document=f,
                            filename=file_name,
                            caption=f"🌙 <b>Midnight Backup (12 AM IST)</b>\n📅 {timestamp} IST",
                            parse_mode=ParseMode.HTML
                        )
                    break
                except RetryAfter as flood_err:
                    wait_s = getattr(flood_err, "retry_after", 5)
                    logger.warning(f"Midnight backup flood-limited, retrying in {wait_s}s (attempt {attempt + 1}/3)")
                    await asyncio.sleep(wait_s + 1)
                except Exception as send_err:
                    logger.error(f"Midnight backup send attempt {attempt + 1} failed: {send_err}")
                    await asyncio.sleep(2 ** attempt)
    except Exception as e:
        logger.error(f"Midnight backup failed: {e}")


async def registration_expiry_checker_job(context: ContextTypes.DEFAULT_TYPE):
    """
    Runs every hour:
    - If registration just expired — notify group with player count
    - If still open — send daily reminder (every ~24h based on a flag stored per group)
    """
    try:
        now = datetime.now()
        to_remove = []

        for group_id, reg_info in list(REGISTRATION_ACTIVE.items()):
            end_dt = reg_info.get('end_date')
            if not end_dt:
                continue

            tournament_name = reg_info.get('tournament_name', 'Tournament')

            # ── Expired ──
            if end_dt <= now:
                # Count players
                try:
                    conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
                    c = conn.cursor()
                    c.execute("SELECT COUNT(*) FROM registered_players WHERE group_id = ?", (group_id,))
                    count = c.fetchone()[0]
                    # Mark inactive in DB
                    c.execute(
                        "UPDATE registration_periods SET is_active = 0 WHERE group_id = ? AND is_active = 1",
                        (group_id,)
                    )
                    conn.commit()
                    conn.close()
                except Exception as e:
                    logger.error(f"Expiry DB update error for group {group_id}: {e}")
                    count = "?"

                to_remove.append(group_id)

                try:
                    await context.bot.send_message(
                        chat_id=group_id,
                        text=(
                            f"🏁 <b>REGISTRATION CLOSED!</b>\n"
                            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                            f"🏆 <b>{html.escape(tournament_name)}</b>\n\n"
                            f"⏰ Registration period has ended.\n"
                            f"👥 <b>{count}</b> player(s) registered.\n\n"
                            f"📋 Use /registeredlist to view the full list.\n"
                            f"🎯 Admins can now proceed to /auction setup!\n"
                            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
                        ),
                        parse_mode=ParseMode.HTML
                    )
                except Exception as e:
                    logger.error(f"Could not notify group {group_id} of expiry: {e}")

            else:
                # ── Still open: check if 24h reminder is due ──
                last_reminder = reg_info.get('last_reminder_at')
                if last_reminder is None or (now - last_reminder).total_seconds() >= 86400:
                    days_left = (end_dt - now).days
                    hours_left = int((end_dt - now).total_seconds() // 3600)

                    # Count current registrations
                    try:
                        conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
                        c = conn.cursor()
                        c.execute("SELECT COUNT(*) FROM registered_players WHERE group_id = ?", (group_id,))
                        count = c.fetchone()[0]
                        conn.close()
                    except Exception:
                        count = "?"

                    time_str = (
                        f"{days_left} day{'s' if days_left != 1 else ''}"
                        if days_left >= 1
                        else f"{hours_left} hour{'s' if hours_left != 1 else ''}"
                    )

                    try:
                        await context.bot.send_message(
                            chat_id=group_id,
                            text=(
                                f"⏰ <b>REGISTRATION REMINDER</b>\n"
                                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                                f"🏆 <b>{html.escape(tournament_name)}</b>\n\n"
                                f"📅 Registration closes in <b>{time_str}</b>!\n"
                                f"👥 <b>{count}</b> player(s) registered so far.\n\n"
                                f"🏏 Not signed up yet? Use /register now!\n"
                                f"📋 View list: /registeredlist\n"
                                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
                            ),
                            parse_mode=ParseMode.HTML
                        )
                        REGISTRATION_ACTIVE[group_id]['last_reminder_at'] = now
                    except Exception as e:
                        logger.error(f"Could not send reminder to group {group_id}: {e}")

        # Remove expired groups from in-memory dict
        for gid in to_remove:
            REGISTRATION_ACTIVE.pop(gid, None)
            logger.info(f"Registration expired and closed for group {gid}")

    except Exception as e:
        logger.error(f"registration_expiry_checker_job error: {e}")


async def approval_expiry_checker_job(context: ContextTypes.DEFAULT_TYPE):
    """
    🔔 Daily job:
    - Sends reminders to owner + support group when a group has ≤5 days left
    - Pins warning in the GC when ≤5 days left
    - Auto-disapproves and notifies group + support group when expired
    """
    try:
        now = datetime.now()
        conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
        c = conn.cursor()
        c.execute("SELECT group_id, group_name, expires_at, reminder_sent FROM tournament_groups")
        rows = c.fetchall()

        for group_id, group_name, expires_at_str, reminder_sent in rows:
            if not expires_at_str:
                continue
            try:
                expires_at = datetime.fromisoformat(expires_at_str)
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 24774)")
                continue

            days_left = (expires_at - now).days

            # ── Reminder: exactly 1 day left ──
            if days_left == 1:
                if not reminder_sent:
                    c.execute("UPDATE tournament_groups SET reminder_sent = 1 WHERE group_id = ?", (group_id,))
                    conn.commit()

                expiry_str = expires_at.strftime("%d %b %Y")

                # Notify owner DM
                try:
                    await context.bot.send_message(
                        chat_id=OWNER_ID,
                        text=themed(
                            "GROUP APPROVAL EXPIRING",
                            [
                                f"📛 Group: <b>{html.escape(group_name)}</b>",
                                f"🆔 ID: <code>{group_id}</code>",
                                f"⏳ {days_left} day{'s' if days_left != 1 else ''} left",
                                f"📅 Expires: {expiry_str}",
                                f"Use <code>/groupapprove {group_id}</code> to renew.",
                            ],
                            "⚠️",
                        ),
                        parse_mode=ParseMode.HTML
                    )
                except Exception as e:
                    logger.error(f"Failed to send owner reminder: {e}")

                # Notify support group
                try:
                    await context.bot.send_message(
                        chat_id=SUPPORT_GROUP_ID,
                        text=(
                            f"⚠️ <b>PREMIUM EXPIRING SOON</b>\n"
                            f"📛 Group: {html.escape(group_name)} (<code>{group_id}</code>)\n"
                            f"⏳ {days_left} day{'s' if days_left != 1 else ''} left · Expires: {expiry_str}"
                        ),
                        parse_mode=ParseMode.HTML
                    )
                except Exception as e:
                    logger.error(f"Failed to send support group reminder: {e}")

                # Send + pin warning in the GC
                try:
                    warn_msg = await context.bot.send_message(
                        chat_id=group_id,
                        text=themed(
                            "PREMIUM ACCESS EXPIRING",
                            [
                                f"Your group's Tournament & Auction authorization ends in <b>{days_left} day{'s' if days_left != 1 else ''}</b> ({expiry_str}).",
                                "🔄 Contact the bot owner to renew your access before it expires.",
                            ],
                            "⚠️",
                        ),
                        parse_mode=ParseMode.HTML
                    )
                    try:
                        await context.bot.pin_chat_message(chat_id=group_id, message_id=warn_msg.message_id, disable_notification=False)
                    except Exception as e:
                        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 24835)")
                        pass
                except Exception as e:
                    logger.error(f"Failed to warn group {group_id}: {e}")

            # ── Auto-disapprove expired groups ──
            elif days_left < 0:
                TOURNAMENT_APPROVED_GROUPS.discard(group_id)
                c.execute("DELETE FROM tournament_groups WHERE group_id = ?", (group_id,))
                conn.commit()

                # Notify the group
                try:
                    await context.bot.send_message(
                        chat_id=group_id,
                        text=themed(
                            "PREMIUM ACCESS EXPIRED",
                            [
                                "⚠️ Your group's Tournament & Auction features have been automatically disabled.",
                                "🔄 To restore access, ask the bot owner to renew the group's approval.",
                            ],
                            "🚫",
                        ),
                        parse_mode=ParseMode.HTML
                    )
                except Exception as e:
                    logger.error(f"Failed to notify group {group_id} of expiry: {e}")

                # Notify support group
                try:
                    await context.bot.send_message(
                        chat_id=SUPPORT_GROUP_ID,
                        text=(
                            f"🚫 <b>GROUP APPROVAL EXPIRED</b>\n"
                            f"📛 Group: {html.escape(group_name)} (<code>{group_id}</code>)\n"
                            f"⏰ Automatically removed from premium access."
                        ),
                        parse_mode=ParseMode.HTML
                    )
                except Exception as e:
                    logger.error(f"Failed to notify support group of expiry: {e}")

                logger.info(f"✅ Auto-disapproved group {group_id} ({group_name}) - expired")

        conn.close()
    except Exception as e:
        logger.error(f"Approval expiry checker error: {e}")

async def restore_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔄 Direct Restore Command - No Confirmation Required"""
    user = update.effective_user
    
    # Security: Only owner can restore
    if not has_power(user.id, "backup"): 
        await update.message.reply_text("🚫 <b>Access Denied!</b>\n\nOnly bot owner can restore backups.", parse_mode=ParseMode.HTML)
        return
    
    # Check if replied to a document
    if not update.message.reply_to_message or not update.message.reply_to_message.document:
        help_text = (
            "📋 <b>How to Restore Database</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            "1️⃣ Upload or forward the backup .db file\n"
            "2️⃣ Reply to that file with <code>/restore</code>\n\n"
            "⚠️ <b>Important:</b>\n"
            "• All active matches will be ended\n"
            "• Current data will be replaced immediately\n"
            "• Only .db or .sqlite files accepted\n\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
        )
        await update.message.reply_text(help_text, parse_mode=ParseMode.HTML)
        return

    doc = update.message.reply_to_message.document

    # Security: Check file extension
    if not doc.file_name.endswith(('.db', '.sqlite', '.sqlite3')):
        await update.message.reply_text(
            "⚠️ <b>Invalid File Type!</b>\n\n"
            "Only <code>.db</code>, <code>.sqlite</code>, or <code>.sqlite3</code> files are allowed.\n\n"
            f"Your file: <code>{doc.file_name}</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    status = await update.message.reply_text("⏳ <b>Restoring database...</b>", parse_mode=ParseMode.HTML)
    temp_path = f"temp_restore_{int(time.time())}.db"

    try:
        # Download file
        new_file = await doc.get_file()
        await new_file.download_to_drive(temp_path)
        
        # Validate database file
        try:
            conn = sqlite3.connect(temp_path)
            c = conn.cursor()
            c.execute("SELECT name FROM sqlite_master WHERE type='table'")
            tables = [row[0] for row in c.fetchall()]
            
            if not tables:
                os.remove(temp_path)
                await status.edit_text(
                    "❌ <b>Invalid Database!</b>\n\nThe file appears to be empty or corrupted.",
                    parse_mode=ParseMode.HTML
                )
                return
            conn.close()
        except sqlite3.Error as e:
            if os.path.exists(temp_path):
                os.remove(temp_path)
            await status.edit_text(
                f"❌ <b>Invalid Database!</b>\n\nCorrupted or not a valid SQLite file.\n\nError: <code>{str(e)}</code>",
                parse_mode=ParseMode.HTML
            )
            return
        
        # Backup current database before restore
        safety_backup = f"pre_restore_backup_{int(time.time())}.db"
        if os.path.exists(DB_FILE):
            shutil.copy(DB_FILE, safety_backup)
        
        # Replace database
        shutil.move(temp_path, DB_FILE)

        # 🔧 FIX: force schema re-init on the restored file. db_connect()
        # only runs init_db() once per process (guarded by _db_ready), so
        # without this reset a restored backup missing tables/columns
        # (e.g. an older export without user_stats) kept throwing
        # "no such table: user_stats" for the rest of the bot's uptime.
        global _db_ready
        _db_ready = False
        init_db()
        _db_ready = True

        # Clear and reload data
        global user_data, match_history, player_stats, achievements, registered_groups
        user_data = {}
        match_history = []
        player_stats = {}
        achievements = {}
        registered_groups = {}
        
        load_data()
        sync_legacy_player_stats_to_ccc()
        
        await status.edit_text(
            f"✅ <b>Restore Complete!</b>\n"
            f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
            f"🔄 Database restored from <code>{doc.file_name}</code>\n"
            f"💾 Safety backup: <code>{safety_backup}</code>\n\n"
            f"⚡ All data reloaded successfully.",
            parse_mode=ParseMode.HTML
        )
        
    except Exception as e:
        logger.error(f"Restore failed: {e}")
        if os.path.exists(temp_path):
            os.remove(temp_path)
        await status.edit_text(
            f"❌ <b>Restore Failed!</b>\n\nError: <code>{str(e)}</code>",
            parse_mode=ParseMode.HTML
        )

async def handle_restore_confirmation(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle restore confirmation"""
    user = update.effective_user
    
    if not has_power(user.id, "backup"):
        return
    
    if 'temp_restore_file' not in context.user_data:
        return
    
    text = update.message.text.strip().upper()
    
    if text == "CONFIRM":
        temp_path = context.user_data['temp_restore_file']
        
        if not os.path.exists(temp_path):
            await update.message.reply_text("❌ Temporary file not found. Please try again.")
            return
        
        status = await update.message.reply_text("⏳ <b>Restoring database...</b>", parse_mode=ParseMode.HTML)
        
        try:
            # Backup current database before restore (safety measure)
            safety_backup = f"pre_restore_backup_{int(time.time())}.db"
            if os.path.exists(DB_FILE):
                shutil.copy(DB_FILE, safety_backup)
            
            # Replace database
            shutil.move(temp_path, DB_FILE)

            # 🔧 FIX: same schema re-init as /restore direct path — see comment there.
            global _db_ready
            _db_ready = False
            init_db()
            _db_ready = True

            # Clear and reload data
            global user_data, match_history, player_stats, achievements, registered_groups
            user_data = {}
            match_history = []
            player_stats = {}
            achievements = {}
            registered_groups = {}
            
            load_data()
            sync_legacy_player_stats_to_ccc()
            
            await status.edit_text(
                f"✅ <b>Restore Complete!</b>\n"
                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
                f"🔄 Database restored successfully\n"
                f"💾 Safety backup saved: <code>{safety_backup}</code>\n\n"
                f"⚡ All data has been reloaded.\n"
                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈",
                parse_mode=ParseMode.HTML
            )
            
            # Clear context
            context.user_data.clear()
            
        except Exception as e:
            logger.error(f"Restore execution failed: {e}")
            
            # Restore from safety backup if exists
            if os.path.exists(safety_backup):
                shutil.move(safety_backup, DB_FILE)
                load_data()
                await status.edit_text(
                    f"❌ <b>Restore Failed!</b>\n\n"
                    f"Original database has been restored.\n\n"
                    f"Error: <code>{str(e)}</code>",
                    parse_mode=ParseMode.HTML
                )
            else:
                await status.edit_text(
                    f"❌ <b>Critical Error!</b>\n\n"
                    f"Error: <code>{str(e)}</code>",
                    parse_mode=ParseMode.HTML
                )
    
    elif text == "CANCEL":
        temp_path = context.user_data.get('temp_restore_file')
        if temp_path and os.path.exists(temp_path):
            os.remove(temp_path)
        
        context.user_data.clear()
        
        await update.message.reply_text(
            "❌ <b>Restore Cancelled</b>\n\n"
            "No changes were made to the database.",
            parse_mode=ParseMode.HTML
        )

async def bug_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    🛠️ Report a Bug to Bot Owner
    Usage: /bug <description>
    or Reply to a message with /bug

    Limited to 1 report per player per day. When the owner replies to the
    forwarded report in their DM, that reply is routed back to the reporter
    as a reply to their original /bug message (falls back to a plain DM).
    """
    user = update.effective_user
    chat = update.effective_chat

    # ── 1 use per player per day ──
    today_str = datetime.now().strftime('%Y-%m-%d')
    if user.id != OWNER_ID and bug_command_usage.get(str(user.id)) == today_str:
        await update.message.reply_text(
            "⚠️ <b>Daily limit reached.</b>\nYou can only report 1 bug per day. Try again tomorrow.",
            parse_mode=ParseMode.HTML
        )
        return

    # Check if there's a description
    bug_text = " ".join(context.args) if context.args else None
    
    # If replied to a message, include that context
    reply_context = ""
    if update.message.reply_to_message:
        reply_msg = update.message.reply_to_message
        reply_context = f"\n\n📌 <b>Reply Context:</b>\n{reply_msg.text[:200] if reply_msg.text else 'Media/File'}"
    
    if not bug_text and not reply_context:
        await update.message.reply_text(
            "🐛 <b>Report a Bug</b>\n\n"
            "<b>Usage:</b>\n"
            "• <code>/bug [description]</code>\n"
            "• Reply to error message with <code>/bug</code>\n\n"
            "<b>Example:</b>\n"
            "<code>/bug Wicket not counting properly</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Build report
    user_tag = f'<a href=\"tg://user?id={user.id}\">{html.escape(user.first_name)}</a>' + _title_suffix(user.id)
    
    report = f"🚨 <b>BUG REPORT</b> 🚨\n"
    report += "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
    report += f"👤 <b>User:</b> {user_tag}\n"
    report += f"🆔 <b>User ID:</b> <code>{user.id}</code>\n"
    report += f"💬 <b>Chat:</b> {chat.title if chat.title else 'Private'}\n"
    report += f"🆔 <b>Chat ID:</b> <code>{chat.id}</code>\n"
    report += f"📅 <b>Date:</b> {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n\n"
    
    if bug_text:
        report += f"📝 <b>Description:</b>\n{bug_text}\n"
    
    if reply_context:
        report += reply_context
    
    report += "\n\n<i>Reply to this message to answer the reporter directly.</i>"
    report += "\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
    
    # Send to owner
    try:
        sent_msg = await context.bot.send_message(
            chat_id=OWNER_ID,
            text=report,
            parse_mode=ParseMode.HTML
        )

        # Remember this message so a reply from the owner can be routed back
        bug_report_map[str(sent_msg.message_id)] = {
            "reporter_id": user.id,
            "reporter_chat_id": chat.id,
            "reporter_msg_id": update.message.message_id,
        }

        if user.id != OWNER_ID:
            bug_command_usage[str(user.id)] = today_str
        
        # Confirm to user
        await update.message.reply_text(
            "✅ <b>Bug Reported!</b>\n\n"
            "Thank you for reporting. The developer has been notified.\n"
            "We'll fix it ASAP! 🛠️",
            parse_mode=ParseMode.HTML
        )
        
        logger.info(f"🐞 Bug reported by {user.first_name} (ID: {user.id})")
        
    except Exception as e:
        logger.error(f"❌ Failed to send bug report: {e}")
        await update.message.reply_text(
            "❌ Failed to send report. Please try again later.",
            parse_mode=ParseMode.HTML
        )


async def _handle_bug_owner_reply(update: Update, context: ContextTypes.DEFAULT_TYPE, mapping: Dict):
    """🛠️ Routes the owner's DM reply on a forwarded bug report back to the original
    reporter as a reply to their /bug message; falls back to a plain DM if that fails."""
    msg = update.message
    answer_text = f"🛠️ <b>Reply from the developer:</b>\n{html.escape(msg.text or '')}"
    try:
        await context.bot.send_message(
            chat_id=mapping["reporter_chat_id"],
            text=answer_text,
            parse_mode=ParseMode.HTML,
            reply_to_message_id=mapping["reporter_msg_id"]
        )
    except Exception:
        # Fallback: DM the reporter directly if replying in the original chat fails
        try:
            await context.bot.send_message(
                chat_id=mapping["reporter_id"],
                text=answer_text,
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.error(f"❌ Failed to route bug reply to reporter: {e}")
            await msg.reply_text("⚠️ Couldn't deliver this reply to the reporter.")


async def _handle_owner_regame_confirm(update: Update, context: ContextTypes.DEFAULT_TYPE, backup_meta: Dict):
    """🛠️ Owner replied "regame" to a match-file backup DM'd earlier — load that exact
    snapshot and commit its stats to the database as-is (winner determined from the
    score frozen at snapshot time), without needing the match to be live in a group."""
    msg = update.message
    backup_path = backup_meta.get("backup_path")
    if not backup_path or not os.path.exists(backup_path):
        await msg.reply_text("❌ That backup file is no longer available (may have already been committed).")
        return

    try:
        with open(backup_path, "rb") as f:
            match = await asyncio.to_thread(pickle.load, f)
    except Exception as e:
        logger.error(f"Failed to load owner regame backup: {e}")
        await msg.reply_text(f"❌ Failed to load that match file: {e}")
        return

    group_id = backup_meta.get("group_id") or getattr(match, "group_id", None)
    try:
        await determine_match_winner(context, group_id, match)
        await msg.reply_text(
            f"✅ <b>Committed!</b>\nStats for match <code>{backup_meta.get('code')}</code> "
            f"have been saved to the database as-is.",
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.error(f"Failed to commit owner regame stats: {e}")
        await msg.reply_text(f"❌ Failed to save stats: {e}")
        return

    # One-time use — remove the backup file + mapping once committed
    try:
        os.remove(backup_path)
    except Exception:
        pass
    owner_regame_backups.pop(str(msg.reply_to_message.message_id), None)


async def owner_dm_reply_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🛠️ Single entry point for the owner replying to a bot DM — routes to whichever
    feature the replied-to message belongs to (bug report answer, or a /regame
    match-file backup confirmation). Combined into one handler because both need the
    same (private + reply + owner + text) filter, and only one handler can claim a
    given update."""
    user = update.effective_user
    if user.id != OWNER_ID:
        return
    msg = update.message
    if not msg or not msg.reply_to_message or update.effective_chat.type != "private":
        return

    replied_id = str(msg.reply_to_message.message_id)

    bug_mapping = bug_report_map.get(replied_id)
    if bug_mapping:
        await _handle_bug_owner_reply(update, context, bug_mapping)
        return

    regame_mapping = owner_regame_backups.get(replied_id)
    if regame_mapping and (msg.text or "").strip().lower() == "regame":
        await _handle_owner_regame_confirm(update, context, regame_mapping)
        return


async def refresh_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /refresh — Admin only. Resends the main setup/lobby button message
    if the original was accidentally deleted.
    """
    chat = update.effective_chat
    user = update.effective_user

    if chat.type == "private":
        await update.message.reply_text("❌ Use this in a group!")
        return

    # Admin or host check
    is_admin = False
    try:
        member = await context.bot.get_chat_member(chat.id, user.id)
        if member.status in ("administrator", "creator"):
            is_admin = True
    except Exception:
        pass

    match = active_matches.get(chat.id)

    if match and user.id == match.host_id:
        is_admin = True

    if not is_admin:
        await update.message.reply_text("🚫 Only admins or the host can use /refresh.")
        return

    if not match:
        await update.message.reply_text("❌ No active match to refresh!")
        return

    # Clear stale message id so refresh_game_message sends a fresh one
    match.main_message_id = None

    phase = match.phase

    try:
        if phase == GamePhase.TEAM_JOINING:
            await update_joining_board(context, chat.id, match)
            # update_joining_board checks main_message_id; since it's None, it won't edit.
            # Instead call the full refresh path:
            text = get_team_join_message(match)
            keyboard = [
                [styled_button("Join Team X", callback_data="join_team_x"),
                 styled_button("Join Team Y", callback_data="join_team_y")],
                [styled_button("Leave Team", callback_data="leave_team")]
            ]
            await refresh_game_message(context, chat.id, match, text, InlineKeyboardMarkup(keyboard), media_key="joining")

        elif phase == GamePhase.TEAM_EDIT:
            await update_team_edit_message(context, chat.id, match)

        elif phase == GamePhase.TOSS:
            # Rebuild toss message
            toss_text = (
                f"🪙 <b>TOSS TIME</b>\n"
                f"<blockquote>┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                f"🎙 Host is flipping the coin!\n"
                f"⏳ Waiting for toss decision...\n"
                f"</blockquote>"
            )
            keyboard = [
                [styled_button("Heads (Team X)", callback_data="toss_heads"),
                 styled_button("Tails (Team Y)", callback_data="toss_tails")]
            ]
            await refresh_game_message(context, chat.id, match, toss_text, InlineKeyboardMarkup(keyboard), media_key="toss")

        elif phase in (GamePhase.SOLO_JOINING,):
            # Solo lobby refresh
            from_text = get_team_join_message(match) if hasattr(match, 'team_x') else "Solo lobby active."
            keyboard = [[styled_button("Join Solo Match", callback_data="solo_join")]]
            await refresh_game_message(context, chat.id, match, from_text, InlineKeyboardMarkup(keyboard), media_key="joining")

        else:
            await update.message.reply_text(
                f"♻️ Refresh sent! (Match phase: {phase.value if phase else 'unknown'})\n"
                "Note: During live match, only lobby/setup messages can be refreshed."
            )
            return

        await update.message.reply_text("✅ Setup message has been refreshed and pinned!")
    except Exception as e:
        logger.error(f"refresh_command error: {e}")
        await update.message.reply_text(f"⚠️ Could not refresh: {e}")


def _get_match_player_ids(match) -> Set[int]:
    """Returns the user_ids of everyone actually playing in this match right
    now (team mode: both squads, solo mode: solo_players) — used to work out
    the 50% threshold for an admin-triggered /endmatch vote."""
    ids: Set[int] = set()
    try:
        if getattr(match, 'game_mode', None) == "SOLO" or hasattr(match, 'solo_players'):
            for p in getattr(match, 'solo_players', []) or []:
                if getattr(p, 'user_id', None):
                    ids.add(p.user_id)
        if hasattr(match, 'team_x') and match.team_x:
            for p in getattr(match.team_x, 'players', []) or []:
                if getattr(p, 'user_id', None):
                    ids.add(p.user_id)
        if hasattr(match, 'team_y') and match.team_y:
            for p in getattr(match.team_y, 'players', []) or []:
                if getattr(p, 'user_id', None):
                    ids.add(p.user_id)
    except Exception as e:
        logger.error(f"_get_match_player_ids error: {e}")
    return ids


# ⏱️ Phases before the first ball is bowled — a group admin can end the match
# directly here (no vote needed): joining, host/captain/fantasy pick, team
# edit, over selection, toss. Module-level so both endmatch_command and the
# confirm_endmatch/confirm_endsolo_* callbacks share the exact same set.
PRE_FIRST_BALL_PHASES = {
    GamePhase.TEAM_JOINING, GamePhase.HOST_SELECTION, GamePhase.CAPTAIN_SELECTION,
    GamePhase.FANTASY_PICK, GamePhase.TEAM_EDIT, GamePhase.OVER_SELECTION,
    GamePhase.TOSS, GamePhase.SOLO_JOINING,
}


async def _endmatch_can_direct_end(context: ContextTypes.DEFAULT_TYPE, group_id: int, user_id: int, match) -> bool:
    """Host can always end directly. A non-host group admin can only end
    directly in a PRE_FIRST_BALL_PHASES phase — anywhere else they must go
    through the Yes/No vote flow in endmatch_command. Shared by the
    confirm_endmatch / confirm_endsolo_* callbacks so they agree with
    endmatch_command about who's allowed to reach this dialog at all."""
    if user_id == match.host_id:
        return True
    if match.phase not in PRE_FIRST_BALL_PHASES:
        return False
    try:
        member = await context.bot.get_chat_member(group_id, user_id)
        return member.status in ("administrator", "creator")
    except Exception:
        return False


async def endmatch_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """End the current match — host can end directly (existing confirm flow).
    A group admin (non-host) can also call /endmatch, but that instead opens
    a Yes/No VOTE among the players currently in the match — the match only
    ends once at least 50% of them vote Yes."""

    if update.effective_chat.type == "private":
        await update.message.reply_text("❌ Use this in a group!")
        return

    group_id = update.effective_chat.id
    user_id = update.effective_user.id

    match = active_matches.get(group_id)

    if not match:
        await update.message.reply_text("❌ No active match to end!")
        return

    # 🔒 Host can end directly (existing confirm flow, unchanged).
    # A non-host GROUP ADMIN can also trigger it, but goes through a vote
    # instead — no one else (regular player) can start /endmatch at all.
    # EXCEPTION: before the first ball is bowled, an admin can end directly too.
    if user_id != match.host_id:
        try:
            member = await context.bot.get_chat_member(group_id, user_id)
            is_admin = member.status in ("administrator", "creator")
        except Exception:
            is_admin = False

        if not is_admin:
            await update.message.reply_text("❌ Only the match host or a group admin can end the match!")
            return

        if match.phase not in PRE_FIRST_BALL_PHASES:
            # First ball already bowled → go through the Yes/No vote flow.
            _old = active_endmatch_votes.get(group_id)
            if _old and (_old.get("match_ref") is not match or time.time() > _old.get("expires_at", 0)):
                if _old.get("task"):
                    _old.get("task").cancel()
                active_endmatch_votes.pop(group_id, None)      # stale / expired → allow a fresh vote
                _old = None
            if _old:
                await update.message.reply_text("⚠️ An end-match vote is already running for this match!")
                return

            eligible = _get_match_player_ids(match)
            if not eligible:
                await update.message.reply_text("❌ No players found in this match to vote!")
                return

            _vote = {
                "yes": set(), "no": set(), "eligible": eligible,
                "message_id": None, "initiator": user_id,
                "match_ref": match, "expires_at": time.time() + ENDMATCH_VOTE_SECONDS, "task": None,
            }
            active_endmatch_votes[group_id] = _vote
            needed = max(1, math.ceil(len(eligible) / 2))
            vote_msg = await update.message.reply_text(
                themed("END MATCH VOTE", [
                    f"👮 Started by admin: {html.escape(update.effective_user.first_name)}",
                    f"🗳 0 Yes / 0 No — need {needed}/{len(eligible)} Yes",
                    f"⏳ Closes in {ENDMATCH_VOTE_SECONDS}s",
                    "Only players currently in this match can vote.",
                ], emoji="⚠️"),
                parse_mode=ParseMode.HTML,
                reply_markup=_endmatch_vote_kb()
            )
            _vote["message_id"] = vote_msg.message_id
            _vote["task"] = asyncio.create_task(_endmatch_vote_expire(context.bot, group_id, _vote))
            return
        # else: first ball not bowled yet → fall through to direct-end confirm flow below

    # ── Solo mode ──
    if getattr(match, 'game_mode', None) == "SOLO" or match.phase in [GamePhase.SOLO_JOINING, GamePhase.SOLO_MATCH]:
        keyboard = InlineKeyboardMarkup([[
            styled_button("Yes, End Solo", callback_data=f"confirm_endsolo_{group_id}"),
            styled_button("Cancel", callback_data="cancel_endsolo")
        ]])
        await update.message.reply_text(
            "⚠️ Are you sure you want to end this solo match?\n\n"
            "📊 Final results will be generated and stats will be saved.",
            parse_mode=ParseMode.HTML,
            reply_markup=keyboard
        )
        return

    # ── Team / Tournament mode ──
    keyboard = InlineKeyboardMarkup([[
        styled_button("Yes, End Match", callback_data="confirm_endmatch"),
        styled_button("Cancel", callback_data="cancel_endmatch")
    ]])
    await update.message.reply_text(
        "⚠️ Are you sure you want to end this match?\n\n"
        "This will terminate the current game without saving stats.",
        parse_mode=ParseMode.HTML,
        reply_markup=keyboard
    )

async def regame_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /regame <code>
    Resume a match that was force-stopped mid-way (no result declared), within
    12 hours of stopping — picks up EXACTLY where it left off. Only the
    ORIGINAL HOST of that specific match can use it, and only in the same
    group where it was stopped. Works for both Team and Solo modes.
    """
    if update.effective_chat.type == "private":
        await update.message.reply_text("❌ Use this command in the group where the match was stopped!")
        return

    group_id = update.effective_chat.id
    user_id = update.effective_user.id

    if not context.args:
        await update.message.reply_text(
            "⚙️ <b>Usage:</b> <code>/regame [code]</code>\n\n"
            "Resumes a match that was force-stopped mid-way, within 12 hours.\n"
            "The code was shown in-chat when the match started and again when it stopped.\n"
            "Only the host of that match can use it.",
            parse_mode=ParseMode.HTML
        )
        return

    code = context.args[0].strip()
    meta = RESUMABLE_MATCHES.get(code)

    if not meta:
        await update.message.reply_text("❌ Invalid or expired code!")
        return

    try:
        expires_at = datetime.fromisoformat(meta["expires_at"])
    except Exception:
        expires_at = datetime.now() - timedelta(seconds=1)
    if datetime.now() > expires_at and user_id != OWNER_ID:
        _discard_resumable(code)
        await update.message.reply_text("❌ This code has expired (valid for 12 hours only).")
        return

    if meta["group_id"] != group_id and user_id != OWNER_ID:
        await update.message.reply_text("❌ This code belongs to a different group!")
        return

    if meta["host_id"] != user_id and user_id != OWNER_ID:
        await update.message.reply_text("❌ Only the host of that match can use this code!")
        return

    if group_id in active_matches:
        await update.message.reply_text("❌ A match is already active in this group! End it first with /endmatch.")
        return

    file_path = meta.get("file_path")
    if not file_path or not os.path.exists(file_path):
        _discard_resumable(code)
        await update.message.reply_text("❌ Saved match data not found (may have already expired).")
        return

    try:
        with open(file_path, "rb") as f:
            match = await asyncio.to_thread(pickle.load, f)
    except Exception as e:
        logger.error(f"Failed to load resumable match {code}: {e}")
        await update.message.reply_text(f"❌ Failed to load saved match: {e}")
        return

    # 🔧 Clear any leftover pause/re-entrancy state from before the snapshot,
    # and make sure no stale (unpicklable, stripped-to-None) task handles
    # linger around — they'll be recreated fresh by the re-request below.
    match.is_paused = False
    match.pause_until = 0.0
    for _attr in _RESUME_STRIP_ATTRS:
        if hasattr(match, _attr):
            setattr(match, _attr, None)

    active_matches[group_id] = match

    # 🛠️ Owner-only: back up the raw snapshot to DM before it's consumed, so the
    # owner can later reply "regame" on that file to commit its stats to the DB
    # as-is — even without resuming the match live in a group.
    if user_id == OWNER_ID:
        try:
            os.makedirs(RESUMABLE_DIR, exist_ok=True)
            backup_path = os.path.join(RESUMABLE_DIR, f"owner_backup_{code}_{int(time.time())}.pkl")
            await asyncio.to_thread(shutil.copyfile, file_path, backup_path)
            sent_doc = await context.bot.send_document(
                chat_id=OWNER_ID,
                document=backup_path,
                filename=f"match_{code}.pkl",
                caption=(
                    f"🗂️ <b>Match File</b> — code <code>{code}</code>\n"
                    f"📍 Group: {html.escape(meta.get('group_name') or 'Unknown')}\n\n"
                    f"<i>Reply <code>regame</code> to this message to save this match's "
                    f"stats to the database as-is.</i>"
                ),
                parse_mode=ParseMode.HTML
            )
            owner_regame_backups[str(sent_doc.message_id)] = {
                "backup_path": backup_path,
                "code": code,
                "group_id": meta.get("group_id"),
                "group_name": meta.get("group_name"),
            }
            save_data()
        except Exception as e:
            logger.error(f"Failed to send owner regame backup file: {e}")

    # Single-use: this exact snapshot is consumed once resumed.
    _discard_resumable(code)

    mode_label = "Solo" if getattr(match, 'game_mode', None) == "SOLO" else "Team"
    await update.message.reply_text(
        f"♻️ <b>MATCH RESUMED!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🎮 <b>Mode:</b> {mode_label}\n"
        f"📍 Picking up exactly where it was stopped.\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"Continue play as normal!",
        parse_mode=ParseMode.HTML
    )

    # 🔁 Actually bring gameplay back to life — re-request whatever the match
    # was waiting on when it was force-stopped, exactly like /timeout's
    # auto-resume does. Without this the match just sits in active_matches
    # with nobody ever prompted for the next action.
    try:
        if getattr(match, 'waiting_for_bowler', False):
            await request_bowler_selection(context, group_id, match)
        elif getattr(match, 'waiting_for_batsman', False):
            captain = match.get_captain(match.current_batting_team) if match.current_batting_team else None
            cap_tag = get_user_tag(captain) if captain else (match.current_batting_team.name if match.current_batting_team else "Batting team")
            await context.bot.send_message(
                group_id,
                themed(f"{cap_tag} ➔ Select your batsman!", [
                    f"⚙️ 𝗨𝘀𝗲: <code>/batting [number]</code>",
                ], "⚔️"),
                parse_mode=ParseMode.HTML
            )
            match.batsman_selection_time = time.time()
            match.batsman_selection_task = asyncio.create_task(
                batsman_selection_timeout(context, group_id, match)
            )
        elif match.phase in (GamePhase.MATCH_IN_PROGRESS, GamePhase.SUPER_OVER):
            # Mid-ball → restart ball execution from where it left off
            await execute_ball(context, group_id, match)
    except Exception as e:
        logger.error(f"Failed to re-trigger gameplay after /regame resume: {e}")
        await context.bot.send_message(
            group_id,
            "⚠️ Match state restored, but couldn't auto-resume the current action. "
            "Host may need to re-trigger it manually.",
        )



async def timeout_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ⏸️ TIMEOUT — Host pauses game for 2 minutes.
    Usage: /timeout  (host only, once per team per match)
    """
    chat = update.effective_chat
    user = update.effective_user

    if chat.type == "private":
        await update.message.reply_text("❌ Use this command in a group!")
        return

    group_id = chat.id
    match = active_matches.get(group_id)

    if not match:
        await update.message.reply_text("❌ No active match found!", parse_mode=ParseMode.HTML)
        return

    if match.phase not in (GamePhase.MATCH_IN_PROGRESS, GamePhase.SUPER_OVER):
        await update.message.reply_text("⚠️ Timeout can only be called during an active match.", parse_mode=ParseMode.HTML)
        return

    if user.id != match.host_id:
        await update.message.reply_text("🚧 <b>HOST ONLY!</b>\nOnly the host can call a timeout.", parse_mode=ParseMode.HTML)
        return

    if match.is_paused:
        remaining = int(match.pause_until - time.time())
        if remaining > 0:
            await update.message.reply_text(
                f"⏸️ <b>ALREADY PAUSED!</b>\nGame resumes in <b>{remaining}s</b>.",
                parse_mode=ParseMode.HTML
            )
            return

    # Pause the game
    match.is_paused = True
    PAUSE_SECONDS = 120
    match.pause_until = time.time() + PAUSE_SECONDS

    # Cancel active ball timers so they don't expire during pause
    if match.ball_timeout_task:
        match.ball_timeout_task.cancel()
        match.ball_timeout_task = None
    if match.bowler_selection_task:
        match.bowler_selection_task.cancel()
        match.bowler_selection_task = None
    if match.batsman_selection_task:
        match.batsman_selection_task.cancel()
        match.batsman_selection_task = None

    pause_msg = (
        f"⏸️〔 <b>TIMEOUT CALLED!</b> 〕⏸️\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🎯 Called by: <b>{user.first_name}</b> (Host)\n"
        f"⏱ Game paused for <b>{PAUSE_SECONDS // 60} minutes</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"📊 <b>{match.current_batting_team.name if match.current_batting_team else '?'}</b>: "
        f"<b>{match.current_batting_team.score if match.current_batting_team else '?'}"
        f"/{match.current_batting_team.wickets if match.current_batting_team else '?'}</b>\n"
        f"<i>Game will auto-resume after 2 minutes.</i>"
    )
    await context.bot.send_message(group_id, pause_msg, parse_mode=ParseMode.HTML)

    async def _resume_after_timeout():
        try:
            await asyncio.sleep(PAUSE_SECONDS)
            if not match.is_paused:
                return
            match.is_paused = False
            match.pause_until = 0.0

            resume_msg = (
                f"▶️〔 <b>TIMEOUT OVER → GAME RESUMED!</b> 〕▶️\n"
                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                f"🏏 <b>{match.current_batting_team.name if match.current_batting_team else '?'}</b> continues batting!\n"
                f"<i>Players, get ready!</i>"
            )
            await context.bot.send_message(group_id, resume_msg, parse_mode=ParseMode.HTML)

            # Re-request bowler/batsman input depending on what we were waiting for
            if match.waiting_for_bowler:
                await request_bowler_selection(context, group_id, match)
            elif match.waiting_for_batsman:
                captain = match.get_captain(match.current_batting_team)
                cap_tag = get_user_tag(captain) if captain else match.current_batting_team.name
                await context.bot.send_message(
                    group_id,
                    themed(f"{cap_tag} ➔ Select your batsman!", [
                        f"⚙️ 𝗨𝘀𝗲: <code>/batting [number]</code>",
                    ], "⚔️"),
                    parse_mode=ParseMode.HTML
                )
                match.batsman_selection_time = time.time()
                match.batsman_selection_task = asyncio.create_task(
                    batsman_selection_timeout(context, group_id, match)
                )
            else:
                # Mid-ball → restart ball execution
                await execute_ball(context, group_id, match)
        except asyncio.CancelledError:
            pass
        except Exception as e:
            logger.error(f"Timeout resume error: {e}")

    if match.pause_task:
        match.pause_task.cancel()
    match.pause_task = asyncio.create_task(_resume_after_timeout())


async def changehost_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Change Host System: Both Captains must vote YES
    Usage: Reply to a player with /changehost
    """
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_matches:
        await update.message.reply_text("❌ No active match.")
        return
    
    match = active_matches[chat.id]
    
    # Only works in Team Edit or Match Phases
    if match.phase not in [GamePhase.TEAM_EDIT, GamePhase.MATCH_IN_PROGRESS]:
        await update.message.reply_text("⚠️ Host change only allowed during Team Edit or Match.")
        return
    
    # Check if user is a captain
    captain_x = match.team_x.captain_id
    captain_y = match.team_y.captain_id
    
    if user.id not in [captain_x, captain_y]:
        await update.message.reply_text("🚫 Only Captains can initiate host change!")
        return
    
    # Check if replied to someone
    if not update.message.reply_to_message:
        await update.message.reply_text("⚠️ Reply to the player you want to make Host.")
        return
    
    new_host = update.message.reply_to_message.from_user
    new_host_id = new_host.id
    
    # Can't make self host if already host
    if new_host_id == match.host_id:
        await update.message.reply_text("⚠️ This player is already the Host!")
        return
    
    # Check if new host is in match
    if not (match.team_x.get_player(new_host_id) or match.team_y.get_player(new_host_id)):
        await update.message.reply_text("⚠️ This player is not in any team!")
        return
    
    # Initialize vote tracking for this candidate
    if new_host_id not in match.host_change_votes:
        match.host_change_votes[new_host_id] = {"x_voted": False, "y_voted": False}
    
    # Record vote
    votes = match.host_change_votes[new_host_id]
    
    if user.id == captain_x:
        if votes["x_voted"]:
            await update.message.reply_text("⚠️ Team X Captain already voted for this change!")
            return
        votes["x_voted"] = True
        voter_team = "Team X"
    else:
        if votes["y_voted"]:
            await update.message.reply_text("⚠️ Team Y Captain already voted for this change!")
            return
        votes["y_voted"] = True
        voter_team = "Team Y"
    
    new_host_tag = get_user_tag(new_host)
    
    # Check if both captains voted
    if votes["x_voted"] and votes["y_voted"]:
        # ✅ HOST CHANGE APPROVED
        old_host_id = match.host_id
        old_host_name = match.host_name
        
        match.host_id = new_host_id
        match.host_name = new_host.first_name
        
        # Clear votes
        match.host_change_votes = {}
        
        msg = f"👑 <b>HOST CHANGED!</b>\n"
        msg += f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        msg += f"🔄 <b>Old Host:</b> {old_host_name}\n"
        msg += f"✅ <b>New Host:</b> {new_host_tag}\n\n"
        msg += f"<i>Both captains approved this change.</i>"
        
        await update.message.reply_text(msg, parse_mode=ParseMode.HTML)
    else:
        # Waiting for second vote
        pending = "Team Y Captain" if not votes["y_voted"] else "Team X Captain"
        
        msg = f"🗳 <b>HOST CHANGE VOTE</b>\n"
        msg += f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        msg += f"📋 <b>Candidate:</b> {new_host_tag}\n"
        msg += f"✅ <b>{voter_team} Captain</b> voted YES\n"
        msg += f"⏳ <b>Waiting for:</b> {pending}\n\n"
        msg += f"<i>{pending}, reply to {new_host.first_name} with /changehost to approve.</i>"
        
        await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

async def changecap_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """👑 Unified Captain Change (Host Only) -> reply/arg then team picker"""
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in active_matches:
        await update.message.reply_text("🚫 No active match!", parse_mode=ParseMode.HTML)
        return
    match = active_matches[chat.id]

    if user.id != match.host_id:
        await update.message.reply_text("🚫 <b>HOST ONLY!</b> Only the host can change captains.", parse_mode=ParseMode.HTML)
        return

    # Check phase
    if match.phase not in [GamePhase.TEAM_EDIT, GamePhase.CAPTAIN_SELECTION, GamePhase.MATCH_IN_PROGRESS]:
        await update.message.reply_text("⚠️ Captain change not allowed in this phase.", parse_mode=ParseMode.HTML)
        return

    # Collect target user: reply or args
    target = None

    # 1. Reply target
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        ru = update.message.reply_to_message.from_user
        if not ru.is_bot:
            target = (ru.id, ru.username or "", ru.first_name or str(ru.id))

    # 2. Args target (@username or user_id)
    if not target and context.args:
        arg = context.args[0]
        if arg.startswith("@"):
            uname = arg[1:].lower()
            for uid, data in user_data.items():
                if data.get("username", "").lower() == uname:
                    target = (uid, data.get("username", ""), data.get("first_name", uname))
                    break
            if not target:
                try:
                    chat_obj = await context.bot.get_chat(arg)
                    target = (chat_obj.id, chat_obj.username or "", chat_obj.first_name or arg)
                except Exception:
                    pass
        elif arg.lstrip("-").isdigit():
            uid_int = int(arg)
            try:
                chat_obj = await context.bot.get_chat(uid_int)
                target = (chat_obj.id, chat_obj.username or "", chat_obj.first_name or str(uid_int))
            except Exception:
                target = (uid_int, "", str(uid_int))

    if not target:
        await update.message.reply_text(
            "ℹ️ <b>CHANGE CAPTAIN (Live Match)</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            "<b>Reply to a message:</b>  reply + <code>/changecap</code>\n"
            "<b>By username:</b>   <code>/changecap @user</code>\n"
            "<b>By user ID:</b>    <code>/changecap 12345</code>\n\n"
            "Bot will then ask which team they should captain.",
            parse_mode=ParseMode.HTML
        )
        return

    uid, uname, fname = target

    # Store pending in bot_data
    pending_key = f"changecappend_{chat.id}_{user.id}"
    context.bot_data[pending_key] = target

    keyboard = InlineKeyboardMarkup([[
        styled_button(f"{match.team_x.name}", callback_data=f"changecappick_X_{chat.id}_{user.id}"),
        styled_button(f"{match.team_y.name}", callback_data=f"changecappick_Y_{chat.id}_{user.id}"),
    ]])

    await update.message.reply_text(
        f"🧢 <b>CHANGE CAPTAIN — CHOOSE TEAM</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"👤 Target: <b>{html.escape(fname)}</b>\n\n"
        f"👇 Which team should they lead?",
        parse_mode=ParseMode.HTML,
        reply_markup=keyboard
    )


async def changecappick_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle team picker for /changecap command"""
    query = update.callback_query
    await query.answer()
    user = query.from_user
    parts = query.data.split("_")
    # changecappick_X_chatid_userid
    if len(parts) < 4:
        await query.answer(plain_alert("❌ Invalid data."), show_alert=True)
        return
    team_letter = parts[1]
    try:
        chat_id = int(parts[2])
        host_id = int(parts[3])
    except (ValueError, IndexError):
        await query.answer(plain_alert("❌ Invalid data."), show_alert=True)
        return

    if user.id != host_id:
        await query.answer(plain_alert("🚫 Only the host can pick the team captain!"), show_alert=True)
        return

    if chat_id not in active_matches:
        await query.message.edit_text("❌ No active match.", parse_mode=ParseMode.HTML)
        return
    match = active_matches[chat_id]
    team = match.team_x if team_letter == "X" else match.team_y
    other_team = match.team_y if team_letter == "X" else match.team_x

    pending_key = f"changecappend_{chat_id}_{host_id}"
    target = context.bot_data.pop(pending_key, None)

    if not target:
        await query.message.edit_text("⚠️ Session expired. Please use /changecap again.", parse_mode=ParseMode.HTML)
        return

    uid, uname, fname = target

    # Ensure player in database — 🔒 only if they've started the bot
    if uid not in user_data and await check_user_started_bot(context.bot, uid):
        user_data[uid] = {
            "user_id": uid, "username": uname, "first_name": fname,
            "started_at": datetime.now().isoformat(), "total_matches": 0
        }
        init_player_stats(uid)
        save_data()

    # Move player if in other team
    player = other_team.get_player(uid)
    if player:
        other_team.remove_player(uid)  # ✅ FIX: safe removal (keeps batsman/bowler indices in sync)
        if other_team.captain_id == uid:
            other_team.captain_id = None

    # Get or add player in this team
    player = team.get_player(uid)
    if not player:
        player = Player(uid, uname, fname)
        team.add_player(player)

    # Set as Captain
    team.captain_id = uid

    await query.message.edit_text(
        f"✅ <b>CAPTAIN UPDATED → TEAM {team_letter} ({html.escape(team.name)})</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"👑 Captain: <b>{html.escape(fname)}</b>\n"
        f"📊 Team size: <b>{len(team.players)}</b>\n\n"
        f"<i>Leadership updated by Host mid-game</i>",
        parse_mode=ParseMode.HTML
    )

async def change_captain_logic(update: Update, context: ContextTypes.DEFAULT_TYPE, team_name: str):
    """
    Unified Captain Change Logic
    """
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_matches:
        await update.message.reply_text("❌ No active match.")
        return
    
    match = active_matches[chat.id]
    
    # Only Host can change captains
    if user.id != match.host_id:
        await update.message.reply_text("🚫 Only the Host can change captains!")
        return
    
    # Check phase
    if match.phase not in [GamePhase.TEAM_EDIT, GamePhase.CAPTAIN_SELECTION, GamePhase.MATCH_IN_PROGRESS]:
        await update.message.reply_text("⚠️ Captain change not allowed in this phase.")
        return
    
    # Check if replied to someone
    if not update.message.reply_to_message:
        await update.message.reply_text(f"⚠️ Reply to the new captain of Team {team_name}.")
        return
    
    new_captain = update.message.reply_to_message.from_user
    new_captain_id = new_captain.id
    
    # Get team
    team = match.team_x if team_name == "X" else match.team_y
    
    # Check if player is in this team
    if not team.get_player(new_captain_id):
        await update.message.reply_text(f"⚠️ This player is not in Team {team_name}!")
        return
    
    # Check if already captain
    if team.captain_id == new_captain_id:
        await update.message.reply_text(f"⚠️ {new_captain.first_name} is already the captain!")
        return
    
    # Get old captain name
    old_captain = team.get_player(team.captain_id)
    old_captain_name = old_captain.first_name if old_captain else "None"
    
    # Change captain
    team.captain_id = new_captain_id
    
    new_captain_tag = get_user_tag(new_captain)
    
    msg = f"🧢 <b>CAPTAIN CHANGE - TEAM {team_name}</b>\n"
    msg += f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += f"🔄 <b>Old Captain:</b> {old_captain_name}\n"
    msg += f"✅ <b>New Captain:</b> {new_captain_tag}\n\n"
    msg += f"<i>Host has updated the leadership.</i>"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

async def impact_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ✅ FIXED: Impact Player with proper validation
    Usage: /impact @old_player @new_player
    or Reply to old player with: /impact @new_player
    """
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_matches:
        await update.message.reply_text("❌ No active match found.")
        return
    
    match = active_matches[chat.id]
    
    # Only during match
    if match.phase != GamePhase.MATCH_IN_PROGRESS:
        await update.message.reply_text("⚠️ Impact Player can only be used during the match!")
        return
    
    # Check if user is captain
    captain_x = match.team_x.captain_id
    captain_y = match.team_y.captain_id
    
    if user.id not in [captain_x, captain_y]:
        await update.message.reply_text("👮‍♂️ Only Captains can use Impact Player!")
        return
    
    # Determine captain's team
    if user.id == captain_x:
        team = match.team_x
        team_name = "Team X"
        impact_count = match.team_x_impact_count
        impact_history = match.team_x_impact_history
    else:
        team = match.team_y
        team_name = "Team Y"
        impact_count = match.team_y_impact_count
        impact_history = match.team_y_impact_history
    
    # ✅ Check if 3 uses exhausted
    if impact_count >= 3:
        await update.message.reply_text(
            f"🛑 <b>{team_name} has used all 3 Impact Players!</b>\n\n"
            f"📋 <b>Substitutions Made:</b>\n"
            f"{format_impact_history(impact_history)}",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Parse targets
    old_player_id = None
    new_player_id = None
    
    # Method 1: Reply + Mention
    if update.message.reply_to_message:
        old_player_id = update.message.reply_to_message.from_user.id
        
        # Get new player from mention
        if update.message.entities:
            for entity in update.message.entities:
                if entity.type == "mention":
                    username = update.message.text[entity.offset:entity.offset + entity.length].replace("@", "")
                    # Find user by username
                    for uid, data in user_data.items():
                        if data.get("username", "").lower() == username.lower():
                            new_player_id = uid
                            break
                elif entity.type == "text_mention":
                    new_player_id = entity.user.id
    
    # Method 2: Two Mentions
    elif update.message.entities and len([e for e in update.message.entities if e.type in ["mention", "text_mention"]]) >= 2:
        mentions = [e for e in update.message.entities if e.type in ["mention", "text_mention"]]
        
        # First mention = old player
        if mentions[0].type == "text_mention":
            old_player_id = mentions[0].user.id
        else:
            username = update.message.text[mentions[0].offset:mentions[0].offset + mentions[0].length].replace("@", "")
            for uid, data in user_data.items():
                if data.get("username", "").lower() == username.lower():
                    old_player_id = uid
                    break
        
        # Second mention = new player
        if mentions[1].type == "text_mention":
            new_player_id = mentions[1].user.id
        else:
            username = update.message.text[mentions[1].offset:mentions[1].offset + mentions[1].length].replace("@", "")
            for uid, data in user_data.items():
                if data.get("username", "").lower() == username.lower():
                    new_player_id = uid
                    break
    
    if not old_player_id or not new_player_id:
        remaining = 3 - impact_count
        await update.message.reply_text(
            f"ℹ️ <b>Usage:</b>\n"
            f"Reply to old player: <code>/impact @newplayer</code>\n"
            f"Or: <code>/impact @oldplayer @newplayer</code>\n\n"
            f"🔄 <b>Remaining Substitutions:</b> {remaining}/3",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Validate old player is in team
    old_player = team.get_player(old_player_id)
    if not old_player:
        await update.message.reply_text("🚫 Old player is not in your team!")
        return
    
    # Check if old player was already substituted out
    for old_name, new_name in impact_history:
        if old_name == old_player.first_name:
            await update.message.reply_text(
                f"🚫 <b>{old_player.first_name}</b> was already substituted out earlier!\n"
                f"You cannot substitute them again.",
                parse_mode=ParseMode.HTML
            )
            return
    
    # Check if old player is currently playing
    if team == match.current_batting_team:
        if team.current_batsman_idx is not None and team.players[team.current_batsman_idx].user_id == old_player_id:
            await update.message.reply_text("🏏 Cannot substitute the current striker!")
            return
        if team.current_non_striker_idx is not None and team.players[team.current_non_striker_idx].user_id == old_player_id:
            await update.message.reply_text("👟 Cannot substitute the current non-striker!")
            return
    
    if team == match.current_bowling_team:
        if team.current_bowler_idx is not None and team.players[team.current_bowler_idx].user_id == old_player_id:
            await update.message.reply_text("⚾ Cannot substitute the current bowler!")
            return
    
    # Check if new player is not already in match
    if match.team_x.get_player(new_player_id) or match.team_y.get_player(new_player_id):
        await update.message.reply_text("👥 New player is already in a team!")
        return
    
    # Initialize new player stats
    if new_player_id not in user_data:
        # Fetch user info
        try:
            new_user = await context.bot.get_chat(new_player_id)
            user_data[new_player_id] = {
                "user_id": new_player_id,
                "username": new_user.username or "",
                "first_name": new_user.first_name,
                "started_at": datetime.now().isoformat(),
                "total_matches": 0
            }
            init_player_stats(new_player_id)
            save_data()
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 26099)")
            await update.message.reply_text("📡 Cannot fetch new player info. Make sure they've started the bot.")
            return
    
    new_user_info = user_data[new_player_id]
    
    # Create new player object
    new_player = Player(new_player_id, new_user_info["username"], new_user_info["first_name"])
    
    # Replace in team
    for i, p in enumerate(team.players):
        if p.user_id == old_player_id:
            team.players[i] = new_player
            break
    
    # ✅ Update impact tracking
    if user.id == captain_x:
        match.team_x_impact_count += 1
        match.team_x_impact_history.append((old_player.first_name, new_player.first_name))
        remaining = 3 - match.team_x_impact_count
    else:
        match.team_y_impact_count += 1
        match.team_y_impact_history.append((old_player.first_name, new_player.first_name))
        remaining = 3 - match.team_y_impact_count
    
    old_tag = f'<a href=\"tg://user?id={old_player_id}\">{html.escape(old_player.first_name)}</a>' + _title_suffix(old_player_id)
    new_tag = get_user_tag(type("User", (), {"id": new_player_id, "first_name": new_user_info["first_name"]}))
    
    msg = f"🔄 <b>IMPACT PLAYER - {team_name}</b>\n"
    msg += f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    msg += f"🔴 <b>OUT:</b> {old_tag}\n"
    msg += f"🟢 <b>IN:</b> {new_tag}\n\n"
    msg += f"📊 <b>Substitutions Used:</b> {impact_count + 1}/3\n"
    msg += f"⏳ <b>Remaining:</b> {remaining}\n\n"
    msg += f"💡 <i>Strategic substitution made!</i>"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

def format_impact_history(history: list) -> str:
    """Format impact player history for display"""
    if not history:
        return "<i>No substitutions made yet</i>"
    
    result = ""
    for i, (old, new) in enumerate(history, 1):
        result += f"  {i}. {old} ➡️ {new}\n"
    return result

async def impactstatus_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Check Impact Player Status
    Shows remaining substitutions for both teams
    """
    chat = update.effective_chat
    
    if chat.id not in active_matches:
        await update.message.reply_text("❌ No active match.")
        return
    
    match = active_matches[chat.id]
    
    # Team X Status
    x_used = match.team_x_impact_count
    x_remaining = 3 - x_used
    x_history = format_impact_history(match.team_x_impact_history)
    
    # Team Y Status
    y_used = match.team_y_impact_count
    y_remaining = 3 - y_used
    y_history = format_impact_history(match.team_y_impact_history)
    
    msg = f"🔄 <b>IMPACT PLAYER STATUS</b>\n"
    msg += f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
    
    msg += f"🧊 <b>Team X</b>\n"
    msg += f"📊 Used: <b>{x_used}/3</b> | Remaining: <b>{x_remaining}</b>\n"
    msg += f"📋 History:\n{x_history}\n\n"
    
    msg += f"🔥 <b>Team Y</b>\n"
    msg += f"📊 Used: <b>{y_used}/3</b> | Remaining: <b>{y_remaining}</b>\n"
    msg += f"📋 History:\n{y_history}\n\n"
    
    msg += f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

async def resetmatch_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle /resetmatch command - Owner only"""
    user = update.effective_user
    
    # Check if owner
    if not has_power(user.id, "match"):
        await update.message.reply_text(
            "This command is restricted to the bot owner."
        )
        return
    
    chat = update.effective_chat
    
    if chat.id not in active_matches:
        await update.message.reply_text("No active match in this group.")
        return
    
    match = active_matches[chat.id]
    
    # Cancel all tasks
    if match.join_phase_task:
        match.join_phase_task.cancel()
    if match.ball_timeout_task:
        match.ball_timeout_task.cancel()
    if match.batsman_selection_task:
        match.batsman_selection_task.cancel()
    if match.bowler_selection_task:
        match.bowler_selection_task.cancel()
    
    # Reset match to team joining phase
    del active_matches[chat.id]
    
    await update.message.reply_text(
        "Match has been reset by bot owner.\n"
        "Use /game to start a new match."
    )
    
    logger.info(f"Match in group {chat.id} reset by owner")

# Error handler
async def error_handler(update: object, context: ContextTypes.DEFAULT_TYPE):
    """Log errors and notify user"""
    logger.error(f"Exception while handling an update: {context.error}")

    # ── Flood control: Telegram is rate-limiting the bot ──
    if isinstance(context.error, RetryAfter):
        try:
            retry_after = getattr(context.error, "retry_after", None) or 5
            effective_chat = getattr(update, "effective_chat", None) if update else None
            flood_chat_id = effective_chat.id if effective_chat else None
            flood_chat_title = (
                html.escape(effective_chat.title or effective_chat.first_name or str(effective_chat.id))
                if effective_chat else "Unknown chat"
            )

            # Notify support group with where the flood happened
            try:
                await context.bot.send_message(
                    chat_id=SUPPORT_GROUP_ID,
                    text=(
                        "🌊 <b>BOT FLOODED!</b>\n"
                        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                        f"📍 <b>Chat:</b> {flood_chat_title}\n"
                        f"🆔 <b>Chat ID:</b> <code>{flood_chat_id}</code>\n"
                        f"⏱ <b>Retry After:</b> {retry_after}s\n"
                        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                        "<i>Telegram rate-limited the bot in this chat. "
                        "Cooling down automatically.</i>"
                    ),
                    parse_mode=ParseMode.HTML
                )
            except Exception as e:
                logger.error(f"Failed to notify support group about flood: {e}")

            # Let the affected chat know to slow down, but don't spam it
            if flood_chat_id is not None:
                now = time.time()
                if now - flood_warned_chats[flood_chat_id] > FLOOD_WARNING_COOLDOWN:
                    flood_warned_chats[flood_chat_id] = now
                    try:
                        await asyncio.sleep(min(retry_after, 5))
                        await context.bot.send_message(
                            chat_id=flood_chat_id,
                            text=(
                                "⚠️ <b>Whoa, slow down a little!</b>\n"
                                "Too many actions were sent too quickly and Telegram "
                                "briefly paused the bot's messages here.\n"
                                "🙏 <i>Please use the commands/buttons calmly, one at a "
                                "time, and everything will keep working smoothly.</i>"
                            ),
                            parse_mode=ParseMode.HTML
                        )
                    except Exception as e:
                        logger.error(f"Failed to send flood notice to chat {flood_chat_id}: {e}")
        except Exception as e:
            logger.error(f"Error while handling RetryAfter flood: {e}")
        return

    # ── Filter out known-benign Telegram noise so owner DMs aren't spammed ──
    # These happen routinely (stale callback buttons, race conditions on
    # edits, unescaped user-supplied text in a caption) and are already
    # harmless no-ops from Telegram's side — they don't need a DM per hit.
    _err_str = str(context.error)
    _benign_markers = (
        "Query is too old",                      # stale inline-button tap, nothing to fix
        "Message is not modified",                # duplicate edit_message_text with identical content
        "message is not modified",
        "Can't parse entities",                   # unescaped '<'/'>'/'&' in HTML-mode text — see note below
    )
    if any(marker in _err_str for marker in _benign_markers):
        logger.warning(f"Suppressed benign Telegram error (not DMing owner): {_err_str}")
        return

    # Notify owner about error
    try:
        error_text = f"An error occurred:\n\n{_err_str}"
        await context.bot.send_message(
            chat_id=OWNER_ID,
            text=error_text
        )
    except Exception as e:
        logger.error(f"Failed to notify owner about error: {e}")

