def _gcsettings_keyboard(group_id: int, drs_on: bool, wide_on: bool, solo_wide_on: bool, commentary: str, lobby_time: int, lobby_timer_on: bool = False) -> list:
    """Builds the aligned 2-column GC settings keyboard: [LABEL] [VALUE] per row."""
    commentary_short = {
        "english": "ENGLISH",
        "hinglish": "HINGLISH",
        "tamil": "TAMIL",
        "bengali": "BENGALI",
    }.get(commentary, "ENGLISH")
    lobby_minutes = max(1, round(lobby_time / 60))
    rows = [
        [
            styled_button("DRS:", callback_data=f"gcs_drs_{group_id}"),
            styled_button("ON" if drs_on else "OFF ❌", callback_data=f"gcs_drs_{group_id}"),
        ],
        [
            styled_button("WIDE:", callback_data=f"gcs_wide_{group_id}"),
            styled_button("ON" if wide_on else "OFF ❌", callback_data=f"gcs_wide_{group_id}"),
        ],
        [
            styled_button("SOLO WIDE:", callback_data=f"gcs_solowide_{group_id}"),
            styled_button("ON" if solo_wide_on else "OFF ❌", callback_data=f"gcs_solowide_{group_id}"),
        ],
        [
            styled_button("COMMENTARY:", callback_data=f"gcs_comm_{group_id}"),
            styled_button(commentary_short, callback_data=f"gcs_comm_{group_id}"),
        ],
        # 🔧 Lobby timer is OFF by default per group; this toggle turns it on/off.
        [
            styled_button("⏱ LOBBY TIMER:", callback_data=f"gcs_lobbytimer_{group_id}"),
            styled_button("ON" if lobby_timer_on else "OFF ❌", callback_data=f"gcs_lobbytimer_{group_id}"),
        ],
    ]
    # Only show the duration adjuster once the timer is actually turned on —
    # no point letting admins tune a duration for a timer that's off.
    if lobby_timer_on:
        rows.append([
            styled_button("⏱ LOBBY DURATION:", callback_data=f"gcs_lobby_{group_id}"),
            styled_button(f"{lobby_minutes} MIN", callback_data=f"gcs_lobby_{group_id}"),
        ])
    rows.append([
        styled_button("CLOSE", callback_data=f"gcs_close_{group_id}"),
    ])
    return rows


async def gcsettings_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle gcsettings button callbacks"""
    query = update.callback_query
    await query.answer()
    
    data = query.data
    user = query.from_user
    
    # Parse group_id from callback data
    parts = data.split("_")
    group_id = int(parts[-1])
    
    # Verify admin
    try:
        member = await context.bot.get_chat_member(group_id, user.id)
        is_admin = member.status in ["creator", "administrator"]
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 27501)")
        is_admin = False
    
    if not is_admin and user.id != OWNER_ID:
        await query.answer(plain_alert("❌ Only admins can change settings!"), show_alert=True)
        return
    
    if data == f"gcs_close_{group_id}":
        try:
            await query.message.delete()
        except Exception:
            pass
        return
    
    # Ensure settings exist
    if group_id not in gc_settings:
        gc_settings[group_id] = {"drs_enabled": False, "commentary_style": "english", "wide_enabled": True, "lobby_time": 120, "solo_wide_enabled": True, "lobby_timer_enabled": False}
    
    LOBBY_STEPS = [60, 120, 180, 240]  # 1/2/3/4 min, cycles

    if data == f"gcs_drs_{group_id}":
        gc_settings[group_id]["drs_enabled"] = not gc_settings[group_id].get("drs_enabled", False)
    elif data == f"gcs_wide_{group_id}":
        gc_settings[group_id]["wide_enabled"] = not gc_settings[group_id].get("wide_enabled", True)
    elif data == f"gcs_solowide_{group_id}":
        gc_settings[group_id]["solo_wide_enabled"] = not gc_settings[group_id].get("solo_wide_enabled", True)
    elif data == f"gcs_comm_{group_id}":
        styles = ["english", "hinglish", "tamil", "bengali"]
        current = gc_settings[group_id].get("commentary_style", "english")
        try:
            new_style = styles[(styles.index(current) + 1) % len(styles)]
        except ValueError:
            new_style = styles[0]
        gc_settings[group_id]["commentary_style"] = new_style
        # Also update registered_groups for backward compat
        if group_id in registered_groups:
            registered_groups[group_id]["commentary_style"] = new_style
    elif data == f"gcs_lobbytimer_{group_id}":
        # 🔧 Lobby timer is OFF by default per group; admins opt in here.
        gc_settings[group_id]["lobby_timer_enabled"] = not gc_settings[group_id].get("lobby_timer_enabled", False)
    elif data == f"gcs_lobby_{group_id}":
        current = gc_settings[group_id].get("lobby_time", 120)
        try:
            next_idx = (LOBBY_STEPS.index(current) + 1) % len(LOBBY_STEPS)
        except ValueError:
            next_idx = 0
        gc_settings[group_id]["lobby_time"] = LOBBY_STEPS[next_idx]
    
    save_gc_setting(group_id)
    
    # Rebuild message
    drs_on = gc_settings[group_id].get("drs_enabled", False)
    wide_on = gc_settings[group_id].get("wide_enabled", True)
    solo_wide_on = gc_settings[group_id].get("solo_wide_enabled", True)
    commentary = gc_settings[group_id].get("commentary_style", "english")
    lobby_time = gc_settings[group_id].get("lobby_time", 120)
    lobby_timer_on = gc_settings[group_id].get("lobby_timer_enabled", False)
    
    commentary_display = {"english": "🇬🇧 English", "hinglish": "🇮🇳 Hinglish Special"}.get(commentary, "🇬🇧 English")
    lobby_line = (
        f"⏱️ <b>Lobby Timer:</b> {'✅ ON' if lobby_timer_on else '❌ OFF'}"
        f"{f' ({lobby_time}s)' if lobby_timer_on else ''}\n"
    )
    
    try:
        chat_title = query.message.chat.title or "This Group"
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 27545)")
        chat_title = "This Group"
    
    text = themed(
        "GC SETTINGS",
        [
            f"🏟️ <b>{html.escape(chat_title)}</b>",
            f"📺 DRS: {'✅ Enabled' if drs_on else '❌ Disabled'}",
            f"🌀 Wide Ball (Team): {'✅ Enabled' if wide_on else '❌ Disabled'}",
            f"🎲 Wide Ball (Solo): {'✅ Enabled' if solo_wide_on else '❌ Disabled'}",
            f"🎙️ Commentary: {commentary_display}",
            lobby_line.rstrip(),
            "✅ Setting updated. Tap to change again.",
        ],
        "⚙️",
    )
    
    keyboard = _gcsettings_keyboard(group_id, drs_on, wide_on, solo_wide_on, commentary, lobby_time, lobby_timer_on)
    
    try:
        await query.edit_message_caption(caption=text, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(keyboard))
    except Exception:
        try:
            await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(keyboard))
        except Exception as e:
            logger.error(f"gcsettings_callback edit error: {e}")


async def broadcastpin_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    📌 BROADCAST + PIN TO GROUPS
    Usage: Reply to ANY message with /broadcastpin
    Bot forwards and pins it in all groups
    """
    user = update.effective_user
    if not has_power(user.id, "broadcast"):
        return

    if not update.message.reply_to_message:
        await update.message.reply_text(
            "⚠️ <b>Usage:</b> Reply to any message with <code>/broadcastpin</code>\n\n"
            "Bot will forward and PIN that message to all groups.",
            parse_mode=ParseMode.HTML
        )
        return

    target_message = update.message.reply_to_message
    
    status_msg = await update.message.reply_text(
        "📢 <b>BROADCAST + PIN STARTED</b>\n"
        "⏳ <i>Forwarding & pinning to all groups...</i>",
        parse_mode=ParseMode.HTML
    )
    
    success = 0
    failed = 0
    pinned = 0
    
    for chat_id in list(registered_groups.keys()):
        if chat_id in banned_groups:
            failed += 1
            continue
            
        try:
            # Forward message
            sent_msg = await context.bot.forward_message(
                chat_id=chat_id,
                from_chat_id=target_message.chat_id,
                message_id=target_message.message_id
            )
            success += 1
            
            # Try to pin
            try:
                await context.bot.pin_chat_message(
                    chat_id=chat_id,
                    message_id=sent_msg.message_id,
                    disable_notification=False
                )
                pinned += 1
            except Exception as pin_error:
                logger.warning(f"Could not pin in {chat_id}: {pin_error}")
            
            await asyncio.sleep(0.05)
        except Exception as e:
            failed += 1
            logger.error(f"Failed broadcast to group {chat_id}: {e}")

    report = (
        "✅ <b>BROADCAST + PIN COMPLETE!</b>\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n\n"
        "📊 <b>GROUPS</b>\n"
        f"   ✅ Sent: <code>{success}</code>\n"
        f"   📌 Pinned: <code>{pinned}</code>\n"
        f"   ❌ Failed: <code>{failed}</code>\n"
        f"   🚫 Banned: <code>{len(banned_groups)}</code>\n"
        f"   📊 Total: <code>{len(registered_groups)}</code>\n\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
    )
    
    await status_msg.edit_text(report, parse_mode=ParseMode.HTML)


