async def endauction_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """End the auction (host/admin only)"""
    
    if update.effective_chat.type == "private":
        await update.message.reply_text("❌ Use this in a group!")
        return

    group_id = update.effective_chat.id
    user_id = update.effective_user.id
    
    auction = active_auctions.get(group_id)
    
    if not auction:
        await update.message.reply_text("❌ No active auction to end!")
        return
    
    try:
        member = await update.effective_chat.get_member(user_id)
        is_admin = member.status in ["creator", "administrator"]
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 27743)")
        is_admin = False
    
    is_auctioneer = (user_id == auction.auctioneer_id)
    
    if not is_auctioneer:
        await update.message.reply_text("❌ Only the Auctioneer can conclude the auction!")
        return
    
    if auction.bid_timer_task:
        auction.bid_timer_task.cancel()
        auction.bid_timer_task = None
    
    sold_count = len(auction.sold_players)
    remaining_count = len(auction.player_pool)
    unsold_count = len(auction.unsold_players)

    confirm_kb = InlineKeyboardMarkup([[
        styled_button("Yes, End Auction", callback_data=f"confirm_endauction_{group_id}"),
        styled_button("Cancel", callback_data="cancel_endauction")
    ]])

    await update.message.reply_text(
        f"🏁 <b>END AUCTION?</b>\n\n"
        f"✅ Sold: <b>{sold_count}</b>  |  ❌ Unsold: <b>{unsold_count}</b>  |  ⏳ Remaining: <b>{remaining_count}</b>\n\n"
        f"Are you sure you want to officially end the auction?\n"
        f"<i>The auction can still continue if you cancel.</i>",
        parse_mode=ParseMode.HTML,
        reply_markup=confirm_kb
    )

ENDMATCH_VOTE_SECONDS = 120
_endmatch_vote_locks: Dict[int, asyncio.Lock] = {}


def _endmatch_vote_text(vote: dict, yes_count: int, no_count: int, total: int, needed: int) -> str:
    left = max(0, int(vote.get("expires_at", 0) - time.time()))
    return themed("END MATCH VOTE", [
        f"🗳 {yes_count} Yes / {no_count} No — need {needed}/{total} Yes",
        f"⏳ Closes in {left}s",
        "Only players currently in this match can vote.",
    ], emoji="⚠️")


def _endmatch_vote_kb() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[
        styled_button("Yes, End Match", callback_data="endmatch_vote_yes"),
        styled_button("No, Continue", callback_data="endmatch_vote_no"),
    ]])


async def _endmatch_vote_expire(bot, group_id: int, vote: dict):
    """Auto-close a vote nobody finished, so it can never block /endmatch forever."""
    try:
        await asyncio.sleep(ENDMATCH_VOTE_SECONDS)
        if active_endmatch_votes.get(group_id) is not vote:
            return
        active_endmatch_votes.pop(group_id, None)
        try:
            await bot.edit_message_text(
                chat_id=group_id, message_id=vote.get("message_id"),
                text=themed("VOTE EXPIRED", [
                    f"🗳 {len(vote['yes'])} Yes / {len(vote['no'])} No — not enough votes",
                    "Match continues!",
                ], emoji="⌛"),
                parse_mode=ParseMode.HTML)
        except Exception:
            pass
    except asyncio.CancelledError:
        pass


async def endmatch_vote_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Yes/No buttons of the admin-started /endmatch vote (>=50% of players must say Yes)."""
    query = update.callback_query
    group_id = update.effective_chat.id
    user_id = update.effective_user.id
    data = query.data

    lock = _endmatch_vote_locks.setdefault(group_id, asyncio.Lock())
    async with lock:
        vote = active_endmatch_votes.get(group_id)
        match = active_matches.get(group_id)

        # stale / wrong message / match gone or replaced
        if (not vote or not match or vote.get("match_ref") is not match
                or (query.message and vote.get("message_id") not in (None, query.message.message_id))):
            if vote and (not match or vote.get("match_ref") is not match):
                active_endmatch_votes.pop(group_id, None)
            await query.answer(plain_alert("⚠️ This vote has ended."), show_alert=True)
            try:
                await query.edit_message_reply_markup(reply_markup=None)
            except Exception:
                pass
            return

        eligible = _get_match_player_ids(match)      # live list: players who left don't count
        if user_id not in eligible:
            await query.answer(plain_alert("❌ Only players currently in this match can vote!"), show_alert=True)
            return

        vote["yes"].discard(user_id)
        vote["no"].discard(user_id)
        (vote["yes"] if data == "endmatch_vote_yes" else vote["no"]).add(user_id)
        vote["yes"] &= eligible
        vote["no"] &= eligible

        total = len(eligible)
        needed = max(1, math.ceil(total / 2))
        yes_count, no_count = len(vote["yes"]), len(vote["no"])
        await query.answer("✅ Vote recorded!")      # answered exactly ONCE

        if yes_count >= needed:
            active_endmatch_votes.pop(group_id, None)
            if vote.get("task"):
                vote["task"].cancel()
            resume_code = save_match_for_resume(match, group_id, match.group_name, match.host_id)
            match.phase = GamePhase.MATCH_ENDED
            for _attr in ('ball_timeout_task', 'batsman_selection_task', 'bowler_selection_task',
                          'join_phase_task', 'solo_timer_task', 'pause_task', 'active_ball_task'):
                _t = getattr(match, _attr, None)
                if _t:
                    _t.cancel()
            try:
                if match.main_message_id:
                    await context.bot.unpin_chat_message(chat_id=group_id, message_id=match.main_message_id)
            except Exception:
                pass
            active_matches.pop(group_id, None)
            processing_commands.pop(group_id, None)

            init_name = None
            if vote.get("initiator"):
                init_name = user_data.get(vote["initiator"], {}).get("first_name")
            lines = [
                f"🗳 Vote passed: {yes_count}/{total} players voted Yes",
                "👤 𝗘𝗻𝗱𝗲𝗱 𝗯𝘆: Group vote" + (f" (started by {html.escape(init_name)})" if init_name else ""),
                "❌ Stats were NOT saved.",
            ]
            if resume_code:
                lines.append(f"🔑 Resume: /regame {resume_code}")
            lines.append("🎮 Use /game to start a new match!")
            try:
                await query.edit_message_text(themed("MATCH ENDED BY VOTE", lines, "🛑"), parse_mode=ParseMode.HTML)
            except Exception:
                pass
            return

        if no_count > total - needed:                 # can no longer pass
            active_endmatch_votes.pop(group_id, None)
            if vote.get("task"):
                vote["task"].cancel()
            try:
                await query.edit_message_text(
                    themed("VOTE FAILED", [f"🗳 {yes_count} Yes / {no_count} No (needed {needed}/{total})",
                                           "Match continues!"], emoji="❌"),
                    parse_mode=ParseMode.HTML)
            except Exception:
                pass
            return

        try:
            await query.edit_message_text(
                _endmatch_vote_text(vote, yes_count, no_count, total, needed),
                parse_mode=ParseMode.HTML, reply_markup=_endmatch_vote_kb())
        except Exception:
            pass


async def end_confirmation_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    
    data = query.data
    group_id = update.effective_chat.id
    user_id = update.effective_user.id
    
    # ==========================================
    # ✅ ENDMATCH CONFIRMATION (NO STATS SAVED)
    # ==========================================
    if data == "confirm_endmatch":
        match = active_matches.get(group_id)
        if not match:
            await query.edit_message_text("❌ No active match found.")
            return

        # 🩹 BUGFIX: this was hard "HOST-ONLY (no admin/owner bypass)", which
        # silently broke endmatch_command's own documented behavior — a
        # non-host group admin ending the match in a pre-first-ball phase
        # (joining/toss/team-edit/etc.) would be shown this exact "Yes, End
        # Match" button, then get rejected the moment they tapped it. Use
        # the same eligibility rule endmatch_command already enforced when
        # it decided to show this dialog in the first place.
        if not await _endmatch_can_direct_end(context, group_id, user_id, match):
            await query.answer(plain_alert("❌ Only the match host (or an admin, before the first ball) can end the match!"), show_alert=True)
            return
        
        # 💾 RESUME SNAPSHOT: save BEFORE mutating phase/state, so /regame
        # restores the exact in-progress state. Only for mid-game force-stops
        # (no result/winner declared) — never for a naturally completed match.
        resume_code = save_match_for_resume(match, group_id, match.group_name, match.host_id)

        # 🔐 CANCEL ALL TASKS
        match.phase = GamePhase.MATCH_ENDED
        
        if hasattr(match, 'ball_timeout_task') and match.ball_timeout_task:
            match.ball_timeout_task.cancel()
        if hasattr(match, 'batsman_selection_task') and match.batsman_selection_task:
            match.batsman_selection_task.cancel()
        if hasattr(match, 'bowler_selection_task') and match.bowler_selection_task:
            match.bowler_selection_task.cancel()
        if hasattr(match, 'join_phase_task') and match.join_phase_task:
            match.join_phase_task.cancel()
        # 🔧 GLITCH FIX: also cancel solo timer / pause-resume / in-flight ball task
        if hasattr(match, 'solo_timer_task') and match.solo_timer_task:
            match.solo_timer_task.cancel()
        if hasattr(match, 'pause_task') and match.pause_task:
            match.pause_task.cancel()
        if hasattr(match, 'active_ball_task') and match.active_ball_task:
            match.active_ball_task.cancel()
        
        # Unpin message
        try:
            if match.main_message_id:
                await context.bot.unpin_chat_message(
                    chat_id=group_id, 
                    message_id=match.main_message_id
                )
        except Exception as e:
            logger.debug(f"Could not unpin message: {e}")
        
        # Generate summary image (optional, no stats saved)
        if match.game_mode == "TEAM":
            try:
                if match.current_batting_team and match.current_bowling_team:
                    if match.current_batting_team.score > match.current_bowling_team.score:
                        winner_team = match.current_batting_team
                    else:
                        winner_team = match.current_bowling_team
                    
                    bio = await generate_team_end_image_v3(match, winner_team.name, context)
                    if bio:
                        await context.bot.send_photo(
                            chat_id=group_id,
                            photo=bio,
                            caption=f"🏏 {match.group_name} - Match Ended (Stats Not Saved) 🏏"
                        )
            except Exception as e:
                logger.error(f"Error generating team end image: {e}")
        
        # ❌ DELETE MATCH (NO STATS SAVED)
        if group_id in active_matches:
            del active_matches[group_id]
        if group_id in processing_commands:
            del processing_commands[group_id]

        # 🚫 ENDMATCH STRIKE: host force-ended without completing the match
        try:
            _em_result = record_endmatch_strike(user_id)
            if _em_result:
                await _dm_endmatch_strike_notice(context, user_id, _em_result["strike_count"], _em_result["ban_until"], _em_result["duration"])
            else:
                await _dm_endmatch_strike_notice(context, user_id, get_endmatch_strike_count(user_id))
        except Exception as e:
            logger.error(f"endmatch strike tracking failed: {e}")

        _me_lines = [
            "⚠️ 𝗦𝘁𝗮𝘁𝘂𝘀: Match was forcefully stopped!",
            f"👤 𝗘𝗻𝗱𝗲𝗱 𝗯𝘆: {html.escape(update.effective_user.first_name)}",
            "❌ 𝗗𝗮𝘁𝗮𝗯𝗮𝘀𝗲: Stats were NOT saved.",
        ]
        if resume_code:
            _me_lines.append(f"🔑 𝗥𝗲𝘀𝘂𝗺𝗲: /regame {resume_code}")
        _me_lines.append("🎮 Use /game to start a new match!")
        await query.edit_message_text(
            themed("🛑 MATCH ENDED", _me_lines, "🛑"),
            parse_mode=ParseMode.HTML
        )
        return
    
    # ==========================================
    # ✅ ENDMATCH CONFIRMATION
    # ==========================================
    if data.startswith("confirm_endmatch_"):
        chat_id = int(data.split("_")[2])
        
        if chat_id not in active_matches:
            await query.message.edit_text("⚠️ Match already ended.")
            return
        
        match = active_matches[chat_id]

        # 🩹 BUGFIX: same issue as bare confirm_endmatch — was hard host-only.
        if not await _endmatch_can_direct_end(context, chat_id, user_id, match):
            await query.answer(plain_alert("❌ Only the match host (or an admin, before the first ball) can end the match!"), show_alert=True)
            return
        
        # 💾 RESUME SNAPSHOT: before state mutation, mid-game force-stop only.
        resume_code = save_match_for_resume(match, chat_id, match.group_name, match.host_id)

        # 🔐 TRIPLE LOCK MECHANISM
        match.phase = GamePhase.MATCH_ENDED
        
        if match.ball_timeout_task: match.ball_timeout_task.cancel()
        if match.batsman_selection_task: match.batsman_selection_task.cancel()
        if match.bowler_selection_task: match.bowler_selection_task.cancel()
        if hasattr(match, 'join_phase_task') and match.join_phase_task: 
            match.join_phase_task.cancel()
        # 🔧 GLITCH FIX: also cancel solo timer / pause-resume / in-flight ball task
        if hasattr(match, 'solo_timer_task') and match.solo_timer_task:
            match.solo_timer_task.cancel()
        if hasattr(match, 'pause_task') and match.pause_task:
            match.pause_task.cancel()
        if hasattr(match, 'active_ball_task') and match.active_ball_task:
            match.active_ball_task.cancel()
        
        try:
            if match.main_message_id:
                await context.bot.unpin_chat_message(chat_id=chat_id, message_id=match.main_message_id)
        except: pass
        
        del active_matches[chat_id]

        # 🚫 ENDMATCH STRIKE: host force-ended without completing the match
        try:
            _em_result = record_endmatch_strike(user_id)
            if _em_result:
                await _dm_endmatch_strike_notice(context, user_id, _em_result["strike_count"], _em_result["ban_until"], _em_result["duration"])
            else:
                await _dm_endmatch_strike_notice(context, user_id, get_endmatch_strike_count(user_id))
        except Exception as e:
            logger.error(f"endmatch strike tracking failed: {e}")

        # 🎬 DONE MESSAGE (removed animation URL fetch that fails on some servers)
        _me2_lines = [
            "⚠️ 𝗦𝘁𝗮𝘁𝘂𝘀: Match was forcefully stopped!",
            f"👤 𝗘𝗻𝗱𝗲𝗱 𝗯𝘆: {html.escape(update.effective_user.first_name)}",
        ]
        if resume_code:
            _me2_lines.append(f"🔑 𝗥𝗲𝘀𝘂𝗺𝗲: /regame {resume_code}")
        _me2_lines.append("🎮 Use /game to start again!")
        await query.message.reply_text(
            themed("🏁 MATCH ENDED", _me2_lines, "🏁"),
            parse_mode=ParseMode.HTML
        )

        return
    
    # ==========================================
    # ❌ CANCEL ENDMATCH (single handler)
    # ==========================================
    elif data == "cancel_endmatch":
        await query.edit_message_text(
            "▶ <b>Match Continues!</b>\nGame is still active — play on! ⚡",
            parse_mode=ParseMode.HTML
        )

    # ==========================================
    # ✅ ENDSOLO CONFIRMATION (NO STATS SAVED)
    # ==========================================
    elif data.startswith("confirm_endsolo_"):
        chat_id = int(data.split("_")[2])
        
        if chat_id not in active_matches:
            await query.edit_message_text("⚠️ Solo match already ended.")
            return
        
        match = active_matches[chat_id]

        # 🩹 BUGFIX: same issue as confirm_endmatch — was hard host-only,
        # contradicting endmatch_command's documented pre-first-ball admin
        # exception (SOLO_JOINING is one of the PRE_FIRST_BALL_PHASES).
        if not await _endmatch_can_direct_end(context, chat_id, user_id, match):
            await query.answer(plain_alert("❌ Only the match host (or an admin, before the first ball) can end the match!"), show_alert=True)
            return
        
        # 💾 RESUME SNAPSHOT: before state mutation, mid-game force-stop only.
        resume_code = save_match_for_resume(match, chat_id, match.group_name, match.host_id)

        # 🔐 CANCEL ALL TASKS
        match.phase = GamePhase.MATCH_ENDED
        
        if hasattr(match, 'ball_timeout_task') and match.ball_timeout_task:
            match.ball_timeout_task.cancel()
        if hasattr(match, 'solo_timer_task') and match.solo_timer_task:
            match.solo_timer_task.cancel()
        if hasattr(match, 'join_phase_task') and match.join_phase_task:
            match.join_phase_task.cancel()
        # 🔧 GLITCH FIX: cancel any in-flight ball/turn processing coroutine too,
        # otherwise process_solo_turn_result keeps running after /endmatch and the
        # solo game appears to continue even though it was "ended".
        if hasattr(match, 'active_ball_task') and match.active_ball_task:
            match.active_ball_task.cancel()
        if hasattr(match, 'pause_task') and match.pause_task:
            match.pause_task.cancel()
        
        # Unpin message
        try:
            if match.main_message_id:
                await context.bot.unpin_chat_message(
                    chat_id=chat_id,
                    message_id=match.main_message_id
                )
        except Exception as e:
            logger.debug(f"Could not unpin message: {e}")
        
        # Generate summary image (optional, no stats saved)
        try:
            sorted_players = sorted(match.solo_players, key=lambda x: x.runs, reverse=True)
            if sorted_players:
                _bowled = [p for p in match.solo_players if getattr(p, "balls_bowled", 0) > 0]
                _best_bowler = sorted(_bowled, key=lambda p: (-p.wickets, getattr(p, "runs_conceded", 0)))[0] if _bowled else None
                await generate_solo_top_performers_image(sorted_players[0], _best_bowler, context)

        except Exception as e:
            logger.error(f"Error generating solo end image: {e}")
        
        # ❌ DELETE MATCH (NO STATS SAVED)
        if chat_id in active_matches:
            del active_matches[chat_id]
        if chat_id in processing_commands:
            del processing_commands[chat_id]

        # 🚫 ENDMATCH STRIKE: host force-ended without completing the match
        try:
            _em_result = record_endmatch_strike(user_id)
            if _em_result:
                await _dm_endmatch_strike_notice(context, user_id, _em_result["strike_count"], _em_result["ban_until"], _em_result["duration"])
            else:
                await _dm_endmatch_strike_notice(context, user_id, get_endmatch_strike_count(user_id))
        except Exception as e:
            logger.error(f"endmatch strike tracking failed: {e}")

        _sme_lines = [
            "⚠️ 𝗦𝘁𝗮𝘁𝘂𝘀: Match was forcefully stopped!",
            f"👤 𝗘𝗻𝗱𝗲𝗱 𝗯𝘆: {html.escape(update.effective_user.first_name)}",
            "❌ 𝗗𝗮𝘁𝗮𝗯𝗮𝘀𝗲: Stats were NOT saved.",
        ]
        if resume_code:
            _sme_lines.append(f"🔑 𝗥𝗲𝘀𝘂𝗺𝗲: /regame {resume_code}")
        _sme_lines.append("🎮 Use /game to start a new match!")
        await query.edit_message_text(
            themed("🏁 SOLO MATCH ENDED", _sme_lines, "🏁"),
            parse_mode=ParseMode.HTML
        )
        return

    # ==========================================
    # ❌ CANCEL ENDSOLO
    # ==========================================
    elif data == "cancel_endsolo":
        await query.message.edit_text(
            "▶ <b>Solo Battle Continues!</b>\nFight on! ⚔️",
            parse_mode=ParseMode.HTML
        )

    # ==========================================
    # ✅ ENDAUCTION CONFIRMATION
    # ==========================================
    elif data.startswith("confirm_endauction_"):
        chat_id = int(data.split("_")[2])
        
        if chat_id not in active_auctions:
            await query.message.edit_text("⚠️ Auction already ended.")
            return
        
        auction = active_auctions[chat_id]

        if query.from_user.id != auction.auctioneer_id:
            await query.answer(plain_alert("🚫 Only the Auctioneer can conclude the auction!"), show_alert=True)
            return

        _capture_pre_end_blob(chat_id, auction, overwrite=True)   # 🧊 exact pre-conclude state
        auction.phase = AuctionPhase.AUCTION_ENDED
        
        if auction.bid_timer_task:
            auction.bid_timer_task.cancel()

        # ✅ FIX: Use reply_text instead of reply_animation (URL fetch fails on some servers)
        try:
            await query.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass
        await query.message.reply_text(
            "🏁 <b>Ending Auction...</b>\n📊 Generating final summary...",
            parse_mode=ParseMode.HTML
        )

        await asyncio.sleep(1)
        await end_auction(context, chat_id, auction)
        return

    # ==========================================
    # ❌ CANCEL ENDAUCTION
    # ==========================================
    elif data == "cancel_endauction":
        await query.message.edit_text(
            "▶ <b>Auction Continues!</b>\nBidding still active — go on! 💸",
            parse_mode=ParseMode.HTML
        )


async def get_all_file_ids(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.message
    file_id = None
    media_type = None

    # --- LIST OF CHECKS ---
    
    # 1. Photo (Yeh list hoti hai, last wali best quality)
    if msg.photo:
        file_id = msg.photo[-1].file_id
        media_type = "📸 Photo"

    # 2. GIF (Animation)
    elif msg.animation:
        file_id = msg.animation.file_id
        media_type = "🎞️ GIF"

    # 3. Video
    elif msg.video:
        file_id = msg.video.file_id
        media_type = "🎥 Video"

    # 4. Document (Files/Zip/Pdf)
    elif msg.document:
        file_id = msg.document.file_id
        media_type = "📁 Document"

    # 5. Audio (Songs/MP3)
    elif msg.audio:
        file_id = msg.audio.file_id
        media_type = "🎵 Audio"

    # 6. Voice Note
    elif msg.voice:
        file_id = msg.voice.file_id
        media_type = "🎤 Voice Note"

    # 7. Sticker
    elif msg.sticker:
        file_id = msg.sticker.file_id
        media_type = "🤡 Sticker"
        
    # 8. Video Note (Gol wala video)
    elif msg.video_note:
        file_id = msg.video_note.file_id
        media_type = "🟣 Video Note"

    # --- RESULT ---
    if file_id:
        await msg.reply_text(
            f"<b>{media_type} Detect hua!</b>\n\n🆔 <b>File ID:</b>\n<code>{file_id}</code>",
            parse_mode=ParseMode.HTML
        )
    else:
        # Agar user ne sirf text likha ho
        await msg.reply_text("Bhai text mat bhejo, koi Media (Photo/GIF/File) bhejo.")

