async def scorecard_refresh_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔄 Refresh scorecard from inline button"""
    query = update.callback_query
    await query.answer(plain_alert("🔄 Refreshing..."), show_alert=False)
    try:
        group_id = int(query.data.split("_")[-1])
    except Exception:
        group_id = update.effective_chat.id

    match = active_matches.get(group_id)
    if not match:
        await query.answer(plain_alert("❌ No active match!"), show_alert=True)
        return

    def _bat_line(pl, team):
        _sr = round((pl.runs / max(pl.balls_faced, 1)) * 100, 1)
        not_out = "*" if not pl.is_out and pl.balls_faced > 0 else ""
        return f"👤 {html.escape(pl.first_name[:16])}{not_out} — {pl.runs} ({pl.balls_faced}b) · SR {_sr}"

    def _bowl_line(pl):
        if pl.balls_bowled == 0:
            return ""
        _ov = format_overs(pl.balls_bowled)
        _econ = round(pl.runs_conceded / max(pl.balls_bowled / 6, 0.1), 2)
        return f"👤 {html.escape(pl.first_name[:16])} — {pl.wickets}/{pl.runs_conceded} ({_ov}) · Eco {_econ}"

    def _inn_block(bat_team, bowl_team, inn_label, inn_num):
        rr = round(bat_team.score / (bat_team.balls / 6), 2) if bat_team.balls > 0 else 0
        extras = bat_team.extras if hasattr(bat_team, 'extras') else 0
        inn_ordinal = "1st" if inn_num == "1st" else "2nd"
        lines = [
            f"🏆 {inn_ordinal} innings — <b>{html.escape(bat_team.name)}</b>",
            f"📊 Score: <b>{bat_team.score}/{bat_team.wickets}</b> ({format_overs(bat_team.balls)} ov) · RR {rr}",
            f"⚖️ Extras: {extras}",
            "🏏 <b>BATTING</b>",
        ]
        batters = [p for p in bat_team.players if p.balls_faced > 0 or p.is_out]
        lines.extend(_bat_line(pl, bat_team) for pl in batters)
        if not batters:
            lines.append("No batting data yet.")
        lines.append("🥎 <b>BOWLING</b>")
        bowlers = [p for p in bowl_team.players if p.balls_bowled > 0]
        lines.extend(_bowl_line(pl) for pl in bowlers)
        if not bowlers:
            lines.append("No bowlers yet.")
        return "\n".join(lines)

    first  = match.batting_first or match.team_x
    second = match.team_y if first == match.team_x else match.team_x

    now = datetime.now().strftime("%d %b %Y  %H:%M")
    text = themed("CRICOVERSE SCORECARD", [], "📊") + "\n"

    text += _inn_block(first, second, "1ST", "1st")
    if match.innings >= 2:
        if match.target > 0:
            _nd = match.target - second.score
            _bl = (match.total_overs * 6) - second.balls
            _rr = round(_nd / (_bl / 6), 2) if _bl > 0 else 0
            text += f"🎯 Target: {match.target} Runs\n"
        text += _inn_block(second, first, "2nd Innings", "2nd")
    if match.current_partnership_runs > 0:
        text += f"🤝 <b>Partnership:</b> {match.current_partnership_runs}({match.current_partnership_balls})\n"
    text += "\n👉 Tap Refresh for latest scores!"

    refresh_kb = InlineKeyboardMarkup([[
        styled_button("Refresh Scorecard", callback_data=f"scorecard_refresh_{group_id}")
    ]])

    # Telegram caption limit is 1024 chars; if longer, truncate with note
    display_text = text if len(text) <= 1024 else _safe_truncate_html(text, 1024, suffix="\n<i>…use /scorecard for full view</i>")

    try:
        await query.edit_message_caption(caption=display_text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb)
    except Exception:
        try:
            await query.edit_message_text(text=display_text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb)
        except Exception:
            await query.answer(plain_alert("✅ Already up to date!"), show_alert=False)


async def evr_reaction_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🎉 Handle wicket/four/six/fifty/century/hatrick reaction taps — tracks
    per-player totals for the end-of-match DM, tracks the top reactor, bumps
    the live +N count shown on the button, fires a Crowd Favourite! group
    alert at 10 taps, and quietly adds a small fantasy + all-time bonus."""
    query = update.callback_query
    user = query.from_user
    data = query.data  # evr_{ecode}_{poolchar}{idx}_{player_id}_{group_id}

    try:
        _, ecode, pool_idx, pid_str, gid_str = data.split("_", 4)
        event_key = _EVENT_CODE_MAP_REV.get(ecode)
        pool_name = "genuine" if pool_idx[0] == "g" else "poke"
        idx = int(pool_idx[1:])
        player_id = int(pid_str)
        group_id = int(gid_str)
        emoji, label = EVENT_REACTIONS[event_key][pool_name][idx]
    except Exception:
        await query.answer(plain_alert("⚠️ This reaction has expired."), show_alert=False)
        return

    msg = query.message

    # 🙋 One reaction per user per message
    msg_key = f"{msg.chat_id}_{msg.message_id}"
    reacted_users = _EVENT_REACTION_MSG_USERS.setdefault(msg_key, set())
    if user.id in reacted_users:
        await query.answer(plain_alert("🙅 You've already reacted to this!"), show_alert=False)
        return
    reacted_users.add(user.id)

    match = active_matches.get(group_id)

    reaction_key = f"{emoji} {label}"
    if match:
        reactions = getattr(match, "event_reactions", None)
        if reactions is None:
            reactions = {}
            match.event_reactions = reactions
        player_totals = reactions.setdefault(player_id, {})
        player_totals[reaction_key] = player_totals.get(reaction_key, 0) + 1

        # 🏅 Track who reacted the most to this player (for the top-reactor DM line)
        reactors = getattr(match, "event_reactors", None)
        if reactors is None:
            reactors = {}
            match.event_reactors = reactors
        player_reactors = reactors.setdefault(player_id, {})
        entry = player_reactors.setdefault(user.id, {"name": user.first_name, "count": 0})
        entry["count"] += 1
        entry["name"] = user.first_name

        player_obj = None
        for team in (getattr(match, "team_x", None), getattr(match, "team_y", None)):
            if not team:
                continue
            for p in team.players:
                if p.user_id == player_id:
                    player_obj = p
                    break
            if player_obj:
                break
        if player_obj:
            award_fantasy_reaction(match, player_obj)

    # 🌐 All-time reactions-received bump (feeds /lb)
    try:
        await asyncio.to_thread(_bump_reactions_received_db, player_id)
    except Exception as e:
        logger.warning(f"reaction DB bump failed: {e}")

    # 🔢 Bump this specific button's live tap count and redraw the row
    tap_key = f"{msg.chat_id}_{msg.message_id}_{pool_idx}"
    new_count = _EVENT_REACTION_TAP_COUNTS.get(tap_key, 0) + 1
    _EVENT_REACTION_TAP_COUNTS[tap_key] = new_count
    try:
        old_row = msg.reply_markup.inline_keyboard[0]
        new_row = []
        for b in old_row:
            try:
                _, b_ecode, b_pool_idx, b_pid, b_gid = b.callback_data.split("_", 4)
            except Exception:
                new_row.append(b)
                continue
            b_pool_name = "genuine" if b_pool_idx[0] == "g" else "poke"
            b_idx = int(b_pool_idx[1:])
            b_emoji, b_label = EVENT_REACTIONS[_EVENT_CODE_MAP_REV.get(b_ecode)][b_pool_name][b_idx]
            b_count = _EVENT_REACTION_TAP_COUNTS.get(f"{msg.chat_id}_{msg.message_id}_{b_pool_idx}", 0)
            new_row.append(styled_button(
                _event_reaction_button_label(b_emoji, b_label, b_count),
                callback_data=b.callback_data,
                style="success" if b_pool_idx[0] == "g" else "danger",
                small_caps=False,
            ))
        await query.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup([new_row]))
    except Exception as e:
        logger.warning(f"evr reaction button redraw failed: {e}")

    # 🔥 Crowd Favourite! milestone alert — fires once, first time a single
    # button crosses the threshold.
    if new_count >= EVENT_REACTION_CROWD_FAVOURITE_THRESHOLD and tap_key not in _EVENT_REACTION_MILESTONE_FIRED:
        _EVENT_REACTION_MILESTONE_FIRED.add(tap_key)
        try:
            player_tag = f'<a href="tg://user?id={player_id}">Player</a>'
            if match:
                for team in (getattr(match, "team_x", None), getattr(match, "team_y", None)):
                    if not team:
                        continue
                    for p in team.players:
                        if p.user_id == player_id:
                            player_tag = f'<a href="tg://user?id={player_id}">{html.escape(p.first_name)}</a>'
                            break
            await context.bot.send_message(
                group_id,
                f"🔥 <b>Crowd Favourite!</b>\n{emoji} <b>{label}</b> has crossed {new_count} reactions for {player_tag}!",
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.warning(f"Crowd Favourite alert failed: {e}")

    await query.answer(f"{emoji} {label} → {user.first_name}", show_alert=False)


