async def tourlb_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle tournament leaderboard tab switches + pagination (Next/Previous/Back)"""
    query = update.callback_query
    await query.answer()
    # Format: tourlb_{group_id}_{metric}_{page}  (page defaults to 0 if omitted, for backward-compat)
    parts = query.data.split("_")
    if len(parts) < 3:
        return
    try:
        gid = int(parts[1])
    except Exception:
        gid = update.effective_chat.id
    metric = parts[2]
    try:
        page = int(parts[3]) if len(parts) >= 4 else 0
    except Exception:
        page = 0

    try:
        _rb, _rr = await asyncio.to_thread(_build_tourlb_page, gid, metric, page, True)
        await rc_edit_or_send(query, _rb, _rr)
        return
    except Exception:
        logger.exception("rich tourlb callback failed — using legacy view")

    text, kb = _build_tourlb_page(gid, metric, page)

    try:
        await query.edit_message_caption(caption=text, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 29784)")
        try:
            await query.edit_message_text(text=text, parse_mode=ParseMode.HTML, reply_markup=kb)
        except Exception:
            pass


