async def fantasy_pick_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Toggle a player in/out of the tapping user's Fantasy Dream III."""
    query = update.callback_query
    user = query.from_user
    data = query.data  # fpick_{group_id}_{player_user_id}

    try:
        _, gid_str, pid_str = data.split("_", 2)
        group_id = int(gid_str)
        player_id = int(pid_str)
    except Exception:
        await query.answer(plain_alert("⚠️ Invalid selection."), show_alert=True)
        return

    match = active_matches.get(group_id)
    if not match or match.game_mode not in ("TEAM", "TOURNAMENT"):
        await query.answer(plain_alert("⚠️ This fantasy window is no longer active."), show_alert=True)
        return

    if not getattr(match, "fantasy_window_open", False) or match.phase != GamePhase.FANTASY_PICK:
        await query.answer("⏰ Fantasy squad picks are locked — the toss has already started!", show_alert=True)
        return

    pool = match.team_x.players + match.team_y.players
    player_obj = next((p for p in pool if p.user_id == player_id), None)
    if not player_obj:
        await query.answer(plain_alert("⚠️ That player isn't part of this match."), show_alert=True)
        return

    cap = get_fantasy_squad_cap(match)
    squad = match.fantasy_squads.setdefault(user.id, {
        "name": user.first_name, "players": [], "match_points": 0, "log": []
    })
    squad["name"] = user.first_name

    if player_id in squad["players"]:
        squad["players"].remove(player_id)
        await query.answer(f"➖ Removed {player_obj.first_name}. ({len(squad['players'])}/{cap})")
    else:
        if len(squad["players"]) >= cap:
            await query.answer(plain_alert(f"🚫 Your Dream III is full ({cap}/{cap})! Remove someone first."), show_alert=True)
            return
        squad["players"].append(player_id)
        await query.answer(plain_alert(f"✅ Added {player_obj.first_name}! ({len(squad['players'])}/{cap})"))


async def fantasy_mysquad_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show the tapping user their current Dream III picks via popup alert."""
    query = update.callback_query
    user = query.from_user
    data = query.data  # fmysquad_{group_id}
    try:
        group_id = int(data.split("_", 1)[1])
    except Exception:
        await query.answer()
        return

    match = active_matches.get(group_id)
    if not match:
        await query.answer(plain_alert("⚠️ No active match."), show_alert=True)
        return

    squad = match.fantasy_squads.get(user.id)
    if not squad or not squad.get("players"):
        await query.answer("📭 You haven't picked anyone yet! Tap player names to build your Dream III.", show_alert=True)
        return

    pool = match.team_x.players + match.team_y.players
    names = [p.first_name for p in pool if p.user_id in squad["players"]]
    cap = get_fantasy_squad_cap(match)
    await query.answer(f"Your Dream III ({len(names)}/{cap}): " + ", ".join(names), show_alert=True)


async def mysquad_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show the caller's fantasy Dream III for the active match in this chat."""
    chat_id = update.effective_chat.id
    user = update.effective_user
    match = active_matches.get(chat_id)
    if not match or match.game_mode not in ("TEAM", "TOURNAMENT"):
        await update.message.reply_text("⚠️ No Team/Tournament match with fantasy squads active here.")
        return

    squad = getattr(match, "fantasy_squads", {}).get(user.id)
    if not squad or not squad.get("players"):
        await update.message.reply_text("📭 You haven't picked your Fantasy Dream III yet! Tap a player in the fantasy message above to build your squad.")
        return

    pool = match.team_x.players + match.team_y.players
    picked = [p for p in pool if p.user_id in squad["players"]]
    cap = get_fantasy_squad_cap(match)

    def _pad(s, w):
        s = html.escape(str(s))
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))

    def _rpad(s, w):
        # 🔧 FIX: was undefined here — every /mysquad call crashed with NameError
        s = str(s)
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else (" " * (w - len(s))) + s

    header = f"{_pad('Rank', 5)}{_pad('Player', 14)}{_pad('Role', 12)}{_rpad('Points', 8)}\n"
    table = header + ("-" * 31) + "\n"
    for i, p in enumerate(picked, 1):
        role = compute_player_role(p.user_id)
        pts = squad.get("match_points", 0)
        table += f"{_pad(i, 5)}{_pad(p.first_name, 14)}{_pad(role, 12)}{_rpad(pts, 8)}\n"

    status_line = (
        "🔓 Picks are still <b>OPEN</b> — tap more players above."
        if getattr(match, "fantasy_window_open", False) and match.phase == GamePhase.TOSS
        else f"🔒 Picks are <b>LOCKED</b> · {squad.get('match_points', 0)} pts this match."
    )
    msg = themed("YOUR FANTASY DREAM XI", [
        f"📊 Squad size: <b>{len(picked)}/{cap}</b>",
        status_line,
    ], "🏆") + f"\n\n<pre>{table}</pre>"
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)


def _fantasylb_ranked(limit: int = 15):
    ranked = sorted(fantasy_data.items(), key=lambda kv: kv[1].get("points", 0), reverse=True)
    return [r for r in ranked if r[1].get("points", 0) > 0][:limit]


def _build_fantasylb_rich_html(ranked) -> str:
    """CCC-style sendRichMessage HTML: a real collapsible <details><table>
    dropdown instead of a plain <pre> text grid."""
    trs = ""
    for i, (uid, d) in enumerate(ranked):
        title_key = d.get("title")
        title_info = get_fantasy_title_info(title_key) if title_key else None
        role = title_info['name'] if title_info else "Manager"
        name = html.escape((d.get('first_name') or 'Player')[:16])
        trs += (
            f"<tr><td align='center'>{i + 1}</td>"
            f"<td>{name}</td>"
            f"<td>{html.escape(role)}</td>"
            f"<td align='right'>{d.get('points', 0):,}</td></tr>"
        )
    table = (
        "<table bordered striped>"
        "<tr><th>#️⃣</th><th>🧢 Player</th><th>🎽 Role</th><th>💰 Points</th></tr>"
        f"{trs}</table>"
    )
    return (
        "<h3>🏆 FANTASY DREAM XI — GLOBAL LEADERBOARD</h3>"
        "<details><summary>📊 Top Managers</summary>"
        f"{table}</details>"
        "<footer>🛍️ /shop — spend cricoins on a title 🎮</footer>"
    )


def _build_fantasylb_fallback_text(ranked) -> str:
    """Plain-text fallback if sendRichMessage isn't supported."""
    def _pad(s, w):
        s = html.escape(str(s))
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))

    def _rpad(s, w):
        s = str(s)
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else (" " * (w - len(s))) + s

    header = f"{_pad('Rank', 5)}{_pad('Player', 15)}{_pad('Role', 12)}{_rpad('Points', 8)}\n"
    table = header + ("-" * 40) + "\n"
    for i, (uid, d) in enumerate(ranked):
        title_key = d.get("title")
        title_info = get_fantasy_title_info(title_key) if title_key else None
        role = title_info['name'] if title_info else "Manager"
        table += f"{_pad(i + 1, 5)}{_pad(d.get('first_name', 'Player'), 15)}{_pad(role, 12)}{_rpad(d.get('points', 0), 8)}\n"

    msg = themed("FANTASY DREAM XI — GLOBAL LEADERBOARD", [
        "📊 Top managers by all-time fantasy points.",
        "🛍️ Use <code>/shop</code> to spend cricoins on a title.",
    ], "🏆")
    msg += f"\n\n<blockquote expandable><pre>{table}</pre></blockquote>"
    return msg


async def _legacy_fantasylb_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show the global, all-time Fantasy Dream III leaderboard as a CCC-style
    expandable native table (sendRichMessage), falling back to a plain
    expandable text table if Rich Messages aren't supported."""
    ranked = _fantasylb_ranked()

    if not ranked:
        await update.message.reply_text(
            themed("NO FANTASY POINTS YET", [
                "Play a Team or Tournament match and pick your Dream III before the toss.",
            ], "📭"),
            parse_mode=ParseMode.HTML
        )
        return

    chat_id = update.effective_chat.id
    html_content = _build_fantasylb_rich_html(ranked)
    ok = await _tg_send_rich_message(chat_id, html_content)

    if not ok:
        fallback = _build_fantasylb_fallback_text(ranked)
        await update.message.reply_text(fallback, parse_mode=ParseMode.HTML)


async def fantasydiscount_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """👑 Owner-only: /fantasydiscount <percent> <hours> — run a limited-time Fantasy Shop sale.
    /fantasydiscount off — cancel an active sale early."""
    user = update.effective_user
    if not has_power(user.id, "system"):
        await update.message.reply_text("🚫 Owner only command!")
        return

    if not context.args:
        active = get_active_discount_percent()
        if active > 0:
            remaining = int(FANTASY_DISCOUNT["expires_at"] - time.time())
            hrs, mins = divmod(max(remaining, 0) // 60, 60)
            await update.message.reply_text(
                f"🔥 Active sale: <b>{active}% OFF</b>, ends in {hrs}h {mins}m.\n"
                f"Usage: <code>/fantasydiscount [percent] [hours]</code> or <code>/fantasydiscount off</code>",
                parse_mode=ParseMode.HTML
            )
        else:
            await update.message.reply_text(
                "ℹ️ No active sale.\n"
                "Usage: <code>/fantasydiscount [percent] [hours]</code>\n"
                "Example: <code>/fantasydiscount 20 24</code> — 20% off for 24 hours",
                parse_mode=ParseMode.HTML
            )
        return

    if context.args[0].lower() == "off":
        FANTASY_DISCOUNT["percent"] = 0
        FANTASY_DISCOUNT["expires_at"] = 0
        await update.message.reply_text("🛑 Fantasy Shop sale cancelled.")
        return

    try:
        percent = int(context.args[0])
        hours = float(context.args[1]) if len(context.args) > 1 else 24
    except (ValueError, IndexError):
        await update.message.reply_text("❌ Usage: <code>/fantasydiscount [percent] [hours]</code>", parse_mode=ParseMode.HTML)
        return

    if not (1 <= percent <= 90):
        await update.message.reply_text("❌ Percent must be between 1 and 90.")
        return
    if hours <= 0:
        await update.message.reply_text("❌ Hours must be greater than 0.")
        return

    FANTASY_DISCOUNT["percent"] = percent
    FANTASY_DISCOUNT["expires_at"] = time.time() + hours * 3600

    await update.message.reply_text(
        f"🔥 <b>Fantasy Shop Sale Activated!</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🏷️ <b>{percent}% OFF</b> all titles\n"
        f"⏱️ Ends in <b>{hours:g} hours</b>\n"
        f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"Use /shop to grab the deal!",
        parse_mode=ParseMode.HTML
    )


def _render_fantasyshop_page(user_id: int, idx: int):
    """Build the (text, keyboard) for one title-shop page. idx is the
    position in FANTASY_TITLES, cheapest first."""
    idx = max(0, min(idx, len(FANTASY_TITLES) - 1))
    t = FANTASY_TITLES[idx]
    profile = fantasy_data.get(user_id, {})
    bal = profile.get("points", 0)
    owned = profile.get("titles_owned", [])
    equipped = profile.get("title")
    discount_pct = get_active_discount_percent()
    disc_price = get_discounted_price(t["price"])

    lines = [f"💰 <b>Your Balance:</b> {fmt_coins(bal)}\n"]
    if discount_pct > 0:
        remaining = int(FANTASY_DISCOUNT["expires_at"] - time.time())
        hrs, mins = divmod(max(remaining, 0) // 60, 60)
        lines.append(f"🔥 <b>{discount_pct}% OFF</b> — ends in {hrs}h {mins}m!\n")

    title_display = f"{_title_emoji_tag(t['key'])} <b>{t['name']}</b>"
    status = ""
    if t["key"] in owned:
        status = " ✅ Owned"
        if equipped == t["key"]:
            status += " 🟢 Equipped"
    if discount_pct > 0:
        price_line = f"<s>{fmt_coins(t['price'])}</s> <b>{fmt_coins(disc_price)}</b>"
    else:
        price_line = f"<b>{fmt_coins(t['price'])}</b>"

    lines.append(f"{title_display}{status}")
    lines.append(f"Price: {price_line}")

    # 🖼️ Demo preview — shows exactly how the buyer's name will look
    # everywhere in the bot (scorecards, /mystats, etc.) once this title
    # is equipped, so the emoji's appeal is obvious before buying.
    preview_name = html.escape(profile.get("first_name") or "You")
    lines.append(f"\n👉 <b>Preview after buying:</b>")
    lines.append(f"{preview_name} {_title_emoji_tag(t['key'])}")

    lines.append(f"\n<i>Tier {idx + 1} / {len(FANTASY_TITLES)}</i>")

    nav_row = []
    if idx > 0:
        nav_row.append(styled_button("Back", callback_data=f"fshop_page_{idx - 1}"))
    if t["key"] not in owned:
        nav_row.append(styled_button(f"Buy ({disc_price:,})", callback_data=f"fbuytitle_{t['key']}"))
    elif equipped != t["key"]:
        nav_row.append(styled_button("Equip", callback_data=f"fequiptitle_{t['key']}"))
    if idx < len(FANTASY_TITLES) - 1:
        nav_row.append(styled_button("Next", callback_data=f"fshop_page_{idx + 1}"))

    keyboard = [nav_row, [styled_button("Close", callback_data="fshop_close")]]
    msg = themed("🛍️ FANTASY TITLE SHOP", lines, "👑")
    return msg, InlineKeyboardMarkup(keyboard)


async def shop_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show the CricoVerse title shop — buy titles using accumulated cricoins, one tier at a time."""
    user = update.effective_user
    init_fantasy_data(user.id, user.first_name, user.username or "")
    save_data()
    msg, reply_markup = _render_fantasyshop_page(user.id, 0)
    photo = MEDIA_ASSETS.get("shop")
    try:
        if photo and os.path.exists(photo):
            await update.message.reply_photo(photo=photo, caption=msg, parse_mode=ParseMode.HTML, reply_markup=reply_markup)
        else:
            await update.message.reply_text(msg, parse_mode=ParseMode.HTML, reply_markup=reply_markup)
    except Exception:
        logger.exception("shop_command: failed to send photo, falling back to text")
        await update.message.reply_text(msg, parse_mode=ParseMode.HTML, reply_markup=reply_markup)


async def fantasyshop_page_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Back/Next pagination and Close in the fantasy shop."""
    query = update.callback_query
    user = query.from_user
    init_fantasy_data(user.id, user.first_name, user.username or "")
    if query.data == "fshop_close":
        await query.answer()
        try:
            await query.message.delete()
        except Exception:
            pass
        return
    idx = int(query.data.split("_")[-1])
    msg, reply_markup = _render_fantasyshop_page(user.id, idx)
    await query.answer()
    try:
        if query.message.photo:
            await query.edit_message_caption(caption=msg, parse_mode=ParseMode.HTML, reply_markup=reply_markup)
        else:
            await query.edit_message_text(msg, parse_mode=ParseMode.HTML, reply_markup=reply_markup)
    except Exception:
        pass


async def fantasy_buytitle_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Purchase a fantasy title with accumulated fantasy points."""
    query = update.callback_query
    user = query.from_user
    key = query.data.split("_", 1)[1]
    title = get_fantasy_title_info(key)
    if not title:
        await query.answer(plain_alert("⚠️ Unknown title."), show_alert=True)
        return

    init_fantasy_data(user.id, user.first_name)
    profile = fantasy_data[user.id]

    if key in profile.get("titles_owned", []):
        await query.answer(plain_alert("✅ You already own this title!"), show_alert=True)
        return
    final_price = get_discounted_price(title["price"])
    if profile.get("points", 0) < final_price:
        short = final_price - profile.get("points", 0)
        await query.answer(plain_alert(f"🚫 Not enough cricoins! You need {fmt_coins(short)} more."), show_alert=True)
        return

    profile["points"] -= final_price
    profile.setdefault("titles_owned", []).append(key)
    profile["title"] = key  # auto-equip the newest purchase, attributed to this buyer
    save_data()

    await query.answer(plain_alert(f"🎉 Purchased {title['name']}!"), show_alert=True)
    idx = FANTASY_TITLES.index(title)
    msg, reply_markup = _render_fantasyshop_page(user.id, idx)
    try:
        if query.message.photo:
            await query.edit_message_caption(caption=msg, parse_mode=ParseMode.HTML, reply_markup=reply_markup)
        else:
            await query.edit_message_text(msg, parse_mode=ParseMode.HTML, reply_markup=reply_markup)
    except Exception:
        pass


async def fantasy_equiptitle_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Equip an already-owned fantasy title so it shows on /fantasylb."""
    query = update.callback_query
    user = query.from_user
    key = query.data.split("_", 1)[1]
    init_fantasy_data(user.id, user.first_name)
    profile = fantasy_data[user.id]
    if key not in profile.get("titles_owned", []):
        await query.answer(plain_alert("⚠️ You don't own this title yet."), show_alert=True)
        return
    profile["title"] = key
    save_data()
    title = get_fantasy_title_info(key)
    await query.answer(plain_alert(f"🎽 Equipped {title['name']}!"), show_alert=True)
    idx = FANTASY_TITLES.index(title)
    msg, reply_markup = _render_fantasyshop_page(user.id, idx)
    try:
        if query.message.photo:
            await query.edit_message_caption(caption=msg, parse_mode=ParseMode.HTML, reply_markup=reply_markup)
        else:
            await query.edit_message_text(msg, parse_mode=ParseMode.HTML, reply_markup=reply_markup)
    except Exception:
        pass



# ═══════════════════════════════════════════════════════════════
# CCC RATING & RANKING SYSTEM
# ═══════════════════════════════════════════════════════════════
CCC_MIN_MATCHES = 5

def classify_player_category(runs: int, wickets: int, matches: int, balls_faced: int, balls_bowled: int) -> str:
    """Fallback single-player classifier (used only when a pool-wide classification
    isn't available, e.g. a tiny player base). Prefer classify_players_pool for the
    real target composition of ~45% Batsman / 35% Bowler / 20% All-Rounder."""
    if matches < CCC_MIN_MATCHES:
        return "Batsman"  # default for unqualified
    runs_per_match = runs / max(matches, 1)
    wickets_per_match = wickets / max(matches, 1)
    # Thresholds
    BAT_THRESHOLD = 8    # avg 8+ runs/match = batting contributor
    BOWL_THRESHOLD = 0.5  # avg 0.5+ wickets/match = bowling contributor
    is_bat = runs_per_match >= BAT_THRESHOLD
    is_bowl = wickets_per_match >= BOWL_THRESHOLD
    if is_bat and is_bowl:
        return "All-Rounder"
    elif is_bowl and not is_bat:
        return "Bowler"
    return "Batsman"


# 🎯 Target composition across the whole qualified player pool. Real games tend to
# have way fewer genuine bowlers/all-rounders than batsmen, so instead of fixed
# absolute thresholds (which used to let too many people qualify as All-Rounder
# and starve the Bowler category), we rank the WHOLE pool by batting vs bowling
# strength and slice it into these target shares — e.g. for 100 qualified players:
# 45 Batsman, 35 Bowler, 20 All-Rounder.
CCC_TARGET_SHARE_BAT = 0.45
CCC_TARGET_SHARE_BOWL = 0.35
CCC_TARGET_SHARE_AR = 0.20


def classify_players_pool(rows: list) -> dict:
    """
    Classify an entire pool of qualified players into Batsman / Bowler / All-Rounder
    at once, targeting the CCC_TARGET_SHARE_* composition (roughly 45/35/20).

    rows: list of dicts each containing user_id, matches, runs, wickets,
          balls_faced, balls_bowled (only qualified players, matches >= CCC_MIN_MATCHES).

    Returns: {user_id: category_str}
    """
    if not rows:
        return {}

    n = len(rows)

    # Too small a pool for percentile slicing to mean anything → fall back to the
    # simple per-player threshold classifier so a 2-3 player group still gets a
    # sensible category each.
    if n < 8:
        return {
            r["user_id"]: classify_player_category(
                r.get("runs", 0), r.get("wickets", 0), r.get("matches", 0),
                r.get("balls_faced", 0), r.get("balls_bowled", 0)
            )
            for r in rows
        }

    enriched = []
    for r in rows:
        matches = max(r.get("matches", 0), 1)
        bat_score = r.get("runs", 0) / matches
        bowl_score = r.get("wickets", 0) / matches
        enriched.append({**r, "bat_score": bat_score, "bowl_score": bowl_score})

    def _norm(vals):
        lo, hi = min(vals), max(vals)
        span = (hi - lo) or 1.0
        return [(v - lo) / span for v in vals]

    bat_norm = _norm([e["bat_score"] for e in enriched])
    bowl_norm = _norm([e["bowl_score"] for e in enriched])
    for e, bn, wn in zip(enriched, bat_norm, bowl_norm):
        e["bat_norm"] = bn
        e["bowl_norm"] = wn
        # "All-rounder-ness" = how strong they are in whichever of the two
        # disciplines they're WEAKER in — a true all-rounder needs both.
        e["ar_score"] = min(bn, wn)

    ar_target = max(round(n * CCC_TARGET_SHARE_AR), 0)
    enriched_by_ar = sorted(enriched, key=lambda e: (-e["ar_score"], -e["matches"], e["user_id"]))
    ar_ids = {e["user_id"] for e in enriched_by_ar[:ar_target]}

    remaining = [e for e in enriched if e["user_id"] not in ar_ids]
    bat_target = max(round(n * CCC_TARGET_SHARE_BAT), 0)

    remaining_sorted = sorted(remaining, key=lambda e: (-(e["bat_norm"] - e["bowl_norm"]), -e["matches"], e["user_id"]))
    bat_ids = {e["user_id"] for e in remaining_sorted[:bat_target]}

    result = {}
    for e in enriched:
        if e["user_id"] in ar_ids:
            result[e["user_id"]] = "All-Rounder"
        elif e["user_id"] in bat_ids:
            result[e["user_id"]] = "Batsman"
        else:
            result[e["user_id"]] = "Bowler"
    return result

def resolve_player_name(user_id: int, fallback_name: Optional[str] = None) -> str:
    """Always get real first_name from user_data if available, never default to 'Player' if user_data has a name."""
    try:
        uid_int = int(user_id)
    except (ValueError, TypeError):
        return fallback_name or "Player"
    u_info = user_data.get(uid_int) or user_data.get(str(uid_int)) or {}
    fn = u_info.get("first_name")
    if fn and fn.strip() and fn.strip().lower() != "player":
        return fn.strip()
    if fallback_name and fallback_name.strip() and fallback_name.strip().lower() != "player":
        return fallback_name.strip()
    return f"Player_{uid_int}" if uid_int else "Player"


def resolve_player_username(user_id: int, fallback_username: Optional[str] = None) -> Optional[str]:
    """Get real username from user_data."""
    try:
        uid_int = int(user_id)
    except (ValueError, TypeError):
        return fallback_username
    u_info = user_data.get(uid_int) or user_data.get(str(uid_int)) or {}
    un = u_info.get("username")
    if un and un.strip():
        return un.strip()
    if fallback_username and fallback_username.strip() and fallback_username.strip() != "-":
        return fallback_username.strip()
    return None


def sync_legacy_player_stats_to_ccc():
    """🔧 Sync legacy player_stats dict AND user_data names into user_stats SQL table."""
    try:
        conn = db_connect(DB_PATH)
        c = conn.cursor()

        # 1. Sync names from user_data into user_stats for all known users
        for uid, data in user_data.items():
            try:
                uid_int = int(uid)
            except (ValueError, TypeError):
                continue
            fn = data.get("first_name")
            un = data.get("username")
            c.execute("SELECT user_id FROM user_stats WHERE user_id = ?", (uid_int,))
            if not c.fetchone():
                c.execute("INSERT INTO user_stats (user_id, first_name, username) VALUES (?, ?, ?)", (uid_int, fn or "Player", un))
            else:
                if fn:
                    c.execute("UPDATE user_stats SET first_name = ? WHERE user_id = ? AND (first_name IS NULL OR first_name = '' OR first_name = 'Player')", (fn, uid_int))
                if un:
                    c.execute("UPDATE user_stats SET username = ? WHERE user_id = ? AND (username IS NULL OR username = '')", (un, uid_int))

        # 2. Sync numerical stats from player_stats dict (solo and team) into user_stats
        if player_stats:
            for uid, stats in player_stats.items():
                try:
                    uid_int = int(uid)
                except (ValueError, TypeError):
                    continue
                solo = stats.get("solo", {}) or {}
                team = stats.get("team", {}) or {}

                legacy = {
                    "matches_played": solo.get("matches", 0),
                    "matches_won": solo.get("wins", 0),
                    "total_runs": solo.get("runs", 0),
                    "total_balls_faced": solo.get("balls", 0),
                    "total_wickets": solo.get("wickets", 0),
                    "total_sixes": solo.get("sixes", 0),
                    "total_fours": solo.get("fours", 0),
                    "total_ducks": solo.get("ducks", 0),
                    "highest_score": solo.get("highest", solo.get("high_score", 0)),
                    "total_hundreds": solo.get("centuries", 0),
                    "total_fifties": solo.get("fifties", 0),
                    "team_matches_played": team.get("matches_played", team.get("matches", 0)),
                    "team_matches_won": team.get("wins", 0),
                    "team_total_runs": team.get("runs", 0),
                    "team_total_wickets": team.get("wickets", 0),
                    "team_total_sixes": team.get("sixes", 0),
                    "team_total_fours": team.get("fours", 0),
                    "team_total_ducks": team.get("ducks", 0),
                    "team_highest_score": team.get("highest", 0),
                    "team_total_hundreds": team.get("centuries", 0),
                    "team_total_fifties": team.get("fifties", 0),
                }

                if not any(legacy.values()):
                    continue

                c.execute("SELECT user_id FROM user_stats WHERE user_id = ?", (uid_int,))
                if not c.fetchone():
                    c.execute("INSERT INTO user_stats (user_id) VALUES (?)", (uid_int,))

                for col, val in legacy.items():
                    c.execute(f"UPDATE user_stats SET {col} = MAX(COALESCE({col},0), ?) WHERE user_id = ?", (val, uid_int))

        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"sync_legacy_player_stats_to_ccc failed: {e}")


# ══════════════════════════════════════════════
# 🏅 PLAYER TIERS & ACHIEVEMENTS SYSTEM
# Sits on top of the existing CCC rating + user_stats totals.
# Tiers = skill ladder derived from CCC rating (auto-recalculated live).
# Achievements = one-time career milestones, permanently unlocked & stored.
# ══════════════════════════════════════════════

PLAYER_TIERS = [
    # (name, emoji, min_rating)  — highest first, matched top-down
    ("Legend",      "👑", 300),
    ("Diamond",     "💎", 220),
    ("Platinum",    "🔷", 160),
    ("Gold",        "🥇", 110),
    ("Silver",      "🥈", 70),
    ("Bronze",      "🥉", 35),
    ("Rookie",      "🌱", 0),
]


def get_player_tier(rating: float) -> tuple:
    """Returns (name, emoji, min_rating, next_min_rating_or_None) for a given CCC rating."""
    for i, (name, emoji, floor) in enumerate(PLAYER_TIERS):
        if rating >= floor:
            next_floor = PLAYER_TIERS[i - 1][2] if i > 0 else None
            return (name, emoji, floor, next_floor)
    return PLAYER_TIERS[-1][0], PLAYER_TIERS[-1][1], 0, PLAYER_TIERS[-2][2]


def _tier_progress_bar(rating: float, floor: int, next_floor) -> str:
    if next_floor is None:
        return "▰▰▰▰▰▰▰▰▰▰ MAX TIER"
    span = max(next_floor - floor, 1)
    filled = max(0, min(10, round(((rating - floor) / span) * 10)))
    return "▰" * filled + "▱" * (10 - filled)


def ensure_achievements_table():
    """Create the player_achievements table if it doesn't exist yet (idempotent)."""
    try:
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute('''CREATE TABLE IF NOT EXISTS player_achievements (
            user_id INTEGER,
            ach_key TEXT,
            unlocked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (user_id, ach_key)
        )''')
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"ensure_achievements_table failed: {e}")


