def _fetch_combined_stats_for_achievements(user_id: int) -> Optional[dict]:
    """Pull the same combined solo+team totals CCC ranking uses, for ONE player."""
    try:
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("""
            SELECT
                (COALESCE(matches_played,0) + COALESCE(team_matches_played,0)) AS matches,
                (COALESCE(matches_won,0) + COALESCE(team_matches_won,0)) AS wins,
                (COALESCE(total_runs,0) + COALESCE(team_total_runs,0)) AS runs,
                (COALESCE(total_wickets,0) + COALESCE(team_total_wickets,0)) AS wickets,
                (COALESCE(total_sixes,0) + COALESCE(team_total_sixes,0)) AS sixes,
                (COALESCE(total_hundreds,0) + COALESCE(team_total_hundreds,0)) AS hundreds,
                (COALESCE(total_fifties,0) + COALESCE(team_total_fifties,0)) AS fifties,
                COALESCE(player_of_match_count,0) AS mom
            FROM user_stats WHERE user_id = ?
        """, (user_id,))
        row = c.fetchone()
        conn.close()
        if not row:
            return None
        matches, wins, runs, wickets, sixes, hundreds, fifties, mom = row
        rating = get_player_ccc_rank(user_id)
        rating_val = rating.get("rating", 0) if isinstance(rating, dict) else 0
        return {
            "matches": matches, "wins": wins, "runs": runs, "wickets": wickets,
            "sixes": sixes, "hundreds": hundreds, "fifties": fifties, "mom": mom,
            "rating": rating_val,
        }
    except Exception as e:
        logger.error(f"_fetch_combined_stats_for_achievements failed: {e}")
        return None


def get_unlocked_achievement_keys(user_id: int) -> set:
    ensure_achievements_table()
    try:
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("SELECT ach_key FROM player_achievements WHERE user_id = ?", (user_id,))
        keys = {r[0] for r in c.fetchall()}
        conn.close()
        return keys
    except Exception as e:
        logger.error(f"get_unlocked_achievement_keys failed: {e}")
        return set()


def check_and_award_achievements(user_id: int) -> list:
    """Checks career totals against ACHIEVEMENTS, unlocks any newly-earned ones,
    persists them, and returns the list of newly-unlocked achievement dicts."""
    ensure_achievements_table()
    stats = _fetch_combined_stats_for_achievements(user_id)
    if not stats:
        return []
    already = get_unlocked_achievement_keys(user_id)
    newly_unlocked = []
    for ach in ACHIEVEMENTS:
        if ach["key"] in already:
            continue
        try:
            if ach["check"](stats):
                newly_unlocked.append(ach)
        except Exception:
            continue
    if newly_unlocked:
        try:
            conn = sqlite3.connect(DB_PATH)
            c = conn.cursor()
            for ach in newly_unlocked:
                c.execute(
                    "INSERT OR IGNORE INTO player_achievements (user_id, ach_key) VALUES (?, ?)",
                    (user_id, ach["key"])
                )
            conn.commit()
            conn.close()
        except Exception as e:
            logger.error(f"check_and_award_achievements save failed: {e}")
    return newly_unlocked


async def notify_new_achievements_via_bot(user_id: int, newly_unlocked: list):
    """DM the player for each newly unlocked achievement, using the module-level
    _global_bot handle (safe to call from match-end code paths that have no
    `context` object). Silently skipped if DM fails or bot isn't ready yet."""
    if not newly_unlocked or not _global_bot:
        return
    try:
        lines = "\n".join(f"{a['emoji']} <b>{a['name']}</b> — {a['desc']}" for a in newly_unlocked)
        text = (
            "🏅 <b>ACHIEVEMENT UNLOCKED!</b>\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            f"{lines}\n"
            "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
            "<i>Check /achievements to see your full collection!</i>"
        )
        await _global_bot.send_message(chat_id=user_id, text=text, parse_mode=ParseMode.HTML)
    except Exception:
        pass


async def _legacy_rank_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🎖️ /rank — shows your tier badge, CCC rating, global rank & progress to next tier."""
    target = update.effective_user
    if update.message.reply_to_message:
        target = update.message.reply_to_message.from_user
    user_id = target.id
    name = resolve_player_name(user_id, target.first_name)

    sync_legacy_player_stats_to_ccc()
    row = get_player_ccc_rank(user_id)
    if not row:
        await update.message.reply_text(
            f"🎖️ <b>{name}</b> hasn't played enough qualifying matches yet to be ranked.\n"
            f"Play a few more matches and try /rank again!",
            parse_mode=ParseMode.HTML
        )
        return

    rating = row.get("rating", 0)
    rank = row.get("rank", "-")
    matches = row.get("matches", 0)
    wins = row.get("wins", 0)
    category = row.get("category", "Batsman")

    tier_name, tier_emoji, floor, next_floor = get_player_tier(rating)
    bar = _tier_progress_bar(rating, floor, next_floor)
    next_line = (
        f"Next tier: <b>{next_floor} rating</b> needed"
        if next_floor is not None else "🏆 Highest tier reached!"
    )

    unlocked_count = len(get_unlocked_achievement_keys(user_id))

    text = (
        f"{tier_emoji} <b>{tier_name.upper()} TIER</b>\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"👤 <b>{name}</b> · {category}\n"
        f"⭐ CCC Rating: <b>{rating}</b>\n"
        f"🌍 Global Rank: <b>#{rank}</b>\n"
        f"📊 Matches: {matches} · Wins: {wins}\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"{bar}\n"
        f"<i>{next_line}</i>\n"
        "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
        f"🏅 Achievements Unlocked: <b>{unlocked_count}/{len(ACHIEVEMENTS)}</b>\n"
        f"<i>Use /achievements to view them all</i>"
    )
    await update.message.reply_text(text, parse_mode=ParseMode.HTML)


async def _legacy_achievements_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏅 /achievements — view unlocked & locked career milestones."""
    target = update.effective_user
    if update.message.reply_to_message:
        target = update.message.reply_to_message.from_user
    user_id = target.id
    name = resolve_player_name(user_id, target.first_name)

    unlocked = get_unlocked_achievement_keys(user_id)
    unlocked_list = [a for a in ACHIEVEMENTS if a["key"] in unlocked]
    locked_list = [a for a in ACHIEVEMENTS if a["key"] not in unlocked]

    lines = [f"🏅 <b>{name}'S ACHIEVEMENTS</b> ({len(unlocked_list)}/{len(ACHIEVEMENTS)})", "┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"]
    if unlocked_list:
        lines.append("✅ <b>Unlocked</b>")
        for a in unlocked_list:
            lines.append(f"{a['emoji']} <b>{a['name']}</b> — {a['desc']}")
    else:
        lines.append("No achievements unlocked yet — get playing! 🏏")

    if locked_list:
        lines.append("\n🔒 <b>Locked</b>")
        for a in locked_list[:10]:
            lines.append(f"▫️ {a['name']} — {a['desc']}")
        if len(locked_list) > 10:
            lines.append(f"<i>...and {len(locked_list) - 10} more</i>")

    await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)


def ensure_ccc_rank_table():
    """Create the CCC Ranking snapshot table if it doesn't exist yet (idempotent)."""
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS ccc_rank_snapshot (
        user_id INTEGER PRIMARY KEY,
        rank INTEGER,
        rating REAL,
        category TEXT DEFAULT 'Batsman',
        snapshot_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    try:
        c.execute("ALTER TABLE ccc_rank_snapshot ADD COLUMN category TEXT DEFAULT 'Batsman'")
    except Exception:
        pass  # Column already exists
    conn.commit()
    conn.close()


def _compute_ccc_ranking_rows():
    """
    🏅 CCC RANKING — CricoVerse's overall player rating, ICC-style.
    Combines batting, bowling, wins and match-winning impact into a single rating,
    averaged per match so grinders don't automatically outrank sharper performers.
    Returns a strictly-ordered list (no ties) of dicts, richest performer first:
    [{user_id, first_name, matches, wins, rating, rank}, ...]
    """
    ensure_ccc_rank_table()
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("""
        SELECT user_id, first_name,
            (COALESCE(matches_played,0) + COALESCE(team_matches_played,0)) AS matches,
            (COALESCE(matches_won,0) + COALESCE(team_matches_won,0)) AS wins,
            (COALESCE(total_runs,0) + COALESCE(team_total_runs,0)) AS runs,
            (COALESCE(total_wickets,0) + COALESCE(team_total_wickets,0)) AS wickets,
            (COALESCE(total_sixes,0) + COALESCE(team_total_sixes,0)) AS sixes,
            (COALESCE(total_fours,0) + COALESCE(team_total_fours,0)) AS fours,
            (COALESCE(total_hundreds,0) + COALESCE(team_total_hundreds,0)) AS hundreds,
            (COALESCE(total_fifties,0) + COALESCE(team_total_fifties,0)) AS fifties,
            (COALESCE(total_ducks,0) + COALESCE(team_total_ducks,0)) AS ducks,
            COALESCE(player_of_match_count,0) AS mom,
            (COALESCE(total_balls_faced,0) + COALESCE(team_total_balls_faced,0)) AS balls_faced,
            (COALESCE(total_balls_bowled,0) + COALESCE(team_total_balls_bowled,0)) AS balls_bowled
        FROM user_stats
    """)
    all_rows = c.fetchall()
    conn.close()

    # First pass: gather raw points-per-match for every qualified player so we can
    # compute a league-average baseline. A *pure* per-match average (old formula)
    # rewards a handful of lucky matches over sustained volume, since one bad game
    # drags a small sample down just as hard as a big one — so grinders who keep
    # playing (and inevitably rack up a few average/bad games too) end up looking
    # worse than someone who played the bare minimum and got lucky. We fix this
    # two ways:
    #   1. Bayesian smoothing — shrink each player's average toward the league
    #      baseline by a fixed number of "phantom" matches (K). This tames small
    #      sample swings without capping anyone's ceiling once they have real volume.
    #   2. Explicit experience bonus — a small flat bonus per matches played
    #      (capped) so consistent grinders get real credit for volume rather than
    #      being purely at the mercy of an average.
    prelim = []
    for (user_id, first_name, matches, wins, runs, wickets, sixes, fours,
         hundreds, fifties, ducks, mom, balls_faced, balls_bowled) in all_rows:
        if matches < CCC_MIN_MATCHES:
            continue

        win_rate = (wins / matches) * 100 if matches else 0

        # Weighted point system (total career points, not yet normalized)
        points = (
            runs * 1.0 +
            wickets * 20 +
            wins * 15 +
            sixes * 2 +
            fours * 1 +
            hundreds * 50 +
            fifties * 20 +
            mom * 25 +
            win_rate * matches * 0.5 -
            ducks * 5
        )

        prelim.append({
            "user_id": user_id,
            "first_name": resolve_player_name(user_id, first_name),
            "matches": matches,
            "wins": wins,
            "points": points,
            "runs": runs,
            "wickets": wickets,
            "balls_faced": balls_faced,
            "balls_bowled": balls_bowled,
        })

    if not prelim:
        return []

    # 🎯 Classify the WHOLE qualified pool at once → ~45% Batsman / 35% Bowler /
    # 20% All-Rounder composition, instead of each player being judged in isolation.
    _category_by_id = classify_players_pool(prelim)
    for p in prelim:
        p["category"] = _category_by_id.get(p["user_id"], "Batsman")

    # League baseline = average points-per-match across all qualified players
    baseline = sum(p["points"] / p["matches"] for p in prelim) / len(prelim)

    K = 15          # regularization strength (in "phantom" matches) — bigger K = more shrinkage for low-volume players
    EXP_BONUS_PER_MATCH = 0.25   # flat reward per real match played, rewarding volume/experience
    EXP_BONUS_CAP_MATCHES = 300  # bonus stops growing past this many matches

    scored = []
    for p in prelim:
        matches = p["matches"]
        points = p["points"]

        # Bayesian-smoothed average: pulls low-sample players toward the baseline
        # instead of letting a handful of great matches rocket them to the top,
        # while barely affecting players who already have a lot of matches.
        smoothed_avg = (points + K * baseline) / (matches + K)

        experience_bonus = min(matches, EXP_BONUS_CAP_MATCHES) * EXP_BONUS_PER_MATCH

        rating = round(smoothed_avg + experience_bonus, 2)

        scored.append({
            "user_id": p["user_id"],
            "first_name": p["first_name"],
            "matches": matches,
            "wins": p["wins"],
            "rating": rating,
            "category": p["category"],
        })

    # Strict deterministic order → guarantees no two players ever share a rank
    scored.sort(key=lambda r: (-r["rating"], -r["matches"], r["user_id"]))
    for i, row in enumerate(scored):
        row["rank"] = i + 1

    return scored


CCC_TREND_WINDOW = timedelta(days=1)  # 🔧 trend arrows (🔼/🔽/🆕) only compare against
                                       # a snapshot taken within the last 1 day; an older
                                       # snapshot is treated as stale and ignored so trend
                                       # effectively resets/expires after 1 day.


def get_ccc_rankings_with_trend(limit: Optional[int] = None):
    """
    Returns the CCC ranking rows (optionally truncated to `limit`), each tagged with a
    'trend' field showing movement since the last snapshot **taken within the last 1 day**:
    '🆕' new entry (or snapshot older than 1 day / missing), '🔼N' climbed N spots,
    '🔽N' dropped N spots, '➖' unchanged.
    Also refreshes the snapshot table used for the next trend comparison.
    """
    rows = _compute_ccc_ranking_rows()

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT user_id, rank, snapshot_at FROM ccc_rank_snapshot")
    now = datetime.now()
    old_ranks = {}
    for uid, r, snap_at in c.fetchall():
        try:
            snap_dt = snap_at if isinstance(snap_at, datetime) else datetime.fromisoformat(str(snap_at))
        except (ValueError, TypeError):
            continue
        # Ignore snapshots older than the trend window — trend "expires" after 1 day
        if now - snap_dt <= CCC_TREND_WINDOW:
            old_ranks[uid] = r

    for row in rows:
        old_rank = old_ranks.get(row["user_id"])
        if old_rank is None:
            row["trend"] = "🆕"
        elif old_rank > row["rank"]:
            row["trend"] = f"🔼{old_rank - row['rank']}"
        elif old_rank < row["rank"]:
            row["trend"] = f"🔽{row['rank'] - old_rank}"
        else:
            row["trend"] = "➖"

        c.execute(
            "INSERT INTO ccc_rank_snapshot (user_id, rank, rating, category, snapshot_at) VALUES (?, ?, ?, ?, ?) "
            "ON CONFLICT(user_id) DO UPDATE SET rank=excluded.rank, rating=excluded.rating, category=excluded.category, snapshot_at=excluded.snapshot_at",
            (row["user_id"], row["rank"], row["rating"], row.get("category", "Batsman"), now)
        )

    conn.commit()
    conn.close()

    return rows[:limit] if limit else rows


def get_player_ccc_rank(user_id: int):
    """Returns this player's CCC ranking row with category-specific rank and trend, or None."""
    rows = get_ccc_rankings_with_trend()
    # Find player's category first
    player_row = None
    for row in rows:
        if row["user_id"] == user_id:
            player_row = row
            break
    if not player_row:
        return None
    # Compute rank within their category
    category = player_row.get("category", "Batsman")
    cat_rank = 1
    for row in rows:
        if row["category"] == category and row["rating"] > player_row["rating"]:
            cat_rank += 1
    player_row["cat_rank"] = cat_rank
    return player_row


def get_ccc_rankings_by_category(category: str, limit: int = 10):
    """Returns CCC rankings filtered to a specific category, re-ranked within that category."""
    all_rows = get_ccc_rankings_with_trend()
    filtered = [r for r in all_rows if r.get("category") == category]
    # Re-rank within category
    for i, row in enumerate(filtered):
        row["cat_rank"] = i + 1
    return filtered[:limit] if limit else filtered


def _build_ccc_rich_html() -> str:
    """Build sendRichMessage HTML for CCC rankings with expandable <h3> dropdowns."""
    rows = get_ccc_rankings_with_trend()
    batsmen = [r for r in rows if r.get("category") == "Batsman"][:12]
    bowlers = [r for r in rows if r.get("category") == "Bowler"][:12]
    allrounders = [r for r in rows if r.get("category") == "All-Rounder"][:12]

    def _cat_table(players):
        if not players:
            return "<p><i>No qualified players yet</i></p>"
        trs = ""
        for i, p in enumerate(players):
            name = html.escape((p.get("first_name") or "Player")[:16])
            trs += (
                f"<tr><td align='center'>{i+1}</td>"
                f"<td>{name}</td>"
                f"<td align='right'>{p['rating']}</td>"
                f"<td align='right'>{p['matches']}</td>"
                f"<td align='center'>{p.get('trend', '🆕')}</td></tr>"
            )
        return (
            "<table bordered striped>"
            "<tr><th>#️⃣</th><th>🧢 Name</th><th>⭐ Rating</th><th>🎮 Matches</th><th>📈 Trend</th></tr>"
            f"{trs}</table>"
        )

    # Telegram Rich HTML: <details> is the expandable container that can
    # contain a native table. <blockquote expandable> is for quotation text,
    # so using it around <table> causes the table to render but not collapse.
    return (
        f"<h3>🏅 CCC RANKING — CricoVerse Career Rating</h3>"
        f"<p>Players auto-classified by stats · min {CCC_MIN_MATCHES} matches</p>"
        f"<details><summary>🏏 Top 12 Batsmen</summary>{_cat_table(batsmen)}</details>"
        f"<details><summary>⚾ Top 12 Bowlers</summary>{_cat_table(bowlers)}</details>"
        f"<details><summary>🏏⚾ Top 12 All-Rounders</summary>{_cat_table(allrounders)}</details>"
        f"<footer>🏅 CRICOVERSE CCC RANKING 🎮</footer>"
    )


def _build_ccc_fallback_text() -> str:
    """CCC rankings rendered as expandable native tables — same look as
    /fantasylb: each category is a <blockquote expandable><pre>table</pre></blockquote>,
    collapsed by default, tap to expand and see the ranked table."""
    rows = get_ccc_rankings_with_trend()
    batsmen = [r for r in rows if r.get("category") == "Batsman"][:12]
    bowlers = [r for r in rows if r.get("category") == "Bowler"][:12]
    allrounders = [r for r in rows if r.get("category") == "All-Rounder"][:12]

    def _pad(s, w):
        s = html.escape(str(s))
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))

    def _rpad(s, w):
        s = str(s)
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else (" " * (w - len(s))) + s

    def _section(title, emoji, players):
        header = f"{_pad('#', 4)}{_pad('Name', 16)}{_rpad('Rating', 7)}  {_rpad('M', 4)}  {_pad('Trend', 6)}\n"
        table = header + ("—" * 42) + "\n"
        if not players:
            table += f"No qualified players yet — play {CCC_MIN_MATCHES}+ matches!\n"
        else:
            for i, p in enumerate(players):
                name = p.get("first_name") or "Player"
                table += (
                    f"{_pad(i + 1, 4)}{_pad(name, 16)}{_rpad(p['rating'], 7)}  "
                    f"{_rpad(p['matches'], 4)}  {_pad(p.get('trend', '🆕'), 6)}\n"
                )
        return f"<blockquote expandable>{emoji} <b>{title}</b>\n<pre>{table}</pre></blockquote>\n"

    text = "🏅 <b>CCC RANKING — CricoVerse Career Rating</b>\n┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
    text += f"Players auto-classified by stats · min {CCC_MIN_MATCHES} matches\n\n"
    text += _section("Top 12 Batsmen", "🏏", batsmen)
    text += _section("Top 12 Bowlers", "⚾", bowlers)
    text += _section("Top 12 All-Rounders", "🏏⚾", allrounders)
    text += "\n🏅 CRICOVERSE CCC RANKING 🎮"
    return text


async def _legacy_ccc_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏅 /ccc — CCC Career Rating Rankings by category (collapsible sections)"""
    chat_id = update.effective_chat.id

    # Same approach as /fantasylb: try the native rich table+dropdown first,
    # fall back to the <blockquote expandable> text table only if it fails.
    html_content = await asyncio.to_thread(_build_ccc_rich_html)
    ok = await _tg_send_rich_message(chat_id, html_content)

    if not ok:
        text = await asyncio.to_thread(_build_ccc_fallback_text)
        await update.message.reply_text(text, parse_mode=ParseMode.HTML)



