# ───────────────────────── GLOBAL LEADERBOARD ─────────────────────────
_LB_PAGE = 10
_LB_TABS = [("runs", "🏃 Runs"), ("wickets", "⚾ Wickets"), ("wins", "🏆 Wins"), ("winrate", "🎯 Win%"),
            ("fours", "4️⃣ 4s"), ("sixes", "🚀 6s"), ("mom", "🌟 MOM"), ("reactions", "🎉 Likes")]
_LB_META = {   # key: (emoji, title, header-after-name, unit-for-"You"-line)
    "runs":      ("🏃", "TOP RUN-GETTERS",     ["RUNS", "BALLS", "SR"],     "runs"),
    "wickets":   ("⚾", "TOP WICKET-TAKERS",   ["WKTS", "OVERS", "ECO"],    "wickets"),
    "wins":      ("🏆", "MOST MATCH WINS",     ["WINS", "PLAYED", "WIN%"],  "wins"),
    "winrate":   ("🎯", "BEST WIN RATE",       ["WIN%", "WINS", "PLAYED"],  "win rate"),
    "fours":     ("4️⃣", "MOST FOURS",          ["4s", "RUNS", "SR"],        "fours"),
    "sixes":     ("🚀", "MOST SIXES",          ["6s", "RUNS", "SR"],        "sixes"),
    "mom":       ("🌟", "MAN OF THE MATCH",    ["MOM"],                     "MOM awards"),
    "reactions": ("🎉", "MOST REACTIONS",      ["LIKES"],                   "reactions"),
}
_LB_CACHE: dict = {}


def _lb_all_rows(metric: str):
    """Full resolved ranking for a metric, cached 20s so tab-spam can't hammer SQLite on the 2vCPU box."""
    return _rc_cache(_LB_CACHE, metric, 20.0, lambda: _lb_query(metric, 0, 10 ** 9)[1])


def _lb_cells(metric: str, row) -> list:
    def _sr(r, b):
        return f"{(r / b * 100):.1f}" if b else "0.0"
    if metric == "runs":
        _, _, _, tr, tb = row
        return [f"{tr:,}", f"{tb:,}", _sr(tr, tb)]
    if metric == "wickets":
        _, _, _, tw, tbb, trc = row
        return [f"{tw:,}", f"{tbb // 6}.{tbb % 6}", f"{(trc / (tbb / 6)):.2f}" if tbb else "0.00"]
    if metric in ("fours", "sixes"):
        _, _, _, n, tr, tb = row
        return [f"{n:,}", f"{tr:,}", _sr(tr, tb)]
    if metric == "wins":
        _, _, _, tw, tp = row
        return [f"{tw:,}", f"{tp:,}", f"{(tw / max(tp, 1) * 100):.0f}%"]
    if metric == "winrate":
        _, _, _, tw, tp = row
        return [f"{(tw / max(tp, 1) * 100):.1f}%", f"{tw:,}", f"{tp:,}"]
    if metric == "mom":
        return [f"{row[3]:,}"]
    return [f"{row[3]:,}"]


def _lb_rich_view(metric: str, offset: int, viewer_id: int):
    if metric not in _LB_META:
        metric = "runs"
    all_rows = _lb_all_rows(metric)
    total = len(all_rows)
    pages = max(1, math.ceil(total / _LB_PAGE))
    offset = max(0, min(int(offset), (pages - 1) * _LB_PAGE))
    offset -= offset % _LB_PAGE
    cur = offset // _LB_PAGE + 1
    emoji, title, heads, unit = _LB_META[metric]

    page_rows = all_rows[offset:offset + _LB_PAGE]
    body = f"<h2>{emoji} CRICOVERSE · {title}</h2><p>🌍 All groups · all time · <b>{total:,}</b> players</p>"
    if page_rows:
        tbl = [["#", "PLAYER"] + heads]
        for i, r in enumerate(page_rows):
            rank = offset + i + 1
            tbl.append([_RC_MEDALS.get(rank, str(rank)), _rc_name(r[0], r[1])] + _lb_cells(metric, r))
        body += rc_table(tbl, ["center", "left"] + ["right"] * len(heads))
    else:
        body += "<p>📭 No data yet — play some matches to get on the board!</p>"

    me = next(((i, r) for i, r in enumerate(all_rows) if r[0] == viewer_id), None)
    if me:
        body += f"<p>📍 <b>You:</b> #{me[0] + 1} of {total:,} · {_lb_cells(metric, me[1])[0]} {unit}</p>"
    else:
        body += "<p>📍 <b>You:</b> not ranked here yet — play a match! 🏏</p>"
    body += f"<footer>Page {cur}/{pages} · /ccc career ratings · /rank your tier 🏅</footer>"

    rows = _rc_tabs([(k, lbl) for k, lbl in _LB_TABS], metric, "lb_{k}_0", per_row=4)
    if pages > 1:
        nav = []
        if offset > 0:
            nav.append(("◀ Prev", "primary", f"lb_{metric}_{offset - _LB_PAGE}"))
        nav.append((f"{cur}/{pages}", "link", "lb_noop"))
        if offset + _LB_PAGE < total:
            nav.append(("Next ▶", "primary", f"lb_{metric}_{offset + _LB_PAGE}"))
        rows.append(nav)
    rows.append([("🏅 CCC Ratings", "primary", "lb_ccc"), ("🔄 Refresh", "link", f"lb_{metric}_{offset}"),
                 ("✖ Close", "danger", "lb_close")])
    return body, rows


async def leaderboard_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏆 /leaderboard — Atlas-style rich table with tabs, pagination and your own rank."""
    chat, user = update.effective_chat, update.effective_user
    try:
        body, rows = await asyncio.to_thread(_lb_rich_view, "runs", 0, user.id)
        if await rc_send(chat.id, body, rows, reply_to=update.message.message_id if update.message else None):
            return
    except Exception:
        logger.exception("rich leaderboard failed — using legacy view")
    await _legacy_leaderboard_command(update, context)


async def leaderboard_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    data = query.data[3:] if query.data.startswith("lb_") else query.data
    if data == "noop":
        await query.answer()
        return
    if data == "close":
        await query.answer()
        try:
            await query.message.delete()
        except Exception:
            pass
        return
    try:
        if data == "ccc":
            body, rows = await asyncio.to_thread(_ccc_rich_view, "bat", query.from_user.id)
        else:
            metric, offset = "runs", 0
            if data != "back":
                parts = data.rsplit("_", 1)
                if len(parts) == 2 and parts[1].isdigit():
                    metric, offset = parts[0], int(parts[1])
                else:
                    metric = data
            body, rows = await asyncio.to_thread(_lb_rich_view, metric, offset, query.from_user.id)
    except Exception:
        logger.exception("rich leaderboard callback failed — using legacy view")
        await _legacy_leaderboard_callback(update, context)
        return
    await query.answer()
    await rc_edit_or_send(query, body, rows)


