_CCC_TABS = [("bat", "🏏 Batsmen"), ("bowl", "⚾ Bowlers"), ("ar", "🏏⚾ All-Rounders")]
_CCC_CAT = {"bat": "Batsman", "bowl": "Bowler", "ar": "All-Rounder"}
_CCC_CACHE: dict = {}


def _ccc_rich_view(cat_key: str, viewer_id: int):
    if cat_key not in _CCC_CAT:
        cat_key = "bat"
    cat = _CCC_CAT[cat_key]
    all_rows = _rc_cache(_CCC_CACHE, "all", 20.0, get_ccc_rankings_with_trend)
    in_cat = [r for r in all_rows if r.get("category") == cat]
    body = (f"<h2>🏅 CCC RANKING · {dict(_CCC_TABS)[cat_key]}</h2>"
            f"<p>CricoVerse career rating · min <b>{CCC_MIN_MATCHES}</b> matches</p>")
    if in_cat:
        tbl = [["#", "PLAYER", "⭐ RATING", "M", "TREND"]]
        for i, p in enumerate(in_cat[:15]):
            tier_emoji = get_player_tier(p["rating"])[1]
            tbl.append([_RC_MEDALS.get(i + 1, str(i + 1)),
                        f"{tier_emoji} {_rc_name(p.get('user_id'), p.get('first_name'), 13)}",
                        p["rating"], p["matches"], p.get("trend", "🆕")])
        body += rc_table(tbl, ["center", "left", "right", "right", "center"])
    else:
        body += f"<p>📭 No qualified players yet — play {CCC_MIN_MATCHES}+ matches!</p>"

    me = next((r for r in all_rows if r.get("user_id") == viewer_id), None)
    if me:
        cat_rank = next((i + 1 for i, r in enumerate(all_rows) if r.get("category") == me.get("category")
                         and r.get("user_id") == viewer_id), "-")
        in_my_cat = [r for r in all_rows if r.get("category") == me.get("category")]
        cat_rank = next((i + 1 for i, r in enumerate(in_my_cat) if r.get("user_id") == viewer_id), cat_rank)
        tier = get_player_tier(me["rating"])
        body += (f"<p>📍 <b>You:</b> {tier[1]} {tier[0]} · ⭐ {me['rating']} · "
                 f"#{cat_rank} {me.get('category', '')} · global #{me.get('rank', '-')}</p>")
    else:
        body += f"<p>📍 <b>You:</b> unranked — play {CCC_MIN_MATCHES}+ matches to qualify.</p>"
    body += "<footer>🏅 CRICOVERSE CCC · /rank for your tier & progress</footer>"

    rows = _rc_tabs(_CCC_TABS, cat_key, "ccc_{k}", per_row=3)
    rows.append([("🏆 Leaderboard", "primary", "lb_back"), ("🔄 Refresh", "link", f"ccc_{cat_key}"),
                 ("✖ Close", "danger", "lb_close")])
    return body, rows


