# ───────────────────────── /rank + /achievements ─────────────────────────
_RK_TABS = [("rank", "🎖️ Rank"), ("ach", "🏅 Achievements")]


def _rk_rich_view(tab: str, user_id: int, name: str):
    rows = [*_rc_tabs(_RK_TABS, tab, f"rk_{{k}}_{user_id}", per_row=2)]
    rows.append([("🏆 Leaderboard", "primary", "lb_back"), ("🏅 CCC", "primary", "lb_ccc"),
                 ("✖ Close", "danger", "lb_close")])
    if tab == "ach":
        unlocked = get_unlocked_achievement_keys(user_id)
        done = [a for a in ACHIEVEMENTS if a["key"] in unlocked]
        todo = [a for a in ACHIEVEMENTS if a["key"] not in unlocked]
        body = f"<h2>🏅 {rc_esc(name)} · ACHIEVEMENTS</h2><p><b>{len(done)}/{len(ACHIEVEMENTS)}</b> unlocked</p>"
        tbl = [["", "ACHIEVEMENT", "HOW TO GET IT"]]
        tbl += [["✅", f"{a['emoji']} {a['name']}", a["desc"]] for a in done]
        tbl += [["🔒", a["name"], a["desc"]] for a in todo]
        body += rc_table(tbl, ["center", "left", "left"])
        body += "<footer>Keep playing to unlock more 🏏</footer>"
        return body, rows

    sync_legacy_player_stats_to_ccc()
    row = get_player_ccc_rank(user_id)
    if not row:
        body = (f"<h2>🎖️ {rc_esc(name)} · RANK</h2>"
                f"<p>Not ranked yet — play a few more qualifying matches and try /rank again!</p>")
        return body, rows
    rating, rank = row.get("rating", 0), row.get("rank", "-")
    tier_name, tier_emoji, floor, next_floor = get_player_tier(rating)
    bar = _tier_progress_bar(rating, floor, next_floor)
    nxt = f"{next_floor} rating needed for next tier" if next_floor is not None else "🏆 Highest tier reached!"
    ach = len(get_unlocked_achievement_keys(user_id))
    body = f"<h2>{tier_emoji} {rc_esc(tier_name.upper())} TIER</h2><p>👤 <b>{rc_esc(name)}</b></p>"
    body += rc_table([["STAT", "VALUE"],
                      ["Role", row.get("category", "Batsman")],
                      ["⭐ CCC Rating", rating],
                      ["🌍 Global Rank", f"#{rank}"],
                      ["🎮 Matches / Wins", f"{row.get('matches', 0)} / {row.get('wins', 0)}"],
                      ["🏅 Achievements", f"{ach}/{len(ACHIEVEMENTS)}"]], ["left", "right"])
    body += f"<p>{rc_esc(bar)}</p><footer>{rc_esc(nxt)}</footer>"
    return body, rows


