# ───────────────────────── TOURNAMENT LEADERBOARD ─────────────────────────
_TOURLB_TABS = [("runs", "🏃 Runs"), ("wickets", "⚾ Wickets"), ("sixes", "🚀 Sixes"), ("fours", "4️⃣ Fours")]


def _tourlb_rich_view(group_id, metric, title, unit, page, total_pages, start, page_rows, total_matches, total_players):
    body = (f"<h2>🏆 TOURNAMENT · {rc_esc(title)}</h2>"
            f"<p>🏟️ Matches: <b>{total_matches}</b> · 👥 Players: <b>{total_players}</b></p>")
    if page_rows:
        tbl = [["#", "PLAYER", unit.upper()]]
        for i, d in enumerate(page_rows):
            rank = start + i + 1
            tbl.append([_RC_MEDALS.get(rank, str(rank)), _rc_name(d["pid"], d["name"]), f"{d['total']:,}"])
        body += rc_table(tbl, ["center", "left", "right"])
    else:
        body += "<p>📭 No data yet — complete some matches!</p>"
    body += f"<footer>Page {page + 1}/{total_pages}</footer>"
    rows = _rc_tabs(_TOURLB_TABS, metric, f"tourlb_{group_id}_{{k}}_0", per_row=4)
    if total_pages > 1:
        nav = []
        if page > 0:
            nav.append(("◀ Prev", "primary", f"tourlb_{group_id}_{metric}_{page - 1}"))
        nav.append((f"{page + 1}/{total_pages}", "link", "lb_noop"))
        if page < total_pages - 1:
            nav.append(("Next ▶", "primary", f"tourlb_{group_id}_{metric}_{page + 1}"))
        rows.append(nav)
    rows.append([("🔄 Refresh", "link", f"tourlb_{group_id}_{metric}_{page}"), ("✖ Close", "danger", "lb_close")])
    return body, rows


