async def setup_public_bot_commands(application: Application):
    """Keep Telegram's command menu focused on user-facing commands."""
    # ✅ FIX: Make sure no webhook is left active before we start polling.
    # If a webhook was ever set (e.g. from a previous deployment) and we then
    # call run_polling() / getUpdates(), Telegram raises:
    #   "Conflict: can't use getUpdates method while webhook is active"
    # Deleting the webhook here (it runs once, right before polling starts)
    # makes startup self-healing regardless of how the bot was run before.
    try:
        for attempt in range(5):
            try:
                await application.bot.delete_webhook(drop_pending_updates=True)
                logger.info("✅ Webhook cleared (if any) — safe to start polling.")
                break
            except Exception as e:
                logger.warning(f"delete_webhook attempt {attempt+1}/5 failed: {e}")
                if attempt < 4:
                    await asyncio.sleep(3)
    except Exception as e:
        logger.warning(f"Could not delete webhook (continuing anyway): {e}")

    # 🩹 BUGFIX: restore any matches that were mid-game when the bot last
    # stopped, and start the periodic autosave loop that keeps future
    # restarts recoverable too. Done here (post_init, async, before polling
    # opens up to real player commands) so it's race-free.
    try:
        await _restore_active_matches_from_autosave(application)
    except Exception as e:
        logger.error(f"Active-match restore failed: {e}")
    asyncio.create_task(autosave_active_matches_loop())
    asyncio.create_task(autosave_active_auctions_loop(application.bot))
    asyncio.create_task(auction_change_watcher_loop())
    asyncio.create_task(warm_normalized_gifs(application.bot))
    try:
        await _restore_interrupted_auctions(application)
    except Exception as e:
        logger.error(f"Auction auto-restore failed: {e}")

    commands = [
        BotCommand("game", "Start a cricket match"),
        BotCommand("help", "Rules, modes, and quick guide"),
        BotCommand("mystats", "Your profile card and stats"),
        BotCommand("h2h", "Head-to-Head: compare 2 players"),
        BotCommand("scorecard", "Live scorecard and worm graph"),
        BotCommand("players", "Current squads and player status"),
        BotCommand("momentum", "Momentum dashboard image"),
        BotCommand("lb", "Global leaderboard"),
        BotCommand("ccc", "CCC Career Rankings by category"),
        BotCommand("fantasylb", "Fantasy Dream III leaderboard"),
        BotCommand("gcsettings", "Group settings for admins"),
        BotCommand("endmatch", "End the current match"),
    ]
    try:
        await application.bot.set_my_commands(commands)
    except Exception as e:
        logger.warning(f"Could not set public bot commands: {e}")

    # 🆕 Load persisted support-group override (if /setsupport was used before)
    _load_support_group()

    # 🆕 Startup notification — fires whenever this process boots (main bot
    # OR a clone), so the owner always knows a bot instance just came online.
    try:
        me = await application.bot.get_me()
        bot_kind = "🧬 Clone Bot" if IS_CLONE else "🤖 Main Bot"
        expiry_line = f"\n⏳ <b>Clone expires:</b> {CLONE_EXPIRES_AT_ISO}" if IS_CLONE and CLONE_EXPIRES_AT_ISO else ""
        await application.bot.send_message(
            chat_id=SUPPORT_GROUP_ID,
            text=(
                f"✅ <b>BOT STARTED</b>\n"
                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n"
                f"{bot_kind}\n"
                f"👤 <b>Username:</b> @{me.username}\n"
                f"🆔 <b>Bot ID:</b> <code>{me.id}</code>\n"
                f"🕒 <b>Started at:</b> {datetime.now().strftime('%d %b %Y, %I:%M %p')}"
                f"{expiry_line}\n"
                f"┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈"
            ),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.warning(f"Could not send bot-started notification: {e}")

    # ⚡ SPEED FIX: warm the animation file_id cache for every local gif
    # BEFORE any real match can hit it. Without this, the very first
    # dot/four/six/wicket/wide of each gif — in every group, every time the
    # process restarts — pays the full ~3s "upload from disk" cost live in
    # front of players. Doing it once here (against the support/log chat,
    # then deleting the message) means matches only ever see cache HITs.
    asyncio.create_task(_warm_animation_cache(application))


async def _warm_animation_cache(application: "Application"):
    """Send every local gif/mp4 (animation) AND every local image once to the
    OWNER's DM so Telegram hands back a file_id which gets cached (and saved
    to file_id_cache.json). After that, every match send reuses the file_id —
    zero disk upload. Already-cached files are skipped, so only the first run
    after a fresh deploy sends anything. Falls back to SUPPORT_GROUP_ID if the
    owner hasn't started the bot yet. Runs in background."""
    def _flatten(v):
        if isinstance(v, Path):
            yield v
        elif isinstance(v, (list, tuple, set)):
            for x in v:
                yield from _flatten(x)
        elif isinstance(v, dict):
            for x in v.values():
                yield from _flatten(x)

    anim_paths = list(_flatten(list(GIFS.values()))) + [BATTING_SELECT_GIF, BOWLING_SELECT_GIF]
    photo_paths = list(_flatten(dict(MEDIA_ASSETS)))

    jobs, seen = [], set()
    for kind, paths in (("animation", anim_paths), ("photo", photo_paths)):
        for p in paths:
            if not isinstance(p, Path) or str(p) in seen:
                continue
            seen.add(str(p))
            cache = _animation_file_id_cache if kind == "animation" else _photo_file_id_cache
            if p.is_file() and not cache.get(str(p)):
                jobs.append((kind, p))

    target = OWNER_ID
    warmed = 0
    for kind, path in jobs:
        for attempt in range(3):
            try:
                try:
                    if kind == "animation":
                        await application.bot.send_animation(chat_id=target, animation=path, caption=f"⚡ cached: {path.name}")
                    else:
                        await application.bot.send_photo(chat_id=target, photo=path, caption=f"⚡ cached: {path.name}")
                except Forbidden:
                    if target == SUPPORT_GROUP_ID:
                        raise
                    logger.warning("Owner DM not open (owner must /start the bot) — warming via support group instead")
                    target = SUPPORT_GROUP_ID
                    continue
                warmed += 1
                break
            except RetryAfter as e:
                await asyncio.sleep(float(getattr(e, "retry_after", 5)) + 1)
            except Exception as e:
                logger.warning(f"⚠️ Cache warmup failed for {path.name}: {e}")
                break
        await asyncio.sleep(0.4)  # stay under flood limits
    if warmed:
        logger.info(f"⚡ Cache warmup complete — {warmed} gif/image file(s) sent to owner DM & cached.")
    else:
        logger.info("⚡ Cache warmup: nothing to do (all media already cached).")


async def ccc_weekly_dm_job(context: ContextTypes.DEFAULT_TYPE):
    """🏅 Weekly CCC Ranking DM — sends CCC rankings to all players via DM.
    Uses sendRichMessage for native expandable tables, with fallback to HTML text."""
    try:
        html_content = _build_ccc_rich_html()
        fallback = _build_ccc_fallback_text()
    except Exception as e:
        logger.error(f"CCC weekly DM build error: {e}")
        return

    sent = 0
    failed = 0
    for uid in list(user_data.keys()):
        try:
            uid_int = int(uid)
        except (ValueError, TypeError):
            continue
        try:
            ok = await _tg_send_rich_message(uid_int, html_content)
            if not ok:
                await context.bot.send_message(
                    chat_id=uid_int,
                    text=fallback,
                    parse_mode=ParseMode.HTML
                )
            sent += 1
        except (Forbidden, TelegramError):
            failed += 1
        except Exception:
            failed += 1
        await asyncio.sleep(0.5)  # Rate limiting

    logger.info(f"🏅 CCC Weekly DM: sent={sent}, failed={failed}")


def main():
    """Start the bot"""

    # 🔧 FIX: fantasy points (and other stats) were saved via a 10-second
    # DEBOUNCED background write — fine for a clean Ctrl+C shutdown (already
    # flushed below), but a platform redeploy/restart normally kills the
    # process with SIGTERM, which nothing here was catching. Any points
    # change in the last ~10s before that kill was silently lost, so
    # balances could appear to drop by a small amount "on their own" after
    # a restart. Now SIGTERM/SIGINT force an immediate synchronous flush
    # of any pending save before the process exits.
    def _flush_on_signal(signum, frame):
        try:
            if _save_data_dirty:
                logger.info(f"📥 Signal {signum} received — flushing pending data before exit.")
                _save_data_sync()
        except Exception as e:
            logger.error(f"Error flushing data on signal {signum}: {e}")
        finally:
            os._exit(0)

    try:
        signal.signal(signal.SIGTERM, _flush_on_signal)
        signal.signal(signal.SIGINT, _flush_on_signal)
    except Exception as e:
        logger.warning(f"Could not register shutdown signal handlers: {e}")

    # 🔧 GLITCH FIX: single-instance lock. If another cric.py process is
    # already running (e.g. systemd restarted us but the old process hadn't
    # fully died yet, or someone launched a second copy manually in
    # screen/tmux), refuse to start. Two live processes on the same bot token
    # each keep their own separate `active_matches` memory — Telegram's
    # polling flip-flops between them, which is exactly what causes
    # "2 games running in parallel" and "/endsolo only ends one of them".
    import fcntl
    _lock_file_path = "/tmp/cricoverse_bot.lock"
    _lock_file = open(_lock_file_path, "w")
    try:
        fcntl.flock(_lock_file, fcntl.LOCK_EX | fcntl.LOCK_NB)
        _lock_file.write(str(os.getpid()))
        _lock_file.flush()
    except (IOError, OSError):
        logger.error(
            f"❌ Another instance of this bot is already running (lock held on {_lock_file_path}). "
            "Exiting to avoid duplicate-process match glitches. "
            "Run `ps aux | grep cric.py` to find and kill the stale process."
        )
        raise SystemExit(1)

    # Load data on startup
    load_data()
    sync_legacy_player_stats_to_ccc()  # 🔧 FIX: fold old JSON-only stats into CCC ranking
    ensure_fonts()

    # 🌊 Flood-control protection: auto-retry-with-backoff on Telegram rate limits.
    # Falls back to no rate limiter if the optional extra isn't installed
    # (pip install "python-telegram-bot[rate-limiter]").
    _rate_limiter = None
    try:
        from telegram.ext import AIORateLimiter
        _rate_limiter = AIORateLimiter(max_retries=3)
    except ImportError:
        logger.warning("AIORateLimiter unavailable — install python-telegram-bot[rate-limiter] for automatic flood-control retries.")

    # Create application
    _builder = (
        Application.builder()
        .token(BOT_TOKEN)
        .post_init(setup_public_bot_commands)
        .read_timeout(60)
        .write_timeout(60)
        .connect_timeout(60)
        .pool_timeout(60)
        .concurrent_updates(256)
    )
    # ⚡ SPEED FIX: PTB's underlying HTTPX connection pool defaults to a
    # tiny size (as low as 1). With concurrent_updates(256) but only 1-2
    # real HTTP connections to Telegram, every outgoing send_message /
    # send_animation call queues up behind each other — this is exactly
    # what makes bowling/batting replies feel "late" once a few groups are
    # active at once, since every ball fires several API calls (bowl DM,
    # ball result message/animation, mini-scorecard, etc). Raising the pool
    # size lets those calls actually run in parallel instead of queueing.
    try:
        _builder = _builder.connection_pool_size(256)
    except AttributeError:
        logger.warning("connection_pool_size() unavailable on this python-telegram-bot version — update PTB for faster concurrent sends.")
    if _rate_limiter:
        _builder = _builder.rate_limiter(_rate_limiter)
    application = _builder.build()
    global _global_bot
    _global_bot = application.bot

    # --- JOBS (Scheduled Tasks) ---
    if application.job_queue:
        # Cleanup inactive matches every 60 seconds
        application.job_queue.run_repeating(
            cleanup_inactive_matches, interval=60, first=60
        )

        # Auto Backup every 1 hour
        application.job_queue.run_repeating(
            auto_backup_job, interval=3600, first=10
        )
        
        # Approval expiry checker - runs every 24 hours
        application.job_queue.run_repeating(
            approval_expiry_checker_job, interval=86400, first=60
        )

        # Clone expiry checker - runs every 24 hours
        application.job_queue.run_repeating(
            clone_expiry_checker_job, interval=86400, first=120
        )
        # 🩹 Clone watchdog — relaunches crashed/rebooted clones (parent only)
        application.job_queue.run_repeating(
            clone_watchdog_job, interval=300, first=45
        )
        # 🤖 Clone self-expiry (1 day / 1 hour warnings + auto shutdown) —
        # a no-op on the parent bot, only active inside generated clones.
        application.job_queue.run_repeating(
            clone_self_expiry_job, interval=300, first=30
        )
        application.job_queue.run_repeating(
            resumable_cleanup_job, interval=1800, first=60
        )
        # 🧹 Folder-level sweep: deletes ANY file in resumable_matches/ older
        # than 1 day, whether or not it's tracked in the index (catches
        # owner /regame backup dumps and any other orphaned .pkl files).
        application.job_queue.run_repeating(
            resumable_folder_sweep_job, interval=3600, first=90
        )
        # 🎪 Auction resume-code cleanup — every 30 min, mirrors resumable_cleanup_job
        application.job_queue.run_repeating(
            auction_resumable_cleanup_job, interval=1800, first=75
        )

        # ⚔️ Challenge-mode 5-min inactivity auto-timeout — checked every 60s
        application.job_queue.run_repeating(
            challenge_inactivity_job, interval=60, first=60
        )

        # 🏏 Bring-back DM for players inactive 5-7 days — runs every 6 hours
        application.job_queue.run_repeating(
            bring_back_inactivity_job, interval=21600, first=200
        )

        # Registration expiry + daily reminder checker - runs every hour
        application.job_queue.run_repeating(
            registration_expiry_checker_job, interval=3600, first=300
        )

        # 🎽 Jersey inactivity checker (warn @60 days, release @90 days) - runs every 24 hours
        application.job_queue.run_repeating(
            jersey_inactivity_job, interval=86400, first=180
        )

        # 🎽 /rmjersey activity-check releaser - runs every hour, releases after 2 unanswered days
        application.job_queue.run_repeating(
            jersey_owner_check_job, interval=3600, first=240
        )

        # 🏅 Weekly CCC Ranking DM (every 7 days at 4 AM IST = 22:30 UTC prev day)
        # Calculate first run to align with 4:00 AM IST
        _now_utc = datetime.utcnow()
        _target_ist_hour = 4  # 4 AM IST = 22:30 UTC previous day
        _ist_offset = timedelta(hours=5, minutes=30)
        _now_ist = _now_utc + _ist_offset
        _next_4am_ist = _now_ist.replace(hour=_target_ist_hour, minute=0, second=0, microsecond=0)
        if _next_4am_ist <= _now_ist:
            _next_4am_ist += timedelta(days=1)
        _first_run_secs = (_next_4am_ist - _now_ist).total_seconds()
        application.job_queue.run_repeating(
            ccc_weekly_dm_job, interval=604800, first=_first_run_secs
        )

        # 🌙 Daily Midnight Backup — every day at 12:00 AM IST = 18:30 UTC (prev day)
        _now_utc_mb = datetime.utcnow()
        _ist_offset_mb = timedelta(hours=5, minutes=30)
        _now_ist_mb = _now_utc_mb + _ist_offset_mb
        _next_midnight_ist = (_now_ist_mb + timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
        _first_run_secs_mb = (_next_midnight_ist - _now_ist_mb).total_seconds()
        application.job_queue.run_repeating(
            midnight_backup_job, interval=86400, first=_first_run_secs_mb
        )

        # 🆕 Re-arm tournament match reminders that survived a restart —
        # job_queue jobs don't persist across process restarts, but the
        # scheduled_time_ist we saved on each fixture does, so rebuild them.
        for _g_id, _fixtures in tournament_fixtures.items():
            for _fix in _fixtures:
                if _fix.get("result") is not None:
                    continue
                # 🩹 BUGFIX: previously skipped re-arming BOTH jobs the moment
                # reminder_sent was true, so a restart between the reminder
                # firing and kickoff time meant the kickoff ping never got
                # rescheduled and silently never fired. Now each job is
                # (re)armed independently based on its own sent flag.
                _need_reminder = not _fix.get("reminder_sent")
                _need_kickoff = not _fix.get("kickoff_ping_sent")
                if not _need_reminder and not _need_kickoff:
                    continue
                _iso = _fix.get("scheduled_time_ist")
                if not _iso:
                    continue
                try:
                    _sched_dt = datetime.fromisoformat(_iso)
                except Exception:
                    continue
                _arm_tour_reminder_job(application.job_queue, _g_id, _fix["match_id"], _sched_dt,
                                        arm_reminder=_need_reminder, arm_kickoff=_need_kickoff)

    # ================== BASIC COMMANDS ==================
    # 🆕 Global activity pulse — group=-1 so it runs alongside (never blocks)
    # every other handler, for ANY message or button tap in a chat that has
    # an active match, in ANY phase. Powers the universal 10-min auto-end.
    application.add_handler(MessageHandler(filters.ALL, touch_activity_on_any_update), group=-25)
    application.add_handler(CallbackQueryHandler(touch_activity_on_any_update), group=-24)

    application.add_handler(CommandHandler("start", start_command))
    application.add_handler(CommandHandler("help", help_command))

    # ================== MATCH COMMANDS ==================
    application.add_handler(CommandHandler("upgrade", upgrade_command))
    application.add_handler(CommandHandler("game", game_command))
    application.add_handler(CommandHandler("adminlock", adminlock_command))
    application.add_handler(CommandHandler("adminunlock", adminunlock_command))
    application.add_handler(CommandHandler("extend", extend_command))
    application.add_handler(CommandHandler("endmatch", endmatch_command))
    application.add_handler(CommandHandler("setsupport", setsupport_command))
    application.add_handler(CommandHandler("regame", regame_command))
    application.add_handler(CommandHandler("reauction", reauction_command))
    application.add_handler(CommandHandler("refresh", refresh_command))
    application.add_handler(CommandHandler("timeout", timeout_command))

    application.add_handler(CommandHandler("add", add_command))
    application.add_handler(CommandHandler("join", join_command))
    application.add_handler(CallbackQueryHandler(mid_game_join_callback, pattern="^midjoin_"))
    application.add_handler(CommandHandler("remove", remove_command))
    application.add_handler(CommandHandler("over", over_command))
    application.add_handler(CommandHandler("changeover", changeover_command))
    application.add_handler(CommandHandler("bet", bet_command))
    application.add_handler(CommandHandler("transfer", transfer_command))
    application.add_handler(CommandHandler("transferplayer", transferplayer_command))
